-- Sources: data/i18n/svSE. Lore text adapted from warcraft.wiki.gg (CC BY-SA 4.0); the core add-on's src fields name the articles.
local P = LoreForeverPacks.Begin("LoreForever_Lang_svSE")
P.entries["quest:94414"] = {n="The Anchors of Zephras",s="The Anchors of Zephras är ett introduktionsuppdrag som Halaan Hawk-Eye erbjuder på Zephras Isle. Halaan låter resenärer låna hans skarpa syn på långt håll för att betrakta de uråldriga ankarpylonerna som håller den flytande ön på plats och bevarar den. De väldiga monoliterna tycks orörda på avstånd, men Halaan varnar för att vindandarnas stabiliserande magi har börjat vackla.",h="The Anchors of Zephras är ett introduktionsuppdrag som Halaan Hawk-Eye erbjuder på Zephras Isle.",kw={"ankarpylon","the anchors of zephras","halaan hawk-eye","ley-linjer","skynsyn","vindandar","zephras"},ang={["class:Mage"]="Halaan skiljer sin skarpa syn från magin hos dem som kan hämta kraft ur ley-linjerna under Zephras.",["class:Shaman"]="Ankarpylonerna är direkt beroende av vindandarnas välsignelse. Därför är all instabilitet i deras magi en akut elementär angelägenhet för schamaner som försöker bevara balansen."},sec={{t="Öns förankringar",b="Zephras ankarpyloner är uråldriga, väldiga monoliter som vindarnas andar skänkte ön. De är djupt invävda i öns mystiska grundvalar och binder, stabiliserar och bevarar landmassan bland de virvlande skyarna. Att se en av dem är att bevittna den sköra balans som håller Zephras svävande, helt beroende av vindandarnas välvilja."},{t="En oroande förändring",b="Ankarpylonerna står stolt och ser oskadda ut för blotta ögat, men de har börjat bete sig oberäkneligt. Halaan Hawk-Eye säger att den magiska harmoni som håller dem vid kraft har blivit instabil och ojämn på senare tid. Eftersom det saknas tydliga tecken på fysisk skada väcker detta subtila förfall stilla oro bland dem som vakar över lundarna, och antyder djupare obalanser som hotar ön."},{t="Halaans gåva",b="Halaan saknar både den medfödda skynsyn som låter vissa se mellan världar och den magiska förmågan att utnyttja Zephras djupa ley-linjer. I stället har han en enklare, skarpare naturlig gåva: synskärpa som når långt och klart. Genom att låna ut sitt perspektiv låter han andra se de avlägsna pylonerna i detalj och uppmuntrar nykomlingar att uppskatta det de har, samtidigt som de håller sig vaksamma på hemlandets föränderliga öde."}},faq={{q="Vad är ankarpylonerna på Zephras?",a="Ankarpylonerna är uråldriga, mystiska konstruktioner som vindarnas andar skänkte ön. De binder och förankrar Zephras och håller ön magiskt svävande och stabil ovanför världen omkring den.",al={"vad är förankringarna","zephras ankarpylon","vad är en ankarpylon"}},{q="Vad är det för fel på ankarpylonerna?",a="Pylonerna visar inga tydliga tecken på fysisk skada eller yttre förfall, men deras stabiliserande magi har på senare tid blivit instabil och ojämn. Det väcker oro för vad som i det tysta stör deras förbindelse.",al={"varför sviktar förankringarna","problem med ankarpylon","vad hände med förankringarna"}},{q="Vem är Halaan Hawk-Eye?",a="Halaan Hawk-Eye är en väktare som bor i Zephras Isles lundar. Han har välsignats med skarp syn som når långt och vakar över landets välmående, samtidigt som han begrundar öns mystiska hälsa.",al={"halaans bakgrund","vem är halaan"}},{q="Vad är Halaans gåva?",a="Halaans gåva är en utomordentligt skarp syn på långt håll. Till skillnad från mystiker som använder skynsyn för att se mellan världar eller kanalisera ley-linjernas krafter är Halaans förmåga naturlig och vardaglig. Den låter honom urskilja avlägsna landmärken med kristallklar skärpa.",al={"halaans gåva","hur ser halaan så långt"}},{q="Vad är skynsyn?",a="Skynsyn är en mystisk varseblivning som vissa utövare på Zephras besitter. Den låter dem tränga igenom slöjan och se direkt mellan världar, långt bortom vad vanlig fysisk syn förmår.",al={"vad är skynsyn","skynsyn betydelse"}},{q="Varifrån kommer magin som driver pylonerna?",a="Vindarnas andar skänkte Zephras ankarpylonerna. Halaan säger att pylonerna binder och bevarar ön, men förklarar inte varifrån deras fortsatta kraft kommer.",al={"vem skapade pylonerna","ankarpylonernas ursprung"}}},fx={["61bc2f74"]={q="Varför vill Halaan Hawk-Eye att du ska titta på ankarpylonen?",a="Halaan Hawk-Eye vakar över lunden och bryr sig djupt om Zephras välmående. De uråldriga ankarpylonerna, gåvor från vindarnas andar, binder samman och håller ön vid liv, men deras magi har på sistone blivit instabil och ojämn. Även om de ser oskadade ut erbjuder Halaan dig att dela sin skarpa syn, så att du kan se pylonerna på nära håll och förstå hur skört ditt hemland är.",al={"halaans motiv","varför titta på ankarpylonen","varför vill halaan detta"}}},fp="22,370,19.361.0,18.378.0,13.412.0,38.198.0,37.200.0,23.200.0,22.249.0,17.190.0,51.181.0"}
P.entries["quest:94449"] = {n="Call of Fire",s="Call of Fire är ett shamanistiskt uppdrag som leder noviser in i lågornas farliga och kaotiska rike högt uppe i Dun Morogh. Efter att ha bemästrat jordens tålmodiga lärdomar skickas utövaren till Bruegs Kindleborn för att pröva om hen är redo för Fire Sapta.",h="Call of Fire är ett shamanistiskt uppdrag som leder noviser in i lågornas farliga och kaotiska rike högt uppe...",kw={"bruegs kindleborn","call of fire","dun morogh","jordens sapta","fire totem","eldens sapta","schaman","south gate outpost"},ang={["class:Shaman"]="Det här uppdraget är en avgörande andlig prövning för schamanen, en övergång från stenens uthållighet till eldens våldsamma, destruktiva kraft.",["faction:Alliance"]="I Dun Moroghs berg följer alliansschamaner sina äldstes vägledning för att väcka kontakt med eldelementen.",["race:Dwarf"]="Denna rit äger rum högt ovanför South Gate Outpost i Dun Morogh och prövar om en dvärg har disciplin nog att tygla lågans brinnande hunger."},sec={{t="Det brinnande provet",b="Efter att ha visat tålamod och stadga genom jordens element får schamaner möta en betydligt mer oberäknelig kraft: eldens elementande. Till skillnad från den stadiga, obevekliga stenen lockar elden med löften om kaos, förstörelse och våldsam energi. En äldste skickar novisen över Dun Moroghs snötäckta toppar för att söka vägledning innan hen försöker tygla denna vilda hetta."},{t="Bergens eremit",b="Högt uppe i bergen ovanför South Gate Outpost håller mentorn Bruegs Kindleborn uppsikt från en avskild grotta. När en novis anländer med en äldstes rekommendation förbereder Bruegs hen för eldens sapta. Men han utfärdar en sträng varning: lusten att bränna och förtära väcks lätt, men att bemästra lågan kräver att man vet precis när man ska hålla igen."}},faq={{q="Vem är Bruegs Kindleborn?",a="Bruegs Kindleborn är en mentor som bor i en bergsgrotta högt ovanför South Gate Outpost i Dun Morogh. Han bedömer schamaner som äldste skickat dit för att avgöra om de har den mognad och disciplin som krävs för att få eldens sapta.",al={"vem är bruegs kindleborn","bruegs kindleborns historia","var finns bruegs"}},{q="Vad är eldens sapta?",a="En sapta är en elementär brygd eller beredning som låter en schaman kommunicera med elementandar. Eldens sapta ger kontakt med lågan och dess råa kraft, men kräver mental koncentration och en grund av sten.",al={"vad är eldens sapta","fire sapta","sapta betydelse"}},{q="Var finns Bruegs Kindleborn?",a="Bruegs Kindleborn finns långt österut i Dun Moroghs snöiga berg, i skydd i en grotta med utsikt över South Gate Outpost.",al={"var hittar man bruegs kindleborn","grottan vid south gate outpost","var lämnar man in call of fire"}},{q="Vad är syftet med Call of Fire?",a="Call of Fire är en övergångsrit för schamaner som har visat tålamod och bemästrat jorden. Den låter dem möta förstörelsens kaotiska kraft under Bruegs Kindleborns vakande öga.",al={"vad är call of fire","eldtotemets uppdrag i dun morogh"}},{q="Varför måste en schaman lära sig stenens lärdomar före elden?",a="Jorden står för orubbligt tålamod, stabilitet och kontroll. Utan den grund av stadga som stenen lär ut riskerar en schaman att överväldigas av eldens oberäkneliga hunger och destruktiva lidelser.",al={"varför stenen först","minns vad stenen lärde dig"}},{q="Vilka förkunskaper krävs innan man påbörjar Call of Fire?",a="Uppdraget bygger vidare på tidigare prövningar där novisen visat tålamod och funnit stadga i jorden. Den äldste skickar en elev till Bruegs Kindleborn först när elevens disciplin har visat sig vara stadig.",al={"förkunskaper för call of fire","koppling till tålamodsuppdraget"}}},fp="12,263,17.390.0,24.360.0,25.221.0,26.226.0,35.129.0,40.200.0,57.200.0,68.201.0"}
P.entries["quest:94465"] = {n="Call of Fire",s="Call of Fire är en helig prövning för noviser som vill visa att de är andligt redo att hantera elementär eld. De måste bära Torch of the Dormant Flame längs en avskild bergsstig i Loch Modan och söka upp Braldir Ashmantle vid Shrine of the Dormant Flame.",h="Call of Fire är en helig prövning för noviser som vill visa att de är andligt redo att hantera elementär eld.",kw={"braldir ashmantle","call of fire","fire totem","loch modan","shaman","shrine of the dormant flame","torch of the dormant flame","valley of kings"},ang={["class:Shaman"]="Prövningen sätter en blivande shaman på prov i sin hängivenhet att komma i kontakt med eldens elementandar. Hen måste bära en helig fackla till en avskild topp i Loch Modan.",["faction:Alliance"]="Medan vanliga resenärer i Alliansens områden bara ser karg bergssten, vaktar helgedomens väktare uråldriga elementhemligheter som är dolda för andras blickar.",["race:Dwarf"]="Uppdragets dialog speglar dvärgarnas sätt att tala och leder noviserna bortom Valley of Kings, upp bland de oländiga klipporna i Khaz Modan."},sec={{t="Stigen bortom Valley of Kings",b="Att förtjäna Fire Totem kräver mer än rå fysisk styrka. Noviserna får i uppgift att bära den släckta Torch of the Dormant Flame högt upp bland klipporna i Loch Modan. Bortom stenhällarna i Valley of Kings leder en mödosam stigning till en avskild bergstopp, där elementen råder långt ovanför de dödligas vägar."},{t="Shrine of the Dormant Flame",b="Högt uppe på den vindpinade toppen står Braldir Ashmantle, väktaren som har fått i uppdrag att vaka över Shrine of the Dormant Flame. Oförberedda vandrare och skattjägare som tar sig upp hit möts bara av tystnad och kal sten. För äkta noviser med den heliga facklan uppenbarar Braldir en djupare elementär kraft som slumrar i helgedomens eldfat och väntar på att åter tändas."}},faq={{q="Vad är uppdraget Call of Fire?",a="Call of Fire är en övergångsrit för en novis som vill förtjäna sitt eldtem. Uppdraget leder novisen upp bland klipporna i Loch Modan för att överlämna Torch of the Dormant Flame till Braldir Ashmantle på en helig bergstopp.",al={"vad är call of fire","shamanens eldprov i loch modan","uppdraget för fire totem"}},{q="Vem är Braldir Ashmantle?",a="Braldir Ashmantle är väktaren som vakar över Shrine of the Dormant Flame högt uppe bland klipporna i Loch Modan. Han avvisar vanliga resenärer och skattletare och välkomnar endast dem som bär Torch of the Dormant Flame.",al={"vem är braldir ashmantle","helgedomens väktare i loch modan"}},{q="Var ligger Shrine of the Dormant Flame?",a="Shrine of the Dormant Flame ligger högt uppe bland klipporna i Loch Modan. Dit kommer du genom att följa en dold stig som slingrar sig bortom Valley of Kings.",al={"var ligger shrine of the dormant flame","platsen för dormant flame"}},{q="Vad är syftet med Torch of the Dormant Flame?",a="Torch of the Dormant Flame är en rituell symbol som noviser bär för att visa sin uppriktiga avsikt och beredskap att komma i kontakt med elementär eld. Braldir Ashmantle måste få se facklan innan han tar emot dem.",al={"vad är torch of the dormant flame","syftet med torch of the dormant flame"}},{q="Varför måste novisen resa till Loch Modan?",a="Den heliga elementtoppen med Shrine of the Dormant Flame blickar ut över Loch Modan, bortom Valley of Kings. Platsen valdes för att ligga avskilt från vanliga resenärer.",al={"varför resa till loch modan","varför ligger eldhelgedomen i loch modan"}},{q="Hur förtjänar man eldtemet genom prövningen?",a="När novisen har nått Braldir Ashmantle och visat sin avsikt med facklan, måste hen tända lågan i helgedomens eldfat och återvända med den brinnande för att förtjäna eldtemet.",al={"vad händer när man hittar braldir","hur får man fire totem"}}},fp="12,284,35.354.0,31.378.0,31.235.0,25.224.0,49.149.0,54.221.0,45.167.0,48.189.0"}
P.entries["quest:94466"] = {n="Call of Fire",s="Call of Fire är en elementär prövning i Loch Modan där noviser förbereder sig för att tala med Eternal Flame och vinna sin egen Fire Totem. Under Braldir Ashmantles ledning samlar kandidater elementära ingredienser från lokala kobolder och troggs för att brygga en bindande Fire Sapta. Resan lär dem att eld inte bara är ett redskap för förödelse, utan själva livets smedja och andetag.",h="Call of Fire är en elementär prövning i Loch Modan där noviser förbereder sig för att tala med Eternal Flame...",kw={"braldir ashmantle","call of fire","eternal flame","fire sapta","fire tar","fire totem","loch modan","stonesplinter seer","tunnel rat geomancer"},ang={["class:Shaman"]="För att tala med elden måste man skapa ett elementärt band med hjälp av en särskilt tillredd sapta. Det leder mot gemenskap med Eternal Flame och möjligheten att få en Fire Totem.",["faction:Alliance"]="Denna prövning utspelar sig i dvärgarnas område Loch Modan och förankrar shamanernas riter stadigt i Alliansens marker, där lokala troggs och kobolder utgör hotet.",["race:Dwarf"]="Braldir Ashmantle vägleder noviser i Loch Modan och ger ett jordnära, dvärgiskt perspektiv på elementäreld. Han ser den som smedjans och skapelsens andetag, inte bara som förstörelse."},sec={{t="Vägen till lågan",b="Bland Loch Modans karga klippor vakar en elementär mentor vid namn Braldir Ashmantle över vägen för noviser som söker lågans kraft. Att tala med eldandarna är ingen enkel besvärjelse; först måste en dödlig själ stämmas till det brinnande elementet genom en helig brygd som kallas Fire Sapta. Utan denna förberedelse skulle Eternal Flames hetta förtära i stället för att upplysa. Braldir kräver att de sökande visar sin beslutsamhet genom att samla två avgörande eldbundna ingredienser från dalens fientliga invånare."},{t="Ingredienser från jord och gnista",b="För att tillreda Fire Sapta krävs ämnen med stark elementär resonans. I norr utvinner Tunnel Rat Geomancers klibbig Fire Tar i sina labyrintiska hålor och använder den som bränsle för sin underjordiska magi. I söder bär Stonesplinter Seers, troggmystiker, Reagent Pouches fyllda med primitiva elementära amuletter genom de karga kullarna. Att ta föremålen kräver kamp mot två av Loch Modans mest svårutrotade plågor, och materialen behövs för att binda en novis själ till elden."},{t="Visdomens härdning",b="När ingredienserna har lämnats över delar Braldir Ashmantle med sig av visdom som tyglar rå förstörelse med tålamod. För den erfarna mentorn är eld mycket mer än vrede och aska – den står för liv, smedjans hantverk och själva skapelsens andetag. Sann behärskning av elementen ligger i balans: liksom skuggan ger ljuset mening hindrar lågan stenen från att förbli ett blott kallt minne. Att bemästra lågan kräver att man vet när man ska förena i stället för att bara bränna."}},faq={{q="Vad är syftet med Call of Fire?",a="Call of Fire är en övergångsrit för blivande shamaner som söker gemenskap med Eternal Flame. För att tala med eldandarna och göra anspråk på en Fire Totem måste man först tillreda Fire Sapta, som binder ens dödliga själ till elementet.",al={"vad är call of fire","vad är det här för uppdrag","syftet med call of fire"}},{q="Vem är Braldir Ashmantle?",a="Braldir Ashmantle är en elementär vägvisare som bor i Loch Modan. Han lär noviser om eldens balans och tillreder den nödvändiga Fire Sapta när de rätta elementära ingredienserna har samlats in.",al={"vem ger call of fire","vem är braldir ashmantle","braldir ashmantles plats"}},{q="Vad är Fire Sapta?",a="Fire Sapta är en elementär dryck eller beredning som tillverkas av eldbundna ingredienser. Genom att dricka eller använda den stäms shamanens själ till och binds vid eldens elementplan, vilket möjliggör syner och gemenskap med Eternal Flame.",al={"vad är fire sapta","vad gör en sapta","varför behövs sapta"}},{q="Var hittar man Fire Tar?",a="Tunnel Rat Geomancers som håller till i koboldgrottorna i norra Loch Modan bär på Fire Tar. Geomanterna använder tjäran i sina primitiva eldkonster.",al={"var får jag fire tar","fire tars plats","fire tar i koboldgrottor"}},{q="Var hittar man Stonesplinter Reagent Pouch?",a="Reagent Pouch måste tas från Stonesplinter Seers som håller till i Loch Modans södra kullar. Dessa troggmystiker använder påsarna för att förvara ingredienser knutna till elementär magi.",al={"var får jag reagent pouch","stonesplinter seers påse","stonesplinter pouchs plats"}},{q="Hur ser Braldir Ashmantle på eldens element?",a="I stället för att behandla eld som meningslös förstörelse lär Braldir att eld är smedja, liv och skapelsens andetag. Den står i balans med andra krafter, härdar kall sten och ger tillvaron värme och mening.",al={"braldirs syn på eld","eldens betydelse i loch modan","dvärgarnas eldfilosofi"}}},fp="12,372,21.545.0,31.497.0,23.459.0,36.228.0,25.196.0,21.230.0,28.176.0,47.179.0,52.225.0"}
P.entries["quest:94467"] = {n="Call of Fire",s="Call of Fire är ett elementärt prov där en novis dricker en tillredd sapta för att uppfatta och möta en mindre manifestation av eld. Genom att kuva anden och lägga dess glöd i den heliga eldfatet vinner den sökande lågans gunst.",h="Call of Fire är ett elementärt prov där en novis dricker en tillredd sapta för att uppfatta och möta en...",kw={"eldfat","call of fire","fire sapta","glowing ember","mindre manifestation av eld","schamanprov","shrine of eternal flame"},ang={["class:Shaman"]="Ett grundläggande prov för schamaner som söker gemenskap med elden. Det kräver en helig sapta för att uppfatta och möta lågornas andar."},sec={{t="Eldens rit",b="Call of Fire är ett traditionellt prov på ande och mod. Vägledd av elementär kunskap får en novis en tillredd Fire Sapta som väcker sinnena för den osynliga världen. När novisen dricker brygden vid helgedomen och går upp mot toppen blir gränsen mellan dödliga ögon och urkrafter allt tunnare, och en slumrande eldmanifestation visar sig, redo att utmanas."},{t="Möte med manifestationen",b="Mötet med den mindre manifestationen av eld prövar både beslutsamhet och uthållighet. Elementarande angriper inte utan anledning, men när den utmanas växer dess styrka för varje ögonblick. När den besegras lämnar den efter sig glödande kol, som måste föras till eldfatet högst upp vid Shrine of Eternal Flame för att tända facklan och vinna andens varaktiga gunst."}},faq={{q="Vad är Call of Fire?",a="Call of Fire är en helig övergångsrit där en novis dricker en särskilt tillredd Fire Sapta för att uppfatta en eldande, möter den i strid och offrar dess glödande kol i ett eldfat för att vinna eldens gunst.",al={"vad är call of fire","call of fire-uppdraget","eldtotemets prov"}},{q="Vad är syftet med Fire Sapta?",a="Fire Sapta är en tillredd brygd som öppnar novisens andliga syn och låter hen se elementaranden som väntar på bergstoppen.",al={"fire sapta syfte","varför dricka sapta","vad gör sapta"}},{q="Vilken ande visar sig under provet?",a="Provet kräver att novisen möter en mindre manifestation av eld på toppen, som väntar med att strida tills den blir träffad.",al={"vilken ande ska jag strida mot","call of fire-varelse","eldmanifestation"}},{q="Varför måste eldanden besegras snabbt?",a="Elementaranden blir allt vildare och hetare ju längre striden pågår. Därför är ett snabbt och avgörande slag avgörande för att kuva den innan lågorna blir övermäktiga.",al={"varför ska man slå snabbt","call of fire-striden","eldandens tidsgräns"}},{q="Vad gör man med de glödande kolen?",a="När den mindre manifestationen av eld har besegrats bärs dess glödande kol till eldfatet högst upp vid Shrine of Eternal Flame för att tända ritualfacklan.",al={"vart förs kolen","call of fire-eldfat","eldfatet vid shrine of eternal flame"}},{q="Vad innebär det att vinna eldens gunst?",a="När ritualen fullbordas och facklan tänds vinner man eldelementarernas direkta gunst och gemenskap och knyter ett viktigt band till lågorna.",al={"vad är belöningen","vad ger ritualen","eldens gunst"}}},fp="12,252,17.364.0,24.367.0,25.221.0,38.163.0,37.142.0,45.170.0,37.155.0,40.148.0"}
P.entries["quest:94468"] = {n="Call of Fire",s="Call of Fire är en helig övergångsrit där en novis hämtar Torch of Eternal Flame från en utsiktsplats ovanför Loch Modan och bär den till Dun Morogh. När resenären återlämnar lågan till mentorn Bruegs Kindleborn visar det att hen behärskar elementen och förtjänar sin Fire Totem.",h="Call of Fire är en helig övergångsrit där en novis hämtar Torch of Eternal Flame från en utsiktsplats ovanför...",kw={"bruegs kindleborn","call of fire","dun morogh","fire totem","lågfödd","loch modan","schaman","torch of eternal flame"},ang={["class:Shaman"]="Den här riten fullbordar eldens prov för blivande schamaner i Khaz Modan och ger dem den Fire Totem som krävs för att kanalisera lågor och stå i förbindelse med eldandarna.",["faction:Alliance"]="När andliga kallelser slår rot i Alliansens områden i Khaz Modan vägleder mästare som Bruegs Kindleborn nya noviser i elementens konster.",["race:Dwarf"]="Att bära lågan från höjderna ovanför Loch Modan ned till Dun Morogh speglar de starka banden mellan dvärgarnas andliga sökare och krafterna i deras bergshem."},sec={{t="Lågan över sjön",b="Call of Fire markerar ett avgörande ögonblick i novisens förbindelse med elementen. Högt uppe på en bergsrygg, där vinden viner över höjderna, tänder novisen Torch of Eternal Flame med utsikt över Loch Modan. Den dansande lågan speglar en ande som vaknar och väcker en elementär iver som måste vårdas och bäras tryggt nedför stigarna till Dun Moroghs snöiga dalar."},{t="Lågföddas belöning",b="I Dun Morogh väntar Bruegs Kindleborn, en elementmentor som avgör om resenärens inre eld verkligen har fått fäste. När novisen visar upp den brinnande facklan bevisar hen sin vilja och vördnad inför elden. Kindleborn hyllar novisen som lågfödd och skänker hen en Fire Totem, vilket upptar hen i en släktlinje av elementär vägledning för de sina."}},faq={{q="Vad är Call of Fire?",a="Call of Fire är ett andligt prov för schamaner i Khaz Modan. Efter att ha tänt Torch of Eternal Flame vid en fyrfat med utsikt över Loch Modan måste novisen bära den brinnande lågan genom bergen tillbaka till Bruegs Kindleborn i Dun Morogh.",al={"vad är call of fire","uppdraget call of fire","vad gör man i call of fire"}},{q="Vem är Bruegs Kindleborn?",a="Bruegs Kindleborn är en mentor och elementär vägvisare som bor i Dun Morogh. Han vakar över eldens elementriter och ger noviser som klarar färden sin Fire Totem.",al={"vem är bruegs kindleborn","var finns bruegs kindleborn","bruegs kindleborns plats"}},{q="Vad är Torch of Eternal Flame?",a="Torch of Eternal Flame är en helig ceremoniell fackla som tänds vid ett fyrfat med utsikt över Loch Modan. Den står för novisens inre förbindelse med elementär eld och måste bäras tryggt tillbaka till Bruegs Kindleborn i Dun Morogh.",al={"vad är torch of eternal flame","torch of eternal flame","var får man facklan"}},{q="Vad får du när du klarar provet?",a="När du tryggt har lämnat Torch of Eternal Flame till Bruegs Kindleborn erkänner mentorn din brinnande ande och ger dig din Fire Totem, som tecken på att du är lågfödd.",al={"vilken belöning ger call of fire","får man fire totem","call of fire totem"}},{q="Var äger resan rum?",a="Resan börjar vid en utsiktsplats med utsikt över Loch Modan, där facklan tänds, och följer bergsstigen tillbaka till Dun Moroghs snöiga trakter för att möta Bruegs Kindleborn.",al={"var utspelar sig call of fire","call of fire färdväg","vart ska facklan bäras"}},{q="Varför nämner Bruegs Madoran?",a="Bruegs svär ”Vid Madorans skägg” och syftar på Madoran Bronzebeard, den vördade dvärgaledare som ledde Bronzebeard-klanen under De tre hammarnas krig.",al={"varför säger han vid madorans skägg","madorans betydelse","vem är madoran som bruegs nämner"}}},fp="12,280,23.390.0,22.396.0,25.244.0,25.182.0,35.231.0,47.173.0,35.181.0,32.161.0"}
P.entries["quest:94484"] = {n="Unnerving Silence",s="Unnerving Silence handlar om att en druideenklav i en grotta i nordöstra Shadowgale Forest plötsligt har slutat höra av sig. Efter Ban'aethalls förstörelse och den ökande oron i området skickas en utredare för att hitta Elegael Thornpaw och ta reda på vad som hänt enklaven.",h="Unnerving Silence handlar om att en druideenklav i en grotta i nordöstra Shadowgale Forest plötsligt har...",kw={"ban'aethall","druid","druideenklav","elegael thornpaw","shadowgale forest","unnerving silence"},ang={["class:Druid"]="Den förlorade kontakten med en avskild enklav i Shadowgale Forest väcker omedelbar oro hos druider som är lyhörda för vildmarkens balans. Att undersöka varför Elegael Thornpaw tystnat handlar om att skydda sina fränder och ta reda på vad som har stört deras gemenskap."},sec={{t="Tystnad i trädkronorna",b="En stilla oro vilar över vildmarken efter Ban'aethalls fall. Byn ligger i ruiner och en mystisk oro sprider sig genom området, samtidigt som de etablerade kontaktvägarna börjar brytas. Särskilt har de regelbundna rapporterna från en avskild druideenklav, djupt inne i en grotta i nordöstra Shadowgale Forest, plötsligt upphört. Det gör deras allierade oroliga."},{t="På jakt efter enklaven",b="Resenärer på väg mot Shadowgale Forest får i uppdrag att leta reda på Elegael Thornpaw, en framstående person bland druiderna som bor i grottan. En utredare måste ta sig in i det skuggiga nordöstra området och ta reda på om enklaven bara har dragit sig undan för att fördjupa sin gemenskap med naturen eller fallit offer för samma faror som härjade i Ban'aethall."}},faq={{q="Vad handlar uppdraget Unnerving Silence om?",a="Unnerving Silence är ett uppdrag att undersöka varför en druideenklav i Shadowgale Forest plötsligt har slutat höra av sig. En orolig person ber resenärer som ska åt det hållet att leta i en grotta i nordost och ta reda på vad som hänt den avskilda gruppen.",al={"uppdraget unnerving silence","vad är unnerving silence"}},{q="Var finns Elegael Thornpaw?",a="Elegael Thornpaw finns i en grotta i den nordöstra delen av Shadowgale Forest. Hon är kontaktpersonen för den avskilda druideenklav som håller till där.",al={"var finns elegael thornpaw","elegael thornpaws plats","hitta thornpaw"}},{q="Vem är Elegael Thornpaw?",a="Elegael Thornpaw tillhör druideenklaven som bor i en grotta i nordöstra Shadowgale Forest. Hennes långvariga tystnad och uteblivna rapporter har väckt allvarlig oro för enklavens säkerhet.",al={"vem är elegael thornpaw","thornpaws bakgrund"}},{q="Vad är Shadowgale Forest?",a="Shadowgale Forest är ett skogsområde med en dold druideenklav i en grotta i nordost. Efter den omfattande oron i området och Ban'aethalls fall har kontakten med skogens invånare blivit oroväckande osäker.",al={"vad är shadowgale forest","shadowgale forests druideenklav"}},{q="Vad är Ban'aethall?",a="Ban'aethall var en by djupt inne i Shadowgale Forest som nyligen ödelagts. Förstörelsen och den större oron i området har ökat rädslan för att närliggande läger, som Shadowgale-enklaven, också kan vara i fara.",al={"vad hände med banaethall","banaethalls ruiner","ban'aethalls fall"}},{q="Varför har druideenklaven tystnat?",a="Druidernas schemalagda meddelanden och rapporter från Shadowgale Forest har upphört utan förklaring. Med tanke på Ban'aethalls förstörelse och de ökande spänningarna i området finns det allvarlig oro för att en katastrof eller fientliga styrkor har drabbat dem.",al={"varför slutade druiderna skicka meddelanden","varför är druiderna tysta"}}},fp="17,288,21.392.0,19.349.0,42.260.0,36.179.0,24.235.0,26.244.0,20.248.0,39.251.0"}
P.entries["quest:94485"] = {n="Tears of the Lady",s="Tears of the Lady är ett akut hjälp­uppdrag åt Elegael i Shadowgale Forest. För att behandla sårade kamrater som blivit kvar i Nightclaw Den måste resenärer söka igenom trädstammar i närheten efter Lady's Tear, en antiseptisk mossa som är livsviktig för att förbinda svåra sår.",h="Tears of the Lady är ett akut hjälp­uppdrag åt Elegael i Shadowgale Forest.",kw={"elegael","lady's tear","mossa","nightclaw den","grötomslag","shadowgale forest","tears of the lady"},ang={["class:Priest"]="Präster kanaliserar Ljuset för att läka livshotande skador, men naturliga grötomslag som Lady's Tear är viktiga fysiska förband för sårade överlevande när den magiska hjälpen inte räcker till.",["profession:Herbalism"]="Örtkunniga och fältläkare värdesätter Lady's Tear för dess klibbiga, antiseptiska sekret, som snabbt kan förbinda öppna sår och förebygga infektion i nödsituationer ute i vildmarken."},sec={{t="Desperata botemedel i Shadowgale",b="I Shadowgales skuggiga djup söker Elegael akut hjälp med att behandla följeslagare som är instängda i Nightclaw Den. Svårt skadade allierade väntar på räddning, men vanliga förnödenheter saknas. Därför måste läkemedel samlas direkt från den omgivande vildmarken. Allt hänger på att hitta naturliga botemedel innan tiden rinner ut för dem som lämnats kvar."},{t="Den läkande mossan",b="Den viktigaste ingrediensen i Elegaels planerade grötomslag är Lady's Tear, en spinkig mossa som klamrar sig fast vid trädens baser runtom i Shadowgale Forest. Växten utsöndrar ett trögflytande, klibbigt sekret med naturligt antiseptiska egenskaper. Det kan försegla öppna sår och skydda svåra skador från att förvärras i den fuktiga vildmarken. Om Elegael får tillräckligt med mossa kan hen förbereda förbanden som behövs för att stabilisera de fallna."}},faq={{q="Vad handlar uppdraget Tears of the Lady om?",a="Tears of the Lady är en räddningsinsats som leds av Elegael i Shadowgale Forest. Sårade kamrater är fortfarande instängda i Nightclaw Den, och Elegael behöver växter från trakten för att göra ett akut grötomslag och hålla dem vid liv.",al={"vad är tears of the lady","information om uppdraget tears of the lady"}},{q="Vad är Lady's Tear?",a="Lady's Tear är en spinkig mossa som växer nära trädens baser i skogarna kring Shadowgale Forest. Den utsöndrar en naturligt klibbig sav som fungerar som ett kraftfullt antiseptiskt medel och därför passar utmärkt för att lägga om och förbinda öppna sår.",al={"vad är ladys tear","ladys tear-mossa","vad är lady's tear-mossa"}},{q="Vem är Elegael?",a="Elegael är den överlevande som organiserar sjukvårdsinsatsen i Shadowgale Forest. Elegael lämnade sårade följeslagare i Nightclaw Den och samlar nu in medicinalväxter för att förbereda behandlingar innan hen återvänder för att hjälpa dem.",al={"vem är elegael","uppdragsgivare för tears of the lady"}},{q="Vad är Nightclaw Den?",a="Nightclaw Den är en plats nära Shadowgale Forest där flera av Elegaels skadade allierade har blivit kvar. Deras tillstånd är kritiskt, vilket gör det brådskande att samla in läkande ingredienser.",al={"vad är nightclaw den","var ligger nightclaw den"}},{q="Varför behöver Elegael Lady's Tear-mossa?",a="Mossan ger ett viktigt antiseptiskt sekret som behövs för att blanda till ett medicinskt grötomslag. Det klibbiga ämnet förseglar öppna sår och motverkar infektion hos de överlevande som lämnats kvar i hålan.",al={"varför behövs ladys tear","vad gör mossan"}},{q="Var hittar man Lady's Tear-mossa?",a="Lady's Tear-mossa klamrar sig vanligtvis fast vid trädens baser runtom i Shadowgale Forest. Elegael samlade in det som fanns inom räckhåll, men mer måste hämtas i skogarna runt omkring.",al={"var växer ladys tear","hitta ladys tear"}}},fp="17,263,32.369.0,16.398.0,42.203.0,20.224.0,15.219.0,26.190.0,39.194.0,32.198.0"}
P.entries["quest:94486"] = {n="Feathers for Binding",s="Feathers for Binding är ett uppdrag i Shadowgale Forest där du samlar isolerande fjädrar från unga skriklingar för att göra ett skyddande läkande omslag. Dessa vanligtvis fogliga varelser har blivit farligt aggressiva, men deras fjädrar behövs fortfarande för att skydda antiseptiska salvor mot väder och vind. Äventyrare måste trotsa de fientliga ungarna för att säkra material till traktens vård.",h="Feathers for Binding är ett uppdrag i Shadowgale Forest där du samlar isolerande fjädrar från unga...",kw={"antiseptisk saft","feathers for binding","läkande omslag","shadowgale forest","shadowgale-skrikling","skrikling","skriklingar"},ang={["class:Druid"]="Druider kan känna sorg tillsammans med uppdragsgivaren över att unga skogsdjur måste dödas, även när den ökande aggressiviteten och det akuta medicinska behovet lämnar få andra alternativ.",["profession:Herbalism"]="Örtkunniga och naturhelare kan uppskatta den noggranna avvägningen mellan mossa, antiseptisk trädsaft och isolerande fjädrar när man skapar ett effektivt fältförband eller läkande omslag."},sec={{t="Skogens läkande medel",b="I Shadowgale Forests djup kräver förberedelser av fältmedicin ofta uppfinningsrikedom och kunskap om naturens resurser. Vid behandling av svåra skador använder örtkunniga och läkare ett särskilt omslag av mossa och antiseptisk trädsaft. För att hindra saften från att torka snabbt eller förlora sin verkan i hårt väder behövs slitstarka, isolerande bindor. De unga Shadowgale-skriklingarnas fjädrar utgör ett utmärkt naturligt skydd. De täcker såret och håller läkemedlet på plats."},{t="Oväntad fientlighet",b="Det har oväntat blivit farligt att skaffa de duniga fjädrarna. Vanligtvis är unga Shadowgale-skriklingar fogliga skogsvarelser. På sistone har de dock blivit oförklarligt mycket mer aggressiva. De här unga rovdjuren anfaller nu förbipasserande med kraftiga klor som kan orsaka dödliga skador. För att samla fjädrarna måste äventyrare möta varelser som förvandlats från harmlösa ungar till verkliga faror."},{t="En beklaglig nödvändighet",b="De lokala vårdarna känner stor tyngd när de ber resenärer att jaga unga varelser, och sörjer öppet att det blivit nödvändigt att gallra bland dem. Men eftersom flera nödlägen hotar trakten och bestarna blir allt farligare, fyller jakten ett dubbelt syfte: att samla viktiga läkemedelsmaterial och hejda ett växande hot mot skogsstigarna. Varje insamlad fjäder behandlas med respekt, så att deras offer inte blir förgäves."}},faq={{q="Varför behövs Shadowgale-skriklingarnas fjädrar till omslaget?",a="Fjädrarna från unga Shadowgale-skriklingar har naturligt isolerande egenskaper. När de läggs ovanpå ett lager mossa fungerar de som ett skyddande bandage. Det hindrar antiseptisk saft från att torka och skyddar såret mot hårt väder.",al={"fjädrarnas syfte","varför skriklingsfjädrar","fjädrar till omslag"}},{q="Hur farliga är de unga skriklingarna?",a="Shadowgale-skriklingar är vanligtvis fogliga, men på sistone har de blivit ovanligt fientliga. Trots sin unga ålder har de stora, vassa klor som kan slita upp magen på en oförsiktig resenär.",al={"skriklingars farlighet","är skriklingar farliga","skriklingars aggressivitet"}},{q="Varför måste unga skriklingar jagas i stället för vuxna?",a="Uppdragsgivaren uttrycker uppriktig sorg över att unga bestar måste gallras ut. Men eftersom de plötsligt blivit mycket mer fientliga och flera akuta problem i vildmarken måste hanteras, anses det vara en smärtsam nödvändighet att minska deras antal och samla in behövda läkemedel.",al={"varför döda unga skriklingar","döda unga skriklingar"}},{q="Var hittar man Shadowgale-skriklingarna?",a="Shadowgale-skriklingarna rör sig bland trädkronorna och i snåren i Shadowgale Forest. Resenärer måste vara försiktiga när de tar sig genom skogen för att spåra upp dem.",al={"var ligger shadowgale forest","skriklingars plats","var finns skriklingar"}},{q="Vilka andra ingredienser används tillsammans med fjädrarna?",a="Omslaget består av lokal mossa och antiseptisk saft. Sedan binds och isoleras det med duniga fjädrar från unga skriklingar.",al={"ingredienser i omslaget","vad innehåller omslaget"}},{q="Varför har skriklingarna blivit så fientliga på sistone?",a="Det är oklart exakt vad som orsakat deras plötsliga fientlighet, men de unga varelserna, som vanligtvis är fridsamma, har blivit ovanligt aggressiva. Det lägger ännu en kris till dem som de lokala vårdarna måste hantera.",al={"varför är skriklingar arga","orsaken till skriklingars aggressivitet"}}},fp="20,414,22.495.0,26.496.0,23.457.0,63.255.0,43.212.0,58.263.0,43.154.0,63.160.0,50.207.0"}
P.entries["quest:94487"] = {n="Unwanted and Unworthy",s="Unwanted and Unworthy är ett uppdrag på Zephras där äventyrare hjälper Elegael att hämnas på Al'Aketh Cultists efter ett blodigt bakhåll i Shadowgale Forest. Genom att dräpa kultisterna och återta stulna arvegods hämnas spelarna fallna druider och återtar heliga släktreliker åt High Elder.",h="Unwanted and Unworthy är ett uppdrag på Zephras där äventyrare hjälper Elegael att hämnas på Al'Aketh...",kw={"al'aketh","blodbestänkta arvegods","elegael","footsoldiers","arvegods","shadowgale forest","shen'dorei","stormchasers","zephras"},ang={["class:Druid"]="Al'Aketh Cultists spillde lokala druider blod under sitt oprovocerade angrepp på Zephras, vilket gör denna attack till en direkt hämndaktion och ett försvar av naturens balans."},sec={{t="Bakhåll i Shadowgale Forest",b="Zephras fredliga balans rubbades plötsligt när Al'Aketh Cultists överraskade de lokala druiderna med ett bakhåll i Shadowgale Forest. Elegael hade tidigare avfärdat dessa fanatiker som ofarliga drömmare med ”moln mellan öronen”, men överrumplades av attackens rena brutalitet. Druidernas blod rann över skogsmarken, och kravet på snabb vedergällning riktades mot Footsoldiers och Stormchasers som låg bakom."},{t="Besudlade arvegods och förlorad ungdom",b="För Elegael fråntog kultisternas förräderi dem deras arv: de förtjänar inte längre att kallas shen'dorei, och deras kvarlevor förtjänar inte heller hemlandets vindar. Många av kultisterna var unga och hade lovande framtider, men fanatismen satte stopp för dem. Genom att återta deras blodbestänkta arvegods hjälper äventyrarna till att se till att dessa heliga föremål återlämnas till High Elder, där de väntar på en visare och mer värdig generation."}},faq={{q="Vilka är Al'Aketh Cultists?",a="Al'Aketh Cultists är stormbesatta kultister som verkar på ön Zephras. Enligt Elegael betraktades de en gång som bara dåraktiga, eller som personer med ”moln mellan öronen”, men de tog plötsligt till brutalt våld mot de lokala druiderna.",al={"vilka är alaketh","alaketh-kulten","vilka är kultisterna"}},{q="Vem är Elegael?",a="Elegael är en beskyddare eller druid av shen'dorei-folket med anknytning till Zephras, som överfölls av Al'Aketh Cultists. Upprörd över förräderiet och blodspillan bland unga söker Elegael vedergällning och vill återta de stulna släktklenoderna.",al={"vem är elegael","uppdragsgivaren elegael"}},{q="Vad är de blodbestänkta arvegodsen?",a="De blodbestänkta arvegodsen tillhörde unga shen'dorei som drogs in i Al'Aketh Cult. Elegael samlar in dem så att de en dag kan återlämnas till High Elders samling och gå vidare till en mer värdig framtida generation.",al={"blodbestänkta arvegods","varför samla arvegods","vad är arvegodsen"}},{q="Vilka är shen'dorei?",a="Shen'dorei är folket som bor på Zephras. Elegael anser att de förrädiska Al'Aketh Cultists har förverkat sin rätt att kallas shen'dorei genom sitt våldsamma förräderi och sin kränkning av öns harmoni.",al={"shen'dorei betydelse","vilka är shen'dorei"}},{q="Var ligger Shadowgale Forest?",a="Shadowgale Forest är ett skogsområde på Zephras där Al'Aketh Footsoldiers och Stormchasers håller till och där det oprovocerade bakhållet mot druiderna ägde rum.",al={"shadowgale forest läge","var ligger shadowgale"}},{q="Varför överföll Al'Aketh Cultists druiderna?",a="Kultisternas exakta motiv är ett oroande mysterium för Elegael. De hade länge avfärdats som ofarliga fanatiker, men deras plötsliga och våldsamma uppror krossade den sköra balansen på ön.",al={"varför anföll kultisterna","kultisternas motiv","varför överföll de druiderna"}}},fp="21,304,27.471.0,32.425.0,30.258.0,15.240.0,32.229.0,24.224.0,27.171.0,48.201.0"}
P.entries["quest:94488"] = {n="The Ties That Bind",s="The Ties That Bind är ett uppdrag i Shadowgale Forest som kretsar kring ett bittert svek inom druidkretsen. Elegael Thornpaw upptäcker att Haalien, en druid från kretsen som varit försvunnen, har anslutit sig till de anfallande kultisterna som befälhavare och beordrar hans avrättning. Uppdraget visar pliktens smärtsamma personliga pris när familjen vänder sig mot sina egna.",h="The Ties That Bind är ett uppdrag i Shadowgale Forest som kretsar kring ett bittert svek inom druidkretsen.",kw={"cenarion circle","befälhavaren haalien","kultister","druid","elegael thornpaw","haalien","shadowgale forest","the ties that bind"},ang={["class:Druid"]="Cenarion Circle håller bevarandet av balans och släktskap heligt. Därför är Haaliens svek och blodspillan bland andra druider i kretsen ett särskilt allvarligt brott mot ordningen."},sec={{t="Svek i skogen",b="I djupet av Shadowgale Forest möter druider en hänsynslös kultistnärvaro som sprider skräck och blodspillan. För Elegael Thornpaw förvärras angreppet av en bitter upptäckt: doften av en tidigare druid från kretsen, Haalien, hänger över slakten. Haalien försvann flera månader tidigare, men dog inte i vildmarken. I stället slöt han upp med de invaderande kultisterna och tog befälet över deras våldsamma fälttåg mot sina tidigare fränder."},{t="Blod och släktskap",b="Haalien svek mer än sina löften till Cenarion Circle. När den fallne befälhavarens avhuggna huvud visas upp avslöjar Elegael att Haalien var hennes egen kusin. Hon rasar över hans grymheter, men att själv döda en släkting blev en alltför tung börda att bära ensam. Hans död sätter ett blodigt slut på en avfälling vars ondska kostade många oskyldiga livet."}},faq={{q="Vem erbjuder uppdraget The Ties That Bind?",a="Elegael Thornpaw är en druid stationerad i Shadowgale Forest. Med kultisternas intrång att hantera skickar hon äventyrare för att jaga befälhavaren Haalien, efter att ha upptäckt hans del i blodbadet.",al={"vem ger the ties that bind","uppdragsgivare i shadowgale","vem är elegael thornpaw"}},{q="Vem är befälhavaren Haalien?",a="Befälhavaren Haalien var tidigare en druid i Cenarion Circle som försvann flera månader innan kultistangreppen. Han föll inte offer för det annalkande mörkret, utan anslöt sig frivilligt till de fientliga kultisterna och steg i graderna tills han ledde deras styrkor mot sina fränder.",al={"vem är haalien","befälhavaren haalien bakgrund","haalien bakgrund"}},{q="Varför vill Elegael att befälhavaren Haalien ska dö?",a="Haalien övergav sin druidkrets och tog befälet över kultister som slaktade oskyldiga och spillde sina bröders blod. På grund av hans handlingar och hotet han utgör mot skogen beordrar Elegael hans avrättning.",al={"varför döda haalien","haaliens brott","vad gjorde haalien"}},{q="Vilken koppling finns mellan Elegael Thornpaw och Haalien?",a="Befälhavaren Haalien är Elegael Thornpaws kusin. Hon är djupt rasande över hans brott, men medger att det skulle ha varit en bitter börda att själv avrätta sin egen släkting. Därför ber hon en äventyrare om hjälp.",al={"är elegael och haalien släkt","hur känner elegael och haalien varandra"}},{q="Varför finns det kultister i Shadowgale Forest?",a="De lokala druiderna kan inte heller förstå kultisternas exakta motiv för att vara i Shadowgale Forest. Men deras styrkor leds av före detta medlemmar av kretsen, som Haalien, som riktade våld och blodspillan mot skogens försvarare.",al={"kultister i shadowgale forest","varför finns kultister i shadowgale"}},{q="Var utspelar sig uppdraget?",a="Uppdraget utspelar sig i Shadowgale Forest, där Elegael Thornpaw undersöker kultisternas invasion och konfronteras med den dystra verkligheten i sin kusins svek.",al={"var utspelar sig the ties that bind","shadowgale forest plats"}}},fp="18,345,22.444.0,17.377.1,40.204.0,25.258.0,45.218.0,60.221.0,50.254.0,33.174.0"}
P.entries["quest:94489"] = {n="The Wounds of Betrayal",s="The Wounds of Betrayal är ett uppdrag i Shadowgale Forest som skildrar följderna av ett tragiskt överfall mot de sällsynta shen'dorei-druiderna. Elegael skickar dig med brådskande omslag till sina sårade fränder i Nightfang Den och för att leta efter hennes försvunna partner, Jorel Windsinger. Uppdraget blottlägger snart svekets bittra pris och driver på en hämndlysten konflikt mot Al'Aketh.",h="The Wounds of Betrayal är ett uppdrag i Shadowgale Forest som skildrar följderna av ett tragiskt överfall mot...",kw={"al'aketh","druid","elegael","jorel windsinger","nightfang den","shadowgale forest","shen'dorei","the wounds of betrayal"},ang={["class:Druid"]="Som druider som vårdar vildmarken känns det tungt och personligt när andra druider, särskilt de fåtaliga shen'dorei-druiderna, faller offer för svek och svåra skador.",["race:NightElf"]="Nattalver vördar druiderna traditioner. Därför berör lidandet bland besläktade druider i Shadowgale Forest och kampen mot förräderi dem djupt."},sec={{t="Hjälp åt shen'dorei",b="The Wounds of Betrayal börjar med Elegael, en shen'dorei-druid som tar hand om följderna av ett katastrofalt överfall i Shadowgale Forest. Hon har hastigt förberett medicinska omslag och söker desperat en äventyrare som kan föra hjälp till hennes fränder, som tagit skydd i närbelägna Nightfang Den, strax norrut på andra sidan gläntan. Shen'dorei-druiderna är ytterst få, så varje enskild medlems överlevnad är avgörande för deras utsatta gemenskap."},{t="Sökandet efter Jorel Windsinger",b="Utöver att ge de sju illa tilltygade druiderna i grottan akut vård bär Elegael på en personlig vädjan: att hitta sin partner, Jorel Windsinger. När hon flydde striderna för att förbereda mediciner kämpade Jorel redan för sitt liv. En färd in i Nightfang Dens mörka skrymslen avslöjar den verkliga förödelse som drabbat tillflyktsorten och Jorels dystra öde."},{t="Ett löfte om vedergällning",b="När Elegael får höra om Jorels tragiska slut och det fruktansvärda priset hennes fränder fått betala brister hennes behärskning i sorg och vrede. Med sammanbitna tänder och ett smärtfyllt morrande förkastar hon förtvivlan till förmån för ren vedergällning. Hon svär att alla som är allierade med de skuggfyllda Al'Aketh ska få känna hennes obevekliga vrede för slakten på hennes folk."}},faq={{q="Vem ger uppdraget The Wounds of Betrayal?",a="Uppdraget ges av Elegael, en shen'dorei-druid som desperat försöker ta hand om sina sårade fränder efter ett våldsamt angrepp i Shadowgale Forest.",al={"vem ger the wounds of betrayal","uppdragsgivare the wounds of betrayal","vem är elegael"}},{q="Var ligger Nightfang Den?",a="Nightfang Den är en grotta strax norrut på andra sidan gläntan i Shadowgale Forest. Där har skadade shen'dorei-druider dragit sig tillbaka för att söka skydd.",al={"var ligger nightfang den","nightfang den plats","var finns de sårade druiderna"}},{q="Vem är Jorel Windsinger?",a="Jorel Windsinger är Elegaels partner. Han skadades svårt i angreppet och stannade i Nightfang Den, där spelaren upptäcker hans tragiska öde.",al={"vem är jorel windsinger","jorel windsingers öde","var är jorel"}},{q="Vad är shen'dorei-druiderna?",a="Shen'dorei är en sällsynt grupp med mycket få druider. Eftersom de är så få betonar Elegael att varje överlevande liv bland dem är dyrbart.",al={"vad är shendorei","vilka är shendorei-druiderna","shen'dorei-druidernas historia"}},{q="Vilka är Al'Aketh?",a="Al'Aketh är fiender som ligger bakom, eller är allierade med dem som angrep druiderna. När Elegael får veta Jorels öde och hur hennes orden ödelagts svär hon att hämnas på Al'Aketh och alla deras allierade.",al={"vilka är al'aketh","al'aketh","varför hatar elegael al'aketh"}},{q="Vad händer Jorel Windsinger under uppdraget?",a="När du hittar Jorel Windsinger i hålan upptäcker du att hans tillstånd har tagit en tragisk vändning. När du återvänder till Elegael med besked om hans öde och de överlevande druidernas svåra belägenhet drabbas hon av sorg och svär ursinnigt att hämnas.",al={"vad händer jorel windsinger","överlever jorel","jorels öde"}}},fp="22,394,22.448.0,31.390.1,20.340.2,43.149.0,31.148.0,24.157.0,31.191.0,21.223.0,46.232.0"}
P.entries["quest:94490"] = {n="Ripped Missive",s="Ripped Missive är ett blodbestänkt brev som hittades på Haalien och avslöjar en brutal kultistattack mot en druidehåla i Shadowgale Forest. Innehållet blottlägger de hänsynslösa motiven bakom massakern och antyder farlig omstörtning inifrån Valanaar.",h="Ripped Missive är ett blodbestänkt brev som hittades på Haalien och avslöjar en brutal kultistattack mot en...",kw={"kultist","druidehåla","elegael thornpaw","haalien","lotheluum","pylon","ripped missive","shadowgale forest","valanaar"},ang={["class:Druid"]="Druider kommer att finna en bitter tragedi i brevet: druiderna i hålan slaktades bara för att de stod i vägen för kultister som sökte efter en forntida pylon."},sec={{t="Blodbestänkta order",b="Det här sönderrivna och blodbestänkta dokumentet låg gömt bakom Haaliens armskena och innehåller mörka upplysningar om det senaste våldet i Shadowgale Forest. Det hittades efter en våldsam strid och kastar ljus över kultisternas mörka avsikter när de anföll den lokala druidehålan. Brevet ger viktiga ledtrådar åt den som söker rättvisa för de fallna."},{t="Meningslös massaker",b="När du visar pergamentet för Elegael Thornpaw i Shadowgale Forest kommer den fruktansvärda sanningen om räden fram. Kultisterna angrep inte druiderna på grund av någon särskild fejd. De sökte efter en mystisk pylon och mördade hålans invånare enbart för att de stod i vägen. Elegael rasar över den meningslösa massakern och svär att hämnas på alla kultister som finns kvar i skogen."},{t="Förräderi i Valanaar",b="Brevet avslöjar inte bara att kultisterna sökte efter pylonen, utan också något långt mer oroande: ordern verkar ha kommit från själva Valanaar. Denna dystra insikt pekar på en förrädare i bosättningen. För att avslöja konspirationen innan fler liv går förlorade måste brevet genast föras till Lotheluum i Valanaar."}},faq={{q="Vad är Ripped Missive?",a="Ripped Missive är ett sönderrivet, blodbestänkt brev som hittades instucket bakom Haaliens armskena efter en strid. Det innehåller viktiga upplysningar som avslöjar motiven bakom kultisternas attack mot en druidehåla i Shadowgale Forest.",al={"vad är ripped missive","uppdraget ripped missive","blodbestänkt brev haalien"}},{q="Var hittades brevet?",a="Brevet hittas direkt på Haalien, instucket bakom en av deras armskenor efter en våldsam konfrontation. Det skadades och fläckades av blod under striden.",al={"vem släppte ripped missive","var kom ripped missive ifrån","vem är haal ien"}},{q="Vem ska få Ripped Missive?",a="Brevet lämnas först till Elegael Thornpaw i Shadowgale Forest. När Elegael har läst det ger hen dig i uppdrag att snabbt lämna det till Lotheluum i Valanaar för att varna för ett möjligt förräderi.",al={"vem vill ha ripped missive","vem ska jag ge ripped missive till","elegael thornpaw brev"}},{q="Varför angrep kultisterna druidehålan?",a="Brevet avslöjar att kultisterna inte angrep druidehålan av hat mot druiderna, utan för att lägga beslag på en pylon där. Druiderna som bodde där slaktades skoningslöst enbart för att de stod i kultisternas väg.",al={"varför angrep kultisterna druidehålan","kultisternas motiv druidehålan","varför angrep haal ien"}},{q="Varifrån kom attackordern?",a="Brevet visar att kultisternas order kom från Valanaar. Det tyder på att en förrädare döljer sig i bosättningen och styr verksamheten därifrån.",al={"varifrån kom ordern","vem skickade haal ien","förrädare i valanaar"}},{q="Vem är Lotheluum och varför måste hen underrättas?",a="Lotheluum är en kontakt i Valanaar. Elegael Thornpaw beordrar dig att ta brevet till Lotheluum och varna om att kultisternas dödliga order kan spåras till någon som gömmer sig i Valanaar.",al={"vem är lotheluum","varför ta brevet till lotheluum","lotheluum valanaar"}}},fp="14,284,19.354.0,19.423.1,21.365.2,27.233.0,36.185.0,38.203.0,42.255.0,38.175.0,47.204.0"}
P.entries["quest:94491"] = {n="The Fate of the Den",s="The Fate of the Den skildrar de dystra följderna av en kultistattack mot en avskild druidskans. En äventyrare skickas med ett återfunnet meddelande till Lotheluum i Valanaar, med nyheter om svåra förluster. Meddelandet avslöjar en djupt oroande verklighet: någon i Valanaar har försett fienden med viktig information.",h="The Fate of the Den skildrar de dystra följderna av en kultistattack mot en avskild druidskans.",kw={"kultister","druidskans","high elder","lotheluum","meddelande","the fate of the den","förrädare","valanaar"},ang={["class:Druid"]="Druider känner tyngden av den här tragedin starkt, eftersom de stupade i skansen var deras fränder och deras avskilda tillflykt förråddes till fientliga kultister."},sec={{t="Tragedin i The Den",b="Efter kultisternas våldsamma angrepp på druidskansen finner sig de överlevande försvararna tilltufsade och sörjer sina stupade kamrater. Den omedelbara krisen kunde hejdas med hjälp utifrån, men de fysiska och känslomässiga skadorna är enorma. De stupade kan inte återupplivas, och de sårade överlevande är inte i skick att ge sig ut på en lång vandring medan kultister fortfarande stryker omkring i närheten."},{t="Förräderi i Valanaar",b="Ett återfunnet meddelande bekräftar att kulten inte agerade på måfå; någon som håller sig dold i Valanaar har aktivt läckt underrättelser till dem. När Lotheluum får meddelandet uttrycker han fullständig bestörtning över slakten på sina fränder och den skrämmande insikten att en medbrottsling eller förrädare går fri i deras bosättning. Fast besluten att deras offer inte ska glömmas för han bevismaterialet direkt till High Elder."}},faq={{q="Vem är Lotheluum?",a="Lotheluum bor i Valanaar och tar emot rapporter om druidskansen. När han får veta om angreppet och granskar det återfunna meddelandet uttrycker han djup sorg över sina stupade fränder och lovar att föra bevisen på förräderiet direkt till High Elder.",al={"lotheluum","vem är lotheluum","lotheluum npc"}},{q="Vad hände i druidskansen?",a="Druidskansen utsattes för ett förödande angrepp av fientliga kultister, och många försvarare dödades. Även om hotet hejdas med hjälp av en äventyrare är de överlevande försvararna svårt tilltygade och hittar bevis för att en insider låg bakom angreppet.",al={"vad hände i skansen","angrepp på druidskansen","bakgrund till the fate of the den"}},{q="Vad avslöjar det återfunna meddelandet?",a="Meddelandet avslöjar att en kontaktperson som håller sig dold i bosättningen Valanaar i hemlighet har försett kulten med underrättelser. Informationen tyder på att den dödliga räden mot skansen möjliggjordes genom sabotage och spionage på orten.",al={"vad står det i meddelandet","meddelande från skansen","förrädarens meddelande"}},{q="Vem är High Elder som Lotheluum nämner?",a="High Elder är en framstående auktoritet i Valanaar som Lotheluum lyder under. På grund av de svåra förlusterna och hotet från en aktiv förrädare för Lotheluum genast meddelandet och nyheten om tragedin vidare till High Elder.",al={"vem är high elder","valanaars high elder","high elder"}},{q="Vem låg bakom angreppet på druidskansen?",a="Angreppet utfördes av medlemmar i en kult som verkar i området. Kultisterna lyckades tillfoga invånarna i skansen katastrofala förluster tack vare vägledning från en informatör som fått skydd i Valanaar.",al={"vem angrep skansen","vem angrep druidskansen","kultister i skansen"}},{q="Varför kunde inte den överlevande i skansen själv leverera meddelandet?",a="Den överlevande i skansen var för svårt sårad för att klara vandringen till Valanaar efter angreppet. Förutom att kroppen inte klarade resan stannade den överlevande kvar för att göra sig av med de återstående kultisterna och skickade en äventyrare för att slå larm.",al={"varför levererar vi meddelandet","uppdragsgivaren är skadad","varför kan den överlevande inte ta sig till valanaar"}}},fp="19,339,18.413.0,21.447.1,17.277.0,31.280.0,39.251.0,45.245.0,48.210.0,69.250.0"}
P.entries["quest:94494"] = {n="Call of Water",s="Call of Water är ett andligt uppdrag för shamaner som är redo att förena sig med vattenelementets renande natur. Efter att ha skapat harmoni med vind, jord och eld når den invigde Norric Lochthane i Loch Modan, som uppmanar dem att ta det första steget mot att lära sig vattnets renhet.",h="Call of Water är ett andligt uppdrag för shamaner som är redo att förena sig med vattenelementets renande...",kw={"call of water","element","berg","renhet","shaman","totemprövning","water totem"},ang={["class:Shaman"]="Denna prövning är ett grundläggande steg i att stämma sig till elementandarna och gå från jord och eld mot förståelsen av vattnets flöde och renhet.",["race:Dwarf"]="Mentorns kärva dvärgstämma speglar hur dvärgshamaner i Forever närmar sig föreningen med naturen längs karga bergsstigar."},sec={{t="Renhetens väg",b="Call of Water är ett viktigt steg på shamanens väg mot elementär balans. Med jorden som grund för varje steg, vinden i ryggen och den inre elden brinnande stark kallas vandraren att förstå vattnets djupare natur. Det är inte bara en yttre kraft, utan också en andlig spegling av renhet och uthållighet."},{t="Uppstigning bland elementen",b="En erfaren mentor talar med bergens stadiga stämma och manar den invigde framåt utan tvekan. En shaman får aldrig en förbindelse med andarna till skänks. Den kräver fysisk ansträngning, uthållig själ och en färd upp genom karg terräng. Som mentorn varnar väntar berget inte på någon, och resan mot verklig förståelse måste börja med det avgörande första steget."}},faq={{q="Vad är Call of Water?",a="Call of Water är en andlig övergångsrit för shamaner som söker förening med vattenelementet. Efter att redan ha lärt sig jordens stadga, vindens fart och eldens gnista kallas den som söker att lära sig vattnets djupare sanning.",al={"vad är call of water","call of water-uppdraget","vad är det här för uppdrag"}},{q="Vem vägleder detta steg på resan?",a="Eldrun Stormbreaker, shamantränaren i Ironforge, skickar den invigde till Norric Lochthane i Loch Modan. Norric säger dessa ord för att mana till beslutsam handling och påminna vandraren om att varken elementen eller höjderna väntar på den tveksamma.",al={"vem ger call of water","vem säger att berget inte väntar på någon","mentor i call of water"}},{q="Vad betyder det att berget inte väntar på någon?",a="Det är en uppmaning att ta det första steget på en krävande uppstigning. Shamaners resor leder ofta högt upp bland toppar och in i avlägsen vildmark där andarna bor. Där krävs beslutsamhet, inte dröjande tvivel.",al={"vad betyder berget väntar inte på någon","berget väntar inte på någon","bergets betydelse"}},{q="Vad är sanningen om vattnets renhet?",a="I shamanens utövande ger varje element sina egna lärdomar. Sten ger stadga och eld stärker beslutsamheten, medan vatten står för rening, flöde och renhet – viktiga insikter för att balansera andarna inom sig.",al={"varför vattnets renhet","vattnets renhets sanning","vattenelementets betydelse"}},{q="Hur förhåller sig vatten till de andra elementen här?",a="Innan vandraren närmar sig vattnet erkänner resan jorden, vinden och elden som grundvalar, redan förnimmade i stövel, andetag och mage. Harmoni med elementen kräver att man bemästrar balans, inte att man söker en enda kraft för sig.",al={"vilka element kommer först","förkunskaper för vatten","elementen i call of water"}},{q="Vart går den invigde efter att ha hört dessa ord?",a="Den invigde måste ta det första steget. Norric Lochthane skickar dem vidare till Wetlands för att söka Water Sapta hos Hervdana Saegrund, som bor i en grotta under de södra vattenfallen.",al={"vad händer sedan i call of water","vart går jag nu","nästa steg i call of water"}}},fp="13,294,18.336.0,24.387.0,26.259.0,36.248.0,53.197.0,36.224.0,49.230.0,53.182.0"}
P.entries["quest:94495"] = {n="Call of Water",s="Call of Water skickar andliga sökare till Wetlands för att lära sig vattnets renande kraft och söka efter Water Sapta. I en avskild grotta under de södra vattenfallen välkomnar dvärgen Hervdana Saegrund resenärer som vågar sig ut i vildmarken.",h="Call of Water skickar andliga sökare till Wetlands för att lära sig vattnets renande kraft och söka efter...",kw={"call of water","dvärg","hervdana saegrund","schaman","södra vattenfallen","water sapta","wetlands"},ang={["class:Shaman"]="Uppdraget är ett viktigt steg i att lära sig vattnets natur och få tag på en Water Sapta för att få kontakt med andarna.",["faction:Alliance"]="Resan tar resenärer djupt in i det förrädiska Wetlands, långt från alla dvärgiska eller alliansens vaktpatruller.",["race:Dwarf"]="Hervdana känner igen sökaren som en frände som vågar sig ut i de farliga träskmarkerna, där Dark Iron-dvärgar lurar i närheten."},sec={{t="Vattnets natur",b="Resan mot förståelse av vatten börjar med en enkel lektion om dess dubbla natur: vatten står för återfödelse, formar sten och renar orenheter när det är rent, men hotar med förödelse när det är förorenat. De som söker gemenskap med elementet skickas ut i vildmarken för att hämta en Water Sapta från dem som lever nära det."},{t="Skydd under vattenfallen",b="Djupt inne i Wetlands fuktiga träskmarker har Hervdana Saegrund och hennes familj sitt hem i en grotta, gömd direkt under de södra vattenfallen. Långt från Ironforge-vakternas beskydd uthärdar de hotet från Dark Iron-dvärgar som lurar i de omgivande träskmarkerna för att kunna leva avskilt vid de forsande vattenfallen."}},faq={{q="Vem är Hervdana Saegrund?",a="Hervdana Saegrund är en dvärg som bor med sin familj i en grotta under Wetlands södra vattenfall. Hon hjälper schamaner som söker gemenskap med vatten och kunskap om Water Sapta.",al={"vem är hervdana","hervdana saegrund","var finns hervdana"}},{q="Vad är Water Sapta?",a="En Water Sapta är ett ceremoniellt elixir som schamaner använder för att få kontakt med vattnets andar. För att få tag på en i de östra rikena hänvisas sökare till Hervdana Saegrund nära de södra vattenfallen.",al={"vad är water sapta","sapta betydelse","varför skaffa water sapta"}},{q="Var finns Hervdana Saegrund?",a="Hervdana och hennes familj bor avskilt i en grotta direkt under de södra vattenfallen i Wetlands.",al={"var bor hervdana","var ligger grottan","de södra vattenfallens läge"}},{q="Varför bor Hervdana i det farliga Wetlands?",a="Trots den ständiga faran från Dark Iron-dvärgar som lurar i träskmarkerna och den totala avsaknaden av stadsvakter har Hervdana och hennes släkt av egna skäl valt att leva avskilt i vattenfallsgrottan.",al={"varför bo i wetlands","faror i wetlands","dark iron i wetlands"}},{q="Vad är lärdomen om vatten här?",a="Vatten står för återfödelse, formar sten, sköljer bort smuts och lindrar trötta när det är rent. Men om det fördärvas eller förorenas förstör det allt det rör vid.",al={"vad betyder vatten","vattnets filosofi","lärdom om vatten"}},{q="Vad är syftet med uppdraget Call of Water?",a="Call of Water är en schamansk övergångsrit som vägleder de invigda till att förstå elementets natur och söka upp Water Sapta hos avskilda vägvisare.",al={"vad är det här för uppdrag","vem är uppdraget till för","dvärgschamanens uppdrag"}}},fp="13,235,19.304.0,25.334.0,25.190.0,24.195.0,37.118.0,49.209.0,40.160.0,47.150.0"}
P.entries["quest:94497"] = {n="Call of Water",s="Call of Water är ett andligt uppdrag i Wetlands som vägleder en novis på vägen mot att förtjäna sapta. Genom att samla bräckt flodmynningsvatten där bergens vattenfall möter havets tidvatten lär sig sökaren vattnets livgivande krafter samtidigt som hen tar sig fram bland träskets faror.",h="Call of Water är ett andligt uppdrag i Wetlands som vägleder en novis på vägen mot att förtjäna sapta.",kw={"call of water","dark iron","flodmynning","hervdana","sapta","skinnflaska","wetlands"},ang={["class:Shaman"]="Att söka sapta kräver att man förstår vattnets natur i olika länder och stämmer sin ande till dess många former.",["race:Dwarf"]="Hervdana sörjer den fortsatta splittringen mellan dvärgklanerna, särskilt när Dark Iron-dvärgar tränger så långt norrut som till Wetlands."},sec={{t="Sapta-vägen",b="För att förtjäna sapta och möta andarna måste en novis söka vatten i dess olika former. Hervdana vägleder sökare att se hur vatten rör sig, förändrar liv och ger näring åt landet. Resan börjar med att förstå flodmynningsvatten där havets tidvatten möter färskt vatten från höglandet."},{t="Där sötvatten möter bräckt vatten",b="Vid foten av vattenfallen nedanför Hervdanas grotta rinner källvatten från höglandet ner i träsket och möter saltvatten som tidvattnet fört in från kusten. Havets tidvatten för med sig sediment, mineraler och krafter som skiljer sig mycket från klart smältvatten från bergen, vilket gör flodmynningen till en källa till naturlig visdom."},{t="Skuggor i träsket",b="Att samla vatten i Wetlands är inte riskfritt. Förutom den farliga träskfaunan har Dark Iron-dvärgar trängt obehagligt långt norrut. Hervdana betraktar med sorg den pågående fientligheten mellan dvärgklanerna och ser hur mycket dvärgfolket skulle kunna åstadkomma om de bara lade sina fejder åt sidan."}},faq={{q="Vad är sapta?",a="Sapta är en helig dryck som används för att möta elementandarna. För att förtjäna den måste en novis söka vatten i dess olika tillstånd och förstå hur det formar landet och ger näring åt levande varelser.",al={"vad är sapta","sapta betydelse","varför söka sapta"}},{q="Vem är Hervdana?",a="Hervdana ger uppgiften från sin grotta ovanför vattenfallen i Wetlands. Hon vägleder noviser när de samlar vattenprover för att stämma dem till elementet.",al={"vem ger call of water","var finns hervdana","hervdanas grotta"}},{q="Varför samla vatten där sötvatten möter bräckt vatten?",a="Flodmynningsvatten är en särskild samlingspunkt där snösmältning och färska källor från höglandet blandas med havets tidvatten. Mötet mellan sötvatten och mineralrikt saltvatten för med sig unika sediment och andlig visdom.",al={"varför flodmynningsvatten","bräckt vatten wetlands","där sötvatten möter saltvatten"}},{q="Vilka faror lurar nära vattenfallen?",a="Dark Iron-dvärgar har smugit sig norrut in i Wetlands och utgör ett direkt hot mot resenärer och elementssökare som försöker nå träskmarkerna och vattenfallen.",al={"dark iron i wetlands","varför är dark iron-dvärgar här","hotet från dark iron"}},{q="Vad innebär det att bli ett kärl?",a="Ett kärl är en novis som har börjat söka vattnets visdom aktivt och bär med sig gåvor av naturens vatten för att utveckla en djupare samklang med elementen.",al={"vad är ett kärl","vattenkärl"}},{q="Vad används Empty Brown Waterskin till?",a="Empty Brown Waterskin är kärlet Hervdana tillhandahåller för att samla in det bräckta provet vid foten av träskets vattenfall.",al={"vad används empty brown waterskin till","vilken skinnflaska används"}}},fp="13,266,20.286.0,26.307.0,20.303.0,18.206.0,16.169.0,52.204.0,38.160.0,37.149.0,43.130.0"}
P.entries["quest:94499"] = {n="Call of Water",s="Call of Water är ett uppdrag där resande skickas till Stonewatch Falls i Redridge för att undersöka misstänkt förorening i vattnet från Lake Everstill. Genom att fylla en Empty Red Waterskin och återvända med den till Hervdana Saegrund i Wetlands avslöjar schamaner den verkliga orsaken till de muterade murlocerna i trakten och får samtidigt ett viktigt reagens till sina andliga prövningar.",h="Call of Water är ett uppdrag där resande skickas till Stonewatch Falls i Redridge för att undersöka misstänkt...",kw={"call of water","hervdana saegrund","lake everstill","nightcrawler-murlocer","redridge","sapta","skuggseare","stonewatch falls","wetlands"},ang={["class:Shaman"]="Uppdraget är ett viktigt steg i bryggandet av en Water Sapta och prövar schamanens hängivenhet och förmåga att uppfatta vatten långt hemifrån, innan mötet med vattnets andar."},sec={{t="Ett misstänkt vattenfall",b="Hervdana Saegrund i Wetlands skickar blivande schamaner söderut till Redridge för att undersöka vattendragen som störtar nerför Stonewatch Falls. Lake Everstill förser Lakeshire med rent vatten, men murlocerna som håller till vid vattenfallets fot har blivit ovanligt stora och förvridna bestar. Hervdana misstänker gift, mörk trolldom eller läckage från den gamla fästningen ovanför och ber resande samla ett prov i en Empty Red Waterskin."},{t="Föroreningens verkliga källa",b="När Hervdana undersöker den fyllda vattenskinnen upptäcker hon att vattnet som forsar från Everstill är helt rent och opåverkat av föroreningar. De lokala Nightcrawler-murlocernas fysiska förvridning beror inte på förorenat dricksvatten, utan på den mörka magi som skuggseare runt Stonewatch använder. Provet visar både att vattenfallet är rent och att schamanen är hängiven, och fungerar som ett viktigt reagens när en andlig sapta ska bryggas."}},faq={{q="Vem ger uppdraget och var finns personen?",a="Hervdana Saegrund, som finns i Wetlands, ger uppdraget. Hon studerar vattenkällor och de reagens som krävs för att skapa en sapta åt en blivande schaman inför de andliga prövningarna.",al={"vem ger call of water","uppdragsgivaren hervdana"}},{q="Varför skickas du för att hämta vatten från Stonewatch Falls?",a="Hervdana misstänker att märkligt gift, mörk magi eller förorening kan rinna nerför Stonewatch Falls från det gamla fortet ovanför och orsaka missbildningar hos murlocerna vid foten. Hon behöver ett färskt prov att undersöka.",al={"varför fylla vattenskinn i redridge","syftet med stonewatch falls"}},{q="Är vattnet vid Stonewatch Falls faktiskt förorenat?",a="Nej, själva vattnet visar sig vara helt rent och oförorenat. Hervdana kommer fram till att de lokala murlocernas förvridna tillstånd i stället beror på mörk magi från traktens skuggseare, inte på förorenat vatten.",al={"är vattnet vid stonewatch förorenat","är lake everstill förorenad"}},{q="Varför är murlocerna vid Stonewatch Falls så stora och förvridna?",a="Nightcrawler-murlocerna nära vattenfallets fot är stora och förvridna jämfört med dem som finns i The Loch eller Wetlands. Hervdana drar slutsatsen att förändringen orsakas av de lokala skuggsearnas onda magi.",al={"varför är murlocer i redridge muterade","skillnad på murlocer vid stonewatch"}},{q="Vad används vattenprovet till?",a="En sapta är en ceremoniell blandning som låter en schaman genomtränga slöjan och uppfatta elementandar. Hervdana samlar rena prover från olika vatten för att brygga det reagens du behöver.",al={"vad är en sapta","syftet med belöningen i call of water"}},{q="Vem är Norric?",a="Norric är en bundsförvant eller mentor som är inblandad i schamanernas prövningar. Hervdana säger att han kommer att glädjas åt att du lyckats hämta det rena vattenprovet.",al={"vem är norric","norric i call of water"}}},fp="13,368,17.466.0,29.473.1,48.170.0,56.205.0,50.213.0,65.204.0,34.194.0,14.160.0"}
P.entries["quest:945"] = {n="Therylune's Escape",s="I södra Darkshore har en ung nattalv vid namn Therylune irrat in på de hotfulla utgrävningsplatserna vid The Master's Glaive och hamnat omringad av fientliga kultister. En eskort från Alliansen behövs för att föra henne i säkerhet och meddela hennes oroliga syster Therysil, som vilar vid The Shrine of Aessina, att hon överlevt.",h="I södra Darkshore har en ung nattalv vid namn Therylune irrat in på de hotfulla utgrävningsplatserna vid The...",kw={"ashenvale","kultister","eskort","the master's glaive","the shrine of aessina","therylune","therysil","twilight's hammer"},ang={["faction:Alliance"]="Att hjälpa strandade vandrare som Therylune stärker Alliansens närvaro och välvilja bland de infödda nattalver som försvarar Ashenvale.",["race:NightElf"]="The Master's Glaive är ett uråldrigt ärr i Kalimdors historia. Att se dina kaldorei-fränder irra obekymrat in bland kultisternas utgrävningar är en tankeväckande påminnelse om hoten som växer inne i Ashenvale."},sec={{t="En farlig promenad",b="The Master's Glaive är ett av Darkshores mest kusliga landmärken, dominerat av en uråldrig monstruös varelses väldiga kranium, genomborrat av ett enormt stensvärd. Trots den fasa som vilar över dalen irrade Therylune rakt in i ravinens hjärta. Snart blev hon fast under Twilight's Hammer-kultisternas bevakning och överlevde bara tack vare snabba reflexer och sin förmåga att gömma sig i den oländiga terrängen."},{t="Besked till helgedomen",b="Therylunes syster Therysil bor långt i söder vid den fridfulla The Shrine of Aessina. Therylune är känd för att vara äventyrslysten och inte bry sig om att smutsa ner kläderna, men även hennes närmaste blev chockade när hon gav sig in bland de osunda utgrävningarna vid The Master's Glaive. Beskedet att Therylune är i säkerhet lättar oron hos en djupt bekymrad syster, som vet alltför väl vilka mörka krafter som just nu gräver genom Darkshores uråldriga jord."}},faq={{q="Vem är Therylune?",a="Therylune är en äventyrslysten ung nattalv som irrade in bland de farliga utgrävningarna vid The Master's Glaive i södra Darkshore. Hon är Therysils syster.",al={"therylune","vem är flickan","alv i fällan"}},{q="Vem är Therysil?",a="Therysil är Therylunes syster och håller till vid den fridfulla The Shrine of Aessina i Ashenvale. Hon blir bestört när hon får veta att hennes syster irrat så nära en så mörk och besudlad plats.",al={"therysil","therylunes syster"}},{q="Varför är The Master's Glaive så farligt?",a="The Master's Glaive är en uråldrig, hotfull ravin där en uråldrig ”old lord” föll för länge sedan. Twilight's Hammer-kultister svärmar över området, gräver aggressivt på platsen och anfaller alla som tränger sig in.",al={"faran vid the master's glaive","kultister vid the master's glaive"}},{q="Vart ska Therylune eskorteras?",a="Therylune behöver eskorteras bort från det omedelbara området kring The Master's Glaive till säkerhet. Därefter måste räddaren resa till The Shrine of Aessina för att underrätta hennes syster.",al={"eskortens mål","vart ska therylune"}},{q="Var ligger The Shrine of Aessina?",a="The Shrine of Aessina ligger i sydvästra Ashenvale, väster om Astranaar, och är en fristad tillägnad skogsanden Aessina.",al={"var ligger the shrine of aessina","var är therysil"}},{q="Hur överlevde Therylune omringad av kultister?",a="Therylune lyckades undvika att bli tillfångatagen enbart genom att hitta ett trångt gömställe bland klipporna och terrängen innan Twilight's Hammer-kultisterna hann upptäcka henne.",al={"hur gömde sig therylune"}}},fx={["8c0c4bd7"]={q="Varför behöver Therylune din hjälp för att fly?",a="Therylune irrade in i den olycksbådande utgrävningen vid The Master's Glaive och fann sig snart fångad och omringad av Twilight's Hammer-sektmedlemmar. Hennes förmåga att gömma sig har hållit henne vid liv, men hon kan inte på egen hand smita förbi fanatikerna som omringar henne för att nå säkerhet och lugna sin syster, Therysil.",al={"varför vill therylune ha hjälp","therylunes motiv","varför hjälpa therylune"}},cc515991={q="Varför kan Therylune inte fly på egen hand?",a="Therylune är skicklig nog på att gömma sig för att undvika att bli tillfångatagen direkt, men hon är helt obeväpnad och försvarslös, djupt inne på fientligt område. Eftersom inga vakter eller allierade finns i närheten är hon helt beroende av en förbipasserande äventyrare som kan bana en flyktväg genom sektmedlemmarna.",al={"varför behöver therylune mig","varför kan therylune inte fly","varför jag för therylune"}}},fp="18,319,17.430.0,18.430.0,17.163.0,16.181.0,40.202.0,41.176.0,39.135.0,49.167.0"}
P.entries["quest:94500"] = {n="Call of Water",s="Call of Water skickar en äventyrare genom Ashenvales smaragdgröna trädkronor för att samla rent, uråldrigt vatten från sjön vid Astranaar. Det är det sista insamlingssteget innan resenären skickas tillbaka till Norric.",h="Call of Water skickar en äventyrare genom Ashenvales smaragdgröna trädkronor för att samla rent, uråldrigt...",kw={"ashenvale","astranaar","auberdine","call of water","menethil","norric","southshore","vattensäck"},ang={["faction:Alliance"]="Uppdraget leder resenärer längs Alliansens sjöväg från Eastern Kingdoms till Kalimdor och förbinder Menethil Harbor med Auberdine och Night Elf-bosättningen Astranaar.",["race:NightElf"]="Uppdraget leder resenärer till det rena vattnet kring Astranaar, ett av Kaldoreis kärnområden i Ashenvale, där uråldriga ruiner fortfarande ligger orörda."},sec={{t="Jakten på rent vatten",b="Call of Water kräver att en äventyrare fyller en vattensäck med Ashenvales orörda vatten. Sökaren måste ta sig till Astranaar, en fristad omgiven av rent, uråldrigt vatten som skvalpar mot sjunkna ruiner från en svunnen tid. Detta rena prov är den sista vätskan uppdragsgivaren behöver innan resenären skickas vidare till Norric."},{t="Vägen till Astranaar",b="För att nå Ashenvales djup måste man korsa havet från Eastern Kingdoms. Den rekommenderade vägen går med fartyget från Menethil Harbor mot Auberdine, med ett hamnstopp i Southshore på vägen. Från Auberdines kajer leder vägen inåt land, in bland Ashenvales smaragdgröna trädkronor, där resenärer varnas för att hålla sig på sin vakt bland trädens vaksamma skuggor."}},faq={{q="Vad är uppdraget Call of Water?",a="Call of Water är ett uppdrag där resenären ska ta med en tom vattensäck djupt in i Ashenvales uråldriga skog. Målet är att samla ett prov av rent, uråldrigt och möjligen förtrollat vatten från sjön vid bosättningen Astranaar innan det återlämnas till uppdragsgivaren.",al={"vad är call of water","uppdraget call of water","målet med call of water"}},{q="Var samlar jag vatten till uppdraget?",a="Vattnet måste samlas från sjön som omger Astranaar, djupt inne i Ashenvale. Vattnet där är fortfarande orört och strömmar bland uråldriga, sjunkna ruiner från en svunnen tid.",al={"var hittar man rent vatten","var fyller man vattensäcken","call of water plats"}},{q="Hur tar jag mig till Ashenvale för uppdraget?",a="Resenärer rekommenderas att ta båten från Menethil Harbor till Auberdine, som stannar i Southshore på vägen. Från Auberdine vid Darkshores kust reser man söderut in i Ashenvales djupa, smaragdgröna skogar för att nå Astranaar.",al={"hur tar man sig till astranaar","resa till ashenvale","båt till astranaar"}},{q="Vad gör vattnet vid Astranaar speciellt?",a="Sjön vid Astranaar är känd för att innehålla vatten som inte har berörts av fördärv. Under ytan ligger nedsänkta stenruiner som vittnar om en uråldrig, svunnen tid av alvisk civilisation och ger vattnet dess rena och möjligen förtrollade egenskaper.",al={"vilken sjö finns i astranaar","astranaars vattenruiner","ruiner i astranaars sjö"}},{q="Vem är Norric?",a="Norric är personen som väntar på resenären efter att detta sista vätskeprov har samlats in. Uppdragsgivaren samlar in detta rena vatten från Ashenvale som den sista ingrediensen innan äventyraren skickas tillbaka till Norric.",al={"vem är norric","återvänd till norric"}},{q="Vilka faror kan jag vänta mig i Ashenvale?",a="Ashenvale är en uråldrig, tät skog full av faror. Uppdragsgivaren varnar resenärer att ständigt vara på sin vakt och påminner om att skogen har vakande ögon som aldrig blinkar när man färdas under dess smaragdgröna trädkronor.",al={"faror i ashenvale","hot i ashenvale"}}},fp="13,229,25.349.0,21.403.0,32.289.0,44.199.0,44.240.0,42.251.0,14.209.0,42.219.0"}
P.entries["quest:94501"] = {n="Call of Water",s="Call of Water är ett andligt prov för shamaner som söker de heliga vatten totem-riterna. Genom att överlämna rent vatten välsignat av Hervdana till Norric Lochthane i Loch Modan förbereder sig sökarna på att skapa den elementära sapta som behövs för att tala med andarna vid Stendel's Pond.",h="Call of Water är ett andligt prov för shamaner som söker de heliga vatten totem-riterna.",kw={"call of water","hervdana","loch modan","moonbrook","norric lochthane","shaman","stendel's pond","vial of purest water","water sapta","water totem"},ang={["class:Shaman"]="Detta prov är ett avgörande steg för att tala med elementen, utföra vatten totem-riterna och skapa den sapta som behövs för att se elementandar.",["faction:Alliance"]="Alliansens shamaner söker kontakt med vattenandar i de östra länderna och knyter samman Loch Modan med Westfall.",["race:Dwarf"]="Resan för samman dvärgiska shamanaspiranter med elementära mentorer som Norric Lochthane i Khaz Modan."},sec={{t="Vägen till Water Totem",b="Call of Water är ett viktigt prov i andlig samklang för blivande shamaner som söker harmoni med vattenelementet. För att gå denna väg måste man samla vatten som välsignats av Hervdana själv och visa både tålamod och vördnad för andarna innan kärlet förs till Norric Lochthane i Loch Modan."},{t="Sapta blir till",b="När Norric får det välsignade kärlet berättar han att den heliga vätskan ska användas till att brygga en vattensapta. Drycken låter sökaren skåda bortom det synliga och se vattenandarna som bor vid Stendel's Pond nära Moonbrook. Varenda droppe är dyrbar, för även en fuktad propp fyller sin funktion i de heliga riterna."}},faq={{q="Vem är Norric Lochthane?",a="Norric Lochthane är en mentor som bor i Loch Modan och vägleder kandidater genom deras samvaro med elementen. Han leder förberedelserna och riterna som krävs för att få en Water Totem.",al={"vem är norric","norric i loch modan","vem är norric lochthane"}},{q="Vem är Hervdana?",a="Hervdana Saegrund är vägvisaren i Wetlands. Hon bor med sin familj i en grotta vid de södra vattenfallen och välsignar det heliga vatten som blivande shamaner samlar in. Därmed ger hon det den andliga renhet som krävs för att skapa en vattensapta.",al={"vem är hervdana","välsignad av hervdana","hervdana vatten"}},{q="Vad används en sapta till?",a="En sapta är en elementär dryck som tillreds med heligt vatten. När en shaman dricker den kan hen skåda bortom slöjan och uppfatta de svårfångade vattenandar som bor i naturliga vattenpölar.",al={"vad är water sapta","saptans syfte","vad gör sapta"}},{q="Var ligger Stendel's Pond?",a="Stendel's Pond ligger i Westfall nära Moonbrook. I dess vatten finns elementära vattenandar som en shaman måste söka upp efter att ha druckit sin tillredda sapta.",al={"var ligger stendel's pond","stendel pond plats","vattenandar vid stendel"}},{q="Varför är Vial of Purest Water viktig?",a="Vial of Purest Water innehåller välsignat vatten som behövs för att brygga vattensaptan och utföra de heliga riterna som krävs för att få en Water Totem. Norric varnar för att inte ens en enda droppe får gå till spillo.",al={"varför behövs rent vatten","vial of purest water syfte"}},{q="Vad är vatten totem-riterna?",a="Vatten totem-riterna är andliga prov som shamaner genomgår för att stämma sig till vattenelementet och visa respekt och balans innan de får en Water Totem.",al={"vad är vatten totem-riterna","hur får man en water totem"}}},fp="13,257,27.325.0,18.332.1,24.179.0,16.226.0,25.175.0,32.161.0,42.208.0,31.180.0"}
P.entries["quest:94502"] = {n="Call of Water",s="Call of Water är ett elementuppdrag där du färdas från Loch Modan till Westfall för att återställa balansen i en fördärvad källa. Genom att rena den besmittade varelsen vid Stendel's Pond och utföra en uråldrig ritual vid den bortglömda helgedomen vinner du vattenandarnas gunst och får deras Water Totem.",h="Call of Water är ett elementuppdrag där du färdas från Loch Modan till Westfall för att återställa balansen i...",kw={"call of water","loch modan","moonbrook","norric","schaman","stendel's pond","water totem","westfall"},ang={["class:Shaman"]="Den här prövningen är en viktig övergångsrit där du stämmer dig till vattenandarna och vinner Water Totem, som visar din harmoni med och behärskning av elementkrafterna.",["faction:Alliance"]="Alliansens schamaner måste färdas genom sina områden, från Loch Modan till de oroliga trakterna i Westfall, för att rena det fördärvade vattnet."},sec={{t="En källa besmittad av skuggor",b="I Moonbrooks skugga ligger Stendel's Pond, som en gång var en hyllad, klar och ren källa. Mörka krafter som sveper över Westfall har förorenat dess fridfulla vatten och tystat de lokala vattenandarna. En gammal helgedom står vid stranden, försummad och täckt av damm och spindelväv, och väntar på att någon ska väcka de slumrande krafterna inom den."},{t="Reningsriten",b="Norric i Loch Modan vägleder dig genom ritualen som krävs för att återställa balansen. Riten kräver att du möter den vidriga varelsen som förorenar Stendel's Pond, tar dess armskenor och lägger dem på stenhelgedomen tillsammans med några droppar av ett alkemiskt brygd. När du uttalar besvärjelsen framkallar ångorna en renad ande, som delar med sig av sin visdom och visar att du är värdig Water Totem."}},faq={{q="Vad är uppdraget Call of Water?",a="Call of Water är en andlig prövning för schamaner som söker kontakt med vattnets element. Uppdraget går ut på att rena fördärvet vid Stendel's Pond i Westfall, använda en gammal helgedom där för att frammana en renad vattenande och vinna sin Water Totem.",al={"vad är call of water","water totem-uppdrag","vattenuppdrag i westfall"}},{q="Vem ger det här uppdraget?",a="Uppdraget ges av Norric, en mentor i Loch Modan. Han lär dig elementritualer, ger dig särskilda brygder och vägleder dig i att rena fördärvade elementvatten.",al={"vem ger call of water","norric i loch modan","uppdragsgivare"}},{q="Var ligger Stendel's Pond?",a="Stendel's Pond ligger strax utanför Moonbrook i sydvästra Westfall. Den var en gång en ren källa, men har blivit stillastående och grumlig under inflytande av mörka, fördärvande krafter.",al={"var ligger stendel's pond","stendel's ponds plats","damm nära moonbrook"}},{q="Hur renar du fördärvet vid Stendel's Pond?",a="För att rena vattnet måste du besegra den fördärvande närvaron vid Stendel's Pond, ta dess armskenor och lägga dem på den uråldriga helgedomen tillsammans med de återstående dropparna av brygden medan du uttalar orden Norric har lärt dig.",al={"hur renar man dammen","rena stendel's pond","ritual vid helgedomen"}},{q="Vad får du när du slutför uppdraget?",a="När du har klarat prövningen och återvänt till Norric i Loch Modan med bevis på reningen får du din Water Totem, som ger dig makt över vattnets elementkrafter.",al={"vilken belöning ger call of water","water totem-belöning"}},{q="Varför är Stendel's Pond fördärvad?",a="Det är oklart var mörkret kommer ifrån. Källan ligger onaturligt stilla och omges av djurben, vilket väcker frågan om den har förgiftats av Westfalls spridande misär eller själv är en källa till fördärvet.",al={"varför är stendel's pond fördärvad","vad fördärvade dammen"}}},fp="13,302,26.358.0,21.400.1,32.273.0,21.190.0,24.166.0,52.220.0,43.181.0,32.238.0"}
P.entries["quest:94503"] = {n="Call of Water",s="Call of Water är ett uppdrag i Westfall där äventyrare ska rena korrumperade elementarkrafter.",h="Call of Water är ett uppdrag i Westfall där äventyrare ska rena korrumperade elementarkrafter.",kw={"call of water","rening","korrumpering","elementar","minor manifestation of water","vattenande","westfall"},ang={["class:Shaman"]="Att tala med uråldriga element och rena besmittade vattenandar är en grundläggande elementrit. Den påminner shamaner om deras eviga plikt att bevara naturens balans.",["faction:Alliance"]="Manifestationen finns i Westfall, ett territorium tillhörande Alliansen där de lokala andarna uthärdar den krypande farsot som drabbar landet."},sec={{t="Reningen av de besmittade vattnen",b="I Westfalls vindpinade landskap hotas vattnens naturliga balans av korrumperade andar. Riten Call of Water kräver att du möter denna ondska och uttalar heliga ord som frammanar ett strålande ljus. Ljuset skingrar de rastlösa, besmittade essenserna till ofarlig aska och stilla dimma."},{t="Andens varning",b="När de korrumperade väsendena drivits tillbaka kan en Minor Manifestation of Water tryggt visa sig och tala med dig. Den omedelbara korrumperingen avtar, men anden varnar för att landets livskraft fortsätter att minska. Den påminner mästarna om att skydda livet är en ständig uppgift."}},faq={{q="Vad är Call of Water?",a="Call of Water är en andlig prövning i Westfall där korrumperade andar fördrivs med en ritual som framkallar ett ljussken. Det befriar de plågade vattnen och gör det möjligt att tala med en Minor Manifestation of Water.",al={"vad är call of water","call of water westfall","vattenuppdrag i westfall"}},{q="Var finns Minor Manifestation of Water?",a="Minor Manifestation of Water finns i Westfall. Den visar sig när de korrumperade andarna i närheten har kuvats och skingrats, redo att tala med dem som hjälpte vattnen.",al={"var finns minor manifestation of water","manifestationens plats","vattenande westfall"}},{q="Vad händer när de korrumperade andarna renas?",a="När besvärjelsen fullbordas bryter ett strålande ljus fram och skingrar de korrumperade andarna. Deras besmittade essens löses upp och sprids som aska, medan vattnet fräser till och blir mild dimma.",al={"vad händer under ritualen","korrumperade andar call of water"}},{q="Har landet återställts helt när uppdraget är klart?",a="Den omedelbara korrumperingen har drivits tillbaka och avtar, men elementaren varnar för att livskraften fortsätter att minska. Det långvariga skyddet av livet ligger i dödligas händer.",al={"är korrumperingen borta","räddade vi vattnet"}},{q="Vem kallas in för att hjälpa manifestationen?",a="Uppdraget erkänner spelarens kall och tackar deras klass för att de träder fram, renar andarna och tar på sig ansvaret att skydda det liv som håller på att sina.",al={"vem kan göra call of water","klasskrav för vattenuppdrag"}},{q="Varför korrumperades vattenandarna i Westfall?",a="Korrumperade andar har stört de naturliga vattnen i Westfall. Även om besmittelsens exakta ursprung är oklart, suger andarnas onda närvaro direkt livskraften ur området.",al={"varför är vattnet korrumperat i westfall","vattenproblem i westfall"}}},fp="13,260,28.310.0,20.273.0,22.214.0,52.181.0,53.184.0,53.168.0,47.177.0,49.195.0"}
P.entries["quest:94505"] = {n="Call of Water",s="Call of Water är en elementär övergångsrit där shamaner lär sig att kommunicera med vattenandar och använda deras läkande krafter. Genom att hämta en Shard of Water från Westfall åt Norric Lochthane i Loch Modan visar de sin hängivenhet och får sin Water Totem.",h="Call of Water är en elementär övergångsrit där shamaner lär sig att kommunicera med vattenandar och använda...",kw={"call of water","loch modan","norric lochthane","shaman","shard of water","water totem","westfall"},ang={["class:Shaman"]="Den här prövningen är en grundläggande övergångsrit som ger en shaman gemenskap med vattenandarna och deras Water Totem för att läka och upprätthålla liv.",["faction:Alliance"]="Till skillnad från Hordens shamaner i Kalimdor vänder sig alliansanslutna invigda till mentorer som Norric Lochthane i Loch Modan och genomgår prövningar på platser som Westfall."},sec={{t="Vattnets väg",b="Call of Water är en viktig andlig prövning där shamaner knyter band till vattenelementet. De invigda får i uppdrag att resa till Westfall och återvända till Norric Lochthane i Loch Modan med Shard of Water. Genom att visa sin förståelse för vattnets livgivande väsen och dess roll i att rena korruption förtjänar shamanerna sin Water Totem och tar ett viktigt steg på sin elementära resa."},{t="Livets givare",b="Prövningen förmedlar en grundläggande elementär sanning: vatten är liv, och korruption gör slut på livet. Shamaner har fått i uppgift att använda vattnets läkande styrka för att skydda de utsatta och bevara levande varelser. Som mentor Norric Lochthane konstaterar när han tar emot Shard of Water sträcker sig vattnets rena gåvor långt bortom enkel fysisk läkning och omfattar uthållighet, förnyelse och andlig balans."}},faq={{q="Vem är Norric Lochthane?",a="Norric Lochthane är en shamansk mentor i Loch Modan. Han vägleder de invigda genom deras prövningar så att de förstår vattenandarna, prövar deras beslutsamhet med en resa till Westfall och ger dem deras Water Totem när de överlämnar bevis på sin gemenskap med vattnet.",al={"vem är norric lochthane","vem ger water totem","norric i loch modan"}},{q="Vad är Shard of Water?",a="Shard of Water är det fysiska bevis som förs tillbaka från Westfall till Norric Lochthane i Loch Modan. Den visar att den invigde har kommunicerat med vattnet, förstått dess livgivande natur och lärt sig bekämpa korruption.",al={"vad är shard of water","användning av shard of water","shard of water uppdragsföremål"}},{q="Varför går prövningen till Westfall?",a="De invigda skickas till Westfall för att förstå vattnets livgivande kraft och hur korruption hotar den. Även små segrar i det oroliga landet väger tungt när den invigdes förmåga att skydda liv ska visas.",al={"varför åka till westfall","vattenuppdrag i westfall","resan till westfall i call of water"}},{q="Vad betyder vattentotemen?",a="Water Totem förkroppsligar en shamans band till vattenelementet. Den är främst känd för att lindra och läka sår med rent vatten, men dess andliga gåvor sträcker sig långt bortom grundläggande läkning och omfattar bevarande och livskraft.",al={"vad gör water totem","varför behöver shamaner water totem","water totems berättelse"}},{q="Vilken lärdom ger prövningen om vatten?",a="Den elementära filosofi som lärs ut under prövningen betonar att vatten ger liv, medan korruption hejdar det. En shaman har fått i uppgift att använda vattnets elementära kraft för att vårda, skydda och återställa balansen där korruption hotar levande varelser.",al={"vad betyder vatten är liv","call of water filosofi","shamanernas vattenlära"}},{q="Vad händer när Call of Water är avklarad?",a="Norric Lochthane påpekar att en invigdes nästa elementära prövning inte kommer med detsamma. Han uppmuntrar shamaner att ta sig tid att öva och utforska vattnets djupare mysterier innan de antar fler prövningar.",al={"vilken prövning kommer härnäst","nästa shamanprövning","vad händer efter call of water"}}},fp="13,280,17.421.0,13.413.0,24.261.0,27.224.0,36.217.0,44.236.0,45.252.0,46.207.0"}
P.entries["quest:94568"] = {n="The Cult's True Plans",s="The Cult's True Plans handlar om följderna av en kultavhoppares för tidiga död. När informatören är död och hans hemligheter gått förlorade måste utredarna rådfråga Talaanis Shadowsong för att utarbeta en ny strategi mot kulten.",h="The Cult's True Plans handlar om följderna av en kultavhoppares för tidiga död.",kw={"kult","avhoppare","fredsbevarare","talaanis shadowsong","the cult's true plans","förrädare"},sec={{t="En tystad avhoppare",b="En insider lämnade kulten när han blev skräckslagen av dess förestående planer och hoppades få hjälp utifrån. Tragiskt nog dödades avhopparen innan han hann berätta vad han visste, och lämnade bara illavarslande varningar efter sig utan några konkreta uppgifter om vad kulten tänker släppa lös."},{t="En ny strategi",b="När deras främsta informatör är död måste ledningen rådfråga Talaanis Shadowsong för att ompröva sin strategi. Att möta kulten i en öppen konfrontation med fredsbevarare bedöms vara en förlorad strid, så de som utreder hotet måste hitta en annan väg framåt."}},faq={{q="Vem var avhopparen som nämns i det här uppdraget?",a="En avhoppare från kulten sökte hjälp när han blev skräckslagen av vad kulten än planerade. Tyvärr dödades han innan han kunde avslöja detaljerna om deras planer, och tog med sig sin värdefulla information i graven.",al={"vem dog i the cult's true plans","vem är den döde avhopparen","kultavhopparens hemligheter"}},{q="Vem är Talaanis Shadowsong?",a="Talaanis Shadowsong är den viktiga kontakt som rådfrågas om hur man ska gå vidare mot kulten efter informatörens plötsliga död. Du bevittnar ett strategiskt samtal med Talaanis för att komma fram till nästa handlingsplan.",al={"talaanis shadowsongs roll","vem är talaanis shadowsong","tala med talaanis"}},{q="Varför kan fredsbevararna inte bara anfalla kulten direkt?",a="Att skicka in fredsbevarare i en öppen strid mot kultens styrkor anses vara alldeles för riskabelt, eftersom fredsbevararna inte väntas klara sig väl i en frontalkrock. En mer subtil eller alternativ strategi krävs i stället.",al={"varför inte strida mot kulten","fredsbevarare mot kult","direkt anfall mot kulten"}},{q="Vad är kultens verkliga planer?",a="Kultens exakta planer är höljda i dunkel eftersom informatören dog innan han hann berätta vad han visste. Vad deras mål än är var det skrämmande nog för att få en medlem att desperat lämna kulten.",al={"vad planerar kulten","kultens planer","vad betyder the cult's true plans"}},{q="Vad är nästa steg efter samtalet med Talaanis?",a="När ledningen har insett att en öppen strid inte är aktuell och att deras främsta underrättelsekälla är död måste den utarbeta en alternativ metod för att avslöja och motverka kultens planer.",al={"vad händer efter the cult's true plans","nästa steg i kultuppdraget"}},{q="Vad händer under The Cult's True Plans?",a="Du talar med Talaanis Shadowsong och bevittnar ett rådslag om situationen. Samtalet kretsar kring följderna av informatörens död och varför vanliga militära styrkor inte kan förväntas stoppa kulten.",al={"sammanfattning av uppdraget the cult's true plans","vad gör man i the cult's true plans"}}},fp="21,224,19.279.0,23.278.1,45.215.0,27.228.0,55.235.0,33.221.0,51.196.0,42.219.0"}
P.entries["quest:94616"] = {n="Water Sapta",s="Water Sapta är en ceremoniell dryck som stämmer ens andliga syn med vattnets dolda andar och fördärv. Bäraren får i uppdrag att hitta förorenat dammvatten på Westfalls fält och undersöka en elementär obalans.",h="Water Sapta är en ceremoniell dryck som stämmer ens andliga syn med vattnets dolda andar och fördärv.",kw={"elementär stämning","sapta","schamanprövning","förorenat damm","water sapta","vattenandar","westfall"},ang={["class:Shaman"]="En sapta är en alkemisk eller rituell dryck som schamaner använder för att stämma sina andliga sinnen med elementandar som inte syns för vanliga ögon.",["faction:Alliance"]="När fördärvat vatten i Westfall undersöks förs elementära reningsriter till hjärtat av ett alliansrike."},sec={{t="Vattnets syn",b="I shamankonstens elementtraditioner är en sapta en ceremoniell brygd som bereder vägen genom slöjan mellan den fysiska världen och andarna. Water Sapta stämmer sinnena specifikt med vattenelementet och ger den andliga syn som krävs för att uppfatta elementära störningar och dolda andar. Utan en sådan stämning kan vanliga resenärer se rakt på en elementaruppenbarelse utan att urskilja mer än vanliga krusningar."},{t="Störningar i Westfall",b="Uppdraget med Water Sapta skickar bäraren till Westfall, ett torrt alliansrike präglat av oro och försummelse. I detta vindpinade land finns ett förorenat damm vars vatten lider av andlig förorening. Med hjälp av saptans förmåga att skärpa sinnena måste bäraren söka upp det fördärvade vattnet för att upptäcka störningen och återställa harmonin bland de lokala vattenandarna."}},faq={{q="Vad är Water Sapta?",a="En vattensapta är en särskild andlig brygd som skapats för att schamaner ska kunna samverka med elementen. När man dricker eller använder en sapta öppnas sinnena tillfälligt för elementarväsen och andliga obalanser som annars är dolda för dödliga.",al={"vad är water sapta","water saptas syfte","vad gör water sapta"}},{q="Var finns det förorenade dammet i Westfall?",a="Det förorenade dammvattnet finns i Westfall. Schamaner skickas dit med vattensaptan för att hitta fördärvade vattenkällor och ta itu med den andliga störning som frodas i området.",al={"var finns det förorenade dammet","förorenat damm i westfall","förorenat damms läge"}},{q="Varför leder vattensaptan till Westfall?",a="Även i jordbruksbygder och torkdrabbade människoländer som Westfall kan elementärt vatten drabbas av förorening eller mörkt fördärv. Uppdraget går ut på att söka efter förorenat dammvatten och återställa balansen bland de oroliga andar som bor där.",al={"varför åka till westfall","vattenfördärv i westfall","varför är vattnet i westfall förorenat"}},{q="Vem använder vattensaptan?",a="Vattensaptor anförtros åt schamaner som genomgår prövningar i samverkan med elementen. Genom att ta del av saptan stämmer utövaren sina sinnen med vattenandar och kan uppfatta dolda elementarväsen eller undersöka förorenade dammar.",al={"vem dricker water sapta","vem använder water sapta","schaman dricker sapta"}},{q="Vad händer när du tar saptan till det förorenade dammet?",a="När du använder vattensaptan nära det förorenade dammet i Westfall får du elementär syn, som avslöjar vattnets andliga tillstånd eller kallar fram dolda andar knutna till den lokala vattenprövningen.",al={"vad händer efter att sapta används","sapta och elementär syn"}},{q="Hur fungerar elementära saptor i schamantraditionen?",a="Saptor förenar jordnära ingredienser med elementära välsignelser i en ceremoniell dryck. Schamaner förlitar sig på dem under sina prövningar för att stämma sig med specifika element — jord, eld, vatten eller luft — och överbrygga klyftan mellan den fysiska världen och andevärlden.",al={"hur fungerar saptor","sapta-lore"}}},fp="11,274,23.457.0,23.371.0,22.247.0,38.224.0,42.260.0,25.232.0,58.191.0,51.250.0"}
P.entries["quest:947"] = {n="Cave Mushrooms",s="Cave Mushrooms är ett uppdrag från Alliansen som ges av nattalven Barithras Moonshade i Auberdine. När han tar fram en specialblandning skickar Barithras en äventyrare till en dold grotta bakom Cliffspring Falls för att samla sällsynta svampar och undersöka oroande föraningar från Grove of the Ancients.",h="Cave Mushrooms är ett uppdrag från Alliansen som ges av nattalven Barithras Moonshade i Auberdine.",kw={"auberdine","barithras moonshade","cave mushrooms","cliffspring falls","darkshore","death cap","grove of the ancients","onu","scaber stalks"},ang={["faction:Alliance"]="Auberdine är Alliansens främsta fäste längs Kalimdors kust, och växande ondska i de östra bergen hotar hela kustens trygghet direkt.",["profession:Herbalism"]="Samlare och örtkunniga uppskattar jakten på death cap och scaber stalks, även om de här exemplaren växer i mörka grottor i stället för i frodig skogsmark.",["race:NightElf"]="Grove of the Ancients är fortfarande djupt förbundet med Darkshores naturliga balans, så varje störning de känner av under fallen är mycket oroande."},sec={{t="Ett recept bakom fallen",b="Barithras Moonshade behöver särskilda ingredienser till en kraftfull blandning: scaber stalks och en svårfunnen death cap. De här svamparna trivs i den fuktiga, skuggiga grottan som ligger dold precis bakom Cliffspring Falls i nordöstra Darkshore. Själva alkemin är krävande, men det är betydligt farligare att samla exemplaren än att plocka vanliga skogsörter."},{t="De äldstes varning",b="Barithras undvek inte grottan av ren lättja. De vördnadsvärda trädväktarna i Grove of the Ancients utfärdade stränga varningar, eftersom de kände att en otäck närvaro hade börjat slå sig ner i bergsgrottorna. Genom att skicka en tålig utforskare i stället för att undersöka saken själv vill Moonshade ta reda på om de äldstes dystra föraningar om en krypande ondska i norra Darkshore verkligen stämmer."}},faq={{q="Var börjar uppdraget?",a="Du får uppdraget av Barithras Moonshade, som bor i nattalvernas kustbosättning Auberdine i centrala Darkshore.",al={"var hämtar man cave mushrooms","var finns barithras moonshade","var börjar uppdraget cave mushrooms"}},{q="Var finns svamparna?",a="De växer i en grotta dold bakom Cliffspring Falls, längs bergssidan nordost om Auberdine.",al={"var finns scaber stalks","var finns death cap","grottan bakom vattenfallet i darkshore"}},{q="Varför hämtar inte Barithras Moonshade svamparna själv?",a="Grove of the Ancients rådde uttryckligen Barithras att hålla sig borta från fallen. De stora trädväktarna kände att en onaturlig, växande ondska hade tagit sin tillflykt i grottan.",al={"varför går barithras inte dit","varför stannar barithras i auberdine"}},{q="Vilka svampar behövs?",a="Moonshade behöver fem scaber stalks och en enda mycket farlig death cap-svamp för att färdigställa sin brygd.",al={"svampar som behövs","vilka svampar behöver moonshade"}},{q="Vart leder ärendet sedan?",a="När närvaron i grottan har bekräftats och svamparna levererats går färden söderut till den uråldriga beskyddaren Onu i Grove of the Ancients.",al={"nästa uppdrag efter cave mushrooms","fortsättningsuppdrag från onu"}},{q="Varför oroar sig de äldste för Cliffspring Falls?",a="Grove of the Ancients varnade Barithras för att en växande ondska kan lura i grottan bakom fallen. Han ber en resenär att samla svampar och undersöka varningen.",al={"de äldstes varning om cliffspring falls","varför utforska grottan"}}},fx={a048db56={q="Varför vill Barithras Moonshade att detta ska göras?",a="Barithras Moonshade är örtalchemist och brygger en kraftfull ny brygd som kräver sällsynta svampar från grottan bakom Cliffspring Falls. Men han har också en djupare oro utöver sitt alkemiska arbete: Grove of the Ancients varnade honom för att ett växande ont lurar i just den grottan. Genom att skicka dig för att samla ingredienser hoppas han också få veta om de uråldriga väktarnas mörka förebud stämmer.",al={"varför vill barithras ha grottsvampar","barithras moonshades motiv","varför samla svamp åt barithras"}},["991c4c10"]={q="Vad ska Death Cap användas till?",a="Death Cap är en ytterst sällsynt och kraftfull giftig svamp som växer i grottan bakom Cliffspring Falls. Barithras Moonshade behöver ett oskadat exemplar som en viktig ingrediens i en specialbrygd han tillverkar i Auberdine.",al={"vad används death cap till","vad death cap-svampen är till för","varför behöver barithras death cap"}},be6516db={q="Vad ska Scaber Stalk användas till?",a="Scaber Stalk är sällsynta svampar som frodas i den fuktiga, skuggiga grottan bakom Cliffspring Falls. Barithras Moonshade behöver fem stycken till sina pågående alkemiska brygder, tillsammans med den kraftfulla Death Cap.",al={"vad scaber stalk används till","vad scaber stalk-svampen är till för","varför behöver barithras scaber stalk"}}},fp="14,207,25.241.0,21.271.1,27.131.0,32.111.0,61.156.0,35.87.0,35.140.0,55.161.1"}
P.entries["quest:94792"] = {n="Taming the Beast",s="Taming the Beast är ett första prov där blivande äventyrare lär sig konsten att lugna och knyta band till vilda djur. Under Josephine Carsons ledning tar noviser med sig en Taming Rod in i skogen för att tämja en Rockhide Boar och öva på viktiga överlevnadsfärdigheter. Uppgiften visar att det är mycket lättare att överleva i karga trakter med ett lojalt djur vid sin sida, så länge man värnar om naturens känsliga balans.",h="Taming the Beast är ett första prov där blivande äventyrare lär sig konsten att lugna och knyta band till...",kw={"djurföljeslagare","naturens balans","djurträning","jägarens husdjur","josephine carson","rockhide boar","taming rod","taming the beast"},ang={["class:Druid"]="Druider håller inte djur på samma sätt som jägare, men uppdragets betoning på att värna naturens känsliga balans speglar grundläggande druidlära. Att bemöta skogens djurliv varsamt och återhållsamt värnar den naturliga jämvikt som druiderna svurit att skydda.",["class:Hunter"]="För jägare är konsten att tämja vilda djur en avgörande övergångsrit som i grunden förändrar hur de överlever i vildmarken. En lojal följeslagare ger viktigt skydd och vaksamhet i strid och skapar ett varaktigt partnerskap mellan spårare och djur."},sec={{t="Att knyta band till djur",b="För många som strövar genom vildmarken innebär en ensam färd genom otämjda områden en inbjudan till fara. Ett djur ger inte bara kraftfullt skydd i strid, utan också troget sällskap under långa och krävande resor. Att lära sig knyta ett sådant band är en viktig milstolpe för varje blivande jägare eller spårare. Under Josephine Carsons ledning får nybörjare en särskild Taming Rod och uppmanas att söka upp en Rockhide Boar i skogen. Att lugna och styra en sådan varelse är ett grundläggande prov som visar om en resenär har det fokus och lugn som krävs för att leda ett djur utan att ge vika för rädsla eller framkalla onödig blodsutgjutelse."},{t="Naturens balans",b="Att bemästra vilda djur medför ett stort etiskt och ekologiskt ansvar. Som Josephine Carson påminner sina elever får det aldrig slå över i hänsynslös exploatering att ta djur i sin tjänst, eftersom naturens balans är skör och alltid måste värnas. Tämjandet handlar inte om grymhet eller dominans, utan om att skapa harmoni och disciplin mellan djur och herre. Med den förtrollade staven kan en nybörjare tryggt öva på att hantera en mäktig varelse som en Rockhide Boar utan att för gott utarma det lokala djurlivet. När grunderna i att styra och lugna djuret väl sitter lämnas staven tillbaka, vilket visar att respekten för naturens ordning går före stoltheten."}},faq={{q="Vad är syftet med uppdraget Taming the Beast?",a="Uppdraget är en viktig övning för äventyrare som vill knyta band till vilda varelser. Under Josephine Carsons ledning lär sig nybörjare att närma sig och lugna en vild Rockhide Boar med hjälp av en särskild Taming Rod. Övningen visar blivande jägare hur ett djur kan hjälpa dem att överleva i vildmarken och betonar samtidigt vikten av att respektera naturens balans.",al={"uppdraget taming the beast","vad är taming the beast","jägarens husdjursuppdrag"}},{q="Vem är Josephine Carson?",a="Josephine Carson är en mentor som lär äventyrare den känsliga konsten att ta hand om djur. Hon ger dem en Taming Rod och låter eleverna öva sina färdigheter på en Rockhide Boar i den närliggande skogen. Josephine betonar att det krävs tålamod, övning och medvetenhet om naturens känsliga balans för att lära sig arbeta tillsammans med djur.",al={"josephine carson","vem ger taming the beast","uppdragsgivare för taming rod"}},{q="Vad används Taming Rod till?",a="Taming Rod är ett särskilt redskap som Josephine Carson tillhandahåller för djurträning. Äventyrare tar staven med sig in i skogen för att lugna och tämja en vild Rockhide Boar. Den låter nybörjare tryggt öva på att styra ett djur utan att orsaka bestående skada på det lokala djurlivet, och måste lämnas tillbaka till Josephine när provet är avklarat.",al={"taming rod","vad gör taming rod","hur använder man taming rod"}},{q="Varför behöver jägare djur?",a="Att färdas ensam genom vildmarkens faror utsätter resenärer för stora risker och bakhåll. Ett djur erbjuder pålitligt skydd, vaksamhet och kraftfull hjälp i strid, vilket gör farliga situationer mycket lättare att uthärda. Ett lojalt djur är både en kraftfull försvarare i främsta ledet och en pålitlig följeslagare under långa och farofyllda expeditioner genom otämjda trakter.",al={"varför skaffa ett husdjur","fördelar med djurföljeslagare","varför tämja djur"}},{q="Vilken varelse måste tämjas under det här provet?",a="Provet kräver att äventyrare ger sig in i skogen och tämjer en Rockhide Boar med den Taming Rod de fått. Dessa kraftiga djur är ett utmärkt test av grundläggande färdigheter i djurhantering och lär resenärer att behålla lugn och disciplin när de möter aggressiva vilda djur. Därefter ska de återvända och rapportera sina framsteg till Josephine Carson.",al={"vilken galt ska jag tämja","mål för rockhide boar","varelse i taming the beast"}},{q="Varför betonar Josephine Carson naturens balans?",a="Josephine Carson varnar för att vilda djur alltid måste betvingas med försiktighet och respekt, aldrig av girighet eller med våld. Naturens ordning är skör, och hänsynslös störning av det lokala djurlivet eller misshandel av varelser rubbar den ekologiska balansen. Att verkligen bemästra djur kräver förståelse för och respekt för deras plats i ekosystemet, inte att behandla dem som förbrukningsbara verktyg.",al={"naturens balans betydelse","naturens balans vid tämjande","varför respektera naturen"}}},fp="16,430,19.689.0,21.716.0,50.399.0,24.376.0,32.354.0,38.377.0,46.356.0,58.402.0"}
P.entries["quest:94793"] = {n="Training the Beast",s="Training the Beast är ett grundläggande uppdrag för unga jägare som skickar dem till den erfarne skogsmannen Isaac Chan i Goldshire. Genom att slutföra uppdraget lär sig jägarna att träna, utfodra och återuppliva sina djurkamrater på rätt sätt, så att ett nyss tämjt vilddjur blir en trogen stridspartner.",h="Training the Beast är ett grundläggande uppdrag för unga jägare som skickar dem till den erfarne skogsmannen...",kw={"elwynn forest","utfodra husdjur","goldshire","jägarens husdjur","isaac chan","träning av husdjur","återuppliva husdjur","training the beast","skogsman"},ang={["class:Hunter"]="Uppdraget är en viktig övergångsrit för jägare under utveckling. De går från att bara fånga vilddjur till att skapa ett varaktigt, disciplinerat band genom att utfodra, återuppliva och träna dem.",["faction:Alliance"]="Alliansens jägare i Elwynn Forest förlitar sig på erfarna skogsmän som Isaac Chan i Goldshire för att bemästra grunderna i att hantera vilddjur."},sec={{t="Jaktens ansvar",b="Att lära sig tämja ett vilt djur är bara det första steget för en blivande jägare. En varaktig samhörighet kräver disciplin och kunskap. Uppdraget skickar nybörjarjägare till den erfarne skogsmannen Isaac Chan i Goldshire för att lära sig grunderna i att träna djur. Utan rätt vägledning förblir ett tämjt djur ett bångstyrigt vilddjur i stället för en pålitlig bundsförvant i vildmarken."},{t="En skogsmans vägledning",b="När jägarna anländer till Goldshire lär Isaac Chan dem färdigheterna som behövs för att ta hand om en djurkamrat. Undervisningen omfattar mer än enkla stridskommandon. Den tar också upp det viktiga ansvaret att utfodra kamraten så att den mår bra och att lära sig hur man återupplivar den om den stupar i strid. Chan påminner sina elever om att makt över vilda djur också innebär ett ansvar att respektera naturens balans och leva med vördnad inför världen omkring oss."}},faq={{q="Vem är Isaac Chan?",a="Isaac Chan är en erfaren skogsman som har bott i Goldshire i Elwynn Forest hela sitt liv. Han är respekterad för sin djupa kunskap om vilda djur och överlevnad i vildmarken, och lär nybörjarjägare hur de tar hand om, leder, utfodrar och återupplivar sina djurkamrater samt lär dem nya förmågor.",al={"vem är isaac chan","djurtränare i goldshire","isaac chans bakgrund"}},{q="Vad är syftet med Training the Beast?",a="En jägare kanske redan vet hur man tämjer ett vilddjur, men det här uppdraget ger kunskapen som behövs för att bevara bandet. Det lär jägaren att utfodra sin kamrat, återuppliva den om den stupar i strid och lära den nya stridsförmågor.",al={"vad gör uppdraget","varför träna vilddjur","syftet med training the beast"}},{q="Var hittar man Isaac Chan?",a="Isaac Chan finns i Goldshire, den centrala orten i Elwynn Forest, strax söder om Northshire Valley och sydväst om Stormwind City.",al={"var finns isaac chan","var lämnar jag in uppdraget","isaac chans plats"}},{q="Vilka färdigheter lär Isaac Chan ut?",a="Isaac Chan lär ut grunderna i skötsel och träning av husdjur. Det innebär att utfodra ditt vilddjur så att det mår bra, återuppliva det om det stupar i strid och lära det nya förmågor medan det växer tillsammans med dig.",al={"vilka färdigheter får man","inlärda husdjursförmågor","vad lär isaac chan ut"}},{q="Varför påminner Isaac Chan jägarna om att respektera naturen?",a="Isaac Chan betonar att det krävs ödmjukhet, inte dominans, för att bemästra vilda djur. Han uppmanar jägarna att värna naturens balans och leva med vördnad inför naturen omkring dem, så att bandet mellan jägare och vilddjur bygger på omsorg snarare än utnyttjande.",al={"varför respektera naturen","jägare respektera naturens balans"}},{q="Vem kan utföra uppdraget?",a="Training the Beast är särskilt utformat för jägare som har lärt sig att tämja vilddjur och behöver disciplinen från skogarna för att ta hand om och träna en djurkamrat.",al={"vem kan göra uppdraget","är training the beast bara för jägare"}}},fp="18,301,32.424.0,21.438.0,18.272.0,42.244.0,30.138.0,34.223.0,53.293.0,26.192.0"}
P.entries["quest:948"] = {n="Onu",s="Det här ärendet leder resenärer söderut från Auberdine mot Grove of the Ancients för att rådgöra med Onu. Dina fynd i grottan bakom Cliffspring Falls har väckt en av Darkshores äldsta väktares brådskande intresse.",h="Det här ärendet leder resenärer söderut från Auberdine mot Grove of the Ancients för att rådgöra med Onu.",kw={"ancient of lore","auberdine","barithras moonshade","cliffwater falls","darkshore","grove of the ancients","onu"},ang={["class:Druid"]="Druider vördar Ancients som naturens visdom förkroppsligad. Att på Onus uppdrag undersöka märklig växtlighet i grottorna stämmer väl överens med Cenarion Circles uppgifter.",["faction:Alliance"]="För Alliansens resenärer som hjälper till att trygga Darkshore är det avgörande att vinna de lokala uråldrigas förtroende och ta del av deras insikter för att kunna ta sig fram i Kalimdors gåtfulla norra vildmark.",["race:NightElf"]="Ancients of Lore är heliga bundsförvanter till Kaldorei och har väglett ditt folk sedan före Sunderingen. Att besvara Onus kallelse är en högtidlig plikt för att bevara Darkshores helgd."},sec={{t="En kallelse från de uråldriga",b="När Barithras Moonshade återvänder till Auberdine med svampprover från Cliffspring Falls djup inser han att saken handlar om långt mer än botanisk nyfikenhet. Ryktet om de fördärvade grottorna når snabbt Onu, en Ancient of Lore med rötter i den fridfulla tillflyktsorten Grove of the Ancients söder om staden. De uråldriga trädväktarna är tålmodiga och eftertänksamma av naturen, men Onus omedelbara önskan att rådgöra visar att fördärvet i Darkshores vattendrag kan ha samband med urgamla, oroande krafter."},{t="Färden till lunden",b="När du följer vägen söderut från Auberdine lämnar du kustens ruiner bakom dig och färdas inåt landet mot bergssluttningarna. Grove of the Ancients är en uråldrig tillflyktsort för naturen, till stor del skyddad från det krypande förfall som plågar kusten. Här väntar Onu bland höga stengravar och besläktade andar, redo att leda sina bundsförvanter mot djupare och mer skrämmande farsoter som vaknar vid vildmarkens gräns."}},faq={{q="Vem är Onu?",a="Onu är en Ancient of Lore, en väldig, tänkande trädväktare som samlar in och bevarar kunskap. Han vakar över Grove of the Ancients i södra Darkshore och erbjuder landets försvarare visdom och vägledning.",al={"vem är onu","onus identitet","vad är onu"}},{q="Varför vill Onu tala med mig?",a="Du begav dig nyligen in i grottorna under Cliffspring Falls för att samla svampprover åt Barithras Moonshade. Det märkliga som upptäcktes där oroade naturforskarna, så Onu bad att få träffa dig för att tala om det växande fördärvet.",al={"varför kallar onu","anledning till samtalet","varför gå till onu"}},{q="Var ligger Grove of the Ancients?",a="Grove of the Ancients ligger söder om Auberdine, vid foten av den östra bergskedjan. Följ huvudvägen söderut genom Darkshore och ta dig österut mot bergssluttningarna för att hitta Onu.",al={"onus plats","var ligger grove of the ancients","hur hittar man onu"}},{q="Vad är en Ancient of Lore för slags varelse?",a="Ancients of Lore är urgamla treanter som står på nattalvernas och Cenarion Circles sida. De vördas för sin djupa visdom och sitt minne och tjänar som levande förvarare av naturmagi och historiska hemligheter.",al={"ancient of lore","vad är onu för varelse","treant eller ancient"}},{q="Varför är Onus kallelse så brådskande?",a="Ancients är kända för sitt långsamma och eftertänksamma sätt och handlar sällan i hast. Som Barithras Moonshade påpekar måste hotet mot Darkshore vara allvarligt om en så tålmodig och metodisk varelse som Onu aktivt kallar dig till ett rådslag.",al={"varför så brådskande","är onu orolig","barithras varning"}},{q="Vad händer efter mötet med Onu?",a="När Onu hälsar dig välkommen till Grove of the Ancients ber han dig hjälpa till att undersöka ett långt mörkare hot längre söderut längs kusten: den illavarslande utgrävningen kring The Master's Glaive.",al={"nästa uppdrag efter onu","vad händer sedan","vart skickar onu dig"}}},fx={be40e913={q="Varför skickar Barithras Moonshade mig till Onu?",a="Barithras vet att de uråldriga vishetsväktarna besitter djup kunskap om landets förruttnelse, och Onu har själv uppmärksammat det du hittade i grottan vid Cliffspring Falls. Eftersom en uråldrig väktare sällan hör av sig om inte Darkshore hotas av en allvarlig och omedelbar fara, uppmanar Barithras dig att genast hörsamma kallelsen.",al={"barithras motiv","varför skicka mig till onu","varför vill barithras att detta ska göras"}}},fp="3,169,27.424.0,20.337.0,11.196.0,35.197.0,35.190.0,44.178.0,39.130.0,34.174.1"}
P.entries["quest:94863"] = {n="Taming the Beast",s="Taming the Beast är en jägarlektion under Josephine Carsons ledning. Efter att ha lärt sig grunderna i att hantera djur med ett vildsvin måste den blivande jägaren vinna en vildare Gray Forest Wolfs förtroende med en Taming Rod.",h="Taming the Beast är en jägarlektion under Josephine Carsons ledning.",kw={"tämja bestar","gray forest wolf","jägare","jägarträning","josephine carson","taming rod","taming the beast"},ang={["class:Hunter"]="Den här träningen är en viktig övergångsrit för jägare och lär ut det tålamod och den respekt som krävs för att komma i samklang med vilda rovdjur."},sec={{t="Jägarens väg",b="En jägares band till det vilda kräver mer än att bara spåra och skjuta; det fordrar respekt och tålamod för att vinna ett vilt djurs förtroende. Efter att ha visat sina grundläggande färdigheter med vanliga vildsvin ställs blivande jägare inför en betydligt vildare utmaning: att ge sig in i skogen och tämja en Gray Forest Wolf. Under tränaren Josephine Carsons vakande öga får jägaren en förtrollad stav som ska lugna rovdjuret och lära jägaren den känsliga balansen mellan jägare och best."},{t="Ett prov på instinkt och tillit",b="Josephine Carson ger jägaren en särskild Taming Rod, utformad för att kanalisera ett lugnande inflytande så att jägaren kan närma sig farliga vilda djur. Uppgiften kräver tålamod och precision, eftersom vargen måste närmas utan dödligt våld samtidigt som dess naturliga aggressivitet stillas varsamt. När bandet har övats in och jägaren visat sig kunna samspela med bestens själ, lämnas staven tillbaka till Josephine som bevis på växande färdighet i att bemästra det vilda."}},faq={{q="Vad är uppdraget Taming the Beast?",a="Taming the Beast är ett träningsprov för jägare där en tränare ger en blivande jägare i uppgift att spåra upp och tämja en Gray Forest Wolf med hjälp av en förtrollad Taming Rod.",al={"uppdraget taming the beast","uppdrag med gray forest wolf","lektion i att tämja varg"}},{q="Vem ger uppdraget och vem slutför det?",a="Josephine Carson är instruktör för provet. Hon ger dig Taming Rod och bedömer ditt band till skogens djur innan hon tar tillbaka staven när du är klar.",al={"vem ger taming the beast","vem är josephine carson","var lämnar man in taming the beast"}},{q="Vilket djur måste du tämja?",a="Du får i uppgift att tämja en Gray Forest Wolf, en vildare skogspredator än de vildsvin du tränade med tidigare.",al={"vad ska jag tämja","vilken best","målet med taming the beast"}},{q="Vad används Taming Rod till?",a="Taming Rod är ett träningsredskap som Josephine Carson ger dig för att hjälpa en jägarlärling att lugna och knyta ett tillfälligt band till en vild Gray Forest Wolf utan att skada den permanent.",al={"vad gör taming rod","varför använda taming rod","taming rods bakgrund"}},{q="Vilket djur tämjde jägaren före provet?",a="Innan du mötte Gray Forest Wolf visade du dina grundläggande färdigheter i att hantera djur genom att lära dig tämja ett skogsvildsvin.",al={"tidigare lektion i tämjning","vad tämjdes före vargen"}},{q="Behåller du Gray Forest Wolf som en permanent följeslagare?",a="Nej, provet är en avgränsad lektion i att bemästra konsten att knyta band till djur. När du har övat dina färdigheter lämnar du tillbaka Taming Rod till Josephine Carson.",al={"behåller man vargen","är vargen ett permanent husdjur"}}},fp="16,228,22.510.0,28.478.0,35.164.0,35.178.0,34.125.0,32.191.0,43.131.0,58.174.0"}
P.entries["quest:94864"] = {n="Taming the Beast",s="Taming the Beast är höjdpunkten i jägares tidiga träning i Elwynn Forest, under ledning av Josephine Carson. Efter att ha visat att de behärskar vildsvin och vargar får jägarna i uppgift att använda en Taming Rod för att lugna en Young Forest Bear och vinna dess förtroende. Det här sista provet fördjupar jägarens samhörighet med vilddjuren och bevarar skogens naturliga balans genom respekt och skicklighet.",h="Taming the Beast är höjdpunkten i jägares tidiga träning i Elwynn Forest, under ledning av Josephine Carson.",kw={"samhörighet med vilddjur","träning i att tämja vilddjur","elwynn forest","jägaruppdrag","josephine carson","taming rod","taming the beast","young forest bear"},ang={["class:Hunter"]="Det här provet är en avgörande övergångsrit för jägaraspiranter. Det förvandlar enkla spårningsfärdigheter till en djup, empatisk samhörighet med vilddjuren.",["faction:Alliance"]="Skickliga djurmästare stärker Alliansens spejare i vildmarken med disciplinerade följeslagare som kan försvara gårdar och patrullera handelsvägar i Stormwinds områden.",["race:Human"]="För mänskliga jägare som tränar i Elwynn Forest lär tämjandet av traktens vilda djur dem att det är viktigt att samexistera med kungarikets naturliga rovdjur i stället för att bara utrota dem."},sec={{t="Jaktens sista prov",b="Blivande jägare i Elwynn Forest genomgår en krävande träning för att förstå de vilda djur som delar deras marker. Efter att redan ha visat att de kan hantera den listiga vargen och det tåliga vildsvinet ställs jägarna inför ett sista prov på mod och tålamod. Josephine Carson skickar dem för att möta Young Forest Bear, den kraftigaste och mäktigaste av skogens vanliga rovdjur. Den här riten prövar om en jägare kan stå emot björnens råa styrka och vinna dess förtroende i stället för att bara kuva den."},{t="Respekt och balans i Elwynn",b="Lärdomen bakom att tämja djurlivet i Elwynn bygger på respekt, inte herravälde. Skogsbjörnar står för skogens styrka och livskraft och spelar en viktig roll för att upprätthålla den naturliga ordningen. Med en särskilt förberedd Taming Rod lär sig jägarna att stilla vilddjurets aggressivitet och skapa ett äkta band av ömsesidig förståelse. Att lugna ett så mäktigt djur fördjupar jägarens andliga samhörighet med vildmarken och fullbordar grundutbildningen under Carsons ledning."}},faq={{q="Vem ger jägarna det här provet?",a="Josephine Carson ansvarar för det här provet för jägare som tränar i Elwynn Forest. Hon bedömer jägarens framsteg när de har tämjt mindre vilddjur och ger dem vägledning och den Taming Rod som behövs för att tämja skogsbjörnen. När provet är avklarat återlämnar jägarna staven direkt till henne som bekräftelse på att träningen är slutförd.",al={"vem ger taming the beast","uppdragsgivare för taming the beast","josephine carson uppdrag"}},{q="Vilka vilddjur måste tämjas före det här provet?",a="Innan jägarna tar sig an utmaningen att tämja en Young Forest Bear måste de först visa sin skicklighet och sitt tålamod genom att tämja ett vildsvin och en varg. De inledande proven visar att jägaren kan hantera både aggressiva och flocklevande vilddjur innan de möter Elwynns björnars råa styrka.",al={"vilddjur som krävs för att tämja","vad tämjde jag före björnen","vilddjur tämjda före detta"}},{q="Varför skickas jägarna efter en Young Forest Bear?",a="Young Forest Bear står för Elwynn Forests djurlivs styrka och mäktighet. Medan vildsvin och vargar prövar jägarens förmåga att hantera snabba eller uthålliga vilddjur, blir björnen det yttersta provet på uthållighet, respekt och fysiskt mod. Att vinna förtroendet hos ett så mäktigt rovdjur visar att jägaren helt behärskar grunderna i att hantera vilddjur.",al={"varför tämja young forest bear","syftet med young forest bear","varför björnar i elwynn"}},{q="Vad är Taming Rod till för?",a="Taming Rod är ett särskilt träningsredskap som Josephine Carson tillhandahåller för att hjälpa jägare att lugna vilda djur. Den samlar det fokus som krävs för att stilla en aggressiv Young Forest Bear utan att döda den, så att jägaren kan knyta ett fredligt band till den. När provet är över återlämnas staven till Carson, och träningen avslutas.",al={"syftet med taming rod","vad gör taming rod","varför använda taming rod"}},{q="Hur hjälper tämjandet Elwynn Forest?",a="Att tämja vilda djur ses som en viktig del av att bevara den naturliga balansen i Elwynn Forest. Genom att närma sig rovdjur med respekt och återhållsamhet i stället för att jaga ner dem hjälper jägarna till att bevara harmonin mellan det lokala ekosystemet och områdets bosättningar, så att farliga vilddjur leds bort på fredlig väg i stället för att dödas.",al={"varför är balansen i elwynn viktig","balansen i elwynn forest","tämjande och skogens balans"}},{q="Vad innebär det för en jägare att klara den här lektionen?",a="Att klara den här sista uppgiften fördjupar jägarens inneboende samhörighet med vilddjuren. Genom att vinna Elwynns mäktigaste varelses förtroende går jägaren bortom enkla jakttekniker och bemästrar den andliga kontakt som krävs för att skapa livslånga band med djurföljeslagare i hela Azeroth.",al={"vad händer efter att björnen tämjts","slutföra jägarträningen","vad innebär samhörighet med vilddjur"}},{q="Var finns Young Forest Bears?",a="Young Forest Bears strövar omkring i de skogsklädda delarna av Elwynn Forest, där de lever bland de täta träden tillsammans med vargar och spindlar. Jägare som ger sig av från närliggande bosättningar måste spåra dessa kraftiga varelser genom skogens snår för att använda tämjningsstaven och fullgöra Carsons sista order.",al={"var finns young forest bear","var hittar man björnar i elwynn","skogsbjörn i elwynn"}}},fp="16,388,27.493.0,29.509.0,34.354.0,49.325.0,47.350.0,38.343.0,42.366.0,54.308.0,35.294.0"}
P.entries["quest:94896"] = {n="Aid For The Refugees",s="Aid For The Refugees handlar om de fördrivna överlevande från Ban'aethal, en bosättning djupt inne i Shadowgale Forest som plötsligt evakuerades mitt i natten. När deras hem började falla upp mot himlen och den omgivande vildmarken blev alltför farlig att beträda, förlitar sig flyktingarna på modiga resenärer som kan hämta tillhörigheterna de tvingades lämna kvar.",h="Aid For The Refugees handlar om de fördrivna överlevande från Ban'aethal, en bosättning djupt inne i...",kw={"aid for the refugees","ban'aethal","tillhörigheter","ealaane","flyktingar","shadowgale forest"},sec={{t="En desperat vädjan",b="Aid For The Refugees är en vädjan om hjälp från Ealaane och hennes medfördrivna bybor. De överlevande flydde med knapp nöd från sina hem djupt inne i Shadowgale Forest och har samlats med nästan ingenting kvar, i hopp om att en resenär på genomfart ska våga möta farorna de lämnade bakom sig."},{t="Ban'aethals katastrof",b="Bosättningen Ban'aethal mötte ett ofattbart öde mitt i natten, när byn plötsligt började falla upp mot himlen. Den bisarra och skrämmande katastrofen gav invånarna bara några ögonblick att fly, så de tvingades överge sina personliga ägodelar medan skogen omkring dem blev fientlig och farlig."}},faq={{q="Vem är Ealaane?",a="Ealaane är en flykting från Ban'aethal som flydde tillsammans med andra när bosättningen började rasa samman. Hon ber äventyrare på väg mot Shadowgale Forest att hämta personliga tillhörigheter som lämnats kvar i ruinerna.",al={"vem gav hjälp till flyktingarna","uppdragsgivare för aid for the refugees","ealaane"}},{q="Vad hände med Ban'aethal?",a="Ban'aethal var en bosättning djupt inne i Shadowgale Forest. Invånarna tvingades nyligen evakuera mitt i natten på grund av en plötslig och bisarr katastrof.",al={"vad är ban'aethal","var ligger ban'aethal","byn ban'aethal"}},{q="Varför var byborna tvungna att evakuera Ban'aethal?",a="Evakueringen utlöstes plötsligt mitt i natten, när Ban'aethal började falla upp mot himlen. Byn och den omgivande skogen blev alltför farliga för invånarna att stanna i eller återvända till.",al={"varför evakuera ban'aethal","faller upp mot himlen","katastrofen i ban'aethal"}},{q="Varför ber byborna att någon hämtar deras tillhörigheter?",a="Katastrofen slog till plötsligt mitt i natten och tvingade byborna att fly för sina liv med nästan ingenting. Nu när skogen och ruinerna är fulla av faror förlitar de sig på dugliga äventyrare för att hämta det som lämnades kvar.",al={"varför behövs tillhörigheterna","övergivna tillhörigheter","varför hämta tillhörigheter"}},{q="Vad är Shadowgale Forest?",a="Shadowgale Forest är det skogsområde där bosättningen Ban'aethal ligger. Efter den bisarra katastrofen som slet sönder byn har skogen blivit extremt farlig för vanligt folk.",al={"var ligger shadowgale forest","shadowgale forests historia"}},{q="Kan flyktingarna återvända hem?",a="Nej. Enligt Ealaane är både Shadowgale Forest och ruinerna av Ban'aethal alltför farliga för att de fördrivna invånarna någonsin ska kunna återvända på egen hand.",al={"kan flyktingarna återvända","är ban'aethal säkert"}}},fp="20,359,16.297.0,26.311.0,15.222.0,28.182.0,50.204.0,66.247.0,26.196.0,39.155.0"}
P.entries["quest:94897"] = {n="The Fate of a Loved One",s="The Fate of a Loved One är ett uppdrag om Resaan, som gav sig in i de farliga Ruins of Ban'aethal för att leta efter förnödenheter och aldrig återvände. Över en vecka senare ber hans sörjande partner resenärer på väg mot ruinerna att ta reda på vad som hänt honom och föra hem honom eller återfinna hans kära arvegods.",h="The Fate of a Loved One är ett uppdrag om Resaan, som gav sig in i de farliga Ruins of Ban'aethal för att...",kw={"ban'aethal","arvegods","resaan","ruins of ban'aethal","förnödenheter","the fate of a loved one"},sec={{t="En desperat vädjan",b="The Fate of a Loved One kretsar kring en desperat vädjan från någon vars partner, Resaan, gav sig tillbaka in i Ruins of Ban'aethal. Trots innerliga böner om att han skulle stanna kände Resaan sig tvungen att trotsa farorna i ruinerna för att söka efter förnödenheter. Han lämnade någon bakom sig som nu väntar i plågsam ovisshet."},{t="Försvunnen i ruinerna",b="Mer än en vecka har gått sedan Resaan gav sig av, långt längre än man rimligen kunde vänta sig att han skulle vara borta. Resenärer på väg mot Ban'aethal ombeds att leta efter honom bland ruinerna – att leda honom hem om han fortfarande lever, eller att återfinna hans familjearvegods om bara tragedi väntar där."}},faq={{q="Vem är Resaan?",a="Resaan är en person som gav sig tillbaka in i Ruins of Ban'aethal för att samla förnödenheter, trots böner om att han skulle stanna. Efter mer än en vecka utan livstecken fruktar hans älskade att han har mött en tragisk död bland ruinerna.",al={"vem är resaan","var är resaan","hitta resaan"}},{q="Vad är Ruins of Ban'aethal?",a="Ruins of Ban'aethal är en farlig plats dit Resaan gav sig för att söka efter nödvändiga förnödenheter. Hans älskade anser att färden är så farlig att det är osannolikt att någon överlever där ensam i en vecka.",al={"vad är banaethal","ruins of banaethal historia","var ligger banaethal"}},{q="Varför återvände Resaan till Ban'aethal?",a="Resaan återvände till Ban'aethal för att hämta förnödenheter. Han valde att göra den farliga resan trots att hans älskade bad honom att inte ge sig av.",al={"varför återvände resaan","varför är resaan i banaethal"}},{q="Vad ber uppdragsgivaren dig att ta med tillbaka?",a="Om Resaan fortfarande lever ber uppdragsgivaren dig att föra honom hem i säkerhet. Om han har omkommit i ruinerna vädjar uppdragsgivaren om att du återfinner hans personliga arvegods som ett sista minne.",al={"vad vill uppdragsgivaren","vad händer om resaan är död"}},{q="Hur länge har Resaan varit försvunnen?",a="Resaan har varit försvunnen i över en vecka sedan han gav sig in i Ruins of Ban'aethal. Med tanke på områdets faror får den långa tystnaden hans älskade att frukta det värsta.",al={"hur länge har resaan varit försvunnen","hur länge har resaan varit borta"}},{q="Vem erbjuder uppdraget?",a="Uppdraget erbjuds av Resaans sörjande partner eller älskade, som desperat söker visshet och är beredd att be förbipasserande resenärer på väg mot Ban'aethal om hjälp.",al={"vem ger uppdraget the fate of a loved one","uppdragsgivaren i the fate of a loved one"}}},fp="23,296,16.297.0,21.290.0,14.217.0,33.199.0,36.156.0,47.193.0,33.180.0,22.165.0"}
P.entries["quest:949"] = {n="The Twilight Camp",s="The Twilight Camp är ett alliansuppdrag för spaning, riktat mot de hemlighetsfulla kultisterna i lägret kring The Master's Glaive i södra Darkshore. Efter att ha fått en glimt av deras ritualplats i en spåskål måste spanare infiltrera utgrävningen för att ta reda på vad Twilight's Hammer försöker gräva fram.",h="The Twilight Camp är ett alliansuppdrag för spaning, riktat mot de hemlighetsfulla kultisterna i lägret kring...",kw={"darkshore","the master's glaive","onu","spåskål","twilight camp","twilight tome","twilight's hammer"},ang={["class:Druid"]="Att avslöja kultens forskning är avgörande för cenarieväktarna, som försöker hålla korrumperande uråldriga väsen säkert begravda.",["faction:Alliance"]="När kultens märkliga utgrävningar stoppas hindras ett växande hot från att destabilisera norra Kalimdor.",["race:NightElf"]="Twilight's Hammer vanhelgar Kalimdors heliga marker med mörk trolldom, alldeles under grenarna i Darkshores uråldriga lundar."},sec={{t="Undersök utgrävningen",b="The Master's Glaive har länge varit ett olycksbådande, förstenat mysterium bland de klippiga kullarna i södra Darkshore, men Twilight's Hammers plötsliga ankomst gjorde en gammal kuriositet till ett omedelbart hot. Efter att ha spanat in deras befästningar med en spåskål skickas spejare rakt in i lägret för att ta reda på deras verkliga avsikter innan försvarsåtgärder kan sättas in."},{t="Den illustrerade boken",b="En genomsökning av lägret visar att kultisterna inte är några vanliga skattsökare eller banditer. Deras verksamhet styrs av djupa ockulta studier. Långt inne i deras norra läger finns en uråldrig, noggrant handtryckt bok med mästerliga men oroande illustrationer. Texten bevisar att Twilight's Hammer medvetet undersöker den väldiga varelse som ligger begravd under jorden."}},faq={{q="Vad är målet med uppdraget The Twilight Camp?",a="Du måste infiltrera Twilight's Hammers läger nära The Master's Glaive i södra Darkshore och hitta en ledtråd om deras motiv, närmare bestämt en handtryckt ritualbok som finns i lägret.",al={"målet med uppdraget twilight camp","vad gör jag i twilight camp"}},{q="Vem skickar dig för att undersöka lägret?",a="Uppdraget tas emot direkt från spåskålen vid utsiktsplatsen ovanför The Master's Glaive. Det fortsätter undersökningen som inleddes för den uråldrige väktaren Onu.",al={"vem ger twilight camp","uppdragsgivare twilight camp"}},{q="Var i lägret finns ledtråden?",a="Den rätta ledtråden är Twilight Tome, som finns i den norra delen av lägret. Andra böcker i lägret kan vara farliga lockbeten som släpper lös skyddsmagi mot inkräktare.",al={"var finns boken","twilight tome plats","hitta ledtråd twilight camp"}},{q="Varför befinner sig Twilight's Hammer vid The Master's Glaive?",a="Kultisterna är besatta av de Gamla gudarnas uråldriga, mörka krafter och deras tjänare. De gräver ut det väldiga förstenade kadaver som den enorma stenbladet genomborrar, för att studera eller väcka den uråldriga ondska som finns kvar där.",al={"varför är kultister vid masters glaive","twilights hammer syfte darkshore"}},{q="Vad händer när du har hittat boken?",a="När du har hämtat boken får du uppdraget Return to Onu, som ber dig ta med de upptäckta skrifterna norrut till den uråldriga träanten i Grove of the Ancients.",al={"nästa uppdrag efter twilight camp","vart går jag efter twilight tome"}}},fx={["8554815a"]={q="Varför leder skålen för skådning dig till att undersöka lägret?",a="Onus skådarskål visar att Twilight's Hammer-sektmedlemmar har samlats runt The Master's Glaive, där en uråldrig ”gammal herre” föll för länge sedan. Deras syfte är okänt, men Onu är säker på att det är mörkt. Innan han och lundens försvarare kan lägga upp en plan behöver de något från lägret som avslöjar vad sekten tänker göra.",al={"varför undersöka twilight-lägret","skålen för skådningens syfte","varför söka igenom twilight-lägret"}}},fp="17,241,15.217.0,20.194.1,44.152.0,38.144.0,36.119.0,52.204.0,36.121.0"}
P.entries["quest:94947"] = {n="Welcome to Azeroth",s="'Welcome to Azeroth' markerar Skyborne-resenärernas ankomst till Stormwind, människornas huvudstad, via Skyborne Portal. När de anmäler sig i Stormwind Keep får nykomlingarna ett formellt erkännande och tillstånd av Highlord Bolvar Fordragon att resa fritt i hela Alliansens områden.",h="'Welcome to Azeroth' markerar Skyborne-resenärernas ankomst till Stormwind, människornas huvudstad, via...",kw={"bolvar fordragon","högalv","high order","kirin tor","portal","skyborne","stormwind keep","welcome to azeroth"},ang={["faction:Alliance"]="Highlord Bolvar Fordragon välkomnar formellt High Order på kung Anduin Wrynns vägnar och ger dem tillstånd att fritt färdas genom Alliansens områden.",["race:Skyborne"]="För Skyborne öppnar denna audiens formellt Stormwinds portar och Alliansens områden för högalver som anländer genom portalen."},sec={{t="Ankomst till huvudstaden",b="Resenärerna kliver rakt in i Stormwinds livliga stadskärna genom den mystiska Skyborne Portal. De ska anmäla sig hos människornas ledning och tar sig genom stadens storslagna huvudgator till Stormwind Keep för att presentera sig inför regentskapet."},{t="Audiens hos regenten",b="I den storslagna tronsalen hälsar Highlord Bolvar Fordragon medlemmar av High Order välkomna efter att en budbärare från Kirin Tor har förvarnat honom. Han konstaterar att det var länge sedan högalver vandrade genom Stormwind Keeps salar. Regenten välkomnar dem nådigt som gäster och ger dem fri lejd genom alla Alliansens områden på kungens vägnar."}},faq={{q="Vad handlar det här uppdraget om?",a="'Welcome to Azeroth' är ett introduktionsuppdrag där en resenär går genom Skyborne Portal till Stormwind och presenterar sig för Highlord Bolvar Fordragon i Stormwind Keep.",al={"vad är welcome to azeroth","uppdraget welcome to azeroth"}},{q="Vem är Bolvar Fordragon?",a="Highlord Bolvar Fordragon är regent över Stormwinds tron och styr riket från Stormwind Keep på den unge kungen Anduin Wrynn vägnar, medan kung Varian fortfarande är försvunnen.",al={"vem är bolvar fordragon","stormwinds regent"}},{q="Varför tar Bolvar emot Skyborne?",a="En budbärare från Kirin Tor underrättade Bolvar Fordragon om att medlemmar av High Order skulle anlända. Bolvar välkomnar dem som kronans gäster och ger dem tillstånd att utforska och resa fritt genom Alliansens områden.",al={"varför är skyborne i stormwind","högalver i stormwind"}},{q="Vad är High Order?",a="High Order är den fraktion eller grupp som de Skyborne-högalverna tillhör. Kirin Tor meddelade Stormwinds ledning om deras ankomst.",al={"vem är high order","high orders historia"}},{q="Vart leder Skyborne Portal?",a="Skyborne Portal för resenärer direkt till Stormwind, människornas huvudstad, så att nyanlända kan fortsätta raka vägen till Stormwind Keep och söka audiens hos kronan.",al={"skyborne portals destination","vart leder portalen"}},{q="Får Skyborne vistas i hela Alliansens område?",a="Bolvar Fordragon välkomnar formellt Skyborne som gäster på kungens vägnar och ger dem uttryckligen tillstånd att resa obehindrat genom Alliansens länder.",al={"tillhör skyborne alliansen","skyborne välkomnas av alliansen"}}},fp="18,272,22.292.0,27.369.0,25.187.0,24.188.0,37.226.0,23.158.0,36.180.0,55.171.0"}
P.entries["quest:95"] = {n="Sven's Revenge",s="Drivna av sorg och hämnd ber eremiten Sven Yorgen resenärer att återvända till hans förstörda gård i södra Duskwood. Medan han i åratal förföljde de skuggiga ryttarna som slaktade hans familj, begravde en misstänkt gestalt något nära hans lada som kan ge svar.",h="Drivna av sorg och hämnd ber eremiten Sven Yorgen resenärer att återvända till hans förstörda gård i södra...",kw={"dark riders","deadwind pass","duskwood","hög med lös jord","stubbe","sven yorgen","svens hämnd","the yorgen farmstead"},ang={["class:Paladin"]="Den våldsamma slakten på oskyldiga utförd av ondskefulla krafter från Deadwind Pass kräver rättmätig vedergällning och rättvisa för de döda.",["faction:Alliance"]="Slakten på familjen Yorgen är ännu ett tecken på Duskwoods isolering och visar hur långt mörka krafters räckvidd sträcker sig utan regelbundna patruller från Stormwinds armé."},sec={{t="Tragedin på gården",b="Sven Yorgen var en gång en enkel bonde som brukade jorden i sydöstra Duskwood. Hans liv slogs i spillror när huvtäckta Dark Riders red ner från Deadwind Pass och angrep hans hem, där de massakrerade hans familj medan han var borta. När Sven återvände till massakern fick han syn på en okänd gestalt som smög omkring nära ladan och frenetiskt begravde något i marken. Sven valde hämnden och gav sig genast av för att jaga mördarna, medan det som hade gömts blev kvar."},{t="Hemligheter grävs fram",b="Nu har Sven slagit läger i de västra kullarna och är uppslukad av vrede. Han behöver någon som återvänder till Yorgen Farmstead. Bakom en gammal trädstubbe mellan bondgården och den förstörda ladan ligger en hög löst hopskottad jord. Att hitta det som begravts där är första steget mot att förstå varför de skuggiga ryttarna över huvud taget gav sig på en stillsam bonde i Duskwood."}},faq={{q="Vem är Sven Yorgen?",a="Sven Yorgen var en vanlig bonde som bodde i sydöstra Duskwood, nära gränsen till Deadwind Pass. Efter att ha kommit hem och funnit sin familj mördad av illavarslande ryttare övergav han sin gård och blev en enstöring, besatt av att hämnas på de skyldiga.",al={"vem är sven","sven bakgrund","svens historia"}},{q="Vad hände med Svens gård?",a="Svens gård överfölls av de mystiska Dark Riders som kom från Deadwind Pass. De slaktade hela hans familj och lämnade gården i ruiner innan Sven hann återvända och försvara dem.",al={"tragedin på yorgen farmstead","vad hände med svens gård","varför är svens gård förstörd"}},{q="Vem begravde något bakom ladan?",a="Strax efter massakern såg Sven en skuggig gestalt som lurade nära hans lada och begravde ett föremål. Sven flydde ut i vildmarken för att jaga Dark Riders innan han hann fånga främlingen eller gräva upp det som gömts.",al={"vem begravde föremålet","skuggig gestalt vid svens gård","vem grävde jordhögen"}},{q="Var ligger jordhögen?",a="Jordhögen finns vid Yorgen Farmstead i sydöstra Duskwood, begravd precis bakom en gammal trädstubbe mellan ladan och den förstörda bondgården.",al={"var ligger jordhögen","jordhögens plats","var finns stubben"}},{q="Vilka är Dark Riders?",a="Dark Riders är hotfulla, huvtäckta ryttare som rider ut från Deadwind Pass. Lite är känt om deras ursprung, men deras våldsamma räder i Duskwood lämnar bara död och förödelse efter sig.",al={"vad är dark riders","dark riders bakgrund","ryttarna från deadwind pass"}},{q="Varför grävde inte Sven upp det begravda föremålet själv?",a="När Sven återvände hem och såg gestalten begrava föremålet var han uppslukad av sorg och förföljde genast de flyende Dark Riders. När han väl hade upprättat sitt gömda läger var gården övertagen och alltför smärtsam för honom att återvända till.",al={"varför undersökte inte sven jorden","varför gav sven sig av"}}},fx={e064b97c={q="Varför vill Sven Yorgen att det begravda föremålet hämtas?",a="Sven söker hämnd för sin familjs brutala slakt, utförd av de mystiska Dark Riders of Deadwind Pass. När han upptäckte massakern såg han en skuggfigur skyndsamt begrava något nära sin lada innan den flydde. Driven av vrede och behovet av svar tror Sven att det som ligger under jorden kan avslöja varför hans gård blev måltavla och vem som hjälpte till att förgöra hans familj.",al={"varför vill sven ha det här","sven yorgens motiv","varför hämnduppdraget åt sven"}}},fp="14,282,24.471.0,18.385.0,19.274.0,29.193.0,37.213.0,41.166.0,24.197.0,47.247.0"}
P.entries["quest:950"] = {n="Return to Onu",s="Return to Onu är ett alliansuppdrag som avslutar en inledande undersökning av kultisterna som slagit läger längs Darkshores kust. Efter att ha plundrat kultisternas läger och försökt läsa Twilight Tome återfår en äventyrare en enda sida med vansinniga krumelurer, som ska lämnas till kunskapens forntida Onu i Grove of the Ancients.",h="Return to Onu är ett alliansuppdrag som avslutar en inledande undersökning av kultisterna som slagit läger...",kw={"darkshore","grove of the ancients","insane scribbles","gamla gudar","onu","twilight tome","twilight's hammer"},ang={["class:Druid"]="Krumelurernas kaotiska, onaturliga resonans är en kränkning av den naturliga ordning som druiderna, tillsammans med treanter som Onu, tjänar för att bevara.",["faction:Alliance"]="Genom att undersöka kultens verksamhet längs Darkshores kust ser man till att nattalvboplatser som Auberdine förblir skyddade mot dolda hot.",["race:NightElf"]="Mörka kultisters vanhelgande av Darkshores stränder hotar balansen som kunskapens Ancients vakar över. Därför är Onus varningar djupt personliga för kaldorei."},sec={{t="En glimt av vansinne",b="När någon upptäcker Twilight Tome i Twilight's Hammer-lägret och blickar in bland dess blad, utsätts sinnena genast för ett angrepp. Den skrivna texten böljar och dansar över pergamentet, och utsirade ornament förvandlas till groteska gestalter. Den mentala påfrestningen är så överväldigande att en dödlig hjärna bara klarar av att slita loss en enda sida med nedklottrade anteckningar innan den dukar under för yrsel."},{t="Forntida misstankar",b="När Onu får sidan känner den väldige Ancient av den onaturliga aura som genomsyrar pappersbiten. Pergamentet utstrålar kaotisk, uråldrig magi, som Onu direkt kopplar till de forntida, skuggfyllda krafter som ligger begravda under jorden. Krumelurerna är svåra att tyda, men de bekräftar att Twilight's Hammer i Darkshore inte bara ägnar sig åt röveri, utan ingår i en djupare, hädisk plan."}},faq={{q="Vad är sidan som tagits ur Twilight Tome?",a="Sidan, som helt enkelt kallas Insane Scribbles, är ett avrivet blad ur kultens heliga bok. Den orsakar svår psykisk plåga för den som betraktar den, eftersom skriften vrider sig till groteska, skiftande mönster knutna till uråldrig tomrumsmagi.",al={"insane scribbles","vad är krumelurerna","sida ur twilight tome"}},{q="Vem är Onu?",a="Onu är en kunskapens Ancient, rotad i Grove of the Ancients i södra Darkshore. Han är en äldre väktare och lärd som vägleder nattalver och allierade i Alliansen mot nya förruttnelser i skogen.",al={"vem är onu","onu darkshore","treant onu"}},{q="Vad får Onu veta av krumelurerna?",a="Onu känner kaotiska, uråldriga energier strömma från sidan och identifierar inflytandet från forntida, illvilliga väsen. Skrifterna antyder att kultisterna i Twilight's Hammer aktivt söker efter relikplatser och begravda krafter i hela Darkshore.",al={"vad upptäckte onu","krumelurernas betydelse"}},{q="Varför är Twilight's Hammer i Darkshore?",a="Kulten har dragits till Darkshore för att gräva ut ruinerade alvplatser och hitta spår av forntida krafter knutna till uråldrigt mörker och de gamla gudarna. De använder landets kaos för att dölja sina ritualer.",al={"kultister i darkshore","varför är twilight hammer här"}},{q="Vart leder undersökningen härnäst?",a="Efter upptäckten av kultens närvaro riktar Onu uppmärksamheten mot de forntida alvruinerna i Mathystra i norr och uppmanar äventyrare att säkra forntida reliker innan kultisterna kan lägga beslag på dem.",al={"vilket uppdrag kommer härnäst","nästa efter return to onu"}},{q="Varför orsakar det yrsel att läsa boken?",a="Twilight Tome är inskriven med mörk, vansinnesframkallande magi av tomrum och kaos. Glyferna förvirrar aktivt dödliga sinnen och orsakar hallucinationer och svimningsanfall för att hindra utomstående från att avslöja deras hemligheter.",al={"varför ger boken yrsel","twilight tomes effekter"}}},fp="13,137,22.223.0,18.277.1,46.130.0,11.190.0,39.209.0,42.193.0,40.157.1,42.166.0"}
P.entries["quest:95041"] = {n="Data Hoarders",s="Data Hoarders är ett uppdrag från Jemma Quikswitch, en förvisad gnom som bor i Ironforge. Under den desperata evakueringen av Gnomeregan kopierade hon familjens mest värdefulla arkiv till hålkort, men tappade flera i de iskalla drivorna utanför stadsportarna. Att återfinna de förlorade datakorten innebär att rädda allt från avancerade ritningar till örlogsfartyg till oersättliga familjerecept.",h="Data Hoarders är ett uppdrag från Jemma Quikswitch, en förvisad gnom som bor i Ironforge.",kw={"data hoarders","dun morogh","gnomeregan","ironforge","jemma quikswitch","hålkort","andra kriget","ubåtsskrov"},ang={["faction:Alliance"]="Alliansen förlitar sig i hög grad på gnomisk uppfinningsrikedom. Genom att hjälpa fördrivna flyktingar att bevara krigstidens ingenjörsritningar ser du till att värdefull teknisk kunskap inom Alliansen inte går förlorad för alltid.",["profession:Cooking"]="Bland ritningar i världsklass finns också Grandma Quikswitchs personliga chilirecept, ett bevis på att god mat har lika stort känslovärde som militär vetenskap.",["profession:Engineering"]="Ingenjörer kan uppskatta det stora värdet som göms på dessa kort, med autentiska ritningar till ubåtsskrov från Andra kriget och komplexa arkanotekniska ekvationer.",["race:Gnome"]="För gnomiska äventyrare handlar återhämtningen av hålkorten om att bevara kulturen och se till att viktiga uppfinningar och familjeminnen inte går förlorade i hemlandets radioaktiva ruiner."},sec={{t="En jakt i snön",b="När trogginvasionen och den efterföljande strålningskatastrofen tvingade gnomerna att lämna Gnomeregan flydde tusentals med de ägodelar de kunde få med sig i kaoset. Jemma Quikswitch tog det förnuftiga steget att skriva ner generationer av familjekunskap på fysiska hålkort. Tragiskt nog läckte flera viktiga kort ut ur en skadad väska och ner i snöfälten kring den fallna staden. Utan de saknade hålkorten blir de återstående uppgifterna obegripligt nonsens, och familjens intellektuella arv riskerar att gå förlorat."},{t="Ekvationer och chili",b="Gnomernas dataarkiv speglar den märkliga bredden i deras civilisations prioriteringar. Familjen Quikswitchs handlingar innehåller avancerade arkanotekniska fältekvationer, viktiga ritningar till ubåtsskrov från Andra kriget och Grandma Quikswitchs hemliga chilirecept. För en utomstående kan det verka märkligt att blanda militär ingenjörskonst med matlagning, men för flyktingarna i Ironforge är det lika viktigt att bevara hemtrevnaden som att bevara tekniska underverk."}},faq={{q="Vem är Jemma Quikswitch?",a="Jemma Quikswitch är en gnomisk flykting som lyckades undkomma Gnomeregans fall och nu bor tryggt bland dvärgarnas salar i Ironforge.",al={"jemma quikswitch","vem ger data hoarders","uppdragsgivare data hoarders"}},{q="Vilka uppgifter finns på de förlorade korten?",a="Hålkorten innehåller familjen Quikswitchs arkiv, däribland arkanotekniska ekvationer, ritningar till ubåtsskrov från Andra kriget och Grandma Quikswitchs chilirecept.",al={"vad är hålkorten","vad fanns på korten","quikswitchs arkiv"}},{q="Var tappades datakorten?",a="De gled ut genom ett hål i Jemmas packning när hon flydde från Gnomeregan och ligger begravda i den snötäckta terrängen utanför portarna till den underjordiska staden i Dun Morogh.",al={"var finns korten","datakortens plats","var tappade hon dem"}},{q="Varför kan Jemma inte läsa de kort som finns kvar utan de saknade?",a="Jemma säger att uppgifterna är för oordnade för att kunna återställas utan de saknade hålkorten. Uppdraget förklarar inte hur korten kodar eller organiserar informationen.",al={"varför behövs alla kort","oordnade uppgifter","hålkortens data"}},{q="Vilken roll hade gnomerna med ubåtar under Andra kriget?",a="Under Andra kriget bidrog gnomerna stort till Alliansens krigsinsats med avancerad ingenjörskonst. De konstruerade och styrde särskilt undervattensfarkoster för att bekämpa Hordens sjöstridskrafter.",al={"gnomiska ubåtar andra kriget","ubåtsskrovets ritningar"}},{q="Varför bor gnomiska flyktingar i Ironforge?",a="Efter att Gnomeregan plötsligt föll för trogginvasionen och den katastrofala strålningen flydde de överlevande gnomerna sitt underjordiska hem. King Magni Bronzebeard erbjöd dem en fristad i den närliggande dvärgstaden Ironforge.",al={"varför är gnomer i ironforge","gnomer som bor med dvärgar"}}},fp="13,403,22.544.0,19.469.0,24.143.0,38.187.0,34.180.0,66.158.0,65.204.0,45.234.0"}
P.entries["quest:95065"] = {n="Fishin' Time",s="Vid Stormwind Harbor börjar Gilbert Gray få slut på bete, just när fisken nappar. Han ber förbipasserande hämta mer från en butik längs stadens kanaler.",h="Vid Stormwind Harbor börjar Gilbert Gray få slut på bete, just när fisken nappar.",kw={"kanaler","catherine leland","fishin time","gilbert gray","nattkrypare","glänsande prydnad","stormwind harbor","trade district"},ang={["faction:Alliance"]="Som medborgare i alliansen bidrar du till livet och moralen i Stormwind genom att hjälpa Gilbert Gray med ett vardagligt behov.",["race:Human"]="Som människa med Stormwind som hem ger du en äldre person en paus från rikets politik genom att hjälpa honom njuta av en stillsam fiskestund."},sec={{t="En dag vid vattnet",b="Gilbert Gray tillbringar lugna dagar med att fiska vid Stormwind Harbors kant. Han håller ögonen på flötet, men när fisken nappar kan betesburken snabbt bli tom. När förrådet är slut och fisken fortfarande nappar ber den äldre fiskaren förbipasserande att hämta mer."},{t="Fiskegrejer vid kanalerna",b="Catherine Leland driver en fiskebutik längs stenkantade kanaler, strax väster om Trade District. Hon förser fiskare i hela Stormwind med drag och bete, däribland stamkunder som Gilbert Gray."}},faq={{q="Vem är Gilbert Gray?",a="Gilbert Gray är en äldre fiskare vid Stormwind Harbor. Han tillbringar dagarna med att kasta ut linan i havet och ber förbipasserande hämta bete och drag när förrådet börjar sina.",al={"gilbert gray","gamle gray","vem ger uppdraget"}},{q="Vem är Catherine Leland?",a="Catherine Leland driver en fiskebutik längs stadens kanaler, strax väster om Trade District. Hon säljer fiskeutrustning och bete till Stormwinds fiskare.",al={"catherine leland","fiskeförsäljare stormwind","leland stormwind"}},{q="Var fiskar Gilbert Gray?",a="Gilbert Gray fiskar vid Stormwind Harbor, där han njuter av den öppna utsikten över havet.",al={"gilbert gray plats","var är gilbert gray","fiskare vid hamnen"}},{q="Vilka förnödenheter behöver Gilbert Gray?",a="Gilbert Gray behöver nattkrypare som bete och en glänsande prydnad som drag. Catherine Leland säljer båda längs kanalerna.",al={"uppdragsföremål fishin time","vilket bete vill gray ha"}},{q="Varför hämtar inte Gilbert Gray förnödenheterna själv?",a="Fisken nappar, och Gilbert Gray vill inte lämna sin plats eller gå miste om en fin fångst genom att gå tillbaka in i staden efter förnödenheter.",al={"varför kan gray inte köpa bete","varför behöver gray hjälp"}},{q="Var längs kanalerna ligger Catherine Lelands butik?",a="Catherine Lelands butik ligger längs kanalerna, strax väster om Trade District, intill stengångarna över stadens vattenleder.",al={"catherine leland plats","var ligger lelands butik","kanalerna vid trade district"}}},fp="12,149,18.264.0,25.191.0,20.167.0,24.160.0,29.82.0,37.118.0,52.132.0,58.129.0"}
P.entries["quest:951"] = {n="Mathystra Relics",s="Det här uppdraget sänder Alliansens äventyrare norrut längs Darkshores kust för att söka igenom de igenvuxna Ruins of Mathystra. Onu, en forntida kunskapsväktare med rötter i Grove of the Ancients, söker dessa urgamla kaldorei-föremål för att förstå hur Twilight's Hammer-sekten använder nattälvornas trolldom i sina onda riter.",h="Det här uppdraget sänder Alliansens äventyrare norrut längs Darkshores kust för att söka igenom de igenvuxna...",kw={"darkshore","grove of the ancients","the master's glaive","mathystra","onu","reliker","ruins of mathystra","twilight's hammer"},ang={["class:Druid"]="Genom att hjälpa Onu kan druider tjäna en av naturens främsta forntida väktare och skydda Darkshores urgamla historia från att förvridas av mörka sekterister.",["faction:Alliance"]="Att hindra Twilight's Hammer från att göra urgammal magi till ett vapen är avgörande för att säkra norra Kalimdor mot mörka, underjordiska krafter.",["race:NightElf"]="För nattalverna är det en sorgsen påminnelse om civilisationens fall att se reliker från tiden före Sunderingen grävas upp ur jorden. Det är också en oroväckande varning om att apokalyptiska galningar utnyttjar deras förfäders mäktiga konster."},sec={{t="En oroande upptäckt",b="När äventyrarna återfann ett besudlat pergament från sekteristerna kring det kolossala monumentet The Master's Glaive, dechiffrerade Onu en oroande uppenbarelse. Texten var inte någon inhemsk sekttext, utan ett förbannat fragment av urgammal nattalvisk skrift. Besudlat av Twilight's Hammer avslöjade pergamentet att dessa apokalyptiska fanatiker använder bortglömd alvisk magi för att väcka eller kalla tillbaka sina forntida herrar till de dödligas värld."},{t="Den fallna borgen",b="För att motverka detta mörka verk ger Onu hjältarna i uppdrag att bege sig till Ruins of Mathystra, längs Darkshores nordöstra kust. För länge sedan var Mathystra en strålande högborneborg innan den krossades under Sunderingen. Staden har rasat samman till ruiner, ogräs och naga, men kraftfulla rester av dess ursprungliga mystiska och andliga besvärjelser dröjer kvar i krossade urnor och forntida reliker utspridda bland stenfundamenten."},{t="Att avslöja mörka planer",b="Genom att samla in överlevande artefakter från ruinernas gräsbevuxna bråte hoppas Darkshores försvarare kunna avslöja vilka metoder sekteristerna tänker utnyttja. Onu studerar den kvarvarande magin i relikerna och skyndar sig att tyda sektens planer innan Twilight's Hammer helt kan förvrida den urgamla kaldorei-trolldomen och befria sina underjordiska herrar."}},faq={{q="Vad är Mathystra-relikerna?",a="De är skärvor av förtrollat lergods, urnor och artefakter som lämnats kvar i Ruins of Mathystra. De skapades under höjdpunkten av den urgamla nattalviska civilisationen före den stora Sunderingen och sjuder fortfarande av kvarvarande magisk energi.",al={"vad är relikerna","mathystra-relikernas historia","alviska reliker i mathystra"}},{q="Varför vill Onu ha relikerna?",a="Onu upptäckte att Twilight's Hammer-sekten använder urgammal alvisk magi i ett försök att återföra sina mörka herrar till världen. Genom att studera hela reliker från Mathystra hoppas Onu förstå hur sekten tänker manipulera den uråldriga kraften.",al={"varför vill onu ha reliker","mathystra-relikernas syfte"}},{q="Var låg Ruins of Mathystra?",a="Ruinerna ligger längs Darkshores nordöstra kust, norr om ruinerna Ameth'Aran och Bashal'Aran, strax bortom Tower of Althalaxx.",al={"var ligger mathystra","mathystra plats"}},{q="Vilka försöker Twilight's Hammer återföra?",a="Sekten hängiver sig åt forntida, ondskefulla herrar. Onu varnar för att de använder urgammal alvisk magi för att återföra dessa gamla herrar till Azeroth.",al={"vilka är twilight hammers herrar","sektens herrar i darkshore"}},{q="Vad var Mathystra innan det blev en ruin?",a="Mathystra var en gång en stor borg och stad för nattalverna, för tusentals år sedan. Staden föll i ruiner under den stora Sunderingen och har sedan dess tagits över av vildmark, spöken och vidriga strandvarelser som naga.",al={"mathystras historia","vad var mathystra"}},{q="Vem ger uppdraget ”Mathystra Relics”?",a="Uppdraget ges av Onu, en uråldrig treant med rötter i Grove of the Ancients i södra centrala Darkshore, efter undersökningen av The Master's Glaive.",al={"vem startar mathystra relics","uppdragsgivare för mathystra relics"}}},fp="16,329,22.461.1,18.465.0,21.377.1,30.237.0,31.253.0,42.141.0,50.142.0,43.230.0,39.163.0"}
P.entries["quest:95161"] = {n="Remember That I Love You",s="I Stormwind är ett blodfläckat brev på väg till Jeremy Heartweaver. Han har lämnat barnhemmet för ett nytt hem hos Avette Fellwood i Duskwood.",h="I Stormwind är ett blodfläckat brev på väg till Jeremy Heartweaver.",kw={"avette fellwood","blood-stained letter","duskwood","jeremy heartweaver","remember that i love you","stormwind","barnhemmet i stormwind"},ang={["faction:Alliance"]="För Alliansen säger minnessaker från stupade eller försvunna anhöriga, som bärs till adopterade föräldralösa barn, något om de personliga kostnaderna för kungarikets oroliga tillstånd.",["race:Human"]="Som människa från Stormwind färdas du från rikets relativt trygga hjärta till Duskwoods hemsökta, bortglömda bosättningar."},sec={{t="Ett meddelande till ett föräldralöst barn",b="Barnen på barnhemmet i Stormwind har förlorat sina familjer i krig, umbäranden och kaoset som sliter sönder kungariket. Jeremy Heartweaver var ett av dem, tills Avette Fellwood adopterade honom. Hon tog honom med sig till Duskwood, där skogarna är dystra och livet innebär faror och hårt arbete. Barnhemmets föreståndare trodde att ett hem hos en familj skulle ge honom mer än ett liv kvar i staden."},{t="Ett dystert tecken",b="Ett Blood-Stained Letter är adresserat till Jeremy, som är i Avette Fellwoods vård. Spåren leder söderut, förbi tryggheten i Elwynn Forest och in i Duskwoods skuggor. Vilken tragedi drabbade Jeremy efter att han lämnat Stormwind, och varför bär brevet ett så dystert tecken?"}},faq={{q="Vem är Jeremy Heartweaver?",a="Jeremy Heartweaver är en ung pojke som växte upp på barnhemmet i Stormwind. Avette Fellwood adopterade honom nyligen, och nu bor och arbetar han i Duskwood.",al={"jeremy","vem är jeremy","den föräldralöse jeremy"}},{q="Vem är Avette Fellwood?",a="Avette Fellwood är Jeremys adoptivmor och bor i Duskwood. Föreståndarna på barnhemmet i Stormwind anser att hon är en vänlig kvinna som troligen tog emot Jeremy för att få ytterligare ett par händer till sitt dagliga arbete.",al={"avette","vem är avette","adoptivmor"}},{q="Vad är Blood-Stained Letter?",a="Blood-Stained Letter är adresserat till Jeremy Heartweaver och hamnar hos hans adoptivvårdnadshavare, Avette Fellwood. Det bär på ekon av våld eller tragedi.",al={"blood-stained letter","brevet","vad är brevet"}},{q="Var hittar jag Avette Fellwood?",a="Avette Fellwood bor i Duskwood, den mörka skogen strax söder om Elwynn Forest, på andra sidan floden.",al={"avette fellwoods plats","var är avette","hitta avette"}},{q="Varför skickades Jeremy till Duskwood?",a="Jeremy adopterades från barnhemmet i Stormwind. Föreståndarna trodde att en familj och hederligt arbete i det farliga Duskwood var bättre än ett liv som föräldralös på barnhemmet.",al={"varför duskwood","varför lämnade jeremy stormwind","barnhemmet i duskwood"}},{q="Vilken fraktion kan ta det här uppdraget?",a="Endast Alliansen kan ta sig an det här uppdraget. Det börjar i Stormwind, människornas huvudstad, och leder in i det allianskontrollerade Duskwood.",al={"är det här alliansen","endast alliansen","horduppdrag"}}},fp="24,144,23.383.0,12.250.1,26.154.0,23.196.0,33.165.0,32.101.0,32.173.0,34.125.0"}
P.entries["quest:95189"] = {n="Crest of Lordaeron",s="Crest of Lordaeron är en väderbiten relik med den fallna nordliga kungadömets kungliga emblem. Sådana reliker är sällsynta sedan rikets fall och hittades bland de öde ruinerna av Capital City. Någon i Stormwind skulle gärna lägga vantarna på just den här.",h="Crest of Lordaeron är en väderbiten relik med den fallna nordliga kungadömets kungliga emblem.",kw={"crest of lordaeron","heraldik","lady dena kennedy","lordaeron","relik","ruins of lordaeron","stormwind","tirisfal glades"},ang={["faction:Alliance"]="Lordaerons emblem symboliserar grundpelaren i den ursprungliga Alliance, så att återfinna det är en symbolisk seger över Scourge och Forsakens försök att utplåna allt.",["race:Human"]="För människor, särskilt dem vars familjer en gång kallade norr sitt hem, är emblemet en gripande påminnelse om det storslagna kungarike som en gång ledde Alliance."},sec={{t="Ett splittrat arv",b="När Scourge drog fram genom kungariket Lordaeron förstördes dess palats, arkiv och stolta insignier till stor del, eller lämnades att förfalla i Undercitys skugga. Fysiska föremål med det kungliga emblemet som överlevt är ytterst sällsynta. Att återfinna ett helt eller väderbitet emblem bland de nordliga ruinerna innebär att en påtaglig del av människornas historia räddas från glömskan."},{t="En fristad i söder",b="Efter det tredje kriget flydde tusentals nordliga flyktingar söderut mot kungariket Stormwind och bar bara med sig minnen av sitt hemland. I Stormwind City är Lady Dena Kennedy angelägen om att förvärva sådana lämningar från Lordaeron, vilket gör reliker som det här emblemet mycket värdefulla i den sydliga huvudstaden."}},faq={{q="Vad är Crest of Lordaeron?",a="Det är ett väderbitet heraldiskt emblem som visar Lordaerons officiella märke. Det lämnades kvar när kungariket föll för Scourge och är en högt värderad historisk relik för människornas överlevande.",al={"crest of lordaeron","vad är crest of lordaeron","föremålet crest of lordaeron"}},{q="Vem vill ha Crest of Lordaeron?",a="Emblemet lämnas till Lady Dena Kennedy, en aristokratisk beskyddare i Stormwind City som vill samla in och bevara sällsynta föremål från det fallna nordliga riket.",al={"vem tar emot emblemet","var lämnar jag crest of lordaeron","lämna in emblemet"}},{q="Var hittades emblemet?",a="Det återfanns i Ruins of Lordaeron i Tirisfal Glades, den förstörda huvudstaden som nu ligger rakt ovanför Forsakens fäste Undercity.",al={"emblemets plats","emblem från ruinerna","var hittar jag emblemet"}},{q="Varför är föremål från Lordaeron så sällsynta?",a="Kungarikets snabba och katastrofala fall under det tredje kriget ledde till en systematisk slakt av dess folk och förödelse av dess gods. Mycket få personliga arvegods överlevde Scourge och Forsakens efterföljande framväxt.",al={"varför är lordaerons reliker sällsynta","sällsynta föremål från lordaeron"}},{q="Varför bryr sig Stormwind om reliker från Lordaeron?",a="Stormwind tog emot vågor av flyktingar, riddare och adelsfolk som flydde förödelsen i norr. Att bevara reliker hedrar Alliances fallna systerrike och håller de nordliga människornas arv vid liv.",al={"varför bryr sig stormwind","stormwind och lordaerons reliker"}},{q="Vem är Lady Dena Kennedy?",a="Lady Dena Kennedy är en adelskvinna som bor i Stormwind City och aktivt intresserar sig för att rädda historiska lämningar och arvegods med ursprung i Lordaeron.",al={"lady dena kennedy","vem är dena kennedy"}}},fp="18,272,20.382.0,19.297.0,31.180.0,33.164.0,26.159.0,41.242.0,50.208.0,25.164.0"}
P.entries["quest:95195"] = {n="Bloodied Insignia",s="Bloodied Insignias är tragiska kvarlevor efter Lordaerons fallna försvarare, utspridda bland rikets härjade ruiner. De bär Alliansens gamla emblem och tillhörde soldater vars familjer flydde söderut till Stormwind under det tredje kriget.",h="Bloodied Insignias är tragiska kvarlevor efter Lordaerons fallna försvarare, utspridda bland rikets härjade...",kw={"allians","bloodied insignia","lordaeron","marcus jonathan","flyktingar","ruins of lordaeron","stormwind","tredje kriget"},ang={["class:Paladin"]="Många av de fallna i huvudstaden stred sida vid sida med Silverhandens riddare. Att återbörda deras medaljer hedrar den heliga ordens förlorade bröder och systrar.",["faction:Alliance"]="Att återlämna dessa emblem till General Marcus Jonathan är en plikthandling och ett sätt att minnas soldaterna som gav sina liv för att försvara den ursprungliga Alliansen.",["race:Human"]="För Alliansens människor är dessa märken allvarliga påminnelser om det största människorikets fall. De knyter samman flyktingarna i Stormwind med deras fallna släktingar i norr."},sec={{t="De fallnas minnesmärken",b="När prins Arthas återvände för att härja Lordaeron med Scourge blev dess mäktiga armé övermannad och massakrerad. Otaliga soldater dog när de försvarade huvudstaden och de omgivande områdena. Efter sig lämnade de få fysiska spår utöver rostiga rustningar och blodfläckad mässing. Dessa gamla emblem från Alliansen tillhörde männen och kvinnorna som stod emot de odödas anstormning. Varje medalj, nedtrampad i ruinstadens jord och grus, är ett minne av rikets sista, desperata försvar."},{t="Budbärare åt de landsflyktiga",b="Många överlevande från Lordaeron flydde söderut över havet och slog sig ner som flyktingar i Stormwind City. Årtionden av allians och släktskap förenar de två människorikena, och många i södern längtar efter besked om sina försvunna närstående. General Marcus Jonathan, befälhavare för stadsvakten i Stormwind, tar hand om dessa blodiga emblem så att minnet av de nordliga försvararna bevaras och deras överlevande familjer äntligen får veta vad som hänt dem."}},faq={{q="Vad är Bloodied Insignias?",a="De är militära medaljer som bars av soldater från kungariket Lordaeron, vilka stred och dog under Alliansens fana i det tredje kriget.",al={"föremålet bloodied insignia","vad är det här emblemet","emblemens bakgrund"}},{q="Var hittar man dessa emblem?",a="De återfinns över hela Ruins of Lordaeron i Tirisfal Glades, där rikets försvarare gjorde sitt sista motstånd mot Scourge.",al={"var faller emblem","emblemens plats","märken i ruins of lordaeron"}},{q="Varför vill General Marcus Jonathan ha dem?",a="General Marcus Jonathan ansvarar för försvaret av Stormwind City, där otaliga nordliga flyktingar nu bor. Han samlar in dessa kvarlevor så att Lordaerons krigares offer kan hedras och deras levande släktingar i södern kan få besked.",al={"vem är marcus jonathan","varför ge dem till stormwind","marcus jonathan och emblem"}},{q="Varför bar Lordaerons soldater emblem från Alliansen?",a="Den ursprungliga Alliansen bildades i Lordaeron under kung Terenas Menethil II för att besegra den gamla Horden. Lordaeron var Alliansen av Lordaerons hjärta och ledare under det andra och tredje kriget.",al={"lordaerons alliansvapen","märke från alliansen av lordaeron"}},{q="Vad hände med soldaterna som bar dessa medaljer?",a="De dödades under det tredje kriget, när prins Arthas Menethil förrådde riket, mördade sin far och släppte lös de odöda i Scourge över huvudstaden.",al={"vad dödade soldaterna","lordaerons soldaters öde"}},{q="Finns det fortfarande levande släktingar till dessa soldater?",a="Ja. Tusentals invånare och soldater evakuerades från Lordaeron under pesten och Scourges invasioner och fann till sist en fristad i kungariket Stormwind.",al={"lordaerons flyktingar i stormwind","vem saknar soldaterna"}}},fp="17,264,20.502.0,26.468.0,32.144.0,32.145.0,43.250.0,55.203.0,52.161.0,51.158.0"}
P.entries["quest:952"] = {n="Grove of the Ancients",s="Grove of the Ancients är ett leveransuppdrag för Alliansen som för äventyrare från Darnassus över havet till Darkshore. På uppdrag av Arch Druid Fandral Staghelm tar kuriren ett brev till Onu, en vördnadsvärd Ancient of Lore som bor söder om Auberdine.",h="Grove of the Ancients är ett leveransuppdrag för Alliansen som för äventyrare från Darnassus över havet till...",kw={"ancient of lore","auberdine","cenarion circle","darkshore","darnassus","fandral staghelm","grove of the ancients","onu","the oracle glade"},ang={["class:Druid"]="När unga druider levererar brev mellan Arch Druid i Darnassus och Onu får de möta de olika temperamenten hos sina äldre inom Cenarion Circle. Staghelms driv ställs mot en Ancient of Lores stilla tålamod.",["faction:Alliance"]="För Alliansens kämpar som har uträttat sina ärenden i Darnassus ger den här leveransen ett tidigt skäl att ordna flygrutter med hippogryfer och utforska Darkshores kustland.",["race:NightElf"]="Uppdraget markerar den naturliga övergången från Teldrassils skyddade vagga till Kalimdors större vildmarker på fastlandet. Det lyfter fram den filosofiska skillnaden mellan Fandral Staghelm och Malfurion Stormrages läror."},sec={{t="Från grenverket",b="Efter att ha hjälpt till med ärenden kring The Oracle Glade på Teldrassils höjder blir äventyrarna kort och gott inkallade till ännu en tjänst av Arch Druid Fandral Staghelm. Staghelm låter inga händer gå sysslolösa och ger budbäraren i uppgift att föra ett brådskande meddelande över havet till Darkshores uråldriga skogar. Han säger åt dem att boka en flygtur med en hippogryf från staden."},{t="En skillnad i tålamod",b="När budbäraren når Darkshore och reser söder om Auberdine till Grove of the Ancients överlämnar hen brevet till Onu. Den väldige Ancient of Lore tar emot det under tyst eftertanke och antyder stillsamt att Staghelm är obevekligt otålig. För Onu och skogens uråldriga väktare sker allt i sin rätta tid – en lugn och bestående visdom som Shan'do Malfurion Stormrage förkroppsligade, men som Staghelm tydligt saknar."}},faq={{q="Vem ger uppdraget Grove of the Ancients?",a="Arch Druid Fandral Staghelm ger dig uppdraget från Cenarion Enclave i Darnassus när du har slutfört hans tidigare ärende kring The Oracle Glade.",al={"uppdragsgivare grove of the ancients","vem ger grove of the ancients","fandral staghelm uppdrag"}},{q="Var ligger Grove of the Ancients?",a="Grove of the Ancients ligger på fastlandet i Darkshore, strax söder om kusthamnen Auberdine.",al={"grove of the ancients plats","var ligger grove of the ancients","onu plats"}},{q="Vem är Onu?",a="Onu är en vis och vördnadsvärd Ancient of Lore som vilar i Darkshore. Som väktare och förvaltare av naturens visdom tar han emot brev från druidernas ledarskap i Darnassus.",al={"vem är onu","onu darkshore","onu ancient of lore"}},{q="Hur tar man sig från Teldrassil till Darkshore?",a="Resenärer tar sig vanligtvis från Darnassus ner till Rut'theran Village och flyger sedan över vattnet med en hippogryf till hamnbyn Auberdine i Darkshore.",al={"hur tar man sig till darkshore","resa till auberdine","hippogryf till darkshore"}},{q="Varför nämner Onu Shan'do Stormrage?",a="När Onu tar emot brevet kommenterar han Arch Druid Staghelms rastlösa brådska. Han tänker på att skogen följer sin egen takt, ett tidlöst tålamod som Shan'do Malfurion Stormrage förstod och respekterade.",al={"onu kommentar om malfurion","shan'do stormrage hänvisning","varför nämns shan'do"}},{q="Vilka uppdrag kommer före det här?",a="Det här uppdraget är det sista steget i en kort kedja med tre delar. Den börjar med The Enchanted Glade, följs av Teldrassil och skickar dig sedan vidare till Darkshore.",al={"förkunskapskrav grove of the ancients","grove of the ancients uppdragskedja","uppdrag före onu"}}},fx={["00893f03"]={q="Varför vill Arch Druid Fandral Staghelm att det här meddelandet överlämnas till Onu?",a="Fandral Staghelm vill upprätthålla nära kontakt med de uråldriga beskyddarna på andra sidan havet i Kalimdor. Onu, en Ancient of Lore som har sina rötter i Darkshore, har väntat på besked från Arch Druid om angelägenheter på Teldrassil. Nu när Fandral har fått de senaste rapporterna från The Oracle Glade är han otålig att genast skicka vidare sina rön och instruktioner och driva på sina planer för nattalverna.",al={"varför skicka meddelande till onu","fandrals motiv i grove of the ancients","varför vill fandral att det överlämnas"}},["658e120a"]={q="Varför väljer Fandral Staghelm dig att överlämna sitt meddelande?",a="Efter att ha sett dig föra bud från The Oracle Glade till Darnassus antar Fandral att du redan kan utföra känsliga ärenden över långa avstånd. I stället för att dra erfarna Cenarion-sändebud eller Sentinels från deras uppgifter sätter han helt enkelt en beprövad budbärare i tjänst för att föra hans skrivelse till Darkshore.",al={"varför just jag med fandrals meddelande","varför skicka spelaren till onu","varför inte skicka en sentinel"}}},fp="21,225,18.255.0,22.341.0,43.143.0,43.109.0,11.162.0,43.126.0,39.192.0,33.153.0"}
P.entries["quest:95204"] = {n="Crest of Lordaeron",s="Crest of Lordaeron är en väderbiten historisk artefakt med det fallna kungarikets emblem. Få sådana skatter överlevde Scourges förstörelse, och därför överlämnas den till Oran Snakewrithe i Undercity för att hjälpa till att bevara Forsakens historia.",h="Crest of Lordaeron är en väderbiten historisk artefakt med det fallna kungarikets emblem.",kw={"crest of lordaeron","forsaken","lordaeron","oran snakewrithe","relik","undercity"},ang={["faction:Horde"]="Genom att hjälpa Forsakens arkivarier i Undercity bidrar du till att bevara Lordaerons materiella arv bland ruinerna som Scourge lämnade efter sig.",["race:Undead"]="Som tidigare medborgare i Lordaeron värdesätter Forsaken bevarade reliker från sitt fallna kungarike som sällsynta kvarlevor från sina forna liv och sitt arv."},sec={{t="En kvarleva från det fallna kungariket",b="Lordaerons kungarike krossades under tredje kriget, och efter det återstod knappt något utom aska, ruiner och Scourges förödelse. Eftersom så mycket av rikets materiella kultur utplånades är bevarade insignier och emblem som Crest of Lordaeron ytterst sällsynta. För Forsaken som bor under ruinerna av Capital City är dessa föremål värdefulla, konkreta band till den civilisation de en gång tillhörde."},{t="Att bevara Forsakens arv",b="När den väderbitna vapenskölden återfinns ute i världen överlämnas den till Oran Snakewrithe i Undercity. Oran verifierar dess äkthet, och testar till och med metallen genom att bita i den, innan han bekräftar att det är ett äkta, till största delen intakt arvegods från deras hem. För Oran och Forsakens arkivarier hjälper varje räddad del till att återskapa en historia som Scourge försökte utplåna helt."}},faq={{q="Vad är Crest of Lordaeron?",a="Crest of Lordaeron är ett väderbitet emblem med det fallna människorikets symbol. Eftersom mycket få fysiska reliker överlevde Scourges förstörelse är den en ovärderlig historisk kvarleva för dem som försöker bevara Lordaerons arv.",al={"vad är crest of lordaeron","uppdraget med lordaerons vapensköld","föremålet vapensköld"}},{q="Vem vill ha vapenskölden i Undercity?",a="Vapenskölden förs till Oran Snakewrithe, som bor i Undercity. Oran granskar noga och bevarar återfunna artefakter med anknytning till det gamla kungariket.",al={"vem får vapenskölden","var lämnar man in vapenskölden","lämna in vapenskölden i undercity"}},{q="Varför biter Oran Snakewrithe i vapenskölden?",a="När Oran Snakewrithe tar emot vapenskölden biter han i den för att verifiera dess äkthet och materialsammansättning innan han förklarar den vara en äkta, till största delen intakt relik från Lordaeron.",al={"varför bita i vapenskölden","oran biter i vapenskölden"}},{q="Varför värdesätter Forsaken reliker från Lordaeron?",a="Forsaken är de odöda resterna av Lordaerons tidigare befolkning. Trots sin odödlighet och nya trohet är reliker från deras förstörda hemland påtagliga band till deras historia och identitet.",al={"varför bryr sig forsaken om lordaeron","forsakenreliker"}},{q="Vad händer med vapenskölden när den lämnas in?",a="Oran Snakewrithe tar hand om vapenskölden för att se till att den förvaras säkert. Han behandlar den som en dyrbar historisk skatt som hjälper till att återupprätta och minnas deras kungarikes arv.",al={"vad händer med vapenskölden","bevara vapenskölden"}},{q="Hur sällsynta är bevarade reliker från Lordaeron?",a="Fysiska emblem och reliker från tiden före tredje kriget är ytterst sällsynta. De flesta av Lordaerons symboler krossades, plundrades eller korrumperades när Arthas och Scourge tog över riket.",al={"är vapenskölden sällsynt","hur många vapensköldar finns kvar"}}},fp="18,256,40.433.0,28.385.0,31.248.0,33.159.0,41.173.0,46.203.0,52.181.0,45.187.0"}
P.entries["quest:95212"] = {n="Never Saddle on Quality",s="Never Saddle on Quality är ett uppdrag för Alliansen vid Amberstill Ranch i Dun Morogh. Djurvårdarna behöver felfria skinn från bergsleoparder för att tillverka varma sadlar åt riddjur som ska förstärka expeditionen till Alterac. På så vis kan både riddjur och ryttare stå emot den bitande kylan i de norra bergen.",h="Never Saddle on Quality är ett uppdrag för Alliansen vid Amberstill Ranch i Dun Morogh.",kw={"alterac","expeditionen till alterac","amberstill ranch","dun morogh","leopardpälsar","never saddle on quality","felfria leopardpälsar","baggar","sadlar"},ang={["class:Hunter"]="Uppdraget kräver skickliga spårare och jägare som kan hitta de vildaste bergsleoparderna i Dun Morogh och säkra felfria skinn.",["faction:Alliance"]="Amberstill Ranchs uppfödning av baggar förser direkt Alliansens styrkor med förstärkningar av riddjur i Alteracs iskalla höjder.",["race:Dwarf"]="Dun Moroghs tåliga bergsbaggar är typiska dvärgriddjur, och uppfödarna vid Amberstill Ranch vägrar utrusta dem med undermålig utrustning."},sec={{t="Expeditionens riddjur",b="Vid Amberstill Ranch i Dun Morogh förbereder djurvårdarna ett nytt lag robusta bergsbaggar som ska förstärka Alliansens expedition i Alterac. Förberedelserna har dock stannat av eftersom det saknas lämpligt material för att tillverka slitstarka sadlar som skyddar djuren mot kylan."},{t="Värme i de höga passen",b="För att stå emot den stränga kylan i Alteracbergen behöver expeditionens riddjur tjock isolering av hög kvalitet. Jägare skickas till de östra klipporna för att spåra upp de största och vildaste bergsleoparderna i Dun Morogh och ta tillvara deras felfria skinn. Då får Alliansens styrkor utrustning som klarar de höga passen."}},faq={{q="Vad är Never Saddle on Quality?",a="Never Saddle on Quality är ett uppdrag som utgår från Amberstill Ranch i Dun Morogh. En uppfödare behöver leopardpälsar av hög kvalitet för att tillverka robusta, varma sadlar åt ett lag baggar som förbereds som förstärkning till expeditionen till Alterac.",al={"vad är det här för uppdrag","uppdraget never saddle on quality","vad är never saddle on quality"}},{q="Varför behövs leopardpälsar?",a="Pälsarna behövs för att tillverka slitstarka, varma sadlar åt expeditionens riddjur. Bergsleoparderna i Dun Morogh har tjock, isolerande päls som skyddar ryttare och djur mot den bitande bergskylan i Alterac.",al={"varför leopardpälsar","vad används pälsarna till","varför felfria skinn"}},{q="Vart ska baggarna skickas?",a="Riddjuren ska till Alliansens styrkor som deltar i expeditionen till Alterac. Med hårt väder och pågående insatser i de höga passen är välutrustade ridbaggar ett viktigt stöd.",al={"vart ska baggarna","vem får baggarna","förstärkning till alterac"}},{q="Vilken roll har Amberstill Ranch här?",a="Amberstill Ranch ligger i de snöiga kullarna i Dun Morogh, öster om Kharanos. Gården är den främsta platsen för uppfödning och träning av dvärgarnas bergsbaggar.",al={"var ligger amberstill ranch","amberstill ranchs plats"}},{q="Var strövar leoparderna?",a="De vilda snöleoparderna strövar omkring på de snöiga höjderna och klipporna öster om Amberstill Ranch i Dun Morogh. Där måste jägare spåra upp de största djuren för att få tag på felfria skinn.",al={"var hittar man leoparder","var finns leoparder i dun morogh"}},{q="Varför är skydd mot kyla så viktigt för expeditionen?",a="Kungariket och bergen i Alterac är kända för sin stränga kyla och hårda vindar. Utan tjockt sadelmaterial av hög kvalitet riskerar både riddjur och ryttare förfrysning och utmattning i bergsterrängen.",al={"är det kallt i alterac","varför varma sadlar"}}},fp="23,312,23.289.0,26.335.0,32.233.0,29.217.0,30.186.0,37.160.0,27.174.0,63.193.0"}
P.entries["quest:95213"] = {n="Stolen Blasting Powder",s="Stolen Blasting Powder handlar om en tom, farlig kruttunna som hittas bland troggs nära Gol'Bolar Quarry. När du återlämnar den saknade tunnan till Quarrymaster Thesten avslöjas ett allvarligt säkerhetsbrott och en riskfylld brist i stenbrottets sprängmedelsförråd.",h="Stolen Blasting Powder handlar om en tom, farlig kruttunna som hittas bland troggs nära Gol'Bolar Quarry.",kw={"sprängkrut","dun morogh","tom kruttunna","gol'bolar quarry","kruttunna","quarrymaster thesten","stolen blasting powder","thesten","troggs"},ang={["faction:Alliance"]="Det är viktigt för alliansens verksamhet i Khaz Modan att skydda Dun Moroghs försörjningsleder och gruvutposter mot troggangrepp.",["profession:Engineering"]="Sprängkrut är ett farligt och instabilt ämne. Ingenjörerna förstår bättre än någon annan vilken förödelse troggs kan orsaka med obehöriga sprängämnen.",["profession:Mining"]="Stenbrottets arbete bygger på kontrollerade sprängningar för att utvinna sten, men saknade kruttunnor signalerar allvarlig fara inne i gruvgångarna.",["race:Dwarf"]="Gol'Bolar Quarry förser Ironforge med sten och resurser, så säkerheten kring stenbrottets sprängämnen är en akut angelägenhet för alla dvärgar."},sec={{t="En farlig upptäckt",b="En tom tunna märkt med allvarliga varningar visar att farligt sprängkrut har hamnat i obehörigas händer vid Gol'Bolar Quarry. Sådana sprängmedel får bara användas vid kontrollerad brytning med stenbrottsmästarens uttryckliga tillstånd. Att tunnan hittas bland fientliga troggs tyder på ett betydligt mer explosivt hot mot gruvan än vanliga störningar i arbetet."},{t="Stenbrottsmästarens oro",b="När den tomma behållaren återlämnas till Quarrymaster Thesten besannas de värsta farhågorna hos dvärgarnas arbetsledare. Thesten blir blek när han ser tunnan och inser att det saknade sprängkrutet redan har tömts och hanterats av troggsen som svärmar i området under jord. Upptäckten får stenbrottets ledning att febrilt försöka ta reda på vad varelserna tänker spränga härnäst."}},faq={{q="Vad är Stolen Blasting Powder?",a="Stolen Blasting Powder är ett uppdrag som inleds när du hittar en tom tunna med sprängkrut och farlighetsvarningar i händerna på troggs nära Gol'Bolar Quarry. Det gör Quarrymaster Thesten uppmärksam på stölden av explosiva gruvförnödenheter.",al={"vad är stolen blasting powder","uppdrag med kruttunna","lore om tom kruttunna"}},{q="Vem ska få den tomma kruttunnan?",a="Den tomma kruttunnan ska lämnas direkt till Quarrymaster Thesten, som leder arbetet vid Gol'Bolar Quarry i Dun Morogh.",al={"vart ska tunnan lämnas","vem är thesten","stenbrottsmästarens plats"}},{q="Varför är det stulna sprängkrutet farligt?",a="Tunnan har tydliga varningar om att stenbrottsmästaren måste godkänna användningen och innehöll farligt sprängkrut. Om troggs får tag på tunga sprängämnen eller detonerar dem hotas hela stenbrottet och närliggande bosättningar.",al={"varför är sprängkrut farligt","troggs med sprängämnen","varför har troggs sprängkrut"}},{q="Vad är Gol'Bolar Quarry?",a="Gol'Bolar Quarry är en dvärgisk gruva i Dun Morogh där sten och mineraler bryts åt Ironforge.",al={"var ligger gol'bolar","stenbrottets plats","gol'bolar dun morogh"}},{q="Varför blir Quarrymaster Thesten blek?",a="När Quarrymaster Thesten får syn på den tomma tunnan blir han märkbart blek och frågar var den hittades. Han inser genast att det farliga innehållet redan har hamnat i händerna på fientliga troggs.",al={"varför blir thesten blek","thestens reaktion","vad säger thesten"}},{q="Vad gör troggs nära Gol'Bolar Quarry?",a="Troggs har tagit över de lägre delarna och utkanterna av Gol'Bolar Quarry. De stör dvärgarnas gruvarbetare och letar igenom utrustning och sprängkrut från gruvan.",al={"finns det troggs i stenbrottet","trogginvasion i dun morogh","varför tar troggs sprängkrut"}}},fp="22,240,21.389.0,24.378.1,31.240.0,40.129.0,44.210.0,25.128.0,40.193.0,44.164.0"}
P.entries["quest:95214"] = {n="Stolen Blasting Powder",s="Stolen Blasting Powder är ett uppdrag vid Gol'Bolar Quarry i Dun Morogh där äventyrare måste återta försvunnen ammunition. Primitiva troggs har kommit över tillräckligt med sprängpulver för att jämna en fästningsflygel med marken, så Quarrymaster Thesten måste rekrytera diskret hjälp innan en katastrof inträffar.",h="Stolen Blasting Powder är ett uppdrag vid Gol'Bolar Quarry i Dun Morogh där äventyrare måste återta...",kw={"sprängpulver","dun morogh","sprängämnen","gol'bolar quarry","ironforge","king magni","quarrymaster thesten","thesten","troggs"},ang={["faction:Alliance"]="Försörjningslederna och stenbrotten i Dun Morogh är avgörande för Alliansens fäste i bergen. Att bevara freden och vakta farlig ammunition skyddar High Seat i närbelägna Ironforge.",["profession:Mining"]="Sprängpulver är ett oumbärligt redskap för att röja sten och öppna malmådror i djupa schakt, men det kräver disciplin att hantera. Att förlora stora tunnor till vilda grottvarelser är varje quarrymasters mardröm.",["race:Dwarf"]="Gol'Bolar Quarry bidrar till Ironforges stenhantverk och utgrävningar. Att låta underjordiska troggs göra gruvsprängämnen till vapen alldeles utanför King Magnis dörr är ett förödmjukande säkerhetsmisslyckande för varje dvärgförman."},sec={{t="Ett saknat förråd",b="Vid Gol'Bolar Quarry i Dun Morogh är dvärgarnas arbete starkt beroende av kraftiga sprängladdningar för att bryta sten och öppna djupa malmådror. Säkerheten brast dock när primitiva troggs som lurade bland klipporna i närheten lyckades komma över en hel stor leverans högklassigt sprängpulver. Quarrymaster Thesten fick skynda sig att hitta dugligt folk innan tjuvflocken råkade utlösa en explosion."},{t="En krutdurk bland klipporna",b="Mängden material som saknas är häpnadsväckande: Thesten säger att tunnan innehöll tillräckligt med sprängkraft för att förvandla King Magni Bronzebeards storslagna tronsal till en sal under bar himmel. Troggarna bar det farliga bytet österut till sina primitiva läger vid foten av bergen. Om de lämnades åt sig själva skulle det bara vara en tidsfråga innan de upptäckte eld eller slog sten mot gnista."},{t="En tyst lösning",b="När de stulna laddningarna har slitits ur troggarnas händer och tryggt återförts till stenbrottets förråd drar Thesten en tung suck av lättnad. Quarrymastern belönar äventyraren med en diskret vädjan om att inte nämna den lilla händelsen för någon."}},faq={{q="Vem är Quarrymaster Thesten?",a="Quarrymaster Thesten övervakar arbetet vid Gol'Bolar Quarry i Dun Morogh. Han ansvarar för utgrävningsplatsens säkerhet och produktivitet, och hamnar i en pinsam knipa när ett stort förråd industrisprängpulver försvinner under hans uppsikt.",al={"vem är thesten","quarrymaster thesten","vem ger uppdraget"}},{q="Var finns det stulna sprängpulvret?",a="Troggarna som håller till bland klipporna och i hålorna strax öster om Gol'Bolar Quarry bar bort pulvret. Äventyrare skickas till de klippiga utlöparna för att ta tillbaka de farliga tunnorna och säckarna från varelserna innan katastrofen slår till.",al={"var finns stulit sprängpulver","troggarnas plats","pulvrets plats"}},{q="Varför stal troggarna sprängpulvret?",a="Troggs är primitiva underjordiska varelser som drivs av enkel list och revirtänkande. De stal pulvret från stenbrottets arbetare, och Quarrymaster Thesten befarar att även klumpiga experiment kan leda till att de råkar antända sprängämnena.",al={"varför stjäl troggs pulver","vad vill troggs med pulver"}},{q="Hur farligt är det stulna sprängpulvret?",a="Enligt Quarrymaster Thesten innehöll den saknade tunnan tillräckligt med explosivt pulver för att spränga King Magnis tronsal till spillror och lämna den öppen mot himlen. Om allt detonerade på en gång i stenbrottet eller grottorna skulle kraften vara förödande.",al={"hur kraftigt är pulvret","pulver i magnils tronsal","är pulvret farligt"}},{q="Varför vill Quarrymaster Thesten hålla händelsen hemlig?",a="När du återlämnar pulvret betalar Thesten dig och ber dig att inte nämna den lilla händelsen för någon. Han säger inte varför, men att förlora så mycket sprängämne till troggs är uppenbarligen något han helst vill hålla tyst om.",al={"varför hålla det hemligt","thestens hemlighet","nämn inte händelsen"}},{q="Vad är Gol'Bolar Quarry?",a="Gol'Bolar Quarry är en framstående utgrävningsplats för dvärgar i östra Dun Morogh, där man bryter sten till byggnads- och ingenjörsprojekt i hela riket. I de djupa schakten får arbetarna regelbundet hantera underjordiska skadedjur som troggs som tränger fram ur berget.",al={"vad är gol'bolar","gol'bolar quarry","var ligger gol'bolar"}}},fp="22,286,19.408.0,25.386.0,16.238.1,28.281.0,46.238.0,45.275.0,44.242.0,59.214.0,25.266.0"}
P.entries["quest:95216"] = {n="The New Plague",s="The New Plague är ett forskningsprojekt som Theodore Griffs bedriver i Apothecarium i Undercity. Efter rapporter om en dödlig leddjursart i ruinerna ovanför, vars gift fräter även på odött kött, vill Griffs analysera och bakåtkonstruera dess dödliga toxiner.",h="The New Plague är ett forskningsprojekt som Theodore Griffs bedriver i Apothecarium i Undercity.",kw={"apothecarium","sekret","ruins of lordaeron","the new plague","theodore griffs","giftig variant","undercity","witherfang"},ang={["faction:Horde"]="Horden tolererar de övergivna som taktiska allierade i Eastern Kingdoms, men de illavarslande biologiska experimenten som pågår i Apothecarium väcker ofta oro hos mer hedervärda medlemmar.",["race:Undead"]="Royal Apothecary Society jagar obevekligt toxiner som kan skada både levande och döda för att säkra de övergivnas överhöghet och skydda deras unga nation."},sec={{t="Apotekarens ambition",b="I Apothecariums fuktiga skrymslen samlar Royal Apothecary Society ständigt in virulenta ämnen från hela Azeroth. Theodore Griffs, en av dess hängivna forskare, spårar exotiska bestar och dödliga föroreningar för att främja de övergivnas alkemiska innovationer. Efter att ha hört rykten om en giftig varelse som strövar bland de krossade stenarna ovanför skickar Griffs ut äventyrare för att hämta ett användbart prov innan tillfället går förlorat."},{t="Ett köttfrätande toxin",b="Målet för forskningen är Witherfang, ett giftigt leddjur som jagar i Lordaerons yttra ruiner. Dess gift har den sällsynta och skrämmande egenskapen att bryta ned inte bara levande vävnad, utan även dött och bevarat kött. För en apotekare som arbetar med att förfina biologisk krigföring och skydda de övergivnas rike ger kunskapen om hur ett sådant toxin kringgår nekrotiskt motstånd ovärderliga kemiska insikter."},{t="Bakåtkonstruktion av sekretet",b="Även om Griffs uttrycker sin frustration när äventyrare dödar Witherfang i stället för att fånga den levande, räcker det insamlade sekretet som analysmaterial. Genom att bryta ned varelsens kroppsvätskor tänker apotekaren bakåtkonstruera giftets virulenta verkningssätt, så att även ett krossat leddjur bidrar till Undercitys växande kemiska styrka."}},faq={{q="Vem är Theodore Griffs?",a="Theodore Griffs är en apotekarforskare verksam i Apothecarium i Undercity. Han undersöker kraftfulla toxiner och exotiska exemplar för att framställa föreningar åt de övergivna och visar föga hänsyn till den som inte uppskattar det känsliga alkemiska hantverket.",al={"vem ger uppdraget the new plague","theodore griffs","vem är theodore griffs"}},{q="Vad är Witherfang?",a="Witherfang är ett dödligt, giftigt leddjur som lurar i Ruins of Lordaeron ovanför Undercity. Det producerar ett anmärkningsvärt frätande toxin som kan lösa upp även motståndskraftigt odött kött.",al={"vad är witherfang","var finns witherfang","leddjur i ruins of lordaeron"}},{q="Varför vill Theodore Griffs ha Witherfangs gift?",a="Theodore Griffs vill studera Witherfangs gift för att ta reda på hur dess toxiner fräter igenom odött kött. Han hoppas kunna bakåtkonstruera ämnet till kraftfulla varianter för de övergivnas alkemiska arsenal.",al={"vad vill theodore med witherfang","varför samla in den mycket giftiga varianten"}},{q="Varför är Theodore Griffs upprörd när du återvänder?",a="Theodore Griffs hoppades att exemplaret skulle hållas intakt eller skördas varsamt i stället för att dödas direkt. Han är irriterad över att Witherfang dödades, men lyckades ändå utvinna tillräckligt med kvarvarande sekret ur lämningarna för att studera dess egenskaper.",al={"varför blev theodore arg","förstörde jag provet"}},{q="Vad är Apothecariums syfte?",a="Apothecarium är Royal Apothecary Societys forskningscentrum under Lordaeron. Det beskrivs som Undercitys viktigaste kvarter och ägnas åt att testa virulenta varianter, framställa alkemiska vapen och experimentera på exotiska varelser.",al={"apothecariums syfte","varför är apothecarium viktigt"}},{q="Hur anser Theodore att virulenta varianter bäst överförs?",a="Enligt Theodore Griffs är det mest potenta och tillförlitliga sättet att överföra smitta alltid att föra in den direkt i blodomloppet.",al={"hur överförs giftet","överföringssätt"}}},fp="14,287,25.429.0,24.413.0,29.391.1,23.272.0,19.195.0,49.203.0,45.240.0,40.261.0,64.151.0"}
P.entries["quest:95217"] = {n="The Quarry's Smith",s="The Quarry's Smith är ett uppdrag från Frast Dokner, en yrkesverksam smed stationerad vid ett läger i ett stenbrott. När en väntad leverans uteblir och han blir strandsatt vänder sig smeden till villiga resenärer för att samla råmetall och tåligt läder till viktiga reparationer av lägret. I utbyte mot materialen delar Dokner med sig av praktiska smidestekniker till blivande metallarbetare.",h="The Quarry's Smith är ett uppdrag från Frast Dokner, en yrkesverksam smed stationerad vid ett läger i ett...",kw={"smide","kopparbarrar","dun morogh","dvärg","frast dokner","gol'bolar quarry","ironforge","the quarry's smith","hårda vildsvinshudar"},ang={["faction:Alliance"]="Genom att hjälpa Dokner håller du det avlägsna dvärgiska stenbrottet i drift och stärker den lokala infrastrukturen och utrustningens beredskap i det snöiga höglandet.",["profession:Blacksmithing"]="Frast Dokner fungerar som fältmentor för lärlingar inom smide och byter sina hårt vunna smidestekniker mot råmetall och läder som håller hans städ varmt.",["profession:Mining"]="Gruvarbetare som arbetar i fyndigheterna i närheten får en omedelbar lokal köpare för sina smälta kopparbarrar och kan förvandla råmalm till praktisk utbildning och reparationer av lägret.",["race:Dwarf"]="Gol'Bolar Quarry visar Bronzebeard-klanens företagsamhet och industri i Dun Morogh, där dvärgarnas beslutsamhet håller smedjorna brinnande även när försörjningskaravanerna blir försenade."},sec={{t="Brist i stenbrottet",b="Livet vid en aktiv utgrävning kräver ständigt underhåll, från att vässa hackor och byta ut slitna fästen till att förstärka lägerutrustning. När en viktig leverans inte kommer i tid börjar det dagliga arbetet stanna av. Utan färska varor från de stora handelsvägarna tvingas hantverkarna på plats improvisera och vända sig till förbipasserande äventyrare för att hålla lägret fungerande. Frast Dokner, som arbetar vid smedjan medan förseningarna fortsätter, förlitar sig på alla som är villiga att leta fram enkla metaller och hudar i stället för att vänta sysslolös på transportvagnar som kanske blir hopplöst försenade."},{t="En lärlings uppgörelse",b="Traditionella dvärggillen för smeder värdesätter disciplin och välbevarade metoder, och delar sällan med sig av yrkeshemligheter till tillfälliga vandrare. Dokner väger dock lokala behov mot gillets formaliteter. Eftersom det råder omedelbar brist på bearbetbar koppar och slitstarkt läder för att laga verktyg och lägerutrustning erbjuder han ett praktiskt byte: kom med råmaterialen direkt till hans städ, så lär han dig sina personliga smidestekniker. Det är en ömsesidigt fördelaktig uppgörelse som vuxit fram ur gränslandets behov, där värdefull yrkeskunskap byts mot omedelbar överlevnad och underhåll."}},faq={{q="Vem är Frast Dokner?",a="Frast Dokner är en erfaren smed stationerad vid ett läger i ett stenbrott. Han ansvarar för att underhålla verktyg, byggnadsbeslag och utrustning åt arbetarna på plats. När logistiska förseningar skär av hans vanliga försörjningslinje tar han saken i egna händer och rekryterar förbipasserande äventyrare för att skaffa råmaterialen han så desperat behöver.",al={"frast dokners bakgrund","vem är smeden i stenbrottet","smed i stenbrott"}},{q="Varför behöver stenbrottet kopparbarrar och vildsvinshudar?",a="Utgrävningen och underhållet av lägret förbrukar stora mängder tåliga material. Koppar är en lättillgänglig, formbar metall som passar till ersättningsbeslag, spikar, fästen och förstärkningsband för trasiga verktyg. Hårda vildsvinshudar ger slitstarkt läder till bälgar, verktygslindor, remmar och skyddsförkläden som står emot de hårda gnistorna och det tunga sliparbetet i stenbrottet.",al={"varför kopparbarrar och vildsvinshudar","material som smeden i stenbrottet behöver","reparationsmaterial till stenbrottet"}},{q="Varför är leveransen försenad?",a="Frast Dokner berättar inte vad förseningen beror på, men landvägarna genom snöiga klippor och bergspass plågas ofta av hårda snöstormar, kringströvande vilda djur och fientliga bakhåll från troggar eller banditer. Avlägsna gruvläger och stenbrott är ofta de första bosättningarna som drabbas när transportvagnar blir försenade.",al={"försenad leverans","vad hände med förnödenheterna","varför är förnödenheterna försenade"}},{q="Vad erbjuder Frast Dokner i utbyte mot materialen?",a="I stället för att bara erbjuda mynt lovar Frast Dokner att dela med sig av sina personliga smidestekniker till den som skaffar förnödenheterna han behöver. För en blivande hantverkare ger undervisning direkt från en erfaren yrkesman ute i fält praktiska insikter i metallarbete och utrustningsunderhåll som stadens formella smedgillen sällan lär ut till nybörjare.",al={"belöning från smeden i stenbrottet","vad lär frast ut","frasts smidestekniker"}},{q="Var ligger stenbrottet?",a="Frast Dokner arbetar i Dun Morogh vid Gol'Bolar Quarry, en dvärgisk utgrävningsplats inbäddad i de snöiga förbergen söder om Kharanos. Stenbrottet utsätts ständigt för hårt vinterväder och aggressiva underjordiska troggar, som regelbundet trakasserar gruvarbetarna och stör handelskaravaner från Ironforge.",al={"vilket stenbrott är det här","var finns frast dokner","smedens plats i stenbrottet"}},{q="Tillhör Frast Dokner Ironforge?",a="Ja, Frast Dokner och lägret vid stenbrottet verkar inom Bronzebeard-klanens och kungariket Ironforges domäner. Stenbrytning och malmutvinning i bergen i Dun Morogh är viktiga för dvärgakungarikets byggprojekt och försvarsverk, vilket gör lokala smeder som Dokner oumbärliga för Ironforges industriella styrka.",al={"frast dokner ironforge","tillhör stenbrottet ironforge","dvärgarnas lojalitet i stenbrottet"}}},fp="18,369,23.580.0,23.599.0,20.349.0,52.409.0,32.369.0,59.358.0,29.326.0,42.360.0"}
P.entries["quest:95250"] = {n="Abominable Creatures",s="Abominable Creatures är ett uppdrag från Captain Truman, en mänsklig lojalist som desperat väntar på förstärkningar i utkanten av Lordaerons fallna huvudstad. Han tror att hans befälhavare, en vördad Grand Marshal, fortfarande kämpar tappert i närliggande Ruins of Lordaeron och ber därför en duglig äventyrare att leta upp honom. Uppdraget avslöjar det dystra ödet för rikets förlorade försvarare och den bittra fientlighet som pyr bland de överlevande lojalistiska styrkorna.",h="Abominable Creatures är ett uppdrag från Captain Truman, en mänsklig lojalist som desperat väntar på...",kw={"abominable creatures","captain truman","grand marshal","head of the baron","lordaeron","ruins of lordaeron","baronen","lordaerons sanna söner"},ang={["faction:Alliance"]="Uppdraget visar den farliga och isolerade situationen för resterna av Alliance som försöker verka bland ruinerna i norra Lordaeron. Det belyser hur de kvarvarande lojalistiska trupperna kämpar med sviktande hopp och den psykiska påfrestningen av att möta övermäktiga monster.",["race:Human"]="Mänskliga äventyrare får bevittna det hjärtskärande ödet för Lordaerons fallna ledarskap, då till och med en aktad Grand Marshal förvandlades till en grotesk odöd fasa. Captain Trumans bittra sorg och nationalistiska nit speglar det råa trauma som bärs av mänskliga överlevare som desperat vill återta sitt förfädershem.",["race:Undead"]="För Forsaken är baronens groteska förvandling en dyster påminnelse om hur Scourge stympade Lordaerons främsta försvarare och förvandlade dem till monstruösa styggelser. Captain Trumans löfte att rensa ruinerna från alla bestar och odöda speglar den obevekliga fientlighet som de levande lojalistiska styrkorna hyser mot folket i Undercity."},sec={{t="En desperat vakt",b="Captain Truman står vaksam vid sin post och väntar oroligt på de sedan länge försenade förstärkningarna som ska hjälpa till att försvara Lordaeron. Han litar på sin överordnades stridsförmåga, en berömd Grand Marshal som han beskriver som en lång, ståtlig hjälte. Truman är fortfarande bunden av sin plikt efter att ha fått order om att hålla linjen medan befälhavaren gav sig in i den pågående striden. Kaptenen misstror utomstående djupt och föraktar öppet dem han anser vara av en lägre ras. Han vägrar att lita på lokala irreguljära styrkor. När en duglig resenär närmar sig tar Truman tillfället i akt att be om hjälp. Han vädjar till någon att bege sig in i det ödelagda området, se efter sin herre och bedöma striden."},{t="Ruins of Lordaeron",b="Sökandet leder äventyrarna rakt in i de farliga Ruins of Lordaeron, den krossade huvudstaden som föll för Scourge under det tredje kriget. Captain Truman väntar sig att hans ärorika ledare ska stå triumferande över de fallna, men verkligheten i den pesthärjade staden är långt dystrare. Ruinerna vimlar av fasor, odöda rester och styggelser som strövar omkring på de sönderslagna stenlagda torgen. För att ta sig fram genom de ödelagda gatorna måste man konfrontera den brutala sanningen om vad som hände försvararna som gav sig in i staden. I stället för att hitta en oklanderlig riddare som håller linjen upptäcker resenärerna att befälhavaren mött ett tragiskt och förvridet slut bland monstren på gårdarna."},{t="En fasansfull upptäckt",b="När äventyrarna hittar den försvunne befälhavaren, som kallas baronen, gör de en fasansfull upptäckt: den en gång så ståtliga hjälten har förvandlats till ett groteskt odött monster. För att slutföra det dystra uppdraget måste de döda varelsen och ta med sig Head of the Baron tillbaka till Captain Truman. När Truman får se huvudet från sin tidigare herre reagerar han med chock, fasa och djup avsky. Kaptenen kan inte acceptera befälhavarens fruktansvärda öde och brister ut i bitter vrede. Han anklagar äventyraren för att stå på monstrens sida och svär att Lordaerons sanna söner en dag ska återta sitt land och rensa det från alla bestar."}},faq={{q="Vem ger uppdraget Abominable Creatures?",a="Uppdraget erbjuds av Captain Truman, en mänsklig lojalist som är stationerad i området kring det fallna riket. Han håller oroligt sin post medan han väntar på förstärkningar och söker desperat nyheter om sin befälhavare, en vördad Grand Marshal som gav sig in i närliggande Ruins of Lordaeron.",al={"vem ger abominable creatures","uppdragsgivare för abominable creatures","var startar abominable creatures"}},{q="Var utspelar sig uppdraget Abominable Creatures?",a="Uppdraget leder äventyrarna till Ruins of Lordaeron, den krossade huvudstaden som översvämmas av Scourges fasor och odöda rester. Captain Truman har en post utanför den pesthärjade huvudstaden och ber modiga resenärer att bege sig rakt in i de farliga ruinerna för att hitta hans försvunne överordnade.",al={"abominable creatures plats","var slutförs abominable creatures","abominable creatures zon"}},{q="Vem är Captain Trumans herre?",a="Captain Truman kallar sin herre för Grand Marshal och prisar honom som en lång, ståtlig militärhjälte. Uppdragsmålen kallar dock den försvunne adelsmannen för baronen, vilket visar att han var en högt uppsatt aristokrat och militär befälhavare som ledde rikets försvar.",al={"vem är trumans befälhavare","grand marshals identitet enligt truman","vem är baronen"}},{q="Vad hände med Grand Marshal i Ruins of Lordaeron?",a="Grand Marshal lyckades inte hålla stånd med segern i sikte. Han dödades och förvandlades till en monstruös odöd varelse i Ruins of Lordaeron. När äventyrarna hittar honom ser de en styggelse som kallas baronen. De tvingas förgöra honom och ta hans avhuggna huvud.",al={"vad hände med baronen","grand marshals öde","är grand marshal död"}},{q="Varför blir Captain Truman arg när du lämnar in uppdraget?",a="Captain Truman väntade sig att hans ståtlige befälhavare skulle vara vid liv och segerrik. När han får se baronens groteska, muterade huvud fylls han av fasa och avsky. Rasande anklagar han äventyraren för att dra ett sjukt skämt och umgås med vidriga bestar.",al={"varför är truman arg","trumans reaktion på abominable creatures","varför skriker truman åt dig"}},{q="Vad menar Captain Truman med ”Lordaerons sanna söner”?",a="Captain Truman använder uttrycket om nitiska mänskliga patrioter som är fast beslutna att återta sitt krossade hemland. Hans ord uttrycker en våldsam och intolerant vision där de rättmätiga mänskliga överlevarna ska rensa riket från alla odöda, bestar och personer som anses stå i förbund med dem.",al={"vad betyder lordaerons sanna söner","vilka är lordaerons sanna söner","truman och de sanna sönerna"}},{q="Varför vägrar Captain Truman att lita på ”halvblod”?",a="Captain Truman visar djupt förakt för icke-mänskliga raser och irreguljära allierade, som han avfärdar som opålitliga halvblod och avskum. Hans intensiva främlingsfientlighet hindrar honom från att anförtro sig åt någon annan än dem han anser vara rikets värdiga representanter.",al={"truman och halvblod","varför är captain truman rasistisk","trumans främlingsfientlighet"}}},fp="20,456,17.710.0,22.711.0,23.661.1,41.290.0,53.295.0,31.285.0,61.280.0,61.274.0,62.286.0,54.258.0"}
P.entries["quest:953"] = {n="The Fall of Ameth'Aran",s="Sentinel Tysha Moonblade skickar äventyrare till Ameth'Arans hemsökta ruiner i Darkshore för att tyda forntida stentavlor. Inskrifterna berättar om tragedin och förödelsen som drabbade Highborne-staden under Sundering. Kunskapen ska föras till Circle of Ancients i Auberdine, där man återupptäcker historia som till stor del gick förlorad under War of the Ancients.",h="Sentinel Tysha Moonblade skickar äventyrare till Ameth'Arans hemsökta ruiner i Darkshore för att tyda...",kw={"ameth'aran","auberdine","azshara","circle of ancients","darkshore","highborne","sundering","tavlor","tysha moonblade"},ang={["class:Mage"]="Tavlorna ger en skakande inblick i den elviska magins höjder före Sundering och den fruktansvärda förödelse som följde när kraften spårade ur.",["faction:Alliance"]="När du hjälper Sentinels att säkra Darkshores historia bevarar du viktig kunskap åt nattalvsledarna som vägleder Alliance på Kalimdor.",["race:NightElf"]="Ameth'Arans ruiner är en dyster påminnelse om dina förfäders övermod under drottning Azshara och de katastrofala följderna av otyglad arkanisk trolldom."},sec={{t="Highbornes ekon",b="Långt innan kusten sprack upp och blev Darkshores dimmiga vidder var Ameth'Aran en blomstrande bosättning, där drottning Azsharas främsta trollkarlar utövade mäktig arkansk magi. Efter Well of Eternitys katastrofala förstörelse för tiotusen år sedan återstod bara krossad marmor och spruckna pelare av staden. Än i dag hemsöks den av de rastlösa, plågade andarna från Highborne, som dog när deras guldålder slets sönder."},{t="Förlorade krönikor återfinns",b="War of the Ancients kastade nattalvernas civilisation in i en kaotisk kamp för överlevnad, och förvånansvärt få skriftliga berättelser överlevde Great Sundering oskadda. Sentinel Tysha Moonblade försökte själv undersöka ruinerna och fann två stora ingraverade tavlor, Lay of Ameth'Aran och Fall of Ameth'Aran, innan spöklika Highborne-vålnader tvingade henne att dra sig tillbaka. Genom att hämta avskrifterna kan sanningen om den forntida katastrofen nå de lärda i Circle of Ancients i Auberdine."}},faq={{q="Vad är Ameth'Aran?",a="Ameth'Aran är en forntida nattalvsruin i centrala Darkshore. För tiotusen år sedan var det en stad där drottning Azsharas Highborne-adelsmän öppet utövade och studerade storslagen arkansk magi, innan den föll under Great Sundering.",al={"ameth'aran historia","vad var ameth'aran","vem bodde i ameth'aran"}},{q="Varför finns det spöken i Ameth'Aran?",a="De rastlösa spöken som hemsöker ruinerna är andar från Highborne som levde och dog där. De fångades i den plötsliga, våldsamma katastrof som krossade Well of Eternity och splittrade Kalimdor, och deras andar förblir bundna till ruinerna i evig plåga.",al={"varför finns andar i ameth'aran","ameth'arans spöken","rastlösa highborne"}},{q="Vem är Sentinel Tysha Moonblade?",a="Sentinel Tysha Moonblade är en nattalvssentinel som är stationerad längs vägen i Darkshore. Hon fick i uppdrag att spana efter forntida platser och återfinna förlorade historiska dokument åt Circle of Ancients i Auberdine.",al={"tysha moonblade","vem ger fall of ameth'aran"}},{q="Varför vill Circle of Ancients att tavlorna ska läsas?",a="Förstörelsen av Well of Eternity kastade Kalimdor in i en enorm omvälvning och utplånade otaliga bibliotek och monument. Eftersom så få skriftliga dokument överlevde War of the Ancients ger tavlorna sällsynta ögonvittnesskildringar av Sundering ur Highbornes perspektiv.",al={"varför läsa tavlorna","circle of ancients tavlor","betydelsen av lay of ameth'aran"}},{q="Var finns tavlorna?",a="De två stora tavlorna, Lay of Ameth'Aran och Fall of Ameth'Aran, är inristade i stående stenmonument bland Ameth'Arans förstörda gårdar, omgivna av stadens tidigare invånares vandrande spöken.",al={"var finns ameth'arans tavlor","tavlornas platser","hur läser man ameth'aran"}},{q="Vad hände med Ameth'Arans Highborne under Sundering?",a="När Well of Eternity imploderade vid höjdpunkten av War of the Ancients slet enorma skakningar och arkaniska motreaktioner Kalimdor i stycken. Ameth'Aran rasade samman och begravde sina invånare, medan deras spöken blev kvar i rasmassorna.",al={"hur föll ameth'aran","ameth'arans förstörelse"}}},fx={["4f4506ec"]={q="Varför vill Sentinel Tysha Moonblade att det här blir gjort?",a="Sentinel Tysha Moonblade skickades på Circle of Ancients vägnar för att undersöka de uråldriga ruinerna. Uppteckningar från War of the Ancients och Sundering är ytterst sällsynta på grund av den tidens omvälvningar. Genom att samla in historien som ristats på tavlorna kan hon ge druiderna och de äldste i Auberdine en fullständig redogörelse.",al={"tysha moonblades motiv","varför behöver tysha detta","varför studera ameth'aran-tavlorna"}},["2329a43d"]={q="Varför behöver Sentinel Tysha Moonblade din hjälp?",a="Tysha gav sig tidigare in i Ameth'Aran för att själv undersöka tavlorna, men överfölls och drevs bort av de hämndlystna Highborne-andar som hemsöker ruinerna. Eftersom hon inte kan skriva av inskrifterna på ett säkert sätt under ständiga andeattacker behöver hon en skicklig äventyrare som kan ta sig in i ruinerna och tyda texten åt henne.",al={"varför kan inte tysha läsa tavlorna","varför behöver tysha mig","varför går inte tysha själv"}}},fp="22,288,23.311.0,26.424.0,19.227.0,35.210.0,32.210.0,56.306.0,30.204.0,66.216.0"}
P.entries["quest:95314"] = {n="That Shadowvale Green Elixir",s="Carolai Anise i Brill söker fynd från den övergivna bosättningen Shadowvale, djupt inne i den avskilda Whispering Forest. Innan riket föll var byn ökänd för att destillera Whispering Elixir från märkliga lokala örter, en kraftfull brygd som förblev eftertraktad på svarta marknaden även efter att den förbjudits i Lordaeron.",h="Carolai Anise i Brill söker fynd från den övergivna bosättningen Shadowvale, djupt inne i den avskilda...",kw={"apotekare","brill","carolai anise","gift","shadowvale","tirisfal","whispering elixir","whispering forest"},ang={["class:Rogue"]="Whispering Elixir var länge eftertraktat av olagliga giftblandare och skurkar som höll sig undan Lordaerons forna domares uppmärksamhet.",["profession:Herbalism"]="Elixiret får sin styrka från säregna örter som bara frodas under den avskilda Whispering Forests kusliga trädkrona.",["race:Undead"]="För Forsaken innebär återvinningen av Lordaerons bortglömda destillat både lönsam handel och experiment med apotekarkonst i det nya Undercity."},sec={{t="En förbjuden brygd",b="Långt före det tredje kriget och Scourges ankomst bryggde Shadowvales tillbakadragna invånare en särpräglad brygd som kallades Whispering Elixir. Den destillerades från sällsynta örter som bara fanns i Tirisfal Glades och blev ökänd i norra Lordaeron. Trots att den officiellt var förbjuden i Capital City gjorde dess ovanliga egenskaper den eftertraktad bland mystiker, giftblandare och apotekare som var beredda att trotsa kungliga dekret."},{t="Ruiner i Whispering Forest",b="Shadowvale ligger dolt djupt inne i Whispering Forest i västra Tirisfal. Byns invånare var historiskt sett slutna och misstrogna och välkomnade sällan främlingar. Efter Scourges invasion föll bosättningen i ruiner, men bortglömda förråd av den åldrade gröna elixiren finns kvar bland spillrorna. Carolai Anise håller till i Brill och drar nytta av den ihållande efterfrågan i undre världen genom att betala äventyrare som vågar sig in i skogens oroväckande tystnad."},{t="Den viskande förbannelsen",b="Carolai föredrar att avfärda rykten som ren vidskepelse, men Whispering Forest har ett mörkt rykte. Enligt lokal folktro är själva jorden och rötterna i skogen besmittade av en uråldrig förbannelse, som tränger direkt in i växterna som Shadowvales bryggare skördar. Vad det än är för kvardröjande ondska som hemsöker den övergivna byn har det knappast dämpat avlägsna köpares begär efter dess buteljerade rester."}},faq={{q="Vad är Shadowvale?",a="Shadowvale var en avskild by gömd i Whispering Forest i västra Tirisfal Glades. Invånarna var hemlighetsfulla enstöringar, främst kända för att destillera sällsynta brygder från den lokala vildmarken innan Scourge översvämmade området.",al={"var ligger shadowvale","vilka bodde i shadowvale","byn shadowvale"}},{q="Vad är Whispering Elixir?",a="Det är en kraftfull grön brygd gjord på unika örter från Tirisfal. Drycken var mycket eftertraktad av mystiker, giftblandare och apotekare och förbjöds i Capital City innan Lordaeron föll.",al={"vad gör elixiret","shadowvales gröna elixir i historien","whispering elixir"}},{q="Vem är Carolai Anise?",a="Carolai Anise är en företagsam Forsaken som bor i Brill. Hon förmedlar värdefulla och förbjudna kuriositeter och skaffar olagliga ingredienser som Shadowvales elixir för att sälja till intresserade köpare runtom i riket.",al={"carolai anise","vem ger uppdraget that shadowvale green elixir","uppdragsgivare i brill"}},{q="Varför förbjöds elixiret i Capital City?",a="Ingen anledning anges. Carolai säger bara att elixiret förbjöds i staden och att apotekare, mystiker och giftblandare ändå sökte efter det. En del tror att Whispering Forest är förbannad och att elixiret, destillerat från dess rötter, bär på samma förbannelse. Carolai avfärdar dock detta som vidskepelse och kopplar det aldrig till förbudet.",al={"varför var whispering elixir olagligt","är elixiret giftigt"}},{q="Varför anses Whispering Forest vara farlig?",a="Den avskilda skogen väster om Deathknell anses allmänt vara kuslig och förbannad. De som vågar sig dit berättar om en djup ondska och märkliga fenomen i skogen, som enligt rykten har besmittat örterna som växer ur dess jord.",al={"är whispering forest förbannad","whispering forests historia"}},{q="Vilka är köparna som vill ha elixiret?",a="Enligt Carolai Anise är flera köpare ivriga att få tag på överlevande flaskor från tiden före kriget, men hon säger inte vilka de är.",al={"vem köper elixiret","carolai anises köpare"}}},fx={["4d019fa8"]={q="Varför vill Carolai Anise att Whispering Elixir samlas in?",a="Carolai Anise skaffar sällsynta varor i Brill, och efterfrågan på den olagliga brygden har aldrig riktigt försvunnit. Många ivriga köpare ber henne om leveranser, så de flaskor som fortfarande är hela bland ruinerna kan ge en rejäl vinst.",al={"varför vill carolai ha elixiret","carolai anises motiv","varför samla whispering elixir"}}},fp="28,340,13.457.0,30.465.0,20.427.1,19.249.0,26.193.0,21.218.0,46.329.0,50.219.0,39.131.0"}
P.entries["quest:95328"] = {n="Whispering Horror Residue",s="Whispering Horror Residue är resterna av ett märkligt odjur som slingrar sig och hämtats från under Whispering Forest. Oförvägna äventyrare samlar in de av tomrummet berörda kvarlevorna och för dem till Father Lankester i Undercitys War Quarter för skuggforskning.",h="Whispering Horror Residue är resterna av ett märkligt odjur som slingrar sig och hämtats från under...",kw={"father lankester","skugga","tirisfal","undercity","tomrum","war quarter","whispering forest","whispering horror residue"},ang={["class:Priest"]="Förfallna skuggpräster som Father Lankester har ett starkt vetenskapligt och teologiskt intresse för exemplar från tomrummet. De ser märkliga kvarlevor från andra plan som studieobjekt snarare än rena avskyvärdheter.",["faction:Horde"]="Äventyrare i Hordens tjänst hämtar oroväckande exemplar från Tirisfal Glades dolda vildmarker för att understödja forskningen under huvudstadens ruiner.",["race:Undead"]="De Förfallna i Undercity studerar aktivt förbjuden magi och onaturlig fördärvning i hela Lordaeron. De söker utnyttja mörka fenomen för att stärka sitt osäkra grepp om kungariket."},sec={{t="En olustig skörd",b="Whispering Horror Residue består av bisarra, slingrande kvarlevor som skrapats upp från ett besegrat odjur under Whispering Forest. I stället för att överge denna onaturliga märklighet samlar driftiga äventyrare in det ryckande materialet i hopp om att forskare i Undercity ska kunna använda det till något gott."},{t="Studier i skuggan",b="Odjurets kvarlevor får en ivrig mottagare i Father Lankester, som finns i Undercitys War Quarter. Lankester påpekar att Whispering Forest länge har berörts av tomrummet och välkomnar chansen att undersöka fysiska rester av denna mörka fördärvning medan han utforskar skuggans mysterier."}},faq={{q="Vad är Whispering Horror Residue?",a="Whispering Horror Residue består av slingrande kroppsliga kvarlevor från ett märkligt odjur som besegrades under Whispering Forest. Trots sin olustiga natur är det värdefullt för forskare inom skuggmagi och deras arkana och ockulta studier.",al={"vad är resterna","vad är whispering horror residue","föremål med rester"}},{q="Vem vill ha Whispering Horror Residue?",a="Resterna lämnas till Father Lankester, en Förfallen som finns i Undercitys War Quarter. Han välkomnar möjligheten att utforska skuggans mysterier och fenomen berörda av tomrummet.",al={"vem tar emot resterna","vem är father lankester","var lämnar man in resterna"}},{q="Varifrån kommer detta exemplar?",a="Exemplaret kommer från under Whispering Forest, en olycksbådande skog väster om Deathknell i Tirisfal Glades. Som Father Lankester påpekar är det känt att det motbjudande området har berörts av tomrummet.",al={"var kommer odjuret ifrån","whispering forests historia","under whispering forest"}},{q="Varför vill Father Lankester ha resterna?",a="Father Lankester vill studera skuggans och tomrummets mysterier. För Förfallna som utforskar förbjudna konster erbjuder fysiska rester från tomrumsbesmittade varelser sällsynta insikter och forskningsmaterial.",al={"varför vill lankester ha detta","skuggforskning i undercity","varför studera resterna"}},{q="Var hittar man Father Lankester?",a="Father Lankester håller till i Undercitys War Quarter. War Quarter är ett livligt centrum för Förfallna krigare, lärda och militära strateger under ruinerna av Lordaerons huvudstad.",al={"var ligger war quarter","var finns lankester","lankesters plats i undercity"}},{q="Har Whispering Forest berörts av tomrummet?",a="Whispering Forest har länge haft ett ondskefullt rykte bland invånarna i Tirisfal. Father Lankester påpekar att det inte är någon hemlighet att den motbjudande skogen och utrymmena under den har berörts av tomrummet.",al={"är whispering forest fördömd","tomrumsfördärv i whispering forest","vad berör whispering forest"}}},fp="25,256,21.318.0,17.307.0,38.242.0,40.195.0,34.206.0,43.211.0,36.195.0,45.212.0"}
P.entries["quest:95349"] = {n="The Earthen Ring",s="Den här färden markerar Windshapers ankomst från Zephras till Azeroth som en förtrupp, efter förseningar orsakade av kultister i Valanaar. Resenärerna går ombord på ett skycutter-skepp utanför lodgen och går i land i Mulgore för att möta Alaana Stormwalker och börja vänja sig vid en vidsträckt och farlig ny värld.",h="Den här färden markerar Windshapers ankomst från Zephras till Azeroth som en förtrupp, efter förseningar...",kw={"alaana stormwalker","banu-alah","kult","mulgore","skycutter","the earthen ring","valanaar","windshapers","zephras"},ang={["class:Shaman"]="Windshapers och shamaner hyser en djup vördnad för elementen och förlitar sig på vindarnas välvilja för att vägleda dem under färden genom luften. Deras ankomst under The Earthen Rings fana knyter dem direkt till de elementära traditioner som slår rot i Mulgore.",["race:Skyborne"]="För Skyborne-äventyrare som lämnar Valanaar markerar färden deras historiska ankomst till Azeroth som en förtrupp. De lämnar kultproblemen i hemlandet bakom sig och tar sina första steg på Mulgore slätter.",["race:Tauren"]="Som Mulgore ursprungliga vårdare bevittnar Tauren ankomsten av nya resenärer från Zephras till sina förfäders slätter. Genom att välkomna dessa himmelsfarare knyter de tidigt band till allierade som etablerar ett fäste i deras länder."},sec={{t="Avfärd från Valanaar",b="Resenärer på väg till Azeroth måste ändra sina planer på grund av de senaste störningarna som kultens verksamhet orsakat i Valanaar. Medan de högsta ledarna stannar kvar vid lodgen för att slutföra brådskande ärenden och hejda kultisthotet skickas en liten förtrupp av Windshapers i förväg. Pionjärerna beger sig till hamnen strax utanför lodgen och går ombord på ett skycutter-fartyg som ska färdas över himlen. Befälhavarna lovar att snart ansluta, men den första expeditionen vilar helt på förtruppens axlar. Den skickas i förväg för att etablera en närvaro innan resten kan följa efter."},{t="Ankomst till Mulgore",b="När äventyrarna från Zephras landar på Mulgore slätter välkomnas de av Alaana Stormwalker. Det tar tid och kräver omsorgsfullt arbete att etablera ett fäste i Azeroth, så nykomlingarna uppmuntras att utforska trakten och vänja sig vid sin nya omgivning. Vindarna är gynnsamma för expeditionen, men Azeroth är fortfarande ett främmande och farligt rike. Att lära känna den lokala terrängen, djurlivet och grannfolken är ett viktigt första steg innan de återstående resenärerna från Valanaar anländer för att hjälpa till."}},faq={{q="Varför reser Windshapers till Azeroth?",a="En förtrupp av Windshapers skickas i förväg för att etablera en närvaro i Azeroth medan deras ledare stannar kvar i Valanaar. Nyliga problem med en lokal kult störde de ursprungliga resplanerna och försenade resten av gruppen. Därför färdas förtruppen ensam i förväg för att gå i land och säkra ett fäste tills förstärkningarna kan följa efter.",al={"varför resa till azeroth","windshapers uppdrag","varför är windshapers i mulgore"}},{q="Vem är Alaana Stormwalker?",a="Alaana Stormwalker är kontaktpersonen som väntar på att ta emot Windshapers när de landar i Mulgore. Hon välkomnar resenärer från Zephras och konstaterar att det kommer att ta tid att etablera en trygg närvaro i de nya länderna. Medan förberedelserna inleds råder hon de nyanlända äventyrarna att utforska trakten och förbereda sig på farorna i Azeroth.",al={"vem är alaana","alaana stormwalkers roll","var finns alaana stormwalker"}},{q="Varför försenades huvudavfärden?",a="Huvudresan från Valanaar sköts upp på grund av oroande händelser med en lokal kult. Problemen med kultisterna tvingade expeditionens ledare att stanna kvar vid lodgen för att slutföra sina ärenden. I stället för att avbryta uppdraget helt skickade de en liten förtrupp av Windshapers med ett skycutter-fartyg för att bana väg till Azeroth.",al={"varför blev det försenat","vilken kult försenade resan","varför stanna i valanaar"}},{q="Hur reser man från Valanaar till Mulgore?",a="Resenärerna gör resan genom att gå ombord på ett skycutter-skepp som ligger förtöjt strax utanför lodgen i Valanaar. Fartyget för förtruppen genom luften till Mulgore slätter och är den främsta transportförbindelsen mellan Zephras och Azeroths länder under den första expeditionen.",al={"hur tar man sig till mulgore","var finns skeppet","hur reser man till azeroth"}},{q="Vad är Zephras?",a="Zephras är hemtrakten eller ursprunget för äventyrarna som anländer med skycutter-fartyget. När resenärerna når Mulgore beskriver Alaana Stormwalker dem som nykomlingar från Zephras och säger att gynnsamma vindar har lett dem genom luften till Azeroths främmande och farliga områden.",al={"var ligger zephras","vad är zephras","zephras historia"}},{q="Vad bör äventyrare göra när de anländer till Mulgore?",a="Nyanlända äventyrare uppmuntras att rekognosera och utforska Mulgore med omnejd. Eftersom det tar tid att etablera ett fast fäste är det viktigt att lära känna den närliggande terrängen, varelserna och de lokala hoten inför färder genom denna spännande men farliga nya värld.",al={"vad ska man göra i mulgore","nästa steg efter ankomsten","vad ska man göra härnäst"}}},fp="16,317,23.583.0,18.573.0,45.356.0,26.381.0,35.358.0,50.281.0,16.299.0,52.302.0"}
P.entries["quest:95350"] = {n="Welcome to Azeroth",s="'Welcome to Azeroth' är ett introduktionsuppdrag som skickar en resenär från Thunder Bluff till Orgrimmar på Windshapers vägnar. Med Earthen Rings andliga band som vägledning möter sändebudet krigshövding Thrall för att knyta överlevnadsband och skapa en allians med Horden.",h="'Welcome to Azeroth' är ett introduktionsuppdrag som skickar en resenär från Thunder Bluff till Orgrimmar på...",kw={"earthen ring","horden","orgrimmar","thrall","thunder bluff","visdomens dal","welcome to azeroth","windshapers"},ang={["class:Shaman"]="Med vägledning från Earthen Ring och vindarnas välsignelse knyter resan samman andliga fränder med schamanledarskapets hjärta i Visdomens dal.",["faction:Horde"]="Det diplomatiska uppdraget formaliserar banden med Horden och presenterar nykomlingarna direkt för krigshövding Thrall som viktiga allierade för överlevnad i Kalimdor.",["race:Skyborne"]="Från de höga höjderna ner till ytvärlden söker Skyborne Windshapers kontakt med Thunder Bluff och Orgrimmar för att säkra sin plats bland nya allierade."},sec={{t="Allierade i en större värld",b="När nykomlingar ger sig ut i Kalimdors vidsträckta vildmarker upptäcker de snabbt att överlevnad bygger på gemenskap. Windshapers blickar bortom sitt isolerade ursprung mot folken där nere och inser att isolering inte skyddar mot Azeroths hot. Genom att sträcka ut en hand till taurenstaden Thunder Bluff och blicka mot orkernas fästen i öster söker de pålitliga följeslagare att möta vildmarken tillsammans med."},{t="Ett möte med krigshövdingen",b="Resan för sändebuden till Thunder Bluffs höga torn innan de leds över The Barrens till Orgrimmar, Hordens mäktiga huvudstad. I den stillsamma Visdomens dal väntar krigshövding Thrall, koalitionens vägledande kraft. Mötet med Thrall markerar Windshapers officiella inträde i Kalimdors politiska och andliga gemenskap, förenade av ett gemensamt mål och respekt för elementen."}},faq={{q="Vad är syftet med uppdraget Welcome to Azeroth?",a="'Welcome to Azeroth' är ett diplomatiskt introduktionsuppdrag där ett sändebud på Windshapers vägnar skickas för att möta krigshövding Thrall i Orgrimmar. Det är en officiell presentation för den större Horden och Kalimdors ytvärld.",al={"vad är det här för uppdrag","uppdraget welcome to azeroth","syftet med welcome to azeroth"}},{q="Vilka är Windshapers?",a="Windshapers är en grupp som sträcker sig från höjderna mot allierade på marken och söker överlevnad genom gemenskap med Earthen Ring och Horden. De skickar resenärer för att tala direkt med Hordens ledare i Durotar.",al={"vilka är windshapers","vad är windshapers"}},{q="Varför skickas du för att tala med Thrall?",a="Som Hordens krigshövding och en vördad schamanledare övervakar Thrall koalitionens viktigaste allianser från Visdomens dal. Kontakten med honom formaliserar relationerna mellan Windshapers och Horden.",al={"varför besöka thrall","tala med thrall i orgrimmar","varför åka till orgrimmar"}},{q="Hur reser du från Thunder Bluff till Orgrimmar?",a="Resenärer flyger från flygmästaren vid Thunder Bluffs centrala rastplats och svävar österut över Kalimdors slätter till Orgrimmars kanjonfäste.",al={"hur tar man sig till orgrimmar","flygmästaren i thunder bluff","från thunder bluff till orgrimmar"}},{q="Vilken roll spelar Earthen Ring i det här uppdraget?",a="I det här mötet beskrivs Earthen Ring som en del av Hordens koalition av likasinnade folk. De hjälper till att knyta band mellan schamanfraktioner och Kalimdors nationer.",al={"earthen rings roll i horden","är earthen ring med i horden"}},{q="Var finns Thrall i Orgrimmar?",a="Krigshövding Thrall bor i Visdomens dal, en stillsam andlig fristad i Orgrimmars västra delar där schamaner och stammarnas rådgivare samlas.",al={"var finns thrall","thralls plats i visdomens dal"}}},fp="18,275,25.456.0,29.431.0,52.238.0,24.215.0,38.218.0,50.177.0,48.190.0,37.159.0"}
P.entries["quest:954"] = {n="Bashal'Aran",s="De demoniska satyrerna och de våldsamma grellerna som hemsöker den uråldriga Night Elf-staden Bashal'Aran närmar sig inte en helgedom, badande i ett övernaturligt blått sken. Thundris Windweaver, Auberdines äldste, skickar äventyrare för att undersöka källan till denna orörda fristad.",h="De demoniska satyrerna och de våldsamma grellerna som hemsöker den uråldriga Night Elf-staden Bashal'Aran...",kw={"asterion","bashal'aran","blått sken","darkshore","grell","kaldorei-ruiner","satyr","thundris windweaver"},ang={["faction:Alliance"]="Auberdines spejare förlitar sig på Alliance-vandrare som tränger in i Darkshores omstridda ruiner och undanröjer demoniska hot innan de når kusten.",["race:NightElf"]="Bashal'Aran är en dyster påminnelse om det som gick förlorat under Sundering, där dina uråldriga fränders kvardröjande andar fortfarande håller ensamma vakor mot den annalkande demoniska korruptionen."},sec={{t="En fyr bland ruinerna",b="Bashal'Aran var en gång en storslagen bosättning i det uråldriga Kaldorei-imperiet, men dess krossade marmor och igenvuxna valv vimlar nu av demonisk smitta. Förvridna satyrer och korrumperade greller livnär sig girigt på ruinernas kvarvarande magiska energier, och deras ondska växer för varje dag som går. Trots deras rovgiriga herravälde upptäckte Thundris Windweaver i Auberdine något märkligt: på en västlig klippa i ruinerna brinner ett eteriskt blått sken över en helgedom som ingen demon närmar sig."},{t="Den sårade anden",b="Om du trotsar demonernas patruller och når den upphöjda helgedomen upptäcker du att det blå ljuset inte är något naturligt fenomen. Det kommer från Asterion, en uråldrig ande vars vaka har fortsatt genom århundraden av ensamhet. Omgiven av ylande bestar och vidriga vidunder ser den utmattade anden till och med en resande främling som en välkommen paus efter årtionden av isolering."}},faq={{q="Var finns det blå skenet?",a="Det blå skenet lyser på toppen av en liten upphöjd klippa vid ruinernas västra kant i Bashal'Aran, strax öster om Auberdine i Darkshore. Platsen ligger något högre än de omkringliggande, sönderfallande murarna.",al={"hitta blått sken","var finns asterion","bashal'aran helgedomens plats"}},{q="Varför undviker satyrerna helgedomen?",a="Ingen vet ännu. Ett märkligt blått sken genomsyrar helgedomen, och de demoniska satyrerna och grellerna som annars hemsöker ruinerna närmar sig den inte. Thundris Windweaver skickar dig för att hitta skenets källa.",al={"varför fruktar demoner","varför håller sig satyrerna borta"}},{q="Vem skickar dig på det här uppdraget?",a="Thundris Windweaver, en Night Elf-druid och Auberdines äldste, ger dig uppdraget efter att ha lagt märke till de onaturliga demonrörelserna i de östra ruinerna.",al={"vem ger uppdraget","uppdragsgivare","thundris windweavers plats"}},{q="Vad är Bashal'Aran?",a="Bashal'Aran är en uråldrig kaldorei-ruin inbäddad i Darkshores skogar. Den plundrades under det uråldriga Sundering och har sedan dess hemsökts av magiska parasiter, greller och satyrer som söker sig till dess slumrande ley-krafter.",al={"vad hände med bashal'aran","bashal'arans historia"}}},fx={["2cba9e48"]={q="Varför vill Thundris Windweaver att jag undersöker Bashal'Aran?",a="Thundris Windweaver betraktar Bashal'Arans uråldriga ruiner med växande oro. Fördärvade sprites och satyrs svärmar över området och utnyttjar kvarvarande arkana energier för att förstärka sin demoniska kraft. Men mitt i denna invasion står en enda helgedom, omgiven av en märklig blå aura, helt orörd av demonerna. Thundris måste förstå vilken kraft som håller dem borta och om den kan vara nyckeln till att hejda fördärvet som tränger in i Darkshore.",al={"varför undersöka bashal'aran","thundris motiv","varför skicka mig till bashal'aran"}}},fp="11,163,21.382.0,17.246.1,31.192.0,35.147.0,28.136.0,20.171.0"}
P.entries["quest:95494"] = {n="Bruised Pride and Lion Hides",s="Bruised Pride and Lion Hides är ett uppdrag där du hjälper en skadad jägare eller hantverkare som behöver råa lejonhudar för att uppfylla ett handelsavtal med en lokal garvare. På grund av sina skador kan personen inte jaga säkert och förlitar sig på resande äventyrare som kan leverera materialet och värna om personens oklanderliga yrkesrykte.",h="Bruised Pride and Lion Hides är ett uppdrag där du hjälper en skadad jägare eller hantverkare som behöver råa...",kw={"bruised pride and lion hides","jakt","lädervaror","lejonhudar","garvare","handel"},sec={{t="En jägares dilemma",b="I Bruised Pride and Lion Hides hjälper du en skadad jägare som inte kan spåra vilda djur efter en nylig skada. För att inte svika ett pågående handelsavtal med en lokal hantverkare anlitar jägaren en äventyrare som kan spåra upp vilda lejon och samla in deras hudar."},{t="Hålla överenskommelsen",b="De insamlade råhudarna byts mot färdig läderutrustning hos en lokal garvare, något uppdragsgivaren behöver för sin försörjning. Trots sina skador och den sårade stoltheten över att behöva hjälp utifrån ser uppdragsgivaren till att hålla avtalet och bevara sitt yrkesrykte."}},faq={{q="Vad handlar det här uppdraget om?",a="Lejonhudarna samlas in åt en skadad jägare eller handelsman som levererar råmaterial till en lokal garvare. I utbyte mot hudarna får uppdragsgivaren färdiga lädervaror som är nödvändiga för försörjningen.",al={"vad är bruised pride and lion hides","uppdragets mål","vad ska lejonhudarna användas till"}},{q="Varför behöver uppdragsgivaren hjälp med att samla in hudar?",a="Uppdragsgivaren har skadat sig och kan inte jaga lejonen själv. I stället för att bryta ett långvarigt affärsavtal med en lokal garvare förlitar sig uppdragsgivaren på äventyrare som kan sköta leveransen.",al={"varför behövs hjälp","varför kan de inte jaga"}},{q="Vem får lejonhudarna?",a="Råhudarna byts med en lokal garvare. Garvaren bereder dem till färdiga lädervaror som uppdragsgivaren behöver för sitt vanliga arbete och sina affärer.",al={"vem får lejonhudarna","vart tar hudarna vägen"}},{q="Vad betyder namnet ”Bruised Pride and Lion Hides”?",a="Titeln anspelar på två saker: en bokstavlig flock lejon som måste jagas och jägarens stolthet, som fått sig en törn eftersom jägaren aldrig tidigare har misslyckats med att leverera enligt ett avtal, trots sina nuvarande fysiska begränsningar.",al={"betydelsen av bruised pride","varför heter det bruised pride"}},{q="Var överenskommelsen med garvaren i fara?",a="Ja. Skadan hindrar uppdragsgivaren från att jaga, vilket riskerar nästa leverans. Genom att samla in lejonhudarna kan uppdragsgivaren hålla sin del av avtalet och undvika att leverera för lite.",al={"håller överenskommelsen med garvaren","bröts handelsavtalet"}},{q="Hur skadades uppdragsgivaren?",a="Uppdragsgivaren skadade sig så att hen inte kan jaga lejon i vildmarken, men den exakta orsaken till skadan nämns inte. Genom att leverera hudarna kan uppdragsgivaren bevara sitt rykte.",al={"uppdragsgivarens skada","vad hände med jägaren"}}},fp="28,309,18.278.0,24.292.0,25.213.0,51.201.0,28.161.0,55.206.0,44.183.0,32.203.0"}
P.entries["quest:95495"] = {n="The Hermit Tanner",s="The Hermit Tanner är ett lokalt leveransuppdrag i The Barrens där äventyrare bär ett knippe råhudar till en tillbakadragen hantverkare som bor på en ås med utsikt över The Dry Hills. Uppdraget visar hur avlägsna samarbeten håller savannens handel igång och introducerar en isolerad, slående eremit som upprätthåller regelbunden handel trots sin avskildhet.",h="The Hermit Tanner är ett lokalt leveransuppdrag i The Barrens där äventyrare bär ett knippe råhudar till en...",kw={"the barrens","bundle of hides","the dry hills","the hermit tanner","ås","garvare","vrang"},ang={["faction:Horde"]="Resenärer genom den centrala savannen hjälper ofta lokala handlare som Vrang att transportera viktiga handelsvaror genom The Barrens oländiga terräng."},sec={{t="En ås i The Barrens",b="The Barrens karga savann främjar handel mellan tåligt folk, även om inte alla hantverkare föredrar det livliga tempot vid vägskäl och boplatser. I skuggan av The Dry Hills byter en handlare vid namn Vrang regelbundet varor med en tillbakadragen garvare som har byggt ett stillsamt hem på åsen med utsikt över landskapet. Eftersom den branta vandringen uppför den klippiga sluttningen är för ansträngande för Vrang, förlitar han sig på förbipasserande äventyrare som kan bära knippen med råhudar upp till hans avskilda samarbetspartner."},{t="En ovanlig hantverkare",b="Innan Vrang skickar iväg resenärer ser han till att ge en tydlig varning om den ensamme hantverkaren. Eremiten har ett oroande och ovanligt utseende som kan skrämma ovetande besökare, men Vrang försäkrar att den tillbakadragne garvaren inte utgör någon fara för gäster. När eremiten tar emot råhudarna vid sitt hem på åsen välkomnar han budbäraren varmt, men beklagar att Vrang inte kunde ta sig upp, eftersom det finns något han hoppades få tala med handlaren om personligen."}},faq={{q="Vem skickar dig med leveransen?",a="En handlare vid namn Vrang ordnar uppdraget och ber en förbipasserande resenär leverera ett knippe råhudar till en affärspartner som bor på åsen ovanför.",al={"vem ger uppdraget the hermit tanner","var börjar uppdraget","vrang leverans"}},{q="Var bor eremitgarvaren?",a="Eremitgarvaren bor ensam i ett avskilt hem på den höga åsen med utsikt över The Dry Hills i The Barrens.",al={"eremitgarvarens plats","var finns eremitgarvaren","eremit på åsen"}},{q="Varför varnar Vrang dig för garvarens utseende?",a="Vrang varnar resenärer i förväg för att inte låta sig skrämmas av garvarens ovanliga eller obehagliga utseende. Han bedyrar att eremiten inte utgör något hot mot besökare, trots sitt utseende.",al={"eremitens utseende","varför ser eremiten skrämmande ut"}},{q="Varför kunde inte Vrang själv ta sig upp?",a="Vrang förklarar att han just nu inte lätt kan klara den branta klättringen uppför den oländiga sluttningen på egen hand, så han anlitar i stället ett bud.",al={"varför behövs leveransen","varför kan vrang inte ta sig upp"}},{q="Vilka varor levereras upp till åsen?",a="Leveransen består av ett knippe hudar avsedda för eremitens garveriverksamhet, ett hantverk som de båda regelbundet samarbetar kring.",al={"vad är ett knippe hudar","varor som levereras i uppdraget"}},{q="Vad vill eremitgarvaren tala med Vrang om?",a="När garvaren tar emot leveransen beklagar han att Vrang inte kunde komma upp personligen och nämner att han har något han behöver tala direkt med Vrang om.",al={"vad vill garvaren med vrang","garvarens affärer med vrang"}}},fp="17,338,22.499.0,27.508.0,31.149.0,34.115.0,54.177.0,42.169.0,44.131.0,55.178.0"}
P.entries["quest:955"] = {n="Bashal'Aran",s="Asterion, en sorgsen highborne-ande som hemsöker de gamla ruinerna i Bashal'Aran, söker ett sätt att häva bindningsmagin som håller hans vålnadsgestalt fången. Han tror att de busiga lokala grellarna har rört vid sigillet som håller honom kvar och ber därför resenärer samla in deras örhängen för att spåra dess kvarvarande magiska resonans.",h="Asterion, en sorgsen highborne-ande som hemsöker de gamla ruinerna i Bashal'Aran, söker ett sätt att häva...",kw={"asterion","bashal'aran","bindning","darkshore","spöke","grell","grell earring","sigill"},ang={["class:Mage"]="Asterions metod att använda förtrollade prydnader för att spåra kvarvarande magiska utstrålningar speglar uråldriga Highborne-metoder för magisk spådom.",["faction:Alliance"]="När de kaotiska grellarna kring Bashal'Aran drivs bort blir de förrädiska norra delarna av Darkshore tryggare för Alliansen.",["race:NightElf"]="För Kaldorei är mötet med Asterion en bister påminnelse om den uråldriga civilisation som föll under Sunderingen och lämnade plågade själar bundna i ruinerna i årtusenden."},sec={{t="En plåga genom århundraden",b="Bland Bashal'Arans krossade marmor dröjer Asterion, en uråldrig Night Elf-ande som uthärdat århundraden i fångenskap. Fångad mellan liv och verklig död har hans existens förfallit till en plågsam väntan under Darkshores trädkronor. Han är bunden direkt till den förstörda bosättningen genom magisk konst och saknar medel att själv bryta sina bojor; hans sinne har nötts ned av oräkneliga år av ensamhet och förtvivlan."},{t="Spår i vildmarken",b="Asterion misstänker att nyckeln till hans befrielse är ett uråldrigt sigill som gömts någonstans i ruinerna. Han kan inte själv söka igenom snåren och de rasade stenarna, men de vilda grellarna som härjar i Bashal'Aran letar ständigt efter föda och stjäl små prydnader. Asterion ber resenärer samla in örhängena som dessa varelser bär, så att han kan läsa av de magiska avtryck som finns kvar på smyckena och hitta sigillet som plågar hans själ."}},faq={{q="Vem är Asterion?",a="Asterion är ett uråldrigt Night Elf-spöke som är bundet till ruinerna i Bashal'Aran i Darkshore. Ett mystiskt sigill har hållit honom fången i århundraden, och han har sett tidsåldrar passera i plåga medan han längtat efter att befrias från sitt vålnadstillstånd.",al={"asterions historia","vem är spöket i bashal'aran","asterion uppdragsgivare"}},{q="Varför vill Asterion ha grellörhängen?",a="Grellar är ökända asätare som samlar på glänsande prydnader och smycken. Asterion tror att varelserna har rört vid det magiska sigill som håller honom fången, så deras örhängen kan ha tillräckligt med magiska rester för att hjälpa honom hitta det.",al={"varför grellörhängen","grellörhängenas syfte","örhängeuppdrag i darkshore"}},{q="Vad är Bashal'Aran?",a="Bashal'Aran är en uråldrig Night Elf-ruin vid Darkshores skogsklädda kust, från tiden före den stora Sunderingen. Den är översvämmad av vilda grellar, satyrer och vålnadsrester från dess sedan länge fallna invånare.",al={"vad är bashal'aran","bashal'arans historia","ruinerna i bashal'aran"}},{q="Vad händer när örhängena har samlats in?",a="Asterion undersöker örhängena och känner att grellarna inte bär på själva sigillet, men att de har snuddat vid det i vad han anser vara relativt nyligen. Spåret hjälper honom att ringa in dess plats i ruinerna.",al={"vad visar örhängena","hade grellarna sigillet","resultat av grellörhänget"}},{q="Varför är Asterion fången här?",a="Asterion bands till Bashal'Aran av ett uråldrigt magiskt sigill som skapades för århundraden sedan. Bindningen förankrar hans ande vid ruinernas fysiska plats och hindrar honom från att gå vidare till en fridfull vila.",al={"vem band asterion","hur är asterion bunden","asterions sigill"}},{q="Vad är grellar?",a="Grellar är små, illvilliga skogsvarelser som hör hemma i Kalimdors skogar. De är kända för sitt busiga lynne, sina vassa klor och sin kärlek till prydnadssaker. De härjar ofta i gamla ruiner och angriper resenärer på väg förbi.",al={"vad är en grell","grellarnas historia","grellar i darkshore"}}},fx={["99bf1a9e"]={q="Varför vill Asterion att det här blir gjort?",a="Asterion är fångad i en plågsam andeskepnad, bunden till Bashal'Arans ruiner av en uråldrig magisk sigill. Århundraden av fångenskap har långsamt brutit ner hans förstånd, och han längtar efter att befrias från plågan. Genom att undersöka örhängena som de lokala varelserna bär hoppas han magiskt kunna skåda sigillformens exakta plats, så att den till sist kan förstöras.",al={"asterions motiv","varför hjälpa asterion","varför vill asterion ha örhängen"}},a8a71265={q="Varför behöver Asterion din hjälp i stället för att agera själv?",a="Asterion är ett formlöst spöke som bundits direkt till ruinerna av mäktig trolldom. Han kan varken färdas långt från sin viloplats eller själv strida fysiskt mot grells och sprites. Därför är han helt beroende av förbipasserande dödliga som jagar varelserna och samlar in deras prydnader åt hans spådomar.",al={"varför behöver asterion mig","varför kan inte asterion hämta örhängena","varför kan inte asterion lämna platsen"}}},fp="11,221,23.325.0,18.348.0,16.189.0,38.165.0,20.194.0,43.230.1,29.145.0,16.181.0"}
P.entries["quest:956"] = {n="Bashal'Aran",s="Asterion, en Night Elf-ande fångad bland Bashal'Arans ruinerade pelare, söker reliken som håller honom bunden till denna värld. Han har känt av fångenskapens fördärv bland traktens grells och skickar resande på jakt efter satyrerna som styr dem och efter Ancient Moonstone Seal.",h="Asterion, en Night Elf-ande fångad bland Bashal'Arans ruinerade pelare, söker reliken som håller honom bunden...",kw={"ancient moonstone seal","asterion","bashal'aran","darkshore","grell","kaldorei","night elf-spöke","satyr"},ang={["class:Druid"]="Satyrernas förvridna inflytande fortsätter att fördärva Darkshores vilda djur och störa uråldriga andar som borde vila fridfullt i naturens kretslopp.",["faction:Alliance"]="När ruinerna i Darkshore renas från satyrernas fördärv säkras Kalimdors nordkust och Kaldorei får hjälp att låta sitt tragiska förflutna vila.",["race:NightElf"]="Bashal'Aran är en dyster påminnelse om ditt folks uråldriga förflutna, där kvarlevande förfäder hålls fastkedjade vid jorden av satyrer som förkroppsligar den demoniska förrädelsen under Sundering."},sec={{t="Ett fängelse av uråldrig sten",b="I långt över tusen år har anden Asterion varit bunden till Bashal'Arans fallna ruiner. Marmorpelarna runt omkring utgör en obeveklig bur som varken hans avtagande andliga krafter eller hans uråldriga magi kan krossa. Bunden av en förbannad relik har han tillbringat århundraden med att blicka ut över Darkshores dimhöljda trädkronor och undra om ens stenens nötning skulle kunna befria honom."},{t="Satyrerna och Moonstone Seal",b="När Asterion upptäckte att närliggande grells bar spår av magin som höll honom fången, drog han slutsatsen att satyrerna som styr de kaotiska varelserna hade lagt beslag på förtrollningens källa. Dessa demoniska Night Elves strövar genom de uråldriga dungarna och håller Ancient Moonstone Seal under uppsikt. Att återta denna talisman är det avgörande steget mot att krossa de osynliga galler som håller Asterion bunden till hans helgedom."}},faq={{q="Vem är Asterion?",a="Asterion är ett uråldrigt Night Elf-spöke fångat i Bashal'Arans ruiner. Bunden av uråldrig magi har han tillbringat mer än tusen år inspärrad bland helgedomens stående pelare, oförmögen att gå vidare eller lämna sitt stenfängelse.",al={"vem är asterion","asterions historia","spöke i bashal aran"}},{q="Varför har satyrerna Ancient Moonstone Seal?",a="Satyrerna leder och påverkar de vilda grells som angriper norra Darkshore. Eftersom grells bar spår av den bindande magin förstod Asterion att deras onda satyrmästare hade beslagtagit Ancient Moonstone Seal för att hålla traktens andar plågade och bundna.",al={"varför har satyrerna sigillet","satyrernas moonstone seal","ancient moonstone seal"}},{q="Vad händer när sigillet återtas?",a="Asterion får tag i själva reliken som har bundit honom i århundraden. Att återta Ancient Moonstone Seal är det näst sista steget mot hans befrielse. Då kan sigillet krossas, så att han äntligen får vandra fritt i skogarna igen.",al={"vad gör sigillet","återta sigillet"}},{q="Vad är Bashal'Aran?",a="Bashal'Aran är en uråldrig Night Elf-ruin längs norra Darkshores dimhöljda stränder. Den var en gång en storslagen bosättning eller helig enklav, men ligger nu i ruiner och hemsöks av grells, satyrer och fångade andar från en svunnen tid.",al={"bashal arans historia","vad är bashal aran"}},{q="Hur länge har Asterion varit fången här?",a="Asterion har varit fängslad i mer än tusen år. Utan fysiska medel eller magi för att bryta gränsen tvingades han vänta genom århundradena och undra om han någonsin skulle bli fri.",al={"hur gammal är asterion","hur länge fången"}},{q="Kan Asterion bara gå sin väg från helgedomen?",a="Nej. Ancient Moonstone Seal upprätthåller en metafysisk barriär runt helgedomen. Stenpelarna fungerar som en ogenomtränglig bur som hindrar hans spöklika gestalt från att ta sig utanför dem.",al={"kan asterion lämna platsen","varför är spöket fångat"}}},fx={["31aed888"]={q="Varför vill Asterion att sigillet hämtas?",a="Asterion är desperat efter frihet. Den uråldriga reliken är ankaret som håller honom fången för evigt och hans ande instängd i den förfallna helgedomen. I över tusen år har han blickat bortom stenpelarna utan att kunna bryta deras grepp med vare sig styrka eller trolldom. Att hämta artefakten är det enda sättet att förstöra den och äntligen låta honom vandra fritt i skogarna igen.",al={"varför vill asterion att det här blir gjort","asterions motiv","varför hjälpa asterion"}},["5f1ff286"]={q="Vad är Ancient Moonstone Seal?",a="Ancient Moonstone Seal är en magisk relik som fungerar som nyckeln till Asterions fångenskap. Den skapar en ogripbar barriär mellan Bashal'Arans pelare, som en evig cell som ingen besvärjelse eller fysisk styrka kan krossa. Så länge sigillet finns i de närliggande fördärvade krafternas händer förblir Asterion bunden till helgedomen.",al={"vad är ancient moonstone seal","vad gör moonstone seal","ancient moonstone seals syfte"}},c7650517={q="Varför skickas du mot de lokala satyrs?",a="Satyrs styr de vidriga grells som svärmar över Bashal'Arans ruiner. Eftersom de mindre grells bar spår av sigillets förtrollning drog Asterion slutsatsen att deras herrar måste ha tagit själva artefakten. Satyrs är fördärvade och dras till uråldriga magiska reliker. De håller sigillet i sitt läger och är därför ditt mål.",al={"vilka är satyrs i bashal'aran","varför strida mot satyrs","vem har sigillet"}},["341831b6"]={q="Varför kan Asterion inte hämta sigillet själv?",a="Asterion kan inte lämna helgedomens gränser. Sigillets magi håller honom helt bunden inom området och gör stenpelarna till ogenomträngliga galler. Han har varken styrkan eller trolldomen som krävs för att bryta sig fri, så han är helt beroende av en utomstående som kan ta sig in i satyr-lägren åt honom.",al={"varför behöver asterion mig","varför kan inte asterion hämta sigillet","varför just jag åt asterion"}}},fp="11,206,25.360.0,29.354.0,16.188.0,50.224.0,40.172.1,20.218.0,40.183.0,46.141.0"}
P.entries["quest:95621"] = {n="Trouble in the Valley",s="Trouble in the Valley handlar om en mystisk grupp Kul Tiran-soldater som upptäckts genomsöka dalbottnen. Beväpnade trupper har slagit läger nära en förstörd karavan i söder, vilket får lokala spejare att vilja oskadliggöra dem och ta reda på varför de oväntat söker igenom området.",h="Trouble in the Valley handlar om en mystisk grupp Kul Tiran-soldater som upptäckts genomsöka dalbottnen.",kw={"karavan","kul tiras","soldater","trouble in the valley","dal","förstörd karavan"},ang={["race:Human"]="Att se soldater med havsgröna färger och ankarsymboler från öriket Kul Tiras i dalen är ett sällsynt och oväntat möte med denna tillbakadragna, sjöfarande människonation."},sec={{t="Misstänkt aktivitet i dalen",b="En vaksam gevärsskytt som spanade över låglandet fick syn på en grupp människosoldater som genomsökte dalbottnen. Genom att titta noga med ett kikarsikte kunde spejaren tydligt urskilja heraldiken och uniformerna från sjönationen Kul Tiras. Deras oväntade närvaro i dalen väckte genast oro, eftersom beväpnade främlingar sällan rör sig så öppet utan att dra till sig uppmärksamhet."},{t="Den förstörda karavanen",b="Soldaterna intog en position nära en förstörd karavan i söder. Vad som lockade dem till den havererade vagnen är fortfarande ett brådskande mysterium. Lokala observatörer har bedömt den påträngande beväpnade närvaron som ett omedelbart hot och skickat utredare för att oskadliggöra soldaterna och ta reda på expeditionens verkliga syfte."}},faq={{q="Vad gör Kul Tiran-soldater i dalen?",a="En prickskytt fick syn på en grupp Kul Tiran-soldater som letade efter något i dalen nedanför. De slog läger nära en förstörd karavan i söder, vilket fick lokala spejare att undersöka deras märkliga avsikter.",al={"varför är kul tiran här","kul tiras-soldater i dalen","vad gör kul tiran här"}},{q="Var ligger Kul Tiran-lägret?",a="Soldaterna har slagit läger nära en förstörd karavan söder om utsiktsplatsen där spejaren spanar över dalen.",al={"den förstörda karavanens plats","var ligger kul tiras-lägret","karavanens plats"}},{q="Hur upptäcktes Kul Tiran-närvaron?",a="En spejare som höll utkik över dalen använde ett kikarsikte för att undersöka den mystiska gruppen människor på avstånd och kände lätt igen Kul Tiras utmärkande uniformer och insignier.",al={"hur identifierades de","kul tiras uniformer"}},{q="Vad är målet med att undersöka lägret?",a="Uppgiften går ut på att resa söderut mot den förstörda karavanen, konfrontera Kul Tiran-soldaterna där och ta reda på vad som fick dem att söka igenom området.",al={"vad är målet","målen i trouble in the valley"}},{q="Varför betraktas Kul Tiran-soldaterna som fiender?",a="Eftersom en beväpnad grupp utländska soldater utan förklaring genomsöker området kring en förstörd karavan, anser spejarna att de utgör ett hot som måste oskadliggöras för att deras avsikter ska bli kända.",al={"varför slåss mot kul tiras","är kul tiran fientliga"}},{q="Vem upptäckte soldaterna i dalen?",a="Walton, eremitskräddaren som håller utkik över dalen, upptäckte först soldaterna genom sitt kikarsikte och anlitade en äventyrare för att oskadliggöra dem och ta reda på varför de var där.",al={"vem såg soldaterna","vem gav uppdraget"}}},fp="21,283,33.369.0,19.318.0,48.231.0,36.143.0,42.170.0,48.165.0,50.210.0,40.178.0"}
P.entries["quest:95646"] = {n="Horrors in the Highland",s="Rethiel the Greenwarden känner en oren fördärvelse sippra genom en bergsklyfta in i det osaltade vattnet ovanför Wetlands. Äventyrare måste ta sig upp till utgrävningsplatserna för att döda en Highland Horror och hämta dess rotkärna. Rethiel upptäcker att en uråldrig energi håller på att vakna och varnar för att det fortsatta grävandet hotar säkerheten för alla i regionen.",h="Rethiel the Greenwarden känner en oren fördärvelse sippra genom en bergsklyfta in i det osaltade vattnet...",kw={"födärvelse","utgrävningsplatser","highland horror","horrors in the highland","rethiel","rethiel the greenwarden","rotkärna","wetlands"},ang={["class:Druid"]="Rethiel känner hur den naturliga balansen förändras genom hans rötter och vattendragen. Druider som är lyhörda för landet kommer att känna igen hur sötvattenlivet plötsligt blivit sårbart för uråldrig fördärvelse.",["faction:Alliance"]="Alliansens utforskare och Prospektörer som arbetar på utgrävningsplatser i bergen riskerar att störa uråldriga krafter begravda under jorden.",["race:Dwarf"]="Dvärgarnas utgrävningsplatser i höglandet har grävt fram mer än uråldriga reliker, vilket får Rethiel att uppmana utgrävarna att avbryta arbetet innan värre ondska vaknar."},sec={{t="Smitta i klyftan",b="Djupt inne i Wetlands känner Rethiel the Greenwarden en oroande förändring i landet. En oren smitta sipprar genom en bergsklyfta och infekterar sötvattensvarelserna som lever i höglandet ovanför. Till skillnad från det härdiga liv som formats av det bräckta låglandsvattnet har dessa sötvattensvarelser aldrig känt havets skyddande salt och är därför helt försvarslösa mot det onda som sprider sig. Rethiel ber äventyrare ta sig upp till utgrävningsplatserna, döda en Highland Horror och hämta dess rotkärna."},{t="Ett uråldrigt uppvaknande",b="När Highland Horrors rotkärna förs fram till Rethiel bekräftas väktarens farhågor: en uråldrig energi har börjat vakna. Åkomman som plågar höglandets varelser är ingen vanlig sjukdom, utan en följd av den senaste tidens grävande. Rethiel varnar enträget för att de ivriga utgrävarna vid bergsplatserna genast måste sluta gräva, innan deras tanklösa nyfikenhet släpper lös något långt värre över Wetlands."}},faq={{q="Vem ger uppdraget Horrors in the Highland?",a="Rethiel the Greenwarden, en uråldrig beskyddare som vakar över Wetlands, ger uppdraget efter att ha känt en oren fördärvelse sippra genom en närliggande bergsklyfta.",al={"vem ger horrors in the highland","uppdragsgivare för horrors in the highland","rethiel uppdrag"}},{q="Var finns Highland Horrors?",a="Highland Horrors håller till på utgrävningsplatserna på högre mark ovanför låglandet, nära bergsklyftan där fördärvelsen sipprar fram.",al={"var finns highland horrors","highland horror plats","var hittar man highland horror"}},{q="Varför är höglandets varelser så mottagliga för fördärvelse?",a="Höglandets sötvattensvarelser saknar den härdande saltlaken och havssaltet som finns i de lägre våtmarkerna, vilket gör dem sköra och särskilt bittra i sin reaktion på den fördärvande smittan.",al={"varför är varelserna smittade","varför är höglandets varelser fördärvade","fördärvelse i osaltat vatten"}},{q="Vad är en Highland Horrors rotkärna?",a="Rotkärnan är hjärtat i den fördärvade Highland Horror. Rethiel behöver den för att undersöka den onaturliga kraft som sprider sig genom vattendragen och bekräfta fördärvelsens natur.",al={"vad är rotkärnan","highland horrors kärna","varför hämta rotkärnan"}},{q="Vad upptäcker Rethiel när du återlämnar rotkärnan?",a="När Rethiel undersöker kärnan inser han att en uråldrig energi har börjat vakna djupt nere i jorden, troligen störd av vårdslöst grävande på utgrävningsplatserna.",al={"vad upptäcker rethiel","uråldrig energi i wetlands","fara vid utgrävning"}},{q="Varför vill Rethiel att utgrävarna slutar gräva?",a="Rethiel varnar för att de ivriga utgrävarna i höglandet genast bör sluta gräva för sin egen säkerhets skull, eftersom deras arbete riskerar att släppa lös farliga uråldriga krafter.",al={"rethiel stoppa grävandet","vad bör utgrävarna göra","varning vid dvärgarnas utgrävningsplats"}}},fp="23,358,18.505.0,19.443.1,45.164.0,36.152.0,60.197.0,43.185.0,57.172.0,53.184.0"}
P.entries["quest:95647"] = {n="Lost in the Thicket Things",s="En orolig alkemist ber resenärer leta reda på hennes försvunne make, Ardin Grassman, som försvann efter att ha följt rykten om skyhöga, okända grässorter. Ardins botaniska nyfikenhet ledde honom rakt mot en närliggande utgrävningsplats, där farliga vilda djur och spindelangrepp har belägrat arbetslaget.",h="En orolig alkemist ber resenärer leta reda på hennes försvunne make, Ardin Grassman, som försvann efter att...",kw={"alkemi","ardin","ardin grassman","utgrävningsplatser","örtinsamling","lost in the thicket things","spindlar","skyhöga grässorter"},ang={["class:Druid"]="Druider som är i samklang med vildmarkens balans kan intressera sig för Ardins naturliga förmåga att känna av växtlighet, liksom den onaturliga upprördhet som stör djurlivet nära utgrävningsplatserna.",["profession:Herbalism"]="Ardin Grassman har en medfödd förmåga att känna av växter och örter och klättrar ofta i förrädisk terräng för att samla sällsynta växter till alkemin."},sec={{t="En samlares kall",b="I ”Lost in the Thicket Things” söker en alkemist hjälp med att hitta sin försvunne make, Ardin Grassman. Ardin har en ovanlig, instinktiv fallenhet för naturen och trotsar regelbundet branta klippor och avlägsen vildmark för att samla sällsynta örter och botaniska exemplar till sina alkemiförråd. När ett förbipasserande utgrävningslag berättade om bisarra, skyhöga grässorter som ingen sett förut, tog nyfikenheten överhanden och Ardin gav sig av för att själv undersöka växtligheten."},{t="Bakhåll vid utgrävningen",b="Ardin följde expeditionen till deras utgrävningsplats, men hamnade rakt i fara. Något i det omgivande landet hade gjort den lokala faunan upprörd, så att aggressiva vilda djur – framför allt svärmar av fientliga spindlar – gick till angrepp och övermannade utgrävningslaget. Ardin och arbetslaget blev instängda av de anstormande bestarna och belägrade tills resenärer ingrep och räddade den strandsatte botanisten."}},faq={{q="Vem är Ardin Grassman?",a="Ardin Grassman är en samlare med en ovanlig naturlig förmåga att känna av växter och örter. Han söker regelbundet av klippor och bergstoppar för att förse sin fru med vilda växter till hennes alkemiverksamhet, men nyfikenheten på märkliga, skyhöga grässorter drog honom mot en utgrävningsplats.",al={"vem är ardin","ardin grassmans bakgrund","vem är ardin grassman"}},{q="Varför gav sig Ardin ut i vildmarken?",a="Ardin hörde ett utgrävningslag beskriva enorma, skyhöga grässorter som de aldrig hade stött på förut. Hans fallenhet för ovanliga växter lockade honom att ge sig ut och se den märkliga växtligheten med egna ögon, men han kom aldrig hem igen.",al={"varför gav sig ardin av","varför är ardin försvunnen","vad letade ardin efter"}},{q="Vart tog Ardin vägen?",a="Ardin begav sig mot de närliggande utgrävningsplatserna efter att ha hört rapporter från en expedition som passerade. Resenärer som letar efter honom måste söka igenom utgrävningsplatserna där arbetslaget slog läger.",al={"var är ardin","ardins plats","var hittar man ardin grassman"}},{q="Vad hände med Ardin vid utgrävningsplatsen?",a="Ardin fann att utgrävningslägret hade övermannats när den lokala faunan blev upprörd och aggressiv. Jättespindlar och andra uppretade bestar överföll expeditionen och höll Ardin och arbetslaget instängda tills hjälp utifrån kom.",al={"vad hände med ardin","är ardin död","vad attackerade ardin"}},{q="Vem letar efter Ardin?",a="Sökandet börjar hos Ardins fru, en alkemist som förlitar sig på hans örtexpeditioner för att fylla sina hyllor. När han inte kom tillbaka efter att ha undersökt rykten om märkligt gräs sökte hon upp dugliga resenärer som kunde hämta hem honom.",al={"vem ger uppdraget lost in the thicket things","vem startade det här uppdraget","ardins fru"}},{q="Varför attackerade de vilda djuren utgrävningslaget?",a="Djurlivet kring utgrävningsplatserna blev plötsligt och våldsamt upprört, men den exakta orsaken är fortfarande oklar. Störningen drev aggressiva varelser, särskilt spindlar, att svärma och övermanna utgrävningslaget.",al={"varför attackerar spindlarna","vad gjorde djuren upprörda","varför är bestarna arga"}}},fp="26,298,19.490.0,22.401.1,22.269.0,39.259.0,19.190.0,46.221.0,25.237.0,48.253.0"}
P.entries["quest:95697"] = {n="Changing Tastes",s="Changing Tastes är ett uppdrag i Orgrimmar om kulinariska ambitioner på Borstan's Firepit. Efter råd från Zamja och berättelser om jättelika rovfågelklor låter Borstan äventyrare resa över havet till Wetlands för att hämta exotiskt kött från snårrovfåglar.",h="Changing Tastes är ett uppdrag i Orgrimmar om kulinariska ambitioner på Borstan's Firepit.",kw={"borstan","borstans eldstad","changing tastes","utgrävningsplatser","orgrimmar","snårrovfågel","kött från snårrovfågel","wetlands","zamja"},ang={["faction:Horde"]="Att förse Borstan's Firepit innebär att ge sig djupt in i omstridda områden på andra sidan havet och ta med exotiskt kött tillbaka till Orgrimmar.",["profession:Cooking"]="Borstan vill förädla traditionella rustika rätter till något som passar Horde-huvudstaden. Det visar hur kulinariska smaker och värdshusmenyer utvecklas bortom byarnas klassiker."},sec={{t="Att förädla huvudstadens mat",b="I hjärtat av Orgrimmar vill Borstan's Firepit utöka sitt kulinariska utbud. Zamja föreslog att de skulle börja servera hemlagad rovfågel för resenärer som saknar de tröstande, välbekanta rätterna från sina hembyar. Borstan gillade tanken på att servera rovfågel för att locka nya gäster, men tyckte att det inte passade Horde-huvudstaden att bara återskapa byarnas rustika rätter. I stället föreställde han sig en storslagenare och djärvare variant av den klassiska rätten."},{t="Jakten i Wetlands",b="Inspirationen kom när en jägare återvände till Orgrimmar med en enorm klo från snårrovfåglarna som stryker omkring vid utgrävningsplatserna i Wetlands. Fascinerad av dessa bestars kvalitet och storlek ordnar Borstan så att äventyrare korsar havet till Eastern Kingdoms, trotsar utgrävningsområdena och hämtar förstklassigt kött från snårrovfåglar till hans sprakande eldar."}},faq={{q="Vad är uppdraget Changing Tastes?",a="Changing Tastes är ett kulinariskt uppdrag i Orgrimmar. Borstan, som äger Borstan's Firepit, vill ha kött från snårrovfåglar i avlägsna Wetlands för att lyfta värdshusets meny över enkel bymat.",al={"vad är changing tastes","uppdraget changing tastes"}},{q="Vem är Zamja?",a="Zamja är en medarbetare eller kollega inom matlagning i Orgrimmar. Hon föreslog att Borstan's Firepit skulle lägga till hemlagade rovfågelrätter för att locka kunder som vanligtvis inte besöker stället.",al={"vem är zamja","zamja matlagning"}},{q="Vad är Borstan's Firepit?",a="Borstan's Firepit är ett matställe i Horde-huvudstaden Orgrimmar, känt för sina rejäla kötträtter som serveras till både resenärer och lokalbor.",al={"borstans eldstad","var finns borstan"}},{q="Varför vill Borstan ha kött från snårrovfåglar?",a="Zamja föreslog vanlig, hemlagad rovfågel för att locka gäster, men Borstan vill skapa en storslagnare variant av välbekanta smaker. Inspirerad av en jägares berättelse om jättelika klor valde han snårrovfåglarna i Wetlands.",al={"varför rovfågelkött","varför snårrovfågel"}},{q="Var finns snårrovfåglarna?",a="Snårrovfåglar lever vid utgrävningsplatserna i Wetlands, en alliansvänlig region på andra sidan Great Sea i Eastern Kingdoms.",al={"var hittar jag snårrovfåglar","rovfåglar vid utgrävningsplatserna i wetlands"}},{q="Vem ger uppdraget Changing Tastes?",a="Borstan, ägaren till Borstan's Firepit i Orgrimmar, erbjuder uppdraget efter att ha inspirerats av råd från Zamja och en trofé som en äventyrslysten jägare tagit med sig tillbaka.",al={"vem ger changing tastes","borstan uppdragsgivare"}}},fp="15,264,25.472.0,24.378.0,34.201.0,13.173.0,26.142.0,42.220.0,38.143.0,36.169.0"}
P.entries["quest:957"] = {n="Bashal'Aran",s="Det här uppdraget ber äventyrare hjälpa Asterions fångade ande i ruinerna av Bashal'Aran. Genom att föra hans bindande sigill söderut till systerruinerna i Ameth'Aran söker de ett sätt att bryta hans uråldriga bojor.",h="Det här uppdraget ber äventyrare hjälpa Asterions fångade ande i ruinerna av Bashal'Aran.",kw={"ameth'aran","asterion","athrikus","azshara","bashal'aran","darkshore","highborne","månstenssigill"},ang={["class:Mage"]="De kraftfulla förtrollningarna som håller Asterion bunden och de överlevande lågorna i Ameth'Aran ger en inblick i den råa arkana kraft som uråldriga Highborne-trollkarlar behärskade.",["faction:Alliance"]="När de uråldriga förbannelserna i Darkshore skingras säkras gränserna för de nya Night Elf-bosättningar som växer fram från Auberdine.",["race:NightElf"]="För nutidens Night Elves i Kalimdor innebär Asterions frigivning ett allvarligt möte med folkets förflutna före Sundringen och den kvardröjande korruptionen hos drottning Azsharas Highborne-adel."},sec={{t="Ett fängelse av uråldrig trolldom",b="Asterions ande har dröjt sig kvar i Bashal'Aran i årtusenden, fjättrad i döden av ett Ancient Moonstone Seal. Sigillet smiddes med Highborne-kastens mäktiga trolldom före den stora Sundringen och kan inte krossas med vanlig styrka. För att förstöra det krävs den särskilda magin från en uråldrig låga som fortfarande glöder bland de fallna stenarna i Ameth'Aran i söder."},{t="Darkshores tvillingruiner",b="Bashal'Aran och Ameth'Aran var en gång livliga systerboplatser i kaldoreis civilisation, när drottning Azshara härskade och Evighetens källa ännu höll deras imperium samman. I dag är båda platserna igenvuxna, hemsökta ruiner fyllda av kvarvarande andar och instabila arkana energier. I ett lusthus av sten i Ameth'Aran finns ett mystiskt fyrfat med cyanblå eld, den enda kraft som kan förtära Asterions bindande relik."},{t="Hämnden vaknar",b="När sigillet förstörts är Asterion äntligen fri från sin börda. Han blickar ut över ett krossat Kalimdor som förändrats fullständigt sedan den gyllene tidsålder han minns. Men friheten ger honom ingen frid. Han känner att hans tidigare mästare och fångvaktare, Highborne Athrikus, fortfarande lever, och Asterions uråldriga förtvivlan övergår snabbt i en kall, brännande hämndlystnad."}},faq={{q="Vem är Asterion?",a="Asterion är en Night Elf-ande som är fångad i ruinerna av Bashal'Aran. Han levde för tiotusen år sedan, under drottning Azsharas regeringstid, och hålls bunden till ruinerna av ett sigill som skapades av en av de mäktigaste bland Highborne.",al={"asterion","vem är spöket","npc asterion"}},{q="Var förstör jag Ancient Moonstone Seal?",a="Sigillet måste föras söderut till Ameth'Aran, Bashal'Arans tvillingruin. Leta efter ett lusthus av sten som skyddar ett stort, kubformat fyrfat med uråldrig grönblå magisk eld.",al={"var finns lågan","plats för uråldrig låga","förstör sigill"}},{q="Hur hänger Bashal'Aran och Ameth'Aran ihop?",a="De var systerstäder i det uråldriga Night Elf-imperiet före Sundringen. Båda ödelades för tiotusen år sedan och lämnade efter sig hemsökta stenpelare, kvarvarande arkana energier och oroliga andar.",al={"tvillingruiner","ametharan koppling","bashalaran ametharan"}},{q="Vem fängslade Asterion?",a="Asterion säger att en av de mäktigaste bland Highborne skapade sigillet som håller honom bunden. Mer om hans tidigare mästare avslöjas under uppdragskedjan.",al={"vem fängslade asterion","vem är athrikus","asterions mästare"}},{q="Vilken tid minns Asterion?",a="Asterion vandrade senast på jorden när den ursprungliga Evighetens källa ännu fanns, drottning Azshara styrde imperiet och Highbornes adel höll sina ståtliga hov före Sundringen.",al={"asterions förflutna","evighetens källas tidsålder","hur gammal är asterion"}},{q="Får Asterions ande ro när han blir fri?",a="Sigillet ska förstöras för att bryta Asterions fängelse. Hans reaktion på friheten får du veta när du återvänder till honom.",al={"går asterion vidare","vad händer med asterion","asterion efter frigivningen"}}},fx={["8275c861"]={q="Varför vill Asterion att Ancient Moonstone Seal förstörs?",a="Ancient Moonstone Seal är ankaret som håller Asterions ande fången i plåga bland Bashal'Arans ruiner. Det skapades för årtusenden sedan med mäktig Highborne-trolldom och håller honom fängslad, blind för världen bortom. Att förstöra det i den mystiska uråldriga lågan i Ameth'Aran är det enda sättet att krossa hans eteriska bojor och ge honom frihet och klarhet att se vad som blivit av Kalimdor.",al={"varför förstöra moonstone seal","asterions motiv","varför vill asterion bryta sigillet"}},["51df5ddd"]={q="Varför behöver Asterion att du tar sigillet till Ameth'Aran?",a="Asterion är bunden av den uråldriga Highborne-magin som håller honom fast vid Bashal'Aran. Han kan inte lämna de närmaste ruinerna, än mindre färdas söderut till Ameth'Aran. Han behöver en resenär som bär sigillet in i den uråldriga lågan.",al={"varför kan inte asterion förstöra sigillet","varför behöver asterion mig","varför skicka en äventyrare att förstöra sigillet"}}},fp="11,141,27.301.0,23.365.0,17.280.1,16.198.0,46.175.0,60.224.0,24.132.1,32.178.0,45.113.1"}
P.entries["quest:95772"] = {n="Songblade Search",s="Songblade Search är ett dvärgärende där Dorin Songblade ber resande att leta efter hans bror Daewyn i Wetlands. Daewyn gav sig av med en arkeologisk expedition från Loch Modan för att gräva i outforskade kullar, men hans ovanliga tystnad fick brodern att frukta det värsta.",h="Songblade Search är ett dvärgärende där Dorin Songblade ber resande att leta efter hans bror Daewyn i...",kw={"daewyn songblade","dls","dorin songblade","loch modan","songblade search","wetlands","whelgar's excavation site"},ang={["faction:Alliance"]="Alliansens resande mellan Loch Modan och Menethil Harbor passerar ofta utgrävningsplatserna och hjälper strandsatta dvärgprospektörer och hantverkare.",["race:Dwarf"]="Dvärgexpeditioner och arkeologiska utgrävningar är vanliga i Khaz Modan, men att färdas från Loch Modans säkerhet till farliga Wetlands innebär ofta stora risker för de anhöriga."},sec={{t="En brors oro",b="Dorin Songblade stannade kvar i sin verkstad, överhopad av beställningar på omgjorda gördlar, medan hans bror Daewyn anslöt sig till en dvärgexpedition som gav sig av från Loch Modan. Daewyn begav sig norrut till Wetlands karga kullar, ivrig att utforska orörd mark som aldrig rörts av dvärgarnas hackor. Daewyn brukar dock skicka brev så snart han kommit fram, och hans tystnad gjorde Dorin djupt orolig."},{t="Grävplatsen i Wetlands",b="Resande som beger sig till Wetlands kan hitta Daewyn Songblade bland grävarna vid Whelgar's Excavation Site. Daewyn liknar sin bror Dorin mycket och bär ett särskilt gevär med initialerna ”DLS” inristade i träkolven, vilket visar att han nådde den avlägsna utgrävningsplatsen i träskmarkerna."}},faq={{q="Vem ger uppdraget Songblade Search?",a="Dorin Songblade ger uppdraget. Han är en hantverkare som just nu är överhopad med arbete med att göra om en hög gördlar, vilket hindrade honom från att följa med sin bror på en arkeologisk utgrävning.",al={"vem ger songblade search","uppdragsgivare för songblade search","dorin songblade"}},{q="Vem är Daewyn Songblade?",a="Daewyn Songblade är Dorin Songblades bror. Han gav sig av med en expedition från Loch Modan mot Wetlands vilda kullar, men hörde inte av sig som han brukar.",al={"vem är dorins bror","försvunnen songblade-dvärg","daewyn songblade"}},{q="Var hittar man Daewyn?",a="Daewyn finns vid Whelgar's Excavation Site i Wetlands. Du känner igen honom på den starka likheten med Dorin och hans skjutvapen, vars träkolv har ”DLS” inristat.",al={"var finns daewyn","var hittar man daewyn songblade","songblade search plats"}},{q="Varför reste Daewyn till Wetlands?",a="Daewyn anslöt sig till en dvärgexpedition från Loch Modan som sökte oupptäckta kullar i Wetlands för en arkeologisk utgrävning.",al={"varför reste daewyn till wetlands","syftet med whelgar's excavation","varför reste dvärgarna till wetlands"}},{q="Vad står initialerna på geväret för?",a="Initialerna ”DLS” på skjutvapnets kolv tillhör Daewyn Songblade och bekräftar att dvärgen vid utgrävningsplatsen verkligen är Dorins försvunne bror.",al={"vad står dls för","dls inristat på gevär","initialerna dls"}},{q="Varför oroade sig Dorin för sin bror?",a="Dorin blev orolig eftersom Daewyn vanligtvis skriver tillbaka snabbt efter att ha gett sig av på en resa. När inga brev kom efter avfärden till Wetlands fick Dorin en obehaglig föraning om att något hade gått fel.",al={"varför är dorin orolig","varför leta efter daewyn","orsaken till songblade search"}}},fp="16,280,18.413.0,23.320.1,37.181.0,24.201.0,26.191.0,38.141.0,44.161.0,40.228.0"}
P.entries["quest:95774"] = {n="Her Name Is Olgra",s="När Mankrik får veta att Olgra har dött i strid beslutar han sig för att hedra henne med ett bestående minnesmärke. Han ber dig hämta hennes försvunna bensmycken från de närbelägna Razormane-rövarna, så att de kan vila intill hennes monument.",h="När Mankrik får veta att Olgra har dött i strid beslutar han sig för att hedra henne med ett bestående...",kw={"smycken","mankrik","minnesmärke","olgra","polerat ben","quilboar","razormane-rövare"},sec={{t="Att hedra de fallna",b="En läkare lyckades rädda Mankrik, men Olgra dog av sina skador på slagfältet. Den sörjande krigaren vill att hennes namn och offer aldrig ska glömmas och förbereder ett bestående minnesmärke till hennes ära."},{t="Förlorade minnessaker",b="Olgra bar älskade smycken av polerat ben, men de saknades på hennes viloplats. Mankrik vill återta dessa personliga skatter från de närbelägna Razormane-rövarna, så att de kan vila intill monumentet han reser åt henne."}},faq={{q="Vem är Olgra?",a="Olgra föll i strid mot quilboar. Läkaren som hjälpte Mankrik lyckades rädda honom, men Olgra gick inte att rädda, och Mankrik tänker hedra hennes minne för alltid.",al={"vem är olgra","mankriks fru","vem dog"}},{q="Vad är Olgras smycken?",a="Hennes smycken är älskade hantverkade prydnader av polerat ben som hon bar innan hon dödades.",al={"vad är olgras smycken","olgras juveler","vad är smyckena gjorda av"}},{q="Varför jagas Razormane-rövarna?",a="Smyckena togs från Olgras fallna kropp, så Mankrik skickar dig mot Razormane-rövarna nära platsen där hon dog för att återta dem.",al={"varför döda razormane-rövare","vem stal olgras smycken","var finns smyckena"}},{q="Vad ska Mankrik göra med de återfunna smyckena?",a="Mankrik tänker placera de återfunna bensmyckena intill monumentet han bygger åt Olgra, så att hennes minne aldrig bleknar.",al={"mankriks minnesmärke","vad ska mankrik göra med smyckena","varför vill mankrik ha smyckena"}}},fp="17,220,19.236.0,14.238.0,13.173.0,28.116.0,43.157.0,51.139.0"}
P.entries["quest:95795"] = {n="Fallen in the Fen",s="Fallen in the Fen är en sorgsen färd som börjar när en död dvärg hittas vid en utgrävning. Beskedet till hans bror Dorin Songblade i Lakeshire ger en förkrossad hantverkare ro, efter att han smitt gåvor åt sin bortgångne bror.",h="Fallen in the Fen är en sorgsen färd som börjar när en död dvärg hittas vid en utgrävning.",kw={"smed","dorin","dorin songblade","dvärg","utgrävning","utgrävningsplatser","fallen in the fen","lakeshire","songblade"},ang={["faction:Alliance"]="Att ge en hantverkare i Redridge ro ger tröst åt en sörjande invånare under en orolig tid för kungariket.",["profession:Blacksmithing"]="Dorin lade all sin skicklighet i vapnen han tänkt ge sin bror som överraskning. Nu påminner utrustningen honom bara om broderns för tidiga död.",["race:Dwarf"]="Dvärgar vet hur bitter sorgen är när en bror går förlorad i gamla utgrävningar och otämjd vildmark, särskilt när det smidda stålet överlever handen som skulle hålla det."},sec={{t="Tragedi vid utgrävningen",b="En stilla tragedi utspelar sig vid utgrävningsplatserna, där en äventyrslysten dvärgs livlösa kropp hittas. En äventyrare täcker kvarlevorna med dvärgens egen mantel och tar sedan det dystra beskedet tillbaka till Lakeshire för att hitta hans anhöriga."},{t="En brors sorg",b="I Lakeshire bryter dvärgsmeden Dorin Songblade ihop när han får veta vad som hänt hans bror. I flera veckor hade Dorin arbetat vid sin ässja och smitt en överraskningsgåva åt sin bror, men utrustningen blev inte klar i tid för expeditionen. Fylld av ånger över att inte ha följt med klarar Dorin varken av att smida om eller sälja det han tillverkat med egna händer. I stället ger han de färdiga föremålen till den som gav honom visshet."}},faq={{q="Vad är Fallen in the Fen?",a="Fallen in the Fen är ett sorgset uppdrag som börjar när kvarlevorna efter en fallen dvärg upptäcks vid en utgrävning. Du täcker kroppen med hans mantel och beger dig till Lakeshire för att personligen berätta för dvärgens sörjande bror, Dorin Songblade, vad som hänt.",al={"vad är fallen in the fen","uppdraget fallen in the fen"}},{q="Vem är Dorin Songblade?",a="Dorin Songblade är en dvärgisk smed som bor i Lakeshire. Han hade smitt utrustning som en överraskningsgåva åt sin bror innan han fick veta om den tragiska döden vid utgrävningsplatserna.",al={"vem är dorin songblade","dorin i lakeshire","dorin songblades roll"}},{q="Vem är den fallne dvärg som hittades vid utgrävningen?",a="Den fallne dvärg som hittades vid utgrävningsplatserna var Dorin Songblades bror. Han hade nyligen passerat genom Lakeshire för att samla förnödenheter inför sin expedition, innan han dog ute i vildmarken.",al={"vem dog i kärret","död dvärg vid utgrävning","vems kropp finns vid utgrävningen"}},{q="Var hittar man Dorin Songblade?",a="Dorin Songblade finns i Lakeshire, den främsta bosättningen i Redridge Mountains, där han arbetar vid smedjan.",al={"var finns dorin songblade","dorin songblades plats"}},{q="Vad smidde Dorin åt sin bror?",a="Dorin arbetade med att smida utrustning som en överraskningsgåva åt sin bror. Tyvärr blev arbetet inte klart innan brodern gav sig av på sin expedition, och Dorin är förkrossad över utrustningen som han varken kan behålla eller sälja.",al={"vad smidde dorin","dorins överraskningsgåva"}},{q="Varför ger Dorin bort föremålen han tillverkat?",a="Överväldigad av sorg och ånger över att inte ha följt med sin bror vill Dorin varken smida om eller sälja vapnen han arbetat så hårt med. Han skänker bort de färdiga föremålen som tack till resenären som kom med beskedet om hans bror.",al={"varför gav dorin bort utrustningen","varför ger dorin dig utrustning"}}},fp="17,263,18.237.0,17.442.1,26.255.0,23.178.0,48.206.0,35.127.0,39.229.0,46.228.0"}
P.entries["quest:95805"] = {n="Grace of An'she and Mu'sha",s="Grace of An'she and Mu'sha är en helig taurenpilgrimsfärd på Red Cloud Mesa, där solen och månen hedras som Jordmoderns himmelska ögon. Genom att bära skör, glödande rökelse till en högt belägen helgedom i de sydöstra kullarna visar resenärerna vördnad för himlaljusen som skänker värme, liv och vägledning åt slätterna.",h="Grace of An'she and Mu'sha är en helig taurenpilgrimsfärd på Red Cloud Mesa, där solen och månen hedras som...",kw={"an'she","jordmodern","måne","mu'sha","mulgore","red cloud mesa","helgedom","glödande rökelse","sol","tauren"},ang={["class:Druid"]="Taurendruider ser solens och månens eviga dans som balansens ursprungliga gestalt, som vägleder deras förståelse av naturens kosmiska rytmer.",["class:Shaman"]="Schamaner talar direkt med världens andar av jord, eld, vatten och luft, men visar lika stor vördnad för de himmelska tvillingarna vars ljus upprätthåller allt levande.",["faction:Horde"]="De heliga riterna på mesan visar den djupa naturvördnad som nomadiska tauren för med sig till sina allierade i Horde.",["race:Tauren"]="Vördnaden för An'she och Mu'sha är central för taurenfolkets andliga identitet och påminner unga krigare om att livet kräver att de hedrar de himmelska tvillingljusen lika troget som Jordmodern själv."},sec={{t="Jordmoderns ögon",b="I taurenmyten kallas solen och månen An'she och Mu'sha, och vördas som Jordmoderns tvillingögon. Medan elementandar bor direkt i Azeroths stenar, vindar och vatten vakar dessa himmelska tvillingar över världen från himlens höjder. Deras ständiga färd över skyn markerar dygnets eviga rytm och skänker värme, vägledning och hopp till alla levande varelser. Att hedra tvillingarna är en viktig andlig plikt och lär att balans kräver vördnad inte bara för marken under ens fötter, utan också för ljuset som strålar ner från himlen."},{t="Ett offer på höjderna",b="För att hedra de himmelska tvillingarna måste en pilgrim bära glödande rökelse till kullarna sydost om mesan, med utsikt över den och strax söder om de taggiga quilboar-markerna. Färden kräver uppmärksamhet och snabbhet: de väldoftande glöden måste överlämnas innan de brunnit ut till kall aska, och resenärerna måste se till att hålla dem borta från vatten längs leden. När pilgrimen når den högt belägna helgedomen kastar hen glöden i den heliga elden och låter den aromatiska röken bära vördnaden upp mot solen och månen."}},faq={{q="Vilka är An'she och Mu'sha?",a="I taurenmytologin är An'she och Mu'sha solen och månen, och de vördas som Jordmoderns tvillingögon. Till skillnad från jordens, luftens, eldens och vattnets andar bor de inte direkt i Azeroths jord. I stället lyser de upp världen från himlavalvet, där An'she skänker värme och liv medan Mu'sha ger vägledning och tröst om natten.",al={"vilka är an'she och mu'sha","an'she och mu'sha i mytologin","taurens sol- och mångudar"}},{q="Varför offrar tauren till solen och månen?",a="Taurenfilosofin lär att balans är nödvändig för all existens. Jordandar råder över det närmaste landskapet, medan An'shes och Mu'shas ljus ger livsviktig energi, syn och hopp åt alla levande varelser. Att offra glödande rökelse på höga platser är en handling av ömsesidig vördnad och ett erkännande av att dödligt liv inte kan frodas utan de båda himlakropparnas ständiga välvilja.",al={"varför vörda solen och månen","tauren och himmelsk dyrkan","varför hedra an'she och mu'sha"}},{q="Var ligger An'shes och Mu'shas helgedom?",a="An'shes och Mu'shas helgedom ligger i de höga kullarna sydost om mesan. Den blickar ut över de vidsträckta slätterna nedanför och ligger strax söder om de taggiga quilboarområdena. Det höga läget ger fri sikt över den öppna himlen och gör platsen idealisk för att sända rök upp mot himlarna.",al={"var ligger an'shes helgedom","helgedomens plats i mulgore","hur hittar man rökelsehelgedomen"}},{q="Vad betyder den glödande rökelsen?",a="Den glödande rökelsen fungerar som en fysisk kanal för bön och vördnad. När dess väldoftande glöd brinner för röken resenärens hängivenhet direkt upp mot solen och månen. När glöden kastas i helgedomens eld fullbordas ritualen, och pilgrimen får en fridfull känsla av andlig tillfredsställelse.",al={"vad gör rökelsen","innebörden av rökelseoffret","varför bränna glödande rökelse"}},{q="Varför måste rökelsen levereras snabbt och hållas torr?",a="Ritualen kräver vaksamhet, snabbhet och omsorg av pilgrimen. Rökelsen måste fortfarande glöda när den kastas i den heliga elden vid helgedomen, så färden måste vara avklarad innan glöden slocknar och blir kall aska. Dessutom släcks glöden omedelbart i vatten, vilket förstör offret innan det når höjderna.",al={"varför har rökelsen en tidsgräns","håll den torr","rökelsen brinner upp"}},{q="Hotar quilboar pilgrimsfärden till helgedomen?",a="Quilboar-stammar håller till i välförsvarade törnlyor i kullarna strax norr om helgedomen. Själva helgedomen ligger på en stillsam utsiktsplats söder om deras marker, men resenärer måste se upp så att de inte råkar hamna i quilboarens snår. Fientliga angrepp kan lätt försena eller störa den ömtåliga färden.",al={"quilboar nära helgedomen","är quilboar ett hot mot pilgrimer","quilboar söder om mesan"}},{q="Hur skiljer sig Mu'sha från andra kulturers syn på månen?",a="I taurenmyten är månen Mu'sha, Jordmoderns kärleksfulla vänstra öga som blickar ner på de dödligas liv. Andra raser på Azeroth, framför allt nattalverna, vördar samma lysande vita måne som gudinnan Elune, men i tauren-traditionen är hon oupplösligt förenad med sin soltvilling, An'she.",al={"är mu'sha elune","taurenmånens skillnad från elune","mu'sha och nattalverna"}}},fp="26,342,27.602.0,26.548.0,26.366.0,53.398.0,49.314.0,51.336.0,55.353.0,54.310.0,61.306.0"}
P.entries["quest:95809"] = {n="Heartwoven",s="Heartwoven är ett Alliance-uppdrag i Wetlands med ett enkelt budskap om överlevnad och tillgivenhet. Efter att ha röjt en flyktväg åt en strandsatt samlare i träskmarkerna bär äventyrare ett handflätat hjärta av vass till Caitlin Grassman i Menethil Harbor.",h="Heartwoven är ett Alliance-uppdrag i Wetlands med ett enkelt budskap om överlevnad och tillgivenhet.",kw={"caitlin grassman","grassman","heartwoven","menethil harbor","vasstråhjärta","vass","wetlands"},ang={["faction:Alliance"]="Menethil Harbor är en viktig Alliance-hamn i Wetlands, där vanliga invånare förlitar sig på resenärer för att hålla de farliga lederna genom träskmarkerna säkra.",["profession:Cooking"]="När Caitlin får vasstråhjärtat och hör att hennes partner överlevt börjar hon genast laga en varm och mättande måltid för att välkomna honom hem."},sec={{t="En signal från träskmarkerna",b="Ute i Wetlands förrädiska träskmarker innebär både liv och arbete ständig fara. Ardin Grassman gav sig av för att se de märkliga gräsen vid utgrävningsplatserna, men blev strandsatt bland träskets faror tills en förbipasserande resenär röjde en väg genom vildmarken. Utmattad men beslutsam stannar han för att hämta andan och säkra sin skörd innan han beger sig tillbaka mot hamnens trygghet."},{t="Minnen från Menethil",b="Innan samlaren beger sig hem tar han kärrvass ur packningen och flätar den till ett hjärta. Han anförtror äventyraren detta tecken, som ska bäras till Caitlin Grassman i Menethil Harbor. I den livliga kustbosättningen väntar Caitlin djupt orolig. När hon får höra att han överlevt och snart kommer tillbaka för en varm måltid håller hon det flätade vasstråhjärtat mot bröstet i lättnad."}},faq={{q="Vad är uppdraget Heartwoven?",a="Heartwoven är ett Alliance-uppdrag i Wetlands. En äventyrare hjälper Ardin Grassman, som blivit strandsatt vid utgrävningsplatserna ute i träskmarkerna. Han tillverkar ett flätat tecken av vass, ett budskap om överlevnad och kärlek som ska lämnas till Caitlin Grassman i Menethil Harbor.",al={"uppdraget heartwoven","vad är heartwoven","heartwoven i wetlands"}},{q="Vem är Caitlin Grassman?",a="Caitlin Grassman är en Alliance-invånare som väntar oroligt i Menethil Harbor. Hon fruktar för sin make Ardins liv. Han gav sig av till utgrävningsplatserna bland Wetlands faror, och hon känner en djup lättnad när du berättar att han överlevt.",al={"vem är caitlin grassman","caitlin menethil harbor","caitlin grassman"}},{q="Vad är det flätade vasstråhjärtat?",a="Det flätade vasstråhjärtat är ett handgjort tecken som den strandsatte samlaren tillverkar av kärrvassen i sin packning. Han flätar det snabbt för att visa att han lever och snart är på väg hem.",al={"vad är vasstråhjärtat","hjärta flätat av vass","flätat vasstråhjärta"}},{q="Var lämnar du in Heartwoven?",a="Uppdraget avslutas hos Caitlin Grassman, som väntar i Alliance-hamnstaden Menethil Harbor på Wetlands västkust.",al={"var lämnar man in heartwoven","plats för inlämning av heartwoven","var finns caitlin grassman"}},{q="Vem ger dig uppdraget Heartwoven?",a="Uppdraget ges av Ardin Grassman, Caitlins make, som överlevde farorna vid utgrävningsplatserna ute i Wetlands. När en äventyrare har röjt en säker väg åt honom vilar han, samlar ihop sina säckar och skickar äventyraren i förväg med ett handgjort tecken till Caitlin.",al={"vem ger heartwoven","vem flätar hjärtat","den överlevande i heartwoven"}},{q="Vad hände med den strandsatta samlaren?",a="Ardin gav sig till utgrävningsplatserna för att se märkliga, höga gräs och blev instängd när uppretade vilda djur, framför allt spindlar, övermannade utgrävningsteamet. Tack vare att en äventyrare röjde en väg genom hoten i omgivningen överlevde han, kunde samla ihop sina säckar och bege sig tryggt tillbaka till Menethil Harbor.",al={"vad hände med samlaren","lever han","överlevande i heartwoven"}}},fp="10,263,25.409.0,18.392.0,29.261.0,24.263.0,29.209.0,32.140.0,35.268.0,39.319.0"}
P.entries["quest:95810"] = {n="Lost Relic Carry",s="Lost Relic Carry handlar om att återfinna en trasig del av en uråldrig stenmekanisk automat och lämna den till Prospector Whelgar i Wetlands. Relikens okända kompositmaterial vittnar om Titanernas sofistikerade ingenjörskonst och väcker stor vördnad hos dvärgiska forskare.",h="Lost Relic Carry handlar om att återfinna en trasig del av en uråldrig stenmekanisk automat och lämna den...",kw={"automat","utgrävningsplats","explorers league","lost relic carry","prospector whelgar","stenmekanisk","titan relic","wetlands"},ang={["profession:Engineering"]="Kompositmaterialet och den intrikata utformningen hos den stenmekaniska automaten vittnar om avancerade mekaniska principer långt bortom vanlig dödlig ingenjörskonst.",["race:Dwarf"]="Dvärgäventyrarna i Explorers' League är besatta av att gräva fram forntida reliker från sina skapare, vilket gör detta automatfragment till ett eftertraktat fynd för dvärgarnas kulturarv."},sec={{t="Ett fragment av uråldrigt hantverk",b="Djupt inne på forntida marker kan äventyrare hitta en trasig komponent från en stenmekanisk automat. Den är långt ifrån vanligt ras, och dess ovanliga kompositmaterial avslöjar hantverket bakom en avancerad, uråldrig mekanism med koppling till Titanerna."},{t="Till utgrävningsplatsen",b="Prospector Whelgar, som håller till vid utgrävningsplatsen i Wetlands, studerar lämningar från forntiden. Genom att föra reliken i säkerhet och lämna den till honom får dvärgiska lärda värdefulla fysiska bevis medan de undersöker sitt forntida arv."}},faq={{q="Vad är Titan Relic?",a="Reliken är en trasig del av en uråldrig stenmekanisk automat. Den består inte av vanligt stenras, utan av ett okänt kompositmaterial som tydligt ingick i en komplicerad mekanisk anordning.",al={"vad är reliken","vad är föremålet","del av stenmekanism"}},{q="Vem är Prospector Whelgar?",a="Prospector Whelgar är en dvärgisk forskare som ansvarar för utgrävningsplatsen i Wetlands. Han studerar forntida jordiska lämningar och reliker som grävs fram på utgrävningsplatser runt om i regionen.",al={"vem är whelgar","whelgars bakgrund","ansvarig för utgrävningen"}},{q="Var ska reliken lämnas?",a="Reliken ska lämnas till Prospector Whelgar vid hans utgrävningsplats i Wetlands, där dvärgiska utgrävare undersöker forntida ruiner.",al={"var ska jag lämna den","var lämnar jag in den","whelgars plats"}},{q="Vad skapade den stenmekaniska automaten?",a="Automatfragmentet identifieras som en Titan-relik. I dvärgisk folktro har forntida mekaniska konstruktioner och stenautomater koppling till de gåtfulla Titanerna, som formade världen.",al={"vem skapade stenautomaten","automatens ursprung","kopplingen till titanerna"}},{q="Varför behandlar Prospector Whelgar reliken med vördnad?",a="Det är ytterst farligt att ge sig ner i djupen där dessa automater finns. Whelgar påpekar att den som överlever färden ner och återvänder med en sådan del i behåll förtjänar genuin respekt.",al={"varför är whelgar imponerad","farlig färd ner i djupen"}},{q="Vad är ovanligt med automatens material?",a="Materialet är en unik komposit med en främmande struktur, olik vanlig sten eller smitt metall. Det visar hur sofistikerat och gåtfullt hantverket bakom Titanernas forntida konstruktioner var.",al={"vad är materialet","främmande komposit"}}},fp="16,290,27.241.0,26.245.0,24.212.0,26.184.0,42.142.0,37.177.0,59.183.0,47.181.0"}
P.entries["quest:95883"] = {n="The Tortured Soul",s="The Tortured Soul är ett uppdrag kring ett hastigt hopsatt ritualaltare vid Beren's Peril i Silverpine Forest. För att fullfölja de mörka riterna som beskrivs i en övergiven anteckning måste äventyrare hämta en själ präglad av lidande från de farliga klipporna i närheten.",h="The Tortured Soul är ett uppdrag kring ett hastigt hopsatt ritualaltare vid Beren's Peril i Silverpine Forest.",kw={"beren's peril","ohelig energi","blodoﬀer","offersten","ritual","silverpine forest","the tortured soul"},ang={["class:Priest"]="Ritualen använder ohelig energi som slitits ur lidande andar och står i skarp kontrast till den Heliga Ljusets helande principer.",["class:Warlock"]="Att kanalisera plågade själar och utföra mörka riter vid uråldriga offerstenar speglar den dystra, manipulativa naturen hos demonisk magi och skuggmagi.",["race:Undead"]="Silverpine Forest tillhör de Förfallna, där rester av mörk magi och kvardröjande lidande ständigt hotar Lordaerons gränser."},sec={{t="En hastig rit",b="Vid Beren's Peril i Silverpine Forest står ett altare med resterna av en hastigt hopsatt mörk ritual. En klottrad anteckning bland den vårdslöst utspridda röran visar att de flesta ingredienser redan har samlats in. Bara ett blodoﬀer och en Tortured Soul återstår för att slutföra ritualen."},{t="Oheliga energier frigörs",b="Invånarna i klipporna vid Beren's Peril uthärdar svår smärta och är därför lämpliga mål för att utvinna den plågade essens som ritualen kräver. När den utvunna själen läggs fram vid den olycksbådande offerstenen frigörs en våg av ohelig magisk energi, och ritualen förs närmare sin fullbordan."}},faq={{q="Vad är The Tortured Soul?",a="The Tortured Soul är ett uppdrag vid Beren's Peril i Silverpine Forest. Det går ut på att undersöka en ofullbordad mörk ritual vid en offersten och leta upp en plågad varelses själ i närheten för att komplettera ritualens ingredienser.",al={"vad är uppdraget the tortured soul","tortured soul silverpine","uppdraget beren's peril"}},{q="Var äger ritualen rum?",a="Ritualaltaret och dess olycksbådande offersten ligger vid Beren's Peril, en bergig och farlig enklav i Silverpine Forest.",al={"var är ritualen","var ligger beren's peril","offerstenens plats"}},{q="Vilka beståndsdelar krävs för ritualen?",a="Enligt en papperslapp som lämnats vid altaret har nästan allt material hastigt samlats in. Två viktiga beståndsdelar saknas: ett blodoﬀer och en Tortured Soul.",al={"vad behövs för ritualen","ritualens beståndsdelar vid beren's peril"}},{q="Var hittar du Tortured Soul?",a="Uppdragstexten säger att varelserna i närheten av Beren's Peril verkar tillräckligt plågade för att lämna ifrån sig den essens som behövs för att ge offerstenen kraft.",al={"var hittar man tortured soul","vem har själen"}},{q="Vad händer när Tortured Soul förs till altaret?",a="När den plågade själen förs till offerstenen avger den ohelig energi, vilket för den mörka ceremonin ett steg närmare fullbordan.",al={"vad händer när man för fram själen","lämna in tortured soul"}},{q="Vem skapade ritualen vid Beren's Peril?",a="Det framgår inte vem som skapade ritualen, men anteckningarna och det hastigt insamlade materialet tyder på att någon flydde eller satte ihop altaret i stor hast bland Beren's Perils fientliga invånare.",al={"vem skapade ritualen","vem skrev anteckningen"}}},fp="17,261,12.295.0,23.301.1,26.235.0,34.146.0,44.173.0,36.153.0,60.143.0,40.197.0"}
P.entries["quest:95884"] = {n="The Offering Stone",s="The Offering Stone är ett rituellt altare gömt i Beren's Peril i Silverpine Forest. Fragment av en väderbiten lapp avslöjar dess läge. Stenen är täckt av bisarra redskap och föremål avsedda för en okänd offerceremoni. Undersökningar på platsen visar att ritualförberedelser pågår i den skuggiga vildmarken.",h="The Offering Stone är ett rituellt altare gömt i Beren's Peril i Silverpine Forest.",kw={"beren's peril","redskap","offering stone","ritual","lappfragment","silverpine forest","the offering stone"},ang={["class:Warlock"]="Åsynen av en offersten täckt av mörka redskap tyder på rituella seder som bör studeras noga av utövare av de mörka konsterna.",["faction:Horde"]="Forsaken- och Horde-äventyrare som säkrar Silverpine Forest måste hålla utkik efter misstänkta ritualer och kultistaktiviteter i de skuggiga klipporna i Beren's Peril."},sec={{t="En Tattered Note",b="En väderbiten pappersbit som hittats i Silverpine Forest berättar om märkliga ritualförberedelser. Tid och fukt har gjort det mesta av texten oläslig, men tillräckligt många fragment återstår för att avslöja omnämnanden av en ritual och en offersten någonstans i närheten. Resenärer som följer ledtrådarna in bland klipporna i Beren's Peril kan hitta det enkla altaret undangömt i vildmarken."},{t="Ritualplatsen",b="När du hittar The Offering Stone i Beren's Peril avslöjar dess grova yta tecken på nylig och oroande aktivitet. Märkliga redskap och bisarra föremål ligger utspridda över stenen, vilket bekräftar att någon aktivt har använt platsen för att förbereda ett offer eller en mörk rit långt från nyfikna blickar."}},faq={{q="Vad är The Offering Stone?",a="The Offering Stone är ett väderbitet stenaltare i Beren's Peril i Silverpine Forest. Det verkar fungera som en samlingspunkt för mystiska förberedelser och mörka ritualer, och är täckt av bisarra redskap och ritualföremål.",al={"vad är offering stone","offering stone i silverpine","vad är det här för sten"}},{q="Var finns The Offering Stone?",a="The Offering Stone ligger i Beren's Peril, ett bergigt och farligt område i södra Silverpine Forest.",al={"var finns offering stone","offering stones plats","hitta offering stone"}},{q="Vem skapade eller använder The Offering Stone?",a="Den skadade lappen som hittades i närheten avslöjar inte vilka ritualisterna är, men redskapen och föremålen på stenen visar att någon aktivt förberedde ett offer eller en mörk rit i området.",al={"vem skapade offering stone","vem använder offering stone","vem utför ritualen"}},{q="Vad står det i den mystiska lappen?",a="Lappens pappersbit är till största delen väderbiten och oläslig, men läsliga fragment beskriver tydligt förberedelser inför en kommande ritual och pekar ut en offersten i närheten.",al={"vilken lapp","lappfragment i silverpine","vad står det i lappen"}},{q="Vad finns på The Offering Stone?",a="Stenens grova yta är täckt av märkliga verktyg, rituella redskap och diverse föremål som arrangerats för ett offer.",al={"vilka föremål finns på stenen","vilka redskap finns på stenen","offering stones föremål"}},{q="Vilken sorts ritual utförs här?",a="Även om de bevarade fragmenten av lappen inte beskriver ritens exakta natur, har stenen gjorts i ordning som ett altare där föremål eller offer placeras inför en ritual.",al={"vilken ritual vid offering stone","varför en offersten","vilket offer i silverpine"}}},fp="18,321,15.390.0,15.301.0,27.231.0,38.123.0,39.200.0,34.180.0,36.131.0,44.196.0"}
P.entries["quest:95885"] = {n="The Offering of Blood",s="The Offering of Blood är en mystisk ritual som utförs vid The Offering Stone i Beren's Peril. Med hjälp av en Tortured Soul offrar äventyrare blod vid stenen, enligt den sönderrivna anteckningen.",h="The Offering of Blood är en mystisk ritual som utförs vid The Offering Stone i Beren's Peril.",kw={"beren's peril","blodritual","offering of blood","offering stone","offer","silverpine forest","the offering of blood","tortured soul"},ang={["class:Priest"]="Präster som oroar sig för de bortgångna själarnas öde kan finna det moraliskt oroande att använda en plågad själ i en olycksbådande blodritual, oavsett om det ger varelsen ro.",["class:Warlock"]="Lockmästare är väl förtrogna med mörka riter och förhandlingar med själar, men även erfarna utövare av den brinnande legionens magi kan rysa inför att utföra ett blodoﬀer vid en uråldrig, okänd sten."},sec={{t="Den sista riten",b="Djupt inne bland klipporna i Beren's Peril ligger The Offering Stone, en olycksbådande relik som väntar på en sista, mörk uppgörelse. Ledda av ledtrådar i övergivna anteckningsfragment som kräver ett villigt offer får äventyrare ta med blodsoffret som krävs för att blidka altarets kvardröjande magi. När de närmar sig stenen med den rastlösa essensen fylls de av en överväldigande känsla av fasa."},{t="Stenen krossas",b="När Tortured Soul offras till stenen utlöses en kraftig reaktion som suger den kvardröjande kraften ur det uråldriga monumentet. I stället för att väcka en större fasa tömmer blodritualen reliken helt på kraft. Den skrovliga stenen berövas sitt magiska syfte, spricker och rasar samman till spillror, och blottar en glittrande belöning bland de krossade fragmenten."}},faq={{q="Var äger ritualen rum?",a="The Offering of Blood äger rum vid The Offering Stone i Beren's Peril i Silverpine Forest. Området är farofyllt och skuggas av mörk, kvardröjande magi.",al={"var finns uppdraget","var finns offering of blood","uppdrag i beren's peril"}},{q="Vad är The Offering Stone?",a="The Offering Stone är ett mystiskt, uråldrigt monument i Beren's Peril. Den kräver en mörk ritual – närmare bestämt ett blodoﬀer från ett villigt offer – för att låsa upp eller tömma kraften som slumrar inom den.",al={"vad är offering stone","offering stone i beren's peril","altare i beren's peril"}},{q="Vad används Tortured Soul till?",a="Ritualen kräver en Tortured Soul, som fungerar som det ”villiga offer” som nämns i återfunna anteckningsfragment. Själen förs fram till The Offering Stone för att fullgöra det blodoﬀer som den uråldriga reliken kräver.",al={"vem är tortured soul","vad är tortured soul","vilket offer behövs"}},{q="Vad händer när offret är fullbordat?",a="När ritualen fullbordas töms den mörka energin som besjälar The Offering Stone helt. Den skrovliga stenen har inte längre något syfte, spricker och smulas sönder, och lämnar något glittrande bland spillrorna.",al={"vad händer med stenen","går stenen sönder","vad händer efter ritualen"}},{q="Vem skapade stenen och varför?",a="Stenens exakta ursprung och slutliga syfte förblir en gåta. Riten tömmer stenen på dess vilande energi och förstör den, men det är fortfarande okänt vem som ursprungligen skapade monumentet och i vilket storslaget syfte.",al={"vem byggde offering stone","syftet med offering of blood","varför skapades stenen"}},{q="Vad är Beren's Peril?",a="Beren's Peril är ett klippigt landmärke i Silverpine Forest, känt för sina vilda djur och dolda faror. The Offering Stone visar att mörka riter och rastlösa själar också har satt sina spår på platsen.",al={"vad är beren's peril","lore om beren's peril","varför heter det beren's peril"}}},fp="21,202,14.388.0,18.371.1,34.176.0,27.217.0,35.211.0,44.213.0,30.244.0,22.216.0"}
P.entries["quest:959"] = {n="Trouble at the Docks",s="Crane Operator Bigglefuzz orsakade en klumpig lastolycka vid Ratchets hamn och lät därmed en småtjuv vid namn Mad Magglish stjäla en ovärderlig årgångsflaska. Årgången, en 99-Year-Old Port som skickats direkt från Baron Revilgaz till Gazlowe, måste återtas från skuggorna i Wailing Caverns innan hamnmästaren avskedar den försumlige kranföraren.",h="Crane Operator Bigglefuzz orsakade en klumpig lastolycka vid Ratchets hamn och lät därmed en småtjuv vid namn...",kw={"bigglefuzz","booty bay","gazlowe","magglish","portvin","ratchet","revilgaz","wailing caverns"},ang={["class:Rogue"]="Att jaga Mad Magglish handlar om att upptäcka slarviga gömställen, eftersom tjuven förlitar sig på enkel smygförmåga i grottans skrymslen för att undgå upptäckt.",["faction:Alliance"]="Även om du verkar djupt inne i det horddominerade The Barrens ger det trygg passage på neutrala vatten att hålla sig väl med Steamwheedles hamnoperatörer.",["faction:Horde"]="När du hjälper Ratchets hamnarbetare bidrar du till att hålla verksamheten i gång i den viktigaste neutrala hamnen som förbinder Kalimdor med Eastern Kingdoms."},sec={{t="Ett klantigt misstag",b="Ratchet blomstrar tack vare den ständiga sjöhandeln med Booty Bay på andra sidan Great Sea, men ibland brister goblinernas effektivitet under den enorma arbetsbördan. När en ovanligt stor morgonleverans anlände till hamnen försökte Crane Operator Bigglefuzz ta genvägar för att skynda på lossningen. Han lyfte långt mer än kranen klarade av och tappade hela lasten över kajen. I kaoset som följde utnyttjade en lokal bråkstake vid namn Mad Magglish de utspridda lådorna, snodde en enda värdefull spritflaska och flydde inåt land."},{t="En diplomatisk årgång",b="Den stulna lasten var långt mer än vanlig kajsprit. Flaskan var en 99-Year-Old Port, en personlig diplomatisk gåva från Baron Revilgaz, den ökände härskaren över Blackwater i Booty Bay, till Gazlowe, Ratchets chefsingenjör och övervakare. Förlusten av en så storslagen gåva riskerar att förödmjuka Bigglefuzz och göra båda handelsmogulerna ursinniga. Med jobbet, eller värre, på spel spårade Bigglefuzz tjuven till den olycksbådande öppningen till Wailing Caverns, men rädslan hindrade honom från att följa efter Magglish in."},{t="Grottans gömställe",b="Mad Magglish gav sig inte djupt in i själva grottfängelsets fördärvade drömlandskap, utan gömde sig i de vidsträckta, fuktiga naturliga tunnlarna utanför den inre ingången. Magglish förlitar sig på klumpig smygförmåga och mörka skrymslen och smyger genom de underjordiska grottorna i hopp om att förföljarna ska ge upp. För att återta portvinet måste tjuven drivas fram ur de yttre delarna innan årgången korkas upp eller förstörs."}},faq={{q="Varför är den här portvinsflaskan så viktig?",a="99-Year-Old Port är inget vanligt mäsk; det är en överdådig personlig gåva som Baron Revilgaz från Booty Bay skickade till Gazlowe, Ratchets chef. Om den går förlorad i en hamnolycka riskerar Ratchets ledning att bli rasande och Crane Operator Bigglefuzz att förlora sitt levebröd.",al={"varför bryr sig bigglefuzz","vad är 99-year-old port","varför är vinet viktigt"}},{q="Vem är Mad Magglish?",a="Mad Magglish är en opportunistisk tjuv och bråkstake som håller till i Ratchet. När Bigglefuzz tappade en enorm last på kajen tog Magglish den sällsynta portvinsflaskan och flydde rakt in i närbelägna Wailing Caverns för att gömma sig.",al={"vem är magglish","vem stal portvinet","mad magglishs bakgrund"}},{q="Måste jag gå in i grottfängelset Wailing Caverns för att hitta tjuven?",a="Nej. Mad Magglish gömmer sig i de slingrande, öppna grottpassagerna utanför instansportalen. Han använder dålig smygförmåga och håller till i de övre sidotunnlarna eller nära de översvämmade kamrarna som leder mot huvudingången.",al={"är magglish inne i instansen","var finns mad magglish","hitta magglish"}},{q="Hur gick lastolyckan till?",a="En enorm lastleverans anlände från Booty Bay, och Crane Operator Bigglefuzz försökte lossa fler lådor åt gången än utrustningen klarade av. Den överlastade kranen tappade lasten och spred värdefrakt över Ratchets kajer.",al={"varför föll lådorna","vad gjorde bigglefuzz","kranolycka i ratchet"}},{q="Vilken relation har Ratchet till Booty Bay?",a="Båda hamnstäderna är viktiga fästen för Steamwheedle Cartel och förenas av handel och kaparflottor. Regelbundna handelsleveranser och formella artighetsbetygelser utbyts mellan Baron Revilgaz i söder och Gazlowe i The Barrens för att hålla deras gemensamma handelsimperium vid liv.",al={"sambandet mellan ratchet och booty bay","steamwheedles hamnar","revilgaz och gazlowe"}},{q="Varför hämtade inte Bigglefuzz flaskan själv?",a="Bigglefuzz förföljde tjuven ända fram till ingången till Wailing Caverns, men den underjordiska labyrintens kusliga rykte och monstruösa invånare skrämde goblinen till att stanna vid tröskeln.",al={"varför hämtade inte goblinen flaskan","varför slutade bigglefuzz förfölja tjuven"}}},fx={b908c2b9={q="Varför behöver Crane Operator Bigglefuzz få tillbaka portvinet?",a="Bigglefuzz riskerar att förlora jobbet. När han försökte lasta av fler lådor än kranen klarade rasade hela morgonleveransen från Booty Bay. I kaoset försvann den eftertraktade flaskan med nittionioårigt portvin, och hamnmästaren har varit honom hack i häl sedan dess. Årgångsvinet var en personlig gåva till Ratchets chefsingenjör, Gazlowe. Om Bigglefuzz inte hittar den riskerar han omedelbar avskedning.",al={"varför vill bigglefuzz ha portvinet","bigglefuzz motiv","varför hjälpa bigglefuzz"}}},fp="20,361,15.535.0,18.522.0,18.419.0,40.271.0,20.238.0,65.208.0,31.240.0,55.258.0,50.207.0"}
P.entries["quest:95981"] = {n="Watching the Roads",s="Watching the Roads är ett uppdrag för de Fördömda i Silverpine Forest, utdelat av Shadow Priest Allister från The Sepulcher. Du ska anfalla Dalaran Wizards och Watchers längs vägarna nära Ambermill och stoppa Kirin Tors leveranser till de Fördömdas område.",h="Watching the Roads är ett uppdrag för de Fördömda i Silverpine Forest, utdelat av Shadow Priest Allister från...",kw={"ambermill","dalaran watcher","dalaran wizard","kirin tor","hängen","reliker","the sepulcher","shadow priest allister","silverpine forest","watching the roads"},ang={["class:Mage"]="Dalarans magiker och väktare förlitar sig på särskilda reliker och magiska patruller för att säkra passagen, vilket gör dem till självklara mål för rivaliserande magiker.",["class:Priest"]="Shadow Priest Allister leder offensiven från The Sepulcher och visar därmed hur aktivt de Fördömdas prästerskap deltar i gränsförsvaret.",["faction:Horde"]="Att störa Dalarans försörjningslinjer kring Ambermill hjälper Horden att behålla sitt fotfäste i området mot fientliga mänskliga enklaver.",["race:Undead"]="Att säkra transportvägarna genom Silverpine är avgörande för att de Fördömda ska kunna försvara sina gränser och stoppa Dalarans magiska intrång."},sec={{t="Spänningar längs vägen vid Ambermill",b="Längs vägarna runt Ambermill har Kirin Tor en aggressiv närvaro. Sedan barriären runt Dalaran föll har deras magiker och vaksamma väktare stramat åt resandet över gränsen till Silverpine Forest. Från sin bas i The Sepulcher ser de Fördömda denna upptrappning med växande oro. De inser att människornas magiker använder de öppna vägarna för att föra farliga reliker och förtrollade hängen djupt in i omstridda områden."},{t="Skär av försörjningslinjen",b="Shadow Priest Allister anser att beslagta enstaka hängen bara behandlar ett symptom. För att hejda flödet av magiska föremål från Dalaran skickar han ut agenter för att jaga Kirin Tors eskorter direkt längs vägen. Genom att slå ut både Dalaran Wizards och Dalaran Watchers nära Ambermill vill de Fördömda bryta Kirin Tors järngrepp om trafiken i området och stänga sin östra gräns för yttre magisk inblandning."}},faq={{q="Vem ger uppdraget Watching the Roads?",a="Uppdraget ges och slutförs hos Shadow Priest Allister, som finns i The Sepulcher i Silverpine Forest. Han ber hjältar anfalla Kirin Tors patruller längs de lokala handelsvägarna.",al={"vem ger watching the roads","uppdragsgivare watching the roads","var lämnar man in watching the roads"}},{q="Varför anfaller de Fördömda Dalarans patruller nära Ambermill?",a="Shadow Priest Allister vill stoppa det stadiga flödet av magiska reliker och hängen som transporteras från Dalaran till Silverpine Forest. Om magikerna och väktarna längs vägarna nära Ambermill elimineras förlorar Dalaran sin enkla passage över de Fördömdas gränser.",al={"varför döda dalaran wizards","varför anfalla vägarna vid ambermill","kirin tors syfte i silverpine"}},{q="Vad har hänt med barriären runt Dalaran?",a="Enligt Shadow Priest Allister har den skyddande barriären runt Dalaran fallit. Som svar har Kirin Tor stramat åt kontrollen över de omgivande vägarna och visar tydlig misstänksamhet när de patrullerar Ambermillområdet.",al={"vad hände med dalarans barriär","dalarans kupol har fallit","barriären har fallit i dalaran"}},{q="Var hittar man Dalaran Wizards och Watchers?",a="Både Dalaran Wizards och Dalaran Watchers patrullerar vägarna runt staden Ambermill i Silverpine Forest. De övervakar trafiken för att skydda förflyttningen av Kirin Tors personal och förtrollade föremål.",al={"var finns dalaran watchers","var patrullerar de vid ambermill","var hittar man dalaran wizards"}},{q="Vilka slags föremål skickar Dalaran längs vägarna?",a="Kirin Tor har fört förtrollade hängen och andra magiska reliker från Dalaran till Silverpine Forest. Allister vill strypa försörjningsvägen vid källan innan föremålen sprids vidare i området.",al={"vilka reliker skickar dalaran","vad är hängena","ambermill hängen"}},{q="Varför är Kirin Tor så vaksamma längs vägarna vid Ambermill?",a="Ända sedan den magiska barriären runt Dalaran föll har Kirin Tor hållit noggrann uppsikt över vägarna in i Silverpine Forest. Allister nämner deras djupa misstänksamhet och vaksamhet, men de Fördömda i The Sepulcher känner inte till deras exakta motiv.",al={"varför är kirin tor misstänksamma","varför patrullerar dalarans vakter","kirin tors kontroll över vägarna"}}},fp="18,263,33.480.0,24.437.0,39.205.0,62.268.0,54.243.0,52.225.0,57.239.0,60.284.0"}
P.entries["quest:95998"] = {n="The Great Outdoors",s="The Great Outdoors är ett introduktionsuppdrag i överlevnad i vildmarken, där resenären Sam lär nybörjare konsten att klara sig ute i naturen. Genom att stanna och vila vid en enkel lägereld lär sig resenärer att ta hand om sig längs vägen innan de ger sig in på särskilda yrkesfärdigheter.",h="The Great Outdoors är ett introduktionsuppdrag i överlevnad i vildmarken, där resenären Sam lär nybörjare...",kw={"enkel lägereld","förstärkt vila","lägeranordning","lägerliv","friluftsmänniska","sam","the great outdoors","yrkesfärdighet"},ang={["class:Hunter"]="Att leva av naturen och vila vid en öppen eld är en självklarhet för vildmarkens spejare, men även erfarna spanare har nytta av att behärska lägerliv.",["profession:Cooking"]="Lägereldar är en självklar del av matlagning ute i fält, och kunskaper om lägerliv i vildmarken ger grunden för att laga mat under bar himmel."},sec={{t="Lärdomar vid elden",b="Azeroths vidsträckta marker lockar oräkneliga rastlösa själar som söker rikedom, faror och berömmelse. Men rå ambition kan inte ensam skydda en nybörjare från bitande kyla eller utmattning längs den öppna vägen. Att behärska grundläggande vildmarkskunskaper – att veta när man ska stanna, göra upp en eld och samla krafter – är den stillsamma grund som varje legendarisk resa vilar på. Sams inbjudan ger nykomlingar en chans att stanna upp och lära sig dessa viktiga färdigheter för att klara sig utomhus."},{t="Friluftskunskap och yrken",b="Att söka skydd vid en varm lägereld gör mer än att hålla nattkylan stången; det ger ett viktigt tillfälle till återhämtning som kallas förstärkt vila. Erfarna överlevare vet att uthållighet i vildmarken beror på ordentlig vila mellan färderna. När grunderna i överlevnad sitter kan hantverkare och samlare rikta uppmärksamheten mot yrkesfärdigheter och lära sig att sätta ihop särskilda lägeranordningar som passar deras arbete ute i fält."}},faq={{q="Vem är Sam?",a="Sam är en erfaren friluftsmänniska och van resenär som tagit på sig att lära nybörjare grunderna i att överleva ute i vildmarken. Han välkomnar vandrare att dela värmen från hans eld medan han förmedlar praktiska kunskaper om friluftsliv.",al={"vem är sam","sams lägereldsuppdrag","uppdragsgivare"}},{q="Varför ska man sitta vid lägerelden?",a="Förstärkt vila är den återhämtande effekten av att vila vid en ordentlig lägereld ute i vildmarken. När trötta äventyrare tar sig tid att sitta i värme och bekvämlighet kan de återfå sin kraft och hålla sig utvilade inför vägen vidare.",al={"vad är förstärkt vila","förstärkt vilas förstärkning","vila vid elden"}},{q="Varför är vildmarkskunskaper viktiga för äventyrare?",a="Världen utanför bosättningarnas murar är vidsträckt och farofylld, och alla vandrare som söker rikedom och ära måste lära sig att ta hand om sig själva. God fältkunskap gör att resenärer kan klara långa färder utan att duka under för tröttheten.",al={"varför lära sig friluftskunskaper","varför klara sig i vildmarken","överlevnadskunskaper"}},{q="Hur hänger yrkesfärdigheter ihop med lägerliv i vildmarken?",a="När du har lärt dig att slå upp ett enkelt läger kan yrkesmästare lära dig att tillverka särskilda lägeranordningar som passar ditt valda yrke och förbättrar dina möjligheter när du befinner dig ute i fält.",al={"yrkesfärdigheter och lägerliv","lägeranordningar","yrken efter detta"}},{q="Vad bör en äventyrare göra efter den här lektionen?",a="När du har vilat vid Sams eld och förstått grunderna i lägerliv uppmanar Sam dig att söka upp yrkeslärare. Om du utvecklas inom ett praktiskt hantverk kan du bygga anpassade fältstationer som passar ditt yrke.",al={"nästa steg","vad efter the great outdoors","efter lägereldsuppdraget"}},{q="Vem kan ta sig an The Great Outdoors?",a="Uppdraget är öppet för alla rastlösa själar som ger sig ut i den större världen, oavsett bakgrund eller lojalitet, och fungerar som en introduktionslektion i att klara livet längs vägen.",al={"kan vem som helst göra detta","vem kan ta sig an the great outdoors","är det här ett allmänt uppdrag"}}},fp="18,291,19.479.0,20.460.0,11.258.0,47.240.0,52.235.0,48.215.0,58.210.0,37.177.0"}
P.entries["quest:95999"] = {n="WANTED: Incinerator Gar'im",s="WANTED: Incinerator Gar'im är en efterlysning från myndigheterna i Lakeshire efter en fientlig orchbefälhavare som håller stånd i Render's Valley. Gar'im leder en farlig grupp skuggmagiker och sägs samarbeta med Blackrock-klanen som håller Stonewatch Keep. Magistrate Solomon utlovar en generös belöning för bevis på att han dödats.",h="WANTED: Incinerator Gar'im är en efterlysning från myndigheterna i Lakeshire efter en fientlig...",kw={"blackrock","belöning","gar'im","incinerator","lakeshire","render's valley","skuggmagiker","solomon"},ang={["class:Mage"]="Gar'im och hans skuggmagiker utövar förvrängd offensiv trollkonst och skuggmagi, något som kräver ett snabbt motangrepp med besvärjelser.",["faction:Alliance"]="Genom att fälla Incinerator Gar'im skyddar du Lakeshires utsatta invånare direkt från ledaren för orchernas anfall och hans ytterst farliga skuggmagiker."},sec={{t="En brand i Render's Valley",b="Redridge Mountains har blivit allt farligare när Blackrock-orcherna tränger ut från sina fästen i bergen. I Render's Valley leder Incinerator Gar'im ett aktivt anfall och går i spetsen för mörk magi tillsammans med sina lojala skuggmagiker. Med ortens vakter hårt ansatta och kronans arméer till stor del frånvarande har Magistrate Solomon vänt sig till fristående legoknektar för att göra sig av med Gar'im, som sägs samarbeta med Blackrock-orcherna i Stonewatch Keep."},{t="Bevis på dödsfall",b="Gar'im är känd för sin förödande magi och sitt befäl över skuggvävare. För att få ortens belöning måste jägare ta sig djupt in på fiendens territorium, besegra förbrännaren och återföra hans krossade stav till stadshuset i Lakeshire som ett konkret bevis på att hotet har undanröjts."}},faq={{q="Vem är Incinerator Gar'im?",a="Incinerator Gar'im är en orchkrigsherre och magiker som leder ett anfall i Render's Valley. Han sägs samarbeta med Blackrock-orcherna i Stonewatch Keep och för befäl över farliga skuggmagiker.",al={"vem är gar'im","gar'im","incinerator gar'im"}},{q="Var finns Incinerator Gar'im?",a="Gar'im har sitt läger bland de fientliga orchstyrkorna i Render's Valley, i sydöstra Redridge Mountains.",al={"gar'ims plats","var finns gar'im","render's valley plats"}},{q="Vem utfäste belöningen för Gar'im?",a="Magistrate Solomon utfäste belöningen på Lakeshires vägnar. Han är desperat att hejda orchernas anfall mot den hårt ansatta orten.",al={"vem utfäste belöningen","solomons belöning"}},{q="Vilket bevis krävs för att få belöningen?",a="Magistrate Solomon kräver Broken Staff of Incinerator Gar'im som bekräftelse på att magikern har dödats innan han betalar ut belöningen.",al={"gar'ims bevis","broken staff uppdragsföremål"}},{q="Vilket hot utgör Gar'im och hans följeslagare?",a="Gar'im brukar dödlig, förödande magi och har skuggmagiker vid sin sida. Deras närvaro stärker Blackrock-klanens fotfäste i Redridge och hotar att övermanna Lakeshire om de inte stoppas.",al={"gar'ims förmågor","skuggmagiker i redridge"}},{q="Varför förlitar sig Lakeshire på belöningar i stället för Stormwinds armé?",a="Stormwind har i stort sett lämnat Redridge att försvara sig självt mitt i politiska stridigheter och brist på trupper, vilket tvingar Magistrate Solomon att anlita äventyrare som är villiga att lönnmörda fiendens ledare.",al={"varför belöningar i lakeshire","var är stormwinds armé"}}},fp="26,345,25.467.0,15.302.0,26.204.0,38.125.0,33.149.0,43.132.0,45.192.0,68.180.0"}
P.entries["quest:96"] = {n="Call of Water",s="Du för Shard of Water tillbaka till Islen Waterseer längs The Barrens kust. Din resa visar att du är i harmoni med läkande krafter och ger dig en Water Totem.",h="Du för Shard of Water tillbaka till Islen Waterseer längs The Barrens kust.",kw={"call of water","islen waterseer","minor manifestation of water","shard of water","silverpine forest","the barrens","water totem"},ang={["class:Shaman"]="Som schaman får du din Water Totem och tillgång till de läkande källorna och renande fontänerna som är centrala för din roll som andlig helare.",["faction:Horde"]="Som medlem av Horde delar du ansvaret för landets andar. Unga schamaner kallas att rena fördärvade områden i Kalimdor och Eastern Kingdoms."},sec={{t="En lång resa hem",b="Du för med dig en gåva från Minor Manifestation of Water tillbaka över havet. För att förtjäna den korsade du kontinenter till Silverpine Forests fördärvade stränder och mötte förruttnelsen där. Vatten ger liv, anpassar sig och läker, men dess följsamma natur gör det sårbart för vanmakt och mörk magi. Inför Minor Manifestation bevittnade du ren elementär vilja och fick Shard of Water. Nu, när du återvänder till The Barrens solstekta marker, påminner skärvan dig om att vatten förbinder avlägsna delar av världen."},{t="Water Totem",b="När du ger skärvan till Islen Waterseer väger hon in mer än ett bevis på din resa. Hon prövar om du har lärt dig balansen mellan bevarande och förnyelse. Lordaerons utbredande förruttnelse kan dölja små segrar, men även reningen av en enda källa betyder något för andarna. Islen godtar din gåva och ger dig en Water Totem. Genom den kan du leda renande, läkande och manaåterställande strömmar in i den dödligas värld och knyta dig till tidvattnet."}},faq={{q="Vad är Shard of Water?",a="Shard of Water är en elementär lämning som Minor Manifestation of Water gav dig. Den visar att du förstår vattnets livgivande kraft och har stått emot förruttnelsen som hotar de elementära strömmarna.",al={"shard of water","vattenskärva","vad är skärvan"}},{q="Vart ska jag ta Shard of Water?",a="För Shard of Water till Islen Waterseer vid hennes avskilda läger på The Barrens östra kust, söder om Ratchet.",al={"var lämnar man in","vem får skärvan","inlämningsplats"}},{q="Vad får jag när jag klarar den här prövningen?",a="Du får en Water Totem, den kanal schamaner behöver för att åkalla elementära vattentotemer för läkande och återställande magi.",al={"uppdragsbelöning","totembelöning","vad får jag"}},{q="Varför ägde prövningen rum i Silverpine Forest?",a="Vattnen i Silverpine Forest är svårt förorenade av pest och skuggmagi. Där bevittnade du vattnets skörhet och försvarade dess naturliga renhet mot förruttnelse.",al={"varför silverpine","varför eastern kingdoms","silverpines vatten"}},{q="Vem är Islen Waterseer?",a="Islen Waterseer är en tauren-schaman på The Barrens östra kust. Hon övervakar schamanernas vattenprov och lär invigda att kommunicera med vattenandar och bemästra läkande konster.",al={"islen","vem är islen waterseer"}}},fx={["352084e3"]={q="Varför skickar Minor Manifestation of Water dig tillbaka till Islen?",a="Elementaruppenbarelsen är den levande rösten för rent vatten, prövad och åkallad genom dina ritualer. När den ger dig Shard of Water anförtros du den grundläggande sanningen om dess natur: vatten skänker liv, medan fördärv släcker det. Den skickar dig tillbaka till Islen Waterseer så att schamanen kan bekräfta din kontakt med andarna, erkänna din framgång i kampen mot fördärvet och ge dig den vatten-totem du visat dig värdig att bära.",al={"minor manifestation motiv","varför ta shard till islen","varför vill vattenmanifestationen ha detta"}}},fp="13,165,19.504.0,15.458.0,27.203.0,35.113.0,44.123.0,43.166.0,23.188.0"}
P.entries["quest:960"] = {n="Onu is meditating",s="När Onu, en urgammal kunskapsbärare, undersöker The Master's Glaive i södra Darkshore, går han in i djup trans för att begrunda det växande hotet. Om du tappar bort din mystiska spådomsampull kan du tala med den mediterande Onu och få en ersättningsampull. Hans tankar kretsar kring den illvilliga alliansen och motiven hos kulten Twilight's Hammer och de serpentinlika naga.",h="När Onu, en urgammal kunskapsbärare, undersöker The Master's Glaive i södra Darkshore, går han in i djup...",kw={"darkshore","grove of the ancients","the master's glaive","mediterar","onu","phial of scrying","spådomsskål","twilight's hammer"},ang={["class:Druid"]="Druider har ett djupt naturligt band till Ancient of Lore. Att upprätthålla kommunikationen med spådomsritualer speglar Cenarion Circles sätt att undersöka fördärvad mark på avstånd.",["faction:Alliance"]="Att skydda Darkshore från kultister och vattenlevande inkräktare är avgörande för Alliance-resenärer som färdas mellan Teldrassil och Ashenvale.",["race:NightElf"]="Som väktare av Kalimdors balans vördar nattalverna Ancient of Lore som Onu och förlitar sig på deras tidlösa visdom för att tolka störningar i Darkshores vildmarker."},sec={{t="Ett sinne i djup begrundan",b="Onu är en Ancient of Lore med rötterna i Grove of the Ancients i Darkshore, och han är ett levande arkiv över Kalimdors historia. När oroväckande rapporter dyker upp om mörka utgrävningar vid The Master's Glaive vänder Onu sitt väldiga medvetande inåt. Han begrundar intensivt vad som kan locka både fanatiska anhängare av kulten Twilight's Hammer och de lömska naga till de förstenade kvarlevorna av en uråldrig jätte. För äventyrare som utför spaning åt honom är han en tillgänglig trygghet och erbjuder ersättningsampuller för spådom om de skulle tappa bort sina ute i vildmarken."},{t="Skåda djupen",b="För att övervaka ruinerna utan att riskera sin fysiska närvaro förlitar sig Onu på naturbunden spådomskonst. Äventyrarna får en spådomsampull som ska framkalla en spådomsskål direkt vid utgrävningsplatsen, så att Onu kan kommunicera på avstånd. Eftersom färden söderut genom Darkshore är farlig och kantad av fientligt djurliv och kultpatruller räknar Onu med missöden. Hans trans är ingen obruten sömn, utan en uppmärksam vaka; han ger gärna en ny ampull med heligt vatten för att se till att undersökningen av The Master's Glaive kan fortsätta utan dröjsmål."}},faq={{q="Varför mediterar Onu?",a="Onu är en Ancient of Lore som begrundar den oroande närvaron av både kulten Twilight's Hammer och naga vid The Master's Glaive. Han mediterar för att uppfatta deras motiv och vägleda äventyrare som undersöker platsen.",al={"varför mediterar onu","onus trans","vad gör onu"}},{q="Vad är syftet med den här interaktionen?",a="Den fungerar som en säkerhetsåtgärd för spelare på uppdraget 'The Master's Glaive'. Om du tappar bort, förstör eller använder din Phial of Scrying i förtid kan du tala med den mediterande Onu för att få en ersättningsampull och kunna slutföra ritualen.",al={"tappat phial of scrying","få en ny ampull","onus ersättningsuppdrag"}},{q="Var finns Onu?",a="Onu har sina rötter i Grove of the Ancients, som ligger i centrala södra Darkshore, strax intill huvudvägen.",al={"onus plats","var hittar man onu"}},{q="Vad gör jag med Phial of Scrying?",a="Ta med ampullen till The Master's Glaive och använd den för att skapa en spådomsskål. Då kan Onu kommunicera med dig genom skålen.",al={"hur använder man phial of scrying","spådomsskål i darkshore","syftet med phial of scrying"}},{q="Vad är The Master's Glaive?",a="The Master's Glaive är en väldig, uråldrig utgrävningsplats i södra Darkshore, där en bortglömd varelses kolossala, förstenade skalle genomborras av ett enormt svärd. Kultister och naga har samlats där i okända, illvilliga syften.",al={"vad är the master's glaive","monument i södra darkshore"}},{q="Kan spelare i Horde interagera med Onu här?",a="Nej. Onu är enbart allierad med nattalverna och Alliance. Äventyrare från Horde som tar sig in i området nära Grove of the Ancients kommer att finna Onu och hans beskyddare fientliga eller ovilliga att samarbeta.",al={"är onu bara för alliance","horde onu mediterar"}}},fx={["72a6a09e"]={q="Varför behöver Onu din hjälp i stället för att undersöka själv?",a="Onu stannar i Grove of the Ancients för att meditera över Twilight's Hammer och naga. Han förlitar sig på resenärer som undersöker The Master's Glaive och kontaktar honom genom en spådomsskål.",al={"varför skicka mig","varför går inte onu själv","varför behöver onu dig"}}},fp="17,255,28.455.0,18.502.0,22.190.0,40.183.0,21.97.0,39.127.0,28.236.0,41.173.0"}
P.entries["quest:96031"] = {n="Camping 101: Leatherworking",s="Camping 101: Leatherworking vägleder hantverkare i hur garvade hudar kan användas för att skapa ett eget, portabelt skydd i vildmarken. Den betonar vad som krävs för att överleva långt från civilisationen och påminner äventyrare om att ett riktigt läger behöver både ett uppslaget tält i vildmarken och en sprakande lägereld, något matlagningsinstruktörer lär ut.",h="Camping 101: Leatherworking vägleder hantverkare i hur garvade hudar kan användas för att skapa ett eget...",kw={"lägertält","lägereld","camping","matlagning","läderarbete","skydd","tält","vildmark"},ang={["profession:Cooking"]="En lägereld är en oumbärlig mittpunkt på varje lägerplats i vildmarken. Med grundläggande kunskaper i matlagning kan en äventyrare tända en eld och hålla lägret vid liv ute i vildmarken."},sec={{t="Slå upp skydd i vildmarken",b="Att skapa ett eget skydd är en viktig milstolpe för alla hantverkare som arbetar med hudar och läder. Ett stadigt lädertält skyddar vandrare mot hårt väder, vind och nattkyla när de färdas över öppna vidder. Men ortsbor ogillar när personliga skydd slås upp på trånga gator eller torg, så en äventyrare måste ta sig ut genom stadsportarna till den otämjda vildmarken för att slå upp sitt tält."},{t="Lägereldens värme",b="Ett uppslaget tält är bara halva grunden till en hållbar lägerplats. Ett riktigt läger behöver en sprakande lägereld som håller mörkret borta, värmer mot kalla vindar och ger en härd i farliga trakter. Eftersom det är grundläggande att kunna bygga och sköta en eld för att laga mat i fält, får äventyrare rådet att söka vägledning hos matlagningsmästare och matlagningsinstruktörer för att lära sig tända en lägereld innan de slår läger."}},faq={{q="Var kan du slå upp ett tält?",a="Ortsbor ogillar när tält slås upp mitt på gator eller torg. En äventyrare måste ta sig ut i den otämjda vildmarken, där det finns gott om öppen mark för att slå upp ett tält ordentligt.",al={"använda tält","var slå upp tält","kan jag campa i staden"}},{q="Vad behövs mer än ett tält för att slå läger?",a="Ett tält räcker inte för att skapa ett fungerande läger. Du behöver också en ordentlig lägereld som brinner bredvid tältet innan en riktig lägerplats kan ordnas.",al={"behövs eld för läger","krav för läger","hur man campar"}},{q="Var lär sig äventyrare att göra upp en lägereld?",a="Instruktörer inom matlagningskonsten lär ut grunderna i matlagning, bland annat hur man tänder och håller liv i en enkel lägereld. En matlagningsinstruktör kan lära dig hur du gör upp eld var som helst.",al={"lära sig göra upp eld","vem lär ut lägereld","matlagningseld"}},{q="Hur hänger läderarbete ihop med att tillverka tält?",a="Läderarbetare använder garvade hudar, skinn och stadiga sömmar för att skapa hållbara skydd som står emot vildmarkens hårda förhållanden. Med detta praktiska hantverk kan vandrare sätta ihop ett pålitligt skydd av djurhudar.",al={"camping 101 läderarbete","lädertält för läger","tälttillverkning läderarbete"}},{q="Varför slår äventyrare läger i vildmarken?",a="När resenärer tar sig långt bortom bebodda utposter utsätts de för väder och farlig terräng. Ett portabelt skydd och en varm eld ger en trygg plats att vila och återhämta sig på, långt från värdshus och bosättningar.",al={"varför campa ute","syftet med camping","överlevnadsläger i vildmarken"}},{q="Varför motsätter sig ortsbor att man slår upp tält i staden?",a="Bosättningar och städer har värdshus och privata logier för resenärer. Tält på offentliga gator blockerar framkomligheten och orsakar störningar, så ortsborna insisterar på att läger hålls ute i vildmarken.",al={"campingregler i staden","inga tält i staden","varför kan jag inte slå upp tält i staden"}}},fp="27,322,28.477.0,24.427.0,32.206.0,53.152.0,47.220.0,54.235.0,53.215.0,56.216.0"}
P.entries["quest:96044"] = {n="Camping 101: Blacksmithing",s="Camping 101: Blacksmithing är en introduktionsuppgift som hänvisar smeder till Tognus Flintfire i Kharanos. Där lär sig hantverkare att tillverka ett portabelt Sharpening Wheel för att underhålla vapen på lägerplatser ute i vildmarken.",h="Camping 101: Blacksmithing är en introduktionsuppgift som hänvisar smeder till Tognus Flintfire i Kharanos.",kw={"smide","klingor","läger","camping 101","dun morogh","kharanos","sharpening wheel","tognus flintfire","vapen"},ang={["class:Rogue"]="En vass dolk är ett viktigt redskap för skurkar, så ett Sharpening Wheel i lägret är välkommet mellan uppdrag ute i fält.",["class:Warrior"]="Krigare förlitar sig på vassa eggar i stridens hetta och har direkt nytta av smeder som tar med Sharpening Wheel till expeditionens läger.",["profession:Blacksmithing"]="Blivande smeder kan lära sig att tillverka redskap för fältbruk, som Sharpening Wheel, och använda sitt hantverk långt från stadssmedjor för att hjälpa sina allierade ute i vildmarken.",["race:Dwarf"]="När Kharanos ligger inbäddat vid Dun Moroghs snöiga fotkullar är dvärgiska smeder stolta över att hålla kallt stål vasst och redo för alla vägar."},sec={{t="Underhåll ute på vägarna",b="Camping 101: Blacksmithing hjälper blivande smeder att lära sig hantverket för bruk ute i fält. I en stadssmedja kan man smida en harneskplåt eller ett svärd, men resande äventyrare behöver underhåll långt från stadsmurarnas bekvämlighet. Smeder som visar grundläggande skicklighet hänvisas till Kharanos, där mästersmeder lär ut hur man förvandlar rå metall till portabla lägerredskap som håller klingor vassa under långa resor."},{t="Mästaren i Kharanos",b="I den snöiga bosättningen Kharanos lär Tognus Flintfire skickliga smeder att tillverka ett Sharpening Wheel. När en sådan slipsten ställs upp på en lägerplats blir en vanlig viloplats en tillfällig vapensmedja. Krigare och skurkar kommer dit för att slipa bort hack och slöa eggar innan nästa marsch."}},faq={{q="Vem är Tognus Flintfire?",a="Tognus Flintfire är en smidesinstruktör i staden Kharanos i Dun Morogh. Han utbildar smeder som har visat tillräcklig skicklighet i sitt yrke och lär dem att tillverka särskild utrustning för lägerplatser.",al={"vem är tognus flintfire","var finns tognus","tognus flintfires plats"}},{q="Vad är ett Sharpening Wheel?",a="Sharpening Wheel är ett lägerredskap som smeder tillverkar. När det ställs upp vid en äventyrares läger blir det en arbetsplats där allierade som använder vapen, till exempel krigare och skurkar, kan vässa och underhålla klingornas eggar ute i fält.",al={"vad gör sharpening wheel","sharpening wheel i lägret","syftet med sharpening wheel"}},{q="Varför har krigare och skurkar nytta av Sharpening Wheel?",a="Krigare och skurkar har störst nytta av ett Sharpening Wheel i lägret, eftersom deras effektivitet i strid till stor del beror på att hålla klingor, yxor och dolkar rakbladsvassa under långa resor långt från stadssmedjor.",al={"vem behöver sharpening wheel","sharpening wheel för krigare","sharpening wheel för skurkar"}},{q="Var ligger Kharanos?",a="Kharanos är en livlig dvärgisk bosättning strax sydväst om Ironforge, bland de snöiga topparna i Dun Morogh. Det är en viktig samlingsplats och handelsstation för resenärer, gruvarbetare och hantverkare som färdas genom bergspassen.",al={"var ligger kharanos","kharanos läge","hitta kharanos"}},{q="Vad krävs för att lära sig tillverka det här lägerföremålet?",a="Smeder måste först visa grundläggande skicklighet i sitt yrke innan Tognus Flintfire lär dem att tillverka utrustning för lägerplatser. När du har övat på grunderna vid ett städ lär han dig att smida det portabla hjulet.",al={"krav för camping 101 blacksmithing","när kan jag lära mig sharpening wheel","smedsträning i lägret"}},{q="Varför tillverkar smeder lägerföremål?",a="Lägerföremål gör att smeder kan hjälpa äventyrssällskap utanför städerna. I stället för att följeslagarna ska behöva återvända till en stor stadssmedja för grundläggande vapenunderhåll ger ett portabelt redskap som Sharpening Wheel nödvändigt underhåll under bar himmel.",al={"varför tillverka lägerföremål","lägerföremål för smeder","smedsredskap ute i vildmarken"}}},fp="26,222,35.414.0,22.341.0,24.241.0,27.260.0,59.233.0,18.230.0,44.226.0,39.266.0"}
P.entries["quest:96045"] = {n="Camping 101: Alchemy",s="Camping 101: Alchemy introducerar blivande alkemister i Ironforge till praktiskt friluftsliv under Vosur Brakthels ledning. Genom att lära sig att bygga en Mana Well till sina läger i vildmarken kan alkemister ge magiker och helare på resande fot välbehövlig återhämtning.",h="Camping 101: Alchemy introducerar blivande alkemister i Ironforge till praktiskt friluftsliv under Vosur...",kw={"alkemi","lägereld","lägerliv","camping 101: alchemy","ironforge","mana well","vosur brakthel"},ang={["faction:Alliance"]="Blivande alkemister som besöker dvärgarnas fäste Ironforge kan rådfråga Vosur Brakthel om hur de kan förbättra sina expeditioner med återställande brygder.",["profession:Cooking"]="Ett ordentligt läger behöver en enkel lägereld, en praktisk färdighet som matlagningslärare lär ut runt om i världen och som kompletterar specialiserat lägerhantverk."},sec={{t="Brygder på resande fot",b="För alkemister som vågar sig ut i Azeroths otämjda trakter är det bara halva hantverket att brygga elixir i ett stilla laboratorium. I Ironforge, dvärgarnas storslagna huvudstad, lär alkemisten Vosur Brakthel ut hur utövare kan anpassa sitt finstämda hantverk till vildmarkens strapatser. Genom att visa sina färdigheter i alkemi lär sig äventyrare att omsätta sina kunskaper i att skapa en Mana Well, en flyttbar lägeranordning som ska hjälpa följeslagare ute i fält."},{t="Läger i vildmarken",b="En Mana Well ger trötta helare och magiker välkommen återhämtning, men den passar inte mitt på en kullerstensgata. Stadsbor ser ogärna att resenärer slår upp tält inne i städer, så sådana anordningar måste tas med ut i vildmarken. Dessutom är inget läger komplett utan glöden från en ordentlig lägereld. Därför bör blivande lägerbyggare söka råd hos lokala kockar innan de ger sig ut i det vilda."}},faq={{q="Vem är Vosur Brakthel?",a="Vosur Brakthel är en alkemilärare som bor i bergsstaden Ironforge. Han lär blivande alkemister hur de kan använda sina kunskaper i att brygga drycker för att skapa en Mana Well som hjälper äventyrare ute i fält.",al={"vem lär ut camping 101: alchemy","vosur brakthels roll","vem är vosur brakthel"}},{q="Vad är en Mana Well?",a="En Mana Well är en lägeranordning som skapas av en alkemist för att återställa magikers och helares krafter. När den placeras i ett läger ute i vildmarken erbjuder den magiker en uppfriskande dryck som fyller på deras magiska energi under långa resor.",al={"vad gör en mana well","mana wells syfte","varför skapa en mana well"}},{q="Kan du slå läger i Ironforge?",a="Stadsbor ogillar i regel att man slår läger på stadens gator. Alkemister som vill bygga ett läger och placera ut sin Mana Well måste resa bortom stadsmurarna, ut i vildmarken.",al={"kan jag slå läger i ironforge","slå läger i staden","var placeras en mana well"}},{q="Vad mer behövs för att slå läger?",a="Varje läger behöver en enkel lägereld som grund. Äventyrare som ännu inte kan göra upp eld bör söka upp en matlagningslärare för att lära sig grunderna i att göra upp eld inför matlagning innan de ger sig av.",al={"krav på lägereld","behöver jag kunna matlagning för att slå läger","hur börjar jag slå läger"}},{q="När kan en alkemist lära sig att skapa en Mana Well?",a="Vosur Brakthel erbjuder sig att undervisa alkemister när de har börjat med yrket och visat prov på viss skicklighet. När de har tillräcklig erfarenhet får de lära sig hemligheterna bakom att sätta ihop en Mana Well.",al={"när kan jag lära mig mana well","krav för mana well","krav för camping 101"}},{q="Vilka har mest nytta av en Mana Well i lägret?",a="Mana Well är främst till nytta för magiker och helare som magiker, präster och druider. De behöver ofta fylla på sina manareserver när de färdas långt från stadens värdshus och härdstenar.",al={"vem har nytta av mana well","klasser som använder mana well","vem använder mana well"}}},fp="20,273,20.475.0,20.465.0,22.228.0,20.235.0,39.195.0,37.203.0,48.215.0,43.202.0"}
P.entries["quest:96046"] = {n="Camping 101: Mining",s="Camping 101: Mining lär gruvarbetare att tillverka en lodestone för att slå läger ute i vildmarken. Det är ett viktigt steg i överlevnadsträningen och visar hur vildmarksliv bygger på mineralbearbetning och grundläggande eldning.",h="Camping 101: Mining lär gruvarbetare att tillverka en lodestone för att slå läger ute i vildmarken.",kw={"lägereld","camping","camping 101: mining","lägerplats","matlagning","lodestone","gruvdrift","vildmark"},ang={["profession:Cooking"]="Lägerbyggande hänger nära samman med grundläggande matlagningskunskaper, eftersom varje användbart skydd behöver en ordentlig lägereld som matlagningsinstruktörer lär ut.",["profession:Mining"]="Gruvarbetare lär sig forma rå jord och mineralmalm till en lodestone, ett viktigt redskap för att förankra läger ute i vildmarken."},sec={{t="Fältkunskap för gruvarbetare",b="Att ge sig bortom de bevakade vägarnas trygghet kräver självständighet och fältkunskap. Gruvarbetare lär sig använda sina kunskaper om mineraler och sten för att tillverka en lodestone, en förankringsdel som behövs för att slå upp ett fungerande läger ute i den otämjda världen."},{t="Vildmarkens regler",b="Folk som bor i samhällen ser inte med blida ögon på resenärer som slår upp skydd mitt på torg eller livliga genomfartsleder. För att slå läger måste du bege dig ut i vildmarken, bort från stadens gränser. Dessutom är ingen lägerplats i vildmarken riktigt användbar utan en sprakande lägereld som håller nattkylan stången, så grundläggande eldning för matlagning är ett oumbärligt komplement till mineralarbete."}},faq={{q="Vad används en lodestone till?",a="En lodestone är ett grundläggande verktyg som överlevare i vildmarken använder för att upprätta och förankra ett eget läger ute i det fria.",al={"lodestones syfte","vad används lodestone till","varför tillverka lodestone"}},{q="Kan jag slå läger i en stad?",a="Stadsbor och samhällets myndigheter ogillar när äventyrare slår upp tält och läger på offentliga torg eller gator, så du måste bege dig ut i vildmarken för att slå läger.",al={"kan jag slå läger i staden","slå läger i staden","slå läger i samhälle"}},{q="Vad behöver jag innan jag slår läger?",a="Ett läger måste ha en varm lägereld för att räknas som komplett. Du kan inte slå upp lägret ordentligt utan en eld som brinner i närheten.",al={"behöver jag en lägereld","hur gör jag ett läger","krav för läger"}},{q="Var lär jag mig att göra upp en lägereld?",a="Grundläggande eldning är en viktig del av matlagningens konst och lärs gärna ut av kockinstruktörer och kockar runt om i Azeroth.",al={"var lär jag mig göra upp eld","vem lär ut att göra upp eld","lägereldsinstruktör"}},{q="Hur hänger gruvdrift ihop med att tillverka en lodestone?",a="Gruvarbetare har yrkeskunskaperna som krävs för att utvinna och bearbeta de naturliga mineraler och den sten som behövs för att tillverka en lodestone.",al={"varför gruvarbetare slår läger","gruvdrift och lodestone","tillverka lodestone"}},{q="Vart ska jag gå för att prova mitt nya läger?",a="Du bör ta dig förbi stadsportarna och ut i den öppna vildmarken, där det finns gott om fri mark och inga ogillande stadsbor.",al={"var prova läger","prova lodestone","slå läger utomhus"}}},fp="19,241,21.247.0,17.389.0,29.133.0,40.192.0,42.126.0,41.126.0,48.123.0,38.136.0"}
P.entries["quest:96047"] = {n="Camping 101: First Aid",s="Uppgiften vägleder nybörjare inom läkekonst i Dun Morogh till att utöka sina överlevnadskunskaper bortom enkla bandage. Genom att söka upp Thamner Pol i Kharanos får äventyrare lära sig att sätta ihop ett särskilt First Aid Kit som håller lägerresenärer vid liv ute i fält.",h="Uppgiften vägleder nybörjare inom läkekonst i Dun Morogh till att utöka sina överlevnadskunskaper bortom...",kw={"bandage","camping 101","dun morogh","first aid","first aid kit","kharanos","överlevnad","thamner pol"},ang={["faction:Alliance"]="Alliansens rekryter lär sig tidigt, under sin utbildning i Khaz Modans frusna hjärta, att självförsörjning och fältmedicin är viktiga tillgångar för varje militär enhet och expeditionsgrupp.",["race:Dwarf"]="Dvärgiska bergsklättrare förlitar sig i hög grad på robust och praktisk utrustning när de patrullerar Dun Moroghs höga, snöiga bergspass. Därför är ett första hjälpen-kit för lägret en oumbärlig del av överlevnadsutrustningen.",["race:Gnome"]="Flyktingar och gnomiska vandrare som utgår från Kharanos har stor nytta av effektiv fältmedicin när de överlever utanför Gnomeregans förlorade salar."},sec={{t="Vårda sår ute i vildmarken",b="Äventyrare som trotsar Dun Moroghs frusna vidder upptäcker snart att linnetrasor och hastiga stygn bara är början på läkekonst för överlevnad. Verklig överlevnad i vildmarken hänger ofta på att ha ordentliga förråd vid en rastplats. De som visar fallenhet för grundläggande vård hänvisas till lokala hantverkslärare i Kharanos, som kan lära dem att förvandla råa sjukvårdsförnödenheter till kompletta kit för överlevnad i lägret."},{t="Lärdomar från Kharanos",b="I den livliga byn Kharanos förmedlar Thamner Pol praktiska metoder för att utrusta expeditionsplatser med nödförnödenheter. Den som vet hur man sätter ihop ett ordentligt fältkit kan se till att hela gruppen kan förbinda sår och återfå sin uthållighet tillsammans vid härden innan de ger sig ut i den bitande kylan igen."}},faq={{q="Vad är syftet med den här uppgiften?",a="Uppgiften leder nyutbildade fältmediciner till Thamner Pol i Kharanos, där han lär dem att tillverka funktionella First Aid Kits för äventyrares lägerplatser.",al={"varför camping 101: first aid","vad gör det här uppdraget","målet med camping 101"}},{q="Vem är Thamner Pol?",a="Thamner Pol är en tränare i staden Kharanos i Dun Morogh. Han lär skickliga överlevare att tillverka yrkesrelaterad utrustning som förbättrar deras läger i vildmarken.",al={"vem är thamner pol","thamner pols plats","var finns thamner pol"}},{q="Var äger utbildningen rum?",a="Utbildningen äger rum i Kharanos, den främsta bosättningen i centrala Dun Morogh, söder om Ironforge.",al={"vart ska jag gå","camping 101-plats","first aid i kharanos"}},{q="Varför är ett första hjälpen-kit för lägret viktigt?",a="Skador är vanliga under expeditioner i hård vildmark. Ett särskilt First Aid Kit ger äventyrare som vilar tillgång till viktiga läkande förnödenheter, så att resenärer kan förbinda sår och återhämta sig tryggt mellan striderna.",al={"vad gör ett first aid kit","varför tillverka ett first aid kit","nyttan med första hjälpen i lägret"}},{q="Behöver du tidigare medicinsk utbildning innan du söker upp Thamner Pol?",a="Ja. Äventyrare förväntas redan kunna grunderna i First Aid och visa grundläggande färdighet innan Thamner Pol lär dem avancerade campingrecept.",al={"krav för camping 101","krävs färdigheten first aid","behöver jag kunna first aid först"}},{q="Kan alla äventyrare ägna sig åt detta?",a="Alla äventyrare kan lära sig First Aid oavsett yrkesroll, vilket gör lägermedicin till en praktisk färdighet för alla som färdas genom Dun Morogh.",al={"kan vem som helst göra det här","klasskrav","vem kan lära sig första hjälpen i lägret"}}},fp="22,236,26.437.0,23.337.0,33.161.0,19.174.0,36.111.0,38.218.0,62.176.0,39.143.0"}
P.entries["quest:96050"] = {n="Camping 101: Fishing",s="Camping 101: Fishing lär friluftsmänniskor vildmarkens viktigaste färdigheter och hur man uppför sig där. Den visar äventyrare hur de kan skapa en dekorativ Fish Bowl till lägerplatsen och betonar att de måste lära sig göra upp lägereld hos en matlagningstränare innan de ger sig ut i vildmarken.",h="Camping 101: Fishing lär friluftsmänniskor vildmarkens viktigaste färdigheter och hur man uppför sig där.",kw={"läger","lägereld","camping","matlagning","fish bowl","fiske","vildmark"},ang={["profession:Cooking"]="Det är viktigt att lära sig grunderna i matlagning för att kunna slå läger, eftersom matlagningstränare lär resande att göra upp den nödvändiga lägerelden."},sec={{t="Vett i vildmarken",b="Livet på vägarna genom Azeroth kräver praktisk kunskap om utmarkerna. För blivande fiskare och vandrare kräver en välordnad lägerplats att man förstår grundläggande friluftsvett. Stadsbor och vakter ogillar när resande slår upp tält och sprider ut sin utrustning mitt i bebyggelsen. Den som vill vila måste därför ta med sig sina förnödenheter utanför stadsgränsen och ut i den öppna vildmarken."},{t="Lägrets bekvämligheter",b="En ordentlig expeditionsplats kräver flera viktiga bekvämligheter. Framför allt är en lägerplats inte komplett utan en varm lägereld, en färdighet som traditionellt lärs ut av matlagningsinstruktörer. När elden väl är tänd kan erfarna resenärer ställa fram särskilda tillbehör som en handgjord Fish Bowl och förvandla en enkel rastplats till en fullt utrustad fristad för fiskare."}},faq={{q="Vad lär du dig av Camping 101: Fishing?",a="Den här lektionen lär äventyrare att tillverka en Fish Bowl som pryder lägerplatsen. Den tar upp grunderna i att ordna en tillflyktsplats i vildmarken, lämpad för fiske och avkoppling långt från bebyggelsen.",al={"vad lär det här uppdraget ut","tillverka fish bowl","belöning från camping fishing"}},{q="Var kan du slå läger?",a="Du kan inte slå läger mitt i en stad, eftersom stadsborna ogillar när resande breder ut sig på allmänna gator. Du måste bege dig ut i vildmarken för att ordna din lägerplats.",al={"var slå läger","kan jag slå läger i en stad","regler för lägerplatser"}},{q="Vad behöver du innan du slår läger?",a="Inget läger i vildmarken är komplett utan en lägereld. Innan du börjar slå läger måste du ha en eld redo som lägerplatsens mittpunkt och värmekälla.",al={"hur börjar jag slå läger","behöver jag en lägereld","krav för att slå läger"}},{q="Hur lär du dig att göra upp en lägereld?",a="Matlagningsinstruktörer och matlagningstränare lär ut grunderna i att göra upp lägereld. Den som ännu inte har lärt sig grunderna i matlagning bör söka upp en kock och lära sig hur man gör.",al={"hur gör man upp lägereld","var lär man sig göra upp lägereld","vem lär ut att göra upp eld"}},{q="Vad är Fish Bowl till för?",a="Fish Bowl är en dekorativ detalj som tillverkas för en lägerplats utomhus och passar den resande fiskare som vill sätta upp ett utpostläger vid vattnet.",al={"vad används fish bowl till","användning av fish bowl vid läger","fish bowl i berättelsen"}},{q="Varför får äventyrare lära sig att slå läger?",a="Vildmarksmentorer ger praktiska råd om livet i utmarkerna så att vandrare vet hur de ska försörja sig, göra upp eld och respektera bebyggelsens gränser innan de ger sig ut i vildmarken.",al={"vem erbjuder camping 101","varför lära sig slå läger","överlevnadsguide för camping"}}},fp="20,289,20.399.0,20.374.0,44.210.0,28.186.0,40.164.0,37.187.0,37.170.0,46.200.0"}
P.entries["quest:96055"] = {n="Camping 101: Herbalism",s="Camping 101: Herbalism hänvisar lovande örtsamlare till Reyna Stonebranch i Ironforge för att utveckla sina praktiska färdigheter. Samlarna lär sig att kombinera vilda örter till rogivande Incense Candle för lägerlivet. Dessa väldoftande skapelser höjer humöret och hjälper besvärjare under krävande expeditioner i vildmarken.",h="Camping 101: Herbalism hänvisar lovande örtsamlare till Reyna Stonebranch i Ironforge för att utveckla sina...",kw={"läger","camping 101","örtsamling","örter","incense candle","ironforge","reyna stonebranch"},ang={["faction:Alliance"]="Alliansens örtsamlare hänvisas till dvärgstaden Ironforge för att söka upp Reyna Stonebranch och få lära sig specialiserade färdigheter för vildmarken.",["profession:Herbalism"]="Samlare som förfinar sitt kunnande om växter kan skapa Incense Candles och förvandla skördade vildmarksörter till väldoftande lägerhjälp åt besvärjande allierade.",["race:Dwarf"]="Kunskapen om att tillverka dessa växtbaserade lägerhjälpmedel finns i Ironforge hos örtsamlingsinstruktören Reyna Stonebranch."},sec={{t="Praktisk fältbotanik",b="Att samla örter i vildmarken handlar om mycket mer än att plocka blommor. Skickliga botaniker upptäcker att skördade växter kan användas för praktisk överlevnad utomhus och ge resesällskap värdefulla lägerföremål. För samlare som vill bredda sin nytta bortom grundläggande insamling av reagenser blir vilda växter viktiga stödföremål när de lär sig specialiserade tekniker för vildmarken."},{t="Dofter vid härden",b="Skickliga örtsamlare hänvisas till Reyna Stonebranch i bergsstaden Ironforge. När de har visat att de behärskar hantverket kan de lära sig att tillverka en Incense Candle. Dessa väldoftande ljus ger välkommen lindring på lägerplatser, höjer reskamraternas humör och skapar en rogivande miljö som besvärjare och helare särskilt uppskattar under långa expeditioner."}},faq={{q="Vad är Camping 101: Herbalism?",a="Camping 101: Herbalism är en instruktion som visar skickliga samlare hur de kan använda sina botaniska kunskaper för överlevnad utomhus och lägerliv i vildmarken.",al={"vad är camping 101 herbalism","örtsamlingsuppdrag för lägerliv","guide till örtsamling i läger"}},{q="Vem är Reyna Stonebranch?",a="Reyna Stonebranch är en örtsamlartränare i den stora dvärgstaden Ironforge som lär skickliga örtsamlare att tillverka lägerföremål.",al={"vem lär ut incense candle","var finns reyna stonebranch","reyna stonebranch plats"}},{q="Vad gör en Incense Candle?",a="En Incense Candle är ett väldoftande lägerföremål som örtsamlare tillverkar. Det höjer humöret vid lägret och ger en uppfriskande effekt som helare och besvärjare särskilt uppskattar.",al={"vad gör incense candle","incense candle för lägerliv","syftet med incense candle"}},{q="Varför är Incense Candles användbara för besvärjare?",a="Gott humör hjälper en att hålla ut, så den rogivande doften från en Incense Candle är särskilt värdefull för helare och magiker som återhämtar sig mellan resor.",al={"vem har nytta av incense candle","är incense candle till för besvärjare"}},{q="Vart måste örtsamlare resa för att få den här instruktionen?",a="Uppdraget skickar örtsamlare till Ironforge i Khaz Modan för att träffa Reyna Stonebranch när de har visat tillräcklig skicklighet i att samla örter.",al={"vart ska jag gå för camping herbalism","vilken stad för camping 101 herbalism"}},{q="Vad krävs innan man får lära sig att tillverka ljuset?",a="Örtsamlare måste visa tillräcklig skicklighet och praktisk förmåga att samla örter innan Reyna Stonebranch lär ut hur man tillverkar rökelse för lägret.",al={"när kan jag lära mig incense candle","krav för örtsamling i läger"}}},fp="22,311,22.393.0,24.411.0,31.172.0,25.157.0,31.173.0,47.166.0,50.158.0,53.161.0"}
P.entries["quest:96056"] = {n="Camping 101: Skinning",s="Camping 101: Skinning är ett introduktionsuppdrag som lär äventyrare konsten att tillverka vildmarksinredning av skinn från fällda djur. Det leder skickliga skinnare till Balthus Stoneflayer i Ironforge, där de får lära sig att tillverka en bekväm Camp Chair till lägerplatsen.",h="Camping 101: Skinning är ett introduktionsuppdrag som lär äventyrare konsten att tillverka vildmarksinredning...",kw={"balthus stoneflayer","camp chair","camping","camping 101: skinning","hudar","ironforge","skinning"},ang={["class:Hunter"]="Jägare som lever av vad landet ger och flår sina byten ute i vildmarken har nytta av att slå upp ett ordentligt läger där de kan vila mellan långa spårningar.",["faction:Alliance"]="Vägen till att tillverka den här fältsitsen leder rakt in i dvärgarnas bergsstad Ironforge, vilket gör Alliansens huvudstad till ett viktigt stopp för läderinsamlare.",["race:Dwarf"]="Balthus Stoneflayer bor i Ironforge och erbjuder skickliga skinnare dvärgarnas hemlighet bakom att förvandla råhudar till stadiga lägerbekvämligheter."},sec={{t="Att ta vara på vildmarken",b="Att flå fallna bestar är en av de mest praktiska färdigheter en äventyrare kan skaffa sig när hen färdas genom Azeroths vildmarker. Hudar från rovdjur som katter och björnar, liksom från andra bestar, ger inte bara råläder åt rustningsmakare och hantverkare, utan kan också användas direkt ute i fält. Den här introduktionsuppgiften lär skinnare att förvandla råmaterial till praktiska bekvämligheter i vildmarken i stället för att bara sälja dem."},{t="Hantverkaren i Ironforge",b="Uppdraget skickar skinnare till dvärgarnas huvudstad Ironforge för att söka upp Balthus Stoneflayer. Balthus känner till hemligheten bakom att förvandla beredda djurhudar till en användbar Camp Chair. Men först kräver han att en äventyrare visar tydliga färdigheter i att flå djur innan han går med på att lära ut sina hantverkstekniker."},{t="Vila och beredskap",b="Livet på vägarna tär hårt på både resenärer och jägare. En stadig Camp Chair ger äventyraren möjlighet att slå sig ner och koppla av vid elden, så att energin och sinnena återhämtar sig. En stunds vila gör att äventyraren är i toppform när nästa farliga sammanstötning börjar och kan slå till där det gör mest nytta."}},faq={{q="Vad är Camping 101: Skinning?",a="Camping 101: Skinning är ett instruktionsuppdrag som leder skickliga skinnare till specialiserad utbildning i lägerhantverk i Ironforge. Det lär äventyrare att förvandla djurhudar från fältet till en bekväm Camp Chair för det egna lägret.",al={"vad är camping 101 skinning","uppdragets syfte","uppdraget camping 101 skinning"}},{q="Vem lär dig att tillverka lägerföremålet?",a="Uppdraget leder dig till Balthus Stoneflayer, en mästerhantverkare som bor i bergsstaden Ironforge. När du har visat tillräckliga färdigheter i ditt insamlingsyrke lär han dig att tillverka särskilda bekvämligheter för lägret.",al={"vem ska man prata med","vem lär ut camp chair","vem är balthus stoneflayer"}},{q="Vart måste du bege dig för att slutföra uppdraget?",a="Du måste resa till Ironforge, dvärgarnas huvudstad bland de snöklädda topparna i Dun Morogh. Balthus Stoneflayer finns i staden, redo att undervisa skinnare som har rätt kvalifikationer.",al={"vart ska man bege sig","var finns balthus","tränare i ironforge"}},{q="Vilket föremål lär sig skinnare att tillverka till lägret?",a="Du lär dig att tillverka en Camp Chair av hudar från fällda djur. Med en bekväm stol kan äventyraren vila benen ute i fält, återfå fokus och hålla sig i toppform mellan farliga möten.",al={"vad tillverkar man","camp chairs syfte","lägerhantverk med skinning"}},{q="Varför är det användbart för en äventyrare att tillverka en lägerstol?",a="Att vila i en bekväm lägerstol ger ett välbehövligt andrum under långa färder genom vildmarken. En stunds avkoppling gör att äventyraren håller sig i toppform och kan slå till med precision när striden förr eller senare bryter ut.",al={"varför tillverka en stol","vad gör camp chair","fördel med camp chair"}},{q="Vilka färdigheter krävs innan Balthus undervisar dig?",a="Balthus Stoneflayer delar bara med sig av sina hantverkskunskaper när en äventyrare har bevisat sina färdigheter i skinning. Du måste visa att du är skicklig på att flå bestar innan han lär dig mönstret.",al={"krav","när kan jag lära mig","krävda färdigheter"}}},fp="21,281,20.424.0,24.346.0,18.363.0,30.262.0,42.252.0,47.179.0,52.240.0,54.240.0,59.219.0"}
P.entries["quest:96101"] = {n="The Great Outdoors",s="The Great Outdoors är ett introduktionsuppdrag som erbjuds av vildmarksvandraren Raan, som lär nybörjaräventyrare grunderna i att överleva i vildmarken. Genom att vila vid en enkel lägereld för att få Boosted Rest lär sig vandrare viktiga lägerkunskaper innan de beger sig till närliggande hantverkstränare för att lära sig praktiska yrken.",h="The Great Outdoors är ett introduktionsuppdrag som erbjuds av vildmarksvandraren Raan, som lär...",kw={"enkel lägereld","boosted rest","lägerutrustning","lägereld","raan","the great outdoors","hantverksyrke","överlevnad i vildmarken"},ang={["class:Hunter"]="Överlevnad i vildmarken börjar med grunderna i lägerkunskap, en viktig färdighet för spårare och skogsvaktare som är vana vid att leva under bar himmel.",["profession:Cooking"]="Att samlas kring en enkel lägereld för att vila och återhämta sig är självklart för lägerkockar, som använder öppna lågor för att hålla resesällskap vid liv ute i vildmarken."},sec={{t="Lärdomar i vildmarken",b="The Great Outdoors är en introduktion till att överleva bortom bosättningarnas trygga murar. Uppdraget erbjuds av den erfarna vildmarksresenären Raan och påminner kringvandrande äventyrare om att rå ambition och stål är värdelösa utan de praktiska lägerkunskaper som krävs för att uthärda hårda förhållanden. Raan välkomnar blivande vandrare till skaran av rastlösa själar som söker rikedom och ära och erbjuder praktiska råd till dem som vill lära sig."},{t="Eldens värme",b="Grundkravet för lektionen är bedrägligt enkelt: slå dig ner vid Raans enkla lägereld tills värmen ger dig effekten Boosted Rest. I Azeroths vidsträckta, otämjda trakter kan kunskapen om att stanna upp, slå läger och återhämta sig vara skillnaden mellan liv och död. När du har lärt dig grunderna i att slå läger hänvisar Raan nybörjare till tränare i byn, där de kan lära sig ett hantverk och tillverka särskild lägerutrustning."}},faq={{q="Vem ger uppdraget The Great Outdoors?",a="Uppdraget erbjuds av Raan, en erfaren resenär som ser potential hos kringvandrande äventyrare och lär dem grunderna i att överleva ute i vildmarken.",al={"vem erbjuder the great outdoors","uppdragsgivare the great outdoors","raans lägereldsuppdrag"}},{q="Vad är syftet med The Great Outdoors?",a="Uppdraget introducerar äventyrare till grunderna i att överleva i vildmarken och visar hur vila vid en enkel lägereld ger värme, återhämtning och den stärkta vila som behövs innan farliga resor.",al={"vad lär the great outdoors ut","syftet med the great outdoors","vad lär jag mig av raan"}},{q="Hur slutför man uppdraget?",a="Slutför lektionen genom att slå dig ner vid Raans enkla lägereld och vila där tills du får förstärkningen Boosted Rest. Då visar du att du förstår hur du återhämtar dig ute i fält.",al={"hur slutför man the great outdoors","raans lägereldsmål","målet med boosted rest"}},{q="Vad föreslår Raan att man gör efter att ha slutfört uppdraget?",a="När lägereldslektionen är klar uppmuntrar Raan dig att besöka tränarna i den närliggande byn för att lära dig ett hantverksyrke. Hantverkare kan skapa lägerutrustning som är anpassad efter deras hantverk.",al={"vad råder raan mig att göra sedan","vart ska jag gå efter the great outdoors","efter att ha slutfört the great outdoors"}},{q="Vad är Boosted Rest?",a="Boosted Rest är den återhämtande effekt du får när du vilar vid en iordningställd lägereld. Den ger resande äventyrare bättre återhämtning medan de trotsar väder och vind.",al={"vad är boosted rest","boosted rest-förstärkning vid lägereld"}},{q="Kan hantverksyrken låta äventyrare tillverka lägerutrustning?",a="Ja, lokala hantverkstränare kan lära hantverkare att tillverka praktisk lägerutrustning som passar deras valda hantverk, så att resenärer kan hålla igång specialanpassade läger ute i det fria.",al={"kan yrken skapa lägereldar","lägerutrustning från hantverksyrken","lägerföremål från hantverk"}}},fp="18,319,19.453.0,24.453.0,39.174.0,42.211.0,27.175.0,56.190.0,21.174.0,60.193.0"}
P.entries["quest:96130"] = {n="Chakuyak",s="Chakuyak är en ovanligt aggressiv prärievarg som stryker bland träddungarna väster om Stonebull Lake i Mulgore. Hon utgör ett allt större hot mot förbipasserande resenärer och har därför utsetts till villebråd av de lokala stammarna, som vill trygga området och hedra det fallna rovdjuret genom att ta vara på skinnet.",h="Chakuyak är en ovanligt aggressiv prärievarg som stryker bland träddungarna väster om Stonebull Lake i...",kw={"chakuyak","mulgore","prärievarg","stonebull lake","taurenjakt","resenärer","vargskinn"},ang={["class:Hunter"]="Att spåra en ovanligt vild, ensam alfavarg genom skogklädda kullar kräver tålamod, skarpa sinnen och respekt för vilda rovdjur.",["race:Tauren"]="Jakten speglar taurenfolkets syn på att balansera vördnad för naturens varelser med plikten att skydda stammen och hedra fällda djur genom att ta vara på deras skinn."},sec={{t="Skuggan över Stonebull Lake",b="Bland prärievargarna som strövar över Mulgore gräsklädda platåer och böljande kullar har den ovanligt vilda alfahonan Chakuyak utmärkt sig genom sin skoningslösa aggressivitet. Hon stryker bland träddungarna väster om Stonebull Lake och har gått från att vara vanligt villebråd till att utgöra en direkt fara för resenärer från andra trakter. Därför har lokala jägare beslutat att röja henne ur vägen innan oskyldiga vandrare skadas."},{t="Vördnad och nödvändighet",b="För de lokala stammarna möts dödandet av ett storslaget rovdjur som Chakuyak med allvarsam vördnad, inte skrytsam grymhet. Att fälla henne ses som nödvändigt för att skydda både resenärer och bybor. Enligt nomadernas seder tas hennes tjocka skinn med tillbaka, bereds omsorgsfullt och används så att den mäktiga vargens ande och offer hedras och inget går till spillo."}},faq={{q="Vem eller vad är Chakuyak?",a="Chakuyak är en ovanligt aggressiv och stor prärievarg som stryker på kullarna nära Stonebull Lake i Mulgore. Hon har fått ett eget namn på grund av hotet hon utgör mot resenärer som färdas genom området.",al={"vad är chakuyak","vem är chakuyak","är chakuyak en varg"}},{q="Var finns Chakuyak?",a="Chakuyak stryker genom den skogklädda terrängen väster om Stonebull Lake och rör sig ljudlöst mellan träddungarna på kullarna.",al={"var hittar man chakuyak","chakuyaks plats","var strövar chakuyak"}},{q="Varför måste Chakuyak jagas?",a="Lokala prärievargar är en naturlig del av Mulgore djurliv, men Chakuyak har blivit ovanligt djärv och aggressiv. Hon hotar direkt resenärer som kommer in i området från andra trakter.",al={"varför döda chakuyak","chakuyaks hot"}},{q="Vad händer med Chakuyaks skinn efter jakten?",a="Uppdragsgivaren ser till att livet på ett så storslaget rovdjur inte tas förgäves. Hennes skinn bevaras och används väl, så att inget går till spillo.",al={"vad händer med chakuyaks skinn","chakuyaks päls"}},{q="Behöver jag en grupp för att jaga Chakuyak?",a="Chakuyak är ovanligt vild och farlig jämfört med vanliga vargar. Resenärer slår sig ofta samman i små jaktlag för att spåra upp och fälla henne på ett säkert sätt.",al={"bör jag bilda grupp för chakuyak","är chakuyak svår att besegra ensam"}},{q="Vem erkänner din seger över Chakuyak?",a="Jägaren som ger dig uppdraget lovar att tala väl om din bedrift inför stammens hövding när besten har fällts och hennes skinn återlämnats.",al={"vem belönar jakten på chakuyak","chakuyak hövding"}}},fp="8,280,28.419.0,23.408.0,24.208.0,26.125.0,33.182.0,47.156.0,35.170.0,44.157.0"}
P.entries["quest:962"] = {n="Serpentbloom",s="Serpentbloom är ett insamlingsuppdrag från Apothecary Zamah, ett sändebud för Royal Apothecary Society som bor i Thunder Bluff. Zamah söker exemplar av en sällsynt ört från Wailing Caverns underjordiska djup för att hjälpa Forsakens forskning.",h="Serpentbloom är ett insamlingsuppdrag från Apothecary Zamah, ett sändebud för Royal Apothecary Society som...",kw={"apotekare","barrens","royal apothecary society","serpentbloom","spirit rise","thunder bluff","undercity","wailing caverns","zamah"},ang={["faction:Horde"]="Det här uppdraget befäster den tidiga operativa alliansen mellan Undercity och Kalimdors stammar, som delar resurser och sällsynta reagenser över havet.",["profession:Herbalism"]="Den förvridna miljön i Wailing Caverns ger upphov till en unik flora som inte finns någon annanstans på Barrens solstekta yta.",["race:Tauren"]="Att hysa Forsakens apotekare under Spirit Rise visar på Hordens gästfrihet, även om deras fokus på dödliga brygder står i kontrast till traditionell läkekonst som bygger på jorden.",["race:Undead"]="Att bidra med Serpentbloom stöder direkt Royal Apothecary Societys alkemiska initiativ i Lordaeron på den Mörka damens uppdrag."},sec={{t="Apothecarys ögon",b="Apothecary Zamah är stationerad i Pools of Vision under Spirit Rise i Thunder Bluff och tjänstgör som sändebud för Royal Apothecary Society från Undercity. Medan taurenfolket fokuserar på andlig balans och på att läka det sårade landet riktar Zamah sin uppmärksamhet mot sällsynta och virulenta ämnen. Hon har isolerat ett prov av en ovanlig växt som kallas Serpentbloom och söker stora mängder för att främja Lady Sylvanas Windrunners och Forsakens forskningsmål."},{t="Grottornas djup",b="Serpentbloom växer inte i Barrens öppna solsken, utan trivs i Wailing Caverns fuktiga, vindlande grottor. Växten odlas i det fuktiga underjordiska klimatet, som förvridits av Fangens korrumperade druider. Den är svår att nå och vaktas hårt av grottans ormlika invånare. Zamah erkänner utan omsvep att många spejare som skickats dit tidigare aldrig återvände, så nu får härdade äventyrare sköta den fortsatta insamlingen."}},faq={{q="Vem är Apothecary Zamah?",a="Apothecary Zamah är en forskare som företräder Royal Apothecary Society i Undercity. Hon är stationerad i Pools of Vision under Thunder Bluffs Spirit Rise och fungerar som förbindelselänk mellan Forsakens alkemister och resten av kontinenten Kalimdor.",al={"zamah","apothecary zamahs bakgrund","vem ger serpentbloom"}},{q="Varför vill Royal Apothecary Society ha Serpentbloom?",a="Zamah tror att örten har en betydande outnyttjad kemisk potential när den förädlas i stora mängder. Society söker aktivt över hela Kalimdor efter sällsynta, kraftfulla växter som kan bidra till Forsakens alkemiska experiment.",al={"varför serpentbloom","forsakens örtstudier","serpentblooms syfte"}},{q="Var växer Serpentbloom?",a="Serpentbloom växer enbart i Wailing Caverns underjordiska områden, bland fuktiga klippgångar och underjordiska passager som löper under norra Barrens.",al={"var finns serpentbloom","serpentblooms plats"}},{q="Varför har tidigare spejare inte återvänt?",a="Wailing Caverns kryllar av förvildade bestar, rovfåglar och de korrumperade Druids of the Fang. Mindre erfarna växtsamlare som skickats in i de labyrintiska gångarna blev snabbt övermannade av grottans rovdjur och giftiga försvarare.",al={"försvunna spejare","zamahs spejare","är wailing caverns farligt"}},{q="Godkänner tauren Zamahs forskning?",a="Taurenfolket i Thunder Bluff gav Forsaken en fristad av medkänsla och en önskan att hjälpa dem att läka, men Royal Apothecary Societys alkemiska metoder tangerar ofta onaturliga experiment som gör traditionella schamaner och druider obekväma.",al={"taurens reaktion","apotekare vid spirit rise"}},{q="Kräver insamling av Serpentbloom kunskaper i örtmedicin?",a="Nej. Även om det är ett botaniskt exemplar kan alla äventyrare som vågar sig ner i Wailing Caverns plocka växterna direkt från grottgolvet utan formell utbildning i örtmedicin.",al={"behöver jag örtmedicin","samla serpentbloom med yrke"}}},fx={["962715c8"]={q="Varför vill Apothecary Zamah att Serpentbloom samlas in?",a="Apothecary Zamah skickades till Thunder Bluff av Royal Apothecary Society med ett särskilt uppdrag att främja Forsakens och den Mörka Damen, Lady Sylvanas Windrunner, intressen. Efter att ha analyserat ett sällsynt prov av Serpentbloom ser Zamah stor potential i dess egenskaper om hon kan få tag på stora mängder. Genom att säkra tillräckligt många exemplar kan hon driva sin forskning framåt och främja Undercitys vetenskapliga och alkemiska ambitioner.",al={"apothecary zamahs motiv","varför behöver zamah serpentbloom","varför samla serpentbloom"}},["92b49307"]={q="Varför skickar Apothecary Zamah en äventyrare i stället för att själv samla Serpentbloom?",a="Zamah kan inte lätt lämna sin post i Thunder Bluff, och för att skörda örten måste man ta sig in i de förrädiska, fördärvade djupen av Wailing Caverns. Hon har redan skickat flera spejare och agenter in i grottsystemet åt sig, men ingen av dem återvände levande. Hon behöver erfarna och skickliga äventyrare som vågar sig in i de mörka djup där vanliga spejare misslyckades.",al={"varför skickas jag efter serpentbloom","varför hämtar inte zamah serpentbloom","varför äventyrare till serpentbloom"}}},fp="12,259,22.476.0,25.436.0,24.253.0,56.226.0,29.188.0,37.240.0,42.259.0,54.188.0"}
P.entries["quest:96243"] = {n="Call of Earth",s="Call of Earth är en inledande kallelse som manar en lärling att stämma sig med stenens andar. Färden går till Coldridge Valley, där resenären ska söka upp Teo Hammerstorm i dvärgarnas fäste Anvilmar.",h="Call of Earth är en inledande kallelse som manar en lärling att stämma sig med stenens andar.",kw={"anvilmar","call of earth","coldridge valley","dun morogh","earth totem","elementen","schaman","teo hammerstorm"},ang={["class:Shaman"]="Att hörsamma jordens kallelse är ett grundläggande steg på schamanens väg. Det knyter lärlingen till landets djupa sten och ståndaktiga andar.",["faction:Alliance"]="Alliansens schamaner i Dun Morogh inleder sin elementära resa i dvärgarnas förfäders fäste Anvilmar.",["race:Dwarf"]="Dvärgar har ett medfött band till sten och jord, så samvaron med dessa jordandar känns naturlig i Dun Moroghs djupa valv."},sec={{t="Stenens röst",b="För en lärling som vandrar elementens väg är jordens kallelse den första viktiga samvaron. Även om elementarkrafter redan kan röra sig under huden skapar förmågan att tala direkt med stenen en stadig balans. Den lär anden att finna orubblig styrka och ger fast mark under både stövlarna och själen."},{t="Anvilmars fäste",b="Lärlingar i Dun Moroghs snöklädda vidder hänvisas till skyddet i Anvilmar, ett mäktigt fäste smitt av hammare, eld och vilja. I denna vördnadsvärda skans i Coldridge Valley väntar Teo Hammerstorm, som lär upp unga schamaner i att lyssna till den mullrande jorden och inleda sina elementära plikter."}},faq={{q="Vad är Call of Earth?",a="Call of Earth är en inledande kallelse som vägleder en blivande schaman till att inleda samvaron med jordandarna. Den instruerar lärlingen att söka vägledning och finna stadga i den levande stenens kraft.",al={"vad är call of earth","uppdraget call of earth","vad är det här för uppdrag"}},{q="Vem är Teo Hammerstorm?",a="Teo Hammerstorm är en mentor i dvärgarnas fäste Anvilmar i Coldridge Valley. Han vägleder lärlingar i att samverka med jorden och förstå dess stadiga styrka.",al={"vem är teo hammerstorm","var finns teo hammerstorm","teo hammerstorms plats"}},{q="Vad är Anvilmar?",a="Anvilmar är ett stadigt fäste smitt av hammare, eld och vilja, beläget i Coldridge Valleys snöiga vidder i Dun Morogh. Det fungerar som en central skans och övningsplats för unga hjältar.",al={"var ligger anvilmar","vad är anvilmar","anvilmars plats"}},{q="Varför måste en schaman lyssna till jordens kallelse?",a="Genom att samverka med jorden kan en schaman finna stadga i sin andliga essens och få fast mark under både fötterna och själen, så att hen kan kanalisera stenens stadiga kraft.",al={"varför tala med jorden","syftet med call of earth","schamanens band till jorden"}},{q="Vem antar denna kallelse?",a="Uppdraget riktar sig till schamaner som börjar sin bana i Dun Morogh och leder dem till erfarna elementarlärare som kan vägleda dem i kontakten med andarna.",al={"vem utfärdar call of earth","vem antar call of earth","vem gör det här uppdraget"}},{q="Vart leder uppdraget?",a="Färden går till Anvilmar, beläget i Coldridge Valley i det snöiga Dun Morogh. Lärlingarna måste ta sig in i fästet för att hitta sin mentor.",al={"var utspelar sig call of earth","call of earths zon","vart ska man gå"}}},fp="13,215,18.352.0,24.313.0,22.211.0,23.185.0,17.201.0,41.190.0,28.173.0,27.161.0"}
P.entries["quest:963"] = {n="For Love Eternal",s="\"For Love Eternal\" är ett tragiskt uppdrag som Cerellean Whiteclaw ger i Auberdine. Plågad av minnena av sin förlorade älskade, Anaya Dawnrunner, ber Cerellean en äventyrare resa till de krossade ruinerna av Ameth'Aran och befria hennes rastlösa ande från en evighet av plågor.",h="\"For Love Eternal\" är ett tragiskt uppdrag som Cerellean Whiteclaw ger i Auberdine.",kw={"ameth'aran","anaya dawnrunner","anaya's pendant","auberdine","cerellean whiteclaw","darkshore","for love eternal","sundering"},ang={["class:Druid"]="Cerelleans öde speglar det personliga pris som druidernas långa dvala vid Shan'do Stormrages sida innebar. De vaknade först efter tusentals år och fann att den vakna världen fortfarande bar spår av deras uråldriga förluster.",["faction:Alliance"]="När du hjälper Cerellean får Alliansens hjältar en inblick i sina Night Elf-allierades tragiska liv genom årtusendena, medan de anpassar sig till den vakna världen.",["race:NightElf"]="För Darkshores Night Elves är det en gripande påminnelse om de bestående ärr som Great Sundering och deras uråldriga städers fall lämnade efter sig att hjälpa Cerellean."},sec={{t="En sömn fylld av sorg",b="För tiotusen år sedan, under War of the Ancients, slet katastrofen kring Well of Eternity uråldriga Kalimdor i stycken. Bland offren fanns staden Ameth'Aran, där Cerellean Whiteclaw förlorade sin älskade Anaya Dawnrunner. Förkrossad av sorg följde Cerellean Shan'do Malfurion Stormrage in i druidernas långa dvala, i hopp om att årtusendena i The Emerald Dream skulle stilla hans värkande hjärta. I stället dröjde sorgen kvar och följde honom genom tiderna."},{t="Ameth'Arans vålnad",b="När Cerellean vaknade i vår tid vandrade han i dvala genom Darkshore tills han åter kom till Ameth'Arans sorgsna ruiner. Där såg han Anayas plågade vålnad bland de uråldriga stenarna. Han stod inte ut med att höja ett vapen mot kvinnan han älskade och vädjar därför till resenärer att förgöra hennes plågade skepnad, hämta hennes hängsmycke och äntligen ge hennes oroliga själ ro."},{t="Farväl på andra sidan slöjan",b="När Anayas hängsmycke återlämnas till Auberdine visar sig en spektral rest av Anaya inför Cerellean en sista gång. Fri från den kvarvarande vånda som band henne till ruinerna tar hon farväl en kort stund, innan hon tonar bort i tomrummet och lämnar den sörjande druiden att gråta i bitterljuv tröst vid havet."}},faq={{q="Vem är Cerellean Whiteclaw?",a="Cerellean Whiteclaw är en Night Elf-druid som vilar i Auberdine. Efter att ha förlorat sin älskade Anaya under Sundering för tiotusen år sedan gick han i lång druidisk dvala tillsammans med Shan'do Malfurion Stormrage och bar sin oläkta sorg genom årtusendena.",al={"cerellean whiteclaw","vem ger uppdraget for love eternal","cerelleans historia"}},{q="Vem var Anaya Dawnrunner?",a="Anaya Dawnrunner var en Night Elf som levde i staden Ameth'Aran före Great Sundering. Hon dödades när staden föll i efterdyningarna av War of the Ancients, och hennes vålnad har varit fången i ruinerna sedan dess.",al={"anaya dawnrunner","vem är anaya","anaya darkshore"}},{q="Var finns Anayas ande?",a="Hennes ande vandrar bland de uråldriga, vålnadshemsökta ruinerna av Ameth'Aran, i södra Darkshore öster om huvudvägen.",al={"anayas plats","var finns anaya dawnrunner","var finns anayas hängsmycke"}},{q="Varför kunde Cerellean inte befria Anaya själv?",a="Trots att tiotusen år hade gått var Cerelleans kärlek till Anaya så djup att han inte stod ut med att själv lyfta handen eller kasta en besvärjelse mot hennes uppenbarelse, inte ens för att få slut på hennes lidande.",al={"varför dödar inte cerellean anaya","varför ber cerellean om hjälp"}},{q="Vad hände med Ameth'Aran?",a="Ameth'Aran var en uråldrig Night Elf-bosättning som förstördes för tiotusen år sedan under Sundering, som följde på War of the Ancients. Ruinerna i Darkshore är fortfarande fulla av kvarvarande vålnader och magiska ekon.",al={"ameth'arans historia","ameth'arans fall","vad är ameth'aran"}},{q="Vad händer när du lämnar tillbaka Anayas hängsmycke?",a="Lämna Anayas hängsmycke till Cerellean i Auberdine efter att ha befriat hennes oroliga ande. Du får veta vad som händer när du återvänder.",al={"lämna in uppdraget anaya","cerelleans slut","slutet på for love eternal"}}},fx={dc23d6a3={q="Varför vill Cerellean Whiteclaw att Anayas ande ska befrias?",a="Cerellean trodde att hans älskade Anaya hade gått under för årtusenden sedan, när Ameth'Aran krossades under Sundringen. När han upptäckte hennes rastlösa, plågade vålnad vandra bland ruinerna brast hans hjärta. Han vet att hon lider, bunden till denna värld, och står inte ut med tanken på att hon ska fortsätta plågas. Samtidigt klarar han inte av att själv lyfta handen mot henne.",al={"varför vill cerellean att detta görs","cerelleans motiv","varför befria anayas ande"}},ed60ea9d={q="Vad ska Anaya's Pendant användas till?",a="Anaya's Pendant är minnessaken som Cerellean ber dig hämta efter att du befriat hennes plågade ande i Ameth'Aran.",al={"anaya's pendant användning","vad gör anaya's pendant","syftet med anaya's pendant"}}},fp="16,149,23.413.0,23.332.0,23.269.1,27.234.0,25.187.0,32.116.0,42.162.0,28.181.0,45.128.1"}
P.entries["quest:96339"] = {n="Legacy Reward: Replica Ironforge Air Rifle",s="Legacy Reward: Replica Ironforge Air Rifle markerar att du hämtar ett mystiskt paket som förvarats åt dig. En okänd budbärare lämnade det, och det var nära att kastas i havet innan det nådde dig.",h="Legacy Reward: Replica Ironforge Air Rifle markerar att du hämtar ett mystiskt paket som förvarats åt dig.",kw={"luftgevär","ironforge","luftgevär från ironforge","legacy-belöning","mystiskt paket","replica ironforge air rifle"},ang={["profession:Engineering"]="Mekare och vapensmeder uppskattar säkert att få en detaljrik modell av ett skjutvapen, även om den kom med en likgiltig kurir och nästan hamnade på havets botten.",["race:Dwarf"]="Paketet innehåller en replika av ett luftgevär från Ironforge, en minnesgåva till de berömda vapnen och det mekaniska hantverket i Khaz Modan."},sec={{t="Ett paket att hämta",b="Ett mystiskt paket adresserat särskilt till dig lämnades hos en motvillig förvarare. Den okända kuriren insisterade på att du skulle komma och hämta det, och skyndade sig därifrån så snabbt att mottagaren inte ens hann vägra ta emot det. Som tur var kom du precis innan den oavhämtade lådan skulle kastas i havet tillsammans med kvällens sopor."},{t="Dvärgteknik i miniatyr",b="I det levererade paketet finns en Replica Ironforge Air Rifle, en souvenir som hyllar den berömda vapentraditionen i dvärgarnas huvudstad. Dvärgarnas bergsvandrare och skarpskyttar bär dödlig eldkraft genom Dun Morogh, medan repliker som denna hyllar det intrikata piparbetet och de pneumatiska mekanismer som fulländats av hantverkare i Ironforge."}},faq={{q="Vem skickade paketet?",a="Kuriren eller den ursprungliga avsändaren lämnade varken namn eller förklaring. Enligt mottagaren som håller i det lämnade någon helt enkelt paketet, adresserat särskilt till dig, insisterade på att du förr eller senare skulle komma och hämta det och försvann innan några frågor kunde ställas.",al={"vem skickade paketet","avsändare av luftgevär","vem lämnade geväret"}},{q="Vad var nära att hända med paketet?",a="Om du inte hade kommit i tid skulle paketet ha kastats i havet tillsammans med nattens sopor. Förvararen erkände att de inte erbjuder förvaring och regelmässigt gör sig av med oönskat skräp i havet.",al={"vad skulle hända med paketet","sopor i havet","paket som kastas bort"}},{q="Vad finns i paketet?",a="Paketet innehåller en Replica Ironforge Air Rifle, överlämnad som ett arvegods särskilt avsett för dig. Den är ett minnesföremål som representerar dvärgarnas vapendesign.",al={"vad finns i paketet","innehåll i replika gevär","paketbelöning"}},{q="Varför höll förvararen i paketet?",a="Förvararen klargjorde att de inte erbjuder postförvaring eller lagring. Paketet blev kvar endast för att den mystiska kuriren skyndade sig därifrån så snabbt att det inte fanns någon möjlighet att vägra ta emot det innan kuriren försvann.",al={"varför förvarade de det","förvaring av post","förvarar den här platsen paket"}},{q="Varför räknas detta som en legacy-belöning?",a="Legacy-belöningar i WoW Forever är särskilda erkännanden och paket som mystiska välgörare lämnar åt erfarna äventyrare. De väntar vid utvalda utposter tills du kommer för att hämta dem.",al={"varför kallas det legacy-belöning","lore om legacy-belöning","vad betyder legacy här"}},{q="Är replikkarbinen ett fungerande vapen?",a="Den beskrivs uttryckligen som en replika av ett luftgevär från Ironforge, tillverkad efter de fint konstruerade dvärgarnas distansvapen snarare än som ett frontlinjevapen.",al={"är geväret ett riktigt vapen","går det att skjuta med","replikans funktion"}}},fp="42,239,29.337.0,32.333.0,22.273.0,36.226.0,26.178.0,42.224.0,39.202.0,41.169.0"}
P.entries["quest:96390"] = {n="Nip 'Em in the Bud",s="Nip 'Em in the Bud är ett uppdrag från Earthseer Farsen där du ska eliminera Dark Iron-spioner som tagit sig in i Dun Morogh. De hemliga agenterna har setts smyga omkring nära Ironband's Compound och hotar säkerheten i Bronzebeardernas hemland.",h="Nip 'Em in the Bud är ett uppdrag från Earthseer Farsen där du ska eliminera Dark Iron-spioner som tagit sig...",kw={"dark iron map","dark iron-spion","dun morogh","earthseer farsen","the hall of thanes","ironband's compound","nip 'em in the bud","underground map"},ang={["faction:Alliance"]="Genom att oskadliggöra fiendens spejare i Dun Morogh skyddar du Ironforges viktiga försörjningsleder och de omgivande utposterna från sabotage.",["race:Dwarf"]="För Bronzebeard-dvärgarna handlar det om att försvara hemmet och utkräva den gamla klanhämnden när de rensar sina förfäders berg från Dark Iron-infiltratörer."},sec={{t="Ögon i kylan",b="Dun Morogh har länge varit en befäst fristad för dvärgarna i Ironforge, men den urgamla fiendskapen mellan dvärgklanerna sover aldrig riktigt. Dark Iron-infiltratörer har tagit sig genom de höga passen och snöiga bergskammarna och smyger misstänkt nära viktiga utgrävningar och bosättningar. Earthseer Farsen inser att även några få dolda observatörer kan förebåda ett förödande anfall, och kallar på Alliansens ståndaktiga försvarare för att spåra upp dem innan deras planer sätts i verket."},{t="Hotet nära Ironband's Compound",b="Spionerna har samlats kring Ironband's Compound, en viktig plats i östra Dun Morogh. Farsen kan till en början inte avgöra deras exakta motiv, men när de hemliga agenterna oskadliggörs får du fysiska bevis på deras större plan. En sökning bland de besegrade spejarna avslöjar en Underground Map, som bekräftar att de inte bara är ute på ett spaningsuppdrag, utan förbereder något kopplat till urgamla underjordiska hemligheter som The Hall of Thanes."}},faq={{q="Vem erbjuder uppdraget Nip 'Em in the Bud?",a="Uppdraget erbjuds av Earthseer Farsen efter uppdraget Farsen's Watch och ber om hjälp med att hantera inkräktare i Dun Morogh.",al={"uppdragsgivare nip em in the bud","vem startar nip em in the bud","farsens uppdrag"}},{q="Varför finns Dark Iron-spioner i Dun Morogh?",a="Dark Iron-klanen smider ständigt planer mot sina kusiner bland Bronzebeard-dvärgarna. Genom att infiltrera östra Dun Morogh kan deras agenter hålla bosättningarna under uppsikt och gräva eller spana efter begravda underjordiska gångar nära Ironband's Compound.",al={"varför dark iron-spioner här","vad gör dark iron i dun morogh","ironband dark iron-spioner"}},{q="Var finns Dark Iron-spionerna?",a="De har samlats i öster, nära Ironband's Compound i östra Dun Morogh, där de håller vakt från den snötäckta utkanten.",al={"spionernas plats","var finns dark iron-spionerna","var hittar man spioner"}},{q="Vad leder fram till det här uppdraget?",a="Uppdraget följer efter att du rapporterat in för Farsen's Watch och trappat upp försvaret från enkel bevakning till aktiv utrensning.",al={"förkunskapsuppdrag","vad kommer före nip em in the bud","förhandsuppdrag till nip em in the bud"}},{q="Vad hittar man när man jagar spionerna?",a="Dödade spioner lämnar efter sig en Dark Iron Map, som inleder uppdraget Underground Map och pekar mot djupare hemligheter kopplade till The Hall of Thanes.",al={"vad får man från spionerna","dark iron map byte","nästa uppdrag efter nip em in the bud"}},{q="Vem är Earthseer Farsen?",a="Earthseer Farsen är en uppmärksam dvärg stationerad i Dun Morogh, som håller koll på ovanliga seismiska rörelser och fientliga klaners aktiviteter i de snöiga bergen.",al={"vem är farsen","earthseer farsens bakgrund"}}},fx={bdd12e65={q="Varför vill Earthseer Farsen att Dark Iron-spionerna oskadliggörs?",a="Earthseer Farsen vet att varje Dark Iron-fäste i Dun Morogh innebär fara för Ironforge och de omgivande områdena. Han känner inte till deras exakta motiv, men om infiltratörerna får verka ostört riskerar det att leda till större sabotage eller ett öppet angrepp. Han vill krossa deras närvaro omedelbart, innan deras planer hinner ta form.",al={"varför vill farsen döda spionerna","earthseer farsens motiv","varför nip 'em in the bud"}}},fp="18,247,16.475.0,31.452.1,40.132.0,38.228.0,38.121.0,26.137.0,44.134.1,24.146.0"}
P.entries["quest:96391"] = {n="Underground Map",s="Underground Map återfanns hos spioner som infiltrerat området nära Ironband's Compound och avslöjar hemliga tunnelgångar som gräver sig mot Ironforges grundvalar. De kantiga Dark Iron-runorna visar en dold väg under jord, rakt mot uråldriga salar under berget. När kartan lämnas till Earthseer Farsen börjar avslöjandet av ett förestående angrepp underifrån.",h="Underground Map återfanns hos spioner som infiltrerat området nära Ironband's Compound och avslöjar hemliga...",kw={"dark iron map","dun morogh","earthseer farsen","the hall of thanes","ironband's compound","ironforge","underground map"},ang={["class:Shaman"]="Den lätta vindpust som leder dig till Earthseer Farsen antyder att elementandar varnar för onaturliga utgrävningar under jord i Dun Morogh.",["faction:Alliance"]="Att oskadliggöra denna infiltrationsväg under jord är avgörande för att bevara Ironforges säkerhet och Alliansens nordliga fäste.",["race:Dwarf"]="För Bronzebeard-dvärgarna är upptäckten av Dark Iron-tunnlar som går rakt mot Ironforges grundvalar ett allvarligt intrång i huvudstadens territoriella integritet."},sec={{t="En infiltrationsritning",b="Pergamentet som återfanns hos Dark Iron-spioner nära Ironband's Compound visar en invecklad labyrint av underjordiska vägar. Diagrammen är ristade med hårda, kantiga runor som är unika för Dark Iron-klanen och visar djupa gångar under jord som möts rakt under Ironforge. Gångarna tyder på ett möjligt hot under Bronzebeard-huvudstaden, men kartans Dark Iron-anteckningar är fortfarande svårtolkade."},{t="Viskningar i vinden",b="När du studerar den grova kartan bär en onaturlig vindpust med sig det svaga sorlet av en dvärgröst som manar till snabb handling. Den mystiska uppmaningen pekar rakt mot Earthseer Farsen. Om du rapporterar upplysningarna avslöjas tidiga rörelser mot de uråldriga salar som förseglats djupt under staden, vilket hotar bergarikets fristad."}},faq={{q="Var kommer den här underjordiska kartan ifrån?",a="Dark Iron-spioner bär på kartan när de spanar av området kring Ironband's Compound i Dun Morogh. Du kan hitta den när du tar hand om deras spejare i bergssluttningarna.",al={"kartsläpp","var hittar man kartan","hur får man underground map"}},{q="Vad visar kartan?",a="Den visar ett komplext nätverk av underjordiska vägar och tunnlar som slingrar sig genom marken och alla möts rakt under staden Ironforge.",al={"vad finns på kartan","kartdetaljer","syftet med dark iron map"}},{q="Vem är Earthseer Farsen?",a="Earthseer Farsen är en dvärg från Aerie Peak med förmåga att skåda i jorden, i samklang med bergets djupa klippor och andar. Han känner av de onaturliga rörelserna under jord och behöver kartan för att bedöma genombrottet under Ironforge.",al={"var finns farsen","vem är farsen","jordskådare"}},{q="Varför gräver Dark Iron tunnlar under Ironforge?",a="Kartan antyder en möjlig väg under Ironforge, men dess Dark Iron-anteckningar har inte dechiffrerats. Earthseer Farsen måste undersöka den innan planen kan fastställas.",al={"varför gräver dark iron tunnlar","dark iron-plan i dun morogh"}},{q="Vad leder det här uppdraget till?",a="När du lämnar kartan till Earthseer Farsen inleds undersökningen av djupen under staden. Den leder rakt in i Old Ironforge Incursion och öppnar vägen mot The Hall of Thanes.",al={"fortsättning på underground map","nästa uppdrag efter underground map"}},{q="På vilket språk är kartans runor skrivna?",a="Kartan använder Dark Iron-dvärgarnas kantiga runskrift. Den som hittar den kan inte vara säker på vad anteckningarna säger.",al={"kartans runor","dark iron-språk"}}},fx={["1c73103d"]={q="Varför måste Dark Iron Map lämnas till Earthseer Farsen?",a="Kartan visar ett oroväckande nätverk av underjordiska tunnlar och vägar som alla löper samman direkt under Ironforge. De kantiga Dark Iron-runorna måste tydas, och den kusliga dvärgrösten som vinden bär med sig gör det tydligt att Earthseer Farsen genast måste undersöka det möjliga hotet under jord och varna bergariket.",al={"varför lämna kartan till farsen","dark iron maps syfte","varför leverera kartan"}}},fp="15,383,27.404.0,20.344.1,41.165.0,23.147.0,24.216.0,49.181.0,29.201.1,45.127.0"}
P.entries["quest:96392"] = {n="Farsen's Watch",s="Farsen's Watch är ett spaningsuppdrag från Earthseer Farsen, en gästande Wildhammer-shaman som är stationerad högt ovanför Gol'Bolar Quarry. Med jordskådarens shamanistiska fjärrsyn får äventyrare själva se hur Dark Iron-dvärgar i allt större antal tränger in i hjärtat av Dun Morogh. Den här viktiga undersökningen är ett tidigt steg på vägen mot The Hall of Thanes.",h="Farsen's Watch är ett spaningsuppdrag från Earthseer Farsen, en gästande Wildhammer-shaman som är stationerad...",kw={"aerie peak","dark iron","dun morogh","jordskådare","farsen","fjärrsyn","gol'bolar","the hall of thanes","wildhammer"},ang={["class:Shaman"]="Wildhammer-jordskådare visar hur deras tradition förenar jordnära insikt och andlig syn, och ger en glimt av dvärgarnas shamanism med rötter i Aerie Peaks klippor.",["faction:Alliance"]="Att avslöja Dark Iron-planer i Dun Morogh är avgörande för att värna säkerheten i Ironforge och de omgivande bergspassen för alla som reser genom Alliance-länderna.",["race:Dwarf"]="För Bronzebeard-försvarare visar varningen från en släkting i Aerie Peak hur djärvt Dark Iron-folket har trängt in i deras hemland."},sec={{t="Ögon över bergskammen",b="Earthseer Farsen håller noggrann uppsikt över de lägre delarna av Dun Morogh från sin utsiktsplats ovanför den snöpinade utgrävningen i Gol'Bolar Quarry. Han har färdats söderut från Aerie Peaks klippor och för med sig Wildhammer-folkets skarpa andliga sinne till trakter som vanligtvis patrulleras av Ironforges bergsvandrare. I stället för att förlita sig på vanliga spejare använder Farsen klanens traditionella konster för att hålla koll på underjordiska skakningar och oväntade rörelser längs sluttningarna."},{t="En lånad syn",b="För att övertyga resenärer om den överhängande faran lånar Farsen ut sin fjärrsyn, en shamanistisk gåva som projicerar ens medvetande över stora avstånd. Genom den andliga linsen blir det tydligt att Dun Moroghs problem sträcker sig långt bortom bångstyriga troggar och vilda bestar. Dark Iron-dvärgar har tagit sig nära Ironforges industriella centrum och befäst sina positioner inför en operation som måste stoppas omedelbart, innan den får fäste."}},faq={{q="Vem är Earthseer Farsen?",a="Earthseer Farsen är en Wildhammer-dvärg som besöker Dun Morogh från Aerie Peak i The Hinterlands. Som jordskådare behärskar han shamanistisk magi som låter honom känna av störningar i marken och upptäcka hot på avstånd.",al={"earthseer farsen","vem är farsen","farsen wildhammer"}},{q="Var äger bevakningen rum?",a="Earthseer Farsen har sin plats med utsikt över Gol'Bolar Quarry, en viktig gruvutgrävning för Bronzebeard i östra Dun Morogh.",al={"farsens plats","var är farsen","utsikt över gruvan"}},{q="Vilket hot avslöjar Farsen?",a="Med sin shamanistiska fjärrsyn avslöjar Farsen att fientliga Dark Iron-dvärgar har etablerat ett fäste i närheten och utgör ett aktivt och farligt hot mot trakten.",al={"vad visar fjärrsynen","hot från dark iron","farsens syn"}},{q="Hur hänger detta ihop med The Hall of Thanes?",a="När du undersöker Dark Iron-närvaron som upptäcktes under Farsen's Watch inleds den längre kedja av uppgifter som äventyrare måste slutföra för att få tillträde till The Hall of Thanes.",al={"tillträde till hall of thanes","uppdragskedja till hall of thanes"}},{q="Varför deltar en Wildhammer-dvärg i försvaret av Dun Morogh?",a="Wildhammer-folket har The Hinterlands som hem, men släktband och gemensam fiendskap mot Dark Iron-dvärgarna för ibland resenärer som Farsen till Bronzebeards förfädersmarker i Dun Morogh.",al={"varför är wildhammer här","aerie peak-dvärg i dun morogh"}},{q="Vad händer direkt efter Farsen's Watch?",a="När du har bevittnat Dark Iron-infiltrationen genom hans syn manar Farsen dig vidare med uppdraget 'Nip 'Em in the Bud' för att aktivt hejda fienden som rycker fram.",al={"nästa uppdrag","vad händer efter farsen's watch","nip em in the bud"}}},fx={["73fc96dc"]={q="Varför vill Earthseer Farsen att det här görs?",a="På väg genom Dun Morogh från Aerie Peak upptäckte Earthseer Farsen tecken på att Dark Iron-dvärgarna trängde fram nära Gol'Bolar Quarry. Innan han agerar eller slår larm vill schamanen att du själv ska bevittna den växande faran genom hans fjärrskådande magi. Då kan Ironforges försvarare förstå den fientliga infiltrationens verkliga omfattning innan den går överstyr.",al={"varför farsen's watch","farsens motiv","varför vill farsen att jag undersöker"}}},fp="14,364,21.463.0,17.448.0,24.219.0,33.127.0,31.165.0,44.164.0,59.191.0,52.174.0"}
P.entries["quest:96393"] = {n="Old Ironforge Incursion",s="Old Ironforge Incursion är det avslutande uppdraget i utredningen av Dark Iron-infiltratörer som gömmer sig djupt under Ironforge. På uppdrag av Earthseer Farsen går hjältar in i The Hall of Thanes under Old Ironforge för att döda fiendens befälhavare, Durgen Dirgehammer, och rapportera hotet direkt till King Magni Bronzebeard.",h="Old Ironforge Incursion är det avslutande uppdraget i utredningen av Dark Iron-infiltratörer som gömmer sig...",kw={"dark iron","dirgehammer","farsen","intrång","ironforge","kharanos","magni","thane"},ang={["faction:Alliance"]="Genom att stoppa intrånget förhindrar man en förödande överraskningsattack mot Alliansens främsta fäste i Eastern Kingdoms.",["race:Dwarf"]="För Bronzebeards är Dark Iron-infiltratörer som lurar i de bortglömda valven under High Seat en oacceptabel kränkning av deras förfäders fästning."},sec={{t="In i valven",b="Efter upptäckten av en underjordisk karta som avslöjade Dark Irons rörelser pekar Earthseer Farsen ut hjärnan bakom intrånget under jord. Djupt inne i Old Ironforges gamla stensalar ligger ingången till The Hall of Thanes. Medan den övre staden ägnar sig åt sådant som sker på ytan har lömska krafter smugit sig in i dessa slumrande grottor, rakt under kungarikets fötter."},{t="Durgen Dirgehammer",b="Farsens tolkning av tillfångatagna Dark Iron-dokument pekar ut en enda befälhavare som styr operationerna: Durgen Dirgehammer. Djupt inne i de nedre valven utgör Dirgehammer ett direkt hot mot hjärtat av Bronzebeards bergsrike. För att knäcka intrånget måste äventyrare störta ner i djupet, döda honom och bära hans avhuggna huvud upp till King Magni Bronzebeard."},{t="Möte med kungen",b="När Durgen Dirgehammers huvud visas upp för King Magni Bronzebeard bekräftar det den dystra verkligheten: Dark Iron-hotet slingrar sig genom stadens gamla rötter. Med både det makabra beviset på segern och en personlig hälsning från sin gamle vän Farsen avslutar äventyrarna formellt utredningen och ser till att Magni får veta vad som lurar där nere."}},faq={{q="Vad är Old Ironforge Incursion?",a="Det är slutet på en uppdragskedja som undersöker Dark Iron-aktivitet under Dun Morogh. Uppdraget ges av Earthseer Farsen och går ut på att ta sig in i The Hall of Thanes under Old Ironforge och döda Dark Iron-befälhavaren Durgen Dirgehammer.",al={"uppdraget old ironforge incursion","uppdraget durgen dirgehammer"}},{q="Var utspelar sig uppdraget?",a="Uppdraget tar äventyrarna till The Hall of Thanes, en uråldrig kammare under jord under Old Ironforge, djupt inne i berggrunden under bergshuvudstaden.",al={"var ligger the hall of thanes","the hall of thanes plats"}},{q="Vem är Durgen Dirgehammer?",a="Durgen Dirgehammer är Dark Iron-befälhavaren som leder intrånget under jord i The Hall of Thanes under Old Ironforge. Earthseer Farsen hittar hans namn i återfunna Dark Iron-dokument.",al={"vem är dirgehammer","durgen dirgehammer"}},{q="Vem ger uppdraget, och vem lämnas det in till?",a="Uppdraget ges av Earthseer Farsen efter att Underground Map har återfunnits. Det lämnas direkt till King Magni Bronzebeard i Ironforge.",al={"uppdragsgivare old ironforge incursion","vem lämnar in old ironforge incursion"}},{q="Hur startar jag uppdragskedjan som leder hit?",a="Kedjan börjar med uppdraget A Visitor to Dun Morogh, som Beldin Steelgrill erbjuder utanför Kharanos i Dun Morogh.",al={"starta uppdraget the hall of thanes","starta a visitor to dun morogh"}},{q="Vilken koppling finns mellan Earthseer Farsen och King Magni?",a="Earthseer Farsen betraktar sig som en gammal vän till King Magni Bronzebeard och ber äventyrarna framföra en personlig hälsning när de visar upp Durgen Dirgehammers huvud i tronrummet.",al={"farsen och magni","earthseer farsens historia"}}},fx={bdae81a8={q="Varför vill Earthseer Farsen att Durgen Dirgehammer dödas?",a="Farsen upptäckte fienderörelser under berget och tydde order som pekade ut Durgen Dirgehammer som befälhavaren bakom angreppet mot Old Ironforge. Dark Iron-styrkornas närvaro i det forntida Hall of Thanes hotar dvärgarnas huvudstad direkt underifrån. Genom att skicka dig för att fälla deras ledare vill Farsen krossa anfallet innan Dark Iron-styrkorna hinner befästa sina positioner och skicka ett obestridligt bevis på hotet direkt till King Magni Bronzebeard.",al={"farsens motiv","varför döda durgen dirgehammer","varför skickar farsen dig"}},["664606f0"]={q="Vad ska Durgen Dirgehammer's Head användas till?",a="Du behöver Durgen Dirgehammer's Head som obestridligt bevis för King Magni Bronzebeard på att befälhavaren för angreppet under jord har oskadliggjorts. När du lämnar den makabra trofén direkt i tronsalen bekräftar det att den fientliga Dark Iron-styrkan i Hall of Thanes har förlorat sin ledare. Den för också med sig Earthseer Farsens personliga varning till kungen.",al={"durgen dirgehammer's head användning","varför ta med durgens huvud","durgen dirgehammers huvud"}}},fp="23,341,20.394.0,18.411.1,22.347.1,32.237.0,33.165.0,26.200.0,41.150.0,50.117.0,63.190.0"}
P.entries["quest:96394"] = {n="The Restless Dead",s="The Restless Dead handlar om en oroväckande störning i Hall of Thanes kryptor, där uråldriga dvärgaandar har väckts ur sin vila. Vårdarna är för rädda för att gå in i gravkamrarna, så en äventyrare måste ta sig ner i katakomberna och söva de arga vålnaderna och Anvilmars ande på nytt.",h="The Restless Dead handlar om en oroväckande störning i Hall of Thanes kryptor, där uråldriga dvärgaandar har...",kw={"anvilmar","dvärgagravar","dvärgaandar","enraged apparitions","spöken","the hall of thanes","anvilmars ande","the restless dead","tormented souls"},ang={["class:Priest"]="Andar som dröjer kvar i plåga eller vrede är en direkt kallelse till plikt för dem som har kontakt med själar och leder oroliga döda mot en fridfull vila.",["faction:Alliance"]="När förfädernas kryptor under Ironforge säkras kan väktarna sköta sina heliga plikter utan att frukta att hämndlystna vålnader ska övermanna dem.",["race:Dwarf"]="I Hall of Thanes vilar dvärgafolkets ärade döda och förfäder. Att de plötsligt och våldsamt vaknat är därför en oroande störning mitt i deras kulturarv."},sec={{t="Störning i de djupa gravkamrarna",b="Djupt under ytan i Hall of Thanes ligger förfädernas kryptor, där generationer av ärade döda vilar. Andarna brukar sova stilla, men har våldsamt rörts upp av en osedd störning i gravkamrarna. Märkliga ljud som ekar upp nerifrån har skrämt platsens vårdare, som vägrar gå in i de nedre kamrarna och utföra sina uppgifter förrän ordningen återställts. Äventyrare kallas in för att ta sig ner i de skuggiga stensalarna och lugna de upprörda själarna."},{t="Att lugna förfäderna",b="Andarna som vilar i Hall of Thanes är ökända för att sova lätt. Vad det än var som skakade om de nedre gravarna väckte horder av Enraged Apparitions och Tormented Souls och förvandlade helig mark till ett farligt tillhåll för vålnader. Bland de väckta finns den vördnadsvärda anden Anvilmar, och det krävs en respektfull men bestämd hand för att stilla de väckta förfädernas vrede och återställa friden i katakomberna."}},faq={{q="Vad handlar uppdraget The Restless Dead om?",a="The Restless Dead är ett uppdrag att undersöka och hejda en våg av spöklika störningar under Hall of Thanes. Någon eller något skrämde de begravda andarna, och väktarna vågar inte gå in i gravkamrarna förrän vålnaderna har tagits om hand.",al={"vad är the restless dead","vad är det här för uppdrag","översikt över uppdraget the restless dead"}},{q="Varför har andarna vaknat?",a="En okänd störning djupt inne i gravkamrarna väckte de begravda döda. Andarna i Hall of Thanes beskrivs som lättväckta, så vad som än hände nere i gravarna skrämde dem till raseri och plåga.",al={"varför är spökena arga","vem störde gravarna","varför är vålnaderna vakna"}},{q="Var äger störningen rum?",a="Störningen har sitt centrum i kryptorna och gravkamrarna i Hall of Thanes, en viloplats för förfäderna under Ironforge där uråldriga dvärgaandar ligger begravda.",al={"var ligger hall of thanes","var dyker the restless dead upp","hall of thanes läge"}},{q="Vem är Anvilmars ande?",a="Anvilmars ande är en uråldrig och framstående själ som vilar i de djupa gravarna i Hall of Thanes. Tillsammans med mindre vålnader väcktes denna mäktiga ande ur sin slummer och måste återföras till en fridfull vila.",al={"vem är anvilmars ande","anvilmars ande i berättelsen","vem är spöket anvilmar"}},{q="Varför behöver väktarna en äventyrares hjälp?",a="Väktarna har i uppgift att sköta kryptorna och utföra sina vanliga plikter i Hall of Thanes. När arga andar stryker omkring i salarna vägrar de gå ner i de nedre gravkamrarna innan hotet har undanröjts.",al={"vilka är väktarna","varför behöver väktarna hjälp","väktarna i hall of thanes"}},{q="Vilka andar hemsöker Hall of Thanes?",a="De störda gravkamrarna hemsöks av Enraged Apparitions, Tormented Souls och Anvilmars vördnadsvärda ande, som alla skrämts upp och nu håller vakt aggressivt i gravkamrarna.",al={"vilka slags spöken finns där nere","vålnader i hall of thanes","typer av rastlösa döda"}}},fp="17,321,30.474.0,22.404.1,38.258.0,30.226.0,39.169.0,30.215.0,45.228.0,38.184.0"}
P.entries["quest:96395"] = {n="An Ancient Grudge",s="Djupt inne i den historiska Hall of Thanes ber en eterisk tjänare om ett slut på en fallen härskares plåga. Faldrim Anvilmars ande dröjer kvar, uppslukad av en gammal oförrätt och utan möjlighet till evig frid. Äventyrare får i uppdrag att ge den rastlöse thanen ro.",h="Djupt inne i den historiska Hall of Thanes ber en eterisk tjänare om ett slut på en fallen härskares plåga.",kw={"uråldrig oförrätt","anvilmar","dvärgspöke","faldrim anvilmar","ghostly attendant","the hall of thanes","rastlös ande","thane"},ang={["class:Paladin"]="Att ge en plågad själ ro är en högtidlig plikt för heliga krigare som svurit att bringa frid åt de lidande döda.",["class:Priest"]="Präster vet att kvardröjande oförrätter och obotad sorg kan binda en dödlig ande till den fysiska världen långt efter att kroppen blivit till stoft.",["race:Dwarf"]="För dvärgar är det en allvarsam påminnelse att möta en rastlös thane ur det egna folket: en uråldrig oförrätt kan överleva själva döden."},sec={{t="En bön från graven",b="I Hall of Thanes stenkammare erbjuder döden ingen omedelbar vila. En spöklik tjänare till Faldrim Anvilmar dröjer kvar där, knappt stark nog att tala genom slöjan mellan de dödliga och de döda. Vålnadens enda bekymmer är dess herre, inte dess egen frihet, och den ber resenärer att stilla thanens upprörda ande."},{t="Det förflutnas börda",b="Döden har inte befriat Faldrim Anvilmar från det förflutna. En förtärande, uråldrig oförrätt binder Faldrim till den fysiska världen. Hans spöke är fortsatt upprört och fientligt och kan inte finna ro förrän det får en kraftfull befrielse."}},faq={{q="Vem är Faldrim Anvilmar?",a="Faldrim Anvilmar var en dvärgthane vars rastlösa vålnad nu hemsöker Hall of Thanes. Hans Ghostly Attendant säger att han är uppslukad av en uråldrig oförrätt och inte kan finna ro. Uppdraget säger inget mer om hans liv eller släkt.",al={"faldrim anvilmars historia","vem är faldrim","thane anvilmar"}},{q="Var ligger Hall of Thanes?",a="Hall of Thanes ligger i grottorna under Old Ironforge, inne i dvärgarnas huvudstad Ironforge.",al={"var ligger hall of thanes","var finns hall of thanes","ingången till hall of thanes"}},{q="Varför är Faldrim Anvilmars spöke fientligt?",a="Enligt den spöklika tjänaren är den forne thanen uppslukad av en uråldrig oförrätt. Dvärgarnas historia präglas av århundraden av klanrivalitet, och Faldrims kvarvarande hat hindrar hans ande från att gå vidare till fridfull vila.",al={"varför är faldrim arg","varför anfaller thanen","förklaring av uråldrig oförrätt"}},{q="Vem ger uppdraget An Ancient Grudge?",a="Uppdraget ges av en Ghostly Attendant som finns inne i Hall of Thanes. Tjänaren är bunden till sin tjänst även efter döden och önskar bara frid för sin forne herre.",al={"vem startar ancient grudge","ghostly attendant-uppdrag","uppdragsgivare"}},{q="Vad måste du göra för att slutföra uppdraget?",a="Du måste möta Faldrim Anvilmars ande inne i Hall of Thanes, besegra hans rastlösa spöke i strid för att befria honom från hans plåga och återvända till Ghostly Attendant.",al={"hur slutför man ancient grudge","ge faldrim ro","målet med ancient grudge"}},{q="Är Faldrim släkt med staden Anvilmar?",a="Det är ännu inte känt. Faldrim har samma namn som bosättningen Anvilmar i Coldridge Valley, men uppdraget säger inget om hans familj eller någon koppling till staden.",al={"kommer faldrim från anvilmar","kopplingen mellan anvilmar och coldridge","anvilmars släkt"}}},fp="17,276,21.348.0,22.214.1,24.233.0,36.102.0,45.234.0,38.168.0,39.186.0,43.166.0"}
P.entries["quest:96403"] = {n="Important Heirlooms",s="Important Heirlooms är ett uppdrag där en äventyrare hjälper en nervös gnom vid namn Thom, som ertappades med att smyga omkring i The Hall of Thanes när Dark Iron-dvärgar bröt sig in i valven med underjordiska mullvadsmaskiner. Uppdraget går ut på att återfinna utspridda dvärgreliker under förevändning att bevara historien.",h="Important Heirlooms är ett uppdrag där en äventyrare hjälper en nervös gnom vid namn Thom, som ertappades med...",kw={"dark iron","dvärgarnas arvegods","gnom","the hall of thanes","important heirlooms","mullvadsmaskin","thom","valv"},ang={["class:Rogue"]="En skurk genomskådar lätt Thoms dåliga ursäkt om att ”patrullera” valven och ser en medplundrare som överrumplats av en underjordisk invasion.",["race:Dwarf"]="Dvärgäventyrare kan se med stor skepsis på Thoms plötsliga intresse för att rädda förfädernas reliker, särskilt med tanke på hans felsägningar om byte och värdering.",["race:Gnome"]="Thoms opportunism och klumpiga täckhistorier visar en mindre vetenskaplig sida av gnomernas nyfikenhet när värdefulla reliker står på spel."},sec={{t="Problem i valven",b="När den företagsamma gnomen Thom utforskade de underjordiska valven i The Hall of Thanes avbröts han av Dark Iron-dvärgar som plötsligt borrade sig uppåt i mullvadsmaskiner. Thom kunde inte säkra området på egen hand och rekryterar därför förbipasserande äventyrare för att våga sig in på den fientliga utgrävningsplatsen och hämta värdefulla dvärgreliker som ligger utspridda i kamrarna, innan inkräktarna tar eller förstör dem."},{t="Kulturbevarande eller lukrativ plundring?",b="Thom hävdar att han bara var på patrull och vill katalogisera relikerna för att bevara dem, men han försäger sig ständigt med prat om ”ovärderligt byte” och att ”värdera fynden”, vilket tyder på betydligt mer själviska motiv. Äventyrarna får rikligt betalt för sitt mod, men om dessa urgamla dvärgskatter någonsin hamnar på ett museum eller en auktion återstår att se."}},faq={{q="Vem är Thom?",a="Uppdraget ges av Thom, en företagsam gnom som håller till nära valven. Hans nervösa felsägningar antyder att han är mycket mer intresserad av lukrativ plundring än av att säkra valven på ett hederligt sätt.",al={"vem ger uppdraget","vem är thom","uppdragsgivare"}},{q="Vad är The Hall of Thanes?",a="The Hall of Thanes är ett underjordiskt dvärgvalv med uråldriga kulturföremål och arvegods, som nyligen har brutits upp av Dark Irons underjordiska styrkor.",al={"vad är hall of thanes","var ligger hall of thanes"}},{q="Varför är Dark Iron-dvärgarna i valven?",a="En styrka med Dark Iron-dvärgar bröt sig in i valven direkt från djupen med hjälp av borrande mullvadsmaskiner och kastade området i kaos av okända skäl.",al={"varför är dark iron där","dark iron-mullvadsmaskiner"}},{q="Återlämnar Thom verkligen arvegodset?",a="Thom försäger sig ständigt: han kallar smygandet för ”patrullering”, arvegodset för ”byte” och ”fynd” och katalogiseringen för ”värdering”. Han betalar den utlovade belöningen, men hans påståenden om att återföra relikerna till hedersplatser är mycket tvivelaktiga.",al={"ljuger thom","stjäl thom","är thom pålitlig"}},{q="Vad är Dwarven Heirlooms?",a="Det är uråldriga dvärgiska kulturföremål som förvaras i The Hall of Thanes och som historiker betraktar som ovärderliga skatter – och opportunister som Thom som lukrativt byte.",al={"vad är arvegodset","dvärgarnas arvegods i historien"}},{q="Varför kan inte Thom hämta arvegodset själv?",a="Thom överrumplades av Dark Iron-mullvadsmaskinernas plötsliga ankomst medan han smög omkring i valven, så han kan inte själv leta rätt på relikerna på ett säkert sätt utan skydd från en äventyrare.",al={"varför behöver thom hjälp","varför hjälpa thom"}}},fp="19,306,21.398.0,43.388.1,12.191.0,27.167.0,40.162.0,39.237.0,31.167.0,46.196.0"}
P.entries["quest:96408"] = {n="A Visitor to Dun Morogh",s="A Visitor to Dun Morogh är ett undersökande uppdrag från Beldin Steelgrill utanför Kharanos. Bergsvakter har rapporterat en okänd lägereld högt uppe på klipporna ovanför Gol'Bolar Quarry. Därför skickas en spejare dit för att ta reda på om främlingen utgör ett hot mot de lokala dvärgarna.",h="A Visitor to Dun Morogh är ett undersökande uppdrag från Beldin Steelgrill utanför Kharanos.",kw={"beldin steelgrill","dun morogh","earthseer farsen","farsen's watch","gol'bolar quarry","the hall of thanes","kharanos","besökare"},ang={["class:Shaman"]="Mötet med Earthseer Farsen knyter an direkt till andlig samhörighet med bergets stenar, en ovanlig syn i Dun Moroghs snötäckta högland.",["faction:Alliance"]="När du hjälper de lokala bergsvakterna utanför Kharanos ser du till att försörjningslederna och arbetarna i stenbrottet skyddas mot oväntade hot.",["race:Dwarf"]="För Bronzebeard-dvärgarna är det standard att bevaka objudna betraktare som ser ut över stora gruvplatser som Gol'Bolar, för att skydda Khaz Modans gränser."},sec={{t="En rökpelare på höjderna",b="Dun Moroghs bergsvakter håller noggrann uppsikt över klippbranterna och de snöiga dalarna kring Ironforge. När en lägereld plötsligt dök upp högt ovanför Gol'Bolar Quarry höjdes ögonbrynen i Kharanos. Beldin Steelgrill oroar sig för det ovanliga lägret, som ligger precis ovanför en viktig dvärggruva. Han rekryterar resenärer för att ta sig uppför bergsryggarna och avgöra om den mystiske främlingen är en fredlig resenär eller en inkräktare."},{t="Mötet med jordsearen",b="När du undersöker bergsryggen upptäcker du att resenären är Earthseer Farsen, en mystiker som slagit läger på de vindpinade höjderna. Han är ingen härjande trogg eller fientlig spion, utan en mystisk betraktare med djupa andliga band till jorden. Hans närvaro på klippavsatsen ovanför stenbrottet inleder en färd där du upptäcker djupare störningar gömda under Khaz Modan, och som till slut knyter an till mysteriet kring The Hall of Thanes."}},faq={{q="Vem skickar dig för att undersöka besökaren?",a="Beldin Steelgrill, som är stationerad utanför Kharanos i Dun Morogh, ger dig uppdraget efter att bergsvakter rapporterat en okänd eld uppe i kullarna.",al={"vem ger uppdraget","uppdragsgivare","beldin steelgrills uppdrag"}},{q="Var ligger det mystiska lägret?",a="Lägerelden brinner högt uppe på de snöiga bergsryggarna öster om Kharanos, precis ovanför utgrävningen i Gol'Bolar Quarry.",al={"lägrets plats","var är besökaren","besökarens plats"}},{q="Vem är besökaren som vakar över stenbrottet?",a="Besökaren är Earthseer Farsen, en andlig betraktare som bor i ett avskilt läger på höjderna ovanför stenbrottet.",al={"vem är farsen","vem är besökaren","earthseer farsen"}},{q="Varför misstänkte dvärgarna att något var fel med lägerelden?",a="Gol'Bolar Quarry är en viktig dvärgverksamhet som redan är pressad av lokala troggar. Ett okänt läger högt ovanför gropen kan lätt tillhöra spejare eller fientliga styrkor som bevakar dvärgarnas rörelser.",al={"varför misstänksam","varför undersöka","varför skickas jag"}},{q="Vad leder det här uppdraget vidare till?",a="När du rapporterar till Earthseer Farsen leder det direkt vidare till uppdraget 'Farsen's Watch' och är den första ledtråden i kedjan som låser upp The Hall of Thanes.",al={"what comes next","nästa uppdrag","introduktion till hall of thanes"}},{q="Måste du slåss mot främlingen vid lägret?",a="Nej. Beldin Steelgrill förbereder dig på att våld kan bli nödvändigt, men besökaren är Earthseer Farsen, en fredlig betraktare som gärna talar med dig.",al={"är besökaren fientlig","ska jag döda besökaren","slåss mot besökaren"}}},fx={["3b0d76fb"]={q="Varför ber Beldin Steelgrill en äventyrare i stället för bergsvakterna?",a="De lokala bergsvakterna såg lägerelden på sluttningen på avstånd, men de är upptagna med att vakta vägar, bosättningar och stenbrottet mot troggar och vilddjur. Eftersom elden troligen är ofarlig ber Beldin en duglig resenär som passerar genom Kharanos att snabbt undersöka bergsryggen, i stället för att ta vakter från deras aktiva uppdrag.",al={"varför skicka mig","varför inte skicka vakter","beldin steelgrill varför jag"}}},fp="23,274,28.427.0,21.440.1,41.138.0,41.132.0,42.114.1,48.212.0,31.154.1,46.153.1"}
P.entries["quest:965"] = {n="The Tower of Althalaxx",s="Sentinel Elissa Starbreeze ansvarar för försvaret av Auberdine och misstänker skumma affärer vid de gamla ruinerna i norr. Hon ber äventyrare hitta Balthule Shadowstrike, en spejare som skickades för att bevaka den gåtfulla Tower of Althalaxx men inte har rapporterat tillbaka i tid.",h="Sentinel Elissa Starbreeze ansvarar för försvaret av Auberdine och misstänker skumma affärer vid de gamla...",kw={"althalaxx","auberdine","balthule shadowstrike","darkshore","elissa starbreeze","spejare","väktare","torn"},ang={["faction:Alliance"]="Auberdine är Alliansens främsta port till norra Kalimdor, så det är viktigt för alla besökande allierade att försvara vägarna och gränserna runt bosättningen.",["race:NightElf"]="Ruinerna i Althalaxx påminner om det forntida Kalimdors fallna högborne-folk. Att skydda Auberdine från korruptionen som frodas i stenarna är en livsviktig plikt för Night Elf-väktarna."},sec={{t="En spejare saknas",b="Auberdines väktare måste ständigt hålla uppsikt över Darkshores växande faror. Sentinel Elissa Starbreeze lade märke till misstänkt aktivitet kring Tower of Althalaxx i skogens norra delar. Hon skickade Balthule Shadowstrike för att undersöka den gamla ruinen. Flera dagar har gått utan ett livstecken från spejaren, så Elissa söker en villig resenär som kan bege sig norrut, hitta Balthule och se till att han inte gått ett för tidigt öde till mötes."},{t="Ögon på ruinen",b="Vägen norrut från Auberdine passerar gamla Kaldorei-ruiner och går över Cliffspring River innan den når tornets skuggiga utbredning. Trots att Balthule inte kunnat skicka bud tillbaka till Auberdine överlevde han den första spaningen. När du hittar honom i skogen runtom bekräftar han att Elissas misstankar stämde: mörka och oroande ting pågår för fullt inne i den sönderfallande stenspiran."}},faq={{q="Vem är Sentinel Elissa Starbreeze?",a="Elissa Starbreeze är en Night Elf-väktare stationerad i Auberdine. Hon ansvarar för att skydda bosättningen mot yttre hot i hela Darkshore och håller uppsikt över faror i området, som Tower of Althalaxx.",al={"elissa starbreeze","vem ger uppdraget","uppdragsgivare i auberdine"}},{q="Vem är Balthule Shadowstrike?",a="Balthule Shadowstrike är en spejare som Sentinel Elissa Starbreeze skickade för att spana på den mystiska aktiviteten kring Tower of Althalaxx. Han håller vakt utanför ruinen för att hålla koll på fientliga styrkor.",al={"balthule","vem är spejaren","shadowstrike"}},{q="Var ligger Tower of Althalaxx?",a="Tornet ligger i nordöstra Darkshore. Du når det genom att färdas österut från Auberdine, följa den norra vägen förbi Bashal'Aran och korsa bron över Cliffspring River tills spiran blir synlig.",al={"tower of althalaxx plats","var ligger tornet","hur hittar man althalaxx"}},{q="Varför skickades en spejare till tornet från början?",a="Elissa skickade Balthule för att undersöka märkliga händelser kring Tower of Althalaxx medan hon fullgjorde sitt uppdrag att skydda Auberdine.",al={"varför bevaka tornet","vad är fel vid althalaxx","varför skickades balthule"}},{q="Varför har Balthule inte återvänt till Auberdine?",a="Elissa har inte fått någon rapport från Balthule och ber dig se till honom. Balthule kan förklara sin situation när du hittar honom.",al={"varför saknas balthule","är balthule fångad","varför stannade balthule"}},{q="Fortsätter den här uppdragskedjan?",a="Ja. När du hittar Balthule Shadowstrike inleds en utredning i flera delar om de mörka krafter som ockuperar Tower of Althalaxx och deras ondskefulla planer i Darkshore.",al={"är det här en kedja","vilket uppdrag kommer sedan","althalaxx-kedjan"}}},fx={["895f5562"]={q="Varför vill Sentinel Elissa Starbreeze att det här görs?",a="Som vaktpost med ansvar för försvaret av Auberdine ska Elissa Starbreeze skydda Darkshore mot hot som tränger sig på. Hon skickade Balthule Shadowstrike för att undersöka misstänkta händelser nära Tower of Althalaxx, men han har varit borta alltför länge. Hon fruktar att han råkat illa ut och behöver någon som hittar honom och bekräftar att han är oskadd.",al={"varför hitta balthule","elissa starbreezes motiv","varför skicka mig till tower of althalaxx"}}},fp="22,174,23.345.0,18.350.1,34.188.0,29.184.0,40.211.0,53.118.0,42.129.0,31.156.0"}
P.entries["quest:966"] = {n="The Tower of Althalaxx",s="När spanaren Balthule Shadowstrike undersöker misstänkt aktivitet kring Tower of Althalaxx i norra Darkshore tar han hjälp för att samla information om de samlade häxmästarna. Genom att återvinna kasserade pergamentbitar från fanatikerna som slagit läger utanför ruinerna försöker han avslöja kultisternas identitet och mörka syfte.",h="När spanaren Balthule Shadowstrike undersöker misstänkt aktivitet kring Tower of Althalaxx i norra Darkshore...",kw={"althalaxx","auberdine","balthule","dark strand","darkshore","delgren","fanatiker","pergament","purifier","shadowstrike","häxmästare"},ang={["class:Paladin"]="Upptäckten av en samlad mörk kult i norra Darkshore hjälper direkt Delgren the Purifiers korståg. Han är en allierad som arbetar för att utrota kaos och demonisk korrumpering.",["class:Warlock"]="Cult of the Dark Strand visar att oberoende häxmästarkretsar tar över gamla ruiner för att utföra sina kallelser långt från både Alliansens och Hordens myndigheters nyfikna blickar.",["race:NightElf"]="De mörka kultisternas skändning av Tower of Althalaxx är ännu en vanhelgning av det gamla alvarvet längs Kalimdors kuster."},sec={{t="Ögon i grundvattnet",b="Balthule Shadowstrike håller vakt längs den dimmiga kusten i norra Darkshore och spanar vaksamt mot den gamla ruinen som kallas Tower of Althalaxx. Han har skickats dit för att övervaka platsen åt Auberdine och varna Delgren the Purifier om faran ökar, men tvekar att lämna sin post för att rapportera. Han är rädd att missa viktiga rörelser från de mörka magikerna som tagit över stenarna och låter därför förbipasserande resenärer spana av lägren i utkanten."},{t="Kultens hemlighet",b="De lägre följarna som hemsöker ruinerna bär på fragmenterade skriftrullar och anteckningar. Genom att sammanfoga flera slitna pergament som återfunnits hos kultisterna i utkanten upptäcker Balthule ett oroande namn: Cult of the Dark Strand. Spanaren känner inte till den skuggfulla sekten, men inser att hotet är mer organiserat än ett enkelt gäng avhoppade häxmästare, och att Delgren måste varnas genast."}},faq={{q="Vem är Balthule Shadowstrike?",a="Balthule Shadowstrike är en spanare i Alliansen som är posterad längs vägen nära Tower of Althalaxx i norra Darkshore. Han skickades dit för att övervaka misstänkta sammankomster vid tornet på uppdrag av ledningen i Auberdine och paladinen Delgren the Purifier.",al={"balthule shadowstrike bakgrund","vem är balthule","balthule darkshore"}},{q="Vad är Tower of Althalaxx?",a="Tower of Althalaxx är en gammal alvruin i norra Darkshore. På senare tid har mörka häxmästare och deras kultistiska tjänare tagit över markerna runt tornet och dess inre, där de utför mörka ritualer långt från Auberdines uppsikt.",al={"tower of althalaxx","vad är althalaxx","förfallen tornruin i darkshore"}},{q="Vilka är kultisterna kring tornet?",a="De tillhör Cult of the Dark Strand, en hemlighetsfull organisation av häxmästare och fanatiker som samlats vid de gamla alvruinerna för att utföra mörka kallelseritualer.",al={"vilka är häxmästarna","cult of the dark strand","dark strands fanatiker"}},{q="Varför avråder Balthule från att gå in i tornet?",a="Balthule påpekar att häxmästarna som håller till i tornets övre delar är mycket mäktigare och farligare än fanatikerna som slagit läger bland ruinerna utanför. Han rekommenderar att samla information från utkanten innan man försöker storma fästet.",al={"kan jag gå in i tornet","farliga häxmästare i tornet","inne i tornet"}},{q="Vad avslöjar de slitna pergamenten?",a="Lösa fragment som kultens fanatiker bär på ger den första tydliga bekräftelsen på gruppens namn, Cult of the Dark Strand. De visar Balthule att ockupanterna är en organiserad sekt vars närvaro utgör ett omedelbart hot mot regionen.",al={"vad står på pergamenten","bakgrund om worn parchment","kultens anteckningar"}},{q="Vem är Delgren the Purifier?",a="Delgren the Purifier är en paladin i Alliansen som är posterad vid Maestra's Post i Ashenvale och arbetar för att rena dem från demoniska och korrumperande krafter. Han misstänkte att illvillig verksamhet höll på att få fäste vid Tower of Althalaxx och är beroende av information från spanare som Balthule.",al={"delgren","vem är delgren","delgren the purifier"}}},fx={bc625320={q="Varför vill Balthule Shadowstrike att det här görs?",a="Balthule Shadowstrike fruktar att mörka krafter samlas i hemlighet precis vid Darkshores gränser. Delgren misstänkte att häxmästare samlades vid de forntida ruinerna, men ingen av dem vet vilka de är eller vilken vidrig ritual de tänker utföra. Balthule behöver tillräckligt med skriftliga bevis för att lista ut deras identitet och motiv innan han vidtar avgörande åtgärder för att skydda området.",al={"varför vill balthule ha skrifterna","balthules motiv","varför undersöka althalaxx"}},["151da73d"]={q="Varför skickar Balthule dig i stället för att gå själv?",a="Balthule är utposterad på en enslig spaningspost utanför ruinerna. Han kan inte lämna sin post för att genomsöka kultisternas läger i området eller återvända till Auberdine för att rapportera. Han är rädd att missa viktiga fienderörelser om han är borta. När han låter dig ta itu med kultisterna i utkanten och hämta deras skrifter kan han fortsätta hålla tornet under uppsikt.",al={"varför behöver balthule hjälp","varför inte balthule","varför ber balthule dig"}}},fp="22,258,20.371.0,20.328.1,29.229.0,31.220.0,43.179.0,50.225.0,35.189.0,28.264.0"}
P.entries["quest:96604"] = {n="The Great Outdoors",s="The Great Outdoors är ett introduktionsuppdrag i överlevnad i vildmarken, som Brakk erbjuder blivande äventyrare. Genom att lära sig vila vid en enkel lägereld får resenärer lära sig grunderna i att klara sig själva i det vilda innan de börjar med praktiska yrkesfärdigheter.",h="The Great Outdoors är ett introduktionsuppdrag i överlevnad i vildmarken, som Brakk erbjuder blivande...",kw={"boosted rest","brakk","lägeranordning","lägereld","the great outdoors","yrkesfärdighet","överlevnad i vildmarken"},ang={["faction:Horde"]="Med en traditionell orcisk hälsning, ”Lok-tar”, ger den här överlevnadslektionen blivande äventyrare från Horde en grund att stå på innan de ger sig ut i farliga områden."},sec={{t="Lärdomar i vildmarken",b="Att ge sig ut i Azeroths otämjda trakter kräver mer än kampvilja; det kräver grundläggande kunskaper för att uthärda väder och vind. Brakk hälsar blivande äventyrare med ett hjärtligt ”Lok-tar” och känner igen den rastlösa andan hos dem som söker rikedom och ära. För att klara den långa vägen framför sig måste varje resenär först bemästra konsten att slå läger och återhämta sina krafter ute i vildmarken."},{t="Från vila till hantverk",b="När du sätter dig vid Brakks Basic Campfire får du lära dig grunderna i återhämtning och kan vila stärkande under bar himmel. När du väl har förstått dessa överlevnadsgrunder hänvisas nybörjaräventyrare till byns hantverkare. Där kan de lära sig yrkesfärdigheter och upptäcka hur man bygger praktiska lägeranordningar som passar det yrke de valt."}},faq={{q="Vad är The Great Outdoors?",a="The Great Outdoors är ett introduktionsuppdrag i överlevnad som Brakk erbjuder. Det lär nya äventyrare att klara sig i vildmarken genom att vila vid en lägereld innan de väljer ett yrke.",al={"vad är the great outdoors","uppdraget the great outdoors"}},{q="Vem är Brakk?",a="Brakk är en erfaren överlevare i vildmarken som välkomnar rastlösa resenärer och ger praktiska lektioner i överlevnad och vila vid en lägereld.",al={"vem är brakk","uppdragsgivare"}},{q="Vad är Boosted Rest-bonusen?",a="Om du vilar vid Brakks Basic Campfire får du Boosted Rest-bonusen. Den visar hur skydd och återhämtning vid en öppen eld stärker en äventyrare i vildmarken.",al={"boosted rest-bonus","lägereldsbonus"}},{q="Vad ska du göra när du har slutfört uppdraget?",a="När äventyrarna har lärt sig grunderna i vila i vildmarken råder Brakk dem att besöka tränare i den närliggande byn för att studera en yrkesfärdighet och lära sig bygga lägeranordningar som passar deras hantverk.",al={"nästa steg efter uppdraget","vad göra efter lägerelden"}},{q="Vad är lägeranordningar?",a="Lägeranordningar är särskilda installationer för lägerplatser, som yrkestränare i närliggande byar lär ut. De låter resenärer anpassa sina läger efter de yrkesfärdigheter de valt.",al={"lägeranordningar","vad är lägeranordningar"}},{q="Vem är träningen till för?",a="Varje rastlös själ som söker rikedom och ära i vildmarken har nytta av den här lektionen, särskilt de som just har börjat sin resa och förbereder sig på att välja ett yrke.",al={"vem bör göra uppdraget","är det här för horde"}}},fp="18,262,19.401.0,20.356.0,27.194.0,13.153.0,30.169.0,46.198.0,23.179.0,34.163.0"}
P.entries["quest:96605"] = {n="The Great Outdoors",s="The Great Outdoors är ett introduktionsuppdrag som lär blivande äventyrare grunderna i överlevnad i vildmarken. Med vägledning av resenären Kaga lär sig nykomlingar att återhämta sig vid en enkel lägereld innan de går vidare till att lära sig yrkesfärdigheter och tillverka särskild lägerutrustning.",h="The Great Outdoors är ett introduktionsuppdrag som lär blivande äventyrare grunderna i överlevnad i...",kw={"boosted rest","lägerutrustning","lägereld","kaga","överlevnad","the great outdoors","yrkesfärdighet","vildmark"},ang={["profession:Cooking"]="Lägereldar och överlevnad i vildmarken är grunden för matlagning ute i fält, vilket gör lägerhantverk till ett naturligt komplement när du lagar mat under bar himmel."},sec={{t="Vildmarkens lärdomar",b="Varje äventyrare som lämnar civilisationens trygghet upptäcker snart att rått mod inte räcker för att överleva i vildmarken. The Great Outdoors lär nykomlingar hur viktigt det är att vänja sig vid vildmarken. Den erfarne resenären Kaga lär ut denna korta lektion och påminner blivande hjältar om att överlevnad i outforskade trakter börjar med kunskapen om hur man slår läger och uthärdar väder och vind."},{t="Eldstad och hantverk",b="En enkel lägereld är ofta det enda som står mellan en upptäcktsresande och utmattning i den otämjda vildmarken. När äventyrare sitter vid Kagas härd och får förstärkningen Boosted Rest upptäcker de hur lägerlivet hjälper dem att återhämta sig. När de väl har förstått grunderna i att vila i vildmarken uppmanar Kaga resenärer att besöka hantverkare i närliggande bosättningar för att lära sig yrkesfärdigheter och bemästra tillverkningen av professionell lägerutrustning."}},faq={{q="Vad är The Great Outdoors?",a="The Great Outdoors är ett introduktionsuppdrag i överlevnad i vildmarken som erbjuds av Kaga. Det lär blivande äventyrare grunderna i att överleva i vildmarken, vila vid en lägereld och förbereda sig för yrkesutbildning.",al={"vad är the great outdoors","uppdraget the great outdoors"}},{q="Vem erbjuder uppdraget?",a="Kaga är en erfaren resenär och friluftsmentor som lär blivande äventyrare grunderna i överlevnad i vildmarken. Han håller en enkel lägereld där nykomlingar kan vila och återhämta sig.",al={"vem är kaga","kaga uppdragsgivare"}},{q="Vad är förstärkningen Boosted Rest?",a="Boosted Rest är det välgörande tillstånd av avslappning som man får genom att sitta lugnt vid Kagas Basic Campfire. Den står för den återhämtande effekten av att vila ordentligt på en lägerplats i vildmarken.",al={"boosted rest","vad är förstärkningen boosted rest"}},{q="Vad är lägerutrustning?",a="När äventyrare har lärt sig grunderna i att vila i vildmarken kan yrkesinstruktörer i närliggande bosättningar lära dem att bygga särskild lägerutrustning anpassad efter deras valda hantverk.",al={"lägerutrustningens historia","yrkesutrustning för läger"}},{q="Varför ber Kaga dig att sitta vid lägerelden?",a="För att överleva utanför civiliserade städer måste man lära sig att slå läger och återfå orken. Genom att sitta vid en lägereld får äventyrare värme, fokus och återhämtning mellan farofyllda resor.",al={"varför vila vid lägereld","vila vid lägereld"}},{q="Vad ska du göra när lektionen är klar?",a="När du har lärt dig att vila ordentligt i vildmarken råder Kaga dig att söka upp yrkesinstruktörer i den närliggande byn för att lära dig ett yrke och få recept på lägerutrustning för yrket.",al={"vad göra efter the great outdoors","efter kaga-uppdraget"}}},fp="18,289,19.425.0,24.429.0,27.225.0,22.193.0,30.193.0,23.181.0,43.199.0,48.186.0"}
P.entries["quest:96606"] = {n="The Great Outdoors",s="The Great Outdoors är en grundläggande lektion i överlevnad i vildmarken som den erfarna spejaren Lyreena håller för jägare. Den betonar vikten av att vila vid en lägereld för att återhämta sig och få förstärkningen Boosted Rest under färder genom den otämjda vildmarken.",h="The Great Outdoors är en grundläggande lektion i överlevnad i vildmarken som den erfarna spejaren Lyreena...",kw={"äventyrare","boosted rest","lägereld","jägare","lyreena","överlevnad","the great outdoors","vildmark"},ang={["class:Hunter"]="Den här lektionen riktar sig direkt till jägare och betonar hur nödvändiga överlevnadskunskaper och lägerkunskaper är när man spårar genom otämjd vildmark."},sec={{t="Vildmarkens lärdomar",b="Att färdas bortom civilisationens gränser kräver mer än stadig hand och skarpa sinnen; det kräver respekt för de otämjda elementen. Den erfarna spejaren Lyreena vägleder kringvandrande jägare och välkomnar dem att stanna upp och vila vid hennes lägereld. I Azeroths farliga vildmarker är det lika viktigt att kunna ordna en lägerplats och återfå krafterna mellan jakterna som att kunna spåra villebråd."},{t="Vila vid lägerelden",b="En sprakande lägereld ger värme i nattkylan och en stunds lugn där utmattade resenärer kan skaka av sig tröttheten. När äventyrare sitter nära lågorna får de Boosted Rest, som återställer deras energi och gör dem redo för utforskningens vedermödor. Att ta sig tid att sitta vid glöden lär unga äventyrare att tålamod och vila är grundpelare i vildmarksöverlevnad."}},faq={{q="Vem är Lyreena?",a="Lyreena är en erfaren mentor i vildmarken som lär blivande äventyrare och jägare att vila ordentligt och överleva ute i det fria. Hon ger praktiska råd vid sin lägereld.",al={"vem är lyreena","lyreenas lägereld","uppdragsgivare"}},{q="Vad är The Great Outdoors?",a="The Great Outdoors är en grundläggande överlevnadsuppgift i vildmarken där den erfarna friluftskvinnan Lyreena bjuder in jägare att sitta vid hennes lägereld och lära sig att klara sig under långa expeditioner.",al={"vad är the great outdoors","vad är det här för uppdrag","uppdraget the great outdoors"}},{q="Vad är Boosted Rest?",a="När trötta vandrare sätter sig nära en enkel lägereld kan de återhämta sig från resetröttheten och få effekten Boosted Rest, som ger dem ny kraft inför kommande färder.",al={"förstärkningen boosted rest","boosted rest vid lägereld","hur får man boosted rest"}},{q="Varför behöver du vila vid en lägereld?",a="Lägereldar ger välbehövlig värme och vila i den hårda vildmarken. När en äventyrare vilar nära elden kan hen hämta andan, samla tankarna och förbereda sig för farliga färder genom otämjda marker.",al={"lägereldens syfte","varför sitta vid elden","vila vid lägereld"}},{q="Varför är överlevnad i vildmarken viktig för jägare?",a="Jägare tillbringar större delen av livet med att färdas genom avlägsna trakter, långt från värdshus och trygga städer. Grundläggande lägerkunskaper gör att en jägare kan uthärda hårda miljöer utan att duka under av utmattning.",al={"jägarens överlevnadskunskaper","överlevnad i vildmarken","varför jägaruppdrag"}},{q="Vad behöver du göra för att slutföra uppgiften?",a="För att slutföra uppgiften behöver du bara sätta dig nära Lyreenas enkla lägereld och vänta en stund tills värmen ger dig förstärkningen Boosted Rest.",al={"uppdragets mål","hur slutför man the great outdoors","målen för great outdoors"}}},fp="18,266,19.439.0,16.406.0,15.191.0,27.207.0,21.189.0,38.200.0,44.214.0,38.164.0"}
P.entries["quest:96607"] = {n="The Great Outdoors",s="Du lär dig hur vila och förberedelser hjälper dig att överleva utanför stadsmurarna. Resenärer i Azeroth lär nya vandrare att vila vid en lägereld och förbereda sig för vildmarken.",h="Du lär dig hur vila och förberedelser hjälper dig att överleva utanför stadsmurarna.",kw={"äventyraren","boosted rest","lägereld","camping","eleanor shackleton","elwynn forest","sam sarsaparilla","överlevnad","hantverk"},ang={["faction:Alliance"]="I Elwynn Forest lär sig mänskliga resenärer grunderna i överlevnad av erfarna vägfarare innan de möter de hårdare hoten i Westfall och Redridge.",["faction:Horde"]="Över Durotars torra slätter och Mulgore's vindpinade platåer lär Horde-överlevnadsexperter unga krigare att hantera eld och visa disciplin utomhus.",["profession:Cooking"]="Varje vildmarksläger börjar med eld, så matlagning hör naturligt ihop med överlevnad utomhus. Efter den här lektionen visar dina instruktörer dig vidare till matlagningslektioner längs stigen."},sec={{t="Lärdomar från stigen",b="Inte ens ett vasst svärd eller kraftfull magi kan skydda dig från vildmarken om du försummar grunderna i överlevnad. Erfarna vandrare nära vägkanternas gläntor delar denna lärdom med resenärer som lämnar sina hemtrakter. Vila vid en lägereld lindrar ömma fötter, stillar sinnet och gör dig redo för vägen framåt. Regelbunden vila och förberedelser ökar dina chanser att överleva länge nog för att finna rikedom och ära."},{t="Ett hem hemifrån",b="När du förstår värdet av en eld och ordentlig vila visar dina lärare dig till stadens hantverkare. Ett läger i fält behöver mer än en glöd och en sovrulle; överlevnad kräver också praktiska hantverk. Du kan smida ersättningsnitar, laga färdkost eller sy ihop trasig utrustning under stjärnorna. Varje yrke erbjuder lägerutrustning som kan hjälpa dig att förvandla en kal sluttning till en självförsörjande utpost."}},faq={{q="Vem lär nya vandrare detta?",a="Erfarna resenärer lär ut detta, och instruktören beror på var du befinner dig. I Elwynn Forest lär Sam Sarsaparilla ut det; på andra platser ingår Eric Brighthammer, Lyreena Duskblade, Brakk, Eleanor Shackleton, Kaga Wildhoof och Raan Wildwind bland instruktörerna.",al={"vem ger the great outdoors","vem inleder the great outdoors","uppdragsgivare the great outdoors"}},{q="Vad är syftet med att sitta vid lägerelden?",a="När du vilar vid en lägereld kan du hämta andan och få effekten Boosted Rest. En stunds vila i fält hjälper dig att behålla krafterna under långa resor genom vildmarken.",al={"varför sitta vid elden","vad gör lägerelden","effekten boosted rest"}},{q="Vart leder den här träningen härnäst?",a="När du har vilat vid elden skickar din mentor dig till närliggande bosättningar för att lära dig praktiska hantverksfärdigheter. Därefter kan du lära dig Camping 101: Cooking och lägerlektioner i fält som passar yrket du väljer.",al={"vad kommer efter the great outdoors","nästa uppdrag efter the great outdoors","lägeruppdrag"}},{q="Kan Horde-äventyrare också gå den här lektionen?",a="Ja. Överlevnad är viktig för äventyrare från båda fraktionerna. Instruktörer från Alliance och Horde, däribland Brakk, Eleanor Shackleton och Kaga Wildhoof, lär sina noviser samma grundläggande lägerhantverk.",al={"är det här bara för alliance","the great outdoors för horde","kan orcher göra det här uppdraget"}},{q="Varför säger instruktörerna åt dig att prata med hantverkstränare?",a="Överlevnad kräver mer än att sitta vid elden; du behöver också kunna klara dig själv. Hantverkstränare lär dig att tillverka lägerutrustning för ditt yrke, oavsett om du lagar färdkost, lagar rustning eller brygger läkemedel under bar himmel.",al={"varför lära sig yrken","lägerutrustning från hantverkstränare","koppling mellan yrke och läger"}},{q="Vilka tidigare erfarenheter förväntas innan du tar dig an det här uppdraget?",a="Du får vanligtvis den här lektionen efter 'The Adventurer', när du har visat grundläggande ambition och lämnat din startby för att ge dig ut i den större regionen.",al={"förkunskaper för the great outdoors","hur låser jag upp the great outdoors","före the great outdoors"}}},fp="18,164,20.411.0,21.397.0,40.260.0,47.182.0,35.206.0,52.207.0,61.225.0,59.144.0"}
P.entries["quest:96608"] = {n="The Great Outdoors",s="The Great Outdoors introducerar vandrande äventyrare till grunderna i överlevnad i vildmarken och lägerliv. Vid Erics lägereld lär sig resenärer hur de återhämtar sig ordentligt i det fria innan de lär sig yrkesfärdigheter som stödjer deras färder.",h="The Great Outdoors introducerar vandrande äventyrare till grunderna i överlevnad i vildmarken och lägerliv.",kw={"boosted rest","lägeranordning","lägereld","eric","överlevnad","the great outdoors","yrkesfärdighet","vildmark"},ang={["class:Priest"]="Präster finner ofta sin kallelse i heliga helgedomar och kapell, men livet på vägen kräver praktiska överlevnadskunskaper utöver böner och välsignelser."},sec={{t="Vildmarkens lärdomar",b="Att ge sig ut i den vida världen kräver mer än ambition och ett vapen eller en helig symbol. För oerfarna resenärer beror överlevnaden på att veta hur man vilar ordentligt ute i naturen. Vid sin enkla lägereld välkomnar den erfarne resenären Eric vandrande äventyrare att slå sig ner, värma sig vid glöden och upptäcka hur viktig ordentlig vila är innan de tar sig an den otämjda vildmarken."},{t="Från lägereld till hantverk",b="En enkel eld är bara början på att hålla en fungerande lägerplats under långa resor. När resenärer lärt sig grunderna i återhämtning i vildmarken uppmuntras de att besöka tränare i yrkesfärdigheter i närliggande bosättningar. Där lär hantverkare dem att sätta ihop särskilda lägeranordningar, så att äventyrare kan utöva sina yrken och understödja sina expeditioner vart vägen än leder."}},faq={{q="Vem är Eric?",a="Eric är en erfaren friluftsmänniska och äventyrare som erbjuder sig att lära oerfarna resenärer grunderna i att överleva i vildmarken. Han välkomnar resenärer att vila vid sin lägereld och delar med sig av praktiska råd om hur man klarar sig långt från stadsmurarna.",al={"vem ger det här uppdraget","vem är eric","vem lär ut friluftsliv"}},{q="Vad är effekten Boosted Rest?",a="När du vilar vid Erics lägereld får du effekten Boosted Rest, som hjälper utmattade resenärer att återhämta sig och förbereda sig inför prövningarna som väntar. Effekten står för att ta en paus från väder och vind för att återhämta sig ordentligt ute i fält.",al={"vad är boosted rest","hur hjälper lägerelden","viloeffekt vid lägret"}},{q="Vad är lägeranordningar?",a="Lägeranordningar är praktiska konstruktioner eller verktyg som är anpassade för särskilda yrkesfärdigheter och som äventyrare kan sätta upp i vildmarken. Som tränare i yrkesfärdigheter i närliggande bosättningar förklarar, kan hantverkare sätta upp arbetsplatser vid sina läger när de lärt sig ett yrke.",al={"vad är lägeranordningar","yrkesanordningar","lägerföremål för yrke"}},{q="Varför behöver du sitta nära Erics lägereld?",a="När äventyrare slår sig ner vid lägerelden kan de ta en paus, värma sig och lyssna på Erics råd om överlevnad i vildmarken. Kroppen får då tid att slappna av och dra full nytta av skyddet som vilan utomhus ger.",al={"varför sitta vid elden","sitta nära lägerelden","lägereldens mål"}},{q="Vart ska en äventyrare gå efter den här lektionen?",a="När grunderna i att vila vid läger är avklarade föreslår Eric att du beger dig till den närliggande byn för att lära dig en yrkesfärdighet av lokala hantverkstränare. När du blivit tränad kan du börja lära dig hur du bygger lägeranordningar som passar ditt hantverk.",al={"vad göra efteråt","vart härnäst","efter the great outdoors"}},{q="Vem är den här överlevnadslektionen avsedd för?",a="Eric ropar till äventyrare som passerar och lägger märke till deras rastlösa sinnelag och vilja att söka rikedom och ära ute i världen. Hans råd om vildmarken kan hjälpa alla som lämnar tryggheten och ger sig ut i det fria.",al={"vem kan göra det här uppdraget","bara präster","är det här för äventyrare"}}},fp="18,255,19.391.0,22.411.0,12.250.0,30.227.0,23.266.0,44.212.0,59.230.0,41.227.0"}
P.entries["quest:96626"] = {n="Camping 101: Cooking",s="Camping 101: Cooking lär blivande äventyrare att matlagning är grundstenen för att slå läger i vildmarken. Hos Cook Tomas i Goldshire lär sig resenärer att göra upp lägereldar och slå upp egna läger i vildmarken.",h="Camping 101: Cooking lär blivande äventyrare att matlagning är grundstenen för att slå läger i vildmarken.",kw={"lägereld","camping","camping 101: cooking","lägerplats","matlagning","möbler","goldshire","tomas"},ang={["faction:Alliance"]="Nybörjare bland Alliansens äventyrare i Elwynn Forest hänvisas till Cook Tomas på Lion's Pride Inn i Goldshire för att lära sig grunderna i matlagning och att göra upp lägereldar.",["profession:Cooking"]="Matlagning är en viktig grund för att överleva i vildmarken. Den ger äventyrare färdigheten att göra enkla lägereldar som blir mittpunkten på deras lägerplatser."},sec={{t="Eldstaden i vildmarken",b="För äventyrare som trotsar Azeroths vildmarker börjar lägerlivet med en pålitlig eld. Uppdraget Camping 101: Cooking lär nybörjare att matlagning inte bara handlar om att laga varm mat, utan är en livsviktig grund för att överleva i vildmarken. När resenärer bemästrar matlagning lär de sig att göra upp en ordentlig lägereld och förvandla en otämjd glänta till en trygg tillflykt."},{t="Undervisning i Goldshire",b="Nya resenärer i Elwynn Forest får uppsöka Cook Tomas i Goldshire för att lära sig grunderna. Efter hans undervisning kan äventyrarna slå upp enkla läger i vildmarken. De första lägren är enkla och har få möbler, men när du blir bättre på matlagning kan du göra större eldar. Andra hantverksyrken ger fler sätt att inreda och anpassa lägerplatsen."}},faq={{q="Vad är uppdraget Camping 101: Cooking?",a="Camping 101: Cooking introducerar äventyrare till grunderna i att överleva i vildmarken. Uppdraget vägleder dig till matlagningsyrket och lär dig att tända en enkel lägereld som blir mittpunkten på din lägerplats ute i vildmarken.",al={"vad är camping 101 cooking","vad lär camping 101 ut","syftet med camping 101"}},{q="Vem är Tomas och var hittar man honom?",a="Tomas är kocken som tränar matlagning i Goldshire i Elwynn Forest. Han håller till på Lion's Pride Inn och lär blivande äventyrare grunderna i matlagning och konsten att tända en lägereld.",al={"vem är tomas","var finns tomas","tomas goldshire"}},{q="Varför krävs matlagning för att slå läger?",a="En lägereld är grunden för varje läger i vildmarken. När du lär dig matlagning får du kunskapen som krävs för att göra upp en eld, där en äventyrare kan vila och ställa ut lägermöbler.",al={"varför behöver jag matlagning för att campa","krävs matlagning för att slå läger","sambandet mellan matlagning och lägereldar"}},{q="Kan man göra större lägereldar när färdigheten förbättras?",a="När du blir bättre på matlagning kan du bygga större och stadigare eldar. I takt med att din matlagningsfärdighet utvecklas blir lägerelden en mer rejäl bas för upptäcktsfärder i vildmarken.",al={"hur uppgraderar man lägerelden","kan jag bygga större lägereldar","större eldar med matlagning"}},{q="Hur skaffar man möbler till lägerplatsen?",a="Utöver matlagning kan du lära dig att tillverka fler lägermöbler av tränare i andra hantverksyrken runt om i världen. Äventyrare med olika hantverksfärdigheter kan skapa föremål som pryder och förbättrar lägren i vildmarken.",al={"hur skaffar man lägermöbler","var kommer lägermöbler ifrån","tillverka lägerföremål"}},{q="Var kan en äventyrare slå läger?",a="När du har bemästrat grunderna i matlagning och att göra upp lägereldar kan du slå läger ute i vildmarken. De första lägerplatserna är dock enkla och rymmer bara några få möbler tills du utvecklar dina färdigheter.",al={"kan jag slå läger var som helst","regler för att slå läger i vildmarken","begränsningar för lägerplatser"}}},fp="20,267,22.409.0,24.423.0,39.254.0,39.203.0,48.210.0,53.190.0,49.228.0,36.245.0"}
P.entries["quest:96627"] = {n="The Adventurer",s="I Northshire Valley skickar Marshal McBride The Adventurer mot Goldshire för att hitta Sam Sarsaparilla. Du har visat din skicklighet när du försvarade klostret, och McBride vill att du undersöker nykomlingen.",h="I Northshire Valley skickar Marshal McBride The Adventurer mot Goldshire för att hitta Sam Sarsaparilla.",kw={"elwynn forest","goldshire","marshal mcbride","northshire","sam sarsaparilla","the adventurer"},ang={["faction:Alliance"]="För nya rekryter i Alliansen som avslutar sin tjänst i Northshire är detta det första officiella steget ut i Elwynn Forests vidare rike.",["race:Human"]="Som mänsklig försvarare som lämnar Northshire Abbey tar du dina första steg mot Goldshire, Elwynns hjärta."},sec={{t="Lämnar dalen",b="När hoten från de lokala Defias och skadedjuren avtar riktar Marshal McBride uppmärksamheten mot vägen bortom Northshire Valley. Stormwinds ordinarie styrkor är hårt ansträngda över hela kungariket, så den lokala garnisonen förlitar sig på lovande kämpar för att hålla uppsikt över resenärer och vandrare i de omgivande skogarna."},{t="En märklig nykomling",b="Marshal McBride ber dig hålla ett öga på Sam Sarsaparilla, en nykomling som setts nära Goldshire. Det är en ovanlig begäran, ingen militär order eller prisjakt, och den för dig från Northshires avskilda dal till Elwynn Forests vidsträckta vildmarker."}},faq={{q="Vem skickar mig på det här uppdraget?",a="Marshal McBride, befälhavare för Stormwinds garnison i Northshire Valley, skickar dig när du har bevisat ditt mod genom att försvara klostret.",al={"uppdragsgivare","vem ger äventyraren uppdraget","marshal mcbrides uppdrag"}},{q="Vem är Sam Sarsaparilla?",a="Sam Sarsaparilla är en äventyrare nära vägen vid Goldshire. Marshal McBride har hört att han är där och ber dig ta reda på vad han gör.",al={"sam sarsaparilla","vem är sam","äventyrare i goldshire"}},{q="Var hittar jag Sam Sarsaparilla?",a="Sam Sarsaparilla finns längs huvudvägen söderut från Northshire mot Goldshire i Elwynn Forest.",al={"sam sarsaparillas plats","var är sam","hitta sam sarsaparilla"}},{q="Varför bryr sig Marshal McBride om en vanlig äventyrare?",a="Northshire är fortfarande på sin vakt mot banditer och inkräktare. McBride håller uppsikt över obekanta legoknektar och vandrare som passerar, och litar på pålitliga lokalbor för att ta den första kontakten.",al={"varför skicka mig","mcbrides motiv","varför leta efter sam"}},{q="Måste jag lämna Northshire Valley för att slutföra detta?",a="Ja. Du lämnar Northshire Valley genom dess södra portar och följer skogsvägen mot Goldshire.",al={"utanför northshire","lämnar detta northshire","ta sig till goldshire"}},{q="Är detta en del av Stormwinds vanliga militära befälsordning?",a="Marshal McBride är en officer i Stormwind, men han kallar detta ett ovanligt uppdrag snarare än vanlig vakttjänst. Han förlitar sig på ditt omdöme som en självständig beskyddare, utanför den formella militära ordningen.",al={"stormwinds militär","är detta vanlig tjänstgöring","officiellt ärende"}}},fx={dd262048={q="Varför väljer Marshal McBride mig att undersöka Sam?",a="Marshal McBride ser det här som ett ovanligt uppdrag, inte som vanlig garnisonstjänst. Han har sett hur du hanterar hoten i Northshire och betraktar dig som en duglig beskyddare som kan verka obemärkt utanför klostrets portar. Hans garnison är redan hårt ansatt av lokala problem. Därför är det klokare att skicka en betrodd rekryt för att undersöka ryktena längs vägen än att skicka vanliga vakter.",al={"varför jag åt marshal mcbride","varför skickar mcbride mig","varför inte skicka en vakt till sam"}}},fp="14,197,18.299.0,18.244.0,26.131.0,24.138.0,33.96.0,56.182.0,52.104.0,63.202.0"}
P.entries["quest:96628"] = {n="The Adventurer",s="The Adventurer är ett lokalt ärende som Mountaineer Thalos ger vid Dun Moroghs södra port. Innan han skickar resenärer genom bergstunneln mot Kharanos ber Thalos dem bära ett paket med förnödenheter till Eric Brighthammer, en nykomling som slagit läger strax utanför byn.",h="The Adventurer är ett lokalt ärende som Mountaineer Thalos ger vid Dun Moroghs södra port.",kw={"coldridge pass","dun morogh","eric brighthammer","kharanos","mountaineer thalos","supply bundle","the adventurer"},ang={["faction:Alliance"]="Mountaineers förlitar sig på rekryter från Alliance för att föra viktig proviant längs de isiga vägarna och se till att allierade som strövar omkring utanför Kharanos har förnödenheter.",["race:Dwarf"]="För unga dvärgar som lämnar Coldridge Valley blir det en första gemensam insats med Mountaineers i det större Dun Morogh att föra proviant till Eric Brighthammer."},sec={{t="En tjänst åt Mountaineers",b="Att bevaka de höga passen och tunnlarna mellan Coldridge Valley och Dun Moroghs vidsträckta snömarker är krävande arbete för Ironforge Mountaineers. Mountaineer Thalos är stationerad vid gränsporten och håller utkik efter både lokala faror och resenärer som färdas längs den upptrampade stigen. När posten får höra att en ensam äventyrare anlänt nära Kharanos låter Thalos betrodda förbipasserande föra vidare nödvändiga förnödenheter till nykomlingar som ger sig in bland de frusna klipporna."},{t="Förnödenheter till Kharanos",b="Vägen som leder ner från det södra passet slingrar sig in i bosättningen Kharanos, det främsta navet för dvärgarnas hantverk och resor i centrala Dun Morogh. Eric Brighthammer har nyligen slagit sig ner strax utanför byn. Genom att leverera Mountaineers förnödenhetspaket till honom hjälper resenärer till att upprätta en viktig förbindelse mellan vaktposterna på de avlägsna bergsryggarna och dem som rör sig ute i vildmarken."}},faq={{q="Vem ger uppdraget The Adventurer?",a="Mountaineer Thalos erbjuder uppdraget. Han står vakt vid bergspassets port som förbinder stigen genom Coldridge Valley med resten av Dun Morogh.",al={"uppdragsgivare","vem ger the adventurer","thalos uppdrag"}},{q="Vem är Eric Brighthammer?",a="Eric Brighthammer är en äventyrare som nyligen anlänt till platsen utanför dvärgstaden Kharanos. Mountaineer Thalos skickar resenärer för att ge honom ett nödvändigt paket med förnödenheter.",al={"var är eric brighthammer","vem är the adventurer","brighthammer"}},{q="Var sker leveransen?",a="Leveransen sker strax utanför Kharanos i Dun Morogh, norr om tunneln vid Coldridge Pass där Mountaineer Thalos är stationerad.",al={"var lämnar man förnödenheter","eric brighthammers plats","var hittar man supply bundle"}},{q="Varför skickar Mountaineer Thalos förnödenheter?",a="Mountaineers håller uppsikt över resenärer i hela Dun Morogh. När Thalos får veta att en äventyrare slagit läger nära Kharanos ordnar han så att förnödenheter förs dit för att hjälpa honom i kylan.",al={"varför skicka förnödenheter","thalos syfte","orsak till paketet"}},{q="Vilket föremål bär du?",a="Du bär ett Supply Bundle som Mountaineer Thalos själv har gett dig, för att lämna till Eric Brighthammer.",al={"vilka förnödenheter","föremålet supply bundle"}},{q="Är uppdraget tillgängligt för Horde-spelare?",a="Nej. Mountaineer Thalos är en dvärgisk vakt i Dun Morogh som tillhör Alliance, så uppdraget är endast tillgängligt för Alliance.",al={"kan horde göra detta","är det bara för alliance","horde-uppdraget the adventurer"}}},fx={["95095969"]={q="Varför ber Mountaineer Thalos dig att leverera förnödenheterna?",a="Mountaineer Thalos och hans patrull är stationerade vid passet för att hålla vägen under uppsikt och skydda tunneln mot lokala faror. Eftersom du ändå ska vidare genom passet mot Kharanos ber han dig ta med leveransen längs vägen, i stället för att dra bort bergsvakterna från deras poster.",al={"varför jag, the adventurer","varför behöver thalos mig","varför skicka spelaren till eric brighthammer"}}},fp="14,279,28.484.0,21.418.0,36.140.0,25.178.0,36.132.0,43.199.0,27.102.0,41.118.0"}
P.entries["quest:96629"] = {n="Camping 101: Cooking",s="Camping 101: Cooking lär äventyrare i Dun Morogh den viktiga överlevnadskonsten matlagning. Förutom att laga färdkost gör denna färdighet det möjligt för resenärer att tända lägereldar som utgör grunden för läger ute i vildmarken.",h="Camping 101: Cooking lär äventyrare i Dun Morogh den viktiga överlevnadskonsten matlagning.",kw={"lägereld","lägerliv","matlagning","dun morogh","möbler","gremlock pilsnor","kharanos","vildmark"},ang={["class:Priest"]="Även andliga utövare som vigt sig åt Ljuset måste behärska grundläggande överlevnadskunskaper som att göra upp eld när de reser långt från tempel och bosättningar.",["faction:Alliance"]="Alliansens äventyrare som börjar nära Dun Morogh lär sig grunderna i vildmarksliv och matlagning av dvärglärarna i Kharanos.",["profession:Cooking"]="Matlagning ger den grundläggande lägereld som behövs för att slå läger i vildmarken och placera ut lägermöbler."},sec={{t="Eldstaden i vildmarken",b="För varje resenär som vågar sig ut i vildmarken börjar ett tryggt läger med en låga. I Dun Morogh hänvisas nybörjare till Kharanos, där de får lära sig grunderna i matlagning av Gremlock Pilsnor. Matlagning handlar inte bara om att hålla sig mätt med varm mat längs vägen. En stadig lägereld är själva ankaret för varje läger i det fria."},{t="Utöka lägret",b="När du lärt dig att göra upp en lägereld kan du slå upp ett enkelt läger var som helst ute i vildmarken. En enkel eld ger bara plats för ett fåtal möbler, men högre matlagningsskicklighet låter dig bygga större brasor. Hantverkare med kunskaper i andra yrken kan dessutom tillverka fler möbler och förvandla ett enkelt rastställe till ett fullt utrustat läger."}},faq={{q="Vad är uppdraget Camping 101: Cooking?",a="Camping 101: Cooking är ett utbildningsuppdrag som lär äventyrare det grundläggande hantverket matlagning, en hörnsten i överlevnad och lägerliv i vildmarken.",al={"vad är camping 101 cooking","uppdragets syfte","grunderna i lägermatlagning"}},{q="Vem är Gremlock Pilsnor?",a="Gremlock Pilsnor är den lokala matlagningstränaren i Kharanos i Dun Morogh. Han lär nybörjare att laga mat och göra upp lägereldar.",al={"vem lär ut matlagning i kharanos","gremlock pilsnors plats","matlagningstränare i dun morogh"}},{q="Varför behövs matlagning för att slå läger?",a="Matlagning låter äventyrare göra upp en enkel lägereld, som utgör grunden för ett läger i vildmarken och för att placera möbler runt elden.",al={"varför behövs matlagning för att slå läger","lägereldens syfte","matlagning och läger"}},{q="Var kan man slå upp ett läger?",a="När du vet hur man gör upp en eld kan du slå upp ett enkelt läger ute i vildmarken och få en viloplats under dina resor.",al={"var kan jag slå upp ett läger","regler för lägerplatser","slå upp läger"}},{q="Hur förbättrar eller utökar man ett läger?",a="När du höjer din matlagningsskicklighet kan du bygga större lägereldar. Om du lär dig andra hantverksyrken kan du tillverka och placera ut fler möbler till lägret.",al={"hur uppgraderar man en lägerplats","större eldar","fler lägerdekorationer"}},{q="Kan andra yrken bidra till lägerlivet?",a="Tränare i andra hantverksyrken kan lära dig grunderna i att tillverka möbler till lägret, om du behärskar deras respektive yrken.",al={"vem erbjuder lägermöbler","hantverksföremål till läger","andra lägertränare"}}},fp="20,242,22.367.0,22.396.0,39.166.0,24.141.0,37.157.0,36.136.0,40.165.0,44.140.0"}
P.entries["quest:96630"] = {n="The Adventurer",s="The Adventurer är ett kort uppdrag i Teldrassil där du hittar en bortkastad dagbok ute i vildmarken. Den enkla anteckningsboken skildrar en okänd resenärs anspråkslösa färder och campingturer och ska lämnas till Lyreena Duskblade nära Dolanaar.",h="The Adventurer är ett kort uppdrag i Teldrassil där du hittar en bortkastad dagbok ute i vildmarken.",kw={"camping","dolanaar","dagbok","förlorad dagbok","lyreena duskblade","teldrassil","the adventurer"},ang={["faction:Alliance"]="För nybörjare i Alliance som hittar sin väg under World Tree hjälper det till att hålla ordning i lundarna att återlämna borttappade tillhörigheter till andra resenärer.",["race:NightElf"]="Unga Night Elves som patrullerar Teldrassil hittar ofta spår av resenärer som passerat och lämnar förlorade personliga minnessaker till vandrare som Lyreena Duskblade."},sec={{t="En vandrarens dagbok",b="Bland Teldrassils täta grenar och snåriga rötter stöter resenärer ibland på övergivna personliga tillhörigheter. Den här enkla dagboken berättar om en namnlös äventyrares anspråkslösa men uppriktiga strövtåg. I stället för storslagna hjältedåd eller farliga monsterjakter skildrar de flesta sidor entusiastiskt den enkla glädjen i att slå läger under skymningshimlen."},{t="Lämna den i Dolanaar",b="I stället för att låta den personliga minnessaken ligga kvar och vittra i den fuktiga vildmarken känner upphittaren sig manad att bära den mot Dolanaar. Lyreena Duskblade, som håller till nära Night Elf-bosättningen, ska ta emot de förlorade sidorna och kanske ge klarhet eller insikt i vems färder de skildrar."}},faq={{q="Vad är det för dagbok som nämns i uppdraget?",a="Det är en enkel personlig anteckningsbok som hittats ute i Teldrassils vildmark. Den beskriver en okänd persons stillsamma liv och resor, med fokus på vardagliga äventyr och en varaktig förkärlek för camping utomhus.",al={"förlorad dagbok","vad är boken","the adventurer-dagboken"}},{q="Vem är Lyreena Duskblade?",a="Lyreena Duskblade är en Night Elf som finns nära Dolanaar. Hon är den avsedda mottagaren av den förlorade dagboken som hittades ute i skogen.",al={"lyreena","var finns lyreena duskblade","inlämningsfigur"}},{q="Var utspelar sig uppdraget?",a="Uppdraget utspelar sig i Teldrassil, Night Elves väldiga grenverk, och kretsar kring vildmarken runt byn Dolanaar.",al={"var finns uppdraget the adventurer","uppdragsområde"}},{q="Beskriver dagboken farliga monster eller strider?",a="Nej. Texten beskrivs som ganska enkel och fokuserar på en okänd persons anspråkslösa liv och strövtåg, särskilt på hur trevligt det kan vara att campa.",al={"dagbokens berättelse","vad finns i dagboken","vad står det"}},{q="Vem kan utföra uppgiften?",a="Uppgiften är bara för medlemmar i Alliance som vandrar genom Teldrassils startområde, särskilt nybörjare bland Night Elves som ger sig ut nära Dolanaar.",al={"kan horden göra detta","uppdrag för alliance"}},{q="Varför lämna dagboken i Dolanaar?",a="Dolanaar är den centrala samlingsplatsen och vägkorsningen i den här delen av Teldrassil, så det är den mest rimliga platsen att lämna borttappade personliga tillhörigheter. Lyreena Duskblade väntar i närheten för att ta emot dagboken.",al={"varför dolanaar","varför lyreena"}}},fp="14,161,20.169.0,20.158.0,43.152.0,25.86.0,33.71.0,56.125.0,27.100.0,36.135.0"}
P.entries["quest:96634"] = {n="Camping 101: Cooking",s="Camping 101: Cooking är ett introduktionsuppdrag där äventyrare får lära sig grunderna i att laga mat under vildmarkscamping. Genom att lära sig tända en lägereld av lokala instruktörer som Zarrin i Dolanaar får resenärer den grund som krävs för att slå läger i vildmarken. Det är första steget mot att bemästra överlevnad utomhus och utrusta en egen lägerplats.",h="Camping 101: Cooking är ett introduktionsuppdrag där äventyrare får lära sig grunderna i att laga mat under...",kw={"lägereld","camping 101","lägerplats","matlagning","dolanaar","möbler","överlevnad i vildmarken","zarrin"},ang={["profession:Cooking"]="Matlagning är grunden för överlevnad i vildmarken och ger dig lägerelden som behövs för varje läger utomhus. När äventyrare utvecklar sina matlagningskunskaper kan de göra större och tåligare lägereldar.",["race:NightElf"]="Nybörjare bland Night Elf-äventyrare som passerar genom Dolanaar lär sig ofta grunderna i vildmarkskunskap och att göra upp eld av Zarrin, innan de ger sig djupare in i Teldassils vildmarker."},sec={{t="Vildmarkens härd",b="Varje lång färd genom vildmarken börjar med förmågan att göra upp en varm eld. I Camping 101: Cooking får blivande äventyrare rådet att söka upp en matlagningsinstruktör som sin första lektion i vildmarkskunskap. Att lära sig laga mat handlar om mer än att tillreda viltkött; grundkunskapen att tända en enkel lägereld är själva grunden för varje läger utomhus. Utan en eld som håller kylan borta och skingrar mörkret går det inte att slå upp ett tryggt läger i vildmarken."},{t="Utöka lägerplatsen",b="När du lär dig att tända en enkel lägereld kan du slå upp små läger ute i vildmarken. Ett nybörjarläger rymmer bara några få enkla möbler, men hängivna äventyrare kan utöka sina möjligheter. När en äventyrare utvecklar sin matlagningsskicklighet låser de upp sätt att tända större och stadigvarande eldar. Hantverkare som behärskar andra yrken kan dessutom vända sig till sina instruktörer för att lära sig tillverka möbler och uppgraderingar till lägret."}},faq={{q="Vad är syftet med Camping 101: Cooking?",a="Camping 101: Cooking introducerar äventyrare till grunderna i överlevnad i vildmarken genom att visa dem hur de lär sig matlagningsyrket. En lägereld är grunden för att slå upp ett läger var som helst i vildmarken.",al={"vad gör det här uppdraget","syftet med camping 101 cooking","varför göra camping 101"}},{q="Vem är Zarrin?",a="Zarrin är en matlagningsinstruktör i Dolanaar på Teldrassil. Han lär nybörjaräventyrare matlagningens grunder och hur man gör upp en enkel lägereld.",al={"vem är zarrin","zarrin dolanaar","var finns matlagningsinstruktören i dolanaar"}},{q="Hur slår du upp ett läger i vildmarken?",a="Du börjar med att göra upp en enkel lägereld, som du lär dig att tända genom matlagningsyrket. Grundläggande träning låter dig slå läger i vildmarken med enkla möbler, medan du med förbättrade färdigheter kan göra större eldar och fler förbättringar av lägerplatsen.",al={"hur bygger man ett läger","hur fungerar camping","att slå upp ett läger"}},{q="Kan du lägga till möbler på din lägerplats?",a="Matlagningen ger dig lägerelden som utgör grunden för lägerplatsen. Instruktörer i andra hantverksyrken runtom i Azeroth kan lära skickliga hantverkare att möblera och uppgradera sina lägerplatser med specialutrustning och dekorationer.",al={"möblera lägerplats","lägerdekorationer","lägermöbler från andra yrken"}},{q="Varför krävs matlagning för att campa?",a="Matlagning lär äventyrare att göra upp och sköta en öppen lägereld ute i vildmarken. Eftersom elden är lägrets självklara mittpunkt är matlagning det första steget mot att slå läger i vildmarken.",al={"varför behövs matlagning för camping","sambandet mellan matlagning och camping"}},{q="Kan du göra större lägereldar?",a="Ja. När du övar på matlagning och höjer din matlagningsskicklighet kan du lära dig att göra större eldar som bättre passar läger i vildmarken.",al={"kan jag göra större lägereldar","hur uppgraderar man lägerelden"}}},fp="20,384,22.515.0,22.504.0,44.234.0,14.159.0,44.272.0,41.214.0,36.228.0,30.155.0"}
P.entries["quest:96638"] = {n="The Adventurer",s="\"The Adventurer\" är ett introduktionsuppdrag på Zephras Isle. Aetheen of the Gales ger det i Thendal Grove och skickar nyblivna vandrare sydväst mot Shen'dar Village för att möta Raan Wildwind, en erfaren lägerbyggare som känner vildmarken.",h="\"The Adventurer\" är ett introduktionsuppdrag på Zephras Isle.",kw={"aetheen of the gales","raan wildwind","shen'dar village","the adventurer","thendal grove","zephras isle"},ang={["race:Skyborne"]="För unga Skyborne som lämnar Thendal Groves skyddande trädkrona markerar mötet med Raan Wildwind det första verkliga steget ut i den större, otämjda ön de kallar sitt hem."},sec={{t="Lämna lunden",b="Thendal Grove erbjuder skydd och en stillsam fristad, men de vidsträckta delarna av Zephras Isle är fortfarande vilda och farliga. Aetheen of the Gales vakar över invånarna och märker när en blivande resenär är redo att lämna de välbekanta gränserna. För den som söker berömmelse, rikedom eller ett syfte räcker det inte längre att stanna inom lundens skyddade gränser."},{t="En vägvisare på vägen",b="Sydväst om lunden, längs vägen mot Shen'dar Village, har en annan resenär redan slagit läger. Raan Wildwind har tillbringat tid med att navigera bland farorna utanför den trygga fristaden. Den som söker upp honom får en praktisk introduktion till hur man överlever bortom Thendal Grove, med lärdomar från någon som redan har trotsat de öppna stigarna."}},faq={{q="Vem skickar dig för att hitta Raan Wildwind?",a="Aetheen of the Gales ger uppdraget i Thendal Grove. När du har visat vad du går för i skogarna runtomkring uppmuntrar hon dig att söka upp någon med egen erfarenhet av den större ön.",al={"vem ger the adventurer","vem startar uppdraget the adventurer","aetheen-uppdrag"}},{q="Var finns Raan Wildwind?",a="Raan Wildwind har slagit läger sydväst om Thendal Grove, precis vid huvudvägen mot Shen'dar Village.",al={"raan wildwinds plats","var är raan","hur hittar man raan wildwind"}},{q="Vad är syftet med uppgiften?",a="Den fungerar som en vägvisare som leder resenärer ut ur den trygga fristaden Thendal Grove och sammanför dem med mentorer och utmaningar längre in på Zephras Isle.",al={"varför göra the adventurer","syftet med uppdraget the adventurer","vad lär raan ut"}},{q="Vilket förhandskrav måste uppfyllas innan du får uppdraget?",a="Du måste slutföra uppgiften som gäller Foul Matriarch åt Aetheen of the Gales innan hon visar dig vägen till Raan Wildwind.",al={"förhandskrav för the adventurer","krav för the adventurer"}},{q="Är Shen'dar Village tryggt för resenärer?",a="Shen'dar Village ligger strax bortom Raans läger, vid slutet av vägen sydväst om Thendal Grove. Byn är en betydande bosättning på ön, men unga äventyrare måste vara försiktiga på vägarna och i vildmarken runtomkring.",al={"är shen'dar tryggt","vad är shen'dar village"}},{q="Vem är Raan Wildwind?",a="Raan Wildwind är en äventyrlig vandrare som gav sig bortom Thendal Grove och slog läger utanför Shen'dar Village. Han ger råd och uppgifter till nykomlingar som följer vägen.",al={"raan wildwind-lore","vem är raan wildwind"}}},fx={dc12ab9c={q="Varför skickar Aetheen of the Gales dig för att hitta Raan Wildwind?",a="Aetheen ser att allt fler vandrare ger sig bortom tryggheten i Thendal Grove i jakt på ära och rikedom. Vildmarken är farlig för den oerfarne, så Aetheen vill att du söker upp Raan Wildwind, en medresenär som slagit läger nära Shen'dar Village. Där kan du få praktiska råd och lära dig överleva, så att du klarar dig under dina resor över ön.",al={"varför skickar aetheen dig","aetheen of the gales motiv","varför träffa raan wildwind"}}},fp="14,245,17.355.0,19.347.0,36.193.0,31.125.0,33.169.0,64.136.0,39.226.0,21.182.0"}
P.entries["quest:96646"] = {n="Camping 101: Cooking",s="Camping 101: Cooking är ett introduktionsuppdrag som lär äventyrare kokkonsten, en viktig grund för att överleva i vildmarken. När resenärer lär sig tända en lägereld av Zerril Softbreeze i Shen'dar Village får de möjlighet att slå upp egna läger i det vilda.",h="Camping 101: Cooking är ett introduktionsuppdrag som lär äventyrare kokkonsten, en viktig grund för att...",kw={"lägereld","camping","lägerplats","matlagning","möbler","shen'dar village","zerril softbreeze"},ang={["profession:Cooking"]="Grundläggande matlagningskunskaper ger den kunskap som behövs för att göra upp en lägereld, lägrets centrala punkt i vildmarken."},sec={{t="Vildmarkens härd",b="För äventyrare som färdas genom otämjda marker börjar överlevnadskunskap med härden. Camping 101: Cooking introducerar vandringsmän till kokkonsten, inte bara för att laga mat, utan också för att kunskapen att göra upp en enkel eld är det första viktiga steget mot en trygg viloplats i vildmarken."},{t="Lägrets grunder",b="Blivande lägerresenärer hänvisas till Zerril Softbreeze i Shen'dar Village för att lära sig grunderna i matlagning. När en äventyrare väl förstår hur man tänder en lägereld kan hen slå upp ett litet läger var som helst i vildmarken. Enkla läger har bara plats för få möbler, men med bättre färdigheter kan man göra större eldar och skapa rikare lägerplatser med hjälp av andra hantverksyrken."}},faq={{q="Vad är Camping 101: Cooking?",a="Det är en introduktion till överlevnad i vildmarken, där äventyrare lär sig hur matlagning och enkla lägereldar utgör grunden för att slå upp ett läger.",al={"vad är camping 101 cooking","camping cooking-uppdrag"}},{q="Vem är Zerril Softbreeze?",a="Zerril Softbreeze är en matlagningstränare i Shen'dar Village som lär nybörjare grunderna i matlagning och hur man tänder en lägereld.",al={"vem är zerril softbreeze","matlagningstränare shen'dar"}},{q="Varför behövs matlagning för att slå läger?",a="Matlagning lär äventyrare att göra upp och underhålla en lägereld, som utgör grunden för varje läger i vildmarken.",al={"varför lära sig matlagning för camping","varför behövs matlagning för läger"}},{q="Var finns Zerril Softbreeze?",a="Zerril Softbreeze finns i Shen'dar Village, där hen lär ut hantverksyrken.",al={"var finns zerril softbreeze","shen'dar village plats"}},{q="Hur kan man möblera ett läger?",a="Nybörjare kan placera ut enkla möbler kring lägerelden, men äventyrare kan lära sig hantverksyrken av andra tränare för att tillverka och sätta upp fler saker i lägret.",al={"lägermöbler","hur möblerar man ett läger"}},{q="Kan lägereldar uppgraderas?",a="När du förbättrar din matlagningsfärdighet kan du lära dig att tända ännu större lägereldar och förbättra dina läger i vildmarken.",al={"större lägereldar","uppgradera läger"}}},fp="20,284,22.312.0,27.442.0,29.173.0,25.145.0,41.152.0,35.76.0,31.183.0,26.116.0"}
P.entries["quest:96652"] = {n="The Adventurer",s="I Durotar hittar The Adventurer en borttappad dagbok bland de röda ödemarkerna. Sidorna berättar om stillsamma resor och nätter under stjärnorna, och den är avsedd för Brakk nära Razor Hill.",h="I Durotar hittar The Adventurer en borttappad dagbok bland de röda ödemarkerna.",kw={"äventyrare","brakk","lägerliv","durotar","dagbok","förlorad dagbok","razor hill"},ang={["class:Hunter"]="Som hunter vet du hur man lever av naturen, och dagbokens kärleksfulla noteringar om att slå läger i vildmarken kan kännas bekanta.",["faction:Horde"]="Många nya rekryter vandrar längs Durotars torra stigar. Att återlämna borttappade tillhörigheter till vandrare som Brakk nära Razor Hill hjälper till att upprätthålla ordningen längs den centrala gränsen."},sec={{t="En vandrings anteckningar",b="En borttappad dagbok ligger i Durotars röda jord, långt från de blodiga strider och storslagna fälttåg som präglar landet. Den okända skribenten fyller sidorna med vardagliga resor och den enkla glädjen i att slå läger under bar himmel. Boken ger en stillsam inblick i livet på vägarna genom ett hårt land."},{t="Överlämning till Brakk",b="Dagboken är avsedd för Brakk, en äventyrare som slagit läger nära Razor Hill. Sidorna knyter en okänd resenär till någon som håller uppsikt över de dammiga vägarna, och att bära den till Brakk kan hjälpa till att bevara minnet av skribentens resor."}},faq={{q="Vad finns i den förlorade dagboken?",a="Dagboken innehåller vardagliga anteckningar om en obemärkt äventyrares resor, med återkommande kärleksfulla noteringar om att slå läger i vildmarken.",al={"vad står det i dagboken","innehållet i den förlorade dagboken","dagbokstext"}},{q="Vem skrev dagboken?",a="De återfunna sidorna nämner inte författaren. De beskriver en okänd äventyrares liv och resor.",al={"vem är äventyraren","författaren till den förlorade dagboken","vem skrev den här boken"}},{q="Vem är Brakk?",a="Brakk är en äventyrare som slagit läger nära Razor Hill i centrala Durotar, och dagboken är avsedd för honom.",al={"brakk razor hill","vem är brakk","var finns brakk"}},{q="Var hittas dagboken?",a="Dagboken ligger övergiven i Durotars röda jord, där en förbipasserande resenär från Horde kan hitta den.",al={"var hittar jag dagboken","den förlorade dagbokens plats","äventyrarens uppdragsstart"}},{q="Varför bryr sig Brakk om dagboken?",a="Dagboken ger ingen anledning till att Brakk skulle bry sig om den. Han är en äventyrare som slagit läger strax utanför Razor Hill och lär nykomlingar grunderna i att slå läger, och dagbokens berättelser handlar om lägerliv.",al={"varför lämna den till brakk","brakks syfte","brakk dagbok"}},{q="Är äventyraren som skrev dagboken i fara?",a="Sidorna ger inga tecken på något fult spel och minns lägerlivet med värme. Skribenten kan ha tappat dagboken av misstag eller oväntat gett sig av.",al={"lever författaren","dog äventyraren","den förlorade äventyrarens öde"}}},fp="14,174,18.307.0,17.216.0,32.133.0,22.102.0,13.99.0,27.98.0,39.196.0,41.146.0"}
P.entries["quest:96655"] = {n="Camping 101: Cooking",s="Camping 101: Cooking lär äventyrare den grundläggande överlevnadskonsten i vildmarken. Genom att visa resenärer vägen till Cook Torka i Razor Hill lär uppdraget ut grunderna i matlagning och att göra upp lägereldar, så att de kan slå läger ute i vildmarken.",h="Camping 101: Cooking lär äventyrare den grundläggande överlevnadskonsten i vildmarken.",kw={"lägereld","camping 101","camping 101: cooking","lägerplats","cook torka","matlagning","durotar","inredning","razor hill"},ang={["faction:Horde"]="Äventyrare som börjar sin färd i Durotar kan bege sig till Cook Torka i Razor Hill för att lära sig matlagningens grunder.",["profession:Cooking"]="Matlagning är grundkravet för att bygga en enkel lägereld och utgör den oumbärliga grunden för överlevnad och lägerliv i vildmarken."},sec={{t="Vildmarkens härd",b="För den som ger sig utanför bosättningens portar kräver överlevnad i vildmarken mer än ett vasst svärd och en stadig rustning. Uppdraget Camping 101: Cooking skickar blivande äventyrare till Cook Torka i Razor Hill för att lära sig matlagningens konst. I Durotars öppna ödemarker och bortom dem handlar matlagning om mer än att laga en varm måltid. Det är grunden för att tända en stadig lägereld, som är hjärtat i varje läger."},{t="Bygg och inred lägret",b="När resenärer behärskar grunderna kan de slå upp ett enkelt läger nästan var som helst i gränslandet. En nybörjares lägereld rymmer bara en handfull nödvändiga inredningsföremål, men vidare studier öppnar nya möjligheter. Med större kunskaper i matlagning kan du bygga större eldar, medan andra hantverksyrken ger dig färdigheterna att inreda och förbättra lägret till ett pålitligt skydd mot den otämjda vildmarken."}},faq={{q="Vad är uppdraget Camping 101: Cooking?",a="Camping 101: Cooking är ett introduktionsuppdrag som lär äventyrare grunderna i överlevnad utomhus. Genom att lära sig matlagning och att göra upp lägereldar kan äventyrare slå läger på egen hand ute i vildmarken.",al={"vad är camping 101 cooking","uppdraget camping 101 cooking","vad gör uppdraget"}},{q="Vem är Cook Torka?",a="Cook Torka är Hordens matlagningstränare i Razor Hill i Durotar. Han lär blivande äventyrare grunderna i matlagningsyrket och hur man tänder en enkel lägereld.",al={"vem lär ut matlagning i razor hill","vem är cook torka","var finns cook torka"}},{q="Varför krävs matlagning för att slå läger?",a="Matlagning handlar inte bara om att laga mat. Lägerelden som du gör upp med matlagningskunskaper utgör grunden för ett läger. Utan eld kan du inte hålla ett ordentligt läger i vildmarken.",al={"varför behöver jag matlagning för att slå läger","sambandet mellan matlagning och lägereld","krävs matlagning för att slå läger"}},{q="Var kan en äventyrare slå läger?",a="När du har lärt dig grunderna i matlagning och att göra upp lägereldar kan du slå upp ett litet läger nästan var som helst i den öppna vildmarken. De första lägren är enkla och rymmer inte mycket inredning.",al={"var kan jag slå läger","hur fungerar camping","placering av läger"}},{q="Hur uppgraderar du lägerelden?",a="När du blir skickligare i matlagningsyrket kan du lära dig att bygga större och mer långlivade lägereldar, vilket ger lägret fler möjligheter.",al={"större lägereldar","uppgradera lägereld","hur förbättrar jag lägret"}},{q="Hur får du inredning till ett läger?",a="Matlagning ger dig grunden i form av en lägereld. Tränare i andra hantverksyrken runt om i världen kan lära äventyrare att tillverka och placera ut mer inredning för att anpassa och bygga ut sina läger.",al={"lägerdekorationer","inredning till lägret","tränare för lägerinredning"}}},fp="20,265,22.457.0,30.450.0,39.235.0,18.177.0,36.207.0,42.208.0,33.160.0,45.199.0"}
P.entries["quest:96656"] = {n="The Adventurer",s="The Adventurer är ett introduktionsuppdrag som Executor Arren ger åt unga, erfarna Forsaken-mästare utanför Deathknell. Efter att ha visat dig pålitlig i angrepp mot Scarlet Crusade skickas du längs vägen mot Brill för att undersöka en främling som dröjer sig kvar nära bosättningen. I stället för ännu en fanatisk spion möter du Eleanor Shackleton, en självständig resenär som gärna lär ut praktiska färdigheter för att överleva i vildmarken.",h="The Adventurer är ett introduktionsuppdrag som Executor Arren ger åt unga, erfarna Forsaken-mästare utanför...",kw={"brill","slå läger","deathknell","eleanor shackleton","executor arren","scarlet crusade","the adventurer","the great outdoors","tirisfal glades"},ang={["faction:Horde"]="Medan Executor Arren vaktar det unga Forsaken-rikets gränser ger fredliga samtal med kringvandrande överlevnadsexperter Horde-nykomlingar värdefulla praktiska kunskaper.",["race:Undead"]="För nya Forsaken som ger sig bortom Deathknell är mötet med en äventyrare från samma folk, som Eleanor, en tidig lärdom: alla främlingar nära Brill är inte spioner åt Scarlet Crusade."},sec={{t="En misstänkt iakttagelse",b="Executor Arren håller noggrann uppsikt över Deathknell och vägarna dit. Scarlet Crusaders spionerar aktivt i området och infiltrerar norra Lordaeron, så varje nykomling som irrar omkring nära Brill måste genast granskas. Du har visat ditt engagemang genom att undanröja korsfararhot längs gränsen, och därför ber Arren dig att i tysthet undersöka den okända gestalten och avgöra om hon utgör en dold fara för Forsaken."},{t="En resenär i skogen",b="När du hittar Eleanor Shackleton vid vägkanten nära Brill visar det sig att hon inte alls ägnar sig åt Crusades fanatiska planer eller Scourges nekromanti. Eleanor är en annan Forsaken som stannat till före nästa färd ut i vildmarken. Hon är helt enkelt en äventyrare. I stället ser hon äventyrarens gnista hos dem som skickats för att kontrollera henne och erbjuder sig att dela med sig av grunderna i att överleva i vildmarken och slå läger."}},faq={{q="Varför vill Executor Arren att Eleanor undersöks?",a="Deathknell och Brill hotas ständigt av Scarlet Crusades infiltratörer och fientliga spioner. Främlingar som smyger omkring längs huvudvägen väcker misstankar tills deras avsikter har visat sig vara godartade.",al={"varför undersöka eleanor","vem skickade mig till eleanor","arrens uppdrag till eleanor"}},{q="Vem är Eleanor Shackleton?",a="Eleanor Shackleton är en självständig äventyrare som slagit läger vid vägen nära Brill. Hon är inte lojal mot Scarlet Crusade och ägnar sig helt åt att utforska vildmarken och dela med sig av sina överlevnadskunskaper till andra resenärer.",al={"vem är eleanor","eleanor shackleton historia","vem är npc:n the adventurer"}},{q="Har Eleanor någon koppling till Scarlet Crusade?",a="Nej. När du kommer fram till hennes läger klargör Eleanor snabbt att hon inte har någon som helst koppling till de fanatiska korsfararna som hotar Tirisfal Glades.",al={"tillhör eleanor scarlet crusade","eleanor fiende","är eleanor spion"}},{q="Vart leder uppdraget?",a="När du rapporterar till Eleanor låses uppdraget 'The Great Outdoors' upp. Där börjar hon lära dig grunderna i att överleva i vildmarken och slå läger.",al={"vad kommer efter the adventurer","nästa uppdrag efter the adventurer","eleanor shackleton fortsättning"}},{q="Var hittar man Eleanor Shackleton?",a="Hon har slagit läger strax intill huvudvägen österut mot staden Brill i Tirisfal Glades.",al={"eleanors plats","var finns eleanor shackleton","eleanors läger i tirisfal"}},{q="Varför valde Executor Arren dig till det här uppdraget?",a="Du vann Arrens förtroende genom att framgångsrikt spåra upp agenter och budbärare från Scarlet Crusade nära Deathknell och visade att du kan hantera känsliga spaningsuppdrag.",al={"varför välja mig","arrens förtroende","varför skickar executor arren dig"}}},fp="14,455,18.461.0,23.423.0,50.208.0,26.227.0,44.151.0,27.143.0,38.99.0,51.172.0"}
P.entries["quest:96658"] = {n="Camping 101: Cooking",s="I närliggande bosättningar lär sig nya äventyrare att laga mat och tända en enkel lägereld inför livet i vildmarken. Lektionen erbjuds i både Alliansens och Hordens områden.",h="I närliggande bosättningar lär sig nya äventyrare att laga mat och tända en enkel lägereld inför livet i...",kw={"lägereld","camping 101","matlagning","goldshire","shackleton","tomas","vildmark","zarrin"},ang={["faction:Alliance"]="Som äventyrare i Alliansen som lämnar Northshire, Dun Morogh eller Teldrassil leds du mot städer som Goldshire, Kharanos och Dolanaar för att lära dig klara dig själv innan du ger dig ut i vildmarken.",["faction:Horde"]="Som ung kämpe i Horden i Durotar, Mulgore eller Tirisfal leds du mot lägereldar i Razor Hill, Bloodhoof Village eller Brill.",["profession:Cooking"]="Matlagning ger dig mat som återställer din styrka och lägerelden som står i centrum för ett läger utomhus."},sec={{t="Vildmarkens härd",b="Alla resenärer behöver veta hur man gör upp en eld utanför de befästa murarnas trygghet. En lägereld kan koka vatten och steka kött, och den blir lägrets fasta punkt i okänd terräng."},{t="Från glöd till läger",b="Lärlingar i matlagning kan bara tända små eldar med få tillbehör. Större skicklighet i matlagning gör att de kan tända större eldar som passar mer välutrustade läger. Andra praktiska yrken lär också ut hur man tillverkar användbara lägerföremål."}},faq={{q="Vad är syftet med det här uppdraget?",a="Nya äventyrare besöker en matlagningstränare i en närliggande bosättning för att lära sig grunderna i matlagning och tända en lägereld som blir lägrets fasta punkt utomhus.",al={"varför göra camping 101","syftet med camping 101: matlagning","vad gör det här uppdraget"}},{q="Vem erbjuder det här uppdraget till resenärer?",a="Erfarna guider i vildmarken och äventyrare erbjuder den här träningen hos båda fraktionerna, däribland Eleanor Shackleton, Eric Brighthammer, Lyreena Duskblade, Sam Sarsaparilla, Brakk, Kaga Wildhoof och Raan Wildwind.",al={"vem ger camping 101","uppdragsgivare för lägeruppdrag"}},{q="Var lämnar spelare i Alliansen in uppdraget?",a="Äventyrare i Alliansen rapporterar till tränare i sina hemtrakter, som Tomas i Goldshire, Gremlock Pilsnor i Kharanos eller Zarrin i Dolanaar.",al={"var lämnar alliansen in uppdraget","matlagningstränare i alliansen"}},{q="Var lämnar spelare i Horden in uppdraget?",a="Äventyrare i Horden kan lära sig av Cook Torka i Razor Hill, William Pickman i Brill eller Pyall Silentstride i Bloodhoof Village.",al={"matlagningstränare i horden","var lämnar horden in uppdraget"}},{q="Kan lägret byggas ut senare?",a="Ja. Större skicklighet i matlagning lär dig att tända större eldar som ger plats åt fler lägerföremål i vildmarken.",al={"större lägereld","förbättra lägret"}},{q="Kan andra yrken bidra till lägerlivet?",a="Ja. Matlagning ger dig lägerelden, medan tränare i andra hantverksyrken lär ut hur du tillverkar praktiska lägerföremål, om du har övat på deras hantverk.",al={"yrken för lägerliv","lägerföremål"}}},fp="20,157,28.177.0,26.239.0,34.140.0,35.214.0,39.147.0,36.128.0,36.109.0,44.145.0"}
P.entries["quest:96659"] = {n="The Adventurer",s="När unga tauren förbereder sig på att lämna sina förfäders träningsmarker på Red Cloud Mesa ber Chief Hawkwind dem om en sista tjänst. Han anförtror dem ett knippe viktiga förnödenheter avsett för Kaga Wildhoof, en erfaren vandrare som slagit läger nära Bloodhoof Village och en gång hjälpte hövdingen i hans egen ungdom.",h="När unga tauren förbereder sig på att lämna sina förfäders träningsmarker på Red Cloud Mesa ber Chief...",kw={"bloodhoof village","camp narache","chief hawkwind","kaga wildhoof","mulgore","red cloud mesa","supply bundle","the adventurer"},ang={["faction:Horde"]="Chief Hawkwind ser till att Horde-allierade som lämnar startplatån knyter tidiga band till Mulgore erfarna vandrare och utposter.",["race:Tauren"]="För unga tauren som för första gången lämnar Camp Narache är det deras första tjänst för sina fränder på Mulgore vidsträckta slätter att överlämna Hawkwinds hedersskuld till Kaga Wildhoof."},sec={{t="En hövdings återgäldning",b="Innan resenärerna går nerför stigen från platån mot Mulgore vidsträckta slätter stannar Chief Hawkwind för att ta itu med ouppklarade personliga skulder. Långt innan han började vägleda nya generationer jägare och schamaner vid Camp Narache mötte Hawkwind Kaga Wildhoof. Hövdingen beskriver henne som en skicklig äventyrare, och hon gav honom ovärderlig hjälp när han behövde den som mest. När han får höra att hon slagit läger strax utanför Bloodhoof Village skickar Hawkwind förnödenheter med de nyprövade noviserna som är på väg att ge sig av."},{t="Lämna platån",b="Det här är ett avgörande övergångsprov för unga Horde-mästare som lämnar Red Cloud Mesa. Stigen ner från högplatån leder direkt mot Bloodhoof Village, hjärtat för kultur och försörjning i centrala Mulgore. När du bär knippet med förnödenheter över slätterna knyter du samman det skyddade träningslivet på platån med de större och vildare utmaningarna för United Tauren Tribes."}},faq={{q="Vem är Kaga Wildhoof?",a="Kaga Wildhoof är en erfaren tauren-äventyrare som nyligen slagit läger strax utanför Bloodhoof Village. Hon har länge varit vän med Chief Hawkwind och hjälpte honom mycket för flera år sedan.",al={"kaga wildhoof","vem är wildhoof","var är kaga"}},{q="Varför skickar Chief Hawkwind förnödenheterna?",a="Hawkwind ser de unga mästarnas avfärd ner mot Bloodhoof Village som ett perfekt tillfälle att återgälda en gammal tjänst till Wildhoof och se till att hans äventyrskamrat har färska förnödenheter inför sina resor.",al={"hawkwinds skuld","varför skicka förnödenheter","syftet med supply bundle"}},{q="Var ligger Kaga Wildhoofs läger?",a="Hennes läger ligger på slätterna strax utanför Bloodhoof Village, nedanför den slingrande sydliga stigen från Red Cloud Mesa till centrala Mulgore.",al={"kagas lägerplats","hitta kaga","lägret vid bloodhoof village"}},{q="När blir uppdraget tillgängligt?",a="Chief Hawkwind erbjuder uppdraget när en resenär har visat sitt mod på Red Cloud Mesa och är redo att bege sig ut i Mulgore vidsträckta områden.",al={"när får jag the adventurer","när får man hawkwinds uppdrag","uppdraget för att lämna platån"}},{q="För uppdraget dig bort från Camp Narache?",a="Ja. Att bära förnödenheterna är en tydlig uppmaning att lämna Camp Narache bakom dig och följa stigen mot Bloodhoof Village.",al={"lämna red cloud mesa","resan till bloodhoof"}},{q="Vad finns i Supply Bundle?",a="Knippet innehåller viktiga förnödenheter som samlats in av Camp Naraches stammar för att hjälpa en äventyrare att klara sig utanför organiserade bosättningar.",al={"vilka förnödenheter","innehållet i supply bundle"}}},fx={["2c6e5885"]={q="Varför ber Chief Hawkwind dig att leverera förnödenheterna?",a="Du har genomfört dina första riter på Red Cloud Mesa och förbereder dig på att lämna Camp Narache för att ge dig ut på Mulgore-slätterna. Eftersom du ändå passerar Bloodhoof Village på vägen ger Chief Hawkwind dig det här ärendet, i stället för att skicka iväg modiga krigare som behövs för att vakta mesan och skydda de unga taurer som tränar där.",al={"varför jag åt hawkwind","varför skicka mig med förnödenheter","varför väljer hawkwind mig"}}},fp="14,306,23.521.0,16.370.0,21.217.0,44.208.0,38.139.0,38.157.0,48.133.0,43.148.0"}
P.entries["quest:96661"] = {n="Camping 101: Cooking",s="Camping 101: Cooking är ett introduktionsuppdrag som visar äventyrare hur grundläggande matlagningskunskaper utgör grunden för att slå läger i vildmarken. Genom att söka upp Pyall Silentstride i Bloodhoof Village lär sig resenärer att göra upp en lägereld som blir lägrets mittpunkt och förbereder dem för livet i vildmarken.",h="Camping 101: Cooking är ett introduktionsuppdrag som visar äventyrare hur grundläggande matlagningskunskaper...",kw={"bloodhoof village","lägereld","camping 101","lägerplats","matlagning","möbler","pyall silentstride","vildmark"},ang={["faction:Horde"]="Äventyrare som reser genom Mulgore inleder sin överlevnadsutbildning i vildmarken i Bloodhoof Village, under ledning av lokala taurenhantverkare och kockar.",["profession:Cooking"]="Matlagning är själva grundpelaren för överlevnad i vildmarken. Den ger inte bara näring, utan också den viktiga färdigheten att tända en lägereld som ett helt läger byggs kring."},sec={{t="Vildmarkens härd",b="Varje lång färd genom den otämjda vildmarken kräver grundläggande överlevnadskunskaper, och varje riktigt läger börjar med eld. För vandrare som korsar Kalimdor introducerar uppdraget Camping 101: Cooking det viktiga sambandet mellan matlagningskunskaper och överlevnad i vildmarken. Matlagning handlar inte bara om att tillaga näringsrika måltider av jagat vilt; den ger grundkunskaperna som behövs för att göra upp en fungerande lägereld ute i väder och vind. Utan eld har en äventyrare inget läger att återvända till när mörkret faller."},{t="Slå läger",b="På Mulgore slätter hänvisas äventyrare till Pyall Silentstride i Bloodhoof Village för att lära sig grunderna i matlagning. Med den här grundutbildningen kan en äventyrare göra upp en lägereld var som helst i vildmarken och slå ett enkelt läger. De första lägren är enkla och rymmer få möbler, men högre matlagningsskicklighet låser upp kunskapen om hur man gör upp större eldar. Hantverkare som behärskar andra yrken kan i sin tur tillverka möbler som gör deras utposter i vildmarken mer kompletta."}},faq={{q="Vad är Camping 101: Cooking?",a="Camping 101: Cooking är ett introduktionsuppdrag som lär äventyrare hur matlagning och konsten att göra upp eld utgör den konkreta grunden för att överleva i vildmarken. Genom att lära sig matlagning får en äventyrare förmågan att göra upp lägereldar och slå läger ute i fält.",al={"vad är camping 101: cooking","uppdrag om matlagning för camping","grunderna i camping och matlagning"}},{q="Vem är Pyall Silentstride?",a="Pyall Silentstride är en matlagningsinstruktör i Bloodhoof Village i Mulgore. Han lär nybörjare matlagningens konst och visar dem hur man gör upp enkla lägereldar.",al={"vem är pyall silentstride","var finns pyall silentstride","matlagningsinstruktör i bloodhoof"}},{q="Varför måste man kunna matlagning för att slå läger?",a="I vildmarken handlar matlagning om mer än att tillaga måltider. När en äventyrare lär sig laga mat lär hen sig också att göra upp en lägereld, som är den konkreta och praktiska mittpunkten i varje läger.",al={"varför behövs matlagning för camping","varför lära sig matlagning för att slå läger","sambandet mellan lägereld och camping"}},{q="Kan man göra större lägereldar när färdigheten förbättras?",a="När du utvecklas och höjer din matlagningsskicklighet får du kunskaperna som krävs för att bygga större och mer robusta eldar, vilket gör det möjligt att ordna mer omfattande läger i vildmarken.",al={"kan jag uppgradera lägereldar","större lägereldar","hur gör man större eldar"}},{q="Hur möblerar man ett läger?",a="Lägerelden utgör lägrets mittpunkt, men du kan lära dig att tillverka fler möbler och tillbehör av andra yrkesinstruktörer runt om i världen, om du har utbildning i deras hantverk.",al={"hur fungerar lägermöbler","lägerdekorationer","möbler till läger genom hantverksyrken"}},{q="Var kan man slå läger?",a="När du har lärt dig att göra upp en lägereld genom grundläggande matlagningsutbildning kan du slå ett enkelt läger ute i vildmarken var dina resor än för dig.",al={"var kan jag slå läger","kan jag slå läger var som helst","begränsningar för lägerplatser"}}},fp="20,322,22.515.0,17.512.0,29.263.0,26.181.0,42.193.0,53.177.0,30.197.0,28.175.0"}
P.entries["quest:967"] = {n="The Tower of Althalaxx",s="Det här uppdraget knyter utredningen av Dark Strand-kulten i norra Darkshore till det större försvaret av norra Kalimdor. Balthule Shadowstrike skickar en allianskurir söderut till Maestra's Post i Ashenvale för att varna sin mentor, Delgren the Purifier, om kultens mörka sammankomst vid Tower of Althalaxx.",h="Det här uppdraget knyter utredningen av Dark Strand-kulten i norra Darkshore till det större försvaret av...",kw={"ashenvale","balthule shadowstrike","dark strand","darkshore","delgren the purifier","heliga ljuset","maestra's post","tower of althalaxx"},ang={["class:Paladin"]="Mötet med Delgren ger paladiner ett inspirerande exempel på deras heliga uppdrag i främmande länder: en mänsklig korsfarare som använder ljuset för att vinna de tillbakadragna nattalvernas djupa förtroende i Kalimdor.",["faction:Alliance"]="Samarbetet mellan Balthule i Darkshore och Delgren i Ashenvale visar hur viktiga kommunikationsvägarna är för att binda samman norra Kalimdors utspridda alliansgarnisoner.",["race:NightElf"]="För nattalverna lyfter det här uppdraget fram det växande, praktiska samarbetet mellan deras vaktposter och de östra folken som kommit för att hjälpa till att rensa deras skogar från demoniska lämningar."},sec={{t="En vädjan om förstärkning",b="Efter de första sammandrabbningarna med Dark Strand-kultisterna kring Tower of Althalaxx inser nattalvsspejaren Balthule Shadowstrike att hotet är större än hans ensamma vakthållning. För att kunna slå till beslutsamt skriver han en utförlig rapport och anförtro den åt en alliansbudbärare på väg till sin mästare, Delgren the Purifier. Kultens besvärjare blir djärvare för varje timme, så budskapet måste nå erfarna ledare som kan styra en utrotningsinsats."},{t="Vägen till Ashenvale",b="För att bära Balthules meddelande måste kuriren färdas längs hela Darkshore, följa den långa kustvägen söderut ut ur dimman och korsa den skogsklädda gränsen till Ashenvale. Delgren the Purifier är stationerad vid Maestra's Post längs den västra vägen och har vigt sig åt att rena skogen från kvardröjande demoner och odöda. Även om han först var obekant med nattalvernas seder har den mänsklige paladinen vunnit vaktposternas djupa respekt och blivit en oumbärlig allierad."},{t="En helig krigare väcks",b="Delgren tar emot Balthules brådskande brev med bister beslutsamhet. Som krigare hängiven det Heliga ljuset ser han mörka kultister, själafördärv och demoniska bestar i dessa uråldriga skogar som en oacceptabel plåga. När han läser om Dark Strands fasta fäste i det förstörda högalvetornet förbereder sig Delgren genast på att ta ledningen för insatsen och slå tillbaka."}},faq={{q="Vem är Delgren the Purifier?",a="Delgren the Purifier är en mänsklig paladin stationerad vid Maestra's Post i Ashenvale. Hängiven det Heliga ljuset erbjuder han sin militära och andliga kunskap till nattalvernas vaktposter för att rena deras förfäders skogar från demoner och odöda.",al={"delgren the purifier","vem är delgren","delgrens bakgrund"}},{q="Varför skickar Balthule Shadowstrike en budbärare till Ashenvale?",a="Balthule är en spejare stationerad utanför Tower of Althalaxx som har studerat Dark Strand-kulten. När han inser att kultens mörka ritualer och antal ökar snabbt skickar han sina upptäckter till sin mentor Delgren, så att en samordnad attack kan genomföras.",al={"varför skicka brev till delgren","varför balthule skickar brev"}},{q="Vilken relation har Balthule och Delgren?",a="Delgren är Balthules mästare. Den mänsklige paladinen har undervisat nattalven i stridskonst och introducerat honom till det Heliga ljusets läror, vilket har skapat ett ovanligt nära band mellan dem trots deras kulturella skillnader.",al={"balthule och delgren","hur känner balthule och delgren varandra"}},{q="Var ligger Maestra's Post?",a="Maestra's Post är en alliansutpost i västra Ashenvale, längs huvudvägen söderut från Darkshore. Den fungerar som en tidig vaktpost för resande mellan Darkshore och skogens djup.",al={"maestra's post läge","var ligger maestra's post"}},{q="Vad gör Dark Strand-kulten vid Tower of Althalaxx?",a="Dark Strand är en kult som verkar från det förstörda högalvetornet Tower of Althalaxx i norra Darkshore. De utövar mörk magi, umgås med demoniska makter och hotar att släppa lös fördärvande krafter längs hela kusten.",al={"dark strand-kulten vid althalaxx","tower of althalaxx-kultister"}},{q="Hur ser Delgren på sin allians med nattalverna?",a="Delgren medgav att han till en början var ovan vid nattalvernas seder och levnadssätt när han först anlände till Kalimdor. Med tiden har han dock utvecklat enorm respekt för vaktposterna genom att stå sida vid sida med dem mot gemensamma fiender.",al={"delgren och nattalverna","mänsklig paladin och nattalver"}}},fx={["4ad41352"]={q="Varför väljer Balthule dig som budbärare i stället för att gå själv?",a="Balthule måste stanna nära Tower of Althalaxx för att hålla Dark Strand-kultisterna under uppsikt och bevaka det växande hotet. Resan går tvärs över hela Darkshore och in i Ashenvale. Därför behöver han en duglig och välbeväpnad resenär som klarar de farliga vägarna och kan se till att varningen når Delgren utan problem.",al={"varför skicka mig till delgren","varför är balthule budbärare","varför kan inte balthule leverera brevet"}}},fp="22,213,25.357.0,21.387.0,23.360.1,28.238.0,62.216.0,54.175.0,24.148.0,61.213.0,56.164.0"}
P.entries["quest:968"] = {n="Tools of the Highborne",s="Tools of the Highborne är ett uppdrag för Alliansen som ges av Thundris Windweaver i Auberdine. Resenärer skickas söderut till Ameth'Arans sönderslagna ruiner för att rycka kvarvarande magiska reliker ur händerna på rastlösa Highborne-spöken. Målet är enkelt: återta dessa uråldriga artefakter innan deras slumrande trolldom kan orsaka ytterligare skada på Kalimdor.",h="Tools of the Highborne är ett uppdrag för Alliansen som ges av Thundris Windweaver i Auberdine.",kw={"ameth'aran","auberdine","darkshore","highborne","reliker","sundering","thundris windweaver"},ang={["class:Druid"]="Att rensa bort de fördärvade magiska resterna från Ameth'Aran hjälper till att läka de andliga sår som stör den naturliga friden i Darkshores vildmark.",["class:Mage"]="Medan kaldorei-samhället vill krossa dessa artefakter av rädsla ser magiska lärda dem som sällsynta, välbevarade exempel på Highbornes hantverk före Sundering.",["faction:Alliance"]="Att hjälpa Night Elf-folket att säkra sina hemsökta områden stärker Alliansens närvaro och samhörighet i Kalimdors uråldriga nordliga skogar.",["race:NightElf"]="För kaldorei är konfrontationen med Ameth'Arans spöken en sorgsen påminnelse om deras förfäders övermod och det katastrofala sönderfallet av deras förfäders rike."},sec={{t="Ekon i ruinerna",b="Söder om Auberdine, öster om kustvägen, ligger Ameth'Arans igenvuxna stenfundament. För tiotusen år sedan var denna bosättning ett fäste för Highborne, den privilegierade adeln i det forntida Night Elf-riket. När deras tygellösa experiment med magi ledde till världens Sundering, krossades Ameth'Aran. Men dess invånare lämnade aldrig platsen helt. Vakter som patrullerar Darkshore rapporterar att dessa adelsmäns spöken fortfarande hemsöker de sjunkna torgen och klamrar sig fast vid de förtrollade verktyg och prydnader de ägde i livet."},{t="Renar det magiska förflutna",b="För dagens kaldorei-samhälle är magi inte bara förbjuden kunskap; den är en existentiell fara som nästan utplånade allt liv på Azeroth. Thundris Windweaver inser att om dessa Highborne-redskap lämnas i spöklika händer står dörren öppen för fördärv. Genom att skicka äventyrare för att rycka relikerna från de rastlösa andarna tänker Thundris se till att de förstörs grundligt, så att den slumrande, besudlade magin aldrig mer kan orsaka en katastrof."}},faq={{q="Var hittar jag Highborne-relikerna?",a="Relikerna finns i ruinerna av Ameth'Aran, söder om Auberdine på den östra sidan av huvudleden genom Darkshore. Vandrande andar i de förstörda stengårdarna bär på dessa uråldriga redskap.",al={"var finns relikerna","ameth'aran plats","var hittar man reliker"}},{q="Vem är Thundris Windweaver?",a="Thundris Windweaver är en lärd och äldre Night Elf som bor i hamnstaden Auberdine. I nära samarbete med de lokala vakterna samordnar han arbetet med att skydda Darkshore från kvarvarande magiska föroreningar och uråldriga förbannelser som lämnats efter Sundering.",al={"thundris windweaver","vem ger tools of the highborne"}},{q="Varför vill Thundris att relikerna förstörs?",a="Night Elf-samhället förkastar magi strikt på grund av den förödande Great Sundering, som orsakades av Highbornes vårdslösa trolldom. Thundris fruktar att den kvarvarande magiska kraften i föremålen kan väcka slumrande ondska om den lämnas obevakad.",al={"varför förstöra relikerna","syftet med tools of the highborne"}},{q="Vilka slags andar hemsöker Ameth'Aran?",a="Andarna är de spöklika resterna av Highborne-eliten som dog under War of the Ancients. Även i döden klamrar de sig fast vid sin forna stolthet, makt och magiska artefakter och spelar upp sina bleknade liv bland stenruinerna.",al={"spöken i ameth'aran","vad är andarna"}},{q="Varför är Highborne fortfarande bundna till ruinerna?",a="Thundris säger inte. Han känner bara till det som vakterna berättat för honom: Highbornes andar finns kvar bland ruinerna av Ameth'Aran och brukar fortfarande sina uråldriga magiska redskap.",al={"varför är de spöken","highborne-förbannelse"}},{q="Vad händer med relikerna när du lämnar in dem?",a="Thundris Windweaver tar hand om de insamlade relikerna med den uttryckliga planen att låta montera isär och förstöra dem för gott, så att deras slumrande magiska förorening aldrig mer kan utnyttjas eller släppas lös.",al={"vad gör thundris med relikerna","relikernas öde"}}},fx={df86da6d={q="Vad är Highborne Relics?",a="Relikerna är forntida magiska redskap som bevarats sedan tiden före den stora Sundringen. De användes en gång av drottning Azsharas främsta trollkarlar. Även efter tiotusen år bär de spår av den ansvarslösa magiska experimentlusta som slet det forntida Kalimdor i stycken. I vålnadernas händer är de fortfarande kanaler för vilande, farlig kraft.",al={"vad är highborne relics","vad är highborne relic","highborne relics bakgrund"}}},fp="22,193,19.522.0,23.360.0,37.144.0,27.203.0,46.179.0,38.187.0,47.192.0,50.160.0"}
P.entries["quest:96821"] = {n="Legging It",s="Legging It handlar om att röja en farlig väg söderut för att skydda arbetande peoner. Hot längs vägen hade skrämt arbetsstyrkan så att den slutade resa, vilket satte viktiga uppgifter på paus. När äventyrarna driver bort farorna blir vägen trygg igen och arbetarna kan återvända till sina uppdrag.",h="Legging It handlar om att röja en farlig väg söderut för att skydda arbetande peoner.",kw={"röjde vägen","hordens arbetskraft","legging it","förman","peonernas arbete","peoner","sydlig väg"},ang={["faction:Horde"]="Orkernas arbete och försörjningslinjer är starkt beroende av peonerna, vilket gör säkra vägar viktiga för Hordens byggande och resursinsamling.",["race:Orc"]="Peonerna utgör ryggraden i orkiska bosättningar, och förmännen förlitar sig på krigare som håller vägarna fria från hot så att arbetet kan fortsätta."},sec={{t="Säkra vägen",b="Legging It handlar om ett avbrott i det lokala arbetet, där peonerna blev för rädda för att färdas söderut. I stället för att utföra sina uppgifter vägrade arbetarna att riskera färden längs vägen på grund av farorna som lurade där. När resenärerna ingriper och driver bort hoten längs vägen blir det tillräckligt tryggt för att förmännen ska kunna skicka tillbaka sina arbetslag."},{t="Arbete och säkra vägar",b="Peonerna är ryggraden i Hordens infrastruktur och ansvarar för timmeravverkning, stenbrytning och byggandet av utposter. Eftersom peonerna har liten stridsförmåga kan även mindre rovdjur vid vägkanten eller fientliga spejare stoppa försörjningskedjorna. Det är viktigt att hålla transportlederna fria för att bosättningarna ska få förnödenheter och kunna fortsätta vara produktiva."}},faq={{q="Vad är Legging It?",a="Legging It är ett uppdrag för att säkra en sydlig färdväg för arbetslagen. Hot längs vägen hade skrämt de lokala peonerna och stoppat deras dagliga arbete, tills en äventyrare ingrep och röjde vägen.",al={"vad är legging it","information om uppdraget legging it","uppdraget legging it"}},{q="Varför var peonerna rädda för att resa söderut?",a="Peonerna var rädda för att bege sig söderut på grund av farorna längs vägen. Utan skydd eller en röjd väg vägrade arbetarna att riskera färden till sina uppdrag, vilket fick det lokala arbetet att stanna av helt.",al={"varför var peonerna rädda","peonernas rädsla","varför slutade peonerna arbeta"}},{q="Vad uppnår man genom att slutföra uppdraget?",a="När den sydliga vägen har röjts och de omedelbara farorna undanröjts kan förmännen tryggt skicka ut peonerna igen för att återuppta arbetet och insamlingen av resurser.",al={"vad händer efter legging it","resultatet av legging it","resultatet av att röja vägen"}},{q="Vilka är peonerna som nämns i uppdraget?",a="Peoner är Hordens grundläggande arbetskraft och ansvarar för tunga lyft, timmeravverkning, gruvdrift och byggandet av befästningar. De är oumbärliga för bosättningarnas verksamhet, men illa lämpade för strid och flyr lätt från faror.",al={"vilka är peonerna","peonernas roll","vad gör peoner"}},{q="Vart var peonerna på väg?",a="Vägen leder söderut till avlägsna arbetsområden och resursfyndigheter som kräver regelbundet underhåll av peonerna. Färden hade dock blivit så farlig att all trafik stoppades innan vägen röjdes.",al={"vart leder vägen","sydlig väg","färd söderut"}},{q="Varför behöver äventyrare röja vägarna åt peonerna?",a="Peoner saknar militär utbildning och stridsutrustning, vilket gör dem sårbara för vildmarksrovdjur och fientliga styrkor. Förmännen måste förlita sig på erfarna äventyrare för att oskadliggöra hot i området och hålla arbetsvägarna trygga.",al={"varför behöver peoner skydd","peonernas säkerhet","skydda peoner"}}},fp="10,324,17.367.0,24.349.0,19.211.0,42.218.0,44.182.0,40.243.0,31.207.0,55.231.0"}
P.entries["quest:96822"] = {n="For Honor",s="For Honor är ett uppdrag för att hedra fallna krigare och bevara minnet av deras bedrifter. Genom att slutföra uppgiften ser en äventyrare till att deras uppoffringar lever vidare i minnet.",h="For Honor är ett uppdrag för att hedra fallna krigare och bevara minnet av deras bedrifter.",kw={"fallna krigare","for honor","heder","minnesmärke","uppdrag","minne","krigare"},ang={["class:Warrior"]="Uppgiften handlar direkt om att hedra fallna krigare och berör särskilt dem som värdesätter uppoffringar på slagfältet och att de fallna blir ihågkomna."},sec={{t="En plikt att minnas",b="Uppdraget For Honor är ett högtidligt uppdrag som går ut på att hedra fallna krigare. I en värld som ständigt prövas av konflikter är det en viktig plikt för de överlevande att se till att soldater som gav allt inte glöms bort."},{t="Att bevara arvet",b="När du har slutfört uppgiften bekräftar uppdragsgivaren att de fallna krigarna lever vidare i minnet tack vare dina insatser. Din gärning ser till att deras uppoffringar blir erkända och respekterade i stället för att falla i glömska."}},faq={{q="Vad handlar uppdraget For Honor om?",a="For Honor är ett uppdrag som handlar om att hedra fallna krigare. När du tar dig an och slutför uppgiften hjälper du till att se till att deras uppoffringar erkänns och inte går förlorade i historien.",al={"vad är for honor","översikt över uppdraget for honor"}},{q="Vilka krigare nämns när uppdraget är slutfört?",a="Uppdragstexten hedrar särskilt fallna krigare vars bedrifter och minne bevaras genom dina handlingar. De som fullföljer uppgiften håller deras tjänst och uppoffringar vid liv.",al={"vilka är krigarna","vem blir ihågkommen"}},{q="Varför är det viktigt att hedra dessa krigare?",a="Uppgiften handlar om att minnas. I en värld präglad av pågående krig och konflikter ger det värdighet att hedra dem som föll i strid och säkerställer att deras mod erkänns.",al={"varför göra uppdraget","for honor betydelse"}},{q="Vem ber dig utföra uppgiften?",a="Uppgiften kommer från någon som vill hedra fallna kamrater. När du återvänder kontrollerar personen om du har utfört uppgiften och bekräftar att krigarna alltid kommer att bli ihågkomna.",al={"vem ger for honor","uppdragsgivare för for honor"}},{q="Leder uppdraget vidare till andra uppgifter?",a="Inget i uppdraget pekar vidare mot någon annan uppgift. Det står på egna ben som en hyllning till fallna krigare och befäster deras arv så att deras uppoffringar aldrig glöms bort.",al={"ingår for honor i en uppdragskedja","vad följer efter for honor"}},{q="Vad står titeln For Honor för?",a="Namnet speglar uppdragets centrala tema: att hedra fallna soldater. Det visar att det är en av en krigares mest högtidliga plikter att erkänna uppoffringar och hålla minnet av slagfältet vid liv.",al={"vad gör det hedervärt","betydelsen av for honor"}}},fp="9,201,21.240.0,21.232.0,34.196.0,47.187.0,41.197.0,34.194.0,36.186.0,38.201.0"}
P.entries["quest:96825"] = {n="This Fruit Could Bite Back",s="This Fruit Could Bite Back är ett insamlingsuppdrag där du plockar vilda fikonkaktusfrukter i de torra trakterna nära Orgrimmar. Frukterna tillagas till mat, medan fröna sparas för framtida odling av en tålig ökengröda som ska ge näring åt Hordens huvudstad.",h="This Fruit Could Bite Back är ett insamlingsuppdrag där du plockar vilda fikonkaktusfrukter i de torra...",kw={"kaktusfrukt","durotar","frukt","orgrimmar","fikonkaktusfrukt","fikonkaktusfrukter","frön","this fruit could bite back"},ang={["faction:Horde"]="Tåliga ökenfrukter är viktiga för att försörja orchernas huvudstad och mätta Hordens växande befolkning.",["profession:Cooking"]="Fikonkaktusfrukter kan användas i matlagningen i Durotars torra klimat och bli ingredienser i smakrika rätter och matförråd åt stadens invånare.",["profession:Herbalism"]="Skördare och botaniker känner till ökenflorans tålighet och hur mycket arbete som krävs för att samla in taggiga vilda frukter för odling."},sec={{t="Skörd i det torra ödemarkslandet",b="Durotar är ett kargt, solbränt landskap där traditionellt jordbruk nästan är omöjligt. För att försörja den växande huvudstaden Orgrimmar tar de rådiga invånarna tillvara på den inhemska ökenfloran. Fikonkaktusen, en tålig kaktus med skyddande taggar, trivs i den torra jorden och ger välbehövlig näring när den plockas varsamt."},{t="Odling och försörjning",b="Att samla fikonkaktusfrukter handlar inte bara om att ordna en måltid för stunden. Fruktköttet tillagas till smakrika rätter, medan de insamlade fröna varsamt sparas för odling. Målet är att plantera dessa tåliga grödor runt hela Orgrimmar och skapa en tillgänglig, varaktig matkälla precis utanför fästningens murar."}},faq={{q="Vad är This Fruit Could Bite Back?",a="This Fruit Could Bite Back är ett uppdrag där du samlar vilda fikonkaktusfrukter i Durotar. Frukten ska både användas direkt i matlagningen och ge frön som kan sås i det torra landskapet kring Orgrimmar.",al={"vad är this fruit could bite back","uppdraget this fruit could bite back","uppdraget med frukten som biter tillbaka"}},{q="Varför samlas fikonkaktusfrukter in?",a="De insamlade fikonkaktusfrukterna fyller två syften: de blir goda måltider för lokalbefolkningen och ger frön som kan gro. Målet på sikt är att odla fikonkaktus i stor skala i det torra landet kring Orgrimmar.",al={"varför samla fikonkaktusfrukter","fikonkaktusfruktens syfte","vad används fikonkaktusfrukter till"}},{q="Var ska fröna planteras?",a="Fröna från skörden ska planteras i utkanten av Orgrimmar och i trakterna runt staden. På så vis kan man skapa en tålig, självförsörjande matkälla i den hårda ökenjorden.",al={"var växer fikonkaktusfrukter","plantering av fikonkaktus kring orgrimmar"}},{q="Vem vill att frukterna samlas in?",a="En lokal invånare som vill öka matförråden och odla grödor i Durotars hårda ökenklimat ber om skörden, så att den kan mätta resande och ge framtida grödor.",al={"vem vill ha fikonkaktusfrukterna","uppdragsgivare för bite back"}},{q="Varför kan frukten ”bita tillbaka”?",a="Fikonkaktusfrukterna är täckta av vassa taggar och tornar, som hos tåliga ökenkaktusar. Därför kan det vara farligt att skörda dem utan försiktighet.",al={"varför biter tillbaka","varför biter frukten tillbaka"}},{q="Varför är det viktigt att plantera frukt kring Orgrimmar?",a="Durotar består till största delen av torr och stenig mark, vilket försvårar vanligt jordbruk. Torktåliga grödor som fikonkaktus kan ge huvudstaden en hållbar matförsörjning.",al={"har orgrimmar matbrist","jordbruk i orgrimmar","jordbruk i durotar"}}},fp="26,286,26.348.0,26.348.0,35.227.0,37.223.0,32.211.0,32.179.0,31.138.0,49.197.0"}
P.entries["quest:96875"] = {n="Beasts of Thunder Ridge",s="Beasts of Thunder Ridge är ett uppdrag i Orgrimmar som ges av läderarbetaren Kamari, som stöder den pågående utbyggnaden av Hordehuvudstaden. Äventyrare skickas till klipporna i Thunder Ridge för att samla slitstarka ödleskinn och lämna in garvade hudar som förstärkning till stadens nyuppförda byggnader.",h="Beasts of Thunder Ridge är ett uppdrag i Orgrimmar som ges av läderarbetaren Kamari, som stöder den pågående...",kw={"beasts of thunder ridge","garvat lätt skinn","durotar","kamari","läderarbete","orgrimmar","peoner","grovt ödleskinn","thunder ridge"},ang={["faction:Horde"]="När Horde etablerar sig i Durotar bidrar förnödenheter från den omgivande vildmarken direkt till att befästa och bygga ut Orgrimmar.",["race:Orc"]="Orchernas byggande bygger på grova, tåliga material som jägare och arbetare samlar in för att stå emot Durotars väder och vind."},sec={{t="En växande huvudstad",b="Medan Horde bygger sitt hem i Durotars torra landskap fortsätter huvudstaden Orgrimmar att växa. Nya bostäder, verkstäder och försvarsverk kräver en stadig tillgång på timmer, sten och djurhudar. Timmer måste transporteras långväga ifrån, men Durotars lokala djurliv ger en riklig tillgång på slitstarka skinn åt stadens peoner och byggare."},{t="Klyftans bestar",b="I djupet av Thunder Ridge har de inhemska ödlorna grova, väderbitna skinn. Hudarna är i allmänhet för tjocka och stela för att sys till bärbar läderrustning, men deras tålighet gör dem till utmärkt byggnadsmaterial. När de flås på rätt sätt används de som beklädnad på tak och väggar i Orgrimmars trä- och stenbyggnader. De skyddar insidan mot den gassande solen och plötsliga vindar genom klyftan."}},faq={{q="Varför behöver Orgrimmar ödleskinn från Thunder Ridge?",a="De grova ödleskinn som samlas in i Thunder Ridge är alldeles för sträva och tjocka för att tillverka bärbar rustning av, men deras tålighet gör dem idealiska för byggändamål. Peoner i Orgrimmar använder dem för att klä väggar och tak i nybyggda hus och skydda dem mot det hårda vädret.",al={"vad ska skinnen användas till","varför grovt ödleskinn","vad används skinnen från thunder ridge till"}},{q="Vem är Kamari?",a="Kamari är en läderarbetare i Hordehuvudstaden Orgrimmar. Hon förser stadens byggare och peoner med tåliga hudar och skinn som behövs för pågående byggprojekt.",al={"vem är kamari","kamari orgrimmar","vem ger uppdraget beasts of thunder ridge"}},{q="Var ligger Thunder Ridge?",a="Thunder Ridge är en karg klyfta i Durotars torra landskap. Den är känd för ödlorna vars tjocka skinn Kamari vill ha till stadens nya byggnader.",al={"var ligger thunder ridge","thunder ridge plats","thunder ridge durotar"}},{q="Varför efterfrågas garvade lätta skinn utöver ödleskinn?",a="Utöver de tunga ödleskinnen behöver Kamari garvade lätta skinn som komplement till de tyngre materialen. Det sätter äventyrarens bredare kunskaper och färdigheter i läderbearbetning på prov.",al={"varför garvade lätta skinn","vad används de garvade skinnen till"}},{q="Varför byggs Orgrimmar ut så snabbt?",a="Som Hordes nygrundade huvudstad är Orgrimmar under ständig uppbyggnad och utbyggnad för att hysa ett växande antal orcher och deras allierade. Därför finns det ett konstant behov av råmaterial.",al={"varför bygger orgrimmar","orgrimmars utbyggnad"}},{q="Kan ödleskinnen från Thunder Ridge användas till rustning?",a="Grova ödleskinn från Thunder Ridge är oftast för tjocka och stela för att kunna formas till smidig rustning. Deras främsta praktiska värde ligger därför i byggnadsmaterial snarare än kläder.",al={"kan man bära ödleskinn","är grovt ödleskinn rustning"}}},fp="23,302,17.404.0,20.426.0,56.295.0,14.172.0,31.161.0,60.183.0,38.198.0,59.173.0"}
P.entries["quest:96876"] = {n="Ukor's Lost Pack",s="Ukor's Lost Pack är ett föremål som tappats i södra Durotars vildmark. Ägarens namn är klumpigt ditsytt. Han övergav det i all hast när han flydde från ett skräckinjagande möte med en jättelik spindel från trakten.",h="Ukor's Lost Pack är ett föremål som tappats i södra Durotars vildmark.",kw={"durotar","horde","förlorad väska","södra durotar","spindel","ukor","ukor's lost pack"},ang={["faction:Horde"]="Unga Horde-äventyrare som färdas genom södra Durotar hjälper ofta lokalbor som Ukor. De visar att de är värdiga förtroende genom att återfinna personliga ägodelar som gått förlorade bland farliga vilddjur."},sec={{t="En förlorad ägodel",b="När en äventyrare färdas genom den torra vildmarken i södra Durotar hittar hen en övergiven resväska med namnet ”Ukor” klumpigt ditsytt på locket. Det hårda livet i Durotars karga marker lämnar föga utrymme för planlöst strövande, och övergiven utrustning brukar tyda på att något olyckligt hänt i närheten."},{t="Flykt från vildmarken",b="När väskan återlämnas till Ukor i södra Durotar kommer sanningen om varför han övergav den fram. Ukor tappade väskan i panik när han överfölls av en enorm spindel från trakten, övertygad om att han aldrig skulle få se sina förnödenheter igen. Att få tillbaka väskan oskadd väcker hans innerliga tacksamhet och lovord."}},faq={{q="Vem är Ukor?",a="Ukor bor i södra Durotar. När han ställdes öga mot öga med en enorm spindel i den torra vildmarken tvingades han överge sina ägodelar i ett desperat försök att komma undan oskadd.",al={"vem är ukor","ukor durotar"}},{q="Varför förlorade Ukor sin väska?",a="Ukor tappade sin väska när han flydde för sitt liv från en jättelik spindel som lurade i Durotar. Han trodde att ägodelarna var borta för alltid tills en äventyrare spårade upp väskan.",al={"varför förlorades väskan","var tappade ukor väskan"}},{q="Vart ska väskan lämnas?",a="Den återfunna väskan tillhör Ukor, som väntar i södra Durotar och är redo att välkomna återvändande resenärer.",al={"var lämnas väskan","lämna in till ukor"}},{q="Hur känner man igen väskan?",a="Det är lätt att känna igen väskan på Ukors namn, som är klumpigt ditsytt på locket.",al={"hur känns väskan igen","väskans sömmar"}},{q="Vilken sorts varelse jagade Ukor?",a="Ukor överfölls av en jättelik spindel som strövade omkring i södra Durotars marker. Den skrämde honom så mycket att han tappade alla sina ägodelar och sprang i säkerhet.",al={"spindel i durotar","vilken spindel anföll ukor"}},{q="Vad händer när du lämnar tillbaka väskan till Ukor?",a="Ukor blir förbluffad och djupt tacksam över att återse sina förlorade ägodelar. Han utropar äventyraren som hämtade väskan till en sann hjälte.",al={"ukors belöning","hur reagerar ukor"}}},fp="16,232,16.327.0,17.317.0,12.183.0,27.174.0,37.116.0,27.99.0,34.152.0,46.138.0"}
P.entries["quest:96877"] = {n="Halikor's Hoof",s="Halikor's Hoof är ett uppdrag där du hämtar ett fysiskt bevis efter att ha dödat den väldiga ödlan Halikor. Att bära den enorma, avhuggna hoven till Horde-huvudstaden Orgrimmar hedrar jägarens seger över ett mäktigt vildmarksmonster.",h="Halikor's Hoof är ett uppdrag där du hämtar ett fysiskt bevis efter att ha dödat den väldiga ödlan Halikor.",kw={"halikor","halikor's hoof","horde","jakt","ödla","orgrimmar","trofé"},ang={["class:Hunter"]="Att fälla ett enormt och mäktigt odjur som Halikor visar spårarens skicklighet och jaktens spänning.",["faction:Horde"]="Att föra bevis på att ett mäktigt odjur har besegrats till Orgrimmar hedrar Hordes traditioner av styrka och jaktkonst."},sec={{t="Trofé från ett mäktigt vilddjur",b="Halikor's Hoof är en konkret trofé från kvarlevorna efter Halikor, en ovanligt massiv ödla. Bland jägare och krigare som färdas genom vildmarken är det en uråldrig sed att ta ett fysiskt minne från en så mäktig varelse som bevis på att den har fällts. Hovens väldiga storlek lämnar inget tvivel om hur enormt och kraftfullt odjuret var i livet."},{t="Bevis till huvudstaden",b="Att bära den tunga hoven tillbaka till Orgrimmars befästa portar visar Horde att odjuret har besegrats. I ett krigarsamhälle som värdesätter råstyrka och överlevnad mot landets hårda rovdjur ger en sådan trofé jägaren ära och försäkrar huvudstaden om att ett farligt djur har fällts."}},faq={{q="Vad är Halikor?",a="Halikor är en mäktig och väldig ödla. Dess enorma storlek framgår av den avhuggna hovens väldiga omfång, som jägare tar som obestridligt bevis på att den har besegrats.",al={"vad är halikor","vem är halikor","halikor ödla"}},{q="Varför måste hoven lämnas till Orgrimmar?",a="Hoven förs till Horde-huvudstaden Orgrimmar som ett fysiskt bevis på att odjuret har besegrats och visar upp jägarens seger för staden.",al={"varför ta hoven till orgrimmar","lämna in halikor's hoof","vart ska hoven"}},{q="Hur får man Halikor's Hoof?",a="Halikor's Hoof tas direkt från Halikors kropp efter att du har spårat upp och dödat den massiva ödlan i strid.",al={"hur får man halikor's hoof","halikor byte"}},{q="Varför har en ödla en hov?",a="Halikor är ingen vanlig ödla, utan ett mäktigt vildmarksmonster, och dess enorma hov är trofén som bevisar att du fällde den. Ingen har sagt varför den har en hov.",al={"har halikor hovar","varför har en ödla hovar"}},{q="Vem i Orgrimmar vill ha Halikor's Hoof?",a="Du bär hoven tillbaka till Orgrimmar som bevis på din seger. Ingen enskild jägare eller ämbetsman har utsetts att ta emot den.",al={"vem tar emot halikor's hoof i orgrimmar","lämna in halikor's hoof i orgrimmar"}},{q="Vad är berättelsen bakom uppdraget Halikor's Hoof?",a="Halikor's Hoof är ett uppdrag som handlar om att besegra den kolossala ödlan Halikor. Att bära dess enorma, avhuggna hov till Orgrimmar visar jägarens stridskonst och förmedlar nyheten om odjurets död till Horde.",al={"vad är uppdraget halikor's hoof","berättelsen om halikor's hoof"}}},fp="14,235,24.357.0,21.337.0,16.181.0,44.146.0,31.121.0,30.176.0,38.115.0,50.222.0"}
P.entries["quest:96895"] = {n="The Argent Emissary",s="The Argent Emissary markerar ankomsten av två Forsaken-representanter för Argent Dawn, som spårar Scourge-kultister nära Undercity. Deras närvaro visar både den gemensamma kampen mot Scourge och den pyrande spänningen mellan den neutrala orden och Forsakens myndigheter.",h="The Argent Emissary markerar ankomsten av två Forsaken-representanter för Argent Dawn, som spårar...",kw={"argent dawn","argent-sändebud","kultister","forsaken","scourge-kultister","tirisfal glades","undercity"},ang={["faction:Horde"]="Argent Dawn är neutrala, men Horde-myndigheterna håller noga uppsikt över deras självständiga verksamhet nära Undercity.",["race:Undead"]="Att se andra Forsaken välja Argent Dawn framför Undercity påminner tydligt om de delade lojaliteterna bland de fria odöda."},sec={{t="Ett avvaktande välkomnande",b="Två Forsaken-sändebud från Argent Dawn har nyligen anlänt till Tirisfal Glades och gjort de lokala myndigheterna nervösa. Även om Argent Dawn bekämpar Scourge är de lokala Forsaken misstänksamma mot varje beväpnad, neutral orden som verkar utan tillsyn på deras suveräna territorium. Inte ens sändebudens gemensamma ursprung stillar deras vaksamhet särskilt mycket."},{t="Kultister vid portarna",b="Sändebuden kom inte för att beundra ruinerna av Lordaeron; de förföljer en grupp Scourge-kultister som upptäckts lura sydost om Undercity, i stadens utkanter. Fast besluten att röja undan Lich Kings agenter innan de får fäste har ett av sändebuden intagit en position nära stadsportarna för att hålla fiendens rörelser under uppsikt."}},faq={{q="Vilka är Argent-sändebuden?",a="Två sändebud som representerar Argent Dawn reste nyligen till Tirisfal Glades. Båda dessa sändebud är Forsaken som har anslutit sig till den heliga och neutrala orden i stället för att enbart tjäna Undercity.",al={"vilka är sändebuden","besökare från argent dawn","vilka kom till tirisfal"}},{q="Varför verkar Argent Dawn nära Undercity?",a="De spårar Scourge-kultister som setts smyga omkring i utkanterna sydost om Undercity. Argent Dawn har åtagit sig att jaga Scourges kvarlevor var de än dyker upp, även nära stora bosättningar tillhörande Horde.",al={"varför är de nära undercity","argent dawns uppdrag i tirisfal","vad gör sändebuden"}},{q="Varför är de lokala Forsaken misstänksamma mot sändebuden?",a="Trots att Argent Dawn bekämpar den gemensamma fienden Scourge tycker de lokala Forsaken inte om att neutrala, beväpnade organisationer verkar utan tillsyn i Tirisfal Glades, oavsett om sändebuden delar deras odöda tillstånd.",al={"varför är man orolig för argent dawn","kan argent dawn litas på","forsakens syn på argent dawn"}},{q="Vilket hot utgör kultisterna?",a="En grupp Scourge-kultister har setts lura sydost om stadens utkanter. Eftersom Lich King fortfarande utgör ett hot mot de fria odöda väckte deras närvaro genast uppmärksamhet hos både lokala spejare och Argent Dawn.",al={"kultister utanför undercity","scourge i tirisfal","vilka är kultisterna"}},{q="Vart tog sändebudet vägen?",a="Ett av sändebuden rörde sig sydost mot ingången till Undercity och skuggade Scourge-kultisternas rörelser precis utanför stadsmurarna.",al={"var hittar man sändebudet","sändebudets plats","hitta en medlem av argent dawn"}},{q="Tjänar Forsaken i Argent Dawn?",a="Ja. Till skillnad från Scarlet Crusade välkomnar Argent Dawn alla som är villiga att kämpa mot Scourge, däribland viljestarka odöda som viger sig åt saken.",al={"får forsaken gå med i argent dawn","argent dawns odöda","kan odöda gå med i argent dawn"}}},fp="19,285,12.370.0,21.360.0,30.233.0,52.219.0,46.234.0,41.244.0,26.162.0,41.174.0"}
P.entries["quest:96896"] = {n="A Righteous Cause",s="A Righteous Cause skildrar ett samtal mellan Leonid Barthalomew the Revered och Danitha Morr, där de minns försvaret av Undercity mot Naxxramas. De talar om Garek Bandarion, en odöd hjälte som återupptäckte hur man kunde använda det heliga ljuset som paladin. Berättelsen lyfter fram de sällsynta Forsaken som försöker bevara sin kontakt med ljuset trots sina fränders skepsis.",h="A Righteous Cause skildrar ett samtal mellan Leonid Barthalomew the Revered och Danitha Morr, där de minns...",kw={"danitha morr","forsaken","garek bandarion","leonid barthalomew","light's hope chapel","naxxramas","paladin","righteous cause","scourge","undercity"},ang={["class:Paladin"]="Garek Bandarion och Danithas grupp står för en anmärkningsvärd utveckling: Forsaken återupptäcker hur de kan använda det heliga ljuset som paladiner trots att de är odöda.",["faction:Horde"]="Leonid Barthalomews närvaro visar banden mellan Undercitys försvarare och Argent Dawn, som har sitt högkvarter vid Light's Hope Chapel i Plaguelands.",["race:Undead"]="Leonid och Danitha försöker återknyta kontakten med ljuset, men de flesta Forsaken håller sig fortfarande på avstånd från den heliga vägen eller är fientliga mot den i sitt odöda liv."},sec={{t="Veteranernas återseende",b="A Righteous Cause skildrar ett gripande återseende mellan två veteraner som försvarade Lordaeron: Leonid Barthalomew the Revered och Danitha Morr. De överlevde den fruktansvärda attacken då Naxxramas släppte lös Scourge mot Undercity. Nu minns de sina fallna kamrater och den svåra väg som Forsaken som fortfarande vördar det heliga ljuset har valt."},{t="Garek Bandarions arv",b="Deras gemensamma minnen kretsar kring Garek Bandarion, den fallne hjälte som fästningen fick sitt namn efter. Enligt Leonid kan Garek ha varit den allra första av Forsaken som återupptäckte hur man använder det heliga ljuset som en sann paladin. De flesta Forsaken har vänt ljuset helt ryggen, men Danitha och hennes följeslagare ägnar sig åt att bevara Gareks arv och utforska möjligheten till ett heligt odött liv."},{t="Tillbaka till Plaguelands",b="Efter samtalet med Danitha förbereder sig Leonid på att lämna fästningen. Hans lojalitet ligger hos den pågående kampen mot Scourge i det härjade österlandet, där han tjänstgör vid Light's Hope Chapel i Eastern Plaguelands och välkomnar alla äventyrslystna som är starka nog att ta till vapen för saken."}},faq={{q="Vem är Leonid Barthalomew the Revered?",a="Leonid Barthalomew the Revered är en framstående odöd medlem av Argent Dawn. Han verkar från Light's Hope Chapel i Eastern Plaguelands, men håller kontakten med sina tidigare kamrater i Lordaeron, som kämpade tillsammans med honom mot Scourge.",al={"vem är leonid barthalomew","leonid the revered","leonid barthalomew historia"}},{q="Vem är Danitha Morr?",a="Danitha Morr är en ledare bland Forsaken som kämpade vid Leonid Barthalomews sida under Scourges attack mot Undercity. Nu leder hon en grupp som är hängiven åt att föra Garek Bandarions lära och heliga arv vidare.",al={"vem är danitha morr","danitha","danitha morr historia"}},{q="Vem var Garek Bandarion?",a="Garek Bandarion var en hjältemodig krigare bland Forsaken som föll när Naxxramas anföll Undercity. Leonid nämner att han kan ha varit den allra första Forsaken som återupptäckte hur man använder det heliga ljuset som paladin.",al={"vem är garek bandarion","garek bandarion historia","fästning uppkallad efter"}},{q="Vad hände under attacken mot Undercity?",a="När nekropolen Naxxramas gick till angrepp mot Undercity samlades mästare bland Forsaken, däribland Danitha Morr, Leonid Barthalomew och Garek Bandarion, för att försvara staden mot Scourges anfall. De led stora förluster i striden.",al={"naxxramas attack mot undercity","försvaret av undercity","scourges attack mot undercity"}},{q="Kan Forsaken använda ljuset som paladiner?",a="Att kanalisera ljuset orsakar en olidlig smärta i odött kött, och de flesta Forsaken avvisar det. Garek Bandarion visade ändå att en odöd krigare kan använda det heliga ljuset som paladin, något som Danitha och hennes följeslagare fortsätter att studera.",al={"kan forsaken bli paladiner","odöd paladin historia","forsaken som använder ljuset"}},{q="Vart beger sig Leonid Barthalomew efter det här?",a="Efter att ha besökt sina vänner och talat med Danitha Morr planerar Leonid att återvända till Light's Hope Chapel i Eastern Plaguelands, där Argent Dawn samordnar sitt fälttåg mot Scourge.",al={"vart beger sig leonid","hitta leonid senare","leonid vid lights hope chapel"}}},fp="17,426,19.353.0,29.416.0,25.311.0,38.251.0,20.220.0,24.225.0,49.261.0,45.270.0,44.201.0"}
P.entries["quest:96897"] = {n="The Cult of the Damned",s="The Cult of the Damned är en uppgift som ställs inför Scourges dödliga tjänare i Tirisfal Glades. Genom att rensa ut Dark Neophytes och Dark Enforcers hindrar försvararna Lich Kings lömska levande agenter från att upprepa förräderierna som en gång krossade Lordaeron.",h="The Cult of the Damned är en uppgift som ställs inför Scourges dödliga tjänare i Tirisfal Glades.",kw={"the cult of the damned","dark enforcers","dark neophytes","levande tjänare","lordaeron","nekromanti","scourge","tirisfal glades"},ang={["class:Paladin"]="Paladiner svor eder om att utrota skuggan som krossade Lordaeron, vilket gör levande sektmedlemmar som helhjärtat tjänar Scourge till Ljusets svurna fiender.",["class:Priest"]="Präster av alla inriktningar känner igen den förvridning av tron som The Cult of the Damned står för. Sekten byter helig hängivenhet mot mörk nekromanti.",["race:Undead"]="De Förfallna vet alltför väl hur de levande sektmedlemmarna ödelade Lordaeron och orsakade deras odödhet. Att stoppa nya sektceller i Tirisfal är avgörande för att säkra det nya kungariket."},sec={{t="Scourges dödliga agenter",b="The Cult of the Damned är Scourges mänskliga ansikte. Sekten består av levande män och kvinnor som svurit trohet till Lich King, och verkar där de tanklösa döda inte kan. I Tirisfal Glades, där invånarna redan kämpar mot kringströvande odöda och Scarlet Crusades obevekliga fanatiker, visar nyupptäckta celler av Dark Neophytes och Dark Enforcers att Scourge lömskt försöker återfå fotfäste."},{t="Lärdomar av fallet",b="Lordaeron lades i ruiner inte bara av de dödas framryckande legioner, utan också av grannar som förrådde varandra. The Cult of the Damned infiltrerade ursprungligen byar, förgiftade spannmålsförråd och iscensatte rikets fall från skuggorna. Det är nödvändigt att hålla vakt mot ny verksamhet från sekten i Tirisfal för att förhindra att historien upprepar sig i nordens sargade länder."}},faq={{q="Vad är The Cult of the Damned?",a="The Cult of the Damned är en organisation av dödliga som villigt tjänar Lich King och Scourge. I stället för att uppväckas som tanklösa odöda sprider dessa levande lärjungar medvetet pest, saboterar försvar och utövar nekromanti i dödens tjänst.",al={"vad är the cult of the damned","vilka är sektmedlemmarna","vilka är dark neophytes"}},{q="Varför verkar sektmedlemmar i Tirisfal Glades?",a="Tirisfal Glades är fortfarande ett omstritt gränsland hemsökt av tanklösa odöda, Scarlet Crusades fanatiker och kvarvarande enklaver av Scourges inflytande. Sekten verkar i hemlighet i regionen för att undergräva det lokala motståndet och främja Scourges mörka planer.",al={"varför finns sekten i tirisfal","sekten i tirisfal glades"}},{q="Vilka är Dark Neophytes och Dark Enforcers?",a="Dark Neophytes är nya invigda som lär sig mörka konster och ritualer, medan Dark Enforcers står för muskelkraften som bevakar sektens verksamhet och upprätthåller disciplinen bland medlemmarna. Tillsammans bildar de aktiva celler ute på fältet.",al={"vilka är dark enforcers","dark neophytes uppgift"}},{q="Varför anses levande tjänare vara värre än tanklösa odöda?",a="Tanklösa odöda handlar enbart på instinkt eller direkt order, men levande sektmedlemmar har med full insikt valt förräderiet. De kan smälta in i dödligas samhällen och infiltrera bosättningar, vilket gör dem mycket lömskare än kringströvande gastar eller skelett.",al={"varför är levande sektmedlemmar värre","levande tjänare åt scourge"}},{q="Vad innebär uppdraget med att inte låta Lordaerons historia upprepa sig?",a="Lordaeron föll inte enbart genom en öppen invasion utifrån, utan för att The Cult of the Damned i tysthet förgiftade spannmålsförråden och förrådde sina medborgare inifrån. Om sekten tillåts få fotfäste riskerar samma katastrof att inträffa igen.",al={"lordaerons historia upprepas","sektens roll i lordaerons fall"}},{q="Hur förhåller sig sekten till Scarlet Crusade i Tirisfal?",a="Scarlet Crusade jagar fanatiskt allt som besudlats av odödhet och ser därför både Scourge och sekten som huvudmål. Den pågående konflikten lämnar invånarna fångade mellan tanklösa fasor, fanatiska korsfarare och hemliga sektmedlemmar.",al={"förhållandet till scarlet crusade","sekten mot scarlet crusade"}}},fp="22,276,28.432.0,19.400.0,31.262.0,57.261.0,46.233.0,62.256.0,74.239.0,60.241.0"}
P.entries["quest:96898"] = {n="Remnants of War",s="Remnants of War ger äventyrare i uppdrag att återfinna krossade skärvor av den nekrotiska fokuseringskristall som sprängdes bort från Naxxramas under anfallet mot Undercity. Både Forsaken och Argent Dawn led stora förluster när de slog tillbaka citadellet, och insamlingen av dessa farliga fragment hindrar Scourge-kultister från att återta sin mörka magi.",h="Remnants of War ger äventyrare i uppdrag att återfinna krossade skärvor av den nekrotiska fokuseringskristall...",kw={"argent dawn","kultister","forsaken","naxxramas","fragment av nekrotisk kristall","remnants of war","scourge","tirisfal glades","undercity"},ang={["class:Mage"]="Trots att Naxxramas nekrotiska fokuseringskristaller är trasiga och till stor del förbrukade behåller de instabil magisk energi som kräver yttersta försiktighet.",["class:Priest"]="Den kvarvarande oheliga korruptionen i de nekrotiska skärvorna är en farlig pest som måste hållas i schack innan den vanhelgar landet ytterligare.",["faction:Horde"]="Att skydda Tirisfal Glades mot kvarvarande Scourge-magi bidrar till att säkra Undercity och Horde viktiga fäste i norra Lordaeron.",["race:Undead"]="Naxxramas anfall hotade Undercitys själva existens. När du återfinner fragmenten skyddar du ditt folk mot ett nytt Scourge-angrepp alldeles inpå knuten."},sec={{t="Skuggan över staden",b="För inte länge sedan tornade skräckcitadellet Naxxramas upp sig rakt över Tirisfal Glades och försökte utplåna Undercity och Forsaken för gott. I ett desperat försvar slog Forsaken och Argent Dawn tillbaka den svävande fästningen till ett högt pris. Under striden förstördes den väldiga nekrotiska fokuseringskristallen högst upp på Naxxramas, och skärvor spreds över gläntorna nedanför."},{t="Spridd nekromanti",b="Citadellet drevs bort, men resterna finns kvar i marken. Scourge-kultister har kommit dit för att hämta fragmenten av den nekrotiska kristallen och hoppas kunna utnyttja den mörka magi som fortfarande dröjer sig kvar i dem. Genom att samla in skärvorna berövar du Scourge rå, ohelig kraft, men det kommer att ta år att rensa bort varenda bit från Tirisfal."}},faq={{q="Vad är fragmenten av den nekrotiska kristallen?",a="De är krossade bitar av den väldiga nekrotiska fokuseringskristall som en gång satt högst upp på det svävande skräckcitadellet Naxxramas. När kristallen förstördes under anfallet mot Undercity regnade skärvor ner över Tirisfal Glades.",al={"vad är fragment av nekrotisk kristall","vad är kristallerna","nekrotiska kristaller"}},{q="Varför anföll Naxxramas Undercity?",a="Naxxramas sänkte sig över Tirisfal Glades med det uttalade målet att förinta Undercity och utplåna Forsaken. Ett gemensamt försvar från Forsaken och Argent Dawn drev bort citadellet, men båda fraktionerna led stora förluster.",al={"varför anföll naxxramas","naxxramas anföll undercity","vad gjorde naxxramas här"}},{q="Varför samlar Scourge-kultister in kristallfragmenten?",a="Scourge-kultister genomsöker Tirisfal Glades efter de krossade fragmenten. Trots att kristallerna är trasiga och förbrukade innehåller de fortfarande nekrotisk magi som Scourge kan ta till vara på eller använda i sina oheliga ritualer.",al={"varför vill kultister ha kristallerna","vad vill kultister ha skärvor till","scourge-kultister och kristaller"}},{q="Är det farligt att hantera de nekrotiska kristallerna?",a="Ja. Trots att fragmenten är trasiga och till stor del tömda på sin ursprungliga kraft hyser de fortfarande potent och flyktig nekrotisk energi, vilket gör direkt fysisk kontakt farlig.",al={"är kristallerna farliga att röra vid","fysisk kontakt med kristallen","kan nekrotiska kristaller skada dig"}},{q="Vilka hjälpte Forsaken att slå tillbaka Naxxramas?",a="I striden om att försvara Undercity kämpade Forsaken sida vid sida med Argent Dawn mot Naxxramas styrkor. De led stora förluster för att säkra Forsakens överlevnad.",al={"vilka stred mot naxxramas","vem försvarade undercity","argent dawns försvar av undercity"}},{q="Kommer alla nekrotiska kristaller någonsin att rensas bort från Tirisfal?",a="Det är osannolikt att området rensas snabbt. Eftersom den väldiga kristallen splittrades högt ovanför gläntorna spreds fragment överallt, så invånarna kommer troligen att gräva upp skärvor ur marken i åratal.",al={"kommer tirisfal att bli fritt från kristaller","kan alla fragment rensas bort","kristaller kvar i tirisfal"}}},fp="15,339,24.390.0,20.338.0,40.233.0,39.249.0,58.217.0,44.176.0,44.194.0,61.228.0"}
P.entries["quest:96899"] = {n="Bandarion Keep",s="Bandarion Keep är ett uppdrag i Tirisfal Glades där äventyrare ska möta Argent Dawn-befälhavaren Leonid Barthalomew vid en avskild fästning. Borgen var en gång en bas för Argent Dawn i kampen mot Scourge, men sköts nu om av Danitha och hennes paladinorden.",h="Bandarion Keep är ett uppdrag i Tirisfal Glades där äventyrare ska möta Argent Dawn-befälhavaren Leonid...",kw={"argent dawn","bandarion keep","cult of the damned","danitha","leonid barthalomew","paladin","scourge","tirisfal glades"},ang={["class:Paladin"]="Bandarion Keep är en borg som förvaltas av Danitha och hennes paladinkamrater, en helig bastion mot mörka krafter i Tirisfal Glades."},sec={{t="En kallelse till borgen",b="Bandarion Keep är ett uppdrag från Argent Dawn som leder äventyrare genom Tirisfal Glades för att möta befälhavaren Leonid Barthalomew. Efter att ha hjälpt Argent Dawn mot Cult of the Damned riktas resenärer nordväst mot fästningen för att möta befälhavaren och få veta mer om ordens pågående korståg mot mörkret."},{t="Historia och förvaltning",b="Borgen tjänade en gång som en viktig utpost för Argent Dawn när de bekämpade Scourges intrång i Tirisfal Glades. När Argent Dawn riktade sin uppmärksamhet mot Eastern och Western Plaguelands lämnades fortet åt sitt öde och riskerade att förfalla, tills paladinen Danitha och hennes följeslagare tog över ansvaret för dess murar."},{t="Minnen av en gemensam vän",b="När Leonid Barthalomew återförenas med äventyrarna vid fästningen minns befälhavaren striderna som utkämpades från dess murar. Han är lättad över att borgen inte har förfallit, men konstaterar att Danitha gav den dess namn till minne av en gemensam vän."}},faq={{q="Vem är Leonid Barthalomew?",a="Leonid Barthalomew är befälhavare i Argent Dawn. Han använde tidigare Bandarion Keep som bas under tidigare Scourge-intrång i Tirisfal Glades och har återvänt dit för att möta Danitha och hennes paladiner.",al={"vem är leonid barthalomew","var finns leonid barthalomew","leonid bandarion keep"}},{q="Vad är Bandarion Keep?",a="Bandarion Keep är en fästning i västra Tirisfal Glades. Den var ursprungligen en utpost för Argent Dawn under Scourges angrepp, men förföll när orden drog sig tillbaka till Plaguelands. Därefter återställde Danithas paladiner fästningen och tog den i sin vård.",al={"vad är bandarion keep","bandarion keep historia","vem håller bandarion keep"}},{q="Vem är Danitha?",a="Danitha är en paladin som tillsammans med sin orden tog över ansvaret för Bandarion Keep efter att Argent Dawn drog sig österut till Plaguelands. Hon gav också borgen dess namn till minne av en gemensam vän till henne och Leonid Barthalomew.",al={"vem är danitha","danitha paladin","vem sköter bandarion keep"}},{q="Varför heter den Bandarion Keep?",a="Danitha gav fästningen dess namn för att hedra en gemensam vän till henne och befälhavaren Leonid Barthalomew.",al={"varför fick den namnet bandarion keep","vem är bandarion","betydelsen av namnet bandarion"}},{q="Varför är Argent Dawn intresserade av Bandarion Keep?",a="Medlemmar av Argent Dawn reser till Bandarion Keep för att samordna sig med Danithas paladiner och hålla vakt mot Scourge-styrkor och Cult of the Damned i Tirisfal Glades.",al={"varför resa till bandarion keep","argent dawn tirisfal glades","bandarion keep argent dawn"}},{q="Varför övergav Argent Dawn borgen tidigare?",a="Argent Dawn drog sig tillbaka från fästningen när de flyttade sina huvudstyrkor österut för att bekämpa Scourge i Plaguelands. Byggnaden stod tom tills Danitha och hennes paladiner tog över ansvaret för den.",al={"vad hände med borgen efter kriget","varför lämnade argent dawn bandarion keep"}}},fp="14,264,21.335.0,23.351.0,27.268.1,26.218.0,23.246.0,15.226.0,32.113.0,52.192.0,52.215.0"}
P.entries["quest:96988"] = {n="Source of Power",s="Source of Power är ett uppdrag i Undercity, beställt av Doctor Martin Felben, som vill dra nytta av oron i Dalaran. Den magiska staden belägras av sina egna förryckta konstruktioner, och Felben skickar äventyrare att säkra deras mystiska kärnor. Han vill förena Dalarans magiska teknologi med de Fördömdas köttformning för att skapa mystiska styggelser och få Mörkerdamens uppmärksamhet.",h="Source of Power är ett uppdrag i Undercity, beställt av Doctor Martin Felben, som vill dra nytta av oron i...",kw={"styggelser","mystiska konstruktioner","cracked sentry core","dalaran","doctor martin felben","royal apothecary society","source of power","sylvanas windrunner","undercity"},ang={["class:Mage"]="Magiker ser nog en bister ironi i att Dalarans magiska konstruktioner vänder sig mot sina herrar, bara för att deras avancerade mystiska kraftkällor ska plundras och användas i fasansfulla alkemiska experiment i Undercity.",["faction:Horde"]="Hordens äventyrare i Lordaeron stöder de Fördömdas försök att säkra avancerad militär utrustning mot sina omgivande rivaler medan Dalaran lamslås av sina egna förryckta skapelser.",["profession:Engineering"]="Ingenjörer kan uppskatta det intrikata hantverket bakom Dalarans självständiga vaktposter, samtidigt som deras ömtåliga mystiska kraftkärnor slits ut för att driva fasansfulla köttformade styggelser.",["race:Undead"]="De Fördömda förlitar sig tungt på Royal Apothecary Societys hänsynslösa innovationer för att överleva i Lordaeron. Om du hjälper Doctor Felben främjar du fraktionens forskning om mystisk köttformning under Mörkerdamens uppsikt."},sec={{t="En opportunistisk skörd",b="Kaoset i den magiska staden Dalaran har öppnat en möjlighet som de Fördömda gärna utnyttjar. Dalarans egna mystiska konstruktioner löper amok och belägrar magikerna, och Doctor Martin Felben ser en gyllene möjlighet i tumultet. I stället för att hjälpa de belägrade trollkarlarna vill apotekaren skaffa sig de mystiska kärnor som driver de förryckta väktarna. Dalaran har länge vaktat sin magiska forskning svartsjukt, men stadens nuvarande utsatthet gör dess förtrollade vaktposter till ett lätt byte för opportunistiska forskare från Undercity."},{t="Ambitioner i apotekarsällskapet",b="Doctor Felben intresserar sig för de spruckna vaktpostkärnorna enbart för att främja sina egna ambitioner inom Royal Apothecary Society. Felben drömmer om att skapa en förödande armé av mystiskt drivna köttbestar genom att infundera de Fördömdas styggelser med den instabila magin från Dalarans konstruktioner. Han räknar med att ett sådant fasansfullt genombrott skulle få Lady Sylvanas Windrunners odelade uppmärksamhet och visa hans oöverträffade alkemiska genialitet. I slutändan hoppas Felben att skapelsen ska höja hans anseende rejält, kanske till och med ge honom ledningen över Royal Apothecary Society, en fraktion där hänsynslös slughet och imponerande resultat avgör vem som överlever och klättrar i graderna."}},faq={{q="Vem ger uppdraget Source of Power?",a="Uppdraget ges av Doctor Martin Felben, en apotekare som bor i de Fördömdas huvudstad Undercity. Felben är en ambitiös forskare som vill bevisa sin alkemiska talang för Royal Apothecary Society och Lady Sylvanas Windrunner genom att utveckla helt nya militära monster.",al={"vem ger source of power","uppdragsgivare för source of power","martin felben uppdrag"}},{q="Vad händer i Dalaran under uppdraget?",a="Dalaran belägras just nu av sina egna mystiska konstruktioner, som har vänt sig mot sina skapare. Kaoset och striderna i den magiska staden skapar en sällsynt möjlighet för utomstående att ta sig in i Dalaran och bärga de kraftfulla magiska komponenter som driver de förryckta vaktposterna.",al={"vad hände i dalaran","dalaran belägras","varför anfaller konstruktioner dalaran"}},{q="Varför vill Doctor Felben ha konstruktionskärnorna?",a="Doctor Felben tänker använda den mystiska energin i Dalarans vaktpostkärnor för att förstärka de Fördömdas styggelser. Genom att förena rå mystisk teknologi med köttformning hoppas han skapa en armé av mystiskt drivna styggelser som bevisar hans alkemiska mästerskap för Lady Sylvanas Windrunner.",al={"varför samla vaktpostkärnor","vad ska felben ha kärnorna till","felbens plan med vaktpostkärnorna"}},{q="Vad är målen för Source of Power?",a="Äventyrarna får i uppgift att ta sig in i staden Dalaran, konfrontera de förryckta konstruktionerna och samla sex Cracked Sentry Cores. När de har fått tag på dessa instabila magiska reliker måste de föra dem tillbaka till Doctor Martin Felben i Undercity, så att de kan användas i hans pågående experiment.",al={"målen för source of power","hur många kärnor behöver jag","vad ska jag samla till source of power"}},{q="Vad är Doctor Felbens mål inom Royal Apothecary Society?",a="Doctor Martin Felben vill bli erkänd och snabbt avancera i de Fördömdas hierarki. Genom att ge Lady Sylvanas Windrunner en mäktig styrka av mystiskt infunderade styggelser hoppas han imponera på Mörkerdamen tillräckligt för att bli utsedd till ledare för Royal Apothecary Society.",al={"felbens mål med apotekarsällskapet","vem leder royal apothecary society","felben vill imponera på mörkerdamen"}},{q="Varför plundrar de Fördömda Dalarans teknologi?",a="Royal Apothecary Society och de Fördömda söker ständigt efter okonventionella vapen och kraftkällor för att säkra sin överlevnad i Lordaeron. Genom att utnyttja den magiska staden Dalaran medan dess försvar faller samman inifrån kan de Fördömdas apotekare skaffa avancerade mystiska komponenter utan att formellt gå i öppet krig mot magikerna.",al={"varför vill de fördömda ha dalarans magi","undercity dalarans konstruktioner","de fördömdas intresse för dalaran"}},{q="Var finns Cracked Sentry Cores?",a="Cracked Sentry Cores samlas från de förryckta konstruktioner som just nu belägrar staden Dalaran. Spelare måste strida mot dessa fientliga, förtrollade väktare runtom i den magiska staden för att få tag på de intakta komponenter som Doctor Felben behöver för sin forskning i Undercity.",al={"var hittar jag cracked sentry cores","plats för cracked sentry core","dalarans vaktpostkärnor byte"}}},fp="15,407,24.594.0,34.676.0,36.287.0,47.296.0,48.294.0,44.276.0,65.281.0,53.344.0,41.282.0"}
P.entries["quest:97"] = {n="The Legend of Stalvan",s="Det här steget i utredningen bekräftar äntligen den kusliga sanningen som knyter den svårfunne läraren till Darkshires register. Clerk Daltry lyckas matcha handstilen i de återfunna dokumenten med Stalvan Mistmantles, och rapporterar genast detta till Commander Althea Ebonlocke. Night Watchs misstankar blir nu obestridliga fakta.",h="Det här steget i utredningen bekräftar äntligen den kusliga sanningen som knyter den svårfunne läraren till...",kw={"althea ebonlocke","clerk daltry","darkshire","duskwood","handstil","mistmantle","night watch","stalvan"},ang={["faction:Alliance"]="För alliansens utredare visar Stalvans spår hur viktigt samarbetet är mellan Darkshires hårt prövade ledning och kringvandrande äventyrare för att hålla rikets södra områden säkra.",["race:Human"]="Mänskliga spelare ser här hur deras eget samhälle tragiskt förfaller, när både aktade lärare och små byar tyst glider från civilisationen in i vansinne och isolering."},sec={{t="En matchning i registren",b="Efter att ha sökt igenom avlägsna herrgårdar, värdshus och kommunala arkiv i människornas riken leder det splittrade spåret tillbaka till Darkshires rådhus. Clerk Daltry jämför den blodfläckade dagbokssidan med namnteckningarna i stadens register. Resultatet är entydigt: handstilen tillhör Stalvan Mistmantle, vilket ger Night Watch de konkreta bevis som behövs för att behandla saken som ett akut lokalt hot."},{t="Night Watchs misstankar",b="Commander Althea Ebonlocke hade haft mörka aningar om Stalvan ända sedan utredningen började. Duskwood dignar redan under vilda worgens, skelettliknande odöda och lurande nekromantiker; en mördare som gömmer sig i skogens skuggor och inte kan redovisas är en fara hon inte kan ignorera. Bekräftelsen från Daltry besannas hennes värsta farhågor och får Night Watch att börja söka efter eremiten för att en gång för alla hitta och oskadliggöra honom."}},faq={{q="Vad upptäckte Clerk Daltry?",a="Clerk Daltry jämförde den blodfläckade dagbokssidan med namnteckningarna i Darkshires register och bekräftade att handstilen exakt matchade Stalvan Mistmantles, precis som Commander Ebonlocke misstänkte.",al={"vad hittade daltry","daltrys handstilsjämförelse","bevis för stalvans handstil"}},{q="Varför bryr sig Commander Althea Ebonlocke så mycket om Stalvan?",a="Commander Althea Ebonlocke leder Night Watch, Darkshires hårt ansatta milis. I ett land som redan plågas av fasor kan hon inte låta en våldsam, skuggfull person med ett mörkt förflutet gå lös och hålla sig undan inom Duskwoods gränser.",al={"varför bryr sig althea","ebonlockes utredning","night watch stalvan"}},{q="Var utspelar sig det här steget?",a="Hela det här steget utspelar sig i staden Darkshire. Clerk Daltry håller till i rådhuset, medan Commander Althea Ebonlocke patrullerar på stadens centrala gator i närheten.",al={"var är uppdraget","uppdragsplats","lämna in stalvan darkshire"}},{q="Vad händer när handstilen har rapporterats som en matchning?",a="När Commander Ebonlocke får bekräftelsen från Clerk Daltry går utredningen vidare till att aktivt leta efter Stalvans nuvarande vistelseort i Duskwoods hemsökta vildmark.",al={"vad händer sedan med stalvan","efter daltrys matchning","nästa steg i stalvan-kedjan"}},{q="Vem var Stalvan Mistmantle från början?",a="Stalvan Mistmantle undervisade en gång på Moonbrook schoolhouse och arbetade senare som privatlärare åt Flintridge-familjens barn. Spåret av hans brev och dagbokssidor går från Moonbrook och Goldshire tillbaka till Duskwood, där han nu lever som en farlig eremit i skogen.",al={"vem är stalvan","stalvans bakgrund","stalvan mistmantles historia"}},{q="Varför behövdes en handstilsanalys?",a="Eftersom händelserna och anklagelserna kring Stalvan utspelade sig i olika områden, däribland Moonbrook och Goldshire, var de officiella uppgifterna splittrade. Darkshires kommunala register innehöll verifierade lokala handskriftsprov som kunde knyta de utländska ledtrådarna till just den här mannen.",al={"varför jämföra handstilar","varför kontrollerade daltry handstilen","bevisa stalvans identitet"}}},fx={cc1b58e5={q="Varför är Clerk Daltry så angelägen om att du ska rapportera till Commander Ebonlocke?",a="Clerk Daltry för stadens register. Han är ingen officer i Nattväktarna, och bekräftelsen på att handstilen tillhör Stalvan Mistmantle styrker Commander Ebonlockes allvarliga misstankar. Daltry inser att en officiell mordutredning kräver omedelbar väpnad myndighet. Därför måste Althea få avgörande bevis utan dröjsmål.",al={"varför vill daltry att detta görs","daltrys motiv","varför rapportera till althea"}}},fp="21,363,22.413.0,28.456.1,31.220.0,63.241.0,32.202.0,51.186.0,38.289.0,39.282.0"}
P.entries["quest:970"] = {n="The Tower of Althalaxx",s="Det här uppdraget markerar en avgörande vändning i utredningen av den ondskefulla Cult of the Dark Strand. Jakten flyttas från det förfallna Tower of Althalaxx i Darkshore över gränsen till Maestra's Post i Ashenvale. Delgren the Purifier skickar äventyrare till närliggande kultistläger för att säkra en kraftfull Glowing Soul Gem. När artefakten dechiffreras avslöjas den mörka trolldom som ger kulten inflytande över de norra skogarna.",h="Det här uppdraget markerar en avgörande vändning i utredningen av den ondskefulla Cult of the Dark Strand.",kw={"althalaxx","ashenvale","dark strand","darkshore","delgren","delgren the purifier","glowing soul gem","maestra's post","ordil'aran"},ang={["class:Paladin"]="Att rena mörka själskärl och dräpa förvridna kultister stämmer väl med paladinens plikt att rensa världen från ohelig korruption.",["class:Priest"]="Att undersöka ett mörkt själskärl påminner om prästens kall att bekämpa korruption och skänka tröst åt plågade själar.",["faction:Alliance"]="Samordning mellan utposter i Darkshore och Ashenvale säkrar den norra gränsen mot mörka magiutövare som hotar Alliansens resenärer.",["race:NightElf"]="När vidriga kultister skändar gamla ruiner som Ordil'Aran och fördärvar de norra skogarna blir det högsta prioritet för varje nattalv att utplåna Cult of the Dark Strand."},sec={{t="En vädjan över gränsen",b="Efter att ha upptäckt den olycksbådande verksamheten kring Tower of Althalaxx i norra Darkshore ledde rapporterna rakt söderut till Delgren the Purifier i Ashenvale. Delgren är stationerad vid Maestra's Post och har länge bekämpat Cult of the Dark Strand, som tränger in i de gamla alvskogarna. När han inser att kultens hot sträcker sig över båda områdena beslutar han sig för att slå mot hjärtat av deras vidriga trolldom."},{t="Ordil'Arans hemligheter",b="Nordost om Maestra's Post ligger ruinerna av Ordil'Aran, som nu är översvämmade av fanatiska Dark Strand-kultister. Delgren konstaterar att deras agenter bär på lysande soul gems, mörka kärl förtrollade med ondskefull magi som upprätthåller kultens kraft. Genom att jaga kultisterna bland ruinerna och återta en sådan ädelsten tänker Delgren bryta förtrollningen och avslöja den verkliga källan till deras illvilliga ritual."},{t="En fångad ande",b="När Delgren tyder de avskyvärda förtrollningarna i den lysande soul gem avslöjar han mer än mörka besvärjelser. Han blottlägger ett kärl av plåga. När ädelstenens skydd bryts frigörs Sargaths ande. Sargath var en av alverna i Ameth'Aran, som Athrikus Narassin fångade i soul gems under Sunderingen och sedan dess långsamt har tömt på kraft. Vålnaden nämner Athrikus löjtnant, Ilkrud Magthrull, vars bok kan avslöja var de återstående soul gems hålls."}},faq={{q="Var hittar jag Glowing Soul Gem?",a="Glowing Soul Gem innehas av medlemmar i Cult of the Dark Strand nordost om Maestra's Post, vid ruinerna av Ordil'Aran i Ashenvale. Olika kultister som håller till bland ruinerna bär den, men det kan krävas en del ihärdighet för att få tag på en.",al={"soul gem plats","var faller soul gem","dark strand soul gem"}},{q="Vem är Delgren the Purifier?",a="Delgren the Purifier är en hjälte för Alliansen, stationerad vid Maestra's Post i norra Ashenvale. Han bekämpar aktivt de ondskefulla krafter som invaderar skogen, med särskilt fokus på att spåra upp och förgöra Cult of the Dark Strand.",al={"delgren","vem är delgren"}},{q="Vad är Cult of the Dark Strand?",a="Cult of the Dark Strand är en ondskefull sekt som verkar från Tower of Althalaxx i Darkshore och gamla alvruiner som Ordil'Aran i Ashenvale. De utövar mörk trolldom, själsbindning och nekromantiska ritualer.",al={"dark strand-kult","vilka är dark strand"}},{q="Varför skickar ett uppdrag i Darkshore mig till Ashenvale?",a="Utredningen börjar vid Tower of Althalaxx i Darkshore, men kultens nätverk sträcker sig söderut över gränsen in i Ashenvale. Delgren the Purifier vid Maestra's Post har den sakkunskap som krävs för att motverka kultens själsbindande magi.",al={"varför maestra's post","varför åka till ashenvale"}},{q="Vad händer när soul gem tyds?",a="Delgren tänker tyda den mörka förtrollningen på Glowing Soul Gem. Vad han upptäcker avslöjas när du har gett honom ädelstenen.",al={"vad finns i soul gem","spöke i soul gem"}},{q="Var ligger Ordil'Aran?",a="Ordil'Aran är en gammal alvruin strax nordost om Maestra's Post i norra Ashenvale. Platsen är för närvarande hemsökt av Cult of the Dark Strand.",al={"ordil'aran plats","var ligger ordilaran"}}},fx={a63b3648={q="Varför vill Delgren the Purifier att det här görs?",a="Delgren har legat i strid med Cult of the Dark Strand, som har befäst sig nordost om Maestra's Post. För honom är de en farlig nagel i ögat som måste ryckas upp med rötterna. De allvarliga varningarna i Balthule Shadowstrikes brev bekräftar att deras korrumperande inflytande växer. Delgren tror att det enda sättet att avslöja och krossa deras makt är att nysta upp hemligheterna i deras förtrollade själsädelsten.",al={"delgrens motiv","varför vill delgren ha soul gem","varför bekämpa cult of the dark strand"}},c112c454={q="Vad ska Glowing Soul Gem användas till?",a="Glowing Soul Gem är en mörk, förtrollad artefakt som Cult of the Dark Strand bär vid Ordil'Aran. Delgren tror att den rymmer hemligheten bakom kultens vidriga magi och deras krafter. När du för med dig ädelstenen till honom kan Delgren tyda de mörka förtrollningarna i stenen och upptäcka vilken essens eller varelse som är fångad därinne.",al={"vad är glowing soul gem","glowing soul gems syfte","soul gem dark strand"}},d0742ede={q="Vem skickas du för att möta vid Ordil'Aran?",a="Du skickas för att konfrontera Cult of the Dark Strand, som håller till i ruinerna av Ordil'Aran, nordost om Maestra's Post. Kultister, fanatiker, akolytter och skickliga magiker har samlats bland alvruinerna för att utföra förbjudna riter. En av dem bär på en förtrollad själsten som Delgren behöver för att låsa upp kultens hemligheter. Du måste kämpa dig igenom deras led tills reliken är återfunnen.",al={"vem finns vid ordil'aran","dark strand vid ordil'aran","vem har soul gem"}}},fp="22,428,24.417.0,25.426.0,16.471.1,37.251.0,28.239.0,36.222.0,49.245.0,45.132.1,28.151.0"}
P.entries["quest:97003"] = {n="Chol'aruk the Ravener",s="Chol'aruk the Ravener är en jakt i The Barrens på en väldig quilboar som sägs bo i en grotta vid Thorn Hill. Efter möten med liknande bestar tror orchen Gur'ak på de skrämmande berättelserna och skickar äventyrare att trotsa dess håla och ta med dess huvud tillbaka.",h="Chol'aruk the Ravener är en jakt i The Barrens på en väldig quilboar som sägs bo i en grotta vid Thorn Hill.",kw={"the barrens","chol'aruk","cholaruk","gur'ak","gurak","quilboar","razormane","ravener","thorn hill"},ang={["class:Hunter"]="Att spåra upp en monstruös best som sägs vara fem gånger större än vanliga quilboar kräver en jägares skarpa instinkter och förberedelser inför ett mäktigt byte.",["class:Warrior"]="Att möta en brutal varelse med omättlig blodtörst kräver frontkrigare som är beredda att stå emot överväldigande fysisk vrede.",["faction:Horde"]="Orchen Gur'ak manar till strid med Hordens traditionella stridsrop ”Blod och åska” och ger äventyrarna i uppdrag att fälla ett farligt hot som lurar i The Barrens."},sec={{t="Legenden om Ravener",b="I The Barrens torra vidder viskar Razormane-quilboar om Chol'aruk, en enorm skräck som kallas ”The Ravener”. Enligt rykten i trakten har denna mardrömslika best sin håla djupt inne i en grotta vid Thorn Hill, nordost om de lokala stigarna. Quilboar hävdar att den är ungefär fem gånger så stor som en vanlig quilboar och drivs av en våldsam, omättlig blodtörst. Många avfärdar sådana historier som överdrivna lägereldsberättelser, men Gur'ak vet bättre efter tidigare strider mot liknande vidunder."},{t="Gur'aks varning",b="Gur'ak inser den verkliga faran med en best av sådan storlek och skickar dugliga resenärer att spåra den till dess underjordiska håla i Thorn Hill. Hans instruktioner är tydliga: gör slut på vidundret och återvänd med dess huvud som obestridligt bevis. Med tanke på Chol'aruks omtalade vildsinthet och väldiga storlek varnar Gur'ak strängt för att bara väl förberedda grupper bör våga sig in i grottan och möta Ravener."}},faq={{q="Vem är Chol'aruk the Ravener?",a="Chol'aruk, som Razormane-stammen också kallar The Ravener, är en legendarisk och monstruös quilboar. Den sägs vara fem gånger så stor som vanliga quilboar, har en omättlig blodtörst och håller till i en djup grotta i The Barrens.",al={"vem är cholaruk","vad är cholaruk","ravener"}},{q="Var hittar man Chol'aruk?",a="Chol'aruk håller till djupt inne i en grotta vid Thorn Hill, nordost om Gur'aks läger i The Barrens. Äventyrare måste ta sig in i grottorna vid Thorn Hill för att hitta dess håla.",al={"var finns cholaruk","cholaruks plats","var ligger grottan vid thorn hill"}},{q="Vem ger jakten på Chol'aruk?",a="Gur'ak, en orch som finns i The Barrens, ger uppdraget. Till skillnad från andra som avfärdar berättelserna om jättebesten som rent krogprat tror Gur'ak på ryktena, eftersom han har mött liknande vidunder tidigare.",al={"vem ger cholaruk-uppdraget","vem är gurak","gurak i the barrens"}},{q="Varför jagar Gur'ak Chol'aruk?",a="Gur'ak vill att Chol'aruk dödas för att undanröja ett vildsint hot som terroriserar trakten. Han kräver bestens avhuggna huvud som bevis på att Ravener har fallit.",al={"varför döda cholaruk","varför har cholaruk en belöning"}},{q="Bör jag slåss mot Chol'aruk ensam?",a="Gur'ak varnar uttryckligen resenärer för att söka upp Chol'aruk ensamma. Med tanke på dess omtalade enorma storlek och vildsinta blodtörst är jakten på Ravener tänkt som en svår utmaning för ett väl förberett jaktlag.",al={"kan jag klara cholaruk ensam","är cholaruk svår","ta med en grupp mot cholaruk"}},{q="Hur hänger Chol'aruk ihop med Razormane-quilboar?",a="Quilboar är vildsvinslika humanoider som hör hemma på centrala Kalimdors slätter, och Razormane-stammen bor i delar av The Barrens. Razormane själva talar om Chol'aruk med skräck och har gett besten titeln ”The Ravener”.",al={"vad är quilboar","razormane och cholaruk","varför fruktar razormane honom"}}},fp="21,271,25.527.0,16.438.0,29.242.0,29.177.0,34.209.0,32.159.0,31.222.0,68.230.0"}
P.entries["quest:97005"] = {n="Chol'aruk the Ravener",s="En fasa stryker omkring i en grotta på Thorn Hill i The Barrens, där Razormane kallar den Chol'aruk the Ravener. Bainham söker dess avhuggna huvud för att hämnas kamrater som föll offer för liknande bestar.",h="En fasa stryker omkring i en grotta på Thorn Hill i The Barrens, där Razormane kallar den Chol'aruk the...",kw={"vidunder","bainham","the barrens","chol'aruk","razormane","the ravener","thorn hill"},ang={["class:Hunter"]="Som jägare sätts din skicklighet och ditt mod på prov när du spårar ett rovdjur som sägs kunna svälja fullständigt bepansrade krigare hela.",["class:Warrior"]="Som krigare kan du svara på Bainhams upprop genom att möta en väldig fasa i dess underjordiska lya och hämnas fallna kamrater.",["faction:Horde"]="Ohämmade monster på de höga platåerna hotar resenärer och karavaner som färdas genom The Barrens. Att döda besten skulle bidra till att skydda regionen."},sec={{t="Skräcken på Thorn Hill",b="Nordväst om Bainhams läger i The Barrens reser sig Thorn Hill över savannen. Razormane-stammar har länge stridit om platån. Nu går rykten om en monstruös styggelse i en av dess grottor, som Razormane kallar Chol'aruk eller the Ravener. Vissa resenärer avfärdar berättelserna om att den kan svälja en bepansrad orc hel. De som har sett förödelsen vet att faran är verklig."},{t="En gammal oförrätt",b="Bainham vet att Chol'aruk inte är någon lägereldssaga. Han har kämpat mot liknande fasor och bär ärr från mötena, samtidigt som han sörjer kamrater som föll för sådana bestar. Han fruktar att styggelsen hotar alla som färdas över savannen. Bainham ber erfarna kämpar att bestiga Thorn Hill, ta sig in i dess underjordiska lya, döda Chol'aruk och föra tillbaka dess väldiga huvud."}},faq={{q="Vad är Chol'aruk för slags varelse?",a="Chol'aruk är en monstruös styggelse i en grotta på Thorn Hill. Rykten säger att den är stor nog att svälja en vuxen orc hel, och de lokala Razormane kallar den the Ravener.",al={"vad är cholaruk","cholaruks monstertyp","vem är the ravener"}},{q="Var ligger Chol'aruks lya?",a="Chol'aruk håller till i en grotta på Thorn Hills höga platå, nordväst i The Barrens.",al={"var finns cholaruk","cholaruks plats","grottan på thorn hill"}},{q="Vem är Bainham och varför vill han att Chol'aruk ska dö?",a="Bainham bor i The Barrens och har kämpat mot liknande bestar. Han vill se Chol'aruk död eftersom han förlorade allierade till sådana styggelser och söker hämnd för sina fallna kamrater.",al={"vem ger uppdraget om cholaruk","varför döda cholaruk","bainhams bakgrund"}},{q="Vad betyder ”The Ravener”?",a="De lokala Razormane quilboar kallar Chol'aruk the Ravener, ett namn som anspelar på dess glupska natur. Rykten säger att den slukar fullvuxna krigare hela.",al={"vad betyder cholaruk","varför kallas den ravener","razormane cholaruk"}},{q="Tillber eller fruktar Razormane quilboar Chol'aruk?",a="Det är okänt om Razormane quilboar fruktar eller dyrkar Chol'aruk. De kallar den Chol'aruk eller the Ravener, men inget mer är känt om deras känslor inför styggelsen i grottan på Thorn Hill.",al={"gillar quilboar cholaruk","razormane och cholaruk"}},{q="Vilket bevis krävs för att bekräfta Chol'aruks död?",a="Bainham ber dig föra tillbaka Chol'aruks avhuggna huvud som bevis på att den är död.",al={"lämna in cholaruk-uppdraget","vad ska jag ta med till bainham"}}},fp="21,177,20.375.0,15.359.0,35.166.0,34.86.0,51.172.0,29.141.0,52.196.0,52.78.0"}
P.entries["quest:971"] = {n="Knowledge in the Deeps",s="Knowledge in the Deeps är ett alliansuppdrag som Gerrig Bonegrip erbjuder i Forlorn Cavern i Ironforge. Han skickar äventyrare över havet till de sjunkna ruinerna av Blackfathom Deeps i Ashenvale för att hämta det uråldriga Lorgalis Manuscript. Bakom Bonegrips lärda fasad döljer sig en illavarslande agenda med kopplingar till mörka väsen och apokalyptiska profetior.",h="Knowledge in the Deeps är ett alliansuppdrag som Gerrig Bonegrip erbjuder i Forlorn Cavern i Ironforge.",kw={"ashenvale","blackfathom deeps","forlorn cavern","gerrig bonegrip","ironforge","knowledge in the deeps","lorgalis manuscript"},ang={["class:Warlock"]="Bonegrip verkar sida vid sida med häxmästarna som gömmer sig i Forlorn Cavern i Ironforge. De delar hans hunger efter förbjudna texter som kan böja själva verklighetens plan.",["faction:Alliance"]="Det verkar ofarligt att hjälpa en allianslärd, men Bonegrips verkliga motiv och skuggaktiga medarbetare antyder mörkare planer inom Ironforges murar.",["race:NightElf"]="Manuskriptet ligger i Blackfathom Deeps, en översvämmad nattalvsk helgedom som nu ockuperas av kultister och andra inkräktare."},sec={{t="En lärd i skuggorna",b="Undangömd i de fuktiga delarna av Forlorn Cavern i Ironforge utger sig Gerrig Bonegrip för att vara en hängiven samlare av uråldriga texter. Ändå har hans lärda sysslor en tydligt kuslig underton. Bonegrip intresserar sig inte för vardaglig historia eller stadskrönikor; han jagar uttryckligen bortglömd kunskap som kan öppna dörrar och väcka ”Those Who Sleep”. Hans tal om att överleva ”de sista dagarna” får honom att framstå som excentrisk – eller som en farlig anhängare av dunkla, slumrande krafter."},{t="Lorgalis sjunkna ruin",b="Bonegrip skickar kunskapssökare halvvägs över Azeroth till Ashenvales skuggiga stränder, där nattalvernas uråldriga helgedom Blackfathom Deeps ligger under vatten. Innan den stora klyvningen slet Kalimdor i stycken samlade nattalvernas lärda enorma magiska kunskaper i sina kusttempel. Bland de översvämmade gångarna, som nu kryllar av naga, satyrer och kultister från Twilight's Hammer, vilar Lorgalis Manuscript – en text med förbjuden kunskap som förvaras i en Pitted Iron Chest."},{t="Bröder och systrar",b="När Bonegrip får det vattendränkta manuskriptet gör han inget försök att arkivera det i Hall of Explorers i Ironforge. I stället gläds han öppet åt att kopior ska framställas och spridas bland hans mystiska ”bröder och systrar”. Bonegrip är tacksam mot alliansäventyraren som hämtade det, men hans lojalitet ligger tydligt hos en hemlig sekt som vill använda den återfunna kunskapen i esoteriska riter som kan förändra världen. Bonegrip har kopplingar till Twilight's Hammer, vars anhängare söker förbjuden kunskap om de gamla gudarna."}},faq={{q="Vem ger uppdraget Knowledge in the Deeps?",a="Uppdraget ges av Gerrig Bonegrip, en dvärg som söker kunskap och bor i den dunkla Forlorn Cavern i dvärgarnas bergsstad Ironforge.",al={"uppdragsgivare","var får man uppdraget","vem startar knowledge in the deeps"}},{q="Vad är Lorgalis Manuscript?",a="Lorgalis Manuscript är en text som Gerrig Bonegrip vill att du hämtar från Blackfathom Deeps. Den förvaras i en Pitted Iron Chest bland de översvämmade ruinerna.",al={"vad är lorgalis manuscript","lorgalis kunskap","vilken bok ska jag hitta"}},{q="Var finns Lorgalis Manuscript?",a="Manuskriptet ligger djupt inne i grottan Blackfathom Deeps, vid Zoram Strand på Ashenvales nordvästra kust i Kalimdor.",al={"lorgalis manuscript plats","var finns boken i bfd","bfd bok plats"}},{q="Vilka är ”Those Who Sleep” som Gerrig Bonegrip nämner?",a="Bonegrip använder detta gåtfulla namn om de slumrande krafter som beskrivs i den förbjudna kunskap han samlar på. Uppdragets skyddade avsnitt utforskar hans mörkare kopplingar.",al={"those who sleep","vem syftar bonegrip på","vad dyrkar gerrig"}},{q="Vilka är ”bröderna och systrarna” som Gerrig tänker dela manuskriptet med?",a="Bonegrips medarbetare delar hans intresse för förbjuden kunskap. Om du hämtar manuskriptet kan du få veta mer om vem han tjänar.",al={"gerrigs bröder och systrar","vem arbetar gerrig för","bonegrips fraktion"}},{q="Varför skickar ett uppdrag i Ironforge spelare ända till Ashenvale?",a="Forlorn Cavern i Ironforge lockar till sig obehöriga magiutövare, häxmästare och skurkar som söker hemligheter dolda för ljuset. Bonegrip samlar på gammal och mäktig kunskap, och ryktet säger att Lorgalis Manuscript, som han vill åt, ligger på botten av Blackfathom Deeps i Ashenvale, de sedan länge döda alvernas forna hem där de en gång ägde stor kunskap.",al={"varför åka till ashenvale","uppdrag från ironforge till bfd","resa till blackfathom"}}},fx={["32faf93b"]={q="Varför vill Gerrig Bonegrip ha Lorgalis Manuscript?",a="Gerrig Bonegrip samlar på uråldriga, kraftfulla texter som kan öppna bortglömda dörrar och väcka Those Who Sleep. Han tror att Lorgalis Manuscript innehåller sedan länge förlorade hemligheter från de forntida nattalverna i Blackfathom Deeps. Han tänker kopiera och sprida dess mörka kunskap bland sina hemlighetsfulla bröder och systrar innan den kommande undergången.",al={"gerrig bonegrips motiv","varför vill gerrig ha manuskriptet","varför ger gerrig bonegrip uppdraget"}}},fp="22,354,24.495.0,27.469.0,20.538.1,43.154.0,32.148.0,41.146.0,55.165.0,77.123.1,68.325.0"}
P.entries["quest:972"] = {n="Water Sapta",s="Vid Islen Waterseers strand får en ung shaman från Horde Water Sapta inför en resa över Great Sea. Provet leder från The Barrens till Silverpine Forest, där en källa har blivit korrumperad.",h="Vid Islen Waterseers strand får en ung shaman från Horde Water Sapta inför en resa över Great Sea.",kw={"call of water","islen waterseer","shamanprövning","silverpine forest","the barrens","totemuppdrag","water sapta"},ang={["class:Shaman"]="Som shaman tar du ett avgörande steg i dina elementära prövningar med Water Sapta. Den öppnar dina ögon för andevärlden innan du får makt över din helande Water Totem.",["faction:Horde"]="Som medlem av Horde ser du hur det här provet skickar noviser från Kalimdors solblekta slätter till Lordaerons hemsökta skogar."},sec={{t="En vattenvision",b="Bland shamaner från Horde är en sapta en dryck som öppnar sinnena för världens andar. För vanliga ögon kan en bäck se lugn ut och en damm stilla. Drick en sapta, så skingras den fysiska världens slöja och visar elementalerna som lever i vattnet."},{t="Vägen till Silverpine",b="Islen Waterseer ger shamanen drycken efter att hen har visat sin hängivenhet till andarna. Hon bor ensam på den karga stranden söder om Ratchet. Hon skickar novisen över Great Sea, bort från Kalimdors torra dalar, till Silverpine Forest. Där förgiftar en elementär korrumpering Lordaerons vattendrag, och shamanen måste möta den."}},faq={{q="Vad är en vattensapta?",a="En sapta är en ceremoniell dryck som shamanernas mentorer bereder. När shamanen dricker den skärps den andliga synen, så att hen kan se och tala med elementaler som är dolda för dödliga ögon.",al={"vad är sapta","vattensaptans betydelse","vad gör sapta"}},{q="Vem är Islen Waterseer?",a="Islen Waterseer är en mästershaman som bor ensam på The Barrens östra kust, söder om The Merchant Coast. Hon vägleder unga shamaner från Horde på den svåra vägen mot att komma i kontakt med och binda vattenelementet.",al={"islen waterseers bakgrund","vem är islen"}},{q="Varför måste shamanen resa till Silverpine Forest?",a="Vattnets elementaler lider av en utbredd plåga i Silverpine Forest. För att slutföra sin invigning bär shamaner sapta över havet och ser en korrumperad vattenkälla med egna ögon, innan de renar den från dess smitta.",al={"varför silverpine","varför resa till eastern kingdoms"}},{q="Vad händer efter att man druckit saptan?",a="Efter att ha druckit sapta kan shamaner se de korrumperade vattenelementalerna i Silverpine Forests förorenade pölar. Den synen öppnar vägen för att konfrontera källan till förfallet.",al={"dricka sapta","saptans effekt"}},{q="Krävs den här prövningen av alla hord-shamaner?",a="Ja. Orc-, tauren- och trollshamaner följer alla Call of Water och tar emot sapta som en övergångsrit innan de får sin Water Totem.",al={"vem tar uppdraget","är det här ett klassuppdrag"}},{q="Var i Silverpine ligger den fördärvade pölen?",a="Den korrumperade källan ligger vid Silverpine Forests kust, väster om The Sepulcher.",al={"silverpines pöls läge","var finns vattenpölen"}}},fx={c8d11240={q="Varför skickar Islen Waterseer dig till Silverpine?",a="Islen Waterseer vill vägleda dig genom din andliga övergångsrit och hjälpa dig att stämma dig till vattnets elementkrafter. För att vinna gemenskap med vattnets andar och fullborda Call of Water måste du möta och rena den besmittelse som plågar världens vattenleder. Hon har gett dig en förberedd Water Sapta, så att du själv kan uppfatta dold elementär korruption och visa din hängivenhet som en blivande schaman.",al={"varför vill islen att detta görs","islen waterseers motiv","varför rena det fördärvade vattnet"}}},fp="11,195,17.252.0,22.346.0,22.172.0,23.204.0,48.219.0,38.164.0,44.138.0,50.78.0"}
P.entries["quest:97220"] = {n="Philmor's Favor",s="Philmor's Favor är ett leveransuppdrag i Stormwind som beror på en pågående brist på hamnarbetare. Kurirer ombeds transportera en ömtålig Gatehouse-försändelse till en avskild förrådsingång på andra våningen i Trias' Cheese i Trade District.",h="Philmor's Favor är ett leveransuppdrag i Stormwind som beror på en pågående brist på hamnarbetare.",kw={"elaine","gatehouse","gatehouse-försändelse","philmor","philmor's favor","stormwind","trade district","trias' cheese"},ang={["faction:Alliance"]="När du hjälper till med leveranser i hela Stormwinds Trade District hålls stadens logistik i gång medan det råder brist på hamnarbetare."},sec={{t="Ansträngd logistik i Stormwind",b="En ihållande brist på hamnarbetare i Stormwind har satt stadens vanliga fraktverksamhet under press. För att hålla de lokala fraktschemat i fas söker lasthanterare pålitliga resenärer som kan bära känsliga lådor direkt till handelsdistriktet."},{t="Diskreta leveranser hos Trias' Cheese",b="Försändelsen är adresserad till Gatehouse, men avlämningen är allt annat än vanlig. I stället för att passera genom huvudingången till vakthuset bärs lådan upp till andra våningen i Trias' Cheese i Trade District. Butiken döljer en förrådsingång som används för att i tysthet föra in förnödenheter och ceremoniella gåvor till vaktofficerarna, utom nyfikna blickar."}},faq={{q="Vem behöver hjälp med leveransen?",a="Uppdraget erbjuds för att avlasta fraktschemat i Stormwind när den lokala verksamheten har ont om hamnarbetare.",al={"vem ger philmor's favor","philmor uppdragsgivare"}},{q="Var ska leveransen lämnas?",a="Försändelsen ska lämnas vid Gatehouses förrådsingång, som nås via andra våningen i Trias' Cheese i Stormwinds Trade District.",al={"var ska jag lämna paketet","leverans till trias' cheese","var finns ingången till gatehouse"}},{q="Vem tar emot försändelsen?",a="Elaine är föreståndaren för Trias' Cheese och är van vid att hantera diskreta fraktleveranser till det intilliggande förrådet vid Gatehouse.",al={"vem är elaine","elaine trias' cheese"}},{q="Vad innehåller Gatehouse-försändelsen?",a="Försändelsen innehåller ömtåliga varor avsedda för Gatehouse. Enligt lokala lasthanterare sker leveranser ofta med särskild diskretion för att möjliggöra ceremoniella överraskningar som ordnas för vaktofficerare.",al={"vad finns i paketet","gatehouse leveransinnehåll"}},{q="Varför nås ett militärt förråd via en ostbutik?",a="På övervåningen i Trias' Cheese finns en ingång till förrådet vid Gatehouse. Den ger möjlighet till diskret passage och avlämning av gods utan att varorna förs genom militärens huvudingång.",al={"varför trias' cheese och gatehouse","hemlig ingång trias' cheese"}},{q="Varför råder det brist på hamnarbetare?",a="Personalbrist har gjort att det saknas folk bland hamn- och lasthanterarna under hela veckan. Därför måste logistikansvariga förlita sig på förbipasserande resenärer för att hålla leveranserna i tid.",al={"varför brist på hamnarbetare","brist på hamnarbetare i stormwind"}}},fp="15,268,31.262.0,36.382.0,34.118.0,34.167.0,26.147.0,38.202.0,59.193.0,34.182.0"}
P.entries["quest:97222"] = {n="Gatehouse Goods",s="Gatehouse Goods är ett lokalt uppdrag i Stormwind där en försändelse ska bäras uppför trapporna i Trias' Cheese. Eftersom ostbutiken delar våningsplan med den intilliggande portvaktsbyggnaden kan varorna diskret lämnas utanför förrådsdörren, så att vakterna kan hämta dem. Arrangemanget visar hur tätt Stormwinds handels- och försvarskvarter är sammanlänkade.",h="Gatehouse Goods är ett lokalt uppdrag i Stormwind där en försändelse ska bäras uppför trapporna i Trias'...",kw={"leverans","elling trias","gatehouse goods","försändelse till portvaktsbyggnaden","förråd","stormwind","trias cheese"},ang={["class:Rogue"]="För den som värdesätter diskretion är det självklart att röra sig tyst kring Trias' Cheese och lägga märke till diskreta arkitektoniska detaljer som dörrar som öppnas inåt.",["faction:Alliance"]="Diskreta leveranser via Trias' Cheese hjälper till att hålla varuflödet igång mellan lokala handlare i Stormwind och personalen i den intilliggande portvaktsbyggnaden."},sec={{t="Gemensamma kvarter och våningsplan",b="Gatehouse Goods är en enkel leverans mitt i Stormwinds livliga gator. Arbetet går ut på att bära en försändelse till portvaktsbyggnaden uppför trapporna inne i Trias' Cheese. Den berömda ostbutiken är en helt fristående verksamhet med eget lager, men byggnaden delar våningsplan med den närliggande portvaktsbyggnaden. Den här arkitektoniska egenheten gör butikens övre avsats till en praktisk passage för att flytta förnödenheter mellan kvarteren utan att störa de stora gatorna."},{t="En praktisk avlämning",b="Rutinen för leveransen är tydlig: budbärarna måste lämna lådan precis utanför förrådsdörren i stället för att bära in den. Portvaktsbyggnadens vakter håller uppsikt över ankommande gods och ser till att någon hämtar paketen när de återvänder till sina poster. Dessutom är förrådsdörren byggd med gångjärn som gör att den öppnas inåt, så att varor som ställs utanför aldrig blockerar ingången eller hindrar dem där inne från att röra sig fritt."}},faq={{q="Vad är Gatehouse Goods?",a="Gatehouse Goods är ett lokalt leveransärende i Stormwind som rör Trias' Cheese och den intilliggande portvaktsbyggnaden. Ett bud ombeds bära en försändelse uppför trapporna och lämna den utanför portvaktsbyggnadens förrådsdörr.",al={"vad är gatehouse goods","uppdraget gatehouse goods"}},{q="Var ska försändelsen lämnas?",a="Leveransen ska uppför trapporna inne i Trias' Cheese. Trias' Cheese är en självständig verksamhet, men byggnaden delar våningsplan med portvaktsbyggnaden, så varorna kan lämnas direkt utanför dess förråd.",al={"trias cheese portvaktsbyggnad","vart går leveransen"}},{q="Varför lämnas lådan utanför dörren i stället för att bäras in?",a="Mottagaren instruerar budet att lämna lådan utanför förrådsdörren i stället för att bära in den. Portvakterna märker att den har anlänt och skickar någon som hämtar den när de återvänder till sin post.",al={"varför lämna utanför","vem hämtar lådan"}},{q="Varför öppnas förrådsdörren inåt?",a="Förrådsdörrens gångjärn gör att den öppnas inåt, så att paket och varor som lämnas utanför dörröppningen inte blockerar dörren eller stänger in någon.",al={"inåtgående dörr trias","förrådsdörrens gångjärn"}},{q="Har Trias' Cheese någon koppling till portvaktsbyggnaden?",a="Nej, Trias' Cheese tillhör inte portvaktsbyggnaden och delar inte dess lager. De två verksamheterna delar dock våningsplan, vilket gör trapporna där uppe till en praktisk plats för överlämning.",al={"tillhör trias cheese portvaktsbyggnaden","trias cheese lager"}},{q="Vem ansvarar för leveransen av varorna?",a="Uppdraget ordnas av lokala företrädare som förväntar sig professionell respekt och ömsesidig diskretion. De tackar pålitliga bud när avlämningen har genomförts utan att blockera dörröppningen.",al={"vem ger gatehouse goods","vem tar emot leveransen"}}},fp="15,378,33.531.0,20.455.0,24.213.0,47.214.0,65.245.0,40.142.0,47.194.0,39.207.0"}
P.entries["quest:97223"] = {n="Bloodtalon Matriarch",s="Bloodtalon Matriarch är ledaren för en snabb och listig rovfågelhjord nära Sen'jin Village. Eftersom hon visat sig vara för farlig och envis för att tämjas som vuxen måste hon konfronteras, så att hennes avkomma kan kläckas ur äggen och växa upp som lojala följeslagare åt Darkspear-stammen.",h="Bloodtalon Matriarch är ledaren för en snabb och listig rovfågelhjord nära Sen'jin Village.",kw={"bloodtalon","darkspear","matriark","rovfågel","rovfågelägg","rovfåglar","sen'jin village","sen'jin","trollens riddjur"},ang={["class:Hunter"]="Jägare känner till hur svårt det är att tämja fullvuxna vilddjur och hur viktigt det är att föda upp rovdjur från födseln för att skapa ett verkligt band.",["faction:Horde"]="Att föda upp lokala rovdjur till lojala allierade hjälper till att skydda Darkspear-bosättningen och stärker Hordens närvaro längs Durotars kust.",["race:Troll"]="Darkspear-trollen i Sen'jin Village uppskattar rovfåglar som smidiga följeslagare och krigsmounts och värdesätter Bloodtalon-släktets list och snabbhet."},sec={{t="Bloodtalon-släktet",b="Bloodtalon-hjorden är känd längs Durotars kust för sin enastående snabbhet och skarpa list. Skötarna i Sen'jin Village värdesätter dessa egenskaper högre än allt annat när de söker pålitliga riddjur och följeslagare åt Darkspear-stammen. Fullvuxna rovfåglar har dock envisa och våldsamma instinkter, vilket gör vuxna djur nästan omöjliga att tämja när de väl vant sig vid ett liv i det vilda."},{t="Bevara blodslinjen",b="Trots flera försök att fånga och träna matriarken blev hennes allt värre aggression ett direkt hot mot området omkring henne. För att skydda stammen och samtidigt bevara hennes enastående blodslinje beslutade trollen att oskadliggöra den farliga modern och rädda hennes kull, så att nästa generation kan växa upp ur äggen som lojala allierade."}},faq={{q="Vem är Bloodtalon Matriarch?",a="Bloodtalon Matriarch är en våldsam, vuxen rovfågel vars hjord är känd för sin snabbhet och list. Tidigare försök gjordes att fånga och träna henne, men till slut blev hon alldeles för farlig att hantera, så Darkspear-trollen beslutade att ta hand om hennes ägg i stället.",al={"vem är bloodtalon matriarch","bloodtalon-rovfågelns matriark","rovfågelmatriark"}},{q="Varför måste Bloodtalon Matriarch tas om hand?",a="Vuxna rovfåglar är ökända för att vara svåra att tämja, och matriarken blev ett alltför stort hot mot bosättningen i närheten. Genom att betvinga henne och samla in hennes kull kan skötarna i Sen'jin Village undanröja faran och samtidigt bevara hennes blodslinje.",al={"varför döda matriarken","varför samla in ägg","varför jaga matriarken"}},{q="Varför tämjer man inte matriarken i stället?",a="Vuxna rovfåglar har våldsamma, otämjbara instinkter som gör dem nästan omöjliga att träna när de väl är fullvuxna. Skötarna lyckas mycket bättre när de tar äggen och låter ungarna växa upp tillsammans med sina blivande följeslagare.",al={"kan vuxna rovfåglar tämjas","träna vuxen rovfågel"}},{q="Vad händer med matriarkens avkomma?",a="Den insamlade kullen förs tillbaka till Sen'jin Village för att ruvas och födas upp. Trollen tänker träna de unga rovfåglarna från födseln, så att de blir pålitliga allierade och riddjur åt stammen.",al={"vad händer med äggen","matriarkens ungar","rovfåglar i sen'jin"}},{q="Var utspelar sig det här uppdraget?",a="Uppdraget utspelar sig kring Sen'jin Village, Darkspear-trollens kustnära fristad i södra Durotar, där skötarna arbetar med att föda upp lojala rovfåglar åt sitt folk.",al={"var lämnas uppdraget in","rovfågeluppdrag i sen'jin village"}},{q="Vad gör Bloodtalon-hjorden speciell?",a="Bloodtalon-rovfåglarna uppskattas särskilt för sin snabbhet och intelligens. Dessa egenskaper gör deras blodslinje mycket eftertraktad hos följeslagare och riddjur, förutsatt att de tränas innan deras vilda instinkter tar över.",al={"bloodtalon-rovfåglarnas egenskaper","varför bloodtalon-rovfåglar"}}},fp="20,280,22.393.0,24.386.0,32.262.0,48.249.0,35.230.0,46.200.0,29.175.0,39.231.0"}
P.entries["quest:97225"] = {n="Forgotten Loa Idols",s="Forgotten Loa Idols handlar om att återfinna heliga religiösa avbilder åt Darkspear Trolls. Dessa förlorade reliker behövs snarast för att återuppta viktiga andliga ceremonier och bevara stammens vördnadsfulla band till sina beskyddande vildandar.",h="Forgotten Loa Idols handlar om att återfinna heliga religiösa avbilder åt Darkspear Trolls.",kw={"darkspear","forgotten loa idols","avgudar","loa","vördnad","ritualer","andar","troll"},ang={["class:Priest"]="Trollpräster och häxdoktorer förlitar sig direkt på ritualer och heliga föremål från förfäderna för att kanalisera andlig kraft och hedra loa.",["class:Shaman"]="Shamanistiska sedvänjor åkallar elementarkrafter, medan trollens andliga ledare hyser djup vördnad för de vilda gudarna och förfädernas loa, som är knutna till stammens överlevnad.",["faction:Horde"]="Darkspear är en av Hordens grundande medlemmar, och genom att hjälpa deras heliga äldste att bevara viktiga religiösa föremål stärks stammens enhet inom fraktionen.",["race:Troll"]="För Darkspear Trolls står samvaron med loa i centrum för det andliga livet. Att återfinna förlorade avgudar gör att viktiga ritualer kan fortsätta och att stammen behåller andarnas välvilja."},sec={{t="Heliga lämningar efter loa",b="För Darkspear Trolls är den andliga balansen oupplösligt knuten till deras relation till loa, de ursprungliga djurandarna och vilda gudarna i deras förfäders arv. Forgotten Loa Idols går ut på att återfinna förlagda religiösa reliker som är nödvändiga för stammens ceremonier. Utan dessa heliga föremål kan de andliga ledarna inte utföra riterna som krävs för att bevara harmonin med deras gudomliga beskyddare."},{t="Bandet till loa",b="Medan flera fientliga trollfraktioner runt om i Azeroth utövar blodsoffer eller försöker tvinga andarna till lydnad, är Darkspear stolta över sitt band av ömsesidig respekt och ödmjuk vördnad. För Darkspear är det en allvarlig katastrof att förlora sina beskyddares välvilja, så att återbörda de förlorade avgudarna är en viktig handling för att bevara stammen."}},faq={{q="Vad är syftet med Forgotten Loa Idols?",a="Forgotten Loa Idols är ett uppdrag åt Darkspear Trolls för att återfinna saknade heliga avbilder. Avgudarna behövs för att återuppta viktiga stamriter och bevara aktningen hos deras vördade vildandar.",al={"forgotten loa idols","vad är det här för uppdrag","vad är forgotten loa idols"}},{q="Vad är loa?",a="Loa är uråldriga, mäktiga ursprungsandar och djurgudomar som trollen vördar. Trollens kultur hedrar dem med offergåvor, böner och rituella ceremonier i utbyte mot beskydd, välvilja och andlig vägledning.",al={"vad är loa","trollgudar","vilka är loa"}},{q="Hur ser Darkspear på sina loa jämfört med andra trollstammar?",a="Till skillnad från mer brutala trollstammar som försöker kuva eller offra till mörka gudomar, ser Darkspear sitt släktskap med loa som något präglat av djup vördnad, ömsesidig respekt och andlig plikt. De tror att deras överlevnad beror på att de behåller andarnas välvilja.",al={"darkspears relation till loa","varför vörda loa","andra stammars loa"}},{q="Varför behövs avgudarna för stamritualerna?",a="Avgudarna fungerar som invigda fokuspunkter för stammens ritualer. Utan dem kan de äldste och andliga ledarna inte utföra riterna ordentligt för att komma i kontakt med och hedra sina beskyddande andar.",al={"varför behövs avgudarna","loa-avgudarnas syfte","varför är avgudar viktiga"}},{q="Varför är det så viktigt för Darkspear att behålla loa:s välvilja?",a="Darkspears äldste fruktar att stammen kan förlora loa:s välvilja och beskyddande välsignelser utan de rätta riterna och offergåvorna. Då skulle stammen vara sårbar i en redan farofylld värld.",al={"vad händer om de inte återlämnas","förlora någons välvilja","darkspears loa-välvilja"}},{q="Vem vill få tillbaka Forgotten Loa Idols?",a="Uppdraget ges av en andlig vägvisare från Darkspear Trolls, som är angelägen om att återuppta gemensamma ceremonier och säkra välsignelserna från stammens förfäders beskyddare.",al={"vem ger forgotten loa idols","uppdragsgivare","vem ber om avgudarna"}}},fp="19,252,26.411.0,18.367.0,43.208.0,13.216.0,67.267.0,44.193.0,57.191.0,48.161.0"}
P.entries["quest:97234"] = {n="Reading Room",s="Reading Room kretsar kring ett utbyte mellan Roy's Book Club och biblioteket i Stormwind. Äventyrare hjälper klubben genom att leverera ett inslaget paket med äldre litteratur till biblioteket för att få modernare texter till medlemmarnas diskussioner.",h="Reading Room kretsar kring ett utbyte mellan Roy's Book Club och biblioteket i Stormwind.",kw={"böcker","legender","bibliotekarie","reading room","roys bokklubb","biblioteket i stormwind"},ang={["faction:Alliance"]="Resenärer från Alliansen besöker ofta Royal Library i Stormwind Keep, där medborgerliga och lärda utbyten håller stadens intellektuella liv levande."},sec={{t="Litterära intressen i Stormwind",b="I Stormwinds livliga huvudstad samlas litteraturälskare under Roy's Book Clubs fana för att granska klassiska legender och debattera provocerande texter. Klubben håller diskussionerna aktuella genom att byta ut äldre eller mindre populära verk mot nyare och mer engagerande böcker från stadens stora samling."},{t="Biblioteksutbytet",b="För att hålla läslistan aktuell förlitar sig klubben på ett etablerat låneavtal med biblioteket i Stormwind. Roy packar klubbens återlämnade böcker med en särskild inslagningsteknik, så att äventyrare kan leverera paketen direkt till bibliotekarien och få en ny lista med moderna böcker i utbyte."}},faq={{q="Vad är uppdraget Reading Room?",a="Reading Room är en uppgift som handlar om Roy's Book Club, en grupp läsare som diskuterar välkända legender och litteratur. Uppdraget går ut på att ta ett inslaget paket med mindre populära verk till biblioteket i Stormwind och byta dem mot modernare böcker.",al={"uppdraget reading room","vad är reading room","berättelsen om reading room"}},{q="Vem är Roy?",a="Roy leder en aktiv läsklubb där medlemmarna samlas för att debattera djupare betydelser i välkända legender och litteratur. Han har en överenskommelse med biblioteket i Stormwind om att byta läsmaterial och återlämna låneböckerna i perfekt skick.",al={"vem är roy","roys bokklubb","bokklubbens ledare"}},{q="Vart förs böckerna?",a="Det inslagna läsmaterialet levereras direkt till biblioteket i Stormwind. Bibliotekarien där känner igen Roy's Clubs särskilda inslagningsteknik och godtar gärna bytet mot nya, moderna texter.",al={"vart förs böckerna","inlämning till biblioteket i stormwind","leverans av inslaget läsmaterial"}},{q="Varför byts böckerna ut?",a="Klubben byter ut en del mindre populär litteratur mot modernare och mer tankeväckande texter, tack vare ett etablerat låneavtal med stadens bibliotek.",al={"varför byta böcker","varför återlämna böcker","byta läsmaterial"}},{q="Vad tycker bibliotekarien i Stormwind om bokklubben?",a="Bibliotekarien i Stormwind är mycket nöjd med överenskommelsen och påpekar att Roy's Club alltid återlämnar lånat material i utmärkt skick och behandlar alla texter varsamt, oavsett hur provocerande ämnet kan vara.",al={"vad tycker bibliotekarien","är bokklubben tillåten","bibliotekets överenskommelse"}},{q="Vilka förfriskningar nämns för klubben?",a="Klubben bjuder på kostnadsfria förfriskningar till besökare och hjälpare som bistår med bokbytena mellan läsplatsen och stadens arkiv.",al={"kostnadsfria förfriskningar i klubben","klubbens förmåner","vilka förfriskningar"}}},fp="12,239,30.329.0,20.310.0,31.259.0,11.248.0,32.219.0,34.189.0,52.237.0,41.159.0"}
P.entries["quest:97236"] = {n="Fang of Githyiss",s="Fang of Githyiss är ett sällsynt och imponerande fynd från en jättespindel som stryker omkring i vildmarken nära Aldrassil. När du lämnar in huggtanden till en naturkunnig person i helgedomen kan lärda studera monstret och hålla uppsikt över rovdjurshoten som har sina bon i Shadowglen.",h="Fang of Githyiss är ett sällsynt och imponerande fynd från en jättespindel som stryker omkring i vildmarken...",kw={"aldrassil","fang of githyiss","githyiss","shadowglen","spindel","spindelstudier","teldrassil"},ang={["class:Druid"]="Druider håller noga uppsikt över naturens balans i Teldrassil. De studerar ovanliga rovdjur och överdimensionerade spindlar för att bevaka tillståndet i den omgivande vildmarken.",["faction:Alliance"]="Studier av farligt djurliv i Teldrassil hjälper Alliance genom att se till att unga rekryter och forskare förstår de korrumperande hoten som har sina bon nära Aldrassil.",["race:NightElf"]="Som Teldrassils försvarare hjälper unga nattalvsäventyrare i Shadowglen till att skydda Aldrassils grenar genom att bekämpa farliga vidunder och bistå de lokala forskarna."},sec={{t="Ett monstruöst fynd",b="Fang of Githyiss är en trofé och ett biologiskt prov från den enorma spindeln Githyiss, som lurar i Shadowglens vildmark. Ett så ovanligt stort odjur utgör ett tydligt hot mot unga resenärer som ger sig ut från Aldrassil. Att hämta dess huggtand handlar därför både om säkerhet och vetenskapligt intresse. I stället för att låta lämningarna ruttna i snåren tar rådiga spejare med sig fyndet tillbaka till den stora trädets helgedom."},{t="Forskning i Aldrassil",b="I Aldrassil håller naturkunniga nattalver och lärda noga uppsikt över djurlivet som rör sig på skogsmarken. En färsk och oskadad huggtand från en varelse av Githyiss storlek ger viktiga insikter i spindelbestånden som frodas under Teldrassils lövverk. De lokala forskarna välkomnar sådana oväntade fynd och använder den väldiga huggtanden i sina pågående studier av gläntans aggressiva djurliv."}},faq={{q="Vad är Fang of Githyiss?",a="Fang of Githyiss är ett färskt prov från jättespindeln Githyiss. Den väldiga huggtanden ger sällsynt forskningsmaterial om spindelrovdjuren som lever i vildmarken runt Aldrassil.",al={"vad är fang of githyiss","uppdraget fang of githyiss","föremålet fang of githyiss"}},{q="Vem eller vad är Githyiss?",a="Githyiss är en ovanligt stor och farlig spindel som stryker omkring i skogarna nära Aldrassil i Shadowglen. Storleken gör den till ett hot mot resenärer och ett intressant studieobjekt för lokala naturkunniga.",al={"vem är githyiss","githyiss spindel","var finns githyiss"}},{q="Vem vill ha Fang of Githyiss?",a="Huggtanden lämnas till en lärd person i Aldrassil som specialiserar sig på spindlar. Sådana forskare välkomnar färska prov som kan öka deras kunskap om de lokala spindlarnas biologi.",al={"vem lämnar in fang of githyiss","var lämnar jag huggtanden","spindelforskare aldrassil"}},{q="Var ligger Aldrassil?",a="Aldrassil är Shadowglens stora gren och centrala helgedom, belägen i världsträdet Teldrassils krona. Den fungerar som övningsplats och fristad för unga nattalver.",al={"var ligger aldrassil","aldrassils plats"}},{q="Varför studerar lärda spindelhuggtänder i Aldrassil?",a="Lärda och naturkunniga i Aldrassil studerar lokala spindlar för att bättre förstå Shadowglens ekologi och hålla uppsikt över de aggressiva, överdimensionerade odjuren under Teldrassils lövverk.",al={"varför studerar de spindlar i aldrassil","varför studera spindelhuggtänder"}},{q="Kan Horde-spelare lämna in Fang of Githyiss?",a="Nej. Uppdraget utspelar sig i Shadowglen, nattalvernas startområde högt uppe i Teldrassil, och är därför endast tillgängligt för Alliance-äventyrare som inleder sin resa i Aldrassil.",al={"är uppdraget bara för alliance","kan horde göra fang of githyiss"}}},fp="16,279,20.462.0,21.438.0,29.219.0,24.188.0,31.185.0,19.184.0,52.194.0,47.182.0"}
P.entries["quest:97237"] = {n="Shelf Picked",s="Shelf Picked är ett budärende i Stormwind där du hämtar en särskild läslista från bibliotekshyllorna åt Roy Lewells. Som behörigt ombud hämtar du böckerna åt en lokal bokklubb som samlas i Park.",h="Shelf Picked är ett budärende i Stormwind där du hämtar en särskild läslista från bibliotekshyllorna åt Roy...",kw={"bokklubb","bud","bibliotek","park","roy lewells","shelf picked","stormwind"},ang={["faction:Alliance"]="Budärenden mellan Stormwinds bibliotek och lokala mötesplatser speglar det stillsamma vardagslivet i huvudstaden, medan större spänningar råder i kungariket."},sec={{t="Ett ärende bland hyllorna",b="I Shelf Picked agerar du officiellt bud åt Roy Lewells, som bor i Stormwinds stadsdel Park. Roy ber om flera läsval, och bibliotekarien bekräftar att alla titlar finns inne. Du måste själv hitta och ta varje bok från hyllorna. Bibliotekarien stannar vid disken och sköter bokföringen, så att inventarielistorna hålls korrekta medan du hämtar böckerna."},{t="Läsklubben i källaren",b="Lånade biblioteksböcker måste ofta lämnas tillbaka enligt strikta regler, men med Roy Lewells fullmakt har du officiell budstatus. Bibliotekarien förklarar att du inte själv ansvarar för böckerna. I stället ansvarar Lewells verksamhet fullt ut för att lämna tillbaka dem. När böckerna levererats till Park förbereder Roy de exotiskt doftande volymerna för livliga diskussioner efter stängning, nere i en källare."}},faq={{q="Vem ger uppdraget Shelf Picked?",a="Du får uppdraget av en bibliotekarie som sköter inventariet, efter att Roy Lewells skickat en ärendelapp. Bibliotekarien bekräftar att Roys läslista finns inne, men ber dig själv hämta böckerna från hyllorna.",al={"vem ger shelf picked","uppdragsgivare för shelf picked","var börjar shelf picked"}},{q="Vem är Roy Lewells?",a="Roy Lewells ordnar en lokal läsgrupp i Stormwinds stadsdel Park. Han skickar bud för att hämta reserverade böcker från biblioteket inför kommande diskussioner efter stängning i gruppens källare.",al={"vem är roy lewells","roy lewells park","vem är lewells"}},{q="Var hämtas böckerna?",a="Uppdraget utspelar sig på ett bibliotek där Mr. Lewells läsval finns inne. Bibliotekarien sköter inventarielistorna medan bud letar på bibliotekets hyllor efter de efterfrågade böckerna.",al={"vilket bibliotek är det här","var hämtas böckerna","vilket bibliotek i shelf picked"}},{q="Varför behöver Roy Lewells böckerna?",a="Roy Lewells har beställt läsmaterial till en informell bokklubb, för att väcka livliga diskussioner bland medlemmarna. Eftersom sammankomsterna hålls efter stängning träffas de i en källare när böckerna har levererats.",al={"varför hämta böcker åt lewells","vad är lewells bokklubb","bokklubb i källaren efter stängning"}},{q="Ansvarar du för att lämna tillbaka de lånade böckerna?",a="Nej. Bibliotekarien klargör uttryckligen att Roy Lewells ärendelapp gör dig till officiellt bud och befriar dig från personligt ansvar för att lämna tillbaka böckerna. Hela ansvaret för återlämningen ligger på Roys verksamhet.",al={"ansvarar jag för att lämna tillbaka böckerna","vem lämnar tillbaka böckerna i shelf picked","ansvar för återlämning av biblioteksböcker"}},{q="Vart lämnar du böckerna när du har hämtat dem?",a="Du lämnar böckerna direkt till Roy Lewells, som finns i stadsdelen Park i Stormwind.",al={"var lämnar man in shelf picked","var hittar man roy lewells","lämna in shelf picked"}}},fp="12,256,24.484.0,23.462.0,33.245.0,19.204.0,42.225.0,38.222.0,53.238.0,44.137.0"}
P.entries["quest:97242"] = {n="Yelmak's Medley",s="Yelmak's Medley är ett uppdrag i Orgrimmar som ska minska spänningarna på Yelmak's Alchemy and Potions i Valley of Honor. Mästaren i alkemi Yelmak vill tygla sin lärling Whuuts destruktiva klumpighet och envisa stolthet genom att tillreda en lugnande blandning av lokala vattenväxter.",h="Yelmak's Medley är ett uppdrag i Orgrimmar som ska minska spänningarna på Yelmak's Alchemy and Potions i...",kw={"alkemi","kaveldun","kor'geld","orgrimmar","spjutgräs","valley of honor","whuut","yelmak","yelmak's medley"},ang={["faction:Horde"]="Ärendet utspelar sig mitt i Orgrimmars Valley of Honor och hjälper till att upprätthålla ordningen och lugna upprörda känslor inom huvudstadens alkemihandel.",["profession:Herbalism"]="Insamlingen av färskt kaveldun och spjutgräs längs stadens vattenleder visar hur lokala växter mitt i Orgrimmar kan användas till blandningar och örtbrygder."},sec={{t="Problem i laboratoriet",b="På Yelmak's Alchemy and Potions i Orgrimmars Valley of Honor försvåras vardagen av den unge lärlingen Whuuts envisa stolthet. I stället för att be om hjälp eller erkänna när han inte klarar av något har den oerfarne blandaren börjat ha sönder butikens utrustning i frustration. För att begränsa skadorna och lugna den unge mannens heta humör utan att såra hans sköra ego hittar mästaren i alkemi Yelmak på en lugnande blandning."},{t="Lugnande lokala växter",b="Receptet kräver färska vilda skott från kaveldun och spjutgräs som frodas längs vattendragen genom Valley of Honor. Kor'geld kan inte lämna butiken utan att väcka den misstänksamma lärlingens uppmärksamhet, så en diskret tredje part måste samla in strandväxterna. När de har samlats in tillreds örtblandningen för att stillsamt påverka Whuuts attityd och återställa lugnet i alkemibutiken."}},faq={{q="Vem ger uppdraget Yelmak's Medley?",a="Kor'geld, som finns på Yelmak's Alchemy and Potions i Orgrimmars Valley of Honor, ger uppdraget för butikens mästare i alkemi.",al={"vem ger yelmaks medley","uppdragsgivare yelmak medley"}},{q="Vem är Whuut?",a="Whuut är en blandarlärling som utbildas av Yelmak i Valley of Honor. Han är känd för sin envisa stolthet och har haft sönder utrustning i stället för att erkänna att han behöver vägledning eller hjälp.",al={"vem är whuut","yelmak lärling","whuut orgrimmar"}},{q="Vad är syftet med den hemlagade blandningen?",a="Det är en särskild hemlagad blandning som mästaren i alkemi Yelmak tillreder av färska skott från kaveldun och spjutgräs för att stillsamt lugna sin stolta lärlings dåliga humör.",al={"vad är receptet på yelmak's medley","vad vill yelmak brygga"}},{q="Var samlas ingredienserna in?",a="Vilt kaveldun och spjutgräs växer längs sötvattenbäckarna och dammarna som rinner genom Valley of Honor i Orgrimmar.",al={"var hittar man kaveldun och spjutgräs","skott i valley of honor"}},{q="Varför samlar inte Kor'geld in skotten själv?",a="Kor'geld kan inte lämna Yelmak's Alchemy and Potions, eftersom Whuut genast skulle förstå att butikens personal i hemlighet anstränger sig för att anpassa sig efter hans besvärliga temperament.",al={"varför behöver korgeld hjälp","varför kan inte korgeld plocka växter"}},{q="Var ligger Yelmak's Alchemy and Potions?",a="Yelmak's Alchemy and Potions ligger i Valley of Honor, ett östra distrikt i hordens huvudstad Orgrimmar, känt för sina vattenvägar, krigarkaserner och hantverksbutiker.",al={"var ligger yelmak alchemy and potions","yelmak butikens plats"}}},fp="15,307,25.449.0,20.431.0,37.139.0,13.190.0,46.177.0,35.135.0,52.180.0,46.180.0"}
P.entries["quest:97243"] = {n="Call of Fire",s="Call of Fire för en initiand genom Skywalls vindar för att söka upp Olariaan Swiftburn, en shen'dorei Windshaper i samklang med eldelementet. Genom att ta Torch of Dormant Flame till Shrine of Flames i Gustberry Lowlands börjar resenären lära sig att lyssna till lågans kallelse, även i luftens domän.",h="Call of Fire för en initiand genom Skywalls vindar för att söka upp Olariaan Swiftburn, en shen'dorei...",kw={"call of fire","elemental plane","gustberry lowlands","olariaan swiftburn","shen'dorei","shrine of flames","skywall","torch of dormant flame","valanaar","windshapers"},ang={["class:Shaman"]="Att hörsamma elementens kallelse är grundläggande i shamanträningen, och även i Skywall kräver samröre med eld hängiven vägledning och vördnad för förfäderna.",["race:Skyborne"]="Även om de hör hemma bland Skywalls vindar förstår Skyborne-resenärer och Windshapers att balans kräver att alla fyra urkrafter erkänns."},sec={{t="Röster över elementplanet",b="Även i Skywall, domänen som styrs av luftelementalerna, förblir de större strömmarna i Elemental Plane sammankopplade. Jordens, vattnets och eldens andar talar fortfarande till dem som är lyhörda nog att höra dem. Bland Windshapers finns individer som är särskilt mottagliga för dessa andra krafter, däribland Olariaan Swiftburn, en shen'dorei med djup samklang med eldelementet."},{t="Shrine of Flames",b="Initiander anförtros Torch of Dormant Flame och visas vägen till Gustberry Lowlands. Långt ute längs öns rand, undangömd väster om Valanaar, står Shrine of Flames. Där tar Olariaan Swiftburn emot den slumrande lågan och erbjuder sig att undervisa blivande elever i att besvara eldens krävande kallelse mitt i luftsfärens virvlande strömmar."}},faq={{q="Vem är Olariaan Swiftburn?",a="Olariaan Swiftburn är en shen'dorei och medlem av Windshapers, med en medfödd samklang med eld. Hen bor vid Shrine of Flames, undangömd längs kanten av Gustberry Lowlands, väster om Valanaar.",al={"vem ger call of fire","vem ska jag ta facklan till","olariaan swiftburn"}},{q="Var ligger Shrine of Flames?",a="Shrine of Flames ligger i Gustberry Lowlands i Skywall. Den ligger avskilt längs kanten av det svävande ölandskapet, rakt väster om Valanaar.",al={"var ligger shrine of flames","gustberry lowlands plats","hur hittar jag olariaan"}},{q="Varför studeras eld i Skywall?",a="Även om Skywall främst är luftens elementdomän är den fortfarande en integrerad del av det större Elemental Plane. Andarna från alla fyra elementen genljuder fortfarande över dess vidder för dem som är tillräckligt samstämda för att lyssna.",al={"varför eld i skywall","eld i elemental plane","är inte skywall bara luft"}},{q="Vad är Torch of Dormant Flame?",a="Torch of Dormant Flame är ett elementärt fokus som förs till Olariaan Swiftburn. Den fungerar som en förbindelse för en initiand som söker undervisning i att kommunicera med eld.",al={"vad är den slumrande lågan","torch of dormant flame","vilket föremål ska jag bära"}},{q="Vilka är Windshapers?",a="Windshapers är utövare i Skywall som navigerar bland och formar elementarkrafter. Bland dem finns individer med olika ursprung, som shen'dorei.",al={"vilka är windshapers","windshaper-fraktionen"}},{q="Vad leder det här uppdraget till?",a="Olariaan Swiftburn undervisar lärjungar i hur de ska lyssna till eldens kallelse. Hen betonar att det krävs stor uthållighet för att bemästra urkrafter i Skywalls krävande domän.",al={"vad lär olariaan ut","eldträning i skywall"}}},fp="12,327,33.414.0,20.363.0,26.202.0,30.164.0,37.225.0,35.162.0,24.170.0,29.180.0"}
P.entries["quest:97244"] = {n="Call of Fire",s="Call of Fire är ett uppdrag från Windshapers, som kräver att Skypriest Faladiel avrättas. Han var en gång en av deras bröder, men förrådde sin orden för makt. Äventyrarna måste spåra den avfällige skypriest till Gustberry Lowlands och hämta hans hjärta för att driva en mäktig elementarritual.",h="Call of Fire är ett uppdrag från Windshapers, som kräver att Skypriest Faladiel avrättas.",kw={"al'aketh","call of fire","faladiel","faladiels hjärta","gustberry lowlands","shrine of akir","skypriest faladiel","valanaar","windshapers"},ang={["class:Priest"]="Präster kan lägga märke till Skypriest Faladiels förfall och fall från nåden. Hans heliga kallelse förvreds från att åkalla lågan till att förråda och mörda sin egen orden.",["class:Shaman"]="Schamaner som är förbundna med eld och elementarriter känner igen den hårda, ursprungliga kraften i att mata lågorna med en förrädares väsen för att stärka deras heliga kraft."},sec={{t="En förrädare bland lågorna",b="Call of Fire går ut på att äventyrarna ska jaga rätt på Skypriest Faladiel, som en gång tillhörde Windshapers men övergav sin lojalitet för att ansluta sig till Al'Aketh. Faladiel var en hängiven flammanropare, men valde makt framför trohet, vände sig mot sina ordensbröder och fick deras blod på sina händer. Windshapers skickar en agent för att verkställa sin kompromisslösa dom."},{t="Räkenskap i låglandet",b="Faladiel har isolerat sig på en gård i Gustberry Lowlands, nordost om Valanaar och strax söder om Shrine of Akir. Att döda den avfällige skypriest handlar om mer än hämnd. Windshapers behöver hans hjärta som en makaber beståndsdel i en kommande ritual. De tror att deras heliga lågor brinner med oöverträffad intensitet när de får sluka en förrädares hjärta."},{t="Blod med blod",b="När Windshapers får hjärtat bekräftar de på nytt sin trosregel: blod ska betalas med blod. Men Faladiels död är bara ett steg i deras arbete. Hjärtat är bara en del av det som måste ge näring åt deras ceremoniella eld innan riterna kan avslutas."}},faq={{q="Vem är Skypriest Faladiel?",a="Skypriest Faladiel var en gång en hängiven flammanropare och en trogen medlem av Windshapers. Liksom många bland Al'Aketh bytte han bort sin lojalitet för att få makt, vände sig mot sina fränder och fick deras blod på sina händer.",al={"vem är faladiel","faladiels bakgrund","skypriest faladiel i berättelsen"}},{q="Varför vill Windshapers att Faladiel ska dö?",a="Windshapers vill hämnas eftersom Faladiel förrådde dem för makt och mördade sina tidigare bröder och systrar. Enligt Windshapers trosregel ska blod betalas med blod, så hans avrättning är både rättvisa och hämnd.",al={"varför döda faladiel","varför vill windshapers döda faladiel","faladiels förräderi"}},{q="Varför behöver Windshapers Faladiels hjärta?",a="Faladiels hjärta är en kraftfull ritualingrediens. Windshapers tror att lågorna ivrigt slukar en förrädares hjärta och blir hetare och brinner mycket intensivare när de får det som näring.",al={"varför faladiels hjärta","vad ska hjärtat användas till","hjärta som ritualingrediens"}},{q="Var finns Skypriest Faladiel?",a="Skypriest Faladiel har sökt skydd på en gård i Gustberry Lowlands, nordost om Valanaar och strax söder om Shrine of Akir.",al={"var finns faladiel","skypriest faladiels plats","hitta faladiel"}},{q="Vad är Windshapers trosregel?",a="Windshapers är en orden bunden av en sträng och obeveklig trosregel. Förräderi glöms aldrig, och blod återgäldas alltid med blod. De utövar flammanrop och heliga elementarriter.",al={"vilka är windshapers","windshapers trosregel","windshapers fraktion"}},{q="Hur är Al'Aketh kopplade till det här uppdraget?",a="Al'Aketh är en fraktion eller grupp med medlemmar som har bytt bort sin tidigare lojalitet och heder mot personlig makt. Faladiel är ett framstående exempel bland deras skypriests.",al={"vad är alaketh","faladiel och alaketh","alaketh förrädare"}}},fp="12,272,25.371.0,25.392.0,21.268.1,26.241.0,44.220.0,45.205.0,38.146.0,37.197.0,50.204.0"}
P.entries["quest:97245"] = {n="Call of Fire",s="Call of Fire är ett uppdrag där Olariaan Swiftburn ber äventyrare att söka upp och konfrontera den uråldriga skogsanden Kuramaa i Shen'dar Highlands. Genom att locka fram anden ur sin stubbe och besegra den med eld får resenärerna dess kraftfulla trämask. Reliken förs sedan till Gustberry Lowlands för att tända en evig låga och tala med eldens andar.",h="Call of Fire är ett uppdrag där Olariaan Swiftburn ber äventyrare att söka upp och konfrontera den uråldriga...",kw={"anchor pylon","call of fire","skogsande","gustberry lowlands","kuramaa","kuramaas mask","olariaan swiftburn","shen'dar highlands"},ang={["class:Mage"]="Kuramaa står emot de flesta magiska inriktningar mycket väl, så besvärjare måste förlita sig helt på eldsmagi för att besegra anden.",["class:Shaman"]="Även om ritualen har samma namn som traditionella shamanistiska eldprov handlar den om att kuva en motståndskraftig ande från höglandet med eld och samla kraft för att tala med eldens andar."},sec={{t="Höglandets skogsande",b="I Shen'dar Highlands viskar lokalbefolkningen berättelser om Kuramaa, en uråldrig skogsande som bor i en vriden trädstubbe på toppen av en kulle nära regionens Anchor Pylon. För att locka fram den tillbakadragna varelsen måste en utmanare slå med knytnäven mot barken på dess hem av trä, kräva att den visar sig och sätta sin stridsförmåga på prov."},{t="Eld och trä",b="Att besegra Kuramaa är ingen enkel uppgift för utövare av mystisk eller gudomlig magi, eftersom anden har starka naturliga skydd mot de flesta magiformer. Endast brännande eld kan tränga igenom dess uråldriga bark och fälla den. När varelsen besegras får man Kuramaas trämask, en artefakt med stor kraft. Ändå är Kuramaa evig, bunden att återbildas och visa sig igen när den kallas."},{t="Den eviga lågan",b="Nere i Gustberry Lowlands väntar Olariaan Swiftburn på att Kuramaas mask ska hämtas. Den förtrollade träreliken är katalysatorn för en esoterisk ceremoni: att tända en evig låga för att tala direkt med eldens andar och låsa upp en uråldrig elementär gemenskap genom att besegra naturandar från höglandet."}},faq={{q="Vem är Kuramaa?",a="Kuramaa är en uråldrig skogsande som bor i Shen'dar Highlands. Enligt lokalbefolkningen på höglandet har den sitt hem i en vriden trädstubbe på toppen av en kulle nära höglandets Anchor Pylon.",al={"vem är kuramaa","kuramaas historia","vad är kuramaa"}},{q="Vem är Olariaan Swiftburn?",a="Olariaan Swiftburn är ritualisten som ber äventyrare att konfrontera Kuramaa. Olariaan håller till i Gustberry Lowlands och behöver Kuramaas trämask för att utföra en helig eldritual.",al={"vem ger call of fire","vem är olariaan swiftburn","var lämnar man in call of fire"}},{q="Hur kallar man på Kuramaa?",a="Kuramaa bor i en vriden trädstubbe på en kulle nära Anchor Pylon i Shen'dar Highlands. För att kalla ut anden till strid måste man knacka hårt med knytnäven mot stubben.",al={"hur kallar man på kuramaa","var finns kuramaas stubbe","kalla på skogsande"}},{q="Vad är Kuramaa sårbar för i strid?",a="Kuramaa har ett exceptionellt starkt naturligt motstånd mot de flesta magiformer. Endast beröringen av eld kan övervinna dess försvar och fälla den uråldriga skogsanden i strid.",al={"kuramaas svagheter","hur besegrar man kuramaa","kuramaa immun mot magi"}},{q="Varför behöver Olariaan Swiftburn Kuramaas mask?",a="Kuramaas trämask anses vara ett föremål med stor kraft. Olariaan Swiftburn använder den mäktiga reliken som en viktig del för att tända en evig låga och tala direkt med eldens andar.",al={"varför samla in kuramaas mask","vad gör masken","kuramaas mask syfte"}},{q="Förstörs Kuramaa för alltid när den besegras?",a="Kuramaa är en evig skogsande, inte en dödlig varelse. Även om dess fysiska gestalt besegras så att man kan ta masken, består anden och visar sig igen när det behövs.",al={"är kuramaa död","dödade jag kuramaa","kuramaas återkomst i berättelsen"}}},fp="12,388,27.364.0,13.383.0,17.323.1,15.225.0,26.194.0,26.194.0,40.174.0,48.207.0,47.191.0"}
P.entries["quest:97246"] = {n="Meal Appeal",s="Meal Appeal är ett ärende i Orgrimmar som Thatog, en orc upptagen med sina dagliga plikter, ger dig. Han oroar sig för att hans unge son Migi hoppar över måltider för att leka. Du får i uppdrag att hämta en färdig lunch från Borstan's Firepit och leta upp Migi, som leker bakom Grommash Hold. Uppdraget ger en jordnära inblick i familjelivet i Hordens huvudstad.",h="Meal Appeal är ett ärende i Orgrimmar som Thatog, en orc upptagen med sina dagliga plikter, ger dig.",kw={"borstan","borstan's firepit","grommash hold","lunchleverans","meal appeal","migi","orgrimmar","thatog"},ang={["faction:Horde"]="Livet innanför Orgrimmars murar handlar inte bara om krig och försvar. Vardagsbestyr som att mätta barnen som springer genom Valley of Strength håller stadens gemenskap levande.",["race:Orc"]="Även i orcernas hårda kultur oroar sig föräldrar som Thatog för att barnen försummar måltiderna för att leka på gatorna i Durotars huvudstad."},sec={{t="En förälders plikt i Orgrimmar",b="I Orgrimmars livliga avenyer av röd sten pågår vardagslivet sida vid sida med gruntsoldaternas övningar och Hordens intriger. Thatog, som plikten håller fast vid sin dagliga post, kan inte hålla uppsikt över sin livlige unge son Migi. När Migi får klara sig själv springer han genom stadens gator med sina vänner från morgon till kväll och glömmer ständigt bort att äta, tills han kommer hem utsvulten."},{t="Leverans bakom fästet",b="För att pojken inte ska gå hungrig ännu en eftermiddag ordnar Thatog en varm måltid från Borstan's Firepit. Eftersom Migi inte tänker avbryta leken för att hämta lunch själv ber Thatog förbipasserande äventyrare att agera bud. Ärendet tar dig från Borstans eldstad till den öppna gården bakom Grommash Hold, där Migi och de andra barnen i grannskapet nästan alltid är uppslukade av sina lekar."}},faq={{q="Vem är Thatog?",a="Thatog är en upptagen orcisk förälder med en post i Orgrimmar. Hans dagliga plikter hindrar honom från att gå därifrån och hålla uppsikt över sin unge son Migi. Thatog oroar sig för att Migi hoppar över måltiderna när han leker med sina vänner, så han ber en villig äventyrare att hämta och leverera mat till pojken.",al={"vem är thatog","uppdragsgivaren thatog","thatog i orgrimmar"}},{q="Var hittar man Migi?",a="Migi tillbringar dagarna med att leka med sina vänner i huvudstaden. Thatog säger att barnen nästan säkert går att hitta när de busar och leker bakom Grommash Hold i Orgrimmar.",al={"var är migi","migís plats","hitta migi"}},{q="Vad är Borstan's Firepit?",a="Borstan driver Borstan's Firepit, ett lokalt matställe i Orgrimmar. Thatog ber dig stanna till där först och säga till Borstan att du ska hämta en lunch som redan beställts för att lämna den personligen till Migi.",al={"var ligger borstan's firepit","borstan's firepit plats","borstans lunch"}},{q="Varför glömmer Migi att äta?",a="Som många livliga unga orcer blir Migi så uppslukad av att leka hela dagen med sina vänner bakom Grommash Hold att han glömmer eller väljer att inte stanna till vid Borstan's Firepit och äta. Ofta kommer han hem i slutet av dagen alldeles utsvulten.",al={"varför hoppar migi över lunchen","migi utsvulten","varför äter migi inte"}},{q="Vem är Migi?",a="Migi är Thatogs unge son. Han strövar runt i Orgrimmar och leker med en grupp vänner, och sätter leken före att gå hem eller hämta sina färdiglagade måltider.",al={"vem är migi","orcunge migi","thatogs son"}},{q="Vad går Meal Appeal ut på?",a="Du ska stanna till vid Borstan's Firepit och säga till Borstan att Thatog har skickat dig för att hämta Migis lunch. Sedan ska du lämna maten direkt till Migi bakom Grommash Hold, så att pojken inte går hungrig medan han leker.",al={"meal appeal uppdragsmål","vad ska man göra i meal appeal","meal appeal uppgift"}}},fp="11,345,28.451.0,24.448.0,14.291.0,24.193.0,26.210.0,28.247.0,12.170.0,37.216.0"}
P.entries["quest:97249"] = {n="Favorite Food",s="Favorite Food är ett uppdrag i Orgrimmar som kretsar kring Migi, en lekfull pojke bakom Grommash Hold vars föräldrar oroar sig för att han inte äter tillräckligt. För att vidga hans smak utan att låta honom gå hungrig tillagar Borstan på Borstan's Meats en varierad lunch kryddad med Migis älskade knaperstekta bitar med söt glasyr. Leveransen ser till att pojken och hans vänner tar en paus från lekarna och äter en näringsrik måltid.",h="Favorite Food är ett uppdrag i Orgrimmar som kretsar kring Migi, en lekfull pojke bakom Grommash Hold vars...",kw={"borstan","borstan's meats","favorite food","grommash hold","grisbringa","lunch","migi","orgrimmar","söt glasyr"},ang={["faction:Horde"]="Uppdraget ger en inblick i vardagslivet i Orgrimmar och visar hur lokala hantverkare och familjer ser till att huvudstadens barn får mat och omvårdnad.",["profession:Cooking"]="Uppdraget visar prov på praktiskt mathantverk i Hordens huvudstad, där knapriga bitar av rökt grisbringa återanvänds som en smakrik krydda till dagens måltider."},sec={{t="Leklust och aptit",b="Bakom Horde-maktens högsäte vid Grommash Hold tillbringar unge Migi och hans vänner eftermiddagarna med att leka längs Orgrimmars dammiga stigar. Migis föräldrar oroar sig dock för att pojken ofta hoppar över måltider när han leker och inte blir mätt. För att se till att han får regelbunden näring vände de sig till Borstan's Meats för att ordna dagliga lunchlådor. Men föräldrarna ställde ett strikt villkor: Borstan får inte servera exakt samma måltid varje dag. De insisterade på att Migi skulle lära sig uppskatta varierad mat i stället för att förlita sig på en enda favoriträtt."},{t="En söt kompromiss",b="Borstan ställdes inför en kulinarisk utmaning, eftersom Migi var ökänd för sin förkärlek för smörgåsar med sötglaserad grisbringa och bara dök upp till lunchen när röken från rökeriet bar med sig deras söta arom. För att respektera föräldrarnas krav på variation och samtidigt hålla pojken mätt kom slaktaren på en finurlig lösning. När sötglaserat fläsk tillagas smulas de överblivna knapriga, glaserade bitarna till en smakrik krydda som kan strös över vilken rätt som helst. Den väldoftande toppingen levererades bakom Grommash Hold och fick Migi och hans vänner att pausa leken och äta lunch tillsammans."}},faq={{q="Vem är Migi?",a="Migi är en ung invånare i Orgrimmar som tillbringar dagarna med att leka med vänner bakom Grommash Hold. Eftersom han blir så uppslukad av lekarna oroar sig hans föräldrar för att han inte äter sig mätt. Därför ordnar de dagliga lunchleveranser från Borstan's Meats.",al={"migi orgrimmar","vem är pojken bakom grommash hold","migis lunch"}},{q="Vem ger uppdraget Favorite Food?",a="Uppdraget ges av Borstan på Borstan's Meats i Orgrimmar. När Borstan fått höra om föräldrarnas oro för Migis näring och matvanor tillagar han en särskild måltid som ska vidga pojkens smak.",al={"vem ger uppdraget favorite food","vem startar favorite food","borstan favorite food"}},{q="Var hittar man Migi?",a="Migi finns bakom Grommash Hold i Orgrimmar, där han samlas med andra barn från trakten för att leka. Barnen går ofta längs vägen till fästet och känner igen Bोरstans dagliga specialiteter på doften.",al={"var migi finns","var finns migi","var lämnar man migis lunch","hitta migi i orgrimmar"}},{q="Vad är Migis favoritmat?",a="Migis favoritmat är smörgåsen med sötglaserad grisbringa som tillagas i rökeriet på Borstan's Meats. När röken väl stiger kan man räkna med att Migi snabbt dyker upp till lunchen, lockad av den karaktäristiska aromen som sprider sig mot Grommash Hold.",al={"vad tycker migi om att äta","migis favoritmåltid","sötglaserad grisbringa migi"}},{q="Varför ber Migis föräldrar om olika måltider?",a="Migis föräldrar bad Borstan att inte packa exakt samma måltid varje dag, så att sonen skulle lära sig uppskatta fler än en rätt. De vill att han ska äta tillräckligt, men också få en allsidig aptit i stället för att enbart leva på sötglaserat fläsk.",al={"varför ändra migis lunch","migis föräldrars önskemål","varför inte sötglaserade smörgåsar varje dag"}},{q="Hur får Borstan Migi att äta olika sorters mat?",a="Borstan smular de överblivna knapriga, glaserade bitarna från den rökta grisbringan till en topping som kan strös över olika rätter. Den starka, välbekanta smaken av söt glasyr gör att Borstan kan servera varierade måltider som Migi ändå glatt äter upp till sista tuggan.",al={"b सिंहorstans knep","hur får borstan migi att äta","smulor med söt glasyr"}},{q="Vad är Borstan's Meats?",a="Borstan's Meats är ett rökeri och ett slakteri i Orgrimmar som är känt för sina smörgåsar med rökt grisbringa och sina matlådor för stadens invånare. Borstan använder sina kulinariska färdigheter för att hålla kvarterets ungdomar välnärda.",al={"borstan's meats orgrimmar","var ligger borstan's meats","vad är borstan"}}},fp="13,381,20.574.0,25.604.0,12.289.0,34.224.0,24.241.0,29.245.0,46.267.0,49.267.0,24.229.0"}
P.entries["quest:97250"] = {n="Wrongly Blamed, Justly Corrected",s="Wrongly Blamed, Justly Corrected handlar om växande spänningar längs kusten mellan Horde och Alliance efter att en vägkrog förstörts under misstänkta omständigheter. Händelsen är en tydlig varning till Alliance-styrkorna, men lämnar frågan obesvarad om vem som verkligen hotade en viktig civil handelsled.",h="Wrongly Blamed, Justly Corrected handlar om växande spänningar längs kusten mellan Horde och Alliance efter...",kw={"varning till alliance","civil färdväg","östkusten","hordes handel","vägkrog","territoriell konflikt","wrongly blamed, justly corrected"},ang={["faction:Alliance"]="Utgången är en sträng varning från Horde-styrkorna mot Alliance ökande närvaro och provokationer längs östkusten.",["faction:Horde"]="Uppdraget innebär en betydande seger och en tydlig defensiv markering mot Alliance-intrång, samtidigt som det väcker oro för skyddet av viktiga handelsleder och färdvägar för Horde-civila."},sec={{t="Friktion längs kusten",b="När friktionen mellan Horde och Alliance stadigt ökar längs östkusten börjar skärmytslingar ta sig allt längre in i omstridda områden. Förstörelsen av en lokal vägkrog längs en viktig genomfartsled har drivit spänningarna till sin spets och hotar både vanliga resor och stabiliteten i regionen."},{t="Tvivlet och störningen",b="Misstankarna riktades först mot Horde, men det lokala ledarskapet tvivlar på att de egna styrkorna låg bakom vägkrogens förstörelse. Genomfartsleden är en viktig livsnerv för Horde-civila och köpmän som transporterar varor. Horde har därför all anledning att hålla vägen öppen, och röster höjs för en grundligare undersökning av vem som verkligen förstörde den."},{t="En varning till Alliance",b="Trots de kvarstående frågorna om själva vägkrogen står utgången klar som en avgörande seger för Horde-styrkorna i området. Resultatet är en tydlig varning till Alliance: varje intrång på territoriet längs kusten kommer att mötas av omedelbart motstånd."}},faq={{q="Vad handlar Wrongly Blamed, Justly Corrected om?",a="Wrongly Blamed, Justly Corrected är ett uppdrag för Horde som handlar om ökande spänningar mellan fraktionerna längs östkusten efter att en vägkrog förstörts längs en viktig färdväg.",al={"vad är det här för uppdrag","lore om wrongly blamed justly corrected","vad hände i wrongly blamed"}},{q="Förstörde Horde vägkrogen?",a="Horde-ledarskapet tvivlar starkt på att Horde-styrkorna låg bakom. Alltför många Horde-civila är beroende av handelsleden för handel och dagliga resor, så att förstöra den vore kontraproduktivt.",al={"förstörde horde vägkrogen","vem brände ner vägkrogen","vem förstörde vägkrogen"}},{q="Varför är den förstörda vägkrogen viktig för Horde?",a="Vägkrogen ligger längs en viktig genomfartsled som civila resenärer och köpmän använder flitigt för handel och resor. Störningen är därför en strategisk angelägenhet.",al={"varför är vägkrogen viktig för färdvägen","varför är vägkrogen viktig"}},{q="Vad orsakade spänningarna längs östkusten?",a="Det är oklart vad som först orsakade spänningarna. Friktionen mellan Horde och Alliance har ökat längs östkusten en tid, och konflikten har nu nått Horde-territorium.",al={"varför strider man längs östkusten","konflikt längs östkusten"}},{q="Vilket budskap sänder utgången till Alliance?",a="Handlingen är en taktisk seger som ger Alliance en sträng varning och visar att intrång på Horde-intressen inte kommer att lämnas obesvarade.",al={"vad uppnådde horde","varför varna alliance"}},{q="Kommer vägkrogens förstörelse att utredas vidare?",a="Omständigheterna kring vägkrogens förstörelse är fortfarande misstänkta och den civila trafiken hotas. Därför vill man utreda saken vidare och ta reda på vem som verkligen låg bakom förstörelsen.",al={"vad ska utredas","kommer vägkrogen att utredas"}}},fp="32,313,21.306.0,20.347.1,25.284.0,47.188.0,33.197.0,50.170.0,42.183.0,52.177.0,61.186.0"}
P.entries["quest:97253"] = {n="Parts and Pieces",s="Parts and Pieces är ett hämtningsuppdrag som Wrenix the Wretched erbjuder i hamnstaden Ratchet. Efter att flera legosoldater inte överlevt möten med de lokala piraterna skickade Wrenix ut en mekanisk konstruktion för att hantera hotet, men rövarna plockade isär den till skrot. Äventyrare får i uppdrag att ta sig till piraternas övre läger och återfinna de utspridda maskindelarna innan fler kommer till skada.",h="Parts and Pieces är ett hämtningsuppdrag som Wrenix the Wretched erbjuder i hamnstaden Ratchet.",kw={"komplicerade delar","maskin","parts and pieces","pirat","pirater","ratchet","sablar","övre piratlägret","wrenix the wretched"},ang={["profession:Engineering"]="Uppfinnare och ingenjörer kan uppskatta ironin i att en avancerad mekanisk apparat föll offer för simpel piratverksamhet. Att bärga Wrenix komplicerade delar ger en påminnelse på nära håll om farorna med att skicka automatiska prototyper in i fientliga läger utan ordentliga fysiska skydd."},sec={{t="En mekanisk lösning",b="Piraternas verksamhet längs kusten söder om Ratchet har blivit allt besvärligare för hamnens invånare och handelsfolk. För att hantera rövarna utan att riskera mer mynt på förbrukningsbara lejda händer tog uppfinnaren Wrenix the Wretched saken i egna händer. Efter att ha skickat fem eller sex legosoldater som alla misslyckades med att återvända i livet utformade Wrenix vad som verkade vara ett genialiskt alternativ: att skicka en automatisk maskin för att ta itu med rövarna. I stället för att utsätta ännu en levande själ för fara skickades den mekaniska konstruktionen för att självständigt lösa problemet med lägret."},{t="Böjda sablar och skruvmejslar",b="Den uppfinningsrika insatsen gick inte så smidigt som planerat. Piraterna som höll till i lägren söder om staden visade sig vara förvånansvärt påhittiga med sina klingor och upptäckte snabbt att böjda sablar kunde fungera som improviserade skruvmejslar. Innan Wrenix hann skicka instruktioner om att maskinen skulle retirera mot Ratchet bände rövarna isär mekanismen och spred dess ömtåliga delar över hela sitt övre läger. Nu behöver uppfinnaren, i stället för att utplåna piraterna, en djärv spejare som kan smyga in i lägret och samla ihop fem nävar av de komplicerade maskindelar som lämnats kvar i jorden."}},faq={{q="Vem är Wrenix the Wretched?",a="Wrenix the Wretched är en excentrisk uppfinnare som bor i den neutrala hamnstaden Ratchet. Wrenix stod inför ett aggressivt rövarband längs kusten i söder och försökte lösa piratproblemet med teknisk innovation. Efter att flera lejda legosoldater inte överlevt sina uppdrag byggde och skickade Wrenix ut en automatisk maskin för att hantera hotet, men den plockades snabbt isär.",al={"vem är wrenix","wrenix the wretched i berättelsen","ratchet wrenix"}},{q="Vad hände med de tidigare legosoldaterna som Wrenix anlitade?",a="Innan Wrenix tog till mekanisk automatisering anlitade han fem eller sex olika äventyrare för att undanröja pirathotet söder om Ratchet. Inte en enda av dessa agenter återvände i livet, vilket visade hur dödliga och välförsvarade piratlägren verkligen är. Deras dystra öde fick Wrenix att dra slutsatsen att det var både ineffektivt och livsfarligt att förlita sig på legosoldater av kött och blod.",al={"wrenix tidigare legosoldater","vad hände med de andra äventyrarna","vem skickade wrenix först"}},{q="Varför skickade Wrenix en maskin för att bekämpa piraterna?",a="Wrenix konstruerade och skickade ut en mekanisk apparat eftersom hans tidigare försök med levande legosoldater hade slutat i totalt misslyckande och dödsfall. Han trodde att ett urverk kunde lyckas där dödliga krigare föll, eller åtminstone förhindra fler dödsoffer, och skickade maskinen direkt in i lägret i förväntan om att mekanisk uppfinningsrikedom skulle övervinna piraterna.",al={"varför skicka en maskin","wrenix robotplan","varför använde wrenix en konstruktion"}},{q="Hur plockade piraterna isär Wrenix maskin?",a="Piraterna visade sig vara förvånansvärt påhittiga när de ställdes inför Wrenix konstruktion. Rövarna använde sina böjda sablar som improviserade skruvmejslar och bände snabbt isär maskinen innan Wrenix hann skicka kommandon om att styra den tillbaka mot Ratchet. De plockade isär apparaten ända ner till ramen och spred dess invecklade delar över hela lägret.",al={"hur förstördes maskinen","hur plockade piraterna isär roboten","piraternas sablar som skruvmejslar"}},{q="Var finns de komplicerade delarna?",a="Delarna från Wrenix förstörda maskin finns i det övre piratlägret längs kusten söder om Ratchet. Efter att ha plockat isär apparaten med sina sablar lämnade piraterna dess invecklade delar utspridda på marken i hela sitt läger på höjden. Äventyrare måste smyga in i lägret och samla ihop fem nävar av dessa komplicerade delar.",al={"var finns delarna","det övre piratlägrets plats","var finns nävarna med komplicerade delar"}},{q="Varför tror Wrenix att det här hämtningsuppdraget är säkrare?",a="Wrenix tror att uppdraget ger betydligt bättre chanser att överleva eftersom det bara handlar om att bärga delar, inte om ett öppet anfall. De tidigare legosoldaterna fick i uppdrag att utrota piraterna, medan detta hämtningsuppdrag bara kräver att man smyger in i det övre lägret, samlar fem nävar utspridda maskindelar ur jorden och återvänder till Ratchet.",al={"är parts and pieces säkert","varför tror wrenix att du överlever","wrenix överlevnadschanser"}},{q="Vad ska de komplicerade delarna användas till?",a="De komplicerade delarna är de särskilda kugghjulen, fjädrarna och precisionsbeslagen som drev Wrenix automatiska konstruktion. Eftersom försöket att neutralisera pirathotet slutade med att maskinen plockades isär behöver Wrenix få tillbaka de ömtåliga delarna, så att hans värdefulla hantverksskicklighet och material inte går helt till spillo.",al={"vad är komplicerade delar","varför behöver wrenix delarna","vad gör wrenix med delarna"}}},fp="16,415,21.598.0,26.644.0,27.407.0,54.378.0,51.380.0,47.374.0,40.364.0,56.400.0,42.357.0"}
P.entries["quest:97257"] = {n="Call of Fire",s="Call of Fire är en shamanistisk övergångsrit som The Windshapers leder i Skywall. De invigda hjälper till att kalla fram eldens andar, fånga Eternal Flame och skynda sig att tända fyrfatet i Valanaar innan tiden rinner ut. Klarar de prövningen visar de sin respekt för elementen och får sitt Fire Totem.",h="Call of Fire är en shamanistisk övergångsrit som The Windshapers leder i Skywall.",kw={"call of fire","eternal flame","fire totem","firelands","olariaan","skywall","valanaar","windshapers"},ang={["class:Shaman"]="Den här riten är en avgörande invigning för shamaner. När den är fullbordad får de makt över elden och tilldelas sitt Fire Totem.",["race:Skyborne"]="The Windshapers leder prövningen i Skywall, där den speglar Skyborne-shamanernas traditioner och vördnad för elementplanen."},sec={{t="Eldens ritual",b="Call of Fire är en helig prövning i samklang med elementen, som genomförs i Skywall. Olariaan från The Windshapers leder ritualen, där de invigda samlas vid Brazier of Offering för att kalla fram eldens andar från Firelands. Om andarna finner offren värdiga tänder de altaret med den heliga Eternal Flame, redo att tas i anspråk av en värdig aspirant."},{t="Resan till Valanaar",b="När Eternal Flame väl har tänts måste den fångas på en fackla och snabbt bäras genom Skywall till Valanaar. Eftersom energierna från Firelands naturligt försvagas och skingras i den virvlande atmosfären i luftens elementplan måste den invigde tävla mot tiden för att nå Brazier of Eternal Flames innan lågan slocknar."},{t="Fire Totem",b="Att tända fyrfatet på nytt i Valanaar visar den invigdes disciplin och vördnad för elementen. Som erkänsla för bedriften skänker The Windshapers den invigde sitt Fire Totem. Som de äldre lär ut tjänar elementens krafter gärna dem som respekterar dem, men förtär skoningslöst dem som inte gör det."}},faq={{q="Vad är Call of Fire?",a="Call of Fire är en helig övergångsrit där en blivande shaman hjälper till att kalla fram eldens andar och fånga Eternal Flame. Att bära den heliga elden till Valanaar visar den invigdes respekt för elementplanet och ger dem sitt Fire Totem.",al={"vad är call of fire","uppdraget call of fire","vad går uppdraget ut på"}},{q="Vem är Olariaan?",a="Olariaan leder ritualen vid Brazier of Offering. Han lägger de nödvändiga materialen på altaret och kallar fram eldens andar för att tända Eternal Flame.",al={"vem är olariaan","olariaans roll","vem inleder ritualen"}},{q="Vad är Eternal Flame?",a="Eternal Flame är en manifestation av eldens andar, som kallas fram från Firelands under The Windshapers ritual. De invigda måste fånga den på en fackla och tända Brazier of Eternal Flames i Valanaar.",al={"vad är eternal flame","eternal flame i skywall"}},{q="Varför måste lågan snabbt bäras till Valanaar?",a="Den råa elementelden som kallas fram kommer från Firelands, och dess intensiva hetta försvinner snabbt i den luftdominerade sfären Skywall. De invigda måste skynda sig så att facklan inte brinner ut innan de når Valanaar.",al={"varför skingras eternal flame","varför skynda till valanaar","eld från firelands i skywall"}},{q="Vilka är The Windshapers?",a="The Windshapers är en orden i Skywall som vägleder de invigda genom elementprövningar. De vördar elementplanens balans och kraft och ansvarar för att dela ut totem.",al={"vilka är the windshapers","fraktionen the windshapers"}},{q="Vad får man för att klara prövningen?",a="Den invigde får sitt Fire Totem genom att fullborda ritualen och tända fyrfatet i Valanaar på nytt. Det är ett viktigt redskap och fokus för att kanalisera elementeldens krafter.",al={"belöning för call of fire","belöning: fire totem","vad får man från call of fire"}}},fp="12,332,19.355.0,23.333.0,14.322.0,25.262.0,16.197.0,26.213.0,50.237.0,24.187.0,44.172.0"}
P.entries["quest:97263"] = {n="Your Package Has Arrived",s="\"Your Package Has Arrived\" är ett brådskande kuriruppdrag som gäller post som kommit bort på väg till Ironforge. En kurirlåda som skickats hela vägen från Wildhammerfästet Aerie Peak lämnades obevakad bredvid en brevlåda, adresserad särskilt till Eldrun Stormbreaker. Resenärer som hittar paketet får i uppgift att slutföra dess resa och se till att det når sin rättmätiga ägare.",h="\"Your Package Has Arrived\" är ett brådskande kuriruppdrag som gäller post som kommit bort på väg till...",kw={"aerie peak","eldrun stormbreaker","ironforge","brevlåda","borttappat paket","brådskande leverans","wildhammer","your package has arrived"},ang={["faction:Alliance"]="Att hålla öppna och pålitliga kommunikationsvägar mellan The Hinterlands och Ironforge är avgörande för Alliansens intressen i Khaz Modan och de nordliga territorierna.",["race:Dwarf"]="Dvärgar känner till de starka banden mellan Bronzebeards i Ironforge och deras Wildhammersläktingar i Aerie Peak. Därför är paketets säkra ankomst en fråga om respekt mellan klanerna."},sec={{t="Försvunnet gods",b="Ett postmissöde gör att flera paket blir liggande övergivna bredvid en brevlåda i staden, öppet framme i stället för att tryggt föras till sina destinationer. Bland denna oordnade hög av försummat gods ligger ett brådskande paket märkt för leverans hela vägen från Aerie Peak, Wildhammerdvärgarnas bergsfäste i The Hinterlands. Att frakta varor mellan avlägsna utposter i Khaz Modan och Lordaeron kan vara både farligt och kaotiskt. Därför kräver borttappade paket ibland att en uppmärksam förbipasserande ingriper och slutför leveransen."},{t="Ett paket till Eldrun Stormbreaker",b="Det borttappade paketet är tydligt märkt med Ironforge som destination och Eldrun Stormbreaker som slutmottagare. Paketet har uttryckligen märkts som brådskande, vilket visar att innehållet ansågs viktigt nog att skickas snabbt från The Hinterlands karga bergstoppar till dvärgarnas huvudstads salar under jord. När du tar hand om lådan tar du också på dig postväsendets ansvar och ser till att Eldrun får det som skickats över bergsryggar och vilda kullar, innan det blir stulet eller glöms bort helt."}},faq={{q="Vad är paketet som hittades vid brevlådan?",a="Paketet är en brådskande försändelse från Aerie Peak i The Hinterlands, adresserad till en mottagare vid namn Eldrun Stormbreaker i Ironforge. Det verkar ha kommit bort bland flera andra paket nära en brevlåda, i stället för att nå sin slutdestination genom den vanliga kurirhanteringen.",al={"vad är paketet","borttappat paket","vad lämnades vid brevlådan","paket vid brevlådan"}},{q="Vem är Eldrun Stormbreaker?",a="Eldrun Stormbreaker är den angivna mottagaren av det borttappade paketet i dvärgarnas huvudstad Ironforge. Paketet är tydligt märkt med hens namn och angivet som brådskande, men fraktsedeln berättar inte mycket mer förrän det har överlämnats säkert till Eldrun.",al={"vem är eldrun stormbreaker","eldrun stormbreaker","vem får paketet","paketets mottagare"}},{q="Varifrån skickades paketet?",a="Försändelsen kommer från Aerie Peak, Wildhammerklanens framstående bosättning och fästning högt uppe i bergen i The Hinterlands. Fraktsedeln visar att paketet färdades genom flera regioner mot Ironforge innan det kom bort nära en lokal brevlåda längs vägen.",al={"varifrån kom paketet","paketets ursprung","varifrån skickades det","leverans från aerie peak"}},{q="Varför märktes paketet som brådskande?",a="Fraktsedeln har en brådskande markering eftersom den som skickade lådan från Aerie Peak ansåg att innehållet eller ankomsttiden var mycket viktig. Med tanke på avståndet mellan Wildhammerhögländerna och staden Ironforge skulle en försenad försändelse kunna orsaka Eldrun Stormbreaker stora problem.",al={"varför är det brådskande","brådskande leverans","vad finns i paketet","varför brådskande"}},{q="Varför lämnades paketet vid en brevlåda?",a="Flera paket lämnades av någon oförklarlig anledning obevakade vid brevlådan i stället för att sorteras och delas ut av lokala kurirer. Hög belastning på kurirerna, logistisk förvirring eller ren försummelse leder ofta till att gods tillfälligt kommer bort under transporten. Då får hjälpsamma äventyrare reda upp misstaget.",al={"varför övergavs det","varför lämnades paketet","borttappad post","borttappade paket"}},{q="Vart ska paketet levereras?",a="Paketet är märkt för leverans till Ironforge, särskilt till Eldrun Stormbreaker. Den som hittar det borttappade godset måste ta på sig kurirens roll och bära det brådskande paketet direkt till Eldrun i dvärgarnas underjordiska fästningsstad.",al={"vart ska jag leverera det","paketets destination","leveransplats","vem ska jag lämna paketet till"}},{q="Vilken koppling finns mellan Aerie Peak och Ironforge?",a="Aerie Peak är Wildhammerdvärgarnas hjärta, medan Ironforge är Bronzebeardklanens storslagna säte. Klanerna har olika seder och hem, men regelbunden korrespondens, handel och släktband förbinder The Hinterlands klippor med Great Forge under berget.",al={"aerie peak och ironforge","handel mellan wildhammer och bronzebeard","kopplingen mellan ironforge och aerie peak","varför skicka post från aerie peak"}}},fp="24,396,17.550.0,32.548.0,41.295.0,27.291.0,31.271.0,33.314.0,46.312.0,45.278.0,56.302.0"}
P.entries["quest:97275"] = {n="Whuut's the Rush",s="Whuut's the Rush är ett alkemistärende om spänningen mellan rå talang och disciplinerat hantverk. Yelmak ber en äventyrare leverera en enkel, noggrant bryggd tonic till sitt underbarn till lärling, Whuut. Det visar att sann mästarförmåga börjar med vardagliga växter, inte med att slösa sällsynta ingredienser.",h="Whuut's the Rush är ett alkemistärende om spänningen mellan rå talang och disciplinerat hantverk.",kw={"alkemi","black lotus","cattail","örtmedicin","mountain silversage","dryck","speargrass","whuut","yelmak"},ang={["faction:Horde"]="Yelmak vägleder blivande alkemister i tålamod, påhittighet och respekt för lokala ingredienser från Kalimdor, i stället för att slösa dyrbara förråd.",["profession:Herbalism"]="Samlare och örtkunniga uppskattar nog läxan i detta ärende: att förstå egenskaperna hos vanliga ogräs som speargrass och cattail kan vara lika viktigt för hantverket som att leta efter legendariska blommor."},sec={{t="Det ivriga underbarnet",b="I alkemibutikens jäkt krockar rå talang ofta med vårdslös ambition. Whuut är känd som ett verkligt underbarn med naturlig fallenhet för omrörning. Men hans otålighet får honom att förbruka butikens sällsyntaste ingredienser innan han ens har fått grepp om grunderna i bryggkonsten. Innan han lär sig den fina balansen mellan vanliga örter söker han upp legendariska växter och behandlar alkemi som ett lopp i stället för en lära."},{t="En läxa i en flaska",b="För att tygla sin lärling utan att kväva hans iver skapar Yelmak en läxa i en flaska. I stället för att skälla på Whuut brygger Yelmak en förfinad dryck av bara vanligt speargrass och cattail med en snabb tonicmetod. Den enkla blandningen hamnar i Whuuts händer medan han dagdrömmer om Black Lotus och Mountain Silversage. Den visar att verklig alkemisk mästarförmåga kräver teknik, tålamod och respekt för vardagens växtliv."}},faq={{q="Vem är Whuut?",a="Whuut är ett ungt alkemiskt underbarn som ivrigt vill experimentera med de sällsyntaste örterna som finns. Han är onekligen begåvad, men hans brådska att brygga med exotiska ingredienser gör att han förbiser grunderna i alkemistyrket.",al={"vem är whuut","whuuts bakgrund","om whuut"}},{q="Vem är Yelmak?",a="Yelmak är en erfaren alkemist som fungerar som mentor i butiken. Han oroar sig för att Whuut slösar bort dyrbara förråd och blandar därför till en enkel tonic för att visa att verklig mästarförmåga börjar med anspråkslösa, lokala ingredienser.",al={"vem ger uppdraget","yelmak roll","vem är yelmak"}},{q="Varför skickar Yelmak dig med en dryck till Whuut?",a="Yelmak vill lära Whuut tålamod och respekt för alkemiens grunder. Genom att visa att en effektiv dryck kan bryggas av vanliga växter som speargrass och cattail hoppas han få Whuut att sluta rusa direkt till sällsynta, outforskade örter.",al={"vad är yelmaks läxa","varför skickar yelmak drycken","uppdragets poäng"}},{q="Vilka ingredienser använde Yelmak i sin dryck?",a="Yelmak brygger sin demonstrations-tonic med bara vanligt speargrass och cattail. Han bevisar för sin lärling att vanliga växter vid vägkanten kan ge anmärkningsvärda resultat när de tillreds varsamt.",al={"vad finns i drycken","yelmaks dryckesingredienser","ingredienser till snabb tonic"}},{q="Vilka sällsynta ingredienser försökte Whuut arbeta med?",a="Innan någon avbröt honom sträckte sig Whuut ivrigt efter några av Azeroths mest dyrbara och legendariska växter, närmare bestämt Black Lotus och Mountain Silversage. Han hoppade helt över vardagliga ingredienser.",al={"vad bryggde whuut","sällsynta örter whuut vill ha","vilka ingredienser använde whuut"}},{q="Lär sig Whuut sin läxa?",a="När Whuut smakar på tonicen och får veta hur enkel receptet är blir han häpen över att vanliga växter kunde ge en sådan brygd. Han medger ödmjukt att Yelmak har rätt och bestämmer sig för att lägga större märke till de vardagliga växter som han tidigare avfärdade.",al={"ändrar whuut uppfattning","whuuts reaktion på drycken","resultatet av whuut's the rush"}}},fp="16,323,17.474.0,18.436.0,13.227.0,14.226.0,49.251.0,46.216.0,50.207.0,28.240.0"}
P.entries["quest:97277"] = {n="Grund and Gozwin",s="Grund and Gozwin skildrar ett bakhåll vid ett läger i de snötäckta kullarna i nordväst, där en dvärg och en gnom angreps av en rovlysten snöleopard. Gnomens partners hagelgevär räddade honom, men hans högt skattade mekanikerlogg blev kvar i tumultet. Äventyrare skickas upp i kullarna för att hämta de ömtåliga anteckningarna och döda besten som smyger omkring.",h="Grund and Gozwin skildrar ett bakhåll vid ett läger i de snötäckta kullarna i nordväst, där en dvärg och en...",kw={"dvärg","gnomisk ingenjör","gozwin","grund","mecha-walker","mechanic's log","snöleopard på lur"},ang={["profession:Engineering"]="Gozwins oro över att ha tappat sin mekanikerlogg visar hur hemlighetsfulla mekaniker är med sina mecha-walker-konstruktioner och egna anteckningar.",["race:Dwarf"]="Grunds snabba reaktion med hagelgeväret och hans lojala kamratskap vid lägerelden visar den ståndaktiga lojalitet dvärgar bidrar med när de färdas tillsammans med sina gnomiska allierade.",["race:Gnome"]="Gozwin är den typiska gnomiska mekanikern: efter att ha överlevt ett våldsamt rovdjursangrepp oroar han sig först för säkerheten kring ritningarna till sin mechastridare."},sec={{t="Ett bakhåll vid elden",b="När dvärgen Grund och hans gnomiska följeslagare Gozwin färdades tillsammans i de snötäckta kullarna slog de läger för kvällen. Medan Grund vände ryggen till för att förbereda ett vildsvin över elden kastade sig en snöleopard på lur fram ur snåren och grep Gozwin med käftarna. Grund reagerade genast, grep sitt pålitliga hagelgevär och avlossade ett skott över besten. Rovdjuret blev skrämt, släppte gnomen och flydde bland de kalla klipporna."},{t="En mekanikers förlorade verk",b="Gozwin undkom kattens käftar med djupa rivsår i stället för dödliga skador, men lägret hade blivit rejält förstört. I kaoset när de flydde tappade Gozwin sin högt skattade Mechanic's Log, en teknisk anteckningsbok med viktiga ritningar till hans mecha-walker. Den sargade gnomen var livrädd för att någon skulle upptäcka hans ingenjörshemligheter och kunde inte vila förrän en äventyrare gick med på att bege sig nordväst upp i kullarna för att hämta boken och döda rovdjuret som strök omkring."}},faq={{q="Vilka är Grund and Gozwin?",a="Grund är en dvärgisk lägerbesökare med hagelgevär, och Gozwin är hans gnomiska ingenjörskamrat. När de slog läger i de snötäckta kullarna för att steka ett vildsvin överrumplades de av en snöleopard på jakt. Gozwin skadades och deras utrustning spreds omkring.",al={"vilka är grund och gozwin","grund gozwin"}},{q="Vad angrep Gozwin vid lägret?",a="En våldsam snöleopard på lur överrumplade Gozwin bakifrån medan Grund lagade middag. Besten satte tänderna i gnomen och försökte släpa bort honom, men Grund avlossade ett varningsskott som skrämde bort katten.",al={"vad angrep gozwin","vem angrep gozwin"}},{q="Varför är Gozwin's Mechanic's Log så viktig för honom?",a="Gozwin's Mechanic's Log innehåller viktiga tekniska ritningar och anteckningar om hans mecha-walker. Gozwin fruktade att hans projekt skulle gå helt om intet om någon annan fick tag på hans personliga ingenjörsanteckningar.",al={"varför är loggen viktig","gozwins mekanikerlogg"}},{q="Hur illa skadades Gozwin i anfallet?",a="Ja, Gozwin överlevde bakhållet tack vare Grunds snabba skott med hagelgeväret. Han klarade sig med djupa rivsår och svår chock, men återhämtar sig tryggt medan Grund tar hand om honom.",al={"mår gozwin bra","överlevde gozwin"}},{q="Var ligger Grund and Gozwin's läger?",a="De bådas läger ligger inbäddat i kullarna i nordväst. Äventyrare skickas dit för att hämta den förlorade loggboken och göra sig av med snöleoparden som smyger omkring i området.",al={"var ligger lägret","grunds lägerplats"}},{q="Vad hände med maten som Grund lagade?",a="Efter att Grunds skott skrämt bort den från Gozwin återvände den rovlystna snöleoparden till det övergivna lägret och kalasade på det stekta vildsvin som Grund hade lagat till middag.",al={"vad hände med det stekta vildsvinet","leopard äter vildsvin"}}},fp="16,367,21.439.0,22.493.0,25.241.0,29.221.0,51.222.0,40.175.0,41.187.0,46.182.0"}
P.entries["quest:97279"] = {n="Wayward Weapons",s="I Valley of Trials skickar Gornek nya rekryter för att hämta vapen till lägret. Unga krigare anländer för att tjäna Horden, förråden sinar och vapensmeden behöver få gamla vapen i bruk igen.",h="I Valley of Trials skickar Gornek nya rekryter för att hämta vapen till lägret.",kw={"durotar","gornek","kzan thornslash","rekryter","återvinning","the den","träningsvapen","valley of trials"},ang={["class:Warrior"]="Som krigare lär du dig att respektera dina vapen. Att hämta vapen som misslyckade rekryter lämnat efter sig kräver disciplin och självständighet innan striden börjar.",["faction:Horde"]="Som medlem av Horden håller du ut i Durotar med beslutsamhet och påhittighet och räddar vapen även när de som inte duger att bära dem kastar dem åt sidan.",["profession:Blacksmithing"]="I Durotar räknas varje metallskärva. Som smed hjälper du till att ta vara på förstörd utrustning och göra om slitna eggar till krigsredskap."},sec={{t="Beväpna de nya",b="Nya rekryter ställs inför hårda prövningar i Durotars röda ödemarker. Många anländer redo att svära trohet till krigshövdingen, vilket tär på lägrets vapenförråd. Vapensmeden Kzan Thornslash kämpar för att möta efterfrågan, särskilt när de första lektionerna blir ödesdigra eller förödmjukande för de oförberedda."},{t="Ett prov på uppfinningsrikedom",b="Uppsyningsmannen Gornek gör bristen till en praktisk prövning. Han skickar nyanlända för att hämta övergivna klingor och slöa träningsvapen som rekryter lämnat efter sig när de stupat eller flytt. Ta de återfunna vapnen till Kzan, så kan han reparera och härda dem inför nästa våg. Nya rekryter lär sig att överlevnad i Horden kräver att man samlar på sig utrustning såväl som svingar stål."}},faq={{q="Varför ligger det så många övergivna träningsvapen här?",a="Vissa rekryter saknar styrkan eller beslutsamheten som Horden kräver. Slarviga eller rädda nykomlingar lämnar sin utrustning, medan andra faller för vildsvin och skorpioner i trakten och sprider sina tilldelade vapen över marken.",al={"varför ligger vapen på marken","övergivna vapen i durotar","vapen från misslyckade rekryter"}},{q="Vem är Kzan Thornslash?",a="Kzan Thornslash är vapensmeden inne i The Den i Valley of Trials. Han utrustar nya rekryter, reparerar sliten träningsutrustning och sköter Hordens krigsförråd i startdalen.",al={"kzan thornslash bakgrund","vem är kzan","vapensmeden kzan"}},{q="Vem delar ut uppgiften?",a="Gornek, uppsyningsmannen utanför The Den, skickar nya rekryter för att hjälpa till. Han håller uppsikt över nytillkomna aspiranter, bedömer deras grundläggande förmåga och tilldelar dem omedelbara uppgifter kring prövningsplatsen.",al={"vem ger uppdraget wayward weapons","gornek uppdrag"}},{q="Vad gör Kzan med de här återfunna vapnen?",a="Kzan reparerar, slipar och återställer de slitna övningsvapnen. Eftersom resurserna i Durotar är knappa och rekryter ständigt anländer återanvänds bärgat järn och trä för att träna nästa våg.",al={"vad händer med träningsvapnen","kzan reparerar vapen"}},{q="Var utspelar sig det här uppdraget?",a="Du befinner dig i Valley of Trials, en avskild ravin i södra Durotar där unga orcher och Darkspear Trolls inleder sin väg som krigare för Horden.",al={"valley of trials plats","var finns wayward weapons"}},{q="Varför smider Horden inte bara helt nya vapen?",a="Durotar är kargt och torrt, med få lättillgängliga järnfyndigheter, och den unga Horden har inte råd med slöseri. Genom att återanvända övningsklingor från misslyckade rekryter sparas råmetall åt fronttrupperna.",al={"varför återvinna vapen","metallbrist i durotar"}}},fx={c966be67={q="Varför vill Gornek att de övergivna vapnen samlas in?",a="En ny våg rekryter har satt Valley of Trials vapenförråd under press. Vapensmeden Kzan börjar få slut på övningsutrustning, och Gornek måste se till att förråden fylls på så att nästa våg kan tränas. När han ber dig genomsöka området löser han bristen samtidigt som han kan pröva din plikttrogenhet och överlevnadsförmåga ute i dalen.",al={"gorneks motiv","varför vill gornek ha vapen","varför samla in övergivna övningsvapen"}},["42aac14b"]={q="Vad används Abandoned Training Weapon till?",a="De här enkla klingorna och klubborna bars av tidigare rekryter som visade sig ovärdiga eller dog innan de klarade sina prövningar. De ligger utspridda i marken, men är fortfarande tillräckligt hållbara för att kunna återställas. När du lämnar dem till Kzan Thornslash reparerar och slipar han dem, så att framtida rekryter får vapen att strida med.",al={"användning av abandoned training weapon","vad används övergivna vapen till","syftet med abandoned training weapon"}},["056af0db"]={q="Varför skickar Gornek en rekryt i stället för vakter?",a="Prövningsområdet ska skilja dugliga krigare från de svaga. Att skicka erfarna vakter för att städa upp efter misslyckade rekryter slösar på veteranernas krafter. När Gornek skickar dig fyller det två syften: du får erfarenhet av att jaga vildsvin i vildmarken, samtidigt som du visar att du kan följa order och sköta lägrets behov.",al={"varför skickas inte vakter","varför jag gornek","varför skicka rekryter efter vapen"}}},fp="15,209,20.283.0,25.348.0,62.212.0,23.198.0,21.185.0,46.192.0,33.153.0,54.183.0"}
P.entries["quest:97281"] = {n="A Simmering Storm",s="A Simmering Storm börjar när en äventyrare återfår en märklig relik som avger gnistor, känd som Dull Stormy Orb, från harpyor i Drygulch Ravine. När äventyraren tar den virvlande miniatyrstormen till goblinuppfinnaren Rezlak får hen insikt i harpyornas märkliga prydnadssaker och väcker intresset hos Ratchets driftiga skrotletare.",h="A Simmering Storm börjar när en äventyrare återfår en märklig relik som avger gnistor, känd som Dull Stormy...",kw={"a simmering storm","drygulch ravine","dull stormy orb","durotar","dustwind","gazlowe","harpy","rezlak"},ang={["class:Shaman"]="Den elektriska miniatyrstormen inuti klotet liknar primala elementarkrafter, men att tämja den i detta enkla kärl väcker frågor om harpyornas metoder.",["faction:Horde"]="Hordens äventyrare som hjälper goblinen Rezlak nära Drygulch Ravine bidrar till att säkra mystiska magiska artefakter som återfunnits hos fientliga harpyor som hotar Durotars kanjoner.",["profession:Engineering"]="Uppfinnare och ingenjörer som Rezlak dras naturligt till märkliga kuriositeter som sprakar av oberäkneliga elektriska laddningar och virvlande dimma inuti."},sec={{t="En gnista i stoftet",b="När resande kämpar mot de aggressiva Dustwind-harpyorna som häckar i hela Drygulch Ravine kan de stöta på en ovanlig kuriositet: Dull Stormy Orb. Föremålets yta ser matt och sliten ut, men när man håller det känner man en stadig vibration av rå elektrisk ström. Inuti sfären virvlar mörk dimma utan uppehåll, och skarpa gnistor lyser upp den med oregelbundna mellanrum. Det är ett otvetydigt bevis på att harpyorna manipulerade stormmagi med märkliga reliker."},{t="Goblinens nyfikenhet",b="I stället för att låta sådan flyktig magi stanna i vildharpyornas klor kan klotet tas direkt till Rezlak. Den pragmatiske goblinuppfinnaren är stationerad vid ingången till Drygulch Ravine och blir genast intresserad av den märkliga reliken. Han säger att fyndet påminner honom om gamla råd från hans arbetsgivare i Ratchet, chefsingenjör Gazlowe. Vad harpyorna än tänkte brygga med miniatyrstormen finns den nu i goblinhänder."}},faq={{q="Vad är Dull Stormy Orb?",a="Dull Stormy Orb är en märklig magisk kuriositet som återfunnits hos en harpy i Durotar. Trots sitt matta yttre surrar den av en svag elektrisk ström, virvlande mörk dimma och återkommande gnistor som hålls instängda inuti.",al={"vad är dull stormy orb","stormigt klot","klot från harpyor"}},{q="Vem vill ha Dull Stormy Orb?",a="Klotet tas till Rezlak, en goblinspejare stationerad strax utanför Drygulch Ravine i Durotar, som har ett skarpt öga för märkliga kuriositeter och värdefullt skrot.",al={"vem tar emot dull stormy orb","lämna in stormigt klot","vart ska klotet tas"}},{q="Varför hade harpyorna klotet?",a="Det exakta syftet är fortfarande okänt, men harpyorna i Drygulch Ravine använde tydligt klotet för att kanalisera eller hålla kvar elektriska stormenergier från elementen.",al={"vad gjorde harpyorna med klotet","varför har harpyor ett stormklot","harpyornas klot syfte"}},{q="Vem är Rezlak?",a="Rezlak är en goblinagent som arbetar i norra Durotar nära Drygulch Ravine. Han tillhör Steamwheedle Cartel och står i tjänst hos chefsingenjör Gazlowe i Ratchet.",al={"vem är rezlak","rezlak durotar","goblin nära drygulch"}},{q="Var ligger Drygulch Ravine?",a="Drygulch Ravine är ett kargt kanjonsystem i norra Durotar, fullt av fientliga Dustwind-harpyor som trakasserar resande och stör lokal handel och bosättningar.",al={"var ligger drygulch ravine","drygulch läge","harpyornas kanjon i durotar"}},{q="Vad tycker Rezlak om klotet?",a="När Rezlak får syn på klotet påminns han genast om lärdomar och kommentarer från sin chef, chefsingenjör Gazlowe, om märkliga och potentiellt lönsamma föremål.",al={"vad säger rezlak om gazlowe","rezlaks koppling till gazlowe"}}},fp="17,323,19.481.0,16.429.0,28.209.0,30.161.0,34.166.0,14.157.0,25.164.0,34.169.0"}
P.entries["quest:97282"] = {n="Stormy Potential",s="Stormy Potential är ett uppdrag i Durotar som goblinen Rezlak ger nära Drygulch Ravine. För att skydda sin handelskaravan mot plundrande harpyor vill Rezlak ladda en urladdad klot med kraft från de elektriska organen hos traktens åsködlor.",h="Stormy Potential är ett uppdrag i Durotar som goblinen Rezlak ger nära Drygulch Ravine.",kw={"laddade organ","drygulch ravine","durotar","gazlowe","harpyor","klot","rezlak","stormy potential","åsködla"},ang={["faction:Horde"]="Rezlaks verksamhet stöder Hordens fäste och resor genom Durotar, där plundrande harpyor från Drygulch Ravine hotar resenärer och försörjningskaravaner.",["profession:Engineering"]="Att utvinna instabil biologisk energi ur åsködlor för att väcka vilande anordningar till liv är typiskt goblinpåhitt, även om säkerhetsmarginalerna i princip är obefintliga."},sec={{t="Ta vara på tillfället",b="I närheten av Drygulch Ravines skugga i Durotar ställdes goblinen Rezlak inför två problem: en karavan som ständigt hotades av traktens harpyor och ett intakt magiskt klot som helt saknade kraft. Han mindes de pragmatiska råd han fått av Gazlowe, Ratchets chefsingenjör: ta vara på tillfället när det bjuds. Rezlak kläckte en djärv plan för att lösa båda problemen på en gång genom att ladda den vilande anordningen med extra kraft."},{t="Tämja stormen",b="För att återställa det urladdade klotet behövde Rezlak en kraftfull och omedelbar källa till rå elektricitet. I ravinen väster om Drygulch Ravine lever åsködlor, varelser vars inre organ kan alstra och leda dödliga blixtstötar. Genom att skicka en äventyrare för att samla in dessa laddade organ hoppades Rezlak kunna leda deras instabila ström direkt in i anordningen på ett säkert sätt. Då skulle hans utsatta lastvagnar få ett mäktigt skydd mot framtida harpyöverfall."}},faq={{q="Vem ger uppdraget Stormy Potential?",a="Stormy Potential erbjuds av Rezlak, en handelsman och uppfinnare av goblinsläkt som håller till nära Drygulch Ravine i Durotar. Han följer Gazlowes råd om att ta vara på tillfället när det bjuds och vill återställa ett urladdat klot med hjälp av den naturliga elektriska laddningen hos traktens bestar.",al={"vem ger stormy potential","var finns rezlak","rezlak uppdragsgivare"}},{q="Vad försöker Rezlak ladda med organen?",a="Rezlak har ett klot som är intakt men helt urladdat. Han hoppas ladda det fullt igen med åsködlors elektriska organ, så att han kan försvara sin karavan mot harpyorna som härjar i området.",al={"vad laddar rezlak","varför behövs åsködlors organ","vad ska rezlak använda klotet till"}},{q="Var finns åsködlorna?",a="Åsködlor lever i en ravin väster om Rezlaks plats nära Drygulch Ravine i Durotar. Jägare måste samla in deras elektriska organ och ta dem till Rezlak.",al={"var hittar man åsködlor","åsködlors plats i durotar","var finns organen"}},{q="Varför är det farligt att samla in organ från åsködlor?",a="Trots sitt åsklika namn avger åsködlor farliga blixtar i stället för att bara ryta. Som Rezlak varnar för är deras elektriska stötar en smärtsam läxa som de flesta resenärer bara behöver lära sig en gång.",al={"varför har åsködlor blixtar","använder åsködlor blixtar"}},{q="Varför är Rezlak rädd för harpyorna?",a="Rezlaks karavan överfölls av de fientliga harpyor som hemsöker Drygulch Ravine. Han tänker använda det laddade klotet som avskräckning eller vapen, så att harpyorna tänker sig för innan de angriper hans transporter igen.",al={"varför behöver rezlak försvar","vem angrep rezlak","harpyor angriper karavan"}},{q="Vilken relation har Rezlak till Gazlowe?",a="Rezlak ser Gazlowe, Ratchets chefsingenjör, som en erfaren mentor och förebild inom affärer. När Rezlak utformar sin plan för att ladda klotet citerar han uttryckligen Gazlowes affärsfilosofi om att ta vara på tillfällen.",al={"vem är gazlowe för rezlak","rezlaks råd från gazlowe"}}},fp="16,255,19.421.0,20.486.0,37.266.0,48.233.0,36.167.0,45.207.0,33.210.0,39.234.0"}
P.entries["quest:97287"] = {n="Shrewd Negotiations",s="Magus Wordeen Voidglare berömmer din infiltration av magikernas stad och säger att det är dags att bli mer förhandlingsinriktad. Du ska föra den mystiska gnista du fann till Archmage Celindra i Dalaran.",h="Magus Wordeen Voidglare berömmer din infiltration av magikernas stad och säger att det är dags att bli mer...",kw={"alterac mountains","mystisk gnista","archmage celindra","dalaran","kirin tor","shrewd negotiations","wordeen voidglare"},sec={{t="Dags att förhandla",b="Magus Wordeen Voidglare medger att ingen plats på Azeroth kan mäta sig med Kirin Tor när det gäller kunskap om det mystiska, och att till och med hans eget lysande arbete bleknar i jämförelse med deras uråldriga visdom. Han tycker att det är hög tid att Horden får tillträde till deras exklusiva orden. Du ska föra gnistan du fann till Archmage Celindra i Dalaran, för Wordeen är säker på att Kirin Tor skulle ge vad som helst för att få tillbaka den."}},faq={{q="Vem skickar dig för att förhandla med Dalaran?",a="Magus Wordeen Voidglare, som vill bli mer förhandlingsinriktad efter din infiltration av staden.",al={"vem ger shrewd negotiations","wordeen voidglare","uppdragsgivare shrewd negotiations"}},{q="Vem ska du tala med?",a="Archmage Celindra i Dalaran.",al={"vem ska jag tala med","var finns celindra","var är celindra"}},{q="Vilket förhandlingskort har du med dig?",a="Den mystiska gnista du fann. Wordeen är säker på att Kirin Tor skulle ge vad som helst för att få tillbaka den.",al={"vad är gnistan","förhandlingskort","mystisk gnista"}},{q="Varför vill Wordeen Voidglare göra upp med Dalaran?",a="Wordeen medger att ingen plats på Azeroth kan mäta sig med Kirin Tor när det gäller kunskap om det mystiska, och tycker att det är dags att Horden får tillträde till deras exklusiva orden.",al={"varför förhandla med kirin tor","wordeens motiv","varför dalaran"}}},fp="19,199,17.402.0,40.94.0,31.30.0,27.95.0,53.161.0"}
P.entries["quest:97288"] = {n="Unending Torment",s="Unending Torment börjar när en märklig abomination dödas och dess huvud lossnar efter upprepade sömmar. Spåren efter att det skilts från kroppen och sytts fast igen många gånger tyder på avsiktliga, mörka experiment i de Fördömdas huvudstad. När du för det makabra fyndet till Master Apothecary Faranell i Undercity avslöjas den förvridna humorn bakom dess upprepade återupplivning.",h="Unending Torment börjar när en märklig abomination dödas och dess huvud lossnar efter upprepade sömmar.",kw={"abominable head","abomination","apothecarium","den mörka damen","master apothecary faranell","royal apothecary society","sylvanas windrunner","undercity","unending torment"},ang={["faction:Horde"]="Äventyrare i Horde som ser hur Faranell tar emot huvudet får en direkt inblick i de oroande metoderna hos deras allierade i Undercity. De Fördömdas metoder med ändlös återupplivning och köttformning är effektiva, men gör ofta deras mer hedersbundna fränder illa till mods.",["race:Undead"]="För de Fördömda visar huvudet deras drottning Sylvanas Windrunners mörka humor och obevekliga natur. Det är en tydlig påminnelse om den mörka damens absoluta makt och Royal Apothecary Societys makabra uppfinningsrikedom."},sec={{t="En lös söm",b="När den väldiga abominationen till slut faller i strid lossnar huvudet plötsligt från axlarna. En närmare undersökning visar att halsen inte bara har skilts från kroppen en gång, utan sytts fast, slitits loss och fästs igen många gånger. För varje ny rekonstruktion har sömmen blivit skörare, tills huvudet knappt sitter kvar på konstruktionens axlar. Så slarvigt men envist lappverk är ovanligt även för odöda konstruktioner och antyder att just denna abomination utsatts för upprepade cykler av förstörelse och återuppbyggnad. Den som undersöker kvarlevorna inser snabbt att vanliga asätare inte kan förklara detta hantverk. Bara de skickliga köttformarna i Undercity kan identifiera varelsens ursprung."},{t="Den mörka damens skämt",b="När du lämnar det avhuggna huvudet till Apothecarium får Master Apothecary Faranell, ledaren för Royal Apothecary Society, se det. Faranell blir inte förvånad över det makabra exemplaret, utan känner genast igen ansiktet. Han förklarar att de upprepade återuppbyggnaderna inte var ett olycksfall i nekromanti, utan ett avsiktligt och grymt skämt som Lady Sylvanas Windrunner själv låg bakom. Vilken förseelse eller förolämpning som gav varelsen detta eviga, förnedrande straff är bara känt av den mörka damen och hennes närmaste krets. I stället för att kasta bort den tilltufsade reliken tar Faranell glatt emot huvudet, övertygad om att Royal Apothecary Society kan använda det i sina pågående alkemiska och nekromantiska försök."}},faq={{q="Vad är Abominable Head?",a="Abominable Head är huvudet av en unik konstruktion, som faller när varelsen besegras. Halsen bär ärr efter upprepade återfästningar, där varje ny sammankoppling försvagat köttet och sömmarna. Det är bevis på ett bisarrt, återkommande straff som varelsen utsatts för och får upphittaren att ta med det till Master Apothecary Faranell i Undercity för undersökning.",al={"abominable head bakgrund","vad är abominable head","uppdragsföremålet abominationhuvud"}},{q="Varför har huvudet fästs fast så många gånger?",a="Varelsens huvud syddes upprepade gånger fast på kroppen igen som en form av plåga. Enligt Master Apothecary Faranell är varelsens tillstånd ett grymt och avsiktligt skämt iscensatt av Lady Sylvanas Windrunner. Varje gång konstruktionen föll eller förlorade huvudet sattes den ihop igen för att fortsätta tjäna eller lida. Halsen blev allt skörare och gav till slut vika ännu en gång.",al={"varför återfästes huvudet","varför syddes huvudet fast igen","unending torment huvudsömmar"}},{q="Vem är Master Apothecary Faranell?",a="Master Apothecary Faranell leder Royal Apothecary Society och håller till i Apothecarium i Undercity. Under drottning Sylvanas Windrunners styre övervakar Faranell de Fördömdas apotekare när de forskar om gifter, farsoter och anatomiska förändringar. Hans nära kännedom om den mörka damens projekt gör att han genast kan identifiera det sydda huvudets ursprung.",al={"vem är faranell","master apothecary faranell bakgrund","faranell i undercity"}},{q="Varför ser Sylvanas det här som ett grymt skämt?",a="Faranell avslöjar inte varelsens ursprungliga identitet, men ser konstruktionens ändlösa cykel av död och återuppbyggnad som ett läckert skämt från den mörka damen. Att tvinga en varelse att genomlida upprepad förstörelse, bara för att slarvigt återuppliva och sy ihop den gång på gång, visar Sylvanas skoningslösa sinne för ironi och hennes straff mot fiender.",al={"sylvanas skämt","varför skämtar den mörka damen","grymt skämt av den mörka damen"}},{q="Vad ska Faranell göra med huvudet?",a="När Faranell tar emot det tilltufsade huvudet konstaterar han med mörk förtjusning att han har användning för det. Som övervakare av Royal Apothecary Societys groteska experiment återanvänder han regelbundet nekromantiska kvarlevor, kött och biologiska egenheter för att utveckla nya brygder, farsoter och förstärkningar till konstruktioner som ska hjälpa de Fördömda i deras pågående konflikter.",al={"vad händer med huvudet","vad ska faranell göra med huvudet","vad ska apotekarna göra med det"}},{q="Var lämnar du in uppdraget Unending Torment?",a="Du slutför uppdraget genom att lämna Abominable Head direkt till Master Apothecary Faranell. Han finns i Apothecarium, den alkemiska flygeln i den södra delen av Undercity. Fördömda äventyrare och allierade i Horde hittar honom omgiven av bubblande kar, assistenter och försöksobjekt medan han övervakar sällskapets forskning.",al={"var lämnar man in unending torment","lämna in unending torment","vem tar emot abominable head"}},{q="Kan spelare i Alliance lämna in det här uppdraget?",a="Eftersom målet är att lämna uppdragsföremålet direkt till Master Apothecary Faranell i Apothecarium i Undercity är uppdraget avsett för äventyrare i Horde. Spelare i Alliance som försöker ta sig fram till Faranell möter fientliga vakter i Undercity och dödas av de Fördömda när de går in i deras underjordiska fäste.",al={"är unending torment bara för horde","alliance och unending torment","kan alliance göra unending torment"}}},fp="16,406,14.772.0,20.739.1,28.399.0,47.406.0,34.404.0,45.388.0,36.370.0,48.346.0,40.355.0"}
P.entries["quest:97289"] = {n="Unending Torment",s="Unending Torment är ett uppdrag i Undercity som handlar om att återuppliva det avhuggna huvudet från Grand Marshal Othmar Garithos. The Forsaken vill förhöra sin tidigare fiende från Alliance genom att förbereda en hopsydd styggelse som hans nya kropp.",h="Unending Torment är ett uppdrag i Undercity som handlar om att återuppliva det avhuggna huvudet från Grand...",kw={"styggelse","the forsaken","garithos","grand marshal","head of the baron","othmar","sylvanas","undercity","unending torment"},ang={["faction:Alliance"]="Den makabra återupplivningen av Grand Marshal Garithos kvarlevor visar vilket fasansfullt öde som väntar ledare från Alliance som trotsar Banshee Queen i Lordaeron.",["faction:Horde"]="Genom att bistå Royal Apothecary Society med återupplivningsexperiment i Undercity får du se The Forsakens mörka hantverk och deras hämnd mot tidigare förtryckare.",["race:Undead"]="För The Forsaken är experiment på Grand Marshal Garithos kvarlevor poetisk rättvisa och en tydlig påminnelse om Lady Sylvanas erövring av Lordaeron."},sec={{t="En trofé från erövringen",b="Djupt nere i Undercitys underjordiska laboratorier syr utövare bland The Forsaken ihop monstruösa styggelser av kasserade rester från de döda. Bland otaliga bevarade skallar finns ändå en relik med ovanligt mycket historisk bitterhet: det avhuggna huvudet från Grand Marshal Othmar Garithos, den arrogante befälhavare som ledde överlevande styrkor från Alliance genom Lordaeron innan han mötte sitt slut för The Dark Ladys hand."},{t="Gravens hemligheter",b="The Forsaken bevarar inte Garithos huvud enbart som krigsbyte. Genom att förbereda en hopfogad styggelsekropp som ny värd tänker nekromantiker från The Forsaken förhöra den tidigare Grand Marshal och avslöja hemligheter från Alliance som är låsta i hans avhuggna skalle. När huvudet förs till den livlösa konstruktionen fylls den sammansatta styggelsen av plågsamt medvetande och återupplever sina fasansfulla sista ögonblick i ändlös pina."}},faq={{q="Vem var Othmar?",a="Othmar syftar på Grand Marshal Othmar Garithos, en ökänd militär befälhavare som ledde resterna av Alliance i Lordaeron efter det tredje kriget. Han var avskydd av icke-människor, och Master Apothecary Faranell säger att The Dark Lady själv hade nöjet att göra slut på honom.",al={"vem är othmar","othmars identitet","vem var othmar"}},{q="Varför återupplivar The Forsaken Othmars kvarlevor?",a="The Forsaken vill få ur honom värdefulla hemligheter som han tog med sig i graven. Genom att placera hans bevarade huvud nära en förberedd styggelsekropp kan The Forsaken utvinna information direkt ur de återupplivade kvarlevorna.",al={"varför återuppliva othmar","syftet med att återuppliva huvudet","vilka hemligheter har othmar"}},{q="Hur dog Othmar?",a="Master Apothecary Faranell säger att Lady Sylvanas Windrunner, The Dark Lady, själv hade nöjet att göra slut på Grand Marshal Garithos.",al={"vem dödade othmar","hur dog othmar","othmars död"}},{q="Varför heter uppdragsföremålet Head of the Baron?",a="The Baron är namnet på den väldiga styggelsen i Ruins of Lordaeron som huvudet tillhörde. Faranell avslöjar att huvudet en gång tillhörde Grand Marshal Garithos.",al={"head of the baron othmar","varför heter det head of the baron"}},{q="Var finns Othmars nya kropp?",a="Den huvudlösa styggelse som byggts för att ta emot Othmars huvud förvaras i en angränsande kammare i Undercity och väntar på att utövare från The Forsaken ska återuppliva den.",al={"var är othmars kropp","styggelsens plats i undercity"}},{q="Vad händer när konstruktionen vaknar?",a="När huvudet placeras nära den sammansatta konstruktionen rycker det hopsydda köttet våldsamt till liv. När kvarlevorna återfår medvetandet gripas de genast av panik när de återupplever skräcken från Garithos sista stunder i livet.",al={"vad händer när kroppen vaknar","othmars reaktion när han vaknar"}}},fp="16,241,20.422.0,20.430.1,15.264.0,50.213.0,19.136.0,51.168.0,35.176.0,40.210.0"}
P.entries["quest:97290"] = {n="Unending Torment",s="Unending Torment är en uppgift som utförs på uppdrag av Royal Apothecary Society i Undercity. Ett sändebud möter en trotsig fånge eller ett trotsigt försöksobjekt som vägrar samarbeta och kallar uppdragsgivaren en styggelse. När trotsen rapporteras till Master Apothecary Faranell möts den av tillfredsställelse snarare än besvikelse, eftersom ledaren för apotekarna gläds åt chansen att bryta ner ett svårhanterligt objekt.",h="Unending Torment är en uppgift som utförs på uppdrag av Royal Apothecary Society i Undercity.",kw={"styggelse","apothecarium","faranell","forsaken","master apothecary faranell","royal apothecary society","undercity","unending torment"},ang={["faction:Horde"]="Hordens mästare som verkar i Lordaeron får ofta bevittna sina Forsaken-allierades kyliga hänsynslöshet. Faranells förtjusning i att bryta ner envisa fångar visar den mörka pragmatism som råder i Undercity.",["race:Undead"]="Forsaken-äventyrare är väl bekanta med att bli kallade styggelser av de levande. Genom att hjälpa Master Apothecary Faranell bekräftar de sitt engagemang för Royal Apothecary Societys dystra arbete."},sec={{t="Trots i skuggorna",b="Royal Apothecary Society har ofta att göra med försöksobjekt, fångar och fientliga varelser som bara hyser hat mot Forsaken. I Unending Torment stöter en utredare på en person som vägrar samarbeta och öppet föraktar uppdragsgivaren, kallar denne en styggelse och vägrar bestämt att hjälpa till. Försöksobjektets desperata trots visar hur stark avsky och fientlighet många levande eller tillfångatagna varelser känner mot Lordaerons odöda."},{t="Faranells ambition",b="När fångens vägran rapporteras till Master Apothecary Faranell i Undercity reagerar han oväntat. I stället för att bli frustrerad över att inga omedelbara framsteg gjorts välkomnar chefen för Royal Apothecary Society motståndet med ondskefull entusiasm. För Faranell är ett obevekligt försöksobjekt inget misslyckat förhör, utan en intressant utmaning – en som lockar fram den grymma uppfinningsrikedom och de experimentella metoder som används i Apothecarium."}},faq={{q="Vad är Unending Torment?",a="Unending Torment är ett uppdrag med anknytning till Royal Apothecary Society. En äventyrare förhör eller undersöker en motsträvig fånge eller varelse som vägrar att hjälpa till och förolämpar äventyraren genom att kalla denne en styggelse. Äventyraren måste sedan rapportera detta misslyckande till Master Apothecary Faranell i Undercity.",al={"uppdraget unending torment","vad är unending torment","unending torment berättelse"}},{q="Vem ger uppdraget Unending Torment?",a="Uppdraget börjar när du möter ett trotsigt försöksobjekt som vägrar samarbeta och förbannar dig som en styggelse innan det beordrar dig att gå. Fången förblir namnlös i det första mötet och hänvisar den frustrerade äventyraren till ledningen för Royal Apothecary Society med sina iakttagelser.",al={"vem startar unending torment","vem ger uppdraget unending torment","var får man unending torment"}},{q="Vem är Master Apothecary Faranell?",a="Master Apothecary Faranell är chef för Royal Apothecary Society, som håller till i Apothecarium under Ruins of Lordaeron i Undercity. Han leder Forsakens alkemister och forskare när de utvecklar nya farsoter, brygder och gifter för att försvara Forsaken och utrota deras fiender i Azeroth.",al={"vem är faranell","master apothecary faranell","apotekare faranells roll"}},{q="Varför kallar talaren spelaren en styggelse?",a="Fången ser på de odöda och deras agenter med djup avsky, en vanlig känsla bland de levande och Forsakens fiender. Att kalla besökaren en styggelse speglar den djupa fördom och fasa som utomstående känner inför de återuppväckta döda som nu bor i Undercity.",al={"varför styggelse","vem kallar dig styggelse","varför är fången arg"}},{q="Var ska du rapportera efter att ha slutfört uppgiften?",a="Iakttagelserna från det motsträviga försöksobjektet ska lämnas direkt till Master Apothecary Faranell i Undercity. Faranell håller till djupt inne i Apothecarium, omgiven av bubblande kittlar, laboratoriekärl och andra forskare som ägnar sig åt att skapa dödliga brygder åt Lady Sylvanas Windrunner och Forsaken.",al={"var lämnar man in unending torment","lämna in unending torment","vem rapporterar man till i unending torment"}},{q="Hur reagerar Master Apothecary Faranell på försöksobjektets trots?",a="Master Apothecary Faranell blir mycket nöjd över försöksobjektets envisa vägran att samarbeta. I stället för att bli arg över dödläget ser han det som en underhållande utmaning. Den främste apotekaren gläds åt att pröva svårhanterliga försöksobjekts gränser med de dystra och skoningslösa metoder som Royal Apothecary Society utvecklat.",al={"faranells reaktion","vad säger faranell","blir faranell arg"}}},fp="16,401,23.488.0,19.468.0,25.330.0,37.325.0,34.314.0,52.299.0,48.327.0,68.333.0"}
P.entries["quest:97291"] = {n="Unending Torment",s="Unending Torment är ett uppdrag i Undercity där Master Apothecary Faranell vill binda en återihopsatt fånge till Dark Ladys vilja. För att fullborda den underkuvande brygden måste äventyrare samla dödliga ingredienser från hela Forsakens huvudstad.",h="Unending Torment är ett uppdrag i Undercity där Master Apothecary Faranell vill binda en återihopsatt fånge...",kw={"apothecarium","blisterweed","essence of agony","faranell","master apothecary faranell","tawny grisette","toxic skullcap","undercity","unending torment"},ang={["class:Rogue"]="Uppdraget kräver att du beger dig till Rogues' Quarter för att köpa Essence of Agony, en kraftfull ingrediens som ofta används av giftblandare och lönnmördare.",["faction:Horde"]="Royal Apothecary Society fortsätter att brygga ondskefulla blandningar djupt under Ruins of Lordaeron och prövar gränserna för alkemiskt tvång.",["profession:Herbalism"]="Att hämta Blisterweed från örttränarna i Apothecarium visar hur vanlig botanisk forskning överlappar med sällskapets mörkare alkemiska projekt.",["race:Undead"]="För Forsaken är det vardag i Apothecarium att med alkemisk tortyr kuva återupplivade kvarlevor och tvinga dem i Dark Ladys tjänst."},sec={{t="Att binda viljan",b="Djupt inne i Undercitys Apothecarium leder Master Apothecary Faranell ohyggliga experiment för att stärka Forsakens makt. Efter att ha lyckats fästa en misshandlad fånges avskurna huvud på nytt behöver Faranell en särskild alkemisk blandning. Den ska krossa det lilla motstånd varelsen har kvar och för alltid binda dess vilja till Lady Sylvanas Windrunner."},{t="Apotekarens ingredienser",b="För att tillreda sin underkuvande brygd skickar Faranell sitt ombud genom Undercity för att samla kraftfulla ingredienser. Uppdraget går ut på att hämta en Toxic Skullcap från Tawny Grisette i Trade Quarter, ta Blisterweed från örttränarna i närheten som står i skuld till honom och köpa Essence of Agony från en giftförsäljare i Rogues' Quarter."},{t="Mästerverket",b="När han får ingredienserna uttrycker Faranell bister tillfredsställelse över sitt förestående mästerverk. Han ser fram emot att pröva brygden på sin ”ärade gäst” och är säker på att den plågsamma drycken ska utplåna fångens sista trots och få den vilsegångna varelsen att lydigt återgå i Dark Ladys tjänst."}},faq={{q="Vem erbjuder uppdraget Unending Torment?",a="Uppdraget ges av Master Apothecary Faranell, ledaren för Royal Apothecary Society, som finns i Apothecarium i Undercity.",al={"vem ger unending torment","uppdragsgivare för unending torment","starta unending torment"}},{q="Vilka ingredienser behövs till Faranells brygd?",a="Master Apothecary Faranell behöver tre särskilda ingredienser: en Toxic Skullcap från Tawny Grisette i Trade Quarter, Blisterweed nära örttränarna i Apothecarium och Essence of Agony från en giftförsäljare i Rogues' Quarter.",al={"vilka ingredienser behövs","föremål i unending torment","vilka ingredienser behöver faranell"}},{q="Vem experimenterar Master Apothecary Faranell på?",a="Mottagaren är en motvillig fånge vars avskurna huvud nyligen har satts fast igen. Faranell kallar honom hånfullt ett ”vilsegånget får” och en ”ärad gäst”. Han vill krossa det trots han fortfarande klamrar sig fast vid efter svår misshandel.",al={"vem är besten","vem är det vilsegångna fåret som faranell nämner","vem torteras"}},{q="Vad är målet med Faranells brygd?",a="Brygden är sammansatt för att bryta ner målet mentalt och med våld binda det till Lady Sylvanas Windrunners vilja, Forsakens Dark Lady. Faranell tror att varelsens misshandlade tillstånd gör den särskilt mottaglig för kemisk kontroll.",al={"varför tillreda den här brygden","syftet med unending torment-brygden","vad gör brygden"}},{q="Var hittar spelare Tawny Grisette?",a="Tawny Grisette finns i Undercitys Trade Quarter, där hon säljer specialvaror, bland annat Toxic Skullcap som apotekarna behöver.",al={"var finns tawny grisette","försäljare av toxic skullcap","hitta miss grisette"}},{q="Var finns Blisterweed?",a="Blisterweed finns nära Undercitys örttränare, Alliestars, som håller till i Apothecarium. Faranell nämner att de är skyldiga honom en tjänst, så äventyrare kan ta det som behövs utan kostnad.",al={"var finns blisterweed","alliestaers örtträning","örttränare i undercity som har blisterweed"}}},fp="16,252,16.382.0,19.356.0,15.336.1,38.141.0,51.254.0,51.254.0,38.253.0,38.156.0,33.205.0"}
P.entries["quest:97292"] = {n="Unending Torment",s="Unending Torment är ett uppdrag i Undercity som Master Apothecary Faranell ger dig i Apothecarium. Du hjälper Royal Apothecary Society genom att hälla det frätande Hissing Serum i en droppande anordning ovanför Othmars kvarlevor. Uppgiften är en bestående hämnd för brott som begåtts mot Dark Lady.",h="Unending Torment är ett uppdrag i Undercity som Master Apothecary Faranell ger dig i Apothecarium.",kw={"apothecarium","dark lady","garithos","hissing serum","master apothecary faranell","othmar","undercity","unending torment"},ang={["faction:Horde"]="När du hjälper Faranell i Undercity får du se de grymma metoder Forsaken använder mot dem som har gått emot dem och Banshee Queen.",["race:Undead"]="Master Apothecary Faranell leder Royal Apothecary Society i Undercity, och bestraffning av Dark Ladys fiender som Garithos är central för Forsakens hämnd."},sec={{t="Apotekarens hämnd",b="I de fuktiga korridorerna i Undercitys Apothecarium utför Master Apothecary Faranell grymma experiment för att se till att Forsakens fiender aldrig får vila i frid. Till den här uppgiften har Faranell berett ett frätande ämne som kallas Hissing Serum, avsett att droppa oupphörligt på en fånge som hänger under en alkemisk apparat."},{t="Garithos öde",b="Faranells försöksobjekt är ingen mindre än Othmar, kvarlevorna efter Grand Marshal Garithos. Eftersom han begick brott mot Dark Lady anser Faranell att ständigt kemiskt lidande är det minsta han förtjänar. Serumet leds in i den upphängda konstruktionen ovanför Othmars kropp, där det långsamt ska sjuda hans kött. Den fallne befälhavaren blir därmed föremål för ett utdraget straff och studium."}},faq={{q="Vem är Othmar?",a="Othmar syftar på Grand Marshal Othmar Garithos, den tidigare mänsklige befälhavaren som ingick en osäker allians med Sylvanas Windrunner under återtagandet av Lordaeron, innan han förråddes och dödades av Forsaken. Master Apothecary Faranell har fått tag på hans kvarlevor för att utsätta honom för fortsatt plåga och experiment.",al={"vem är othmar","vad är othmar","othmar garithos"}},{q="Varför plågas Othmar?",a="Othmar Garithos arbetade tillsammans med Sylvanas Windrunner för att återta Capital City från dreadlords, men föraktade andra raser och ville återta hela Lordaeron åt mänskligheten. Forsaken håller honom ansvarig för brott mot Dark Lady och anser att evig kemisk tortyr är ett passande straff för hans arrogans och tidigare handlingar.",al={"varför torteras othmar","vad gjorde othmar","brott mot sylvanas"}},{q="Vem är Master Apothecary Faranell?",a="Master Apothecary Faranell leder Royal Apothecary Society i Undercitys Apothecarium. Han övervakar utvecklingen av nya serum, gifter och plågor och leder själv operationen mot Othmar.",al={"faranells roll","vem ger uppdraget unending torment","apothecary faranell"}},{q="Vad gör Hissing Serum?",a="Hissing Serum är en alkemisk blandning som Master Apothecary Faranell har bryggt för att sjuda kött och orsaka olidlig smärta. Den leds in i en droppanordning som hänger precis ovanför Othmars kropp.",al={"vad är hissing serum","serumets effekter","faranells serum"}},{q="Är Othmar levande eller odöd?",a="Othmar är odöd. Dark Lady själv dödade Garithos, och hans huvud har fästs på en styggelses kropp som rycker till liv. Faranell kallar honom deras ”nya gäst” och tänker låta serumet fortsätta droppa över honom.",al={"är othmar död eller levande","lever garithos","othmars tillstånd"}},{q="Vad tänker Faranell göra med Othmar härnäst?",a="Master Apothecary Faranell tänker låta Othmars kött sjuda under droppanordningen medan han håller honom under uppsikt. Faranell säger att han har omfattande planer för Othmars framtid och ska använda stackaren i fortsatta experiment och som hämnd.",al={"faranells framtidsplaner","vad händer med othmar härnäst","othmars framtid"}}},fp="16,341,22.344.0,20.402.1,14.325.0,30.351.0,34.226.0,31.223.0,26.245.0,47.247.0"}
P.entries["quest:973"] = {n="The Tower of Althalaxx",s="Det här uppdraget är det femte kapitlet i undersökningen av Tower of Althalaxx och leder Alliansens äventyrare söderut från Darkshore till Ashenvale. Delgren the Purifier skickar dig för att döda orc-hexmästaren Ilkrud Magthrull, som håller till vid det fördärvade Fire Scar Shrine, och hämta hans esoteriska bok.",h="Det här uppdraget är det femte kapitlet i undersökningen av Tower of Althalaxx och leder Alliansens...",kw={"althalaxx","ashenvale","delgren","fire scar shrine","ilkrud","maestra","magthrull","bok","hexmästare"},ang={["class:Paladin"]="Att arbeta tillsammans med Delgren the Purifier för att döda fel-besvärjare och beslagta fördärvade böcker speglar Ljusets klassiska kamp mot demoniskt fördärv.",["class:Warlock"]="När du konfronterar Ilkrud Magthrull ställs du mot en annan utövare av de mörka konsterna. Han använder tillkallade succubi och voidwalkers för att vakta sina oheliga texter.",["faction:Alliance"]="Uppdraget tar Alliansens äventyrare från Darkshores trygghet och djupt in i Ashenvales demonbesmittade hörn för att rena området från ett växande mörkt hot.",["race:NightElf"]="Fire Scar Shrine är en vidrig skändning av Ashenvales urgamla skogar, så att röja undan Ilkrud handlar om att försvara heliga förfädersmarker."},sec={{t="En jakt in i Ashenvale",b="Efter spåren av mörk kultistverksamhet som upptäcktes vid Tower of Althalaxx i Darkshore känner den helige krigaren Delgren the Purifier igen tecknen på en farlig utövare: orc-hexmästaren Ilkrud Magthrull. Ilkrud verkar från den demoniska härd som kallas Fire Scar Shrine i sydvästra Ashenvale, och hans skumma förehavanden hotar att sprida oren magi över de orörda alviska skogarna. Delgren ger dig i uppdrag att döda hexmästaren och lägga beslag på hans grimoar för att avslöja hans mästares planer."},{t="Hexmästarens näste",b="Fire Scar Shrine är en ruin märkt av fel och full av demoniska trälar. Helgedomen känns igen på de olycksbådande röda pelarna längs den klippiga stigningen och hyser Ilkrud, en tillkallad succubus och väktare som är felslayers. När du besegrar orcen i hjärtat av hans fel-domän kan Delgren granska Ilkruds bok efter den mörka kunskap och de order som knyter an till de olycksbådande ritualerna vid Althalaxx."}},faq={{q="Vem är Delgren the Purifier?",a="Delgren the Purifier är en mästare i Alliansen som är stationerad vid Maestra's Post, en nattalvisk utpost vid gränsen mellan Darkshore och Ashenvale. Han leder insatserna mot demoniskt fördärv och kultister i regionen.",al={"delgren","delgrens bakgrund","vem ger uppdraget"}},{q="Vem är Ilkrud Magthrull?",a="Ilkrud Magthrull är en mäktig orc-hexmästare med sitt näste vid Fire Scar Shrine i sydvästra Ashenvale. Delgren betraktade honom först som ett mindre irritationsmoment, men hans koppling till de mörka riterna vid Tower of Althalaxx gör honom till ett viktigt mål.",al={"ilkrud","vem är ilkrud magthrull","orc-hexmästare ashenvale"}},{q="Var ligger Fire Scar Shrine?",a="Helgedomen ligger i sydvästra Ashenvale, söder om The Shrine of Aessina och väster om Astranaar. Det är en fördärvad enklav full av demoner, flankerad av två tydliga röda pelare som leder upp till Ilkruds altare.",al={"fire scar shrine plats","var finns ilkrud","hur tar man sig till ilkrud"}},{q="Varför behöver Delgren Ilkrud Magthrulls bok?",a="Ilkruds bok innehåller hans mörka ritualer och meddelanden. Delgren vill tyda skrifterna för att avslöja vilken ondskefull plan som knyter orc-hexmästaren till kultisterna kring Tower of Althalaxx.",al={"varför boken","vad finns i ilkruds bok","bokens syfte"}},{q="Hur kopplar uppdraget samman Darkshore och Ashenvale?",a="Berättelsen börjar med undersökningar vid Tower of Althalaxx på Darkshores norra kust. När mysteriet fördjupas leder kultisternas nätverk äventyrarna söderut genom Darkshore och in i Ashenvales omstridda skogar.",al={"uppdrag från darkshore till ashenvale","koppling till althalaxx-kedjan"}},{q="Vad händer när boken har hämtats?",a="Delgren granskar texten för att dra slutsatser om de djupare planerna bakom kultisternas närvaro vid Tower of Althalaxx, vilket leder vidare till uppdragskedjans slutliga konfrontationer.",al={"nästa uppdrag","vad följer efter althalaxx 5"}}},fx={b25de95c={q="Varför vill Delgren the Purifier att detta görs?",a="Delgren the Purifier har vigt sig åt att utrota demonisk korruption i området. Tidigare såg han Ilkrud Magthrull som något mer än en mindre plåga, men häxmästarens ondskefulla forskning och aktiva närvaro vid det fördärvade Fire Scar Shrine gör honom till ett växande hot som Delgren inte längre kan ignorera.",al={"delgrens motiv","varför döda ilkrud magthrull","delgren the purifiers mål"}}},fp="22,185,21.346.0,18.261.1,28.204.0,24.236.0,38.203.0,46.176.0,51.193.0,39.154.0"}
P.entries["quest:97326"] = {n="Rocks to Rests",s="Rocks to Rests är ett lättsamt ärende åt Thra, en ung ork som leker med vänner bakom Grommash Hold i Orgrimmar. Barnen behöver en äventyrares styrka för att släpa släta stenblock till sin glänta, där de ska användas som enkla stolar och bord. Det ger en charmig inblick i vardagslivet och lekarna hos den yngre generationen som växer upp i Hordens huvudstad.",h="Rocks to Rests är ett lättsamt ärende åt Thra, en ung ork som leker med vänner bakom Grommash Hold i...",kw={"durotar","grommash hold","orker","orgrimmar","rocks to rests","släta stenblock","brädspel","thra"},ang={["faction:Horde"]="Att ta sig tid att hjälpa unga orker bakom hövdingens fäste visar att gemenskap och vardagsliv i Orgrimmar betyder något även i ett krigarsamhälle.",["race:Orc"]="Unga orker som hittar på egna lekar bakom Grommash Hold speglar hur nästa generation växer upp i hjärtat av Durotar."},sec={{t="En lugn vrå i Orgrimmar",b="I den jordiga gläntan precis bakom Grommash Hold i Orgrimmar samlas en grupp unga orker, utom räckhåll för fästningsvakternas stränga blickar. Platsen har gott om öppen mark för små figurer, men saknar möbler, så ungdomarna tvingas leka sittande direkt i dammet."},{t="Enkla möbler",b="När en förbipasserande äventyrare får syn på Thra ber den unga orken om hjälp att släpa åtta medelstora, släta stenblock till lekplatsen. Tack vare sina plana sidor fungerar de tunga stenarna som stadiga, enkla stolar och låga bord. Ungdomarna kan då ordna sina lekar bekvämt utan att behöva sitta i jorden."}},faq={{q="Vem ger uppdraget Rocks to Rests?",a="Thra är en ung ork som leker med vänner i den öppna gläntan bakom Grommash Hold i Orgrimmar. Thra är uppmärksam och lekfull och ber förbipasserande äventyrare om en hjälpande hand för att förbättra lekplatsen.",al={"vem ger rocks to rests","thra orgrimmar","vem är thra"}},{q="Var utspelar sig uppdraget?",a="Uppdraget utspelar sig i gläntan precis bakom Grommash Hold, hövding Thralls säte i Visdomens dal i Orgrimmar. Barnen samlas på den här relativt öppna jordfläcken, undan fästningens livliga trafik.",al={"var finns rocks to rests","thras plats","var bakom grommash hold"}},{q="Varför behöver Thra släta stenblock?",a="Thra och de andra ungdomarna behöver släta, medelstora stenar som enkla stolar och bord. Utan möbler tvingas de sitta direkt i jorden när de ställer upp sina småspel och leker.",al={"varför stenar","vad används släta stenblock till","varför stenblock"}},{q="Vilket spel spelas bakom Grommash Hold?",a="Thra och följeslagarna spelar ett enkelt brädspel med små figurer som de breder ut på marken. De släta stenblocken ger stadiga ytor att ställa figurerna på och bekväma sittplatser under spelet.",al={"vilket spel spelar de","thras spel orgrimmar","figurer bakom grommash hold"}},{q="Innebär Rocks to Rests strid?",a="Nej, Rocks to Rests är ett enkelt och fredligt ärende, inte en militär operation eller ett stridsprov. Uppdraget går helt ut på att använda råstyrka för att släpa tunga stenblock till barnens lekplats.",al={"är rocks to rests farligt","förekommer strid i rocks to rests"}},{q="Vad gör barnen med stenblocken när de har levererats?",a="När de åtta släta stenblocken har levererats skjuter Thra och barnen dem på plats över gläntan. De använder de plana sidorna som sittplatser och bord för sina små figurer.",al={"vad händer efter rocks to rests","vad gör thra med stenarna"}}},fp="14,375,27.316.0,19.313.0,35.220.0,33.238.0,35.213.0,47.205.0,37.191.0,57.196.0"}
P.entries["quest:97538"] = {n="Pigments for Paints",s="Tah Winterhoof från Thunder Bluff behöver en resenär som tar sig till Stonetalon Mountains för att fylla på hans förråd av rött färgpigment. Materialet han efterfrågar kommer från mirkweed, en unik vattenväxt som växer i Mirkfallon Lake och vars torkade kapslar ger ett lysande karmosinrött färgämne.",h="Tah Winterhoof från Thunder Bluff behöver en resenär som tar sig till Stonetalon Mountains för att fylla på...",kw={"mirkfallon lake","mirkweed","mirkweed pods","pigments for paints","rött pigment","stonetalon mountains","tah winterhoof","thunder bluff"},ang={["faction:Horde"]="Uppdraget visar de vardagliga banden mellan taurenhuvudstaden Thunder Bluff och de närliggande karga passen i Stonetalon Mountains.",["profession:Herbalism"]="Vattnen i Mirkfallon Lake är farliga, men den inhemska mirkweed-växten visar hur regionala vattenväxter kan ge användbara material och pigment utöver vanliga medicinalörter.",["race:Tauren"]="Tah Winterhoof representerar hantverkarna i Thunder Bluff, som förlitar sig på naturlig flora från hela Kalimdor för att skapa traditionella pigment och färgämnen."},sec={{t="En hantverkares behov",b="Tah Winterhoof, en äldre taurenhantverkare som bor i Thunder Bluffs stad på den höga mesan, tvingas lägga sitt hantverk åt sidan när det röda pigmentet tar slut. Eftersom hans resande år är bakom honom förlitar sig målaren på tåliga resenärer med yngre hovar för den mödosamma färden norrut till Stonetalon Mountains, där de kan fylla på hans förråd av färgämnen."},{t="Mirkfallons vatten",b="Hemligheten bakom Tahs lysande karmosinröda nyans finns i djupet av Mirkfallon Lake, en framträdande cirkelformad vattenmassa inbäddad i Stonetalonpasset. I vattnet växer mirkweed, en särskild vattenväxt vars frökapslar får en lysande, intensivt röd färg när de skördas och torkas ordentligt. Genom att hämta trettio sådana kapslar förser resenärer mästerhantverkaren med råmaterialet han behöver för att återuppta sitt arbete."}},faq={{q="Vem ger uppdraget Pigments for Paints?",a="Tah Winterhoof erbjuder uppdraget i Thunder Bluff. Som en äldre taurenhantverkare vars resdagar är förbi söker han någon med yngre hovar som kan samla råmaterial åt honom.",al={"vem ger pigments for paints","uppdragsgivare för pigments","tah winterhoofs plats"}},{q="Var hittar man Mirkweed Pods?",a="Mirkweed växer i vattnet i Mirkfallon Lake, en stor rund sjö mitt i bergspasset i Stonetalon Mountains.",al={"var hittar man mirkweed pods","mirkweeds plats","var ligger mirkfallon lake"}},{q="Varför behöver Tah Winterhoof mirkweed?",a="Tah Winterhoof har fått slut på rött pigment till sina målningar. Mirkweed-växtens kapslar får en lysande röd färg när de torkas, vilket gör dem till ett idealiskt naturligt färgämne till hans färger.",al={"varför samla mirkweed","vad används mirkweed till","varför rött pigment"}},{q="Hur många Mirkweed Pods behövs?",a="Tah Winterhoof behöver trettio Mirkweed Pods som samlas direkt från vattnet i Mirkfallon Lake för att fylla på sitt förråd av rött pigment.",al={"hur många kapslar behövs","antal mirkweed"}},{q="Vad är mirkweed?",a="Mirkweed är en unik vattenväxt som hör hemma i Mirkfallon Lake i Stonetalon Mountains. Dess främsta kännetecken är att kapslarna torkar till ett intensivt rött pigment.",al={"vilken sorts växt är mirkweed","fakta om mirkweed"}},{q="Var finns Tah Winterhoof?",a="Tah Winterhoof bor högst upp i mesastaden Thunder Bluff i Mulgore, där han utövar sitt hantverk och förbereder traditionella färger.",al={"var finns tah winterhoof","tah winterhoof thunder bluff"}}},fp="19,275,17.349.0,24.434.0,40.189.0,30.143.0,38.178.0,34.132.0,17.158.0,32.132.0"}
P.entries["quest:97539"] = {n="Silky Sutures",s="Silky Sutures är ett Horde-uppdrag i Arathi Highlands som Doctor Gregory Victor ger i utposten Hammerfall. Läkaren i lägret är frustrerad över att belägringsskadorna inte har reparerats och att sjukvårdsförråden sinar. Därför rekryterar han äventyrare för att samla giftigt spindelsilke från höglandet och använda det som suturtråd i fält. Uppdraget visar hur desperat och resursfattigt Hammerfalls försvarare har det när de försöker hålla vakter och arbetare på benen.",h="Silky Sutures är ett Horde-uppdrag i Arathi Highlands som Doctor Gregory Victor ger i utposten Hammerfall.",kw={"arathi highlands","doctor gregory victor","suturtråd för fältbruk","hammerfall","sjukstuga","silky sutures","spindelsilke","kirurgiskt spindelsilke"},ang={["faction:Horde"]="Hammerfall är ett viktigt fäste för Horde i Arathi Highlands. Doctor Victors arbete med att hålla försvararna friska och stridsberedda är avgörande för fraktionens överlevnad i området.",["race:Undead"]="Doctor Gregory Victor för med sig den pragmatiska och osentimentala läkarkunskap som förknippas med Forsaken till Hammerfall. Han använder resurser från höglandet för att hålla kliniken igång."},sec={{t="Den förfallna utposten",b="Hammerfall håller stånd i det karga Arathi Highlands, men lägret bär tydliga spår av långvarig påfrestning. Belägringsskadorna längs försvarsverken har inte reparerats, vilket får den lokala läkaren, Doctor Gregory Victor, att bittert konstatera att försummelse tycks vara officiell policy. Trots de förfallna befästningarna och bristen på stöd utifrån vägrar Victor att låta förfallet nå sjukstugan. En fungerande klinik är nödvändig för att hålla arbetarna och vaktstyrkan på benen och redo för strid."},{t="Provisoriska sjukvårdsförnödenheter",b="De sinande förråden har drivit Hammerfalls sjukavdelning nära bristningsgränsen och tvingat Doctor Victor att improvisera på slagfältet. När vanliga bandage och suturtråd börjar ta slut kan det sega, hållfasta silket från höglandsspindlar tvinnas till förvånansvärt slitstark suturtråd för fältbruk. Victor skämtar torrt om att infektionsrisken är det minsta en sårad soldat behöver oroa sig för. Silkesjakten ger ändå sjukstugan den viktiga utrustning som behövs för att sy ihop sårade försvarare i fientligt område."},{t="Galghumor i Hammerfall",b="Att driva en klinik vid fronten under belägring kräver hårdhudat sinnelag, något Doctor Gregory Victor har gott om. Han hälsar resenärer med bittra skämt om dystra prognoser och stygn av spindeltråd, och döljer på så vis hur isolerat Hammerfall är. Regelbunden hjälp är sällsynt i höglandet, så varje insats från besökande mästare är viktig för att hålla kliniken igång. Med improviserade botemedel och trotsigt motstånd ser Victor till att de sårade i Hammerfall får vård, även när utposten omkring dem verkar övergiven åt sitt förfall."}},faq={{q="Vem är Doctor Gregory Victor?",a="Doctor Gregory Victor är läkaren och traumakirurgen som ansvarar för sjukstugan i Hammerfall i Arathi Highlands. Med sin bittra humor och sitt rättframma sätt att prioritera skadade på slagfältet arbetar han outtröttligt med att behandla sårade vakter och arbetare. Trots svår brist på förnödenheter och oåtgärdade belägringsskador i utposten är Victor fast besluten att hindra sjukavdelningen från att förfalla.",al={"vem är victor","gregory victor i berättelsen","läkaren i hammerfall"}},{q="Varför behöver Doctor Victor spindelsilke?",a="Sjukstugan i Hammerfall har nästan helt slut på vanlig sjukvårdsutrustning. Under hård press från striderna improviserar Doctor Victor och tvinnar starkt spindelsilke från höglandet till effektiv suturtråd för att sy ihop sår och skärskador. Det slitstarka silket håller ihop sönderriven vävnad när riktig kirurgisk suturtråd saknas.",al={"varför spindelsilke","användning av kirurgiskt spindelsilke","suturtråd av spindelsilke"}},{q="Vilket skick är Hammerfall i under uppdraget?",a="Hammerfall är tydligt eftersatt och i dåligt skick. Gamla belägringsskador längs lägrets försvarsverk har inte reparerats alls, vilket får Doctor Victor att tro att administrativ försummelse har blivit officiell policy. Basen får inte regelbunden hjälp eller förnödenheter utifrån, så vakterna, arbetarna och sjukvårdspersonalen där måste klara sig själva.",al={"hammerfalls tillstånd","varför är hammerfall skadat","hammerfalls skick"}},{q="Varifrån kommer spindlarna i uppdraget?",a="Spindlarna stryker omkring i vildmarken i Arathi Highlands, runt Hammerfall. Äventyrare som ger sig utanför utpostens murar måste jaga de aggressiva spindeldjuren över höglandets slätter och samla in det kirurgiska spindelsilke som Doctor Victor behöver till sin suturtråd för fältbruk, innan de återvänder tryggt till kliniken.",al={"spindlar i arathi","var hittar man spindelsilke","plats för kirurgiskt spindelsilke"}},{q="Varför skämtar Doctor Victor om infektion?",a="När Doctor Victor får det insamlade spindelsilket skämtar han om att en liten infektion är det minsta en sårad soldat behöver oroa sig för när såren sys ihop. Den svarta humorn speglar den bistra verkligheten vid fronten i Hammerfall, där det är viktigare att förhindra allvarlig blodförlust och dödliga skador på slagfältet än att erbjuda steril klinisk vård.",al={"läkarens humor","spindelsilke och infektion","victors skämt"}},{q="Varför är det så ont om förnödenheter i Hammerfall?",a="Hammerfall ligger isolerat i ett omstritt område av Arathi Highlands, omgivet av fientliga hot och avskuret från pålitliga försörjningslinjer. Förstärkningar och leveranser utifrån kommer sällan, så utpostens garnison och sjukavdelning får utstå kronisk brist på råmaterial, verktyg och grundläggande läkemedel.",al={"varför saknas förnödenheter","brist på förnödenheter i hammerfall","brist på hjälp i hammerfall"}},{q="Vilka behandlar sjukstugan i Hammerfall?",a="Sjukstugan lyder direkt under Doctor Gregory Victor och ansvarar för att behandla arbetarna och vakterna som är stationerade i Hammerfall. Utposten utsätts ständigt för faror från höglandet och strukturella skador, så försvararnas hälsa är avgörande för att hålla bosättningen befäst och fungerande.",al={"vilka behandlar victor","patienter i hammerfall","klinikens patienter"}}},fp="13,478,21.507.0,26.542.0,27.573.0,29.431.0,40.397.0,50.396.0,46.324.0,47.364.0,41.347.0,43.336.0"}
P.entries["quest:97558"] = {n="Hides for the Forsaken",s="En bister nödvändighet i de odödas tillvaro i Tirisfal Glades, där de Förkastade måste leta efter djurhudar för att ersätta sitt förruttnande kött. Shelene Rhobart ber äventyrare samla in mörkerhundshudar, Duskbat Wing-membran och murlocskinn för att lappa ihop skadade kroppar.",h="En bister nödvändighet i de odödas tillvaro i Tirisfal Glades, där de Förkastade måste leta efter djurhudar...",kw={"mörkerhundshud","duskbat wing","hides for the forsaken","shelene rhobart","tirisfal glades","hudtransplantat för odöda","vile fin-murloc"},ang={["profession:Tailoring"]="De Förkastades skrädderi överlappar ofta med likbalsamering. Sömnadskunskaper används inte bara till kläder, utan också för att binda fast råa djurmembran på förruttnande kroppar.",["race:Undead"]="En bister påminnelse om de praktiska bördorna som följer med att vara Förkastad, där överlevnad kräver handfast underhåll och hudtransplantat från asätare i stället för naturlig läkning."},sec={{t="Odödlighetens pris",b="De Förkastades kött läker inte av sig självt. Fysiska sår lämnar ruttnande hål som inte kan återbildas genom normala biologiska processer. För att behålla sin form och hålla sina lik funktionsdugliga måste de hämta organiskt material från den levande världen och sy fast ersättningsbitar över skadorna."},{t="Särskilda material",b="Alla hudar fyller inte samma anatomiska funktion. Tjock mörkerhundshud är slitstark och passar för stora, stadiga lagningar. Tunna Duskbat Wing-membran är lätta och smidiga nog att täcka ansikten och fingrar utan att skapa stela, otympliga lager. Samtidigt samlar de in det böjliga skinnet från Vile Fin-murlocer för att klä invändiga hinnor och känsliga områden som kindernas insidor och munnar."}},faq={{q="Varför behöver de Förkastade djurhudar?",a="En odöds hud läker eller återbildas inte naturligt när den skadas. För att överleva fysiska skador och hejda förruttnelsen utåt skördar de Förkastade skinn och membran från levande varelser, som de lappar och syr fast över sina såriga kroppar.",al={"varför de förkastade behöver hudar","lore om odödas läkning","läker odöda"}},{q="Vem är Shelene Rhobart?",a="Shelene Rhobart är en Förkastad läderarbetare i Tirisfal Glades. Hon samlar in olika hudar och biologiska material för att se till att skadade Förkastade har det de behöver för att laga sina förruttnande kroppar.",al={"shelene rhobart","vem är shelene"}},{q="Varför behövs särskilt Duskbat Wing-membran?",a="Duskbat Wing-membran är exceptionellt tunna och smidiga jämfört med tyngre hudar. De är så lätta att de passar utmärkt för att täcka känsliga och detaljerade delar av kroppen, som ansiktsdrag och fingrar, utan att den fastsydda huden blir för tjock eller stel.",al={"vad duskbat-vingar används till","varför duskbat-membran"}},{q="Vad används murlocskinn till?",a="Skinn från Vile Fin-murlocer har en särskild fuktighet och smidighet, vilket gör det väl lämpat för invändiga hinnor och känsliga slemhinnor, som insidan av kinder och munnar.",al={"varför murlocskinn","murlocskinn för odöda"}},{q="Var finns de här materialen?",a="Alla tre varelserna strövar omkring i Tirisfal Glades hemsökta landskap. Mörkerhundar och skymningsfladdermöss jagar i skogarna och längs vägkanterna, medan Vile Fin-murlocer håller till längs nordkusten och i vattendragen inåt land.",al={"var man hittar hudar","bestar i tirisfal"}},{q="Är det vanligt att de Förkastade använder djurhudar?",a="Ja. Att hämta vävnad från djur och rester som de hittar är en grundläggande del av de Förkastades vardagliga överlevnad. Utan tillgång till ersättningskött och hudar skulle oläkta sår lämna ben, organ och muskler helt blottade för väder och vind.",al={"använder alla förkastade hudar","de förkastades kroppshantverk"}}},fx={["84f1a52c"]={q="Vad används Darkhound Hide till?",a="Odött kött läker inte naturligt från skador, så Forsaken måste laga sina kroppar med skördade djurhudar. Ömtåliga vävnader kräver tunna hinnor, medan tjockare och tåligare skinn som Darkhound Hide fungerar som hållbara transplantat över stora ytor på kroppen som slits hårt och behöver tålig ersättningshud.",al={"användning av darkhound hide","varför darkhound hide","darkhound hide till forsaken"}}},fp="22,266,20.316.0,21.383.0,38.240.0,23.197.0,51.273.0,29.175.0,32.197.0,46.256.0"}
P.entries["quest:97583"] = {n="WRIGGLE.",s="WRIGGLE. är ett möte med en sprallig, ung slime som älskar att dansa tills den inte orkar mer. För att pigga upp varelsen och bli vän med den måste en äventyrare hämta en särskild omgång Nutritious Slime Sludge från Undercitys kanaler.",h="WRIGGLE.",kw={"kanaler","sprallig slime","nutritious slime sludge","slime","sludge","undercity","wriggle"},ang={["faction:Horde"]="För att få tag på den särskilda sludge måste du bege dig in i kanalerna i Undercity, de försvurnas huvudstad, och göra affärer med de lokala handelsmännen.",["race:Undead"]="De försvurna är väl vana vid det giftiga avfallet och de levande slimes som håller till i Undercitys kanalsystem, så en slime som följeslagare passar naturligt in."},sec={{t="En dansande slime",b="WRIGGLE. handlar om att möta en livlig, sprallig liten slime som gärna härmar vänliga resenärers dansrörelser. Trots sin entusiasm blir den lilla slemvarelsen snabbt utmattad av dansen och behöver näring för att återfå sin styrka."},{t="Näring från kanalerna",b="För att pigga upp den utmattade varelsen måste äventyrare leta upp Nutritious Slime Sludge, en märklig blandning som säljs i Undercitys stinkande kanaler. När den får i sig denna omtyckta, vidriga godsak får den energiska slimen genast ett band till den som gav den maten och är redo att följa sin nya vän."}},faq={{q="Vad är WRIGGLE.?",a="WRIGGLE. är ett möte där en äventyrare blir vän med en sprallig liten slime genom att dansa, men snart upptäcker att varelsen behöver särskild näring för att orka hålla igång.",al={"wriggle-uppdrag","vad är wriggle","slimedans-uppdrag"}},{q="Var hittar du Nutritious Slime Sludge?",a="Nutritious Slime Sludge säljs av en handelsman som håller till i Undercitys kanaler, där alkemiskt avfall och spill är vanligt.",al={"var får man tag på sludge","försäljare av nutritious slime sludge","mata slime i undercity"}},{q="Hur fångar du slimens uppmärksamhet om den verkar trött?",a="Om den spralliga slimen blir trött eller distraherad fångar du dess uppmärksamhet genom att dansa med den, så härmar den dina lekfulla rörelser.",al={"hur fångar man slimens uppmärksamhet","trött slime","väcka slime wriggle"}},{q="Varför äter slimen sludge?",a="Slimes absorberar alkemiskt slem och sludge från omgivningen för att få näring och återfå sin livskraft. På så sätt piggnar de till efter att ha gjort av med energi.",al={"varför äter slimes sludge","vad äter slimes"}},{q="Vad händer när slimen har fått mat?",a="När den fått sin föredragna sludge får den återupplivade slimen ett band till äventyraren och vill följa efter den.",al={"följer slimen efter dig","slime som följeslagare","wriggle-belöning"}},{q="Kan alliansspelare lätt få tag på sludge?",a="Eftersom den nödvändiga Nutritious Slime Sludge bara går att få genom att besöka handelsmännen i Undercitys kanaler blir det extremt farligt för alliansens resenärer att ta sig in i de försvurnas huvudstad.",al={"kan alliansen göra wriggle","alliansen slime sludge"}}},fp="8,236,15.270.0,26.283.0,17.182.0,42.139.0,57.124.0,34.127.0,35.129.0,46.196.0"}
P.entries["quest:976"] = {n="Supplies to Auberdine",s="Supplies to Auberdine är ett eskortuppdrag där Alliansens äventyrare skyddar Feero Ironhand när han för viktiga förnödenheter och meddelanden norrut från Maestra's Post mot Darkshore. Hotet från Tower of Althalaxx växer, och fientliga infiltratörer finns i Ashenvale, så en säker färd kan inte tas för given.",h="Supplies to Auberdine är ett eskortuppdrag där Alliansens äventyrare skyddar Feero Ironhand när han för...",kw={"ashenvale","auberdine","balizar the umbrage","darkshore","delgren the purifier","feero ironhand","maestra's post","sentinel starbreeze","tower of althalaxx"},ang={["faction:Alliance"]="Genom att säkra den här leden hålls utposterna i Ashenvale förbundna med Auberdines logistiska nav, vilket bevarar Alliansens bräckliga grepp om norra Kalimdor.",["race:Human"]="Feero Ironhand visar hur människor är villiga att stödja sina kaldorei-allierade djupt inne i främmande, farliga uråldriga skogar.",["race:NightElf"]="Förnödenheterna och rapporterna som skickas norrut hjälper direkt väktarna i Auberdine när de möter det växande mörkret i Darkshore och längs gränsen till Ashenvale."},sec={{t="En farlig väg norrut",b="Maestra's Post ligger vid Ashenvales västra gräns, en stillsam utpost mellan skogens oroligheter och Darkshores bekymmer. Efter undersökningar av den ondskefulla verksamheten kring Tower of Althalaxx samlar Delgren the Purifier ihop viktiga förnödenheter och underrättelser som ska till Sentinel Starbreeze i Auberdine. I stället för att riskera ensamma kurirer låter utposten beväpnade eskorter följa Feero Ironhand längs skogsvägen."},{t="Skuggor längs stigen",b="Resan visar hur utsatt vildmarken kring vägen har blivit. Feeros väg kantas av samordnade bakhåll. Kultister från Dark Strand vill tysta alla rapporter om sina demoniska ritualer, Forsaken-spejare smyger genom skogens snår och våldsamma befälhavare som Balizar the Umbrage, Aligar the Tormentor och Caedakar the Vicious försöker fälla karavanen innan den når gränsen."}},faq={{q="Vem är Feero Ironhand?",a="Feero Ironhand är en mänsklig kurir stationerad vid Maestra's Post i västra Ashenvale. Delgren the Purifier har anförtrott honom viktiga meddelanden och logistiskt stöd till Auberdine. Han är försiktig nog att vägra resa utan dugliga livvakter.",al={"feero","feero ironhand bakgrund","vem är dvärgeskorten"}},{q="Varför behöver Auberdine dessa förnödenheter?",a="Darkshore och norra Ashenvale står inför tilltagande korruption och hot från demoniska kultister som verkar från Tower of Althalaxx. Night Elf-väktarna i Auberdine, under lokalt befäl av personer som Sentinel Starbreeze, behöver nya förnödenheter och aktuell information för att försvara kusten.",al={"varför skicka förnödenheter till auberdine","förnödenheter till auberdine","sentinel starbreeze"}},{q="Vem angriper Feero längs vägen?",a="Feero varnar för att farliga fiender härjar i skogen och ber om vakter. Vilka som anfaller upptäcks under eskortuppdraget.",al={"vem överfaller feero","feeros angripare","vem anfaller längs vägen"}},{q="Vad har Tower of Althalaxx med saken att göra?",a="Delgren the Purifier har samordnat arbetet med att avslöja och störa kultisternas mörka ritualer vid Tower of Althalaxx. Eskorten är en följd av den undersökningen och ser till att underrättelser och viktigt stöd når Night Elf-ledarna i Auberdine.",al={"koppling till althalaxx","tower of althalaxx","delgrens koppling"}},{q="Var rapporterar jag när jag har skyddat Feero?",a="När Feero tryggt har tagit sig genom bakhållen i Ashenvale rapporterar du tillbaka till Delgren the Purifier vid Maestra's Post och bekräftar att leveransen lyckades.",al={"lämna in supplies to auberdine","vart går jag efter att ha eskorterat feero","lämna in uppdrag"}}},fx={["1813fb85"]={q="Varför vill Feero Ironhand leverera de här förnödenheterna?",a="Delgren the Purifier gav Feero i uppdrag att föra nödvändiga förnödenheter och viktiga meddelanden norrut till Sentinel Starbreeze i Auberdine. Mörka krafter och kultister med ondskefulla avsikter verkar över hela västra Ashenvale. Feero vet att det kan få katastrofala följder för Alliansens försvar om fienden får tag i dessa känsliga meddelanden eller förråd.",al={"feero ironhands motiv","varför behöver feero hjälp","varför leverera förnödenheter till auberdine"}},affb8fb0={q="Varför ber Feero Ironhand dig om skydd i stället för postens vakter?",a="Feero vill helst inte resa ensam med viktiga förnödenheter och meddelanden genom det farliga Ashenvale. Han ber dig att eskortera honom så att leveransen når Auberdine säkert.",al={"varför jag feero","varför behöver feero eskort","varför reser inte feero ensam"}}},fp="21,347,21.488.0,23.428.1,22.248.0,39.317.0,33.151.0,49.269.0,41.153.0"}
P.entries["quest:97891"] = {n="Prompt Potion Runner",s="Prompt Potion Runner är ett brådskande leveransuppdrag i Undercity, där du måste skynda med en instabil brygd över slemskanalen till Apothecarium. Uppdraget visar de fysiska åkommorna som följer med odödhet och den oberäkneliga naturen hos Forsakens alkemiska forskning.",h="Prompt Potion Runner är ett brådskande leveransuppdrag i Undercity, där du måste skynda med en instabil brygd...",kw={"alessandro","apothecarium","doctor martin felben","prompt potion runner","royal apothecary society","slemskanal","undercity","instabil dryck"},ang={["faction:Horde"]="Undercity är en viktig knutpunkt för Horden, men resenärer måste ta sig fram genom stadens giftiga slemskanaler för att hjälpa Forsaken med deras riskfyllda alkemiska förehavanden.",["race:Undead"]="Leveransen visar den sköra fysiska verkligheten i Forsakens odöda tillvaro, där spröda leder och förmultnande knän lätt kan sätta stopp för viktigt laboratoriearbete hos Royal Apothecary Society."},sec={{t="En kapplöpning mot förfallet",b="I Undercitys underjordiska gångar behöver den Forsaken-al kemisten Alessandro snabbt ett bud. Han har tillrett en mycket flyktig brygd med extremt kort hållbarhet och vågar inte själv transportera den över stadens giftiga slemskanal, eftersom hans odöda leder är så sköra. En äventyrare måste springa mot klockan för att se till att brygden kommer fram oskadd innan den förvandlas till oanvändbart slam."},{t="Apothecariums krav",b="Målet är Apothecarium, där Doctor Martin Felben ivrigt väntar på leveransen till sin pågående forskning. Felben berättar att de sex föregående buden eller försöken misslyckades eftersom brygderna destabiliserades under färden. Om leveransen kommer fram i tid kan doktorn fortsätta sina skumma experiment utan avbrott, vilket visar både hur oberäkneliga Royal Apothecary-brygder är och vilka fysiska förödmjukelser odödheten medför."}},faq={{q="Vem ger uppdraget?",a="Alessandro i Undercity ger uppdraget. Han behöver en äventyrare som kan springa över slemskanalen, eftersom hans förmultnande odöda knän hoppar ur led och skallrar när han försöker springa.",al={"vem ger prompt potion runner","vem startar prompt potion runner","vem är alessandro"}},{q="Vart ska drycken?",a="Drycken ska levereras till Doctor Martin Felben, som utför alkemiska experiment i Apothecarium i Undercity.",al={"vart lämnar man drycken","vem är doctor martin felben","lämna in prompt potion runner"}},{q="Varför är leveransen tidsbegränsad?",a="Brygden är en instabil dryck med exceptionellt kort hållbarhet. Om den inte levereras snabbt över kanalen destabiliseras blandningen och blir oanvändbar.",al={"varför tidsbegränsad","instabil dryck hållbarhet","varför skynda"}},{q="Har andra leveransförsök misslyckats?",a="Doctor Martin Felben säger att de sex föregående dryckerna som Alessandro försökte skicka destabiliserades på vägen innan de nådde Apothecarium. Därför är din lyckade leverans en ovanlig triumf.",al={"misslyckades andra bud","alessandros tidigare försök","hur många drycker misslyckades"}},{q="Varför kan inte Alessandro leverera drycken själv?",a="Alessandro förklarar att hans knän skallrar och hoppar ur led så fort han försöker springa. Han kallar det ännu en olycklig fysisk bieffekt av odödheten, som hindrar honom från att själv skynda med leveransen.",al={"varför kan alessandro inte leverera den","alessandros knän"}},{q="Vad går Doctor Felbens experiment ut på?",a="Doctor Martin Felben är en apotekare som utför experiment i Apothecarium. Den exakta formeln hålls hemlig, men han återupptar genast sin forskning när den stabila blandningen kommer fram.",al={"vad gör doctor felben","vad används drycken till"}}},fp="20,263,20.434.0,26.420.0,21.183.0,33.127.0,26.171.0,36.194.0,48.195.0,37.191.0"}
P.entries["quest:97894"] = {n="Business in Auberdine",s="Borgus Steelhand söker nyheter om sin bror Gorbold i Auberdine. Dvärgköpmannen ber resenärer som seglar västerut att höra efter hur Gorbold har det, eftersom han nyligen började handla i nattalvernas hamn. Deras rutt förbinder Stormwind Harbor med norra Kalimdors stränder.",h="Borgus Steelhand söker nyheter om sin bror Gorbold i Auberdine.",kw={"auberdine","borgus steelhand","business in auberdine","darkshore","gorbold steelhand","köpman","steelhand","stormwind harbor"},ang={["faction:Alliance"]="Som resenär för Alliansen kan du segla direkt mellan Stormwind Harbor och Auberdine, vilket förbinder människoriket med Kaldoreiländerna i norra Kalimdor.",["race:Dwarf"]="Som dvärg kan du hitta dvärgköpmän som familjen Steelhand som handlar långt bortom Khaz Modan-bergen, till och med i nattalvernas stilla, skuggiga bosättningar."},sec={{t="En dvärg långt hemifrån",b="Borgus Steelhand litar på sin familjs namn bland handelsmän. Hans bror, Gorbold Steelhand, korsade nyligen Great Sea för att arbeta vid ett handelsstånd i Auberdine. Gorbold hoppades göra vinst genom att förse fartyg som anlöper Darkshore. Veckor har gått utan ett ord, och Borgus oroar sig för hur hans bror klarar sig så långt från Ironforge och Stormwind."},{t="Passagen från hamnen",b="Resan från Eastern Kingdoms till Kalimdor innebar en gång en kringlig passage via Menethil Harbor eller neutrala goblinhamnar som Booty Bay. Borgus hänvisar resenärer till ett fartyg vid den sydligaste kajen i Stormwind Harbor. Det seglar direkt till Auberdines långa träbryggor."}},faq={{q="Vem är Borgus Steelhand?",a="Borgus Steelhand är en dvärgköpman i Stormwind. Han litar på familjens rykte om rättvis handel och söker resenärer som kan föra bud till hans bror Gorbold på andra sidan havet.",al={"borgus steelhand","vem ger uppdraget business in auberdine","borgus"}},{q="Var finns Gorbold Steelhand?",a="Gorbold Steelhand finns i Auberdine, den främsta hamnbosättningen i Darkshore på Kalimdors nordvästra kust. Han arbetar vid ett handelsstånd som betjänar ankommande fartyg.",al={"var är gorbold","hitta gorbold steelhand","gorbolds plats"}},{q="Hur tar du dig till Auberdine från Stormwind?",a="Ett fartyg seglar från den sydligaste bryggan i Stormwind Harbor över Great Sea till Auberdines kajer i Darkshore.",al={"båt till auberdine","hur tar man sig till darkshore från stormwind","båt från stormwind till auberdine"}},{q="Varför oroar sig Borgus för sin bror?",a="Gorbold gav sig av för flera veckor sedan för att börja arbeta vid ett handelsstånd i Auberdine, i hopp om att göra vinst genom att förse fartyg. Han har inte skickat något bud hem, så Borgus ber resenärer ta reda på hur han har det.",al={"varför höra efter hur gorbold har det","vad hände med gorbold"}},{q="Vad är Auberdine för slags bosättning?",a="Auberdine är en kustbosättning i Darkshore, byggd och huvudsakligen bebodd av nattalver. Det är Alliansens främsta sjöfartsknutpunkt och färjeförbindelse mellan norra Kalimdor och Teldrassil.",al={"vad är auberdine","staden auberdine"}},{q="Vad är familjen Steelhand känd för?",a="Familjen Steelhand är känd för handel och för att hävda att den erbjuder rättvisa affärer åt resenärer och hamnarbetare.",al={"familjen steelhand","stålnävar"}}},fp="21,259,21.343.0,18.276.0,24.176.0,35.156.0,42.116.0,40.175.0,37.190.0,39.106.0"}
P.entries["quest:97903"] = {n="Camping 101: First Aid",s="Camping 101: First Aid är ett utbildningsuppdrag där skickliga resenärer skickas till Rawrk i Razor Hill, som lär dem att tillverka sitt eget First Aid Kit för att överleva i vildmarken. Uppdraget betonar vikten av att klara sig själv ute på vägarna och påminner äventyrare om att lära sig göra upp lägereldar och respektera lokala samhällen genom att slå läger ute i vildmarken.",h="Camping 101: First Aid är ett utbildningsuppdrag där skickliga resenärer skickas till Rawrk i Razor Hill, som...",kw={"lägereld","camping 101","durotar","first aid kit","rawrk","razor hill","överlevnad","läger i vildmarken"},ang={["faction:Horde"]="Utbildningen hålls i Razor Hill i Durotar och riktar sig till resenärer från Horde som vill klara sig själva i Kalimdors karga gränsland.",["profession:Cooking"]="Färdigheter för lägerlivet och matlagning hör ihop. Rawrk påpekar att ett ordentligt läger kräver en sprakande lägereld, en viktig teknik som lärs ut av matlagningsinstruktörer."},sec={{t="Överlevnad vid gränsen",b="För att överleva i Durotars otämjda vidder och bortom dem krävs mer än rå stridsstyrka; man måste kunna klara sig själv ute på vägarna. I Razor Hill erbjuder Rawrk vägledning åt dugliga vandrare som vill tillverka nödvändig utrustning för vildmarken. Genom Camping 101: First Aid får de som visat grundläggande färdigheter lära sig att sätta ihop ett särskilt First Aid Kit, så att de kan förbinda sår och ta hand om skador långt från tryggheten vid ett apotek eller en sjukstuga."},{t="Konsten att göra upp en lägereld",b="Att slå läger är en konst som styrs av praktisk gränslandsetikett och nödvändighet. Rawrk varnar äventyrare för att det inte uppskattas när de slår upp tält mitt i samhällen som Razor Hill. Därför måste de prova på att slå läger ute i vildmarken. Dessutom fungerar ingen lägerplats utan en sprakande lägereld som håller nattkylan borta. Därför är det en stor fördel för blivande campare att känna till matlagningens grunder, där man först lär sig att göra upp eld."}},faq={{q="Vem är Rawrk och var hittar man honom?",a="Rawrk finns i Razor Hill i Durotar. Han lär ut överlevnadskunskaper för lägerlivet och visar dem som redan behärskar grunderna hur de sätter ihop egna First Aid Kits för resor i vildmarken.",al={"vem lär ut campingens första hjälpen","var finns rawrk","camping 101 instruktör"}},{q="Vad krävs innan man slår läger i vildmarken?",a="För att slå läger behöver man en öppen plats i vildmarken och en ordentlig lägereld. Rawrk varnar för att det ogillas att slå läger innanför stadens gränser och påminner resenärer om att lära sig grunderna i att göra upp eld av en matlagningsinstruktör innan de ger sig av.",al={"vad behöver jag för att slå läger","hur slår man läger","krav på lägereld vid camping"}},{q="Kan man slå läger inne i städer eller samhällen?",a="Man kan inte slå läger i samhällen eller stadskärnor. Lokalbefolkningen motsätter sig att resenärer slår upp tält mitt på gatorna, så äventyrare måste bege sig ut i vildmarken för att slå läger.",al={"kan jag slå läger i razor hill","camping inne i städer","var kan jag slå läger"}},{q="Vad lär den här utbildningen äventyrare att tillverka?",a="När utbildningen är klar kan äventyrarna tillverka ett eget First Aid Kit, ett oumbärligt tillbehör i fält som hjälper dem att hålla sig friska och orka med längre utflykter i vildmarken.",al={"belöning från camping 101: first aid","vilket föremål lär uppdraget ut","tillverka first aid kit"}},{q="Varför rekommenderar Rawrk att man lär sig matlagning?",a="Ett ordentligt läger behöver en varm lägereld som samlingspunkt. Eftersom grunderna i att tända och sköta en enkel eld lärs ut av matlagningsinstruktörer råder Rawrk campare att lära sig matlagningens konst i förväg.",al={"varför behöver jag matlagning för camping","matlagning lägereld camping"}},{q="Vilka förkunskaper behövs för att lära sig hantverket?",a="Resenärer måste visa grundläggande färdigheter inom läkekonst och överlevnad innan Rawrk lär dem att tillverka ett särskilt First Aid Kit för fältbruk.",al={"förkunskaper för camping 101: first aid","färdighet som krävs för campingens första hjälpen"}}},fp="22,349,24.489.0,23.482.0,35.190.0,53.243.0,49.218.0,51.189.0,42.205.0,57.163.0"}
P.entries["quest:97905"] = {n="Camping 101: Herbalism",s="Camping 101: Herbalism lär samlare att tillverka rökelseljus av vilda växter. Här får du lära dig grunderna i vildmarksliv, från att bygga en ordentlig lägereld till att lämna städerna bakom dig innan du slår läger.",h="Camping 101: Herbalism lär samlare att tillverka rökelseljus av vilda växter.",kw={"läger","lägereld","camping","matlagning","örtmedicin","incense candle","vildmark"},ang={["profession:Cooking"]="Grundläggande matlagning lär resenärer att göra upp en ordentlig lägereld, som utgör den nödvändiga mittpunkten i varje läger.",["profession:Herbalism"]="Örtmedicinare lär sig att tillverka rökelseljus av insamlade växter och ge läger i vildmarken värme, väldoft och praktisk nytta."},sec={{t="Vildmarkens doftande hantverk",b="För att överleva i Azeroths vildmarker krävs mer än ett svärd; du behöver också kunna förvandla insamlade växter till praktiska bekvämligheter. Med örtmedicin lär sig samlare att tillverka egna rökelseljus och göra lugnande doftämnen av sådant de hittar längs vägen. Eftersom stadsbor ogillar tält som breder ut sig på stadens gator är ljusen avsedda att användas långt bortom de bevakade bosättningarnas murar."},{t="Lägerplatsens hjärta",b="Inget läger i vildmarken är komplett utan en välkomnande brasa. Innan ett rökelseljus kan komma till användning måste du slå läger med en ordentlig lägereld i mitten. Örtmedicinare står för den väldoftande lågan, men resenärer får vända sig till matlagningens konst för att lära sig grunderna i att göra upp eld av kockar runt om i landet."}},faq={{q="Vad är ett rökelseljus?",a="Ett rökelseljus är ett väldoftande campingredskap som tillverkas av örtmedicinare. Det görs av vilda växter och är avsett att brännas på en lägerplats i vildmarken, intill en sprakande lägereld.",al={"vad är ett rökelseljus","använda rökelseljus","campingföremål örtmedicin"}},{q="Var kan du slå läger?",a="Du kan inte slå läger i stadskärnor, eftersom stadsbor ogillar när resenärer breder ut sig på allmänna gator. Den som vill prova ett rökelseljus och slå läger måste bege sig ut i den öppna vildmarken.",al={"var slå läger","kan jag slå läger i en stad","camping i städer"}},{q="Varför behöver du en lägereld för att slå läger?",a="Varje fungerande läger behöver en sprakande lägereld i mitten. Kockar runt om i Azeroth lär ut grunderna i att bygga en lägereld, så resenärer bör studera matlagningens grunder innan de ger sig av.",al={"hur göra upp en lägereld","lägereld behövs för läger","kock lägereld camping"}},{q="Vem lär ut hur man gör upp en lägereld?",a="Kockar lär resenärer att tända en enkel lägereld. Om du lär dig grunderna i matlagning får du den grund du behöver för att tända en eld i vildmarken.",al={"vem lär ut lägereldar","lära sig göra upp eld","kock lägereld"}},{q="Hur hänger örtmedicin ihop med camping?",a="Örtmedicin ger de aromatiska växter och kådor som behövs för att tillverka särskilda rökelseljus. De förhöjer lägerplatsen med rogivande växter som skördats ute i vildmarken.",al={"örtmedicin koppling till camping","varför örtmedicin camping","vad ger örtmedicin till läger"}},{q="Behöver du en lägereld för att använda ett rökelseljus?",a="Ett läger anses inte vara komplett utan en ordentlig lägereld. Resenärer ska först anlägga en lägereld innan de slår sig till ro och njuter av fördelarna med ett rökelseljus.",al={"kan jag tända rökelseljus utan eld","krävs lägereld för rökelseljus"}}},fp="22,255,26.413.0,25.346.0,26.180.0,28.226.0,44.218.0,35.171.0,36.190.0,48.186.0"}
P.entries["quest:97907"] = {n="Camping 101: Mining",s="Camping 101: Mining är ett yrkesuppdrag som lär blivande gruvarbetare grunderna och leder dem till Krunn i Razor Hill. Där får de visa sin skicklighet och lära sig smida en Lodestone, en särskild lägeranordning som stärker krigarna kring en lägereld i vildmarken.",h="Camping 101: Mining är ett yrkesuppdrag som lär blivande gruvarbetare grunderna och leder dem till Krunn i...",kw={"läger","lägereld","camping 101: mining","matlagning","durotar","krunn","lodestone","gruvdrift","razor hill"},ang={["faction:Horde"]="Hordens gruvarbetare som reser genom Durotar kan bege sig till Krunn i Razor Hill för att lära sig tillverka Lodestones till sina expeditioner.",["profession:Cooking"]="Matlagningsinstruktörer lär ut grunderna i att göra upp en enkel lägereld, mittpunkten i varje fungerande läger i vildmarken.",["profession:Mining"]="Med gruvdrift kan du gräva fram råa mineraler och tillverka särskild fältutrustning som en Lodestone för att hjälpa dina allierade i lägret."},sec={{t="Gruvarbetarens läger",b="Gruvdrift ger en hederlig försörjning och praktiska material för utforskning och överlevnad i vildmarken. När gruvarbetare utvecklar sitt yrke och visar att de kan hantera hacka och malm, kan de lära sig tillverka särskild lägerutrustning. I Durotar hänvisas skickliga gruvarbetare till Krunn i bosättningen Razor Hill, där de kan lära sig smida en Lodestone för sina resor."},{t="Gemenskap vid lägerelden",b="En Lodestone blir en lockande mittpunkt för äventyrare som vilar i vildmarken. När den placeras vid ett läger ger den krigare som samlas vid elden ett övertag i strid. Men god lägeretikett kräver att du lämnar bosättningarna bakom dig: stadsbor ogillar läger på torg, så resenärer måste söka sig ut i vildmarken för att pröva sitt hantverk."},{t="Eld och friluftskunskap",b="Även den stadigaste Lodestone är värdelös utan en ordentlig eld som förankrar lägret. En enkel lägereld behövs innan du slår läger, och den som inte kan göra upp eld bör söka upp en matlagningsinstruktör. Träning i matlagning ger expeditioner i vildmarken den värme och grundläggande näring som krävs för att överleva utanför stadsmurarna."}},faq={{q="Vad är Camping 101: Mining?",a="Camping 101: Mining är ett introduktionsuppdrag för gruvarbetare. Det leder gruvarbetare som har visat sin skicklighet till Krunn i Razor Hill, där de får lära sig tillverka ett praktiskt lägerföremål som kallas Lodestone.",al={"vad är camping 101 mining","gruvuppdraget camping","gruvuppdraget lodestone"}},{q="Vem är Krunn?",a="Krunn är en instruktör i Razor Hill i Durotar. Han lär skickliga gruvarbetare att tillverka lägerföremål som Lodestone när de har visat tillräcklig yrkesskicklighet.",al={"vem är krunn","var finns krunn","instruktör i razor hill"}},{q="Vad används en Lodestone till?",a="En Lodestone är en lägeranordning som gruvarbetare kan tillverka. När den placeras vid en lägereld i vildmarken ger den fysiska stridskämpar som samlas kring elden extra stridsförmåga och stärker deras kampkraft.",al={"vad gör en lodestone","lodestones fördel","varför tillverka lodestone"}},{q="Kan du slå läger i Razor Hill?",a="Stadsbor och bosättningens myndigheter uppskattar inte läger på befolkade gator. Du måste ge dig ut i den omgivande vildmarken för att slå läger och placera din Lodestone.",al={"kan jag slå läger i en stad","varför kan jag inte slå läger i razor hill","läger i städer"}},{q="Varför behöver du en lägereld innan du slår läger?",a="Varje fungerande läger behöver en lägereld i mitten. Matlagningsinstruktörer lär ut hur man gör upp en enkel lägereld, så matlagning är ett viktigt komplement för den som ger sig ut i vildmarken.",al={"behöver jag en lägereld","hur börjar jag slå läger","eldkrav för läger"}},{q="Vem kan lära sig tillverka en Lodestone?",a="För att tillverka en Lodestone behöver du utbildning i gruvdrift. Gruvarbetare som visar tillräcklig skicklighet kan lära sig tekniken direkt av Krunn i Razor Hill.",al={"vem kan tillverka lodestones","kan vem som helst tillverka en lodestone"}}},fp="19,287,16.379.0,20.419.0,19.382.0,28.220.0,13.183.0,29.211.0,38.209.0,50.208.0,35.178.0"}
P.entries["quest:97908"] = {n="Camping 101: Skinning",s="Camping 101: Skinning är ett introduktionsuppdrag i vildmarken som hänvisar garvare i Orgrimmar till Thuwd, där de får lära sig tillverka en Camp Chair. Genom att använda insamlade hudar för ökad komfort kan äventyrare ordna riktiga läger ute i Kalimdors vildmark.",h="Camping 101: Skinning är ett introduktionsuppdrag i vildmarken som hänvisar garvare i Orgrimmar till Thuwd...",kw={"camp chair","lägereld","camping","camping 101: skinning","orgrimmar","garvning","thuwd"},ang={["faction:Horde"]="Thuwd tränar garvare i Orgrimmar, vilket gör denna introduktion till vildmarkshantverket särskilt lättillgänglig för Horde-äventyrare som utgår från Durotar.",["profession:Cooking"]="En ordentlig lägerplats behöver både sittplats och värme. Nybörjare inom garvning uppmuntras att studera grunderna i matlagning för att lära sig göra en enkel lägereld."},sec={{t="Bekvämlighet i vildmarken",b="Att ta till vara på pälsar och hudar från fallna bestar är en av de mest praktiska överlevnadskunskaper en äventyrare kan skaffa sig i vildmarken. Råa läder används oftast till rustningstillverkning, men skickliga garvare kan också förvandla pälsarna de samlat in till bekvämligheter för lägret. I Orgrimmar hänvisar instruktörer dugliga garvare till Thuwd, där de får lära sig hantverket att sätta ihop en stadig Camp Chair av garvade hudar."},{t="Vildmarkens regler",b="Stadsbor och vakter ogillar när resenärer slår upp tillfälliga läger längs stadens vältrafikerade gator. Som Thuwd påminner nya hantverkare om är en lägerstol avsedd för öppna områden bort från bosättningars murar. Dessutom är inget läger i vildmarken komplett med bara sittplatser. En ordentlig lägerplats behöver en varm lägereld, en grundläggande teknik som kockar lär ut över hela Kalimdor."}},faq={{q="Vem lär garvare att tillverka lägerföremål?",a="Uppdraget hänvisar garvarelever till Thuwd, en tränare i läderarbete och garvning i Orgrimmar, Hordens huvudstad, när de har visat grundläggande skicklighet i sitt insamlingshantverk.",al={"vem ger camping 101: skinning","vem ska man prata med i orgrimmar","vem är thuwd"}},{q="Vilket lägerföremål kan garvare tillverka?",a="Garvare lär sig att tillverka en Camp Chair av hudar och pälsar från fallna bestar. Den ger en bekväm plats att sitta på och vila och återhämta sig ute i vildmarken.",al={"vad tillverkar garvare för lägret","garvning och lägerhantverk","camp chair och garvning"}},{q="Kan du slå upp en lägerstol i en stad?",a="Stadsbor och vakter ogillar när man ställer upp lägerutrustning mitt i stan. Äventyrare måste ge sig ut i vildmarken bortom bosättningens portar för att slå läger och ställa fram stolen.",al={"kan jag slå läger i orgrimmar","läger i staden","var kan man slå läger"}},{q="Vad mer behövs för ett komplett läger?",a="En lägerplats är ofullständig utan en eld som ger värme, ljus och möjlighet att laga mat. Äventyrare rekommenderas att rådfråga en matlagningstränare och lära sig att göra en enkel lägereld innan de slår läger.",al={"varför behövs en lägereld","krav för lägerplats","hur slår man läger"}},{q="Varför bör en äventyrare tillverka en lägerstol?",a="En stunds vila i en bekväm stol mellan jakterna hjälper äventyrare att återhämta sig efter färden och hålla sig i toppform inför nästa skärmytsling.",al={"garvningens nytta för camping","varför vila i en camp chair","fördelar med camp chair"}},{q="När lär Thuwd ut mönstret för Camp Chair?",a="Garvare måste visa grundläggande skicklighet i att ta till vara på skinn och hudar från fallna bestar innan Thuwd delar med sig av hemligheterna bakom möbler för läger i vildmarken.",al={"när kan jag lära mig camp chair","krav för camping 101","vilken garvningsnivå behövs"}}},fp="21,260,19.381.0,18.353.0,44.209.0,37.172.0,42.203.0,41.191.0,44.181.0,45.167.0"}
P.entries["quest:97914"] = {n="Expanding Horizons",s="Thundris Windweaver skickar bud från Auberdine över det stora havet till Stormwind. Brevet ber stadsarkitekten Baros Alexston att erkänna Auberdines arbete och dess hem.",h="Thundris Windweaver skickar bud från Auberdine över det stora havet till Stormwind.",kw={"ameth'aran","auberdine","baros alexston","bashal'aran","darkshore","darnassus","expanding horizons","hamn","stormwind","thundris windweaver"},ang={["faction:Alliance"]="Som medlem av alliansen ser du arbetet som krävs för att ena folk från två kontinenter i en enda fraktion.",["race:Human"]="Som människa ser du hur det återuppbyggda rikets räckvidd växer när du återvänder till Stormwind med en kaldoreisk bosättnings sigill.",["race:NightElf"]="För kaldorei innebär öppnandet av sjövägar till Eastern Kingdoms ett brott med tiotusen års isolering och knyter ditt folk till människornas civilisation."},sec={{t="Vidgade vyer",b="Auberdine förbinder nu Darkshore med Stormwind till havs. Night elves höll sig en gång till Kalimdors skogar, skilda från Eastern Kingdoms, men efter det tredje kriget anslöt de sig till den stora alliansen. Den nya förbindelsen ger den nordliga hamnen en direkt länk till människoriket. Lokala ledare vill säkra sjövägen och knyta Auberdine till den bredare alliansen. Ameth'Aran och Bashal'Aran, närliggande ruinstäder, har länge fått mer uppmärksamhet än den levande kustbosättningen."},{t="Ett brev till stadsarkitekten",b="Brevet som korsar det stora havet är adresserat till Baros Alexston, Stormwinds stadsarkitekt. Han övervakar byggande och infrastruktur i människorikets huvudstad, däribland offentliga arbeten och logistik. Thundris Windweaver vill att Auberdines arbete erkänns och att dess hem blir känt."}},faq={{q="Vem skickar dig på det här uppdraget?",a="Thundris Windweaver, en inflytelserik Night Elf i Auberdine, ber dig att bära brevet. Han tycker att Darnassus och allierade på andra sidan havet förbiser bosättningen och söker en formell länk till människoriket.",al={"uppdragsgivare expanding horizons","vem ger expanding horizons","thundris uppdrag"}},{q="Vem är Baros Alexston?",a="Baros Alexston är Stormwinds stadsarkitekt. Han är en respekterad stadsplanerare som kände Edwin VanCleef när de var yngre och övervakar byggande och strukturell förvaltning i hela huvudstaden.",al={"baros alexston bakgrund","vem är baros","stadsarkitekt stormwind"}},{q="Varför vänder sig Auberdine till Stormwind?",a="Auberdine vill att hamnen erkänns som en inkörsport för förnödenheter, handel och alliansens resor. Lokala ledare hoppas att de nya sjövägarna mellan Darkshore och Eastern Kingdoms ska stärka de ekonomiska banden och logistiken med människoriket.",al={"varför skicka brev till stormwind","förbindelse mellan auberdine och stormwind","varför kontakta människor"}},{q="Hur fungerar resan mellan Auberdine och Stormwind?",a="Ett fartyg seglar nu från Auberdine över det stora havet till Stormwind Harbor och för med sig förnödenheter och liv till Auberdines stränder.",al={"båt till stormwind","hur tar man sig från auberdine till stormwind"}},{q="Vad är Ameth'Aran och Bashal'Aran?",a="Ameth'Aran och Bashal'Aran var välmående städer för högborna i forntida Darkshore. Den stora klyvningen slet sönder kontinenten för tiotusen år sedan, och städerna ligger nu som hemsökta ruiner, mer framträdande i kaldoreisk historia än levande byar som Auberdine.",al={"ameth aran bakgrund","bashal aran","forntida städer i darkshore"}},{q="Varför lämna brevet till en arkitekt i stället för kung Anduin eller Bolvar?",a="Thundris Windweaver anger ingen anledning till sitt val. Han ber dig ta brevet till Baros Alexston, Stormwinds stadsarkitekt, så att Auberdines arbete kan erkännas.",al={"varför baros alexston","varför inte bolvar","varför inte överherre bolvar"}}},fp="18,170,24.466.0,31.276.0,28.220.0,22.205.0,43.245.0,53.125.0,36.262.0,66.168.0"}
P.entries["quest:97916"] = {n="Camping 101: Blacksmithing",s="Camping 101: Blacksmithing är en introduktionsuppgift i Goldshire som lär smeder att tillverka utrustning för fältbruk. Genom att rådfråga Smith Argus lär sig skickliga metallarbetare att smida en bärbar Sharpening Wheel för resor i vildmarken. Uppgiften betonar beredskap för fältet och visar hur viktigt det är med öppen mark och en ordentlig lägereld för att slå läger.",h="Camping 101: Blacksmithing är en introduktionsuppgift i Goldshire som lär smeder att tillverka utrustning för...",kw={"smide","lägereld","läger","camping 101","elwynn forest","goldshire","sharpening wheel","smith argus"},ang={["faction:Alliance"]="Alliansens hantverkare som börjar sin resa i Goldshire kan rådfråga Smith Argus för att förbereda sig inför långa expeditioner bortom stadsmurarna.",["profession:Blacksmithing"]="Smeder som lär sig sitt hantverk i Elwynn Forest kan tillverka en Sharpening Wheel för att underhålla utrustningen och slipa klingor ute i fält.",["profession:Cooking"]="Ett ordentligt läger kräver en pålitlig eld, så grundläggande matlagningskunskaper passar naturligt ihop med metallarbete i vildmarken."},sec={{t="Smide för färden",b="Smith Argus i Goldshire vägleder blivande metallarbetare i hur de kan ta med sig sitt hantverk på vägarna. Smeder som visar tillräcklig skicklighet kan lära sig att tillverka praktisk utrustning för ett liv ute i det fria, i stället för att vara bundna till stadens städ. Lärdomen handlar om att smida en egen Sharpening Wheel, ett viktigt verktyg för att hålla klingor vassa under långa resor."},{t="Livet i fält",b="Att slå läger kräver mer än fältutrustning. God sed och förberedelser i vildmarken är lika viktiga. Stadsbor ogillar att någon slår läger mitt i en bosättning som Goldshire, så hantverkare måste söka sig ut i det öppna landskapet för att använda sin utrustning. Dessutom är inget läger komplett utan en varm lägereld. Därför är ett besök hos en lokal kock för att lära sig grunderna i att göra upp eld ett nödvändigt första steg."}},faq={{q="Vad är Camping 101: Blacksmithing?",a="Uppdraget introducerar blivande smeder till överlevnadshantverk och lär dem att smida en bärbar Sharpening Wheel för expeditioner i vildmarken.",al={"vad gör det här uppdraget","syftet med camping 101 blacksmithing","vad lär jag mig"}},{q="Vem är Smith Argus?",a="Smith Argus är smeden och tränaren i Goldshire i Elwynn Forest. Han lär lovande smeder grunderna i metallarbete och lägerhantverk.",al={"vem är smith argus","smedtränare i goldshire","argus goldshire"}},{q="Vad är en Sharpening Wheel?",a="Sharpening Wheel är ett yrkesspecifikt föremål för läger som smeder lär sig att tillverka inför sina expeditioner. Den låter dem slipa verktyg och vapen långt från stadens vanliga smedjor.",al={"vad är en sharpening wheel","sharpening wheel för läger","lägerföremål för smeder"}},{q="Kan du slå läger inne i staden?",a="Stadsbor uppskattar inte att man slår läger i bebodda områden som Goldshire. Smeder måste bege sig ut i vildmarken för att sätta upp sin utrustning.",al={"kan jag slå läger i goldshire","slå upp tält i staden","var kan jag slå läger"}},{q="Varför behöver du en lägereld för att slå läger?",a="Ett läger är inte komplett utan en sprakande lägereld. Smeder bör rådfråga en matlagningstränare och lära sig grunderna i att göra upp eld innan de ger sig av.",al={"behöver jag kunna matlagning för att slå läger","lägereld för lägret","hur slår jag läger"}},{q="När kan du lära dig det här lägerhantverket?",a="Du måste visa tillräcklig skicklighet i smide innan Smith Argus lär dig att smida särskild lägerutrustning.",al={"krav för camping 101","krav på smideskunskaper"}}},fp="26,355,21.401.0,17.424.0,35.150.0,19.170.0,27.188.0,32.150.0,40.167.0,38.141.0"}
P.entries["quest:97917"] = {n="Camping 101: Enchanting",s="Camping 101: Enchanting skickar förtrollare till Betty Quin i Stormwind för att lära sig särskilda lägerfärdigheter. Genom att förse fritidsföremål som Enchanted Lute med magi hjälper förtrollare till att hålla humöret uppe och kroppen utvilad längs vägen.",h="Camping 101: Enchanting skickar förtrollare till Betty Quin i Stormwind för att lära sig särskilda...",kw={"betty quin","läger","camping 101","camping 101: enchanting","enchanted lute","förtrollning","stormwind"},ang={["faction:Alliance"]="Förtrollare som färdas genom alliansens områden hänvisas till hjärtat av Stormwind för att söka upp Betty Quin och få lägerundervisning."},sec={{t="Magi längs vägen",b="Livet på vägarna genom Azeroth kräver mer än stål och ransoner; moral och bekvämlighet ute i vildmarken är lika viktiga för att överleva långa resor. Förtrollare tillför magisk flärd vid lägerelden och använder sin esoteriska konst för att förvandla lugna vilostunder till stärkande underhållning som förbereder resenärer på prövningarna längs vägen."},{t="Sök upp Betty Quin",b="Förtrollare som vill tillverka särskilda lägerföremål hänvisas till Betty Quin i Stormwind. När en utövare har visat tillräcklig skicklighet i förtrollning kan hon dela med sig av kunskapen som krävs för att skapa Enchanted Lute, ett instrument vävt med besvärjelser som lyfter humöret runt lägerelden."}},faq={{q="Vad är Camping 101: Enchanting?",a="Camping 101: Enchanting visar utövare av förtrollningskonsten hur de tillverkar magiska lägerförnödenheter. När de har förfinat sin konst skickas blivande förtrollare till Betty Quin i Stormwind.",al={"vad är camping 101: enchanting","camping 101 för förtrollare","lägeruppdrag i förtrollning"}},{q="Vem är Betty Quin?",a="Betty Quin är en instruktör i Stormwind som lär kunniga förtrollare att tillverka användbar magisk utrustning för överlevnad och avkoppling på vägarna.",al={"vem är betty quin","betty quin, förtrollningsinstruktör i stormwind","var finns betty quin"}},{q="Vad är Enchanted Lute?",a="Enchanted Lute är ett musikinstrument genomsyrat av magi, avsett att ge underhållning och höja moralen under vilostunder vid lägret. Det hjälper äventyrare att möta svårigheter när de ger sig ut på vägarna.",al={"vad gör enchanted lute","varför tillverka enchanted lute","enchanted lutes syfte"}},{q="Varför uppskattas förtrollare vid ett läger?",a="Förtrollare bidrar med välgörande magi vid lägret och förvandlar vanliga vilostunder till tillfällen för återhämtning, förberedelser och nöjen som hjälper resenärer att uthärda hårda färder genom vildmarken.",al={"varför behövs förtrollare vid läger","nytta med förtrollare vid läger"}},{q="Vart ska jag gå för att slutföra uppgiften?",a="Uppdraget leder dig till Betty Quin i huvudstaden Stormwind, som ligger i kungariket med samma namn.",al={"var lämnar jag in camping 101: enchanting","betty quins plats"}},{q="Vilken färdighet krävs för att lära sig recept på förtrollningar för läger?",a="Du måste visa goda kunskaper i förtrollning innan Betty Quin lär dig att tillverka lägerföremål som Enchanted Lute.",al={"krav för camping 101: enchanting","när kan jag lära mig enchanted lute"}}},fp="23,252,18.332.0,18.297.0,32.216.0,18.157.0,26.193.0,40.185.0,36.119.0,57.139.0"}
P.entries["quest:97919"] = {n="Camping 101: First Aid",s="På Lion's Pride Inn visar Michelle Belle resenärer hur de förbereder ett läger. I Goldshire kan du lära dig att tillverka ett First Aid Kit inför den fortsatta färden.",h="På Lion's Pride Inn visar Michelle Belle resenärer hur de förbereder ett läger.",kw={"förband","lägerkit","camping 101","elwynn forest","first aid","goldshire","michelle belle","överlevnad"},ang={["class:Rogue"]="Som skurk som verkar i skuggorna långt från hjälp förlitar du dig på fältmedicin för att förbinda blödande sår innan du går vidare till nästa mål.",["class:Warrior"]="Utan medfödda läkande besvärjelser förlitar du dig som krigare på förband och fältkit för att uthärda långa fälttåg i vildmarken.",["faction:Alliance"]="Goldshire är en viktig vägkorsning för Alliansens resenärer på väg från Northshire in i Elwynn."},sec={{t="Fältmedicin på vägen",b="Resor genom Elwynn Forest kan lämna dig skadad, långt från en stadsläkare eller ett värdshus. First Aid låter dig ta hand om dina egna skador och klara dig utan att förlita dig på andra. Förband hjälper mot blödningar och skador, utan arkaniska ritualer eller helig bön."},{t="Förnödenheter till lägret",b="Ett läger erbjuder en plats att vila på bland vildmarkens faror. På Lion's Pride Inn i Goldshire lär Michelle Belle skickliga utövare att sätta ihop First Aid Kits. Förvara sjukvårdsutrustning i lägret så att en trött grupp kan behandla skador och återfå krafter innan den möter farorna längre fram."}},faq={{q="Vad är syftet med det här uppdraget?",a="Äventyrare som har lärt sig grunderna i First Aid söker upp Michelle Belle i Goldshire. Hon lär dem att tillverka ett First Aid Kit och förse ett vildmarksläger med sjukvårdsutrustning.",al={"syftet med camping 101: first aid","vad går uppdraget ut på","varför camping 101: first aid"}},{q="Vem behöver jag tala med i Goldshire?",a="Tala med Michelle Belle, en First Aid-tränare i Goldshire. När du visar tillräcklig skicklighet lär hon dig tekniker för att tillverka campingutrustning anpassad för fältmedicin.",al={"vem är michelle belle","campingtränare i goldshire","first aid-tränare i lägret"}},{q="Varför är First Aid viktigt för resenärer?",a="First Aid hjälper resenärer att ta hand om skador från vilddjur, banditer och hårt väder. Det låter vem som helst, oavsett om de brukar gudomlig eller arkanisk magi, förbinda sår och återhämta sig mellan skärmytslingar.",al={"varför lära sig first aid","är first aid användbart","first aid-lore"}},{q="Var ligger Goldshire?",a="Goldshire är den främsta byn i Elwynn Forest, strax söder om Stormwind City längs den stora handelsvägen. Det är en central knutpunkt för förnödenheter och lokala tränare, med vila på Lion's Pride Inn.",al={"var ligger goldshire","goldshires läge","hur hittar man michelle belle"}},{q="Behöver jag tidigare träning för att klara uppgiften?",a="Ja. Michelle Belle ber dig visa att du behärskar First Aid innan hon lär dig att tillverka lägerkit.",al={"krav för camping 101","krävs first aid-färdighet","förkunskaper"}},{q="Hur passar ett First Aid Kit in i camping?",a="En vildmarkscamping erbjuder en trygg plats att återhämta sig på. Ett First Aid Kit håller förband och läkemedel nära till hands, sådant som behövs för att rädda liv långt från stadens läkare.",al={"användning av first aid kit i lägret","first aid-föremål för camping","varför tillverka ett first aid kit"}}},fp="22,152,26.263.0,25.292.0,34.170.0,41.180.0,41.194.0,27.196.0,47.107.0,42.177.0"}
P.entries["quest:97920"] = {n="Camping 101: Fishing",s="I Elwynn Forest söker nybörjarfiskare sätt att göra lägerlivet bekvämare. Nära Goldshire lär fiskeexperten Lee Brown resande hur fiske kan ge enkla bekvämligheter på lägerplatsen.",h="I Elwynn Forest söker nybörjarfiskare sätt att göra lägerlivet bekvämare.",kw={"lägerhantverk","camping 101: fishing","crystal lake","elwynn forest","fish bowl","goldshire","lee brown"},ang={["faction:Alliance"]="Som mänsklig resande på väg ut i Elwynn Forest kan du lära dig att klara dig själv i vildmarken vid Goldshires välbekanta vatten."},sec={{t="Lägerliv för fiskare",b="Fiske ger dig mat, men lägerlivet kräver mer än mat och skydd. En Fish Bowl kan skänka tröst och muntra upp trötta resande mellan utflykterna. Klara tankar och gott mod bidrar till att skapa formidabla kämpar."},{t="Lee Browns expertis",b="Lee Brown väntar vid vattnen utanför Goldshire för att hjälpa nybörjarfiskare att utveckla sitt hantverk. Resande som visar skicklighet med spö och lina kan lära sig hur enkla fångster och grundläggande material blir användbara tillskott på en lägerplats."}},faq={{q="Vad är syftet med det här uppdraget?",a="Lee Brown nära Goldshire vägleder blivande fiskare. När du har visat grundläggande fiskeskicklighet lär han dig att tillverka lägerföremål, som en Fish Bowl för lägerplatser längs vägen.",al={"varför fiska på läger","vad gör camping 101","syftet med uppdraget"}},{q="Vem är Lee Brown?",a="Lee Brown är en fisketränare vid Crystal Lake, strax utanför Goldshire i Elwynn Forest. Han lär ut fiske och hur man tillverkar lägerutrustning för fiskare.",al={"var finns lee brown","vem lär ut lägerfiske","lee brown"}},{q="Vad gör en Fish Bowl för en lägerplats?",a="En Fish Bowl skänker tröst och glädje på en lägerplats. En trivsam omgivning höjer moralen och hjälper äventyrare att känna sig redo och kapabla när de möter vildmarken.",al={"fish bowls effekt","vad gör en fish bowl","varför göra en fish bowl"}},{q="Var sker den här träningen?",a="Träningen sker i Elwynn Forest, vid vattnen runt Goldshire där lokala fiskare samlas.",al={"uppdragets plats","vart ska jag gå","lägertränare i elwynn forest"}},{q="Behöver jag kunna fiska sedan tidigare för att klara det här?",a="Ja. Lee Brown undervisar resande som har övat på att kasta och visat grundläggande fiskeskicklighet.",al={"krav på fiskeskicklighet","behöver jag kunna fiska","krav på förkunskaper"}},{q="Är lägerliv användbart i strid?",a="Ja. Ett välskött läger skänker bekvämlighet som förbättrar äventyrarens fysiska och mentala beredskap, motståndskraft och effektivitet i strid ute i fält.",al={"hjälper lägerliv i strid","lägerbonusar","varför slå läger"}}},fp="20,188,21.224.0,21.228.0,34.170.0,17.158.0,40.155.0,36.101.0,50.93.0,29.154.0"}
P.entries["quest:97921"] = {n="Camping 101: Herbalism",s="Camping 101: Herbalism är ett träningsuppdrag som skickar skickliga samlare till specialiserad vildmarksundervisning i Elwynn Forest. När de visat att de kan skörda växter hänvisas örtisterna till Herbalist Pomeroy för att lära sig tillverka lägerutrustning. Efter utbildningen kan du skapa Incense Candles, växtbaserade hjälpmedel som stärker besvärjares fokus och humör när de vilar ute i fält.",h="Camping 101: Herbalism är ett träningsuppdrag som skickar skickliga samlare till specialiserad...",kw={"läger","camping 101","lägerplats","elwynn forest","helare","herbalism","herbalist pomeroy","incense candle","besvärjare"},ang={["class:Mage"]="Magiker i fält uppskattar de lugnande egenskaperna hos Incense Candles. Därför är en örtist i sällskapet särskilt eftertraktad på långa resor genom vildmarken.",["class:Priest"]="Präster och andra hängivna helare har stor nytta av att vila nära Incense Candles. Ljusen höjer humöret och hjälper dem att återfå livskraft under expeditioner i vildmarken.",["faction:Alliance"]="Eftersom Herbalist Pomeroy bor i Elwynn Forest har Alliansens äventyrare nära till den här specialiserade lägerundervisningen.",["profession:Herbalism"]="Uppdraget gör Herbalism till mer än ett enkelt samlaryrke och ger örtister en aktiv roll i lägrets försörjning. De kan tillverka Incense Candles som hjälper reskamraterna."},sec={{t="Växtbaserad utrustning för resan",b="För kringvandrande örtister tjänar örtskörd i Azeroths vildmark till mycket mer än att brygga enkla läkande drycker eller sälja blomsterknippen till stadens köpmän. När samlarna förfinar sitt hantverk får de möjlighet att använda sina växtkunskaper för att överleva i vildmarken. Ett läger behöver mer än en sprakande eld och en torr sovrulle. För att resesällskapet ska orka och behålla skärpan krävs särskild bekvämlighet. Erfarna växtsamlare vet att vissa växter har aromatiska egenskaper som kan pigga upp trötta sinnen. Genom att hänvisa lovande örtister till erfarna läromästare förenar uppdraget enkel insamling med praktiskt fältarbete. Det visar att ett tränat öga för naturens rikedomar kan hålla en hel expedition vid liv långt från civilisationen."},{t="Herbalist Pomeroys vägledning",b="Örtister som vill utveckla sitt kunnande om lägerutrustning skickas till hjärtat av Elwynn Forest för att träffa Herbalist Pomeroy. Pomeroy kan mycket om växterna i skogarna omkring sig och vet hur torkade kronblad, aromatiska stjälkar och naturliga hartser kan blandas till användbar lägerutrustning. Hon lär samlarna att tillverka ett Incense Candle, i stället för att använda örter enbart till alkemiska flaskor. När det brinner i lägret lugnar den väldoftande skapelsen utmattade resenärer och muntrar upp följeslagare som är beroende av mana. Om du hittar Pomeroy och visar att du behärskar skäran blir du en ovärderlig tillgång för varje äventyrssällskap som ger sig ut i den otämjda vildmarken."}},faq={{q="Vad är Camping 101: Herbalism?",a="Camping 101: Herbalism är ett introduktionsuppdrag där erfarna örtister får lära sig att utöka sitt samlaryrke med lägerutrustning. Du skickas till Elwynn Forest för att träffa Herbalist Pomeroy, som lär dig tillverka särskilda Incense Candles för läger i fält.",al={"uppdraget camping 101 herbalism","herbalismuppdrag för läger","vad är camping 101 herbalism"}},{q="Vem lär örtister lägerreceptet?",a="Herbalist Pomeroy lär ut örtisternas lägerrecept. Du hittar henne i Elwynn Forest, där hon delar med sig av sina kunskaper om lokala växter och visar skickliga samlare hur de tillverkar väldoftande Incense Candles som gör vilan i lägret behagligare.",al={"vem lär ut herbalism för läger","camping 101 instruktör","var finns herbalist pomeroy","herbalist pomeroys plats"}},{q="Vilket föremål får örtister lära sig att tillverka genom uppdraget?",a="När du slutför utbildningen kan du tillverka ett Incense Candle till lägret. Ljuset tillverkas av insamlade örter och växtmaterial. Det sprider lugnande dofter som höjer humöret och ger besvärjare och helare en välkommen fördel när de vilar i vildmarken.",al={"vad tillverkar örtister för läger","herbalismföremål för läger","incense candle herbalism","vad lär camping 101 ut"}},{q="Vilka krav finns för att börja på Camping 101: Herbalism?",a="Du måste ha yrket Herbalism och visa att du är tillräckligt skicklig på att samla innan du får uppdraget. När din färdighet i Herbalism har kommit förbi nybörjarnivån anser instruktörerna att du är redo att lära dig tillverka växtbaserad lägerutrustning av Herbalist Pomeroy.",al={"krav för camping 101 herbalism","när kan jag få camping 101 herbalism","vilken herbalismfärdighet krävs för camping 101"}},{q="Varför är Incense Candles användbara för äventyrssällskap?",a="Incense Candles sprider lugnande örtdofter som höjer modet och återställer det mentala fokuset. Besvärjare och helare i fält gör av med enorma mängder energi när de kanaliserar magiska krafter. Därför är den andliga och magiska förstärkning som de väldoftande ljusen ger särskilt värdefull när man återhämtar sig i vildmarken.",al={"vad gör incense candle","varför tillverka incense candle","fördelar med incense candle","användning av incense candle inom herbalism"}},{q="Var utspelar sig uppdraget?",a="Uppdraget tar äventyrarna till Elwynn Forest, det grönskande skogsområdet kring staden Stormwind. Du ger dig ut på landsbygden i Elwynn för att träffa Herbalist Pomeroy, slutföra uppdraget och lära dig att skapa växtbaserad lägerutrustning.",al={"zon för camping 101 herbalism","var lämnar jag in camping 101 herbalism","herbalismuppdrag i elwynn forest"}},{q="Kan personer utan Herbalism tillverka Incense Candle?",a="Nej, tillverkningen av Incense Candle är direkt knuten till yrket Herbalism. Receptet kräver särskilda kunskaper om vilda växter, bevarande av blommor och aromatiska essenser. Herbalist Pomeroy lär bara ut det till äventyrare som samlar växter.",al={"kan vem som helst tillverka incense candle","är incense candle enbart för herbalism","behöver jag herbalism för incense candle"}}},fp="22,450,32.806.0,33.739.0,31.293.0,46.240.0,55.276.0,58.300.0,55.310.0,33.278.0,44.262.0"}
P.entries["quest:97922"] = {n="Camping 101: Leatherworking",s="Camping 101: Leatherworking hänvisar blivande läderrustningsmakare till Adele Fielder i Goldshire för att lära sig tillverka ett resetält. Ett tält i vildmarken ger skydd och vila mot hårt väder och är ett viktigt överlevnadsredskap utanför bebodda orter.",h="Camping 101: Leatherworking hänvisar blivande läderrustningsmakare till Adele Fielder i Goldshire för att...",kw={"adele fielder","lägereld","camping","elwynn forest","goldshire","läderrustning","tält","överlevnad i vildmarken"},ang={["faction:Alliance"]="Den här utbildningen utgår från Goldshire i Elwynn Forest och vägleder Alliansens läderrustningsmakare till praktiska överlevnadskunskaper inför färder genom Azeroth.",["profession:Cooking"]="Adele Fielder påpekar att inget läger i vildmarken är komplett utan en lägereld och uppmanar resenärer att lära sig matlagning för att kunna tända en ordentlig brasa."},sec={{t="Skydd längs öppna vägar",b="För en äventyrare långt från stadens portar är skydd lika viktigt som rustning. Läderrustningsmakare i Elwynn Forest hänvisas till Adele Fielder i Goldshire för att utveckla sitt hantverk bortom enkla bälten och tunikor. När en hantverkare visar att hen behärskar hudar och nål delar Adele med sig av konsten att sätta ihop ett tåligt lägertält som står emot hårt väder under långa färder över land."},{t="Grunderna i lägerliv",b="Ett färdigt tält ger mer än bara skydd för syns skull; det håller trötta resenärer svala under brännande sol, torra i hällregn och utvilade mellan farliga möten. Men hänsyn till vildmarken och lokala regler spelar roll: invånarna i Goldshire och stadsvakterna tolererar inte läger mitt på stadens gator. Hantverkare måste bege sig ut i vildmarken för att slå läger, och Adele påminner alla vandrare om att inget läger är komplett utan en ordentlig lägereld, som man lär sig tända av en matlagningstränare."}},faq={{q="Vem lär läderrustningsmakare att tillverka tält?",a="Adele Fielder finns i staden Goldshire i Elwynn Forest. Hon lär kvalificerade läderrustningsmakare att tillverka tåliga överlevnadstält när de visat att de behärskar sitt hantverk.",al={"vem lär ut tältillverkning","adele fielder plats","läderrustningens tältlärare"}},{q="Vad är ett tillverkat tält till för?",a="Ett välgjort tält skyddar resenärer från extremt väder och håller dem svala under heta dagar och torra i kraftigt regn. Ännu viktigare är att det ger äventyrare den vila de behöver för att hålla sig alerta på färder genom vildmarken.",al={"varför tillverka tält","vad gör ett tält","tältets fördelar"}},{q="Kan man slå upp ett tält inne i en stad?",a="Tält kan inte slås upp var som helst; stadsbor ogillar när resenärer belamrar gator eller torg med läger. Äventyrare förväntas ta med sig utrustningen ut i vildmarken för att slå läger på rätt sätt.",al={"kan jag slå upp tält i en stad","var kan jag använda tält","tält i stormwind eller goldshire"}},{q="Vad mer behövs för att göra ett läger komplett?",a="Ett tält räcker inte för att skapa ett fungerande läger. Adele Fielder betonar att alla riktiga läger behöver en lägereld, som ger värme och praktisk nytta i vildmarken.",al={"vad mer behöver jag till ett läger","krav på lägereld för tältläger","hur gör jag lägerplatsen komplett"}},{q="Var kan en resenär lära sig att göra upp en lägereld?",a="Matlagningstränare och lokala kockar lär ut grunderna i att tända en lägereld. Äventyrare som förbereder sig för att slå läger hänvisas till matlagningskonsten, så att de vet hur de gör upp en pålitlig eld var de än färdas.",al={"vem lär ut lägereld","hur lär jag mig göra lägereld","eld till läger"}},{q="När kan en läderrustningsmakare lära sig att tillverka ett lägertält?",a="Blivande läderrustningsmakare måste först visa att de behärskar läderrustningens hantverk innan Adele Fielder lär dem att tillverka ett tält. När de visat tillräcklig skicklighet kan de lära sig tekniken.",al={"krav för tältfärdighet","hur får jag tältrecept","när kan jag tillverka tält"}}},fp="27,277,25.402.0,27.521.0,46.203.0,39.246.0,35.215.0,56.175.0,47.212.0,55.206.0"}
P.entries["quest:97923"] = {n="Camping 101: Mining",s="Camping 101: Mining är ett nybörjaruppdrag där gruvarbetare lär sig tillverka en lodestone som förbättrar lägerplatser i vildmarken. Under Gelman Stonehands ledning i Stormwind lär sig prospektörer att kanalisera jordens resonans för att stärka sina följeslagares stridsförmåga vid lägerelden.",h="Camping 101: Mining är ett nybörjaruppdrag där gruvarbetare lär sig tillverka en lodestone som förbättrar...",kw={"lägereld","camping 101: mining","lägerplats","gelman stonehand","lodestone","gruvdrift","stormwind","vildmark"},ang={["faction:Alliance"]="Gelman Stonehand verkar i Stormwind City och vägleder Alliansens hantverkare i att förvandla rå jordmagi till praktiska hjälpmedel ute i fält.",["profession:Cooking"]="Läger är helt beroende av en välskött lägereld, så grundläggande matlagningskunskaper är ett viktigt komplement till särskild lägerutrustning.",["profession:Mining"]="Gruvarbetare som finslipar sitt hantverk kan forma lodestones för att förbättra sina lägerplatser i vildmarken och ge stridsfördelar åt allierade som vilar intill dem."},sec={{t="Jordens resonans",b="Gruvdrift är hårt, hederligt arbete, men belöningen sträcker sig långt bortom att smälta råa tackor och forma rustningar. Hängivna gruvarbetare i Stormwind kan lära sig att utnyttja jordens naturliga magnetism och skapa en fungerande lodestone. När stenen placeras på en expeditionens lägerplats stärker den stridskraften hos alla krigare som samlas kring eldstaden. Gelman Stonehand, den erfarne gruvinstruktören i rikets huvudstad, lär ut hantverket till prospektörer som visar att de behärskar en hacka."},{t="Läger i vildmarken",b="En lodestone kan inte bara läggas på kullerstenen i Cathedral Square eller Trade District. Stadsbor ser ogärna att resenärer slår upp tillfälliga läger inom stadens gränser, så pionjärer måste bege sig ut i den otämjda vildmarken för att slå läger. Dessutom är specialutrustning som en lodestone värdelös utan lägereldens varma grund, en grundläggande överlevnadsfärdighet i vildmarken som kockar lär ut i hela riket."}},faq={{q="Vad är Camping 101: Mining?",a="Det här uppdraget introducerar gruvarbetare till konsten att tillverka särskilda förbättringar för lägerplatser. När du har visat att du behärskar gruvdrift talar du med Gelman Stonehand i Stormwind för att lära dig smida en lodestone.",al={"vad är camping 101 mining","uppdragsmål","vad ska jag göra"}},{q="Vem lär ut ritningen för lodestone?",a="Gelman Stonehand är en gruvtränare i Stormwind City. Han lär kvalificerade gruvarbetare att tillverka en lodestone som stärker deras expeditioner i vildmarken.",al={"vem lär ut lodestone","var finns gelman stonehand","stonehands plats"}},{q="Vad gör en lodestone?",a="En lodestone är ett föremål som placeras på en lägerplats i vildmarken. Den utstrålar en stärkande närvaro kring lägerelden och förbättrar stridsförmågan hos krigare och andra stridskämpar som samlas där för att vila.",al={"vad gör lodestone","lodestone-förstärkning","varför tillverka lodestone"}},{q="Kan jag slå läger inne i Stormwind?",a="Stadens myndigheter och vanligt folk uppskattar inte läger på torg eller längs stadens gator. Du måste bege dig ut i vildmarken, bortom bosättningens portar, för att slå läger och placera ut din lodestone.",al={"kan jag slå läger i staden","var kan jag slå läger","lägerbegränsningar"}},{q="Varför behöver jag en lägereld för att slå läger?",a="Varje lägerplats behöver en enkel lägereld som grund innan någon särskild lägerutrustning kan användas. Kockar lär ofta resenärer att göra upp eld med enkelt trä och flinta.",al={"behöver jag matlagning för att campa","hur slår jag läger","krav på lägereld"}},{q="Vem har störst nytta av att samlas kring en lodestone?",a="Alla som svingar ett svärd, en yxa eller en hammare har stor nytta av lodestonens kraft. Den skänker extra stridsförmåga som krigare söker medan de vilar vid lågorna inför en farlig strid.",al={"vem har nytta av lodestone","är lodestone till för närstrid","lodestone-klasser"}}},fp="19,281,26.496.0,30.439.0,28.209.0,36.163.0,25.207.0,35.210.0,40.192.0,52.198.0"}
P.entries["quest:97924"] = {n="Camping 101: Skinning",s="Camping 101: Skinning är en introduktionsuppgift för skickliga pälsjägare som färdas genom Elwynn Forest. Den hänvisar äventyrare till Helene Peltskinner i Goldshire för att lära sig tillverka en Camp Chair av skinn från fällda djur. När du kan tillverka egen lägerutrustning kan du vila och återhämta dig långt från tryggheten i bebodda samhällen.",h="Camping 101: Skinning är en introduktionsuppgift för skickliga pälsjägare som färdas genom Elwynn Forest.",kw={"camp chair","lägereld","camping 101: skinning","goldshire","helene peltskinner","pälsjakt","camping i vildmarken"},ang={["faction:Alliance"]="Nybörjare inom Alliansens pälsjägare som besöker Elwynn Forest hänvisas till Helene Peltskinner i Goldshire för att utveckla sina överlevnadskunskaper i vildmarken.",["profession:Cooking"]="Pälsjägare som lär sig att bygga ett läger i fältet rekommenderas att rådfråga en kock, eftersom ingen lägerplats är komplett utan en enkel lägereld att värma sig vid och laga mat över."},sec={{t="Bekvämlighet i vildmarken",b="För jägare och spejare i vildmarken ger konsten att ta till vara på djurhudar mer än handelsvaror och rustningsdelar. Erfarna pälsjägare kan tillverka praktiska saker för fältbruk, som en Camp Chair, så att resenärer kan sitta, vila benen och hålla sig i toppform under långa färder genom farliga områden. Helene Peltskinner i Goldshire lär skickliga pälsjägare att förvandla råa djurhudar till bekväma sittplatser för lägret."},{t="Regler för lägerplatsen",b="En viloplats i fältet kräver hänsyn till närliggande samhällen och goda förberedelser för friluftsliv. De flesta stadsbor ogillar när äventyrare slår upp personliga läger på torget, så resenärer måste bege sig ut i vildmarken innan de packar upp sin utrustning. Dessutom är ingen lägerplats riktigt användbar utan en lägereld, vilket får många pälsjägare att studera grunderna i matlagning och lära sig att göra upp eld."}},faq={{q="Vad är Camping 101: Skinning?",a="Camping 101: Skinning är en introduktionsuppgift där skickliga pälsjägare får lära sig att tillverka en Camp Chair av djurhudar, så att de bättre kan överleva i vildmarken.",al={"vad är camping 101 skinning","vad gör det här uppdraget","uppdrag om camp chair och pälsjakt"}},{q="Vem lär pälsjägare att tillverka en Camp Chair?",a="Helene Peltskinner, tränare i läderrustning och pälsjakt i Goldshire i Elwynn Forest, lär skickliga pälsjägare att tillverka stolen.",al={"vem lär ut camp chair","var finns helene peltskinner","var lämnar jag in camping 101 skinning"}},{q="Vad är syftet med att tillverka en Camp Chair?",a="En Camp Chair ger en äventyrare en bekväm sittplats vid lägret där hen kan vila och återhämta sig, så att hen håller sig i toppform för färder och strid i vildmarken.",al={"vad gör en camp chair","varför tillverka en camp chair","syftet med camp chair"}},{q="Var kan äventyrare slå läger?",a="Stadsbor i allmänhet ogillar att man slår läger mitt i samhällen. Äventyrare förväntas bege sig ut i vildmarken innan de ställer upp sina stolar och läger.",al={"kan jag slå läger i en stad","var kan jag ställa camp chair","camping i goldshire"}},{q="Vad mer behövs för att ordna en komplett lägerplats?",a="En ordentlig lägerplats behöver en enkel lägereld innan du packar upp utrustningen. Äventyrare som inte kan göra upp eld uppmuntras att lära sig matlagning av en lokal kock.",al={"vad behöver jag för ett läger","behöver jag en eld för att slå läger","krav på lägereld"}},{q="Vem kan lära sig det här lägerhantverket?",a="Det här lägerhantverket är avsett för pälsjägare som har visat att de kan ta till vara på hudar från fällda djur och använda skinnet de samlar in i fältet för praktisk överlevnad.",al={"vem kan lära sig camp chair","kan andra än pälsjägare göra det här","krav på pälsjakt för camping"}}},fp="21,368,29.435.0,21.394.0,30.200.0,47.149.0,45.173.0,34.188.0,51.174.0,44.199.0"}
P.entries["quest:97925"] = {n="Camping 101: Tailoring",s="Camping 101: Tailoring visar skickliga tygvävare vägen till Eldrin vid Eastvale Logging Camp i Elwynn Forest. Där lär sig skräddare att väva en Faction Banner som inspirerar och höjer moralen vid lägerplatser i vildmarken.",h="Camping 101: Tailoring visar skickliga tygvävare vägen till Eldrin vid Eastvale Logging Camp i Elwynn Forest.",kw={"fana","läger","camping 101","eastvale logging camp","eldrin","elwynn forest","faction banner","skrädderi"},ang={["faction:Alliance"]="Äventyrare från Alliansen hänvisas till Eldrin vid Eastvale Logging Camp i Elwynn Forest för att lära sig sy fraktionsfanor.",["profession:Tailoring"]="Skräddare kan väva en inspirerande Faction Banner som höjer moralen och håller humöret uppe i lägret under långa expeditioner."},sec={{t="Vävarens uppgift i vildmarken",b="Camping 101: Tailoring visar lovande nålarbetare vägen till Eldrin, en hantverkare vid Eastvale Logging Camp i östra Elwynn Forest. Skrädderi uppskattas ofta för skyddande kläder och väskor av tyg, men det här uppdraget lyfter fram dess roll i att stödja expeditioner i vildmarken. Äventyrare som visat fallenhet för nål och vävstol får särskild vägledning i att skapa lägertillbehör som underlättar långa färder genom vildmarken."},{t="Moralfanorna",b="Det främsta hantverket som lärs ut genom den här vägledningen är Faction Banner, ett emblem som är tänkt att stå stolt intill en resenärs lägereld. På farliga resor och slagfält är det lika viktigt att hålla moralen uppe som att ha vapen och proviant. En inspirerande fana över lägret ger trötta äventyrare en välbekant symbol för beslutsamhet och den energi de behöver för att fortsätta in i fientliga länder."}},faq={{q="Vad är syftet med Camping 101: Tailoring?",a="Camping 101: Tailoring visar blivande skräddare vägen till Eldrin vid Eastvale Logging Camp i Elwynn Forest. När en skräddare visar tillräcklig skicklighet lär Eldrin ut hur man syr en inspirerande Faction Banner som höjer moralen på lägerplatsen.",al={"vad är camping 101 tailoring","uppdrag om skrädderi och lägerföremål","hur får man en lägerfana"}},{q="Vem är Eldrin och var finns han?",a="Eldrin är en hantverkare som bor vid Eastvale Logging Camp i östra Elwynn Forest. Han kan lära skickliga skräddare att tillverka fraktionsfanor för läger.",al={"vem är eldrin","var finns eldrin","eldrins plats"}},{q="Vad gör Faction Banner för ett läger?",a="Faction Banner är lägrets mittpunkt och är tänkt att stärka moralen och inspirera. I fältet hjälper en visad trohet till att hålla trötta resenärer energiska och fokuserade under krävande fälttåg.",al={"vad gör skrädderifanorna","fraktionsfana till lägret","varför tillverka en fraktionsfana"}},{q="Vilka krav finns för att lära sig hantverket av Eldrin?",a="Du måste visa att du behärskar skrädderi innan Eldrin delar med sig av tekniken. Bara de som har förfinat sitt nålarbete kan väva och sätta ihop fanan på rätt sätt.",al={"vilken färdighet behövs","krav för lägerfana","kan alla skräddare göra en fana"}},{q="Var ligger Eastvale Logging Camp?",a="Eastvale Logging Camp ligger inbäddat i de östra skogarna i Elwynn Forest, längs vägen mot Redridge Mountains. Det är ett aktivt timmercentrum där lokala hantverkare och arbetare samlas.",al={"var ligger eastvale logging camp","eastvale logging camp i elwynn"}},{q="Är det här uppdraget bara för Alliansens skräddare?",a="Det här ärendet leder hantverkaren till Eldrin i hjärtat av Elwynn Forest, mitt i Alliansens territorium. Därför riktar det sig till hantverkare som står på Alliansens sida och verkar i de östra bosättningarna.",al={"kan horden göra det här uppdraget","är detta bara för alliansen"}}},fp="22,234,30.473.0,17.433.0,46.267.0,40.179.0,43.211.0,60.191.0,43.207.0,43.206.0"}
P.entries["quest:97926"] = {n="Making Do",s="Making Do är ett Alliance-uppdrag som förbinder hamnen Auberdine i Darkshore med det avlägsna kungariket Stormwind. En äventyrare får i uppdrag att överlämna ett officiellt svar från Alexston till Elder Thundris Windweaver och kommer med dystra nyheter: Stormwinds tömda skattkistor gör att kungariket inte kan hjälpa den hårt prövade Night Elf-bosättningen.",h="Making Do är ett Alliance-uppdrag som förbinder hamnen Auberdine i Darkshore med det avlägsna kungariket...",kw={"alexston","alexston's reply","auberdine","skattkistor","darkshore","making do","stormwind","thundris windweaver"},ang={["faction:Alliance"]="Uppdraget belyser hur bräcklig sammanhållningen inom Alliance är och visar hur geografiskt avstånd och inre påfrestningar tvingar avlägsna bosättningar som Auberdine att klara sig själva utan ekonomiskt stöd från Stormwind.",["race:Human"]="Alexstons brev speglar den bistra verkligheten i kungariket Stormwind, där tömda skattkistor och utbredda ekonomiska svårigheter på hemmaplan hindrar kronan från att finansiera hjälpinsatser utomlands.",["race:NightElf"]="För Night Elf-folket i Auberdine visar Stormwinds avslag allt tydligare att varken deras mänskliga allierade på andra sidan havet eller närbelägna Darnassus ställer upp för att lösa deras lokala problem."},sec={{t="En kurir över havet",b="I Making Do får en resenär i uppdrag att föra Alexston's Reply över havet till Elder Thundris Windweaver i Auberdine. Brevet innehåller inga löften om hjälp eller truppförstärkningar, utan ett beklagligt avslag. Stormwinds representant beklagar att kungarikets skattkammare börjar sina och att de få rikedomar som finns kvar redan går åt till dess egna kämpande territorier."},{t="Överlämnade åt sitt öde",b="När Thundris Windweaver tar emot svaret beklagar han utgången, men tackar resenären för den långa färden. Stormwind kan inte erbjuda hjälp och Darnassus har inte heller ställt upp. Thundris finner sig i att han och hans folk måste klara sig själva och konstaterar att Auberdines öde helt ligger i deras egna händer."}},faq={{q="Vad är uppdraget Making Do?",a="Making Do är ett uppdrag där en äventyrare levererar Baros Alexstons formella svar från Stormwind till Elder Thundris Windweaver i Auberdine. Det innehåller de nedslående nyheterna att Stormwind inte har råd att skicka hjälp till Darkshore.",al={"vad är making do","uppdraget making do","uppdrag auberdine stormwind"}},{q="Varför vägrar Stormwind att hjälpa Auberdine?",a="Stormwinds representant förklarar att kungarikets skattkistor är nästan tömda och att de resurser som finns kvar är hårt ansträngda i de egna länderna. Därför kan de inte bekosta hjälp till Auberdine.",al={"varför sa stormwind nej","stormwinds skattkistor sinar","varför hjälper stormwind inte auberdine"}},{q="Hur reagerar Thundris Windweaver på nyheten?",a="Thundris Windweaver tar emot brevet med sorg, men accepterar verkligheten. Eftersom varken Stormwind eller Darnassus kommer att ge stöd drar han slutsatsen att Auberdines folk måste ta sitt öde i egna händer.",al={"thundris reaktion på stormwind","hur reagerar thundris"}},{q="Vem skickade Alexston's Reply?",a="Baros Alexston är Stormwinds stadsarkitekt och den som framför kungarikets svar. Han uttrycker personlig medkänsla med Auberdines svåra situation, men förmedlar också den hårda sanningen om Stormwinds oförmåga att hjälpa till av ekonomiska skäl.",al={"vem är alexston","vem skickade alexstons svar"}},{q="Hjälper Darnassus Auberdine?",a="När Thundris Windweaver läser Alexstons brev konstaterar han att varken Stormwind eller deras närliggande huvudstad Darnassus har ställt upp för att hjälpa till. Bosättningen Auberdine lämnas därför isolerad och måste klara sig själv.",al={"hjälper darnassus auberdine","varför hjälpte darnassus inte"}},{q="Var överlämnas Alexston's Reply?",a="Uppdraget avslutas i hamnstaden Auberdine vid Darkshores kust, där Thundris Windweaver väntar på att budbäraren från Stormwind ska återvända.",al={"var avslutas uppdraget","inlämningsplats för making do"}}},fp="9,214,24.296.0,22.276.1,28.193.0,43.153.0,47.154.0,26.138.0,31.114.0,36.110.0"}
P.entries["quest:97932"] = {n="Camping 101: Fishing",s="Camping 101: Fishing lär fiskare att utrusta lägerplatser i vildmarken med handgjorda bekvämligheter. Genom att visa Uthan Stillwater i Bloodhoof Village vad de kan vid fiskespöet lär sig fiskare att tillverka ett Fish Bowl som muntrar upp resenärer som vilar i vildmarken.",h="Camping 101: Fishing lär fiskare att utrusta lägerplatser i vildmarken med handgjorda bekvämligheter.",kw={"bloodhoof village","lägereld","camping","camping 101: fishing","fish bowl","fiske","mulgore","uthan stillwater"},ang={["faction:Horde"]="Hordens fiskare som färdas genom Mulgore kan lära sig att tillverka lägerdetaljer av Uthan Stillwater i Bloodhoof Village.",["profession:Cooking"]="Varje ordentlig lägerplats behöver en enkel lägereld för att komma igång, så grundläggande matlagningskunskaper är ett naturligt komplement till varje fiskares läger i fält."},sec={{t="Fiske i vildmarken",b="Fiskare som färdas genom Mulgore kan förvandla sitt stillsamma tidsfördriv till praktiskt lägerhantverk med Camping 101: Fishing. Äventyrare som har visat att de behärskar spö och lina får i uppdrag att söka upp Uthan Stillwater i Bloodhoof Village. Skickliga fiskare lär sig att tillverka en hemtrevlig detalj för livet i vildmarken, inte bara att skaffa mat: ett eget Fish Bowl som gör lägerplatsen ljusare."},{t="Lägerlivets bekvämligheter",b="Ett Fish Bowl kan verka som en märklig följeslagare för härdade vandrare, men en bekväm viloplats lönar sig längs vägen. Den lilla inredningsdetaljen tillför en välkommen känsla av lätthet och ro i den hårda vildmarken och stärker modet hos alla som vilar vid lågorna. Som erfarna överlevare vet ger gott humör skarpare instinkter och större motståndskraft i strid."},{t="Lägereld och öppet land",b="Att slå läger kräver både respekt för lokala seder och goda grundkunskaper. Bosättningar som Bloodhoof Village tillåter inte resenärer att slå upp tillfälliga läger mitt i byn, så Fish Bowl kan bara provas ute i vildmarken. Dessutom går det inte att slå läger utan en ordentlig lägereld, så blivande campare behöver söka upp matlagningstränare för att lära sig grunderna i att göra upp eld."}},faq={{q="Vad gör ett Fish Bowl för en lägerplats?",a="Ett Fish Bowl är en dekorativ lägerdetalj som tillverkas av skickliga fiskare. Det är tänkt att skänka glädje och bekvämlighet åt äventyrare som vilar i vildmarken, så att de behåller modet och är alerta och stridsdugliga.",al={"fish bowl på lägerplats","vad gör fish bowl","fish bowl fördel"}},{q="Vem lär ut receptet på Fish Bowl?",a="Uthan Stillwater lär ut hantverket i Bloodhoof Village, som ligger på de böljande slätterna i Mulgore. Han undervisar fiskare som redan har visat att de är tillräckligt skickliga på att fiska.",al={"var lär man sig fish bowl","vem lär ut fish bowl","uthan stillwater plats"}},{q="Varför kan man inte slå läger i en bosättning?",a="Stadsbor och byvakter ser i allmänhet ogärna att resenärer slår upp fullskaliga läger och tänder eldar mitt på gatorna. Lägren måste slås upp ute i det öppna landskapet.",al={"slå läger i stad","varför kan jag inte campa i bloodhoof village","camping i städer"}},{q="Vad mer behövs för att slå läger?",a="En ordentlig lägerplats fungerar inte utan en lägereld i mitten. Resenärer som inte kan göra upp eld rekommenderas att söka upp en matlagningstränare och lära sig konsten att tända en eld innan de slår läger.",al={"krav på lägereld för camping","behövs eld för läger","grunderna i camping och eld"}},{q="Vilka krav måste uppfyllas innan man kan lära sig om Fish Bowl?",a="För att Uthan Stillwater ska dela med sig av hemligheterna bakom lägerdetaljerna måste fiskare först visa att de är skickliga på att fiska. Nybörjare behöver tillbringa lite tid vid vattnet och vässa sitt hantverk först.",al={"fiskeskicklighet för camping","när kan jag få fish bowl","krav för camping 101: fishing"}},{q="Varför skulle en äventyrare vilja ha ett Fish Bowl när hen campar?",a="Livet på vägarna i Azeroth är hårt och utmattande. Små inslag av hemliv och fridfulla fritidssysslor, som att se en fisk simma i en skål vid elden, ger en sällsynt glimt av glädje som stärker en äventyrares mod.",al={"varför ta med fish bowl på camping","fish bowl campinglore"}}},fp="20,285,19.401.0,16.384.0,25.420.0,42.228.0,33.196.0,45.194.0,39.211.0,59.214.0,55.218.0"}
P.entries["quest:97934"] = {n="Camping 101: Leatherworking",s="Camping 101: Leatherworking visar blivande läderarbetare till Bloodhoof Village i Mulgore, där de får lära sig konsten att tillverka bärbara lägertält. Genom att bemästra detta viktiga hantverk under Chaw Stronghides ledning kan resenärer bygga skyddande läger i vildmarken och hålla sig utvilade och uthålliga på sina färder. Uppdraget lyfter fram vikten av självförsörjning, överlevnad i vildmarken och förberedelser för friluftsliv ute vid gränstrakterna.",h="Camping 101: Leatherworking visar blivande läderarbetare till Bloodhoof Village i Mulgore, där de får lära...",kw={"bloodhoof village","lägereld","camping 101","chaw stronghide","läderarbete","mulgore","skydd","tält"},ang={["faction:Horde"]="Hordens resenärer som färdas genom Kalimdors vidsträckta, torra terräng är beroende av tålig campingutrustning för att överleva långt från befästa fästen.",["profession:Cooking"]="Matlagningslärare lär ut konsten att göra upp en ordentlig lägereld, som behövs för att förvandla ett enkelt lädertält till ett fullt fungerande och varmt läger.",["race:Tauren"]="Att tillverka bärbara läderskydd passar väl ihop med taurenstammarnas nomadiska traditioner och arv av överlevnad i vildmarken på Mulgore slätter."},sec={{t="Skydd på de öppna slätterna",b="För läderarbetare som färdas genom Kalimdors vidsträckta vildmarker är kunskapen att sy ihop ett stadigt tält lika viktig som att bereda ett skinn. Ett välgjort tält skyddar trötta resenärer från den brännande middagssolen och håller de ihållande prärieregnen borta. Det är mer än bara kanvas och läder: tältet erbjuder en lugn tillflyktsort där en äventyrare kan vila ordentligt och återfå sina krafter innan nästa prövning väntar på de öppna slätterna."},{t="Chaw Stronghides hantverk",b="I den fridfulla taurenbosättningen Bloodhoof Village, bland Mulgore gyllene gräs, för Chaw Stronghide vidare praktiska hemligheter om överlevnad i vildmarken. Chaw märker när en läderarbetare har utvecklat den skicklighet som krävs för att hantera grövre skinn och tåliga sömmar. När hantverkaren har visat sin förmåga lär han ut hur man bygger ett hållbart lägertält som står emot väder och vind under långa färder bort från civilisationen."},{t="Läger i vildmarken",b="Att slå upp ett tält kräver gott omdöme och respekt för bosättningar i närheten. Bybor ogillar när resenärer belamrar huvudstråk och genomfartsleder med privata lägerplatser, så läderarbetare måste bege sig ut i gränstrakternas vildmark innan de sätter upp sina skydd. Dessutom är inget läger i vildmarken komplett utan värmen och skyddet från en sprakande eld, så vandrare bör rådfråga skickliga kockar för att lära sig göra upp en ordentlig lägereld."}},faq={{q="Vad lär det här uppdraget läderarbetare?",a="Uppdraget leder läderarbetare till att lära sig bygga ett eget lägertält för sina resor. Ett stadigt tält skyddar mot hårt väder, håller resenärer svala i brännande hetta och torra under skyfall, samtidigt som det ger dem möjlighet att vila ordentligt ute i vildmarken.",al={"läderarbetesuppdrag om tält","vad lär camping 101 ut","lägerföremål för läderarbete"}},{q="Vem lär läderarbetare att tillverka lägertält?",a="Chaw Stronghide, som finns i Bloodhoof Village i Mulgore, lär läderarbetare att bygga lägerskydd. Han delar med sig av sina kunskaper om tältbygge när en läderarbetare har visat tillräcklig skicklighet i sitt hantverk och för vidare traditionella överlevnadskunskaper för långa expeditioner genom vildmarken.",al={"vem lär ut tältbygge","chaw stronghide tält","lärare i lädertält"}},{q="Var kan resenärer sätta upp sina lägertält?",a="Lägertält måste sättas upp ute i den öppna vildmarken, inte i befolkade bosättningar. Invånare och byäldste uppskattar inte när resenärer slår upp privata skydd mitt på torg eller livliga vägar, så vandrare måste bege sig ut på landsbygden för att prova sin nya utrustning.",al={"var kan jag slå upp tält","kan jag slå läger i staden","placering av tält"}},{q="Varför behövs en lägereld vid sidan av ett tält?",a="Ett ordentligt läger i vildmarken är inte komplett utan en sprakande lägereld som ger ljus, värme och mat. En läderarbetare kan tillverka skyddstältet, men att göra upp en eld kräver grundläggande kunskaper i överlevnadsmatlagning. Resenärer uppmuntras att besöka lokala kockar för att lära sig göra upp och sköta en lägereld innan de beger sig ut i vildmarken.",al={"varför behöver jag en lägereld","matlagning lägereld tält","tält och eld"}},{q="Var ligger Bloodhoof Village?",a="Bloodhoof Village är en framstående taurenbosättning i centrala Mulgore, söder om Thunder Bluff vid Stonebull Lakes stränder. Den är ett viktigt nav för lokala jägare, samlare och hantverkare och erbjuder utbildning, handelsvaror och vägledning åt resenärer som utforskar slätterna i närheten.",al={"var ligger bloodhoof village","bloodhoof village plats","hur hittar jag chaw stronghide"}},{q="Behöver du kunna laga mat för att hålla ett ordentligt läger?",a="Matlagning är inte ett absolut krav för att sy ihop ett lädertält, men alla campare rekommenderas starkt att lära sig matlagningens konst. Kockar lär resenärer att göra upp enkla lägereldar, som behövs för ett fullständigt utomhusläger, för att värma nattluften och laga mat under långa färder genom obebodda trakter.",al={"behövs matlagning för camping","behöver jag kunna laga mat","grunderna i lägereldsmatlagning"}},{q="Vilka fördelar ger ett lägertält en resenär?",a="Ett lägertält ger pålitligt skydd mot gränstrakternas obarmhärtiga väder och skyddar vandrare från stark hetta under soliga dagar och från kraftigt regn. Vila i ett välgjort tält gör att en äventyrare håller sig utvilad, uppmärksam och redo att möta faror när avlägsna trakter utforskas.",al={"fördelar med ett campingtält","varför bygga ett tält","vad gör tältet"}}},fp="27,418,28.445.0,28.472.0,17.472.0,42.292.0,51.329.0,44.310.0,42.342.0,35.321.0,56.330.0,53.324.0"}
P.entries["quest:97935"] = {n="Camping 101: Mining",s="Camping 101: Mining lär gruvarbetare att överleva i vildmarken genom sitt yrke. Genom att söka upp Brek Stonehoof i Thunder Bluff lär de sig att forma en särskild lodsten som stärker äventyrarnas stridsförmåga när de vilar vid lägerelden.",h="Camping 101: Mining lär gruvarbetare att överleva i vildmarken genom sitt yrke.",kw={"brek stonehoof","läger","lägereld","camping 101: mining","lodsten","gruvdrift","thunder bluff"},ang={["faction:Horde"]="Hordens expeditionsresenärer som vilar kring en gruvarbetares lägereld har nytta av den förberedda lodstenen, som stärker frontlinjens kombattanter inför kommande strider.",["profession:Mining"]="Gruvarbetare lär sig att använda sitt insamlingsyrke direkt för att överleva i fält genom att förbereda en lodsten åt expeditionsläger.",["race:Tauren"]="Undervisningen för gruvarbetarna till Brek Stonehoof på Thunder Bluffs högplatåer och bygger på taurenfolkets kunskap om sten och jordbearbetning."},sec={{t="Hederligt arbete i jorden",b="Gruvdrift kanske saknar den prakt och elegans som förknippas med högre magi, men är fortfarande ett grundläggande och hederligt arbete i hela Azeroth. Gruvarbetare hämtar användbara mineraler och tät sten ur djupa bergväggar och förser andra med viktiga material till vapen, rustningar och numera även praktisk fältutrustning. Genom lägerkonsten kan gruvarbetare forma den utvunna stenen till tåliga förstärkningar för sina rastplatser i vildmarken."},{t="Lodstenen från Thunder Bluff",b="För prospektörer som vill använda sitt yrke för att överleva erbjuder Brek Stonehoof i Thunder Bluff särskild undervisning. När en gruvarbetare visar att hen behärskar sin hacka delar Brek med sig av konsten att forma en lägerlodsten. Stenen placeras bredvid en öppen eld och ger kampvilja och en viktig fördel åt alla som förbereder sig på att svinga ett svärd i strid."}},faq={{q="Vad gör lodstenen för ett läger?",a="En tillverkad lodsten som placeras vid ett läger utstrålar subtila stridsegenskaper och ger extra stridsförmåga och kraft åt krigare och äventyrare som samlas runt lägerelden.",al={"lodstenens nytta vid läger","lodstenens bonus","vad gör lodstenen"}},{q="Vem är Brek Stonehoof?",a="Brek Stonehoof finns i taurenfolkets huvudstad Thunder Bluff. Han lär erfarna gruvarbetare att tillverka särskilda campingredskap av utvunnen sten och malm.",al={"brek stonehoofs plats","var finns brek stonehoof","vem lär ut lägerföremål för gruvdrift"}},{q="När kan en gruvarbetare lära sig att tillverka en lodsten?",a="Gruvarbetare måste först visa grundläggande skicklighet i sitt yrke innan Brek Stonehoof lär dem teknikerna för att tillverka en lodsten.",al={"när kan jag lära mig lodsten","krav på gruvfärdighet för lodsten"}},{q="Vem har mest nytta av en gruvarbetares lodsten?",a="Alla som vill svinga ett vapen har nytta av en lodsten, eftersom dess påverkan ger fysiska kombattanter extra stridsstyrka när de vilar bredvid den.",al={"vem har nytta av lodstenen","är lodstenen till för närstrid"}},{q="Hur bidrar gruvdrift till att slå läger?",a="Gruvdrift förser inte bara smältare och smeder med råmetall, utan låter också resenärer i vildmarken tillverka tåliga stenredskap som lodstenar, vilka stärker läger för överlevnad i det fria.",al={"varför gruvdrift för lägerliv","hur hjälper gruvdrift lägret"}},{q="Vad är syftet med Camping 101: Mining?",a="Camping 101: Mining är en instruktion som leder blivande gruvarbetare till Thunder Bluff, där de kan lära sig att tillverka fältutrustning för överlevnad i vildmarken.",al={"översikt över camping 101: mining","vad är camping 101: mining"}}},fp="19,267,25.382.0,30.360.0,42.171.0,22.173.0,48.162.0,43.163.0,49.183.0,43.169.0"}
P.entries["quest:97936"] = {n="Camping 101: Skinning",s="Camping 101: Skinning vägleder skickliga flåare till Bloodhoof Village för att utveckla sina praktiska färdigheter i fält. Under Yonn Deepcuts ledning lär sig flåare att göra bekväma Camp Chairs av djurhudar för att överleva i vildmarken. Utbildningen betonar vikten av vila och förberedelser när man färdas långt bortom civilisationens trygghet.",h="Camping 101: Skinning vägleder skickliga flåare till Bloodhoof Village för att utveckla sina praktiska...",kw={"bloodhoof village","camp chair","lägereld","camping 101","camping 101: skinning","mulgore","flåning","yonn deepcut"},ang={["faction:Horde"]="Hordens flåare i Mulgore kan besöka Bloodhoof Village för att lära sig tillverka praktisk lägerutrustning av insamlade hudar.",["profession:Cooking"]="Ett ordentligt läger behöver en varm lägereld som sällskap till sittplatserna. Matlagningstränare runt om i världen kan lära äventyrare att göra upp eld.",["race:Tauren"]="I hjärtat av Mulgore lär Yonn Deepcut flåare att tillverka bekväma stolar av djurhudar för vila i vildmarken."},sec={{t="Vildmarkens hudar",b="Att ta till vara på hudar och skinn från fallna bestar är en av Azeroths mest praktiska överlevnadsfärdigheter. Förutom att garva läder till rustningar och utrustning kan en påhittig flåare förvandla grova djurhudar till bekvämligheter för vildmarken. För resenärer som tillbringar långa veckor med att färdas genom vilda marker kan kunskapen att förvandla hudar till viloutrustning vara skillnaden mellan utmattning och att hålla sig stridsberedd."},{t="Lektioner i Bloodhoof Village",b="I Mulgore hänvisas flåare till Bloodhoof Village för att tala med Yonn Deepcut. När en flåare visar grundläggande färdighet i att ta till vara på djurhudar lär Yonn ut hantverket att sy ihop en Camp Chair. Invånarna i städer och byar välkomnar inte resenärer som slår upp tält mitt på gatorna, så stolarna är särskilt utformade för vildmarken och kombineras med en sprakande lägereld, något lokala kockar lär ut."}},faq={{q="Vad är Camping 101: Skinning?",a="Camping 101: Skinning är en introduktionsuppgift som vägleder skickliga flåare till en specialiserad instruktör i Mulgore. När de har visat sin skicklighet i att ta till vara på hudar får flåarna lära sig att tillverka en Camp Chair till sina läger i vildmarken.",al={"vad är camping 101: skinning","flåningsuppdraget camping 101","vad gör det här uppdraget"}},{q="Vem lär ut receptet på Camp Chair?",a="Yonn Deepcut, en flåare i Bloodhoof Village i Mulgore, lär ut tekniken för att tillverka en Camp Chair när en äventyrare har visat sin skicklighet i att ta till vara på djurhudar.",al={"vem lär ut camp chair","vem ska jag prata med om camping 101: skinning","var finns yonn deepcut"}},{q="Vad används en Camp Chair till?",a="En Camp Chair ger en bekväm plats att vila på när du slår läger ute i vildmarken. Om äventyrare tar sig tid att sitta ner och koppla av kan de återhämta sina krafter och hålla sig i toppform inför kommande strider.",al={"vad används en camp chair till","användning av camp chair","varför tillverka en camp chair"}},{q="Var kan du slå läger?",a="Stadsbor ser ogärna att resenärer slår läger mitt i bosättningar. Äventyrare måste ta sig ut i vildmarken för att slå läger och prova sin tillverkade utrustning.",al={"var kan jag slå läger","kan jag slå läger i en stad","camp chair i staden"}},{q="Vad mer behövs för att slå läger?",a="Ett läger är inte komplett utan en sprakande lägereld. Äventyrare måste göra upp en eld innan de slår läger. Det är en grundläggande färdighet som ofta lärs ut av matlagningstränare och kockar.",al={"vad mer behöver jag för ett läger","behövs en lägereld","behöver jag en eld för att slå läger"}},{q="Var ligger Bloodhoof Village?",a="Bloodhoof Village är en stor taurenbosättning på Mulgore slättland, som sveps av vinden. Där finns olika hantverkare, bland annat flåningstränare.",al={"var ligger bloodhoof village","bloodhoof village läge"}}},fp="21,361,17.406.0,28.429.0,30.248.0,34.189.0,30.204.0,28.180.0,39.180.0,35.149.0"}
P.entries["quest:97938"] = {n="Camping 101: Alchemy",s="Camping 101: Alchemy är ett introduktionsuppdrag som förenar grundläggande dryckestillverkning med överlevnad i vildmarken. Alkemister hänvisas till Cyndra Kindwhisper i Dolanaar för att lära sig bygga en uppfriskande Mana Well vid sina lägerplatser, så att resande magiker och helare får välbehövlig magisk påfyllning.",h="Camping 101: Alchemy är ett introduktionsuppdrag som förenar grundläggande dryckestillverkning med överlevnad...",kw={"alkemi","läger","camping 101","camping 101: alchemy","cyndra kindwhisper","dolanaar","mana well","teldrassil"},ang={["faction:Alliance"]="Alliansens alkemister som färdas över Teldrassil leds direkt till Dolanaar för att stärka sin överlevnadsförmåga i vildmarken med magiska lägeranordningar.",["race:NightElf"]="Nattalvernas örtalister och alkemister som verkar från Dolanaar förenar naturbotanik med lägerhantverk för att hjälpa magiker i vildmarken."},sec={{t="Fältkunskap för alkemister",b="Camping 101: Alchemy lär alkemister att anpassa sina färdigheter i dryckestillverkning till livet på vägarna. I stället för att bara brygga elixir i laboratorieglas lär sig äventyrarna skapa installationer i fält som hjälper resesällskap att klara långa färder genom vildmarken."},{t="Mana Well i Dolanaar",b="Uppdraget instruerar äventyrarna att söka upp Cyndra Kindwhisper i Dolanaar när de visat grundläggande yrkesskicklighet. Hon lär ut tekniken för att anlägga en Mana Well vid lägret, en uppfriskande källa särskilt anpassad för att hjälpa helare och magiker som är beroende av mana när de färdas långt från värdshus och bosättningar."}},faq={{q="Vad är Camping 101: Alchemy?",a="Camping 101: Alchemy är en utbildningsuppgift som leder nybörjaralkemister till Dolanaar. Den lär resenärer att använda sina färdigheter i dryckestillverkning för att skapa praktiska lägeranordningar i vildmarken.",al={"vad är camping 101 alchemy","uppdraget camping 101 alchemy","alkemilägeruppdrag"}},{q="Vem lär ut den här campingfärdigheten?",a="Cyndra Kindwhisper är en alkemilärare i nattalvernas bosättning Dolanaar på Teldrassil. Hon undervisar utövare som visat tillräcklig skicklighet i bryggning och tillverkning av specialiserade campingföremål.",al={"vem är cyndra kindwhisper","cyndra kindwhispers plats","var finns cyndra kindwhisper"}},{q="Vad är en Mana Well?",a="En Mana Well är en specialiserad vildmarksinstallation som alkemister tillverkar för sina lägerplatser. Den ger en uppfriskande källa till mystisk återhämtning som lockar magiker och helare som behöver fylla på sina magiska reserver längs vägen.",al={"vad gör en mana well","mana well lägerföremål","mana well historia"}},{q="Vart tar det här uppdraget dig?",a="Dolanaar är en nattalverby mitt på Teldrassil och fungerar som ett viktigt nav för unga äventyrare och yrkeslärare efter att de lämnat Shadowglen.",al={"var finns dolanaar","hur tar man sig till dolanaar","dolanaars plats"}},{q="Vem har nytta av en alkemists lägerinstallation?",a="Helare och resande magiker har störst nytta av Mana Wells, eftersom de frammanade eller bryggda källorna ger välbehövlig förfriskning och påfyllning under krävande färder långt från städer.",al={"vem har nytta av mana wells","vem använder mana wells","mana well magiker"}},{q="Vad krävs innan man kan lära sig tillverka en Mana Well?",a="Alkemister måste först visa skicklighet i grundläggande bryggning och dryckestillverkning innan Cyndra Kindwhisper undervisar dem i att sätta ihop campinganordningar som Mana Well.",al={"när kan jag lära mig mana well","krav för camping 101","krävd yrkesskicklighet"}}},fp="20,304,26.291.0,25.319.0,29.212.0,31.224.0,20.245.0,31.156.0,51.177.0,54.189.0"}
P.entries["quest:97942"] = {n="Camping 101: First Aid",s="Camping 101: First Aid lär äventyrare att överleva i vildmarken genom att visa hur de tillverkar ett fältkit för första hjälpen till lägerplatsen. Byancie i Dolanaar lär ut hur man klarar sig själv och gör en praktisk bedömning av skador långt från stadens kliniker.",h="Camping 101: First Aid lär äventyrare att överleva i vildmarken genom att visa hur de tillverkar ett fältkit...",kw={"byancie","lägereld","camping","dolanaar","fältmedicinare","första hjälpen","first aid kit","jägare"},ang={["class:Hunter"]="För jägare som tillbringar långa perioder med att spåra bestar långt från civilisationen gör överlevnadskunskaper och första hjälpen att de kan ta hand om skador utan att förlita sig på stadens läkare.",["profession:Cooking"]="Lägerlivet kräver både mat och värme, så grundläggande matlagningskunskaper är viktiga för att lära sig göra upp den nödvändiga lägerelden."},sec={{t="Fältmedicin i vildmarken",b="Att färdas djupt in i vildmarken innebär ständiga faror, från bett av vilda djur till förrädisk terräng. För skogsvaktare och resenärer i fält kan det inte alltid vänta med att få tag på sjukvårdsutrustning tills de återvänder till staden. Om du lär dig sätta ihop ett särskilt First Aid Kit kan en enkel rast vid vägen bli en fungerande fältstation, så att små skrubbsår inte blir dödliga under bar himmel."},{t="Lärdomar i Dolanaar",b="Byancie håller till bland Dolanaars skuggiga lövsalar och lär resenärer som kan bedöma skador att packa sjukvårdsutrustning för ett hårt liv på stigarna. Sådan utrustning kräver respekt för lokala bosättningar. Stadsbor tolererar inte uppslagna tält och utspridd utrustning i stadskärnan, så campare måste bege sig ut i skogen innan de slår läger."},{t="Lägrets härd",b="Varje fungerande läger börjar med en öppen eld. Innan äventyrare lägger fram sjukvårdskit eller bäddar måste de göra upp en lägereld för värme och skydd. Eftersom det är grundläggande för överlevnad i fält att bygga och sköta en eld rekommenderar tränare att du rådfrågar en kock för att lära dig konsten att tända en eld innan du försöker hålla ett läger i vildmarken vid liv."}},faq={{q="Vem är Byancie?",a="Byancie är en lärare i bosättningen Dolanaar på Teldrassil. Hon lär äventyrare som visat att de behärskar sjukvård att sätta ihop särskilda First Aid Kits för camping i vildmarken.",al={"vem är byancie","byancies plats","var finns byancie"}},{q="Vad är ett First Aid Kit för camping?",a="Ett First Aid Kit är ett särskilt campingredskap som tillverkas av äventyrare med medicinsk utbildning. När det placeras på en etablerad lägerplats ger det en särskild station där du kan behandla sår och ge viktig läkning ute i fält.",al={"vad är first aid kit för läger","hur fungerar first aid kit","first aid kit för camping"}},{q="Var kan du slå läger?",a="Invånare och vakter ogillar när resenärer slår upp tillfälliga läger på torg eller i bosättningars centrum. Lägren måste slås upp i den öppna vildmarken, utanför stadens gränser.",al={"kan jag campa i staden","varför campa utanför staden","lägerregler"}},{q="Varför behövs en lägereld?",a="En lägereld är grunden för varje läger i vildmarken och ger värme, ljus och trygghet. Äventyrare lär sig oftast att tända en enkel lägereld av matlagningstränare och kockar.",al={"varför behöver jag en lägereld","matlagning och lägereld","krav på lägereld"}},{q="Varför är första hjälpen praktiskt för jägare?",a="Jägare arbetar ofta ensamma i avlägsna delar av vildmarken, långt från läkare och tempelriddare. Kunskap om att bedöma skador i fält och tillverka bandage gör att de kan klara sig själva när de spårar villebråd eller överlever bakhåll.",al={"varför behöver jägare första hjälpen","läkning för jägare"}},{q="Hur lär du dig tillverka ett First Aid Kit för camping?",a="Äventyrare måste först visa grundläggande färdigheter inom första hjälpen. Därefter kan Byancie i Dolanaar lära dem de särskilda tekniker som behövs för att sätta ihop ett First Aid Kit för camping.",al={"hur får jag ett first aid kit","lära sig tillverka first aid kit"}}},fp="22,250,27.356.0,19.372.0,22.350.0,15.220.0,32.222.0,28.201.0,38.191.0,50.219.0,50.196.0"}
P.entries["quest:97943"] = {n="Camping 101: Fishing",s="Camping 101: Fishing lär fiskare hur de skapar trivsel i vildmarken genom att tillverka en dekorativ Fish Bowl till lägret. Hos Astaia i Darnassus lär sig skickliga fiskare att små glädjeämnen kan stärka äventyrarens mod och stridsförmåga ute i vildmarken.",h="Camping 101: Fishing lär fiskare hur de skapar trivsel i vildmarken genom att tillverka en dekorativ Fish...",kw={"astaia","lägereld","camping","camping 101: fishing","lägerplats","darnassus","fish bowl","fiske"},ang={["faction:Alliance"]="Astaia bor i Darnassus, vilket gör Night Elf-huvudstaden till ett viktigt resmål för alliansens fiskare som vill utveckla sitt lägerhantverk.",["profession:Cooking"]="Det krävs en ordentlig lägereld för att slå läger, så grundläggande matlagningskunskaper är ett viktigt komplement till fiskarens skydd utomhus."},sec={{t="Trivsel vid lägerplatsen",b="Fiskare som färdas genom Kalimdor upptäcker ofta att de lugna stunderna vid vattnet kan fylla ett större syfte. I Darnassus visar hantverkaren Astaia erfarna fiskare hur de kan förvandla sina fångster och färdigheter till lägerinredning, särskilt genom att skapa en Fish Bowl att ställa i lägret. Denna prydnad skänker trötta resenärer en välkommen känsla av trivsel och glädje."},{t="Nödvändigheter i vildmarken",b="Det krävs mer än fiskeredskap för att skapa ett ordentligt skydd i vildmarken. Läger kan inte slås upp i livliga stadskärnor eller stadsdelar, så äventyrare måste ge sig ut under öppen himmel. Dessutom behöver varje läger en varm lägereld som grund, så äventyrare bör besöka en lokal matlagningstränare och lära sig grunderna i att göra upp eld innan de slår sig till ro för natten."}},faq={{q="Vem lär dig att tillverka lägerföremål för fiskare?",a="Astaia finns i Darnassus. När en fiskare har visat tillräcklig skicklighet i fiske lär Astaia ut hur man tillverkar en dekorativ Fish Bowl till lägerplatsen.",al={"vem lär ut lägerfiske","var finns astaia","fish bowl-tränare"}},{q="Vad används en Fish Bowl till i lägret?",a="Fish Bowl är en del av lägerinredningen som ska ge vila och glädje åt äventyrare. En glad och utvilad lägerbesökare strider med förnyad kraft, vilket direkt gynnar expeditioner utomhus.",al={"vad gör fish bowl","fish bowl i lägret användning","fish bowl som lägerinredning"}},{q="Kan du slå läger i Darnassus eller andra städer?",a="Läger kan inte slås upp mitt i bosättningar eller stadskärnor. För att slå läger och placera ut föremål som en Fish Bowl måste resenärer bege sig ut i vildmarken.",al={"kan man slå läger i darnassus","var kan man slå läger","läger i städer"}},{q="Vad krävs innan man slår läger?",a="Ingen lägerplats är komplett utan en enkel lägereld. Resenärer bör söka upp en matlagningstränare och lära sig att göra upp eld innan de slår läger i vildmarken.",al={"vad behövs för ett läger","hur slår man läger","lägereld krävs"}},{q="Behöver du kunna fiska för att lära dig tillverka en Fish Bowl?",a="För att lära sig hantverket av Astaia måste en äventyrare först visa skicklighet i yrket fiske.",al={"fiske skicklighet för camping","när kan jag lära mig fish bowl"}},{q="Varför slår äventyrare läger i vildmarken?",a="Ett läger ger resenärer utomhus en plats att vila på och bekvämligheter som stärker modet, till exempel en tillverkad Fish Bowl. På så vis håller sig äventyrarna utvilade och redo under färder i vildmarken.",al={"varför slå läger i wow forever","fördelar med camping"}}},fp="20,296,23.391.0,22.390.0,55.172.0,44.193.0,55.165.0,42.174.0,60.107.0,44.191.0"}
P.entries["quest:97944"] = {n="Camping 101: Herbalism",s="Camping 101: Herbalism visar samlare hur deras yrke kan användas för praktisk överlevnad. Genom att besöka Malorne Bladeleaf i Dolanaar lär sig skickliga örtmästare att tillverka lugnande Incense Candle som stärker helare och besvärjare kring lägerelden.",h="Camping 101: Herbalism visar samlare hur deras yrke kan användas för praktisk överlevnad.",kw={"camping","camping 101: herbalism","dolanaar","örtmästaryrket","incense candle","malorne bladeleaf","teldrassil"},ang={["faction:Alliance"]="Alliansens örtmästare i trakterna kring Teldrassil hänvisas till Dolanaar för att lära sig särskilda fältfärdigheter av lokala Night Elf-utövare.",["profession:Herbalism"]="Örtmästare upptäcker att växtskörd tjänar praktisk överlevnad i vildmarken utöver alkemi, eftersom råa växtingredienser kan användas till lägerutrustning som Incense Candle.",["race:NightElf"]="Night Elf-folket har länge förstått naturens örters omgivande och återställande egenskaper och för traditionerna vidare i bosättningar som Dolanaar."},sec={{t="Mer än att plocka blommor",b="Örtkunskap handlar om mycket mer än att ströva genom ängar och plocka blommor. Samlare säljer ofta sina fynd eller förser alkemister med råvaror, men erfarna vildmarksresenärer vet att vilda växter kan förvandlas direkt till värdefull lägerutrustning. När man lär sig bereda skördade växter för överlevnad kan varje skörd bidra direkt till längre färder i fält."},{t="Dolanaars rogivande låga",b="I bosättningen Dolanaar lär en instruktör vid namn Malorne Bladeleaf skickliga örtmästare att tillverka ett Incense Candle. Dessa väldoftande ljus skapar en samlad och upplyftande fristad kring lägerelden, och ger en återhämtande närvaro som helare och besvärjare uppskattar när de återställer sin magiska energi mellan faror."}},faq={{q="Vad är syftet med det här uppdraget?",a="Camping 101: Herbalism är ett introducerande yrkesuppdrag som leder skickliga samlare till att studera särskilt hantverk för vildmarken. Det lär örtmästare att tillverka lägerutrustning av växterna de skördar i fält.",al={"vad är camping 101 herbalism","uppdraget camping herbalism"}},{q="Vad gör ett Incense Candle för ett läger?",a="Ett Incense Candle skapar en uppiggande stämning på lägerplatsen, höjer humöret och ger en rogivande förstärkning som besvärjare och helare förlitar sig på för att behålla sitt magiska fokus.",al={"vad gör incense candle","fördelar med incense candle"}},{q="Vem är Malorne Bladeleaf?",a="Malorne Bladeleaf är en instruktör i Dolanaar som kan tillverka örtmästarnas lägerutrustning och särskilt lär skickliga samlare att forma Incense Candle.",al={"vem lär ut incense candle","vem är malorne bladeleaf","bladeleaf dolanaar"}},{q="Vart tar det här uppdraget dig?",a="Dolanaar är en Night Elf-bosättning på ön Teldrassil och fungerar som ett regionalt nav för resenärer, tränare och skogshantverkare.",al={"var ligger dolanaar","dolanaars läge"}},{q="Varför är Incense Candle användbara för magiker?",a="Helare och besvärjare har störst nytta av den lugna, fokuserade miljö som ett Incense Candle skapar. Det hjälper dem att återfå sitt mod och sin magiska styrka under expeditioner i vildmarken.",al={"vem har nytta av incense candle","är incense candle för besvärjare"}},{q="Vad krävs innan Malorne Bladeleaf lär dig?",a="Samlare måste visa tillräcklig praktisk skicklighet och färdighet i örtmästaryrket innan Malorne Bladeleaf delar med sig av konsten att tillverka lägerutrustning.",al={"när kan jag lära mig incense candle","krav på örtmästarnivå för camping"}}},fp="22,259,25.388.0,30.344.0,34.233.0,42.187.0,25.197.0,31.146.0,46.198.0,57.167.0"}
P.entries["quest:97946"] = {n="Camping 101: Leatherworking",s="Camping 101: Leatherworking lär skickliga hantverkare på Teldrassil att skapa skydd för överlevnad i vildmarken.",h="Camping 101: Leatherworking lär skickliga hantverkare på Teldrassil att skapa skydd för överlevnad i...",kw={"lägereld","camping","darnassus","dolanaar","läderarbete","nadyia maneweaver","tält","vildmark"},ang={["class:Rogue"]="Rogues som färdas genom vildmarken behöver god vila och skydd för att hålla sig skärpta, så ett eget lädertält är ett ovärderligt överlevnadsredskap.",["profession:Cooking"]="För att slå upp ett ordentligt läger behövs en varm lägereld, en viktig färdighet som matlagningstränare lär ut runtom i landet."},sec={{t="Skydd i vildmarken",b="För äventyrare som färdas genom Kalimdors vilda trakter innebär vila under bar himmel stora utmaningar, från plötsliga skyfall till brännande hetta. Skickliga läderarbetare får lära sig att tillverka tåliga skydd av hudar och skinn, så att resande kan finna en trygg tillflykt vart färden än går. Med ett eget campingtält får vandrare den vila de behöver för att hålla reaktionsförmågan skarp och sinnet klart långt från värdshusens trygghet."},{t="Vägen från Dolanaar",b="Längs skogsvägen mellan bosättningen Dolanaar och Darnassus grenar ger Nadyia Maneweaver vägledning åt skickliga läderarbetare. Hon lär ut konsten att sy stadiga tält som passar livet längs vägen. Men ett tält räcker inte för att skapa en fungerande lägerplats. Resande måste också kunna tända en lägereld, en grundläggande överlevnadskunskap som lärs ut av kockar, och komma ihåg att slå upp sina skydd i den öppna vildmarken i stället för att belamra stadsgatorna."}},faq={{q="Vem lär ut campingfärdigheten?",a="Uppdraget leder den blivande läderarbetaren till Nadyia Maneweaver, som finns längs vägen från Dolanaar mot Darnassus på Teldrassil.",al={"vem ger camping 101: leatherworking","vem lär ut camping 101","nadyia maneweaver"}},{q="Vad lär sig läderarbetare av uppdraget?",a="Det lär läderarbetare att tillverka ett eget campingtält som håller resande svala under heta dagar och torra när det regnar i vildmarken.",al={"vad lär camping 101 ut","tältmönster","vad lär jag mig av camping 101"}},{q="Var kan du slå upp ett campingtält?",a="Tält kan inte slås upp i bosättningar eller stadskärnor, eftersom stadsbor inte uppskattar läger mitt i staden. Resande måste ta sig ut i den öppna vildmarken för att slå läger.",al={"var kan jag slå upp mitt tält","kan jag slå upp tält i stan","camping i städer"}},{q="Vad mer behövs för att slå läger?",a="Ett riktigt läger kräver en tänd lägereld bredvid tältet innan det kan upprättas. Grundläggande kunskaper i att göra upp lägereld lär man sig vanligtvis av matlagningstränare.",al={"vad behövs för ett läger","krav på lägereld","behöver jag en lägereld till tältet"}},{q="Varför är ett tält användbart för resande?",a="Ett pålitligt tält ger skydd mot väder och vind och ser till att äventyrare får tillräckligt med vila för att hålla sig alerta och skärpta när de färdas långt från värdshus.",al={"varför bygga ett tält","tältets vilofördel","varför slå läger"}},{q="Var finns Nadyia Maneweaver?",a="Nadyia Maneweaver finns längs huvudvägen från byn Dolanaar mot Night Elf-huvudstaden Darnassus.",al={"var finns nadyia maneweaver","nadyias plats","tränare längs vägen till darnassus"}}},fp="27,320,25.499.0,22.491.0,31.156.0,45.173.0,32.201.0,39.160.0,42.153.0,35.140.0"}
P.entries["quest:97948"] = {n="Camping 101: Mining",s="Camping 101: Mining är ett introduktionsuppdrag som hänvisar gruvarbetare till Kurdram Stonehammer i Auberdine. Genom att visa sin skicklighet i yrket kan gruvarbetare lära sig att tillverka en lägerlodsten som stärker stridsförmågan hos allierade som vilar kring en lägereld.",h="Camping 101: Mining är ett introduktionsuppdrag som hänvisar gruvarbetare till Kurdram Stonehammer i...",kw={"auberdine","lägerutrustning","lägereld","camping 101: mining","darkshore","kurdram stonehammer","lodsten","gruvdrift"},ang={["faction:Alliance"]="Kurdram Stonehammer undervisar från Auberdine vid Darkshores kust, vilket gör denna lägerutrustning lättillgänglig för alliansresenärer på väg genom norra Kalimdor.",["profession:Mining"]="Gruvarbetare kan använda sina mineralkunskaper för att hjälpa resenärer längs vägen och förvandla grov sten till en funktionell lägerlodsten som stärker frontkämpar."},sec={{t="Jordens och stenens praktiska konst",b="Gruvdrift är ett slitigt och hederligt arbete, men nyttan sträcker sig långt bortom att smälta tackor och hamra fram rustningar. Erfarna prospektörer kan forma rå jord och magnetisk malm till särskild campingutrustning, så att resenärer kan skapa väl befästa härdar i vildmarken. Camping 101: Mining introducerar gruvarbetare till denna praktiska användning av deras hantverk."},{t="En mentor i Auberdine",b="Uppdraget leder lovande gruvarbetare till Kurdram Stonehammer i Auberdine, Darkshores livliga kusthamn. När en gruvarbetare har bevisat sitt engagemang och sin skicklighet lär Kurdram ut hur man bygger en lägerlodsten. Stenen placeras intill en eld och utstrålar en stärkande närvaro som ökar stridsförmågan hos stridsvana följeslagare i närheten."}},faq={{q="Vad är Camping 101: Mining?",a="Camping 101: Mining leder gruvarbetare till Kurdram Stonehammer i hamnstaden Auberdine. När du har visat din skicklighet i gruvdrift lär han dig att tillverka en särskild lodsten som förbättrar lägerplatser.",al={"vad är det här för uppdrag","målet med camping 101 mining","vad gör jag i camping mining"}},{q="Vem är Kurdram Stonehammer?",a="Kurdram Stonehammer är en skicklig hantverkare i Auberdine vid Darkshores kust. Han lär kvalificerade gruvarbetare att skapa praktiska campingföremål, särskilt lodstenar.",al={"vem är kurdram stonehammer","gruvtränare i auberdine","kurdram stonehammers plats"}},{q="Vad är en lägerlodsten?",a="En lodsten är ett föremål som gruvarbetare tillverkar för ett läger. När den reses intill en lägereld ger den en uppiggande närvaro som skänker fysiska kämpar extra kraft och stridsförmåga.",al={"vad gör en lodsten","lägerlodstenens effekt","campingens kraftbonus"}},{q="Var utspelar sig uppdraget?",a="Auberdine är en kusthamn i Darkshore och fungerar som en viktig hamn och knutpunkt för Alliansen i norra Kalimdor. Kurdram Stonehammer bor där och lär blivande gruvarbetare att skapa lägerutrustning.",al={"var ligger auberdine","auberdines plats","hur tar jag mig till auberdine"}},{q="Vem har nytta av en lägerlodsten?",a="Lodstenen uppskattas särskilt av stridsvana kämpar som svingar svärd och vapen på nära håll. Dess resonanta kraft ger resenärer inriktade på strid extra styrka medan de vilar kring elden.",al={"vem har nytta av lodstenen","är lodstenen bra för krigare","vem får lägerlodstenens bonus"}},{q="När kan du lära dig att tillverka lodstenen?",a="Du måste visa tillräcklig skicklighet i gruvdrift innan Kurdram Stonehammer delar med sig av hemligheterna bakom att tillverka en lodsten till ditt läger.",al={"när kan jag lära mig lodstenen","gruvnivå för lägerlodsten","krav på skicklighet"}}},fp="19,259,36.352.0,21.368.0,28.217.0,27.188.0,25.183.0,33.202.0,35.211.0,42.145.0"}
P.entries["quest:97949"] = {n="Camping 101: Skinning",s="Camping 101: Skinning visar vildmarksresenärer hur de tillverkar sin egen bärbara Camp Chair. Den betonar grunderna i friluftsöverlevnad och påminner äventyrare om att en ordentlig lägerplats kräver att man lämnar staden och tänder en lägereld.",h="Camping 101: Skinning visar vildmarksresenärer hur de tillverkar sin egen bärbara Camp Chair.",kw={"camp chair","lägereld","camping 101","camping 101: skinning","matlagning","flåning","vildmark"},ang={["profession:Cooking"]="Campare rekommenderas att lära sig grundläggande matlagning av en matlagningsinstruktör, eftersom kunskap om hur man gör upp en enkel lägereld är nödvändig för att ordna en ordentlig lägerplats i vildmarken."},sec={{t="Bekvämligheter längs vägen",b="Camping 101: Skinning introducerar friluftsmänniskor och flåare till konsten att överleva i vildmarken. Genom att använda insamlade hudar och material på praktiska sätt lär sig resenärer att tillverka en bärbar Camp Chair för sina färder. Äventyrare förväntas ta med sig sitt hantverk ut i Azeroths öppna vildmarker i stället för att belamra livliga stadskärnor där invånarna ogillar uppslagna läger."},{t="Den nödvändiga lägerelden",b="Ingen lägerplats i vildmarken fungerar utan en värmande lägereld. Först måste man göra upp en eld när man slår läger, så att den ger värme och skydd mot väder och vind. Nybörjare som ännu inte har lärt sig grundläggande matlagning uppmuntras att besöka en matlagningsinstruktör, som kan lära dem grunderna i att göra upp eld ute i fält."}},faq={{q="Vad lär du dig av Camping 101: Skinning?",a="När du slutför uppgiften lär du dig att tillverka din egen Camp Chair, en viktig bekvämlighet när du vilar ute i vildmarken.",al={"vad får jag","vad ger camping 101","tillverka camp chair"}},{q="Kan du slå läger i en stad?",a="Stadsbor brukar ogilla när resenärer slår läger på torg eller gator. Du behöver ta dig ut i vildmarken för att slå läger på rätt sätt.",al={"kan jag slå läger i en stad","slå upp tält i stormwind","camping inne i städer"}},{q="Behöver du en lägereld för att slå läger?",a="En ordentlig lägerplats kräver en tänd lägereld innan den kan upprättas. Du kan lära dig grundläggande metoder för att göra upp eld av de flesta matlagningsinstruktörer i Azeroth.",al={"behövs eld för läger","hur gör man en lägereld","eld för camp chair"}},{q="Var kan du lära dig att göra upp en lägereld?",a="De flesta matlagningsinstruktörer kan lära dig grunderna i matlagning, inklusive hur du gör upp en enkel lägereld med flinta och ved.",al={"vem lär ut att göra upp eld","matlagningsinstruktör för eld","var lär man sig göra upp eld"}},{q="Varför måste du ge dig ut i vildmarken för att slå läger?",a="Vildmarken erbjuder det öppna utrymme som behövs för att slå läger utan att störa stadsborna eller blockera vägar och bebyggelse.",al={"varför behövs vildmarken","var kan jag använda camp chair","var kan man slå läger"}},{q="Hur hänger flåning ihop med att tillverka en lägerstol?",a="Flåare arbetar med läder och hudar från vilddjur, material som passar att spänna och sy till bärbara sittplatser för utomhusbruk, som en Camp Chair.",al={"samband mellan flåning och camping","varför flåning för stol","flåning camp chair"}}},fp="21,255,21.388.0,22.368.0,45.124.0,30.160.0,36.164.0,43.163.0,53.137.0,48.158.0"}
P.entries["quest:97955"] = {n="Camping 101: First Aid",s="Camping 101: First Aid leder äventyrare med medicinsk utbildning till Nurse Neela i Brill. Genom att lära sig sätta ihop ett First Aid Kit för lägerplatserna kan resenärer ge livräddande vård och återhämtning medan de överlever långt ute i vildmarken.",h="Camping 101: First Aid leder äventyrare med medicinsk utbildning till Nurse Neela i Brill.",kw={"brill","lägereld","camping","camping 101","first aid","first aid kit","nurse neela","tirisfal glades"},ang={["faction:Horde"]="Nurse Neela håller till i den Forsaken-bosättningen Brill i Tirisfal Glades, vilket gör hennes undervisning till en viktig lokal resurs för Horde-äventyrare.",["profession:Cooking"]="Matlagningsinstruktörer lär ut hur man tänder en enkel lägereld, något som krävs för att anlägga en lägerplats i vildmarken innan man lägger till medicinsk utrustning.",["race:Undead"]="Nurse Neela, som har sin bas i Brill, hjälper Forsaken och deras allierade att anpassa sina medicinska kunskaper för att överleva i Lordaerons förstörda landskap."},sec={{t="Medicin ute i fält",b="Att färdas bortom befästa bosättningar innebär ständig fysisk fara, från fientliga bestar till rivaliserande fraktioner. För resande utövare av First Aid gör kunskapen att sätta ihop ett särskilt First Aid Kit en vanlig viloplats i vildmarken till en mobil fältklinik, där sår kan plåstras om och livskraft återställas långt från samhällets infrastruktur."},{t="Undervisning i Brill",b="I den Forsaken-staden Brill lär Nurse Neela ut hur grundläggande medicinska kunskaper kan omsättas i praktisk lägerutrustning. När en resenär visar tillräcklig skicklighet i att lägga förband och ge behandling delar hon med sig av teknikerna för att sätta ihop ett bärbart kit. Sådan utrustning kräver en lämplig plats i vildmarken med en enkel lägereld, som vanliga matlagningsinstruktörer kan lära resenärer att göra."}},faq={{q="Vem är Nurse Neela?",a="Nurse Neela är en vårdgivare i den Forsaken-bosättningen Brill i Tirisfal Glades. Hon lär skickliga utövare av First Aid att tillverka First Aid Kits avsedda för lägerplatser ute i fält.",al={"vem är nurse neela","var finns nurse neela","nurse neelas plats"}},{q="Vad gör ett First Aid Kit vid ett läger?",a="Ett First Aid Kit är ett särskilt campingtillbehör som tillverkas av utövare av First Aid. När det sätts upp på en lägerplats i vildmarken ger det viktiga läkande resurser för att behandla skador som uppstått under äventyren.",al={"vad är ett first aid kit","first aid kits syfte","first aid kit för läger"}},{q="Varför behövs en lägereld för att slå läger?",a="En lägereld är grunden för varje läger i vildmarken och krävs innan du sätter upp fler bekvämligheter, som medicinkit. Matlagningsinstruktörer och kockar lär ofta ut grunderna i att bygga lägereldar.",al={"varför behövs en lägereld","hur gör man en lägereld","lägereld för matlagning och läger"}},{q="Kan du slå läger i en stad?",a="Stadsbor och lokala myndigheter brukar ogilla att resenärer slår upp tält och gör upp eld mitt på stadens gator. Lägerplatser måste anläggas ute i den öppna vildmarken.",al={"kan jag slå läger i en stad","camping i brill","varför slå läger i vildmarken"}},{q="Vem lär ut hur man gör ett First Aid Kit?",a="Nurse Neela i Brill lär behöriga äventyrare att tillverka kitet när de har visat tillräcklig skicklighet i yrket First Aid.",al={"vem lär ut first aid för camping","lärare i campingens first aid","lärare för first aid kit"}},{q="Vad är målet med Camping 101: First Aid?",a="Camping 101: First Aid är en introduktionsuppgift som leder blivande sjukvårdare till Nurse Neela i Brill. Den lär äventyrare att använda sina kunskaper i fältmedicin för att sätta ihop medicinsk utrustning för läger ute i det fria.",al={"vad är camping 101: first aid","uppdraget camping 101"}}},fp="22,261,21.354.0,20.426.0,19.208.0,39.214.0,42.204.0,36.189.0,42.142.0,43.217.0"}
P.entries["quest:97957"] = {n="Camping 101: Herbalism",s="Camping 101: Herbalism vägleder blivande örtmästare till lokala yrkestränare runtom i Azeroth, som Faruza i Brill, för att bemästra Incense Candles. Dessa väldoftande skapelser ger viktig återhämtning åt magiker som vilar i läger ute i vildmarken.",h="Camping 101: Herbalism vägleder blivande örtmästare till lokala yrkestränare runtom i Azeroth, som Faruza i...",kw={"brill","camping","eleanor shackleton","faruza","örtkunskap","incense candle","tirisfal"},ang={["class:Mage"]="Magiker uppskattar örtmästare som tillverkar Incense Candles, eftersom den lugnande röken hjälper dem att återfå fokus och humör långt från värdshusens bekvämligheter.",["profession:Herbalism"]="Örtmästare kan stötta äventyrargrupper direkt genom att tillverka väldoftande Incense Candles till lägereldarna, i stället för att bara brygga elixir eller sälja växtstjälkar.",["race:Undead"]="Förskrivna resenärer från Deathknell och Brill lär sig av Faruza att göra praktiskt hantverk av Tisifals vissna växtlighet."},sec={{t="Växter till lägret",b="Örtkunskap ses ofta som grunden till alkemi, men rötter och blommor som samlas in i fält är minst lika viktiga för att klara sig i vildmarken. Erfarna resenärer visar blivande växtsamlare till regionala örtmästare, där de får lära sig att tillverka Incense Candles. I Tirisfal Glades hänvisar Eleanor Shackleton lovande växtsamlare till Faruza i Brill när de har visat grundläggande färdigheter."},{t="Näring för sinnet",b="Livet på vägarna tär hårt på magiker och andliga utövare. Incense Candles sprider återhämtande dofter som ska muntra upp och lugna trötta sinnen. Genom att blanda torkade växter i ljus ger samlare viktig hjälp åt helare och magiker vars magiska krafter sinar under långa resor."}},faq={{q="Vad är syftet med det här uppdraget?",a="Uppdraget vägleder örtmästare till en grundläggande färdighetsnivå så att de kan lära sig att tillverka Incense Candles av en örttränare. Ljusen hjälper magiker att hålla ut och ger dem stöd när de vilar ute i vildmarken.",al={"varför campa med örtkunskap","vad ger camping 101","målet med camping 101: herbalism"}},{q="Vem erbjuder det här uppdraget i Tirisfal Glades?",a="Eleanor Shackleton ger örtmästare den här vägledningen i Tirisfal Glades och visar dem vidare till Faruza i den närbelägna bosättningen Brill.",al={"vem ger camping 101: herbalism i tirisfal","eleanor shackleton uppdrag"}},{q="Vad gör ett Incense Candle?",a="Incense Candles ger lägret fördelar, muntrar upp och hjälper helare och magiker som behöver återfå sitt mentala fokus medan de vilar ute i fält.",al={"effekten av incense candle","vad används incense candles till"}},{q="Vem lär ut receptet på Incense Candle?",a="Lokala örttränare undervisar äventyrare som uppfyller kraven. I Tirisfal Glades sköter Faruza i Brill träningen, medan tränare som Jandi i Orgrimmar, Reyna Stonebranch i Ironforge och Malorne Bladeleaf i Dolanaar gör det i andra städer och samhällen.",al={"vem lär ut örtkunskap för camping","var lämnar man in camping 101: herbalism"}},{q="Kan medlemmar i andra fraktioner och raser ta det här uppdraget?",a="Ja. Eleanor Shackleton och Faruza hjälper resenärer i Tirisfal Glades, medan andra uppdragsgivare och tränare ger örtmästare samma undervisning runtom i Kalimdor och Eastern Kingdoms.",al={"är camping 101 bara för horden","camping 101: herbalism för alliansen"}},{q="Vilken färdighet krävs för att slutföra träningen?",a="Örtmästare måste visa verklig skicklighet i sitt yrke och nå en örtkunskapsnivå på tjugo innan tränaren lär ut ljusreceptet.",al={"hur mycket örtkunskap krävs","färdighetsnivå för camping 101"}}},fp="22,259,18.400.0,23.318.0,34.223.0,41.136.0,31.176.0,38.256.0,56.196.0,58.140.0"}
P.entries["quest:97960"] = {n="Camping 101: Skinning",s="Camping 101: Skinning är en grundläggande vildmarkslektion för nybörjare inom insamling i Tirisfal Glades och på andra håll i Azeroth. Den hänvisar garvare som har övat sitt yrke till lokala hantverkare för att lära sig tillverka en hållbar Camp Chair av insamlade hudar.",h="Camping 101: Skinning är en grundläggande vildmarkslektion för nybörjare inom insamling i Tirisfal Glades och...",kw={"brill","camp chair","camping","eleanor shackleton","rand rhobart","garvning","tirisfal glades","undercity"},ang={["faction:Horde"]="Horde-jägare och samlare tar till vara på varje bit av ett fällt byte, så att inget går till spillo längs den obarmhärtiga vägen.",["race:Undead"]="Även Forsaken, som är fria från dödlig utmattning, har nytta av att hålla lägren funktionella när de jagar de pestsmittade bestarna i Tirisfal."},sec={{t="Bekvämlighet i vildmarken",b="För att överleva i vildmarken krävs mer än en vass kniv; du måste också veta hur du hushållar med krafterna mellan prövningarna. Äventyrare som Eleanor Shackleton betonar att hudar från fällda bestar ger mer än bara råvaror för handel. Genom att utveckla grundläggande fältkunskaper kan garvare tillverka viktig lägerutrustning, som stolar av behandlade hudar, så att trötta vandrare kan vila och återhämta sig ordentligt före nästa farliga möte."},{t="Bemästra hantverket",b="I Tirisfal Glades hänvisas unga Forsaken-garvare som nått grundläggande skicklighet till Rand Rhobart, som arbetar längs vägen mellan Brill och Undercitys ruiner. Rhobart delar med sig av praktiska metoder för att göra grovt läder till funktionella lägersäten, ett hantverk som garvarmästare över hela Horde och Alliance också lär ut."}},faq={{q="Vad är syftet med det här uppdraget?",a="Uppdraget hänvisar nybörjare inom garvning till en skicklig yrkesmentor som kan lära dem att sätta ihop en Camp Chair av insamlade djurhudar.",al={"vad gör camping 101: skinning","varför camping 101: skinning","belöning från camping 101"}},{q="Vem erbjuder den här utbildningen i Tirisfal Glades?",a="I Tirisfal Glades delas uppgiften ut av Eleanor Shackleton, som hänvisar nya garvare till Rand Rhobart längs vägen mellan Brill och Undercity.",al={"vem ger uppdraget i tirisfal","eleanor shackleton uppdrag"}},{q="Vilken färdighetsnivå krävs för att slutföra uppgiften?",a="Du måste höja din garvningsfärdighet till minst 20 innan tränaren anser dig erfaren nog att lära dig tillverka utrustning för lägret.",al={"vilken garvningsnivå behöver jag","krav för camping 101: skinning","krävd garvningsfärdighet"}},{q="Var hittar man Rand Rhobart?",a="Rand Rhobart finns längs huvudvägen som går söderut från Brill mot ingången till Undercity i Tirisfal Glades.",al={"rand rhobarts plats","var finns rand rhobart","rand rhobart tirisfal"}},{q="Kan medlemmar av andra fraktioner lära sig tekniken?",a="Ja. Forsaken lär sig av Rand Rhobart, medan motsvarande instruktörer tränar garvare i Goldshire, Ironforge, Dolanaar, Orgrimmar, Bloodhoof Village och Shen'dar Village.",al={"är uppdraget bara för horde","kan alliance göra camping 101: skinning","alliance garvning camp chair"}},{q="Varför är det användbart att tillverka en Camp Chair?",a="En Camp Chair ger dig en bekväm plats att sitta och återfå uthålligheten ute i vildmarken, så att du är utvilad och uppmärksam inför kommande strider.",al={"vad gör en camp chair","varför tillverka en camp chair"}}},fp="21,270,20.439.0,19.382.0,34.152.0,44.157.0,51.149.0,32.127.0,51.169.0,36.153.0"}
P.entries["quest:97965"] = {n="Camping 101: First Aid",s="Camping 101: First Aid hänvisar resenärer till Shen'dar Village för att lära sig tillverka viktig sjukvårdsutrustning för ett läger i vildmarken. Genom att söka upp Naleeia Tattermend kan skickliga utövare skapa lägerkit som kan behandla skador och rädda liv långt från civilisationen.",h="Camping 101: First Aid hänvisar resenärer till Shen'dar Village för att lära sig tillverka viktig...",kw={"bandage","camping","camping 101: first aid","första hjälpen","first aid kit","naleeia tattermend","shen'dar village","överlevnad i vildmarken"},sec={{t="Läkning i vildmarken",b="Livet på vägarna genom Azeroth är fyllt av våld, vilda bestar och faror från omgivningen. För alla resenärer är det lika praktiskt som hedervärt att lära sig First Aid, så att såriga skärsår och brutna ben kan förbindas utan att enbart förlita sig på magi. Ett särskilt First Aid Kit vid ett läger i vildmarken ger en pålitlig plats för läkning, där utmattade äventyrare kan återhämta sig och ta hand om sina följeslagare innan de fortsätter."},{t="Mentorn i Shen'dar Village",b="Alla fältsjukvårdare vet inte hur man sätter ihop hållbar sjukvårdsutrustning för läger. I Shen'dar Village lär en specialist vid namn Naleeia Tattermend hängivna utövare konsten att tillverka First Aid Kits för lägerplatser. De som söker hennes vägledning måste först visa att de behärskar grundläggande sjukvård innan hon avslöjar sina metoder."}},faq={{q="Vem behöver jag tala med om det här uppdraget?",a="Du måste söka upp Naleeia Tattermend i Shen'dar Village. Hon har kunskapen som krävs för att tillverka specialiserad sjukvårdsutrustning för läger i vildmarken.",al={"vem man talar med om första hjälpen för läger","var naleeia tattermend finns","lämna in camping 101: first aid"}},{q="Var ligger Shen'dar Village?",a="Shen'dar Village är en by på Zephras Isle, där sjukvårdaren Naleeia Tattermend bor. Utövare som söker avancerad utbildning i första hjälpen för vildmarken reser dit när de har finslipat sina färdigheter.",al={"var shendar village ligger","shen'dar village plats","första hjälpen i shen'dar village"}},{q="Vad är syftet med att tillverka ett First Aid Kit för lägret?",a="Utbildningen lär dig att tillverka ett First Aid Kit anpassat för en äventyrslägersplats. I vildmarken ger lättillgänglig sjukvårdsutrustning vid lägret livsviktig läkning mellan färderna och kan vara skillnaden mellan liv och död.",al={"vad första hjälpen för läger gör","first aid kit för läger","varför tillverka first aid kit"}},{q="När lär Naleeia Tattermend mig att tillverka kitet?",a="Naleeia Tattermend kräver att du visar tillräckliga kunskaper i First Aid innan hon går med på att dela med sig av sina tillverkningsmetoder. Du måste öva på grunderna i att lägga bandage och behandla skador innan du sätter ihop fältkit.",al={"när man kan lära sig tillverka first aid kit","naleeia tattermends krav","krav för camping 101: first aid"}},{q="Varför anses First Aid vara både hedervärt och praktiskt?",a="Sår och fysiska trauman är oundvikliga risker när man äventyrar genom Azeroth. Bandage och medicinska behandlingar gör det möjligt för resenärer av alla slag att ta hand om sina egna skador och stabilisera följeslagare utan att enbart förlita sig på magisk hjälp.",al={"varför första hjälpen är viktig","första hjälpen lore","är första hjälpen användbart"}},{q="Kan alla äventyrare tillverka ett First Aid Kit för lägret?",a="Alla äventyrare som ägnar sig åt att studera First Aid och visar sin kompetens kan lära sig tillverka ett First Aid Kit för lägret av Naleeia Tattermend i Shen'dar Village.",al={"kan alla lära sig tillverka det här kitet","vem kan tillverka first aid kit för läger"}}},fp="22,281,25.455.0,30.355.0,43.150.0,34.199.0,57.243.0,55.223.0,57.242.0,49.177.0"}
P.entries["quest:97967"] = {n="Camping 101: Fishing",s="Camping 101: Fishing vägleder blivande fiskare i hur tålamod med spö och lina kan göra vildmarksexpeditioner bättre. Genom att söka upp Fenn Fairweather i Shen'dar Village kan skickliga fiskare lära sig att tillverka en dekorativ inredning, Fish Bowl, som höjer moralen och gör lägret bekvämare.",h="Camping 101: Fishing vägleder blivande fiskare i hur tålamod med spö och lina kan göra vildmarksexpeditioner...",kw={"camping","camping 101: fishing","fenn fairweather","fish bowl","fiske","shen'dar village"},sec={{t="Hemmets härd",b="Livet i vildmarken kräver mer än vassa klingor och stadig rustning. Att hålla moralen uppe i fält kan vara skillnaden mellan triumf och utmattning. Fiske ses ofta bara som ett stillsamt tidsfördriv eller ett sätt att skaffa proviant, men skickliga fiskare kan använda sitt hantverk för att göra lägret bekvämare. Genom att fånga levande fiskar och förbereda särskilda inredningsföremål kan en resenär förvandla ett trist läger till en välkomnande fristad."},{t="Hantverkaren i Shen'dar",b="I Shen'dar Village delar hantverkaren Fenn Fairweather med sig av yrkeshemligheter till erfarna fiskare som förstår tålamodet bakom spö och rulle. Den som visar tillräcklig skicklighet kan lära sig att tillverka en Fish Bowl, en enkel lägerinredning som sprider glädje och ro bland trötta följeslagare. Högt humör ute i vildmarken hjälper gruppmedlemmar att hålla fokus och beslutsamhet när faror hotar."}},faq={{q="Vem lär ut lägerhantverket Fish Bowl?",a="Fenn Fairweather bor i Shen'dar Village. När du har visat tillräcklig skicklighet i fiske kan Fenn lära dig att tillverka en Fish Bowl som inreder och livar upp lägret.",al={"vem lär ut fish bowl","var finns fenn fairweather","instruktör för fish bowl"}},{q="Vad är syftet med en Fish Bowl i lägret?",a="En Fish Bowl är en dekorativ inredning till lägret som ger dig och dina följeslagare lite bekvämlighet och glädje. Ett välskött läger och gott humör håller äventyrarna skärpta och stärker deras beredskap inför farliga prövningar i fält.",al={"vad gör fish bowl","fish bowl-förstärkning","effekt av fish bowl i lägret"}},{q="Var ligger Shen'dar Village?",a="Shen'dar Village är en bosättning som fungerar som samlingsplats för hantverkare och instruktörer, däribland Fenn Fairweather. Fiskare reser dit för att lära sig praktiska lägerhantverk som passar deras färdigheter.",al={"var ligger shen'dar village","shen'dar village plats"}},{q="Vilken färdighet krävs för att lära sig det här lägerhantverket?",a="Du måste först visa grundläggande färdighet som fiskare innan du kan börja med hantverket. När du har finslipat din fiskefärdighet delar instruktörer i Shen'dar Village med sig av metoderna för att sätta ihop lägerinredning som Fish Bowl.",al={"krav för camping och fiske","när kan jag lära mig fish bowl","hur börjar jag med camping och fiske"}},{q="Varför är fiske viktigt för lägerlivet i vildmarken?",a="En fiskare bidrar till lägerlivet på oväntade sätt, utöver att bara dra upp fångster till mat. En färsk fångst i en tillverkad skål skänker ett lugnt, välbekant inslag och höjer moralen under långa expeditioner i vildmarken.",al={"varför fiske för lägerlivet","nytta med fiske i lägret"}},{q="Vem är Fenn Fairweather?",a="Fenn Fairweather är en hantverkare och instruktör i Shen'dar Village. Fenn förstår vad som gör livet i vildmarken bekvämt och delar med sig av särskild kunskap om lägerinredning till skickliga fiskare.",al={"vem är fenn fairweather","fenn fairweather bakgrund"}}},fp="20,292,22.452.0,23.416.0,40.199.0,44.251.0,26.221.0,51.241.0,47.256.0,24.206.0"}
P.entries["quest:97968"] = {n="Camping 101: Herbalism",s="Camping 101: Herbalism visar samlare vägen till lärare som kan lära dem att tillverka Incense Candle för lägerplatser i vildmarken. Med skördade växtingredienser kan örteologer erbjuda väldoftande tröst som stärker magiker och helare under långa resor.",h="Camping 101: Herbalism visar samlare vägen till lärare som kan lära dem att tillverka Incense Candle för...",kw={"läger","camping","camping 101: herbalism","helare","herbalism","örter","incense candle","magiker"},ang={["class:Mage"]="Magiker som förlorar sin koncentration i strid uppskattar lägerrökelseljus som lugnar sinnet och stödjer återhämtningen av magisk kraft.",["class:Priest"]="Rökelseljus som tänds vid en lägerplats höjer modet och fyller på de mentala krafterna hos heliga helare mellan striderna.",["profession:Herbalism"]="När man samlar växter i vildmarken får man de råa, aromatiska örter som behövs för att tillverka rökelse till lägret. Därmed är örteologens växtinsamling praktisk för överlevnad såväl som för alkemi."},sec={{t="Vilda växter längs vägen",b="För resenärer som tillbringar dagarna med att vandra genom vildmarken är det mycket mer än tidsfördriv att samla rötter och kronblad. Camping 101: Herbalism introducerar skickliga samlare till praktiska färdigheter i fält och för dem samman med mentorer som vet hur vilda, aromatiska växter blir till Incense Candle för lägret. I stället för att bara sälja färska stjälkar eller brygga drycker kan en samlare använda skördade växter för att hjälpa en grupp längs vägen."},{t="Lugn för sinnet",b="Långa resor genom fientligt territorium tär på helare och magiker, vars mentala krafter och moral är avgörande i strid. Ett Incense Candle som brinner vid en aktiv lägerplats fyller luften med lugnande, uppfriskande dofter som håller modet uppe. Magianvändare och helare uppskattar särskilt den aromatiska förstärkningen, som hjälper följeslagarna att återfå klarhet och styrka innan de ger sig ut i faran igen."}},faq={{q="Vad är Camping 101: Herbalism?",a="Camping 101: Herbalism är ett uppdrag för äventyrare som har övat på att samla örter. Det introducerar örteologen till specialiserade hantverkare som kan lära ut hur man tillverkar rökelse för läger i vildmarken.",al={"vad är camping 101: herbalism","uppdraget camping 101: herbalism","uppdrag om herbalism och camping"}},{q="Vad används Incense Candle till?",a="Incense Candle är ett lägertillbehör som tillverkas av växtmaterial. När ett sådant brinner på en lägerplats stärker det vilande äventyrares moral och mod, särskilt genom att ge helare och magiker en välgörande förstärkning.",al={"vad gör incense candle","effekt av incense candle vid läger","varför tillverka incense candle"}},{q="Vem lär ut hur man tillverkar Incense Candle?",a="Tränaren beror på var du börjar: Reyna Stonebranch i Ironforge, Malorne Bladeleaf i Dolanaar, Herbalist Pomeroy i Elwynn Forest, Jandi i Orgrimmar, Faruza i Brill, Komin Winterhoof i Thunder Bluff eller Syriel Nightrain i Valanaar.",al={"vem lär ut incense candle","tränare för incense candle","var lär man sig incense candle"}},{q="Varför är Incense Candle särskilt användbart för magianvändare?",a="Att kanalisera magi och vårda sår i strid dränerar både fysisk energi och mental koncentration. Gott mod är viktigt för att hålla magiker redo för strid, och den lugnande röken från ett rökelseljus hjälper dem att återhämta sig.",al={"varför behöver magiker rökelse","incense candle för helare","incense candle för magianvändare"}},{q="Måste man vara örteolog för att ta det här uppdraget?",a="Den här instruktionen riktar sig direkt till dem som kan samla växter och örter, eftersom metoderna går ut på att identifiera och använda vilda, aromatiska växter.",al={"kan vem som helst lära sig incense candle","behöver jag herbalism för camping 101: herbalism","krav på herbalism för lägerljus"}},{q="Hur hänger Herbalism ihop med camping?",a="Skördade växter från vildmarken kan användas till mer än brygder och salvor. De har även praktiska och väldoftande användningsområden vid lägret, som att tillverka rökelse som piggar upp trötta följeslagare.",al={"är herbalism bara till för brygder","användning av örter vid läger","föremål för lägret från herbalism"}}},fp="22,291,23.430.0,17.397.0,31.221.0,35.222.0,42.243.0,58.224.0,50.165.0,36.175.0"}
P.entries["quest:97969"] = {n="Camping 101: Leatherworking",s="Camping 101: Leatherworking vägleder blivande läderarbetare till fördjupad undervisning i att tillverka tåliga vildmarksskydd. Hos Indari Sunseam i Shen'dar Village får hantverkare lära sig sy skyddande tält som ger välbehövlig vila under långa expeditioner i vildmarken.",h="Camping 101: Leatherworking vägleder blivande läderarbetare till fördjupad undervisning i att tillverka...",kw={"campingtält","lägereld","camping","matlagning","indari sunseam","läderarbete","shen'dar village","tält","vildmark"},ang={["profession:Cooking"]="Ett tält räcker inte för att skapa ett fungerande läger. Resenärer måste också kunna grunderna i att göra upp lägereld, något de vanligtvis lär sig av matlagningsinstruktörer."},sec={{t="Skydd på vägen",b="För läderarbetare på resande fot är det viktigt att kunna förvandla hudar och pälsar till tålig utrustning för vildmarken. När hantverket är inlärt hänvisas hantverkare till Indari Sunseam i Shen'dar Village för att lära sig tillverka ett ordentligt campingtält. Sådana skydd håller äventyrare torra under ihållande skyfall och svala under stekande sol, så att de får ordentligt med vila under långa resor."},{t="Lägerplatser i vildmarken",b="Att slå upp ett tält kräver respekt för gränserna för offentliga platser, eftersom stadsbor ogillar primitiva lägerplatser som skräpar ner gatorna. Läger måste slås upp ute i vildmarken. Dessutom är ett stadigt skydd bara halva lösningen: inget läger är komplett utan en värmande lägereld. Därför bör äventyrare besöka en lokal kock och lära sig grunderna i att göra upp eld innan de ger sig ut i vildmarken."}},faq={{q="Vem lär läderarbetare att tillverka ett tält?",a="Indari Sunseam bor i Shen'dar Village och lär skickliga läderarbetare att tillverka egna campingtält.",al={"vem lär ut tält i läderarbete","instruktör för campingtält","var finns indari sunseam"}},{q="Vad är syftet med att tillverka ett tält?",a="Ett välgjort tält skyddar resenärer mot hårt väder, som regn och brännande hetta, så att äventyrare får den vila de behöver för att hålla sig alerta längs vägen.",al={"vad gör ett tält","tältets syfte","tältets fördelar"}},{q="Var kan ett campingtält slås upp?",a="Tält får inte slås upp i stadskärnor där lokalbefolkningen motsätter sig dem. Resenärer måste ta sig ut i den öppna vildmarken innan de slår läger.",al={"kan jag slå upp tält i en stad","var kan jag använda tält","lägerregler"}},{q="Vad mer behövs för att slå upp ett ordentligt läger?",a="Ett komplett läger behöver en sprakande lägereld utöver skyddet. Äventyrare uppmuntras att söka upp en matlagningsinstruktör för att lära sig göra upp en enkel eld.",al={"behöver jag en eld","krav för läger","vad mer behövs för läger"}},{q="När lär Indari Sunseam dig tältmönstret?",a="Du måste öva på läderarbete och visa tillräcklig skicklighet i yrket innan Indari Sunseam lär dig att tillverka ett campingföremål.",al={"när kan jag lära mig tält","tältkrav","krav på tält i läderarbete"}},{q="Vad är Shen'dar Village?",a="Shen'dar Village är bosättningen där Indari Sunseam bor och arbetar, och där resenärer kan få undervisning i att tillverka campingutrustning.",al={"var ligger shen'dar village","shen'dar village plats","indari sunseams ort"}}},fp="27,285,19.396.0,20.392.0,47.123.0,39.162.0,36.144.0,43.167.0,52.151.0,25.142.0"}
P.entries["quest:97971"] = {n="Camping 101: Skinning",s="Camping 101: Skinning lär äventyrare att förvandla insamlade hudar till en praktisk Camp Chair för läger i vildmarken. Under ledning av Mendalass Tattermend i Shen'dar Village lär sig garvare att förena sitt hantverk med överlevnad i vildmarken och avkoppling vid lägerelden.",h="Camping 101: Skinning lär äventyrare att förvandla insamlade hudar till en praktisk Camp Chair för läger i...",kw={"camp chair","lägereld","camping 101","hudar","mendalass tattermend","shen'dar village","garvning","vildmark"},ang={["profession:Cooking"]="Matlagning och överlevnad i vildmarken går hand i hand. Som Mendalass påpekar kräver en ordentlig lägerplats en enkel lägereld, en färdighet som traditionellt lärs ut av matlagningsinstruktörer."},sec={{t="Bekvämlighet i vildmarken",b="Att ta hudar från fallna bestar är en viktig överlevnadsfärdighet i Azeroth, men nyttan sträcker sig långt bortom enkel rustningstillverkning. Genom Camping 101: Skinning lär sig samlare att använda sitt yrke för att överleva i vildmarken genom att tillverka en bärbar Camp Chair. En stunds vila på en bekväm stol ute i vildmarken hjälper utmattade äventyrare att återfå sina krafter och hålla sig i bästa stridsform inför nästa strid."},{t="Undervisningen i Shen'dar Village",b="För att bemästra mönstret skickas äventyrare till Shen'dar Village för att träffa Mendalass Tattermend när de visat att de behärskar en flåkniv. Mendalass lär resenärer att sätta ihop hållbara sittplatser av insamlade hudar. Men för att slå läger krävs mer än möbler: bosättningar tolererar inte tillfälliga läger innanför stadsgränsen, och en lägerplats är inte komplett utan en sprakande lägereld, en färdighet man traditionellt lär sig av lokala matlagningsinstruktörer."}},faq={{q="Vad handlar Camping 101: Skinning om?",a="Camping 101: Skinning leder skickliga garvare till Mendalass Tattermend i Shen'dar Village. Genom utbildningen lär sig äventyrare att göra om insamlade hudar till en praktisk Camp Chair för vila och återhämtning i fält.",al={"vad är det här för uppdrag","syftet med camping 101","varför göra uppdraget"}},{q="Vem är Mendalass Tattermend?",a="Mendalass Tattermend är en garvningsinstruktör i Shen'dar Village. Han lär skickliga garvare att sy ihop insamlade hudar till bekväma sittplatser för läger i vildmarken.",al={"vem är mendalass","vem lär ut camp chair","mendalass tattermend"}},{q="Var finns Mendalass Tattermend?",a="Mendalass Tattermend finns i Shen'dar Village, dit äventyrare måste resa för att visa sin skicklighet och lära sig konsten att tillverka lägerutrustning.",al={"var finns mendalass","var ligger shendar village","var lämnar jag in det här"}},{q="Vilket föremål lär det här uppdraget dig att tillverka?",a="Garvare lär sig mönstret för att tillverka en Camp Chair av hudar från fallna bestar, så att de får en bekväm plats att vila på ute i vildmarken.",al={"vad tillverkar garvare","recept på camp chair","vilket föremål får jag"}},{q="Kan man slå läger inne i en stad?",a="Stadsbor ser ogärna att man slår läger mitt i en bosättning. Läger och Camp Chairs är till för vildmarken, långt från stadskärnorna.",al={"kan jag slå läger i staden","var kan jag slå läger","var använder jag camp chair"}},{q="Vad mer behövs för ett ordentligt läger?",a="Varje ordentlig lägerplats behöver en sprakande lägereld för att vara komplett. Äventyrare som ännu inte kan göra upp eld rekommenderas att fråga en matlagningsinstruktör om grunderna.",al={"vad mer behöver jag till lägret","lägereld behövs","krav för läger"}}},fp="21,267,20.446.0,33.502.0,36.232.0,28.185.0,40.147.0,44.170.0,34.158.0,44.189.0"}
P.entries["quest:97973"] = {n="Camping 101: Tailoring",s="Camping 101: Tailoring lär skräddare konsten att skapa specialutrustning för vildmarksläger. Genom att visa sin skicklighet för Taleen Shimmerthread i Shen'dar Village lär sig skräddare att sy en inspirerande Faction Banner som höjer modet och håller lägrets moral uppe.",h="Camping 101: Tailoring lär skräddare konsten att skapa specialutrustning för vildmarksläger.",kw={"lägerfana","lägerliv","camping 101: tailoring","faction banner","shen'dar village","skrädderi","taleen shimmerthread","yrkesfärdighet"},ang={["profession:Tailoring"]="Skräddare lär sig att tillverka inspirerande Faction Banners som stärker lägrets moral och ger allierade energi ute i fält."},sec={{t="Vävarens bidrag till lägret",b="Camping 101: Tailoring hjälper tygmakare att utveckla sitt hantverk bortom enkla kläder och väskor. I den otämjda vildmarken kräver överlevnad mer än varma kläder; en ordentlig lägerplats kan vara skillnaden mellan uthållighet och nederlag. Skräddare uppmuntras att söka avancerad undervisning för att förvandla tygbuntar till symboler för enighet och styrka."},{t="Undervisning i Shen'dar Village",b="Uppdraget leder blivande skräddare till Shen'dar Village, där Taleen Shimmerthread undervisar i lägerhantverk. De som har utvecklat tillräckliga färdigheter i skrädderi kan lära sig metoderna för att tillverka en Faction Banner. En sådan fana, omsorgsfullt sydd och stolt rest vid lägret, blir en inspirerande samlingspunkt som höjer moralen och håller allierade fulla av energi inför prövningarna som väntar."}},faq={{q="Vad är Camping 101: Tailoring?",a="Camping 101: Tailoring leder lovande skräddare till specialundervisning i fälthantverk. När du har visat tillräcklig skicklighet i skrädderi kan du lära dig att skapa en dekorativ och inspirerande Faction Banner för läger i vildmarken.",al={"vad är det här för uppdrag","uppdraget camping 101 tailoring","lägerfana i skrädderi"}},{q="Vem är Taleen Shimmerthread?",a="Taleen Shimmerthread är en skicklig skräddare i Shen'dar Village. Hon undervisar skickliga hantverkare i hur de väver lägerföremål med skrädderi, däribland fanor som höjer modet i lägret.",al={"taleen shimmerthread","vem lär ut att väva lägerfana","var finns taleen shimmerthread"}},{q="Var ligger Shen'dar Village?",a="Shen'dar Village är bosättningen där Taleen Shimmerthread bor. Skräddare beger sig dit för att få särskild vägledning i hur de kan använda sitt tyghantverk till lägerutrustning.",al={"var ligger shen'dar village","shen'dar village plats"}},{q="Vilket lägerföremål kan skräddare lära sig att tillverka?",a="En Faction Banner är ett lägerföremål som skräddare tillverkar. På slagfält och under hårda expeditioner är inspiration och moral livsviktiga, och en rest fana skänker en energigivande närvaro åt dem som vilar i lägret.",al={"faction banner för läger","vad tillverkar skräddare till lägret","lägerföremål i skrädderi"}},{q="Vilka krav finns för att lära sig tillverka lägerfanan?",a="Du måste visa att du behärskar skrädderi som yrkesfärdighet innan Taleen Shimmerthread i Shen'dar Village lär dig mönstret för att väva en Faction Banner till ditt läger.",al={"hur lär man sig faction banner","krav för faction banner i skrädderi"}},{q="Varför är fraktionsfanor värdefulla i lägret?",a="Moral och inspiration är avgörande under varje fälttåg. Skräddare syr fraktionsfanor för att visa sin tillhörighet och skapa en energigivande samlingspunkt som hjälper äventyrare att hålla ut under strapatsrika resor.",al={"varför tillverka en faction banner","lägerfana och moral"}}},fp="22,281,33.349.0,31.405.0,31.244.0,28.199.0,26.178.0,45.216.0,54.169.0,41.196.0"}
P.entries["quest:97977"] = {n="Nature's Call",s="Nature's Call är ett uppdrag i Shadowglen där dryaden Tarindrella vill ta reda på varför de lokala Gnarlpine-furbolgerna plötsligt vänt sig mot sina långvariga Night Elf-allierade. Genom att samla in ristade totem från deras övergivna läger hjälper äventyrare till att avslöja den oroande andliga fördärv som sprider sig genom Teldrassil.",h="Nature's Call är ett uppdrag i Shadowglen där dryaden Tarindrella vill ta reda på varför de lokala...",kw={"furbolg","gnarlpine","grell","grellkin","nature's call","mardrömmar","shadowglen","tarindrella","teldrassil","totem"},ang={["class:Druid"]="Druider är lyhörda för naturens balans och den andliga fördärv som påverkar Kalimdors varelser. Därför är den mardrömsdrivna fördärven av furbolgernas totem ett alarmerande tecken.",["faction:Alliance"]="Att skydda Teldrassils grenar är avgörande för att värna det unga Night Elf-riket och se till att deras nya Alliance-allierade förblir förankrade på Kalimdor.",["race:NightElf"]="Gnarlpine hade länge varit Night Elf-folkets följeslagare. Därför är deras fall i fientlighet och vansinne en djupt personlig tragedi för Teldrassils försvarare."},sec={{t="Undersöker gläntan",b="Nature's Call är ett undersökningsuppdrag i Shadowglen som ges av dryaden Tarindrella. Hon vägrar tro att Gnarlpine-furbolgerna skulle överge århundraden av vänskap med Night Elf utan anledning. Därför ber hon resenärer att leta igenom furbolgernas hastigt övergivna läger längs gläntans västra gräns och hämta hela, graverade totem."},{t="Skuggan och mardrömmen",b="När de återfunna totemen dechiffreras blottas en tragisk färd in i vansinnet. Gnarlpine plågades av återkommande mardrömmar om en annalkande skugga som var ämnad att utplåna dem. Med tiden förvandlades ren skräck till blint raseri och förvrängde deras sinnen, tills de såg sina långvariga alviska grannar som själva skuggan de fruktade. Tarindrella hoppas att fynden ska kasta ljus över den djupare sjukdom som sprider sig genom Teldrassil."}},faq={{q="Vem ger uppdraget Nature's Call?",a="Tarindrella är en dryad som vakar över Shadowglen i Teldrassil. Hon oroar sig över de lokala Gnarlpine-furbolgernas plötsliga fientlighet och skickar äventyrare att hämta reliker från deras övergivna läger för att undersöka orsaken till deras vansinne.",al={"vem ger nature's call","vem är tarindrella","tarindrella plats"}},{q="Varför blev Gnarlpine-furbolgerna fientliga?",a="Gravyrer på totem som hämtats från Gnarlpine visar att furbolgerna började lida av hemska mardrömmar om en hotande skugga som skulle förgöra dem. Den krypande skräcken förvandlades till okontrollerbar paranoia och vrede, och fick dem att se sina forna Night Elf-allierade som fiender.",al={"varför attackerade gnarlpine","varför är gnarlpine vansinniga","vad hände med gnarlpine-furbolgerna"}},{q="Var finns Gnarlpine-totemen?",a="De mindre totemen finns i Gnarlpine-furbolgernas övergivna läger längs gläntans västra kant, men grell och grellkin som letar efter mat bland ruinerna har spritt ut några i området runt omkring.",al={"var finns gnarlpine-totemen","hitta gnarlpine-totem","gnarlpine-lägrets plats"}},{q="Varför kan spelare inte samla in de större totemen i lägren?",a="Tarindrella avråder uttryckligen från att försöka hämta de större totemen i lägren. Som dryad har hon ingen aning om vad hon skulle göra med sådana otympliga sniderier och föredrar i stället mindre, bärbara totem med gravyrer.",al={"varför ignoreras stora totem","kan jag plundra stora totem","stort gnarlpine-totem"}},{q="Vilka är Gnarlpine-furbolgerna?",a="Gnarlpine är en furbolgklan från Teldrassil som levde sida vid sida med Night Elf som fredliga allierade. Att de nyligen blivit aggressiva fiender är en onaturlig förändring som orsakats av krypande mardrömmar, inte av urgammalt hat.",al={"vilka är gnarlpine","gnarlpine-lore","är gnarlpine onda"}},{q="Vad är den stora skuggan som nämns på totemen?",a="Gravyrerna berättar om en osedd Great Shadow som hemsöker furbolgernas drömmar. Även om ursprunget till detta mörka inflytande är okänt hoppas Tarindrella att deras öde ska hjälpa till att nysta upp den större fördärv som plågar Teldrassil.",al={"vilken skugga gnarlpine","vad är skuggan i teldrassil","mardrömmar i teldrassil"}}},fp="13,321,22.354.0,28.424.1,34.247.0,44.280.0,39.225.0,57.252.0,30.248.0,49.245.0"}
P.entries["quest:97979"] = {n="The Goddess Provides",s="The Goddess Provides är ett introduktionsuppdrag för kaldorei som handlar om att uppmärksamma Elunes gudomliga gåvor. Bland Teldrassils grenar, efter den långa vaksamhetens slut, lär det unga Night Elf att ta till sig månens vägledning och de skuggor som döljer dem, gåvor från Moder Måne.",h="The Goddess Provides är ett introduktionsuppdrag för kaldorei som handlar om att uppmärksamma Elunes...",kw={"elune","goddess provides","hyjal","kaldorei","lång vaksamhet","moder måne","skuggmantel","teldrassil"},ang={["class:Priest"]="Kaldoreis prästerskap är hängivet Moder Måne och kanaliserar Elunes nåd direkt som vägledande strålglans och gudomligt beskydd.",["faction:Alliance"]="Efter slaget vid Mount Hyjal gjorde Night Elf slut på sin långa isolering och anslöt sig till Alliansen. De ställer sina heliga månkrafter till förfogande för ett gemensamt försvar.",["race:NightElf"]="Som stjärnornas barn ärver kaldorei Elunes direkta välsignelser. De använder månljuset för att visa dolda vägar och förmågan att gömma sig för att smälta in i skuggorna."},sec={{t="Vaksamheten är över",b="I årtusenden efter Sundringen höll kaldorei sin ensamma långa vaksamhet. De vakade över Kalimdor och skyddade Mount Hyjals heliga toppar. Den tredje krigets förödelse och det avgörande försvaret av världsträdet gjorde slut på denna urgamla isolering. Nu har Night Elf flyttat till Teldrassils skyddande grenar och möter en främmande värld. De tar plats på Azeroths större scen genom att knyta band till avlägsna allierade på andra sidan havet."},{t="Moder Månens välsignelser",b="Trots förändrade allianser och nya hem vilar grunden för kaldoreis identitet fortfarande på dyrkan av Elune, Moder Måne. Night Elf får från tidig ålder lära sig att åkalla hennes två aspekter: strålglans som vägleder stridsslag och klargör syftet, och skugga som döljer ens närvaro för fiendens blick. Dessa nedärvda gåvor är både en andlig gemenskap och en praktisk förberedelse inför farorna bortom det stora trädet."}},faq={{q="Vad är The Goddess Provides?",a="The Goddess Provides är en introduktionsrit för unga Night Elf bland Teldrassils grenar. Den lär kaldorei att känna igen och visa de medfödda välsignelser som mångudinnan Elune skänkt dem.",al={"vad är the goddess provides","uppdraget the goddess provides"}},{q="Vem är gudinnan som nämns i uppdraget?",a="Gudinnan är Elune, som kaldorei också vördar som Moder Måne. Hon är den centrala gudomen i Night Elfs kultur och andliga liv. Man tror att hon skänker sina barn månens välsignelser i form av beskydd, klarhet och förmågan att smälta in i skuggorna.",al={"vem är gudinnan","vem är moder måne","night elf-gudinna"}},{q="Vilka gåvor ger Elune kaldorei?",a="Elune skänker en nåd som kan lysa upp en krigares slag och hjälpa dem att träffa rätt, liksom förmågan att smälta in i omgivande skuggor, precis som månen döljer solen under en förmörkelse.",al={"vilka gåvor ger elune","elunes rasegenskaper","elunes krafter"}},{q="Vad var den långa vaksamheten?",a="Den långa vaksamheten var den tusentals år långa isolering som Night Elf upprätthöll för att vaka över Kalimdor. Den tog slut efter det avgörande försvaret av Mount Hyjal mot den brinnande legionen, vilket fick kaldorei att till sist öppna sina gränser.",al={"vad var den långa vaksamheten","varför tog den långa vaksamheten slut"}},{q="Varför har Night Elf anslutit sig till Alliansen?",a="Efter att försvaret av Mount Hyjal gjort slut på deras ensamma isolering valde kaldorei att knyta band till dödliga folkslag på andra sidan havet och ansluta sig till den stora alliansen för ömsesidig överlevnad och gemenskap.",al={"varför gick night elf med i alliansen","kaldorei och alliansen"}},{q="Var äger den här undervisningen rum?",a="Teldrassil är det väldiga stora trädet utanför Kalimdors norra kust. Dess höga, skyddade grenar är Night Elfs nya hem och fristad efter den tredje kriget.",al={"var ligger teldrassil","vad är teldrassil"}}},fp="20,274,17.476.0,24.466.0,29.226.0,44.222.0,46.194.0,24.252.0,45.213.0,39.196.0"}
P.entries["quest:98013"] = {n="Swelling Forces",s="Swelling Forces är ett uppdrag där Arbal ger äventyrare från Grove of the Ancients i uppgift att minska antalet Stormscale-naga som samlas i ruinerna i nordost.",h="Swelling Forces är ett uppdrag där Arbal ger äventyrare från Grove of the Ancients i uppgift att minska...",kw={"arbal","grove of the ancients","highborne","myrmidon","naga","trollkvinna","stormscale","swelling forces","twilight's hammer"},ang={["faction:Alliance"]="Alliansens styrkor som försvarar de heliga skogarna kring Darkshore och Grove of the Ancients måste möta en samordnad front mellan nagorna och Twilight's Hammer.",["race:NightElf"]="Nagorna som strövar omkring i ruinerna var en gång nattalvernas Highborne-fränder. Att se dem återvända för att vanhelga och plundra de forntida skogarna tillsammans med mörka kultister är ett bittert svek."},sec={{t="Ormar i den sjunkna staden",b="Från Grove of the Ancients ser Arbal med stor oro mot ruinerna i nordost. Förbannade Highborne, förvandlade till de ormlika nagorna i Stormscale-stammen, har tagit över resterna av sin en gång magnifika civilisation. De sjunkna stenarna vilar inte i minnet, utan ekar nu av en framryckande härs slingrande marsch. Arbal skickar försvarare till ruinerna för att hugga ned deras växande antal innan de sprider sig ut i den större skogen."},{t="En ohelig allians",b="Stormscale-nagornas närvaro handlar om mer än enkel territoriell aggression. Arbal avslöjar att dessa förvridna forna Highborne hjälper den nihilistiska kulten Twilight's Hammer. Att vanhelga och plundra skogarna som en gång gav dem skydd, särskilt i tjänst hos lömska skuggmästare, är ett oförlåtligt brott. Det är brådskande att minska deras antal för att hindra kulten och dess ormlika allierade från att stärka sitt grepp om landet."}},faq={{q="Vem ger uppdraget Swelling Forces?",a="Arbal ger uppdraget Swelling Forces och skickar äventyrare från Grove of the Ancients för att konfrontera de fientliga naga-styrkor som samlas i ruinerna i nordost.",al={"vem ger swelling forces","arbal uppdragsgivare","var finns arbal"}},{q="Varför är nagorna måltavlor i det här uppdraget?",a="Stormscale-nagorna har tagit över ruinerna i närheten och hotar skogsmarkerna runt omkring. Än mer oroande är att de verkar hjälpa kulten Twilight's Hammer och därmed våldföra sig på markerna de en gång kallade sitt hem.",al={"varför döda nagor","nagor i ruinerna","stormscale-hotet"}},{q="Vad har nagorna för koppling till ruinerna?",a="Som Arbal berättar var nagorna en gång Highborne-alver i det forntida Kalimdor, men drabbades av en fruktansvärd förbannelse. De bodde förr i dessa storslagna städer, men har återvänt som förvridna ormar som söker erövring och förödelse.",al={"vilka är stormscale-nagorna","nagornas ursprung","förbannade highborne"}},{q="Vad har nagorna för koppling till Twilight's Hammer?",a="Uppdraget avslöjar att nagorna hjälper den skuggfulla kulten Twilight's Hammer. Deras exakta överenskommelse är fortfarande höljd i dunkel, men Arbal varnar för att alliansen bara kan föra med sig mer förödelse och elände till de forntida skogarna.",al={"twilight's hammer och nagor","varför samarbetar nagorna med kulten"}},{q="Var samlas Stormscale-styrkorna?",a="Ruinerna ligger nordost om Grove of the Ancients. Äventyrare skickas dit för att hejda den växande Stormscale-hären genom att jaga deras myrmidoner, trollkvinnor och krigare.",al={"var finns ruinerna","var hittar man stormscale"}},{q="Varför anser Arbal att nagornas handlingar är oförlåtliga?",a="För Arbal är det fullständigt oförlåtligt att plundra sitt eget forntida hemland på uppdrag av en mörk härskare. All den ädelhet Highborne en gång ägde har suddats ut av deras förfall till grymhet och mörka allianser.",al={"varför hatar arbal nagorna","oförlåtligt enligt arbal"}}},fp="15,381,27.499.0,18.482.1,36.166.0,46.225.0,54.221.0,55.222.0,38.184.0,56.221.0"}
P.entries["quest:98021"] = {n="Journey to Sentinel Hill",s="Journey to Sentinel Hill leder Alliansens äventyrare till Westfalls oroliga jordbruksmarker, där de ska rapportera till utposten Sentinel Hill. Efter månader av obesvarade vädjanden till Stormwind om kungliga förstärkningar är de frustrerade lokala befälhavarna redo att genast sätta alla villiga resenärer i arbete.",h="Journey to Sentinel Hill leder Alliansens äventyrare till Westfalls oroliga jordbruksmarker, där de ska...",kw={"journey to sentinel hill","folkets milisstyrka","sentinel hill","spinkig alv","stormwind","westfall"},ang={["faction:Alliance"]="Westfall är ett alliansområde i desperat behov av stöd, men Stormwind har lämnat de lokala befälhavarna att vädja om förstärkningar och förlita sig på de frivilliga som anländer.",["race:NightElf"]="Gränsbefälhavaren vid Sentinel Hill kanske muttrar över att ha fått en ”spinkig alv” i stället för vältränat infanteri från Stormwind, men Sentinel Hill behöver all hjälp det kan få."},sec={{t="Ankomst till gränslandet",b="Journey to Sentinel Hill markerar en äventyrares ankomst till den hårt prövade regionen Westfall. Utposten Sentinel Hill är den främsta försvarsbastionen för de omgivande jordbruksmarkerna, men dess garnison har ständigt för få soldater och förbigås av det kungliga hovet. När resenärer anländer för att erbjuda hjälp slösar den lokala befälhavaren ingen tid på att fråga om deras härkomst, utan vill genast sätta alla villiga händer i arbete."},{t="Vädjanden till Stormwind",b="I månader har ledningen vid Sentinel Hill vädjat till Stormwind om militära förstärkningar för att skydda regionen mot annalkande hot. Rikets försummelse har tvingat de lokala befälhavarna att ta emot all hjälp som dyker upp, även om det innebär att hälsa en nyanländ äventyrare med en torr kommentar om att de väntade sig en armé men fick en spinkig alv i stället. I Westfall har tiggare inte råd att vara kräsna."}},faq={{q="Vad är Journey to Sentinel Hill?",a="Journey to Sentinel Hill är ett uppdrag för Alliansen som leder äventyrare till gränsområdet Westfall. Det introducerar nykomlingar för de lokala försvararna vid Sentinel Hill, som har vädjat om hjälp från Stormwind utan att få tillräckliga officiella förstärkningar.",al={"vad är journey to sentinel hill","uppdraget journey to sentinel hill","uppdraget sentinel hill"}},{q="Varför ber Sentinel Hill om hjälp?",a="Den militära ledningen vid Sentinel Hill har i månader bett Stormwind om förstärkningar för att hantera problemen som plågar Westfall. I stället för reguljära trupper måste den lokala ledningen förlita sig på de äventyrare som råkar dyka upp.",al={"vem ber stormwind om hjälp","sentinel hills garnison","varför sentinel hill behöver hjälp"}},{q="Varför nämner uppdragstexten en spinkig alv?",a="När du har slutfört resan säger befälhavaren att de har bett Stormwind om hjälp i månader, bara för att få en spinkig alv skickad till sig. Befälhavaren muttrar att tiggare inte kan vara kräsna och bestämmer sig snabbt för att genast sätta den nyanlända äventyraren i arbete.",al={"citat om spinkig alv","varför spinkig alv","sentinel hills kommentar om alven"}},{q="Varför har Stormwind inte skickat ordentliga förstärkningar?",a="Stormwinds kungliga regering är för närvarande upptagen och pressad, vilket gör att avlägsna områden som Westfall till stor del försummas. Sentinel Hill har vädjat upprepade gånger om hjälp under flera månader, men något officiellt kungligt stöd har inte kommit. De lokala befälhavarna måste därför förlita sig på frivilliga.",al={"varför hjälper stormwind inte westfall","stormwind försummar westfall","stormwinds hjälp till westfall"}},{q="Vad är Sentinel Hill?",a="Sentinel Hill är Folkets milisstyrkas centrala militärutpost och bastion i Westfall. Den utgör den främsta försvarslinjen mot laglösheten, Defias-banditerna och gnollerna som härjar bland regionens jordbruksmarker.",al={"var ligger sentinel hill","vad är sentinel hill","sentinel hills läge"}},{q="Vad händer när man kommer till Sentinel Hill?",a="När du har rapporterat in vid Sentinel Hill sätter de lokala försvararna genast dig i arbete. Äventyrare får i uppgift att hjälpa till att hantera de många hoten över Westfalls slätter och jordbruksmarker.",al={"vad man gör i westfall","nästa uppdrag i westfall","vad händer efter ankomsten till westfall"}}},fp="24,291,23.433.0,18.430.0,33.285.0,37.265.0,45.249.0,48.288.0,22.223.0,42.200.0"}
P.entries["quest:98024"] = {n="Journey to the Crossroads",s="Journey to the Crossroads leder nyanlända resenärer från det elementära planet till The Barrens karga savann. Äventyrare får i uppdrag att rapportera till Thork vid The Crossroads och hjälpa Hordens styrkor att kämpa mot den hårda gränsmarken. Det ger en nödvändig introduktion till de dödliga faror som väntar Horden i Kalimdor.",h="Journey to the Crossroads leder nyanlända resenärer från det elementära planet till The Barrens karga savann.",kw={"barrens","crossroads","elementära planet","horden","journey to the crossroads","the barrens","thork"},ang={["faction:Horde"]="Den här resan leder nyanlända mästare till att ta till vapen för Horden och sättsätter dem på prov i Kalimdors karga gränsland.",["race:Skyborne"]="Efter ankomsten till Azeroth från det elementära planet uppmanas resenärerna att inte underskatta dödliga konflikter och att bevisa sitt värde i Hordens tjänst."},sec={{t="En kallelse till gränslandet",b="Resenärer som anländer till Azeroth efter en färd från det elementära planet möts av en bister verklighet: dödliga konflikter kan verka små i jämförelse, men farorna som hotar Horden är högst verkliga. Tjänstgöring vid fronten ger en viktig prövning för den som vill bli mäktig och samtidigt hjälpa riket."},{t="Kalimdors vägskäl",b="För att påbörja sin tjänstgöring skickas äventyrare sydväst, till The Barrens vidsträckta, solstekta slätter. Där ligger The Crossroads, en viktig knutpunkt och utpost för Horden, vars stolta försvarare ständigt pressas av farorna runtomkring. Genom att rapportera direkt till Thork blir nykomlingarna en del av bosättningens försvar."}},faq={{q="Vem är Thork?",a="Thork är en framstående företrädare för Horden, stationerad vid The Crossroads i The Barrens. Han leder det lokala försvaret och skickar äventyrare för att bistå mot de många hot som riktas mot bosättningen och de omgivande områdena.",al={"vem är thork","ledare vid crossroads","var är thork"}},{q="Vad är The Crossroads?",a="The Crossroads är en central utpost för Horden och ett handelscentrum där flera stora leder möts i The Barrens. Den omges av fientligt djurliv, centaurstammar och quilboar-rövare, så försvararna behöver ständigt hjälp med att hålla viktiga försörjningsleder säkra.",al={"vad är crossroads","crossroads i barrens","varför bege sig till crossroads"}},{q="Var ligger The Barrens?",a="The Barrens är en vidsträckt, torr savann i centrala Kalimdor, sydväst om Durotar. Området utgör en viktig länk mellan Hordens territorier på kontinenten.",al={"var ligger barrens","barrens läge"}},{q="Varför nämner uppdraget det elementära planet?",a="Uppdraget nämner att resenären nyligen har anlänt från det elementära planet. Även om konflikter i andra världar kan verka storslagna är farorna som hotar de dödligas rike och Horden omedelbara och allvarliga.",al={"ankomst från det elementära planet","varför det elementära planet","resa från det elementära planet"}},{q="Vad är syftet med Journey to the Crossroads?",a="Uppdraget leder nykomlingar till att rapportera direkt till Thork vid The Crossroads. Där blir de en del av Hordens insatser vid fronten och får möjlighet att växa sig mäktiga genom hedervärd tjänstgöring.",al={"syftet med crossroads-uppdraget","varför skickas man till crossroads"}},{q="Vilka faror möter invånarna vid The Crossroads?",a="The Barrens utsätts ständigt för angrepp från inhemska rovdjur, kringströvande centaurer, quilboar-krigshorder och intrång från Alliansen. Varje utpost blir därför en omstridd bastion som behöver dugliga försvarare.",al={"vilka faror finns i barrens","hot i barrens"}}},fp="25,335,22.324.0,26.328.0,13.222.0,23.260.0,30.167.0,47.209.0,49.199.0,52.195.0"}
P.entries["quest:98025"] = {n="WANTED: Jai'vhanel",s="WANTED: Jai'vhanel är en alliansisk efterlysning som utfärdats av Auberdines byråd i Darkshore. Efterlysningen kräver att Jai'vhanel, en vansinnig svart uggla känd som ”Swordfeather”, dödas. Hon har börjat överfalla resenärer på vägen nära Auberdine. Äventyrare måste jaga varelsen nära ruinerna av Ameth'Aran och ta med bevis på hennes död till Sentinel Glynda Nal'Shea.",h="WANTED: Jai'vhanel är en alliansisk efterlysning som utfärdats av Auberdines byråd i Darkshore.",kw={"ameth'aran","auberdine","svart uggla","darkshore","glynda nal'shea","jai'vhanel","swordfeather","wanted: jai'vhanel"},ang={["class:Druid"]="Nattalvernas druider håller noga uppsikt över Darkshores djurliv. Därför är den plötsliga vansinnigheten och aggressiviteten hos en ädel fågel som Jai'vhanel en oroande ekologisk störning.",["class:Hunter"]="Denna våldsamma, kolsvarta rovfågel kallas Swordfeather. Hon stryker omkring aggressivt nära bergen i Darkshore, där hennes jaktvanor har blivit oförutsägbart dödliga.",["faction:Alliance"]="Auberdines byråd förlitar sig på äventyrare från Alliansen och nattalvernas väktare för att hålla Darkshores viktiga kustvägar säkra från vansinniga rovdjur."},sec={{t="Ett hot på vägen",b="En anslagen efterlysning från Auberdines byråd varnar resenärer längs Darkshores kustvägar för ett farligt hot. En välkänd uggla i trakten vid namn Jai'vhanel, med smeknamnet ”Swordfeather”, har plötsligt blivit vansinnig. I stället för att hålla sig till den täta vildmarken har hon börjat överfalla resenärer och kurirer nära Auberdine. En vanlig skogspredator har därmed blivit en allvarlig fara för bosättningen."},{t="Rådets belöning",b="För att göra vägarna säkra har rådet utlyst en belöning för Jai'vhanels huvud. Jägare ska spåra den svartfjädrade rovfågeln till hennes jaktmarker norr om ruinerna av Ameth'Aran, vid bergsfoten. För att bekräfta dödsfallet och få sin belöning måste jägarna ta med en av hennes karaktäristiska kolsvarta fjädrar till Sentinel Glynda Nal'Shea i Auberdine."}},faq={{q="Vem är Jai'vhanel?",a="Jai'vhanel, även känd under namnet ”Swordfeather”, är en stor uggla med kolsvarta fjädrar. Hon är vanligtvis ett vilt djur från Darkshores skogar, men har blivit vansinnig och nu är hon aggressivt fientlig mot resenärer.",al={"vem är jai'vhanel","vad är jai'vhanel","vem är swordfeather"}},{q="Varför har Jai'vhanel en belöning utfäst på sig?",a="Auberdines byråd utfäste en formell belöning för Jai'vhanel eftersom hon har blivit vansinnig och börjat angripa resenärer på huvudvägen nära Auberdine. Hon utgör en allvarlig fara för den lokala trafiken.",al={"varför döda jai'vhanel","varför har jai'vhanel en belöning utfäst på sig","varför angrips ugglan"}},{q="Var finns Jai'vhanel?",a="Jai'vhanel sågs senast norr om de forntida ruinerna av Ameth'Aran i Darkshore, där hon strök omkring vid foten av de östra bergen.",al={"var finns jai'vhanel","jai'vhanels plats","var hittar man swordfeather"}},{q="Vem utfäste belöningen för Jai'vhanel?",a="Belöningen utfästes av Auberdines byråd, som ansvarar för den civila säkerheten och invånarnas välfärd i kustbosättningen och längs de omgivande vägarna.",al={"vem utfäste belöningen","vem vill se jai'vhanel död"}},{q="Vem hämtar ut belöningen för Jai'vhanel?",a="Prisjägare måste visa upp en av Jai'vhanels kolsvarta fjädrar som bevis på hennes död för Sentinel Glynda Nal'Shea, som finns i staden Auberdine.",al={"vem tar emot dödsbeviset","var lämnar man in jai'vhanels fjäder","glynda nal'sheas belöning"}},{q="Vilket bevis krävs för att få belöningen?",a="Den som vill få rådets belöning måste hämta och visa upp en av Jai'vhanels karaktäristiska kolsvarta fjädrar som bevis på att den vansinniga fågeln har dödats.",al={"vad är dödsbeviset för jai'vhanel","vilket föremål bevisar att jai'vhanel är död"}}},fp="18,379,20.436.0,20.388.0,18.249.0,36.208.0,30.132.0,36.150.0,39.154.0,41.148.0"}
P.entries["quest:98042"] = {n="It's All Fun and Games Until...",s="It's All Fun and Games Until... är ett uppdrag om en djupt oroande upptäckt som förs till Thundris. När Thundris känner igen det omisskännliga tecknet på en uråldrig ondska ser han till att reliken genast skickas till Darnassus för vidare undersökning.",h="It's All Fun and Games Until...",kw={"uråldrig ondska","ande'thoras-ethil","darnassus","tecknet på en uråldrig ondska","night elf","thundris"},ang={["faction:Alliance"]="Alliansens äventyrare som för oroande fynd till nattalvernas myndigheter hjälper till att se till att farliga reliker undersöks och tas om hand av lärda från Darnassus.",["race:NightElf"]="Undersökningen berör nattalvernas vaksamhet mot uråldrig korruption och leder till att Darnassus genast ingriper."},sec={{t="En oroande rapport",b="En oroande upptäckt får en äventyrare att söka upp Thundris för råd i en olustig fråga. När Thundris hör äventyrarens rapport och undersöker det som lagts fram sjunker han in i tyst begrundan och känner igen mörka tecken som inte kan avfärdas lättvindigt."},{t="Den uråldriga ondskans tecken",b="När Thundris undersöker saken närmare urskiljer han det omisskännliga tecknet på en uråldrig ondska som klamrar sig fast vid upptäckten. Han inser att faran sträcker sig långt bortom en lokal incident och beslutar att genast skicka reliken till Darnassus, där huvudstadens lärda och präster får ta hand om den för grundlig undersökning och inneslutning."}},faq={{q="Vilka är inblandade i att slutföra uppdraget?",a="Uppdraget lämnas in till och avslutas hos Thundris. Han lyssnar på den bekymrade äventyraren och undersöker föremålet eller bevismaterialet som visas upp innan han förbereder det för transport.",al={"vem lämnar in it's all fun and games until","thundris uppdrag","vem lämnar in its all fun and games until"}},{q="Varför skickas föremålet till Darnassus?",a="Thundris upptäcker att artefakten eller fyndet bär tecknet på en uråldrig ondska. Han säger att han genast ska se till att det förs till Darnassus för vidare undersökning, och säger inget mer än så.",al={"varför skicka till darnassus","undersökning i darnassus","uråldrig ondska darnassus"}},{q="Vad är den uråldriga ondska som Thundris nämner?",a="Thundris upptäcker att fyndet bär tecknet på en uråldrig ondska, men detaljer om dess exakta ursprung hålls hemliga i väntan på närmare undersökning i nattalvernas huvudstad.",al={"vad är den uråldriga ondskan","betydelsen av tecknet på uråldrig ondska"}},{q="Vad betyder ”Ande'thoras-ethil”?",a="”Ande'thoras-ethil” är en darnassisk fras som Thundris säger när han avslutar samtalet med dig, efter att ha sagt att fyndet ska föras till Darnassus.",al={"betydelsen av ande'thoras-ethil","ande'thoras-ethil nattalvsfras","darnassisk avskedsfras thundris"}},{q="Vad händer efter att uppdraget har slutförts?",a="Efter avslöjandet om den uråldriga korruptionen förbereder Thundris den oroande reliken för omedelbar transport till Darnassus, så att lärda i huvudstaden kan undersöka den.",al={"vad händer efter it's all fun and games until","nästa uppdrag efter it's all fun and games until","uppföljning till darnassus"}},{q="Vilken fraktion hanterar den här undersökningen?",a="Ärendet hanteras av Darnassus ledare och nattalver som Thundris, och kretsar kring hot som förs inför nattalvernas myndigheter.",al={"är it's all fun and games until endast för alliansen","vem kan göra it's all fun and games until"}}},fp="31,248,18.272.0,24.322.1,41.170.0,42.196.0,48.187.0,35.146.0,40.170.0,41.160.0"}
P.entries["quest:98046"] = {n="Crown of the Earth",s="Crown of the Earth är ett uppdrag i Darnassus som börjar när Arch Druid Fandral Staghelm avbryter en misslyckad besvärjelse med en vattenflaska. Den frustrerade Arch Druid avfärdar dig och ger dig i uppgift att lämna den tömda behållaren till Priestess Lariia vid Temple of the Moon för att kastas bort. Men när prästinnan undersöker flaskan märker hon att det finns lite vatten kvar, vilket väcker tvivel om varför ritualen egentligen misslyckades.",h="Crown of the Earth är ett uppdrag i Darnassus som börjar när Arch Druid Fandral Staghelm avbryter en...",kw={"cenarion circle","crown of the earth","darnassus","drained vessel","elune","fandral staghelm","lariia","malfurion","temple of the moon"},ang={["class:Druid"]="Fandral tilltalar dig uttryckligen som en meddruid och bemöter ritualens misslyckande med kort tålamod innan han avfärdar dig.",["faction:Alliance"]="Uppdraget visar de lågmälda ledningsspänningarna i Darnassus, Alliansens främsta huvudstad på Kalimdor, medan Malfurion Stormrage är borta.",["race:NightElf"]="Ärendet visar den vardagliga pressen i Darnassus och ställer Fandral Staghelms lättretliga auktoritet mot The Sisterhood of Elunes tålmodiga hängivenhet i Temple of the Moon."},sec={{t="Fandrals frustration",b="I Darnassus bär Arch Druid Fandral Staghelm ansvaret för att vägleda nattalverna medan Malfurion Stormrage är borta. I sin jakt på svar försöker Fandral utföra en besvärjelse med heligt vatten i en flaska. När ritualen till synes inte ger något resultat tappar Arch Druid humöret. Övertygad om att vattnet är värdelöst avfärdar han dig med hårda ord och säger åt dig att ta den tömda behållaren söderut till Temple of the Moon, så att prästinnorna kan göra sig av med den."},{t="De sista dropparna",b="När du kommer fram till Temple of the Moon erbjuder Priestess Lariia ett mildare perspektiv och ber dig att ha överseende med Fandrals hårda sätt med tanke på den tunga börda han bär. När hon undersöker flaskan upptäcker hon dock något som Arch Druid missade i sin brådska: flera vattendroppar finns fortfarande kvar därinne. Resterna gör det mycket möjligt att Fandrals ritual inte misslyckades på grund av bristfällig magi, utan för att behållaren inte hade tömts ordentligt."}},faq={{q="Vem ger uppdraget Crown of the Earth?",a="Uppdraget ges av Arch Druid Fandral Staghelm i Darnassus. Fandral har för tillfället hand om Cenarion Circle medan Malfurion Stormrage är borta. Han ger dig uppgiften i ett plötsligt vredesutbrott efter att en besvärjelse med heligt vatten inte ger de svar han sökte.",al={"vem startar crown of the earth","crown of the earth uppdragsgivare","fandral uppdrag"}},{q="Var ska du lämna Drained Vessel?",a="Du lämnar Drained Vessel till Priestess Lariia vid Temple of the Moon i södra Darnassus. Fandral säger åt dig att överlämna den så att Elunes prästinnor kan göra sig av med den, eftersom han antar att den förbrukade behållaren inte längre är till någon nytta.",al={"var ska drained vessel lämnas","lämna in drained vessel","var finns lariia"}},{q="Varför är Fandral Staghelm så frustrerad?",a="Arch Druid Fandral Staghelm är hårt pressad av ansvaret att leda nattalverna och Cenarion Circle medan Malfurion Stormrage är borta. När hans magiska besvärjelse inte ger något resultat får hans irritation och stolthet honom att snäsa åt dig och snabbt avfärda dig i stället för att undersöka misslyckandet närmare.",al={"varför är fandral arg","fandrals attityd","varför är fandral otålig"}},{q="Varför misslyckades Fandrals besvärjelse?",a="Fandral Staghelm antar att vattnet saknade all användbar kraft, men Priestess Lariia upptäcker en viktig detalj när hon tar emot behållaren. Flera vattendroppar sitter fortfarande kvar på insidan, vilket tyder på att besvärjelsen kan ha misslyckats helt enkelt för att behållaren inte tömdes helt under ritualen.",al={"varför misslyckades besvärjelsen","fungerade fandrals ritual","misslyckad besvärjelse"}},{q="Var är Malfurion under det här uppdraget?",a="Malfurion Stormrage är för tillfället borta från Darnassus, så Arch Druid Fandral Staghelm får leda Cenarion Circle och vägleda nattalverna. Frånvaron lägger en tung börda på Fandral och bidrar till hans häftiga humör och otålighet när motgångar uppstår.",al={"var är malfurion","varför är malfurion borta","malfurions status"}},{q="Vem är Priestess Lariia?",a="Priestess Lariia är en nattalv som tjänar Elune och håller till i Temple of the Moon i Darnassus. Hon tar emot behållaren från dig, visar förståelse för Fandrals stora ansvar och upptäcker klokt nog att det fortfarande finns vatten kvar i den.",al={"vem är lariia","priestess lariias bakgrund","lariia temple of the moon"}}},fp="18,440,21.512.0,19.479.1,39.284.0,37.232.0,38.307.0,35.304.0,37.287.0,24.283.0"}
P.entries["quest:98065"] = {n="Crown of the Earth",s="Crown of the Earth är ett uppdrag i Darnassus där äventyrare överlämnar renade Moonwell Remnants till översteprästinnan Tyrande Whisperwind. Mötet äger rum i Temple of the Moon och visar hur heliga Elunes vatten är och hur de politiska spänningarna mellan Tyrande och Arch Druid Fandral Staghelm växer.",h="Crown of the Earth är ett uppdrag i Darnassus där äventyrare överlämnar renade Moonwell Remnants till...",kw={"crown of the earth","darnassus","elune","fandral staghelm","malfurion","moonwell remnants","temple of the moon","tyrande whisperwind"},ang={["class:Druid"]="Tyrandes skarpa ord om Arch Druid Fandral Staghelm understryker den växande friktionen inom Cenarion Circle när Malfurion är borta.",["class:Priest"]="Att tjäna översteprästinnan Tyrande Whisperwind stärker förståelsen för den viktiga roll Elunes prästerskap spelar i att vägleda och styra nattalvernas samhälle.",["faction:Alliance"]="Ett möte med Darnassus ledare ger en inblick i de interna politiska spänningar som präglar en av Alliansens viktigaste huvudstäder.",["race:NightElf"]="Att överlämna heligt månbrunnsvatten visar tydligt kaldoreiernas delade ledarskap, klämt mellan Tyrandes prästerskap och Fandrals druider."},sec={{t="Möte med översteprästinnan",b="När de har samlat in de heliga Moonwell Remnants får äventyrarna i uppdrag att hälla det välsignade vattnet i ett ceremoniellt kärl och överlämna det direkt till Tyrande Whisperwind. Elunes översteprästinna håller hov högt uppe i Temple of the Moon i Darnassus, vakar över staden och skänker sin gudinnas ljus åt alla som kommer dit. Att anförtro henne sådant heligt vatten ses som en ära och en handling av hängivenhet till Elune."},{t="Spänningar i ledarskapet",b="När Tyrande tar emot resterna uttrycker hon djup tacksamhet för att det välsignade vattnet har räddats, men tankarna vänder sig snart till de politiska spänningar som håller Darnassus i sitt grepp. I Malfurion Stormrages frånvaro har Arch Druid Fandral Staghelm tagit kommandot över druidernas angelägenheter, men Tyrande gör det fullständigt klart att ansvaret för att styra kaldorei-folket enbart vilar på henne. Hon uppmanar till respekt för Staghelms ämbete, men samtalet blottlägger den skarpa friktionen mellan The Sisterhood of Elune och Cenarion Circle."}},faq={{q="Vad är Crown of the Earth?",a="Crown of the Earth är ett uppdrag i Darnassus där en äventyrare bär ett ceremoniellt kärl med Moonwell Remnants till översteprästinnan Tyrande Whisperwind i Temple of the Moon. Det markerar ett ögonblick av direkt kontakt med nattalvernas högsta ledare.",al={"vad är crown of the earth","crown of the earth-uppdraget","uppdraget crown of the earth"}},{q="Vem är Tyrande Whisperwind?",a="Tyrande Whisperwind är Elunes översteprästinna och nattalvernas politiska ledare. Hon styr Darnassus från den övre nivån i Temple of the Moon och bär ansvaret för att vägleda sitt folk i oroliga tider.",al={"vem är tyrande whisperwind","var är tyrande","översteprästinnan tyrande"}},{q="Varför förs Moonwell Remnants till Tyrande?",a="Moonwell Remnants består av heligt vatten som välsignats av Elune. Eftersom vattnet är heligt hälls det i ett ceremoniellt kärl och förs till Tyrande, så att hon kan ta emot och skydda det å gudinnans vägnar.",al={"varför föra moonwell remnants till tyrande","vad är moonwell remnants","heligt vatten darnassus"}},{q="Vad är tvisten mellan Tyrande och Fandral Staghelm?",a="Medan Malfurion Stormrage är borta leder Arch Druid Fandral Staghelm druiderna, men Tyrande håller bestämt fast vid att ansvaret för att styra Darnassus och leda kaldorei-folket fortfarande enbart är hennes. Hon vägrar låta druidernas makt överskugga Elunes prästerskap.",al={"spänningar mellan tyrande och fandral","varför ogillar tyrande staghelm","fandral mot tyrande"}},{q="Var är Malfurion under det här uppdraget?",a="Malfurion Stormrage är för tillfället borta från Darnassus. Det lämnar ett tomrum i druidernas ledarskap som Arch Druid Fandral Staghelm har klivit in för att fylla, vilket ökar de politiska spänningarna med Tyrande.",al={"var är malfurion","vad hände med malfurion","malfurions frånvaro"}},{q="Var ligger Temple of the Moon?",a="Temple of the Moon ligger i hjärtat av Darnassus. Det är The Sisterhood of Elunes främsta helgedom, och Tyrande håller hov på den övre nivån, direkt ovanför helgedomens stora sal.",al={"temple of the moon plats","var ligger temple of the moon","var hittar man tyrande"}}},fp="18,325,32.433.0,22.494.1,27.258.0,27.229.0,49.219.0,57.257.0,37.201.0,32.214.0"}
P.entries["quest:98067"] = {n="Eyes of the Sentinels",s="Eyes of the Sentinels är ett uppdrag i Darnassus där spelare hjälper Sentinel Dalia Sunblade att placera ut magiska spaningsugglor vid viktiga poster i nattalvernas huvudstad. När oron växer i Teldrassil stärker övervakningen från luften stadens försvar och ger Sentinels tid att be till Elune.",h="Eyes of the Sentinels är ett uppdrag i Darnassus där spelare hjälper Sentinel Dalia Sunblade att placera ut...",kw={"cenarion hold","craftsman's terrace","dalia sunblade","darnassus","elune","eyes of the sentinels","feathermoon","sentinelugglor","teldrassil","temple of the moon"},ang={["class:Hunter"]="Spaningsugglorna speglar nattalvernas klassiska spaning, där tränade djur och himmelska fågelväktare blir en naturlig förlängning av en jägarinnas sinnen.",["class:Priest"]="Sentinels betonar att vapen inte ensamma kan skydda kaldorei. Regelbunden bön och Elunes andliga gåvor är avgörande för deras väktarskap.",["faction:Alliance"]="När Darnassus hålls säkert skyddas nattalvernas huvudstad och Alliansens främsta fäste i norra Kalimdor stärks.",["race:NightElf"]="Sentinels är nattalvernas traditionella stående armé och folkets väktare. De förenar stridskonst med Elunes gudomliga välsignelser och vaksamma blick."},sec={{t="Hängivenhet och försvar",b="I Temple of the Moons heliga fristad vakar Sentinel Dalia Sunblade över Darnassus. General Shandris Feathermoon har befallt att varje krigare ska förena stridskonst med andlig hängivenhet, och därför ordnar Dalia så att vaksamma sentinelugglor placeras ut på viktiga platser i staden. När Sentinel tar över hennes dagliga plikter får hon värdefulla stunder till bön och eftertanke inför mångudinnan, samtidigt som kaldorei-huvudstaden förblir väl bevakad."},{t="Vaka över Darnassus",b="Oro ligger i luften över Teldrassil, och Sentinels skärper därför sin vaksamhet. För att skydda sig mot infiltration och oroligheter placeras sentinelugglor vid viktiga knutpunkter: i djupen under Cenarion Hold i norr, vid den livliga banken på torget, på värdshuset i Craftsman's Terrace och vid stadens huvudportar. Med hjälp av stadsvakterna blir dessa bevingade väktare tysta beskyddare som vakar över alla som går på det stora trädets gator."}},faq={{q="Vad är Eyes of the Sentinels?",a="Eyes of the Sentinels är ett uppdrag i Darnassus där en äventyrare hjälper Sentinel Dalia Sunblade att placera ut sentinelugglor på viktiga platser i staden och hålla vakt mot hot som närmar sig.",al={"uppdraget eyes of the sentinels","vad är eyes of the sentinels","översikt över eyes of the sentinels"}},{q="Vem är Sentinel Dalia Sunblade?",a="Sentinel Dalia Sunblade är en kaldorei-väktare stationerad i Temple of the Moon i Darnassus. Hon övervakar stadens försvarsrutiner och ser till att vaksamma ugglor bevakar stadens viktigaste stråk.",al={"vem är dalia sunblade","dalia sunblades bakgrund","sentinel dalia sunblade"}},{q="Varför placeras sentinelugglor ut runt Darnassus?",a="Sentinelugglorna fungerar som vaksamma spanare från luften och gudomliga spejare som Elune har skänkt. De låter Sentinels övervaka viktiga samlingsplatser och trånga passager i Darnassus.",al={"varför placera ut sentinelugglor","vad gör sentinelugglor","sentinelugglornas syfte"}},{q="Var placeras sentinelugglorna?",a="Sentinelugglorna placeras vid ingången till djupen under Cenarion Hold i norr, vid Darnassus Bank mitt i staden, på värdshuset i Craftsman's Terrace och vid stadsportarna.",al={"platser för ugglorna","var placeras ugglorna","eyes of the sentinels platser"}},{q="Varför är Sentinels på högsta beredskap i Teldrassil?",a="Sentinel Dalia Sunblade säger att något känns fel i världsträdet Teldrassil. Därför ökar Sentinels övervakningen och håller ständig beredskap mot osedda faror.",al={"varför är sentinels oroliga","vad är fel med teldrassil","något känns fel i teldrassil"}},{q="Vilken roll har General Feathermoon i Sentinels dagliga plikter?",a="General Shandris Feathermoon leder Sentinels och ser till att hennes jägarinnor förenar sina militära plikter med daglig hängivenhet och bön till gudinnan Elune.",al={"general feathermoons roll","shandris feathermoon och sentinels","feathermoons böneregel"}}},fp="21,324,20.489.0,20.490.0,30.201.0,31.195.0,52.188.0,35.188.0,50.197.0,71.175.0"}
P.entries["quest:98071"] = {n="Brewer's Trade",s="En byteshandel har ordnats med bryggsläkten i Dun Garok, som saknar familjen Fallrooks vingårdar lika mycket som någon annan. En låda Fallrook Varietal färdas till deras fäste i sydöstra Hillsbrad Foothills, och en säck av deras Homebrew Hops kommer tillbaka.",h="En byteshandel har ordnats med bryggsläkten i Dun Garok, som saknar familjen Fallrooks vingårdar lika mycket...",kw={"bryggsläkt","dun garok","fallrook","fallrook varietal","hillsbrad","homebrew hops","humle","vin"},sec={{t="Smaken av det förflutna",b="De flesta av de bästa årgångarna av Fallrook-vin på flaska dracks upp för länge sedan, men lådor med Fallrook Varietal står fortfarande i källarna. Bryggsläkten i Dun Garok saknar också familjen Fallrooks vingårdar, och en byteshandel har ordnats med dem."},{t="Bytet vid Dun Garok",b="Lådan färdas sydost till Dun Garok, där den lämnas till bryggsläkten vid eldstaden där de samlas, nere vid foten av deras fäste. I utbyte tar du med dig en säck av deras Homebrew Hops tillbaka."}},faq={{q="Vad byts i den här byteshandeln?",a="En låda Fallrook Varietal från källarna går till bryggsläkten i Dun Garok i utbyte mot en säck av deras Homebrew Hops.",al={"vad ska jag leverera","föremål i bryggarens byte","fallrook-vin"}},{q="Var i Dun Garok ska vinet lämnas?",a="Du lämnar det till bryggsläkten vid eldstaden där de samlas, nere vid foten av deras fäste.",al={"var är eldstaden","leveransplats i dun garok","var ska vinet lämnas"}},{q="Var ligger Dun Garok?",a="Dun Garok ligger i sydöstra Hillsbrad Foothills.",al={"dun garoks läge","var ligger dun garok"}},{q="Vilka var familjen Fallrook?",a="Familjen Fallrook hade vingårdar som man saknar. De flesta av deras bästa årgångar på flaska dracks upp för länge sedan, men lådor med vinet finns kvar i källarna.",al={"familjen fallrook","fallrooks vingårdar"}}},fp="14,253,19.243.0,25.195.0,38.127.0,44.102.0,27.55.0,23.164.0"}
P.entries["quest:981"] = {n="The Tower of Althalaxx",s="Det här uppdraget avslutar triumferande fälttåget mot Cult of the Dark Strand vid Tower of Althalaxx. Efter att ha utplånat kultens ledarskap i Darkshores olycksbådande ruiner för en äventyrare budskap söderut till Delgren the Purifier i Ashenvale. Det är en avgörande seger för Alliansen i kampen mot demonisk korruption vid de forntida nattalvergränserna.",h="Det här uppdraget avslutar triumferande fälttåget mot Cult of the Dark Strand vid Tower of Althalaxx.",kw={"althalaxx","ashenvale","balthule","kult","dark strand","darkshore","delgren","maestra's post"},ang={["class:Paladin"]="Att rapportera till Delgren the Purifier har särskild betydelse för paladiner, som delar hans heliga uppdrag att rena världen från demonisk korruption och onda kulter.",["faction:Alliance"]="När kulten utplånas skyddas landsvägen mellan Darkshore och Ashenvale, så att Alliansens spejare och resenärer kan färdas säkert från demoniska bakhåll.",["race:NightElf"]="För nattalverna innebär reningen av Tower of Althalaxx att en vidrig plåga försvinner från de forntida Highborne-ruinerna som ligger utspridda i deras heliga kustskogar."},sec={{t="Ett avvärjt hot",b="Tower of Althalaxx stod i veckor som ett varigt sår i norra Darkshore, ockuperat av den fanatiska Cult of the Dark Strand och dess skuggmästare. Genom ihärdig spårning, underrättelsearbete och våldsamma skärmytslingar monterades kultens verksamhet systematiskt ned. När dess trollkarlar dödats och de mörka ritualerna brutits har det omedelbara hotet från demonisk infiltration i Darkshore äntligen avvärjts."},{t="Rapportera till Maestra's Post",b="Efter kultledarens död skickar Balthule Shadowstrike segraren söderut till Maestra's Post bland Ashenvales trädkronor. Där väntar Delgren the Purifier, en hängiven krigare i det Heliga ljusets tjänst som ledde korståget mot Althalaxxs onda invånare. Nyheten om kultens fall ger områdets försvarare sinnesro och ger hjälten Delgrens bestående välsignelse och välförtjänta tacksamhet."}},faq={{q="Vad är målet med uppdraget?",a="Det här uppdraget är den sista inlämningen i den långa berättelsen om Tower of Althalaxx. Du behöver bara ta dig från tornets närhet till Maestra's Post i Ashenvale och rapportera din avgörande seger till Delgren the Purifier.",al={"målet med tower of althalaxx","lämna in tower of althalaxx","var lämnar man in uppdrag 981"}},{q="Vem är Delgren the Purifier?",a="Delgren the Purifier är en Alliansens förkämpe stationerad vid Maestra's Post i norra Ashenvale. Han brukar det Heliga ljuset och är hängiven åt att rena världen från korruption och bekämpa demoniska hot som Cult of the Dark Strand i norra Kalimdor.",al={"vem är delgren","delgrens bakgrund","delgren the purifier"}},{q="Vem är Balthule Shadowstrike?",a="Balthule Shadowstrike är en agent för Alliansen som håller till nära Tower of Althalaxx i Darkshore. Han samarbetar nära med Delgren, håller uppsikt över kultens rörelser och vägleder äventyrare när de monterar ned den mörka sammansvärjningen inifrån.",al={"balthule","balthules bakgrund","vem är balthule shadowstrike"}},{q="Vad gjorde Cult of the Dark Strand i tornet?",a="Cult of the Dark Strand ockuperade de forntida ruinerna av Tower of Althalaxx för att utföra mörka ritualer, åkalla demoniska väsen och utöka sitt olycksbådande inflytande över Darkshores kustland.",al={"cult of the dark strand","vad hände vid althalaxx","tower of althalaxx bakgrund"}},{q="Var ligger Maestra's Post?",a="Maestra's Post är en utpost för Alliansen i nordvästra Ashenvale, strax söder om gränsövergången från Darkshore längs huvudvägen.",al={"maestra's post plats","var ligger maestra's post","var finns delgren"}},{q="Är Cult of the Dark Strand helt utplånad?",a="Ledarskapet vid Tower of Althalaxx har avrättats och den främsta ritualen brutits, men kringströvande kultister och rester finns fortfarande kvar i avlägsna delar av Kalimdor. Deras organiserade hot i Darkshore har dock krossats.",al={"är kulten borta","är dark strand utplånad","dödade vi kulten"}}},fx={b456cfd7={q="Varför vill Balthule Shadowstrike att detta görs?",a="Nu när Cult of the Dark Strand har slagits sönder och dess ledarskap krossats vill Balthule att du förmedlar segerbudskapet till Delgren the Purifier. Delgren inledde kampanjen mot kultisterna som höll till i tornet. Balthule anser att dina insatser förtjänar erkännande och den belöning paladinen lovade.",al={"varför skicka mig tillbaka till delgren","balthules motiv","varför rapportera till delgren"}}},fp="22,202,16.358.0,24.388.0,31.201.0,28.248.0,29.205.0,56.189.0,32.129.0,52.228.0"}
P.entries["quest:98155"] = {n="Pristine Pesterhide Pelts",s="Pristine Pesterhide Pelts är ett uppdrag på uppdrag av Kristy Grant, en resenär som söker efter Pesterhide-hyenornas lysande pälsar i Thousand Needles. Eftersom Kristy själv saknar stridsvana förlitar hon sig på skickliga äventyrare som jagar odjuren och tar till vara på deras skinn. Hon vill skicka de unika skinnen över havet till sina systrar i Stormwind, där de kan förvandlas till fina kläder och föremål.",h="Pristine Pesterhide Pelts är ett uppdrag på uppdrag av Kristy Grant, en resenär som söker efter...",kw={"päls","jakt","hyena","kristy grant","skinn","pesterhide","stormwind","thousand needles"},ang={["faction:Alliance"]="Uppdraget handlar om en resenär från Stormwind som vill förse sin hantverkskunniga familj i huvudstaden. Det visar hur invånare i Alliansen färdas djupt in i Kalimdors gränsland för att hitta exotiska material.",["profession:Tailoring"]="Hantverkare som arbetar med tyg och dekorativa pälsar kan uppskatta Kristys systrars ambition att förvandla vilda skinn från Kalimdor till förfinade kläder.",["race:Human"]="Kristy Grant förkroppsligar Stormwind-människornas företagsamma anda när de färdas långt över havet och håller nära kontakt med släktingar i kungariket."},sec={{t="En systers ambition",b="Långt från Stormwinds livliga kullerstensgator färdas Kristy Grant genom den torra, solstekta ravinen i Thousand Needles. När hon betraktar det lokala djurlivet slås hon av Pesterhide-hyenornas pälsars intensiva färg och fina kvalitet. Hon inser att sådana särpräglade skinn är så gott som okända i Eastern Kingdoms och föreställer sig hur hon skickar en last hem till sina systrar. För henne är skinnen inte bara en bit av Kalimdors gränsland, utan också råmaterial som familjens skickliga händer i kungariket kan förvandla till något alldeles enastående."},{t="Jägare på saltslätterna och i ravinerna",b="Kristy Grant har sinne för hantverk och handel, men är ingen krigare och saknar stridsvana för att själv möta ravinens vildsinta rovdjur. Pesterhide-hyenorna är våldsamma asätare som jagar i flock och strövar över de dammiga vidderna nedanför de höga platåbergen. Att samla in felfria skinn är därför farligt för en ensam resenär. För att få tag på fem oskadade skinn utan att riskera livet tar Kristy hjälp av erfarna äventyrare som färdas genom Needle. Uppdraget kräver att de ger sig ut i vildmarken, besegrar de revirhävdande odjuren och varsamt samlar in skinnen som hennes familj behöver för sitt hantverk där hemma."}},faq={{q="Vem är Kristy Grant?",a="Kristy Grant är en resenär från kungariket Stormwind som just nu färdas genom Kalimdor. Till skillnad från de härdade soldater och legosoldater som tar sig genom Thousand Needles medger hon att hon själv saknar stridsvana. I stället förlitar hon sig på skarp iakttagelseförmåga och sinne för värdefulla hantverksmaterial. Hon anlitar skickliga äventyrare för att samla in varor som hyenaskinn åt henne.",al={"kristy grant bakgrund","vem ger pristine pesterhide pelts","vem är kristy grant"}},{q="Vad är Pesterhide-hyenor?",a="Pesterhide-hyenor är vilda rovdjur av hundsläktet som hör hemma på de torra ravinbottnarna och vidderna i Thousand Needles. De strövar genom den ogästvänliga terrängen och jagar och letar efter as i flock. Förutom sin vildsinta natur är de kända för sin lysande, vackert färgade päls, som sticker ut mot öknens klippor och fångar resande skräddares och pälsarbetares blickar.",al={"pesterhide-hyena","hyenor i thousand needles","vad är pesterhides"}},{q="Varför vill Kristy Grant ha skinnen?",a="Kristy Grant vill samla in felfria hyenaskinn och skicka dem över havet till sina systrar i kungariket Stormwind. Hon är mycket imponerad av pälsarnas lysande färg och tror att hennes systrar har hantverksskickligheten som krävs för att väva eller sy fantastiska färdiga produkter av de exotiska skinnen.",al={"varför samla pesterhide-skinn","vad används pesterhide-skinn till","vad gör kristy med skinnen"}},{q="Vart tar skinnen vägen?",a="Skinnen som samlas in i Thousand Needles ska till Eastern Kingdoms, närmare bestämt stadsriket Stormwind. Kristy tänker frakta skinnen hem över Great Sea, så att hennes systrar kan arbeta med exotiska material som är nästan omöjliga att få tag på i de välbekanta skogarna i Elwynn eller Redridge.",al={"vart skickas skinnen","skinn till stormwind","vem får hyenaskinnen"}},{q="Varför kan inte Kristy jaga hyenorna själv?",a="Kristy Grant medger öppet att hon helt saknar stridsvana. De vilda djuren i Thousand Needles är aggressiva och farliga att möta, särskilt för en obeväpnad hantverkare eller resenär. I stället för att riskera skada eller död bland hyenornas kringströvande flockar anlitar hon skickliga vandrare för att jaga djuren säkert.",al={"varför kan kristy inte slåss","kristy grant stridsvana","varför behöver kristy hjälp"}},{q="Vad gör skinnen felfria?",a="Eftersom skinnen är avsedda för fint hantverk och modekreationer av Kristys systrar i Stormwind duger inte vanliga eller sönderrivna pälsar. Endast oskadade, felfria skinn bevarar den livfulla färgen och strukturen som krävs för att tillverka kläder av hög kvalitet. Därför måste jägarna vara försiktiga och bara ta till vara på de bästa skinnen från odjuren.",al={"vad betyder felfria skinn","varför felfria skinn","kvaliteten på pristine pesterhide-pälsar"}}},fp="25,416,19.626.0,37.648.0,20.388.0,27.373.0,37.309.0,26.326.0,41.329.0,32.339.0"}
P.entries["quest:98190"] = {n="A Friend of the Family",s="A Friend of the Family är ett brådskande kuriruppdrag från Menethil Harbor i Wetlands. Av rädsla för lokala hot som Dragonmaw-orcherna anförtror hamnens myndigheter en äventyrare att leverera den ovärderliga Menethil Statuette direkt till Highlord Bolvar Fordragon i Stormwind Keep.",h="A Friend of the Family är ett brådskande kuriruppdrag från Menethil Harbor i Wetlands.",kw={"bolvar","dragonmaw","fordragon","hamn","menethil","statyett","stormwind","terenas","wetlands"},ang={["class:Paladin"]="Namnet Menethil för tankarna till den välgörare som grundade Silver Hand-riddarna. Därför är det en högtidlig plikt för varje helig krigare att bevara reliken.",["faction:Alliance"]="Att leverera reliken hedrar den historiska nordliga alliansen och håller en ovärderlig symbol borta från klanen Dragonmaws klor.",["race:Human"]="För människor bevarar skyddet av ett föremål från Menethil-dynastin det stolta och tragiska minnet av det fallna Lordaeron och stärker Stormwinds plikt som det sista stora mänskliga kungariket."},sec={{t="En utsatt hamn",b="Menethil Harbor är en viktig flottport som förbinder de norra delarna av Eastern Kingdoms med södern. Hamnen är uppkallad efter den avlidne kung Terenas Menethil II av Lordaeron och ligger isolerad bland förrädiska träsk och fientliga fiender. När hoten i området ökar inser hamnens ledning att ovärderliga reliker med anknytning till det fallna nordliga kungariket inte kan förvaras säkert i en så utsatt utpost."},{t="Hotet från Dragonmaw",b="Wetlands är fortfarande hemsökt av resterna av klanen Dragonmaw, vildsinta orcher kända för sitt mörka förflutna och sin hänsynslösa opportunism. Med tanke på hur nära de finns och hur hungriga de är på erövringar fruktar hamnens försvarare att Dragonmaw inte skulle dra sig för att plundra historiska skatter som Menethil Statuette, kanske vanhelga den eller använda den som vapen för egna syften."},{t="Rakt till Highlord",b="I stället för att riskera förseningar via vanliga byråkratiska eller militära kanaler får kuriren order att helt kringgå befälskedjan. Reliken skickas direkt till Stormwind Keep, till Highlord Bolvar Fordragons händer. Han är regent åt den unge kungen Anduin Wrynn, och man litar på att ledningen i huvudstaden bäst kan skydda en del av Lordaerons arv."}},faq={{q="Vad är Menethil Statuette?",a="Menethil Statuette är ett värdefullt arvegods med band till Lordaerons kungliga ätt och kung Terenas Menethil II. Den representerar de historiska banden mellan det nordliga kungariket och Alliansen, vilket gör den till ett mål för asätare och fiender.",al={"menethil-relik","vad är statyetten","statyettens historia"}},{q="Varför kan statyetten inte stanna i Menethil Harbor?",a="Menethil Harbor ligger isolerad och omges av fientliga träsk, mörka järndvärgar, murlocer och fientliga orcher. Garnisonen anser att bosättningen är alldeles för utsatt för att kunna skydda en så betydelsefull relik.",al={"varför flytta statyetten","är menethil harbor osäkert"}},{q="Vilka är Dragonmaw och varför vill de ha den?",a="Klanen Dragonmaw är en orchfraktion som har slagit sig ned i Wetlands. Hamnens tjänstemän oroar sig för att de gärna skulle offra krigare för att plundra ansedda alliansreliker och kanske vanhelga eller använda dem i onda syften.",al={"hotet från dragonmaw","varför vill orcher ha statyetten"}},{q="Varför leverera reliken direkt till Bolvar Fordragon?",a="Som regent över Stormwind och beskyddare av den unge kungen Anduin har Highlord Bolvar Fordragon den högsta verkställande makten i huvudstaden. Om reliken överlämnas direkt till honom slipper den administrativa låsningar och får högsta möjliga säkerhet.",al={"varför bolvar","varför kringgå befälskedjan"}},{q="Var befinner sig Highlord Bolvar Fordragon?",a="Highlord Bolvar Fordragon står i tronsalen i Stormwind Keep, bredvid pojkkungen Anduin Wrynn.",al={"var bolvar finns","var är bolvar"}},{q="Hur hänger Menethil Harbor ihop med kung Terenas?",a="Menethil Harbor fick sitt namn som en hyllning till kung Terenas Menethil II, som ledde Lordaeron och stödde Alliansen av Lordaeron under det andra kriget, innan han tragiskt dog under det tredje kriget.",al={"varför heter hamnen menethil harbor","terenas menethils koppling"}}},fx={ece51c60={q="Varför väljs du att föra Menethil Statuette till Stormwind?",a="Menethil Harbor är isolerat och ständigt hotat av fientliga styrkor på andra sidan Wetlands, vilket gör att garnisonen har fullt upp med att försvara hamnen. Du har redan visat dig kapabel och pålitlig genom att återfinna arvegodset. Genom att anförtro det åt en självständig resenär som du slipper staden försvaga sitt lokala försvar, och uppdraget kan genomföras diskret genom farligt område.",al={"varför skicka mig","varför inte skicka vakter","varför leverera statuetten"}}},fp="22,291,19.430.0,20.362.0,24.373.0,31.240.0,48.205.0,46.226.0,51.236.0,43.118.0,49.192.0"}
P.entries["quest:98191"] = {n="A Friend of the Family",s="I Stormwind för A Friend of the Family en sällsynt avbild av kung Terenas till Cathedral of Light. Highlord Bolvar Fordragon anförtror Menethil Statuette åt en äventyrare för Lord Grayson Shadowbreaker, som ska hålla den i säkerhet.",h="I Stormwind för A Friend of the Family en sällsynt avbild av kung Terenas till Cathedral of Light.",kw={"bolvar","katedral","lordaeron","menethil","shadowbreaker","statuett","stormwind","terenas"},ang={["class:Paladin"]="Som paladin skyddar du en relik från kung Terenas som berörts av ljuset. Den hedrar härskaren som först gav sitt godkännande till grundandet av Knights of the Silver Hand.",["class:Priest"]="Som präst kan du se hur helig kraft samlats i en enkel, utskuren avbild. Den vittnar om Lordaerons trogna arv, trots att kungarikets landområden förstörts.",["faction:Alliance"]="Som medlem av Alliansen minns du kung Terenas Menethil II som en grundpelare i Alliance of Lordaeron. Varje föremål med anknytning till honom är ett kärt tecken på enighet och hågkomst."},sec={{t="Ett sällsynt minne",b="Kung Terenas Menethil II hjälpte till att forma Grand Alliance under andra kriget och levde med stor personlig hängivenhet. Trots sin höga ställning bland människornas kungariken var han ödmjuk och ogillade monument som restes till hans ära. Få avbildningar beställdes, och ännu färre överlevde Lordaerons fall och Scourges förödelse."},{t="Berörd av nåden",b="Highlord Bolvar Fordragon ser mer än ett fint hantverk i den bevarade Menethil Statuette. The Holy Light har börjat samlas i den och ger figuren en stilla andlig närvaro. Bolvar beslutar att Stormwind Keep inte är rätt plats för ett sådant heligt föremål. Han skickar den genom staden till Cathedral of Light, i Lord Grayson Shadowbreakers vård. Där tränar han paladiner."}},faq={{q="Vem var kung Terenas Menethil II?",a="Kung Terenas Menethil II styrde Kingdom of Lordaeron och var älskad av sitt folk. Under andra kriget förenade han människorikena med dvärgarna, gnomerna och högalverna för att bilda Grand Alliance, som besegrade Orcish Horde. Han dödades när hans rike föll.",al={"terenas menethil","vem är terenas","lordaerons kung"}},{q="Varför är statyer av kung Terenas så sällsynta?",a="Kung Terenas var ödmjuk och ogillade storslagna monument till sin ära. Få avbildningar höggs ut, och nästan inga överlevde Scourges förstörelse av Lordaeron.",al={"varför finns det få statyer","terenas statuett sällsynthet","varför så få minnesmärken"}},{q="Varför lyser Menethil Statuette av ljuset?",a="Bolvar märker att ljuset har samlats i statuetten. Han kallar Terenas en god och from man, men förklarar inte varför denna avbild bär på helig kraft.",al={"varför har statuetten ljus","helig statuett","ljus som samlas"}},{q="Vem är Lord Grayson Shadowbreaker?",a="Lord Grayson Shadowbreaker är en erfaren mänsklig paladin i Knights of the Silver Hand och en mästare vid Cathedral of Light. Han är stationerad i Cathedral Square, där han tränar blivande paladiner och vakar över heliga angelägenheter för Stormwinds troende.",al={"vem är shadowbreaker","lord graysons roll"}},{q="Varför skickar Highlord Bolvar statuetten till katedralen?",a="Bolvar hedrar Terenas som Alliansens fader och anser att statuetten hör hemma i Cathedral of Light. Helig kraft har samlats i den, och han anförtror den åt de heliga ordnarna i stället för att låta den stanna bland hovets tjänstemän i Stormwind Keep.",al={"varför skicka till katedralen","varför inte behålla i stormwind keep"}},{q="Var ligger Cathedral of Light?",a="Cathedral of Light dominerar Cathedral Square i hjärtat av Stormwind City, mellan Dwarven District, Trade District och Mage Quarter. Den är den främsta helgedomen och gudstjänstplatsen för Church of the Holy Light i de södra kungarikena.",al={"var ligger cathedral of light","cathedral squares läge"}}},fp="22,233,18.331.0,16.370.0,33.284.0,40.164.0,53.156.0,34.250.0,61.247.0,40.251.0"}
P.entries["quest:982"] = {n="Deep Ocean, Vast Sea",s="Deep Ocean, Vast Sea är ett Alliance-uppdrag som Gorbold Steelhand ger i Auberdine. Du ska dyka i vattnet norr om byn och hämta personliga kassaskrin från två sjunkna Night Elf-fartyg, Silver Dawning och Mist Veil. Båda fartygen överfölls av murlocs från kusten, och de överlevande i besättningarna söker nu ett avslut.",h="Deep Ocean, Vast Sea är ett Alliance-uppdrag som Gorbold Steelhand ger i Auberdine.",kw={"auberdine","darkshore","deep ocean vast sea","gorbold steelhand","kassaskrin","mist veil","murloc","skeppsvrak","silver dawning"},ang={["faction:Alliance"]="Besättningarnas gemensamma sorg i Auberdine visar på det nära maritima samarbetet mellan dvärgar och Night Elves längs Kalimdors kust.",["race:Dwarf"]="Gorbold Steelhand visar den typiska dvärgiska instinkten att hedra fallna kamrater och stötta sina sjömän i främmande hamnar.",["race:NightElf"]="De stupade kaptenerna var Night Elf-sjöfarare i Auberdines sjöfartshandel, så att återfinna deras tillhörigheter är en fråga om heder gentemot förfäderna."},sec={{t="Tragedi vid kusten",b="Vattnen utanför Darkshore har blivit allt farligare, inte bara på grund av förrädiska strömmar och naturliga rev, utan också på grund av aggressiva kuststammar. Fartygen Silver Dawning och Mist Veil var på väg in till hamnen i Auberdine när de övermannades av svärmande murlocs. Inget av fartygen överlevde anfallet, och båda sjönk på grunt vatten norr om bosättningen. De överlevande i besättningarna lyckades ta sig i land, men förlusten av fartygen och kaptenerna lade en tung skugga över hamnen."},{t="Återfinna förlorade minnen",b="Gorbold Steelhand, en dvärg stationerad i Auberdine, tar sig an uppgiften att hedra de stupade Night Elf-kaptenerna. Fartygen är nu ruiner under vattnet, som traktens murlocs tagit över som troféer och bon, men kaptenernas kassaskrin ligger fortfarande låsta i de vattenfyllda lastrummen. När loggböckerna och de personliga tillhörigheterna därinne återbördas kan de överlevande sjömännen i Auberdine sörja sina befälhavare ordentligt och låta deras andar få ro."}},faq={{q="Var ligger de sjunkna fartygen?",a="Vrak efter både Silver Dawning och Mist Veil ligger under vatten utanför Darkshores kust, alldeles norr om bryggorna i Auberdine.",al={"var ligger skeppsvraken","vrakens plats","var hittar man silver dawning"}},{q="Vad hände med Silver Dawning och Mist Veil?",a="Båda fartygen överfölls av murlocs när de seglade över havet mot Auberdine. Besättningarna övermannades, båda kaptenerna dog och fartygen gick under och lade sig på havsbotten.",al={"hur sjönk fartygen","varför förliste fartygen","vad sänkte mist veil"}},{q="Vem är Gorbold Steelhand?",a="Gorbold Steelhand är en dvärg som bor i Night Elf-hamnen Auberdine. Han håller uppsikt över de överlevande sjömännen i staden och ger äventyrare i uppdrag att återfinna de förlorade kaptenernas tillhörigheter.",al={"vem ger deep ocean vast sea","gorbold steelhands historia"}},{q="Vad finns i kassaskrinen?",a="Kassaskrinen innehåller personliga tillhörigheter och loggböcker som tillhör de stupade Night Elf-kaptenerna. Föremålen är kära minnen för besättningsmedlemmarna som överlevde förlisningen.",al={"vad finns i kassaskrinen","kaptenernas kassaskrin innehåll"}},{q="Varför bryr sig de överlevande så mycket om de här tillhörigheterna?",a="Kaptenerna var respekterade Night Elf-sjöfarare. Att återfinna deras loggböcker och ägodelar ger deras överlevande besättningar ett avslut och tros hjälpa deras andar att få ro.",al={"varför återfinna kassaskrinen","varför hjälpa kaptenerna"}},{q="Vilka varelser bor nu i skeppsvraken?",a="Ruinerna har tagits över av murlocs, som behandlar de vrakslagna skroven som troféer och stryker omkring i vattnen intill.",al={"vad vaktar fartygen","fiender vid skeppsvraken"}}},fp="20,208,21.248.0,24.304.0,35.71.0,54.147.0,25.143.0,29.126.0,54.150.0,42.102.0"}
P.entries["quest:98208"] = {n="Bloom of the Heavens",s="Bloom of the Heavens handlar om att återfinna Nord'el, en helig Night Elf-blomma som plockas under fullmåne på Mount Hyjal. Blomman gick förlorad när Night Elf-fartyget Flying Osprey förliste söder om Menethil Harbor tillsammans med skepp från Kul Tiran Third Fleet. Nu måste äventyrare våga möta murlocer som håller till bland vrakdelarna för att hämta den.",h="Bloom of the Heavens handlar om att återfinna Nord'el, en helig Night Elf-blomma som plockas under fullmåne...",kw={"auberdine","bloom of the heavens","flying osprey","menethil harbor","mount hyjal","murlocer","nord'el","sylessa duskwhisper","teldrassil","wetlands"},ang={["faction:Alliance"]="Det förlorade fartyget Flying Osprey seglade tillsammans med Kul Tiran Third Fleet innan båda drabbades av katastrofen utanför Menethil Harbors kust.",["profession:Herbalism"]="Nord'el är en ytterst sällsynt Night Elf-blomma som odlas under fullmåne på toppen av Mount Hyjal. Den är ett botaniskt underverk utan motstycke.",["race:NightElf"]="Nord'el är en dyrbar botanisk relik från Mount Hyjal, plockad innan Night Elf flyttade sitt hem till Teldrassils grenar."},sec={{t="En relik från Mount Hyjal",b="Sylessa Duskwhisper gjorde den långa resan från Auberdine vid Kalimdors kust till Menethil Harbor för att rädda en skatt med djup kulturell betydelse. Lasten hon söker är Nord'el, som på det gemensamma språket kallas Bloom of the Heavens, en helig blomma plockad på Mount Hyjals topp under en strålande fullmåne. För de fördrivna Night Elf som nu bor i Teldrassil är sådana reliker från deras förfäders berg ovärderliga påminnelser om deras arv."},{t="Flying Ospreys öde",b="Blomman gick förlorad för många månvarv sedan när Night Elf-fartyget Flying Osprey förliste längs den klippiga kusten strax söder om Menethil Harbor, efter att ha seglat tillsammans med Kul Tiran Third Fleet. I dag ligger det förstörda skrovet på grunt vatten, som ett dystert minnesmärke över katastrofen. Som om det inte vore nog har våldsamma murlocrövare tagit över vraket. De försvarar det förstörda fartyget med våld och hotar alla som försöker återta Kaldorei-lasten."}},faq={{q="Vad är Nord'el?",a="Nord'el betyder Bloom of the Heavens på darnassiska. Det är en helig blomma av stor betydelse för Night Elf, plockad efter att ha blommat under fullmåne på toppen av Mount Hyjal, Night Elfs förfäders bergshem.",al={"vad är nord'el","nord'el-blomma","vad är bloom of the heavens"}},{q="Vad var Flying Osprey?",a="Flying Osprey var ett Night Elf-fartyg som seglade tillsammans med Kul Tiran Third Fleet. För många månvarv sedan förliste fartyget strax söder om Menethil Harbor, längs Wetlands kust, och dess värdefulla last spreds ut.",al={"fartyget flying osprey","vilket fartyg förliste","kul tiran third fleet wetlands"}},{q="Vem är Sylessa Duskwhisper?",a="Sylessa Duskwhisper är en Night Elf-sändebud som reste över havet från Auberdine och Teldrassils grenar till Menethil Harbor, särskilt för att återfinna den förlorade blomman åt sitt folk.",al={"vem är sylessa duskwhisper","uppdragsgivare menethil","night elf i menethil"}},{q="Varför är skeppsvraket farligt?",a="Våldsamma murlocrövare har tagit över kustvraket söder om Menethil Harbor och lagt beslag på resterna av Flying Osprey. Därför är bärgningen farlig för Sylessa.",al={"varför finns murlocer vid vraket","vem vaktar vraket","vrak söder om menethil"}},{q="Varför är Nord'el så viktig för Night Elf?",a="Blomman plockades på toppen av Mount Hyjal, Kaldoreis forna hem, innan Teldrassil grundades. Dess ursprung och heliga skörd under fullmånen ger den ett enormt kulturellt och känslomässigt värde för Night Elf.",al={"varför är blomman viktig","varför vill sylessa ha nord'el"}},{q="Var finns vraket?",a="Vraket efter Flying Osprey ligger vid kusten strax söder om Menethil Harbor i Wetlands, bland klippor som nu svärmar av fientliga murlocer.",al={"var finns vraket","var finns blomman","skeppsvrakets plats wetlands"}}},fp="20,370,22.466.0,29.455.0,16.225.0,27.218.0,27.190.0,31.166.0,47.248.0,32.143.0"}
P.entries["quest:98209"] = {n="Bloom of the Heavens",s="Bloom of the Heavens är en resa över havet för att föra en mirakulös botanisk relik från Night Elf, kallad Nord'el, vidare. Den bevarade blomman troddes ha gått förlorad i generationer och är en stark symbol för Elunes nåd och kaldoreiernas motståndskraft efter förlusten av sin odödlighet.",h="Bloom of the Heavens är en resa över havet för att föra en mirakulös botanisk relik från Night Elf, kallad...",kw={"auberdine","bloom of the heavens","darkshore","darnassus","elune","menethil harbor","nord'el","sylessa","thundris windweaver","wetlands"},ang={["faction:Alliance"]="Uppdraget förbinder den livliga allianshamnen Menethil Harbor i Eastern Kingdoms med Auberdine och Darnassus i norra Kalimdor, tvärs över Great Sea.",["profession:Herbalism"]="Örtkännare och botaniker kommer att uppskatta att Nord'el återfunnits. Denna heliga växt troddes ha varit förlorad i evigheter och behöver odlas i Darnassus.",["race:NightElf"]="Nord'el är en dyrbar kvarleva av Kalimdors heliga arv och ett upplyftande tecken på att Elune vakar över kaldoreierna medan de anpassar sig till förlusten av sin odödlighet."},sec={{t="En farlig återhämtning",b="I våtmarkerna i Wetlands lyckas Sylessa återfinna en legendarisk blomma som kallas Nord'el, trots att hon utsätts för ett angrepp från våldsamma lokala murlocer. Utmattad efter sin farliga flykt anförtror hon växten åt en äventyrare, som ska föra den över Great Sea till Auberdine. Båten från Menethil Harbor går direkt till Darkshore och förbinder Eastern Kingdoms med norra Kalimdor."},{t="Ett tecken på Elunes nåd",b="När Elder Thundris Windweaver får Nord'el i Auberdine blir han häpen. Han hade trott att den heliga blomman försvunnit för alltid. Night Elf kämpar fortfarande med uppoffringen av sin odödlighet efter slaget vid Mount Hyjal, och Nord'els mirakulösa överlevnad lyser som en välsignelse från Elune. Thundris förbereder sig på att skicka den ömtåliga växten vidare till Darnassus, där den ska odlas och bevaras åt kommande generationer."}},faq={{q="Vad är Nord'el?",a="Nord'el är en helig växt som Night Elf länge trodde hade gått förlorad. Att den återfunnits och överlevt efter många år gör den till en dyrbar symbol för Elunes gudomliga ynnest och ett vittnesbörd om naturens motståndskraft.",al={"vad är nord'el","nord'el blomma","helig blomma"}},{q="Vem ger uppdraget Bloom of the Heavens?",a="Sylessa i Wetlands ger uppdraget. Hon lyckades återfinna den heliga blomman trots att hon överfölls och förföljdes av fientliga murlocer, men prövningen gjorde henne alltför utmattad för att själv slutföra resan.",al={"vem ger bloom of the heavens","uppdragsgivare i wetlands nord'el","sylessa wetlands"}},{q="Vart ska Nord'el levereras?",a="Nord'el ska föras över havet till Elder Thundris Windweaver i Auberdine, vid kusten i Darkshore. Resenärer tar båten direkt från Menethil Harbor till Auberdine.",al={"vart ska jag föra nord'el","thundris windweaver plats","leverans till auberdine"}},{q="Varför är Nord'el så betydelsefull för Night Elf?",a="Elder Thundris Windweaver ser blommans överlevnad som ett sällsynt hoppets ljus i mörka tider. Den är en helig påminnelse om Elunes nåd och kaldoreiernas uthålliga anda efter att de offrat sin odödlighet under det tredje kriget.",al={"varför är nord'el viktig för night elf","nord'el bakgrund","night elf odödlighet nord'el"}},{q="Vad händer med blomman när den når Auberdine?",a="När Thundris Windweaver tar emot blomman i Auberdine ordnar han så att den förs säkert inåt landet till Darnassus, där Night Elf-botaniker och präster kan vårda och odla den ordentligt.",al={"vad händer med nord'el sedan","nord'el darnassus","vart skickar thundris nord'el"}},{q="Hur tar man sig från Menethil Harbor till Auberdine?",a="Resenärer kan ta passagerarbåten som lägger till i Menethil Harbor i Wetlands. Den seglar direkt över Great Sea till hamnen i Auberdine i Darkshore.",al={"hur tar man sig till auberdine från wetlands","båt från menethil till auberdine","båt till darkshore"}}},fp="20,274,20.407.0,23.464.0,16.200.0,41.219.0,40.188.0,49.256.0,56.197.0,52.165.0"}
P.entries["quest:98245"] = {n="Razormaw Needling",s="Razormaw Needling är ett uppdrag i Wetlands där Howin Kindfeather ber resenärer samla in framtänder från traktens Razormaw-raptorer. Howin vill tillverka hållbara sylverktyg av deras vassa tänder för att kunna genomborra och sy ihop drakungars fjäll till eldtålig rustning.",h="Razormaw Needling är ett uppdrag i Wetlands där Howin Kindfeather ber resenärer samla in framtänder från...",kw={"dark iron","dragonmaw","howin kindfeather","raptor ridge","raptorer","razormaw-framtänder","razormaw needling","saltspray glen","wetlands","drakungafjäll"},ang={["faction:Alliance"]="Skyddsutrustning mot drakeld hjälper Alliansen i den pågående kampen mot drakkin och Dragonmaw-styrkorna som håller de östra träskmarkerna.",["race:Dwarf"]="Howin Kindfeather delar Wildhammer- och Ironforge-dvärgarnas bittra hat mot både Dark Iron-klanen och Dragonmaw-orcherna, som härjade i Wetlands och Grim Batol."},sec={{t="Hämndens verktyg",b="I Wetlands blöta marker hyser Howin Kindfeather ett djupt raseri mot fienderna som har plågat trakten: de förrädiska Dark Iron-dvärgarna, de brutala Dragonmaw-orcherna och de eldsprutande drakar de förde med sig i strid. För att slå tillbaka och skydda sig mot drakeld arbetar Howin med att sätta ihop skyddande rustning av drakungars fjäll. Men de tåliga skinnen är ökända för att vara svåra att sy ihop utan särskilda hantverksverktyg."},{t="Tänder som nålar",b="För att sticka igenom det tåliga drakungeskinnet behöver Howin verktyg som är mycket vassare och starkare än vanliga metallnålar, som lätt böjs eller blir slöa mot drakfjäll. Han vänder sig till de lokala Razormaw-raptorerna som stryker omkring på Raptor Ridge i nordost och Saltspray Glen i nordväst. De har fått sitt namn efter sina dödliga, nålvassa tänder. Hela Razormaw-framtänder fungerar utmärkt som sylverktyg och genomborrar hårda fjäll utan att splittras under tryck."}},faq={{q="Vem ger uppdraget Razormaw Needling?",a="Howin Kindfeather ger uppdraget i Wetlands. Han hyser ett djupt agg mot Dark Iron-dvärgarna, Dragonmaw-klanen och drakarna de red på, och vill tillverka drakeldstålig rustning av drakungars fjäll.",al={"vem ger razormaw needling","vem är howin kindfeather","uppdragsgivare för razormaw needling"}},{q="Varför behöver Howin Kindfeather Razormaw-framtänder?",a="Howin arbetar med tåliga drakungafjäll för att tillverka skyddande rustning, men skinnet är för tätt för att enkelt kunna sys ihop. Han behöver Razormaw-raptorernas vassa, starka framtänder för att tillverka sylverktyg som kan genomborra fjällen utan att gå sönder.",al={"varför vill howin ha raptortänder","vad används razormaw-framtänder till","vad ska tänderna användas till"}},{q="Var finns Razormaw-raptorerna?",a="Razormaw-raptorer stryker omkring på två huvudsakliga jaktmarker i Wetlands: Raptor Ridge i högländerna i nordost och Saltspray Glen i nordväst, mot kusten.",al={"var hittar man razormaw-raptorer","razormaw-raptorernas plats i wetlands","var finns raptorerna"}},{q="Vad tillverkar Howin Kindfeather av drakungafjällen?",a="Howin syr ihop drakungars fjäll till skyddande utrustning. Fjällen ger ett gott skydd mot eldiga andedräkter och skyddar mot drakar och Dragonmaw-klanens drakar.",al={"vilken rustning tillverkar howin","rustning av drakungafjäll i wetlands","varför drakungafjäll"}},{q="Varför hatar Howin Dark Iron och Dragonmaw?",a="Wetlands och de omgivande bergen bär djupa ärr efter både Dark Iron-klanen och Dragonmaw-orcherna, som förslavade röda drakar under det andra kriget. Howin avskyr båda fraktionerna och deras flygande riddjur och är fast besluten att återställa balansen.",al={"varför hata dark iron och dragonmaw","howins fiender","varför hatar howin dragonmaw"}},{q="Vad gör Howin av raptorernas framtänder?",a="En syl är ett smalt, spetsigt handverktyg som används för att göra hål i tjocka hudar och läder före sömnad. Genom att fästa hela raptorframtänder på skaft eller använda deras naturliga avsmalning tillverkar Howin hållbara sylverktyg som kan genomborra drakfjäll utan att knäckas.",al={"vad är en syl","razormaw-sylverktyg","hur används raptortänder som verktyg"}}},fp="17,275,20.479.0,16.435.0,38.217.0,50.270.0,39.178.0,55.213.0,49.257.0,46.258.0"}
P.entries["quest:98246"] = {n="Trying Times",s="Trying Times är ett Alliance-uppdrag i Wetlands där äventyrare hjälper dvärgen Howin Kindfeather. För att förbereda sin griniga gryf Bassbeak för ett kommande uppdrag behöver Howin ett dussin hela ägg från de vilda Razormaw-raptorerna.",h="Trying Times är ett Alliance-uppdrag i Wetlands där äventyrare hjälper dvärgen Howin Kindfeather.",kw={"bassbeak","gryf","howin kindfeather","raptor ridge","razormaw-ägg","saltspray glen","trying times","wetlands"},ang={["faction:Alliance"]="Att hålla gryfer friska är avgörande för Alliansens resor och kommunikation genom Khaz Modan, särskilt när lokala faror hotar säkerheten i regionen.",["race:Dwarf"]="Dvärgarnas gryfryttare vet att en argsint gryf är lika farlig som vilken fiende som helst. Därför måste den få ordentlig mat och omvårdnad innan den lyfter mot skyn.",["race:Gnome"]="Howin påpekar skämtsamt att Razormaw-raptorernas ägg har gulor stora som en gnoms knopp. Det är ett talande, om än lite respektlöst, dvärgmått."},sec={{t="Att blidka en hungrig gryf",b="I Wetlands dunkla vidder krävs ständig vaksamhet för att hålla ett riddjur i skick. Howin Kindfeather, en dvärg som arbetar tillsammans med sin gryf Bassbeak, vägrar lyfta utan att först stilla sin följeslagare nyckfulla aptit. En hungrig gryf är envis och oförutsägbar, och den kan lätt gå till angrepp. Därför måste den få en ordentlig måltid innan någon flygtur över träskmarkerna."},{t="Razormaw-raptorernas fångst",b="Det har blivit allt svårare att hitta pålitlig, ofördärvad föda i Wetlands. För att mätta Bassbeak siktar Howin in sig på de inhemska Razormaw-raptorernas bon vid Raptor Ridge i nordost och Saltspray Glen i nordväst. Raptorernas ägg sägs ha gulor stora som en gnoms huvud. De ger Bassbeak den rejäla, rena måltid hon behöver innan hon möter regionens faror."}},faq={{q="Vem är Howin Kindfeather?",a="Howin Kindfeather är en dvärgskötare som tar hand om en gryf vid namn Bassbeak i Wetlands. Han ber äventyrare samla färska raptorägg och mata sin följeslagare innan han sätter sina planer i verket.",al={"vem är howin kindfeather","howin kindfeather wetlands","uppdragsgivare trying times"}},{q="Vem är Bassbeak?",a="Bassbeak är Howin Kindfeathers gryf. Enligt Howin blir hon lättretlig och direkt farlig när hon är hungrig. Det är därför osäkert att rida på eller använda henne innan hon är mätt.",al={"vem är bassbeak","bassbeak gryfen","howins gryf"}},{q="Varför behöver Howin raptorägg?",a="Howin är särskilt ute efter Razormaw-raptorägg eftersom ofördärvad föda är sällsynt i Wetlands. Äggen har stora, näringsrika gulor som kan mätta Bassbeaks väldiga aptit.",al={"varför raptorägg","varför mata gryfen med ägg","vad ska äggen användas till"}},{q="Var finns Razormaw-raptorerna?",a="Razormaw-raptorer håller till vid Raptor Ridge i nordost och Saltspray Glen i nordväst i Wetlands. Äventyrarna måste själva våga sig in i bona för att få tag på felfria ägg.",al={"var finns razormaw-raptorer","var hittar man razormaw-ägg","raptorernas platser i wetlands"}},{q="Varför måste äggen vara perfekta?",a="Howin kräver ägg utan sprickor eller skavanker för att maten ska vara helt färsk och ofördärvad. Då håller sig Bassbeak frisk och nöjd, i stället för att få dåliga rester.",al={"varför måste äggen vara perfekta","spruckna ägg trying times"}},{q="Vad planerar Howin att göra med Bassbeak?",a="Howin nämner att han har större planer för Bassbeak, men håller detaljerna i bakgrunden tills gryfen har fått mat och lugnat sig så pass att hon säkert kan lyfta trots hoten i regionen.",al={"vad är howins plan","vad planerar howin och bassbeak"}}},fp="12,240,26.401.0,19.405.0,25.204.0,16.178.0,32.200.0,36.176.0,35.181.0,43.204.0"}
P.entries["quest:98247"] = {n="Shipping Label",s="Shipping Label är en återfunnen fraktmarkering på en Supply Crate som tillhör Azeroth Commerce Authority. Den hänvisar kurirer till organisationens handelsnav vid Three Corners-korsningen i Redridge Mountains och introducerar resenärer till dess nätverk av självständiga transportörer.",h="Shipping Label är en återfunnen fraktmarkering på en Supply Crate som tillhör Azeroth Commerce Authority.",kw={"azeroth commerce authority","låda","leverans","merchant's favor","redridge mountains","shipping label","three corners"},ang={["faction:Alliance"]="Azeroth Commerce Authority verkar vid Three Corners-korsningen och förlitar sig på kringresande äventyrare i Alliansens södra områden för att återfinna gods på villovägar och säkra landvägarna för transport."},sec={{t="En leverans på villovägar",b="Den här skadade fraktsedeln sitter på en välfylld Supply Crate och markerar gods som tillhör Azeroth Commerce Authority. Den avsedda destinationen och mottagaren har rivits bort, men tydliga instruktioner säger att den som hittar godset ska återlämna det eller rapportera till myndighetens handelsutpost i Redridge Mountains. Bredvid den formella texten visar en enkel karta vägarna mot Three Corners-korsningen."},{t="Commerce Authoritys nav",b="Vid Three Corners-korsningen värvar representanter för Azeroth Commerce Authority aktivt resenärer som självständiga kurirer. I stället för att binda transportörer till strikta handelsavtal driver myndigheten ett informellt nätverk där äventyrare får Merchant's Favor i ersättning för att återfinna försvunnet gods och slutföra övergivna leveranser längs landsvägen."}},faq={{q="Vad är Shipping Label?",a="Shipping Label är ett sönderrivet dokument som hittas på sidan av en återfunnen Supply Crate. Mottagarens namn saknas, men etiketten visar att varorna tillhör Azeroth Commerce Authority och hänvisar upphittaren till deras nav vid Three Corners.",al={"vad är shipping label","uppdraget shipping label","trasig shipping label"}},{q="Vad är Azeroth Commerce Authority?",a="Azeroth Commerce Authority är ett företag som organiserar logistik, handel och frakt i regionen. De håller lokala handelsnav för att återfinna förlorade försändelser och anlitar kringresande kurirer utan långsiktiga avtal.",al={"vem är aca","azeroth commerce authority","vad är azeroth commerce authority"}},{q="Var ligger Azeroth Commerce Authoritys handelsnav?",a="Azeroth Commerce Authoritys handelsnav ligger vid Three Corners-korsningen i Redridge Mountains, strategiskt placerat längs vägarna som förbinder Elwynn Forest, Duskwood och Lakeshire.",al={"var ligger aca:s handelsnav","navet vid three corners","var lämnar jag in shipping label"}},{q="Vad är Merchant's Favor?",a="Merchant's Favor är en särskild sorts värdebevis eller kredit som Azeroth Commerce Authority ger till självständiga kurirer. Anslutna kurirer använder den för att köpa olika handelsvaror och logistiktjänster vid myndighetens stationer.",al={"vad är merchant's favor","merchant's favor","aca:s ersättning"}},{q="Hur blir du ansluten till Azeroth Commerce Authority?",a="För att bli ansluten krävs inga formella avtal, papper eller långsiktiga åtaganden. Azeroth Commerce Authority kräver bara att kurirer hjälper till att återlämna eller slutföra felriktade leveranser som de stöter på ute i världen.",al={"hur blir man ansluten till aca","gå med i aca","behöver jag ett avtal"}},{q="Vad händer med lådan efter att du lämnat in fraktsedeln?",a="Fraktsedeln får handelsnavets representanter att fråga om den fysiska låda som den satt på, eftersom det är viktigt för deras handelsverksamhet att få tillbaka tomma eller levererade fraktbehållare.",al={"vad händer med lådan","försvunnen låda","vill de ha lådan"}}},fp="14,287,16.447.0,28.387.0,27.270.0,39.220.0,58.199.0,25.225.0,65.232.0,53.203.0"}
P.entries["quest:98248"] = {n="Shipping Label",s="En sönderriven fraktsedel på en nyligen påfylld fraktcontainer visar vägen till ett regionalt handelscentrum i The Barrens. Durotar Supply and Logistics förlitar sig på kringresande vandrare som kan återfinna försvunna lådor och lämna tillbaka papperen till deras postering väster om The Crossroads. När du lämnar tillbaka dem hålls viktiga leveranskedjor och handeln i centrala Kalimdor igång.",h="En sönderriven fraktsedel på en nyligen påfylld fraktcontainer visar vägen till ett regionalt handelscentrum...",kw={"låda","crossroads","durotar supply and logistics","shipping label","the barrens","handelsplats"},ang={["faction:Horde"]="Horde-äventyrare som färdas genom The Barrens stöter ofta på Durotar Supply and Logistics verksamhet och hjälper till att upprätthålla viktig handel och leveranser mellan Durotar och centrala Kalimdor."},sec={{t="En vilsegången fraktsedel",b="Det här sönderrivna dokumentet sitter på en nyligen påfylld lastlåda och innehåller logistikuppgifter från Durotar Supply and Logistics. Mottagarens namn har slitits bort under resans gång, men ursprungsrubriken visar tydligt vilket fraktbolag som verkar från Horde-territorier. En grovt skissad färdväg bredvid texten visar kurirer raka vägen till företagets uppställningsplats på de centrala slätterna."},{t="Handel vid gränsen",b="Meddelandet uppmanar resenärer att frakta vilsegångna containrar, skadade varor eller bevis på bärgning till handelsplatsen, som ligger rakt väster om The Crossroads. Durotar Supply and Logistics verkar i The Barrens karga vidder och är starkt beroende av självständiga fraktare och resenärer för att återfinna utspridd last. De lovar ersättning till alla som hjälper till att hålla regionens leveranser igång."}},faq={{q="Vad är Shipping Label?",a="Det är ett dokument som sitter på en fullastad låda och innehåller returinstruktioner för Durotar Supply and Logistics. Det visar vägen tillbaka till deras postering nära The Crossroads för försvunna eller tomma containrar.",al={"vad är shipping label","shipping label uppdrag","sönderriven fraktsedel"}},{q="Vart ska fraktsedeln lämnas?",a="Fraktsedeln visar kurirer till personalen på Durotar Supply and Logistics handelscentrum, som ligger rakt väster om The Crossroads i The Barrens.",al={"vart lämnar jag shipping label","vem vill ha shipping label","lämna in shipping label"}},{q="Vad är Durotar Supply and Logistics?",a="Durotar Supply and Logistics är ett kommersiellt fraktbolag som verkar i Durotar och The Barrens. De sköter godstransporter, insamling av lådor och logistiskt stöd i Horde-territorier.",al={"vad är durotar supply and logistics","durotar supply handelsplats"}},{q="Vem var försändelsen ursprungligen avsedd för?",a="Den avsedda mottagarens namn har slitits bort helt från fraktsedeln. Bara returinstruktionerna och företagets ursprungsuppgifter finns kvar på lådan.",al={"vem var lådan avsedd för","lådans mottagare"}},{q="Var ligger Durotar Supply and Logistics handelsplats?",a="Enligt anvisningarna och den grova kartan på fraktsedeln ligger handelsplatsen bekvämt nog rakt väster om bosättningen The Crossroads i The Barrens.",al={"var ligger handelsplatsen","durotar supply plats crossroads"}},{q="Ersätter Durotar Supply and Logistics resenärer för återlämnade lådor?",a="Ja, det tryckta meddelandet lovar uttryckligen att kurirer får ersättning för tid och arbete när de lämnar skadade försändelser, fraktsedlar eller tomma lådor vid handelsplatsen.",al={"betalar de för återlämnade lådor","durotar supply ersättning"}}},fp="14,364,18.424.0,17.415.0,27.191.0,36.161.0,37.198.0,45.164.0,64.158.0,76.184.0"}
P.entries["quest:98283"] = {n="Carnage",s="Carnage är ett uppdrag i Wetlands som Rethiel the Greenwarden ger i The Green Belt. Rethiel ber resenärer locka fram och döda Carnage, en vansinnig Razormaw-raptorhane vars pestframkallade raseri har rubbat regionens naturliga ordning.",h="Carnage är ett uppdrag i Wetlands som Rethiel the Greenwarden ger i The Green Belt.",kw={"carnage","loch modan","raptor ridge","razormaw","rethiel the greenwarden","rotclaw","the green belt","wetlands"},ang={["class:Druid"]="Druider delar Rethiels sorg över den rubbade naturliga balansen i Wetlands, där sjukdom har förvandlat rovdjur som Carnage till vettlösa skräckväsen.",["class:Hunter"]="Jägare förstår faran när en alfahanes naturliga instinkter går förlorade i pestframkallat raseri och den börjar jaga sina egna."},sec={{t="En rubbad balans",b="I Wetlands träskmarker har den naturliga ordningen börjat krackelera. Razormaw-raptorerna fyllde en gång en viktig ekologisk funktion och höll vildmarken fri från okontrollerad växtlighet. Nu har deras flockhierarki slagits sönder av den skräckinjagande alfahanen, ett blodtörstigt best känt enbart som Carnage. I stället för att leda flocken har Carnage spridit skräck bland de sina, slaktat urskillningslöst och kastat det lokala ekosystemet i kaos."},{t="Locka fram alfahanen",b="Rethiel the Greenwarden, som vakar över The Green Belt, tror att Carnage har fallit offer för den vidriga korruption som fortfarande plågar regionen. För att locka fram det rasande odjuret ur sitt gömställe måste resenärer samla in de sjuka Rotclaw-björnarnas illasinnade inälvor. Björnarna har vandrat ner från Loch Modan. Om man placerar det vidriga köttet i Carnages grotta under Raptor Ridge retas monstret till anfall, så att resenärerna kan göra slut på dess lidande."}},faq={{q="Vem är Carnage?",a="Carnage är den monstruösa alfahanen bland Wetlands Razormaw-raptorer. I stället för att leda flocken som vanligt har sjukdomen drivit odjuret till vansinne. Det lämnar bara slakt efter sig och skrämmer till och med sina egna raptorfränder.",al={"vem är carnage","carnage raptor","vad är carnage"}},{q="Vem ger uppdraget Carnage?",a="Uppdraget ges av Rethiel the Greenwarden, en väktare stationerad i Wetlands, i The Green Belt. Hen arbetar för att återställa regionens fördärvade naturliga balans.",al={"vem ger uppdraget carnage","var lämnar man in carnage","rethiel wetlands"}},{q="Varför måste Carnage dödas?",a="Rethiel vill att Carnage ska dö eftersom en onaturlig sjukdom har drivit odjuret till vansinne. Det har krossat Razormaw-raptorernas naturliga hierarki och ödelagt den lokala ekologin.",al={"varför döda carnage","varför vill rethiel att carnage ska dö"}},{q="Hur lockas Carnage fram?",a="Carnage lockas fram genom att man agnar grottan med sjuka björnars illasinnade kött och inälvor. Björnarna finns nedanför Raptor Ridge, åt nordost.",al={"hur kallar man fram carnage","hur lockar man fram carnage","var finns carnages grotta"}},{q="Vilka är de sjuka björnarna som Rethiel nämner?",a="De sjuka björnarna är Rotclaws som har vandrat ner från Loch Modan. Den kvardröjande korruptionen har drivit dem till vansinne. Deras fördärvade kött fungerar som effektivt bete för att locka fram den galna raptoralfan.",al={"vad är rotclaw-björnar","varifrån kommer de sjuka björnarna"}},{q="Vilken roll hade Razormaw-raptorerna ursprungligen i Wetlands?",a="Under normala omständigheter upprätthåller Razormaw-raptorerna den ekologiska balansen i Wetlands genom att hindra växt- och djurlivet från att breda ut sig okontrollerat. Carnages vansinne har rubbat denna viktiga funktion.",al={"vilken roll har razormaw","varför är raptorer viktiga i wetlands"}}},fp="7,243,16.445.0,16.443.0,15.226.0,28.162.0,30.185.0,25.145.0,49.186.0,68.200.0"}
P.entries["quest:98286"] = {n="Camping 101: Enchanting",s="Camping 101: Enchanting skickar utövare av den magiska konsten till Shen'dar Village för att lära sig skapa specialutrustning för vildmarken. Genom att tala med Nasalanna Windsinger kan erfarna förtrollare lära sig att tillverka en Enchanted Lute som underhåller och stärker deras följeslagare vid lägerelden.",h="Camping 101: Enchanting skickar utövare av den magiska konsten till Shen'dar Village för att lära sig skapa...",kw={"lägereld","camping","camping 101","enchanted lute","förtrollning","luta","nasalanna windsinger","shen'dar village"},sec={{t="Hemmets bekvämligheter",b="Livet på vägarna kräver mer än vässade klingor och ransoner; vila och gott mod är avgörande för att klara långa expeditioner. Förtrollare bidrar med unika magiska bekvämligheter i lägerlivet och använder sin kunskap om omgivande magi för att muntra upp resenärer under vilan. I vildmarksläger över hela Azeroth ser en förtrollare till att utmattade äventyrare kan återfå sin styrka och sitt mod innan de återvänder till farliga stigar."},{t="Sången från Shen'dar",b="För att lära sig lägrets subtila skapandemagi hänvisas blivande förtrollare till Shen'dar Village. Där instruerar Nasalanna Windsinger skickliga besvärjare i att konstruera en Enchanted Lute. Hantverkare måste först visa sin hängivenhet och skicklighet i förtrollning innan Nasalanna delar med sig av hemligheterna bakom ett instrument som kan väva läkande melodier under stjärnorna."}},faq={{q="Vem är Nasalanna Windsinger?",a="Nasalanna Windsinger är en instruktör som bor i Shen'dar Village. Hon lär skickliga utövare att tillverka särskilda yrkesföremål för vildmarksläger, närmare bestämt Enchanted Lute för förtrollare som visar sin skicklighet.",al={"vem lär ut enchanted lute","vem är nasalanna windsinger","var finns nasalanna windsinger"}},{q="Var ligger Shen'dar Village?",a="Shen'dar Village är bosättningen där Nasalanna Windsinger bor. Äventyrare som vill lära sig att tillverka campingutrustning som Enchanted Lute reser dit när de har utvecklat sina grundläggande färdigheter.",al={"var ligger shendar village","hur hittar man shendar village"}},{q="Vad är Enchanted Lute?",a="Enchanted Lute är ett magiskt campinginstrument som tillverkas av förtrollare. Det underhåller och stärker moralen under vilan vid lägerelden, så att resenärer kan samla mod och förbereda sig på vildmarkens utmaningar.",al={"vad gör enchanted lute","varför tillverka enchanted lute","campingluta"}},{q="Vilka krav gäller för att lära sig receptet?",a="Innan Nasalanna Windsinger lär dig att tillverka en Enchanted Lute måste du först bevisa din skicklighet i förtrollningens magiska konst. Bara erfarna utövare får förtroendet att skapa dessa praktiska lägerförtrollningar.",al={"krav för camping 101 enchanting","när kan jag lära mig enchanted lute"}},{q="Varför är förtrollare värdefulla vid lägerplatser i vildmarken?",a="Förtrollare bidrar med subtil nytta och magiska bekvämligheter i avlägsna läger där vanliga förnödenheter ofta inte räcker till. Genom att förse vanliga campingredskap med magiska egenskaper hjälper de äventyrare att återhämta sig, få underhållning och förbereda sig på oväntade faror längs vägen.",al={"varför vill campare ha förtrollare","fördelar med förtrollare vid camping"}},{q="Kan andra yrken tillverka campingföremål?",a="Ja, hantverkare och samlare inom olika yrken lär sig att skapa särskilda redskap för lägerplatser. För förtrollare består detta specialhantverk av Enchanted Lute, som Nasalanna Windsinger lär ut i Shen'dar Village.",al={"finns det andra campingföremål","andra yrkens campinghantverk"}}},fp="23,296,22.461.0,20.402.0,28.252.0,26.213.0,26.250.0,46.233.0,52.266.0,42.228.0"}
P.entries["quest:98293"] = {n="Forced Disarmament",s="Forced Disarmament är ett uppdrag för Alliansen i Wetlands där äventyrare ska lägga beslag på vapengömmor från Dragonmaw-klanen vid Dragonmaw Retreat. Genom att samla in trettio buntar med vapen hindrar spelarna de fientliga orcherna från att utrusta fler soldater inför framtida räder. Den beslagtagna utrustningen lämnas till Captain Stoutfist i Menethil Keep för att skydda regionens viktiga hamn.",h="Forced Disarmament är ett uppdrag för Alliansen i Wetlands där äventyrare ska lägga beslag på vapengömmor...",kw={"captain stoutfist","dragonmaw armaments","dragonmaw-klanen","dragonmaw retreat","forced disarmament","menethil harbor","menethil keep","wetlands"},ang={["faction:Alliance"]="Alliansens styrkor är beroende av Menethil Harbor som en viktig livlina över Great Sea, vilket gör det till ett akut strategiskt behov att avväpna fientliga klaner i närheten.",["race:Dwarf"]="Dvärgiska försvarare från Ironforge bemannar garnisonen i Menethil Keep och strävar efter att säkra Khaz Modans gränser mot gamla fiender som slagit rot i träskmarkerna.",["race:Orc"]="Dragonmaw är en splittrad och obotfärdig kvarleva från Old Horde, vars våldsamma krigshets isolerar dem från den nya Horde-ledningen i Kalimdor."},sec={{t="Ett vapenförråd i träskmarkerna",b="I Wetlands träskmarker har den fientliga Dragonmaw-klanen börjat samla på sig ett oroväckande stort vapenförråd i Dragonmaw Retreat. Om förrådet lämnas orört kan de fredlösa orcherna utrusta nya skaror krigare och inleda förödande räder mot närliggande bosättningar. Genom att avväpna deras läger slår man direkt mot deras försörjningsförmåga och hejdar varje planerad offensiv innan deras krigshärar hinner mobiliseras och gå ut i strid."},{t="Att säkra kusthamnen",b="Menethil Harbor är den främsta porten som förbinder Khaz Modan och Stormwind med havet, vilket gör all militär upprustning i närheten till ett allvarligt hot. Captain Stoutfist samordnar försvaret från Menethil Keep och håller noggrann uppsikt över de fientliga klanerna och bestarna som närmar sig staden. Genom att återta trettio uppsättningar Dragonmaw-vapen berövar man orcherna nödvändig ammunition och ger samtidigt dvärgarnas garnison viktig information om fiendens beredskap."}},faq={{q="Vem är Captain Stoutfist?",a="Captain Stoutfist är en dvärgisk officer som är stationerad i Menethil Keep och ansvarar för försvaret av Menethil Harbor och de omgivande Wetlands. Stoutfist står under ständig press från fientliga bestar, Dark Iron-sabotörer och Dragonmaw-klanen och leder aktivt soldater och äventyrare i arbetet med att slå ner närliggande hot innan hamnens viktiga försörjningslinjer och anläggningar blir översvämmade av fiender.",al={"stoutfist","vem är stoutfist","kaptenen i menethil keep"}},{q="Varför måste Dragonmaw avväpnas?",a="Dragonmaw-klanen samlar aktivt vapen i sitt tillhåll för att utrusta nya kämpar inför strid. Om de tillåts samla på sig ammunition utan motstånd kan deras krigshärar övermanna Alliansens lokala försvar och hota Menethil Harbor. Genom att beslagta trettio buntar med vapen hindrar man direkt deras logistiska förberedelser och hindrar fler orksoldater från att gå ut i strid.",al={"varför ta dragonmaws vapen","syftet med dragonmaw armaments","avväpna dragonmaw"}},{q="Var ligger Dragonmaw Retreat?",a="Dragonmaw Retreat är ett läger som Dragonmaw-orcherna har upprättat i Wetlands, österut mot bergen bortom Menethil Harbor. Klanen använder denna avskilda utpost för att samla styrkor, lagra vapen och förbereda attacker mot resande i träskmarkerna. Äventyrare måste ta sig in i lägrets hjärta för att återta vapnen de samlat på sig.",al={"dragonmaw retreats läge","var ligger dragonmaw retreat","dragonmaw retreat i wetlands"}},{q="Vad är Dragonmaw Armaments?",a="Dragonmaw Armaments är förråd med stridsutrustning, klingor och utrustning som Dragonmaw-klanen har smitt eller stulit för att förse sina krigare. Dessa vapen utgör klanens omedelbara militära kapacitet i regionen. Captain Stoutfist begär att trettio buntar av denna ammunition beslagtas och förs tillbaka till Menethil Keep för undersökning och bortskaffning.",al={"dragonmaw-vapen","vad är vapenutrustning","dragonmaw-utrustning"}},{q="Är Dragonmaw-klanen en del av Horde år tjugofem efter den mörka porten?",a="Nej, Dragonmaw-klanen i Wetlands verkar som en självständig, fientlig fraktion som inte lyder under Warchief Thrall. Orcherna är fortfarande trogna sina gamla seder efter det andra kriget, hyser ett djupt hat mot Alliansen och avvisar alla fredliga inviter. Därför betraktar både Alliansens försvarare och självständiga resande dem som dödliga fiender.",al={"tillhör dragonmaw horde","dragonmaw-klanens fraktion","dragonmaw och thrall"}},{q="Varför oroar sig Menethil Keep för Dragonmaw?",a="Menethil Keep är den administrativa och militära fästning som skyddar Menethil Harbor, Alliansens främsta sjöfartsknutpunkt i Khaz Modan. Eftersom träskmarkerna runt hamnen plågas av träskbestar och aggressiva orcher kan Captain Stoutfist inte låta ett tungt beväpnat läger som Dragonmaw Retreat växa fram så nära rikets kajer och handelsvägar.",al={"dragonmaw-hotet mot menethil keep","varför stoutfist bryr sig","försvaret av menethil harbor"}}},fp="18,389,24.469.0,25.479.0,25.398.0,41.365.0,35.362.0,29.356.0,50.362.0,50.382.0"}
P.entries["quest:98298"] = {n="Arugal's Folly",s="Arugal's Folly är ett uppdrag från Forsaken i Silverpine Forest där Dalar Dawnweaver undersöker worgenflockarnas verkliga ursprung nära The Greymane Wall. Genom att analysera insamlade worgenlämningar vill Dalar bevisa att Archmage Arugal var en bedragare som bara band varelserna, snarare än att framkalla deras förbannelse.",h="Arugal's Folly är ett uppdrag från Forsaken i Silverpine Forest där Dalar Dawnweaver undersöker...",kw={"arugal","arugal's folly","dalar dawnweaver","the greymane wall","silverpine forest","the sepulcher","worgenbitar","worgenförbannelse"},ang={["class:Mage"]="De som utövar arcane-magi kan uppskatta Dalars analytiska nedmontering av Arugals så kallade magiska förbannelse och se skillnaden mellan bindande förtrollningar och smittsamma sjukdomar.",["faction:Horde"]="Hordens äventyrare som hjälper Dalar Dawnweaver bidrar till att skydda Silverpine Forest från både vilda rovdjur på härjningståg och de närliggande mänskliga bosättningar som dukar under för sjukdomen.",["race:Undead"]="För Forsaken vid The Sepulcher är det avgörande att förstå worgenutbrottets verkliga natur i Silverpine för att skydda Lordaeron från okontrollerbara vilda hot."},sec={{t="Avslöja ärkemagikern",b="Forsaken-magikern Dalar Dawnweaver är stationerad vid The Sepulcher i Silverpine Forest och vill rasera rivalen Archmage Arugals mystik. Efter att ha undersökt förtrollade bojor drar Dalar slutsatsen att Arugal saknade den råa kraft som krävdes för att frambringa eller skapa worgenflockarna som terroriserar trakten. Arugal kunde bara använda enklare förtrollningar för att binda bestarna en kort stund, så förbannelsens verkliga mekanik och ursprung förblir ett mysterium."},{t="Bestarnas intrång",b="För att hitta konkreta bevis skickar Dalar äventyrare söderut till The Greymane Walls imponerande befästningar. I vildmarken runt muren har vilda worgen börjat angripa och smitta människor i närheten. Genom att fälla de glupska varelserna och hämta vävnadsprover ger utredarna Dalar fysiska prover som han kan analysera för att förstå sjukdomens biologiska och magiska natur."},{t="En bitter upprättelse",b="När Dalar undersöker de insamlade worgenlämningarna utropar han skadeglatt sin seger över Arugals akademiska rykte och bekräftar att ärkemagikern inte hade något med sjukdomens ursprung att göra. Men avslöjandet får en dyster följd för Forsaken: om Arugal aldrig skapade förbannelsen är de påstådda botemedel och motåtgärder han tog fram helt värdelösa, och worgenutbrottets verkliga gåta förblir olöst."}},faq={{q="Vem ger uppdraget Arugal's Folly?",a="Uppdraget ges och avslutas hos Dalar Dawnweaver, en arcane-forskare och Forsaken-magiker stationerad vid The Sepulcher i Silverpine Forest.",al={"vem ger arugal's folly","var lämnar jag in arugal's folly","uppdragsgivare arugal's folly"}},{q="Varför anser Dalar Dawnweaver att Arugal är en bedragare?",a="Dalar Dawnweaver drar slutsatsen att Archmage Arugal är en arrogant bedragare. Dalar hävdar att Arugal knappt hade tillräcklig magisk skicklighet för att tillfälligt binda worgen, snarare än att skapa dem eller ge dem deras ursprung. Därmed avslöjar han den så kallade ”Curse of Arugal” som en bluff.",al={"vad tycker dalar om arugal","skapade arugal worgen","arugal bedragare"}},{q="Var hittar du worgenbitar åt Dalar?",a="För att slutföra uppdraget reser äventyrarna söderut genom Silverpine Forest mot The Greymane Wall, där vilda worgen stryker omkring nära traktens mänskliga bosättningar. När bestarna dödas får man worgenbitarna som Dalar behöver för sin undersökning.",al={"var finns worgenbitarna","worgen vid greymane wall","vart ska jag gå i arugal's folly"}},{q="Hittar Dalar ett botemedel mot worgenförbannelsen?",a="Inget botemedel upptäcks här. Eftersom Dalar kommer fram till att Arugal inte skapade worgensjukdomen är alla botemedel eller motbesvärjelser som Arugal kokade ihop helt värdelösa. Forsaken måste söka någon annanstans efter en verklig lösning.",al={"kan worgenförbannelsen botas","fungerar arugals botemedel","finns det ett botemedel mot worgen"}},{q="Hur sprids worgensjukdomen nära The Greymane Wall?",a="Dalar noterar att worgensjukdomen verkar spridas direkt till människor i närheten av The Greymane Wall genom fysisk kontakt och bett, snarare än genom någon övergripande magisk ritual eller besvärjelse från Arugal.",al={"hur sprids förbannelsen","worgen smittar människor","vem blir smittad"}},{q="Vad drar Dalar för slutsats efter att ha undersökt worgenbitarna?",a="Undersökningen av de anatomiska delarna från dödade worgen bevisar för Dalar att deras förbannelse inte har något med Arugals trolldom att göra. Den bekräftar hans rivals magiska inkompetens, men också att worgenförbannelsen fortfarande är ett aktivt, oförklarat hot utan fungerande motgift.",al={"vad lär sig dalar av bitarna","slutsats arugal's folly","avslöjandet i arugal's folly"}}},fp="14,316,21.476.0,21.440.0,20.435.1,35.143.0,50.256.0,44.244.0,44.255.0,62.233.0,58.282.0"}
P.entries["quest:98299"] = {n="Stop the Spread",s="Stop the Spread är ett uppdrag i Silverpine Forest som handlar om att begränsa worgenförbannelsen med koppling till ärkemagikern Arugal. Medan forskare söker ett sätt att hejda smittan beordras förebyggande åtgärder mot levande mänskliga flyktingar vid The Greymane Wall, så att de inte förvandlas till Arugals tjänare.",h="Stop the Spread är ett uppdrag i Silverpine Forest som handlar om att begränsa worgenförbannelsen med...",kw={"arugal","förbannelse","forsaken","the greymane wall","flyktingar","silverpine","himmelsburna","stop the spread","worgen"},ang={["race:Human"]="Forsaken-forskare ser de oinfekterade mänskliga flyktingarna som kurar ihop sig vid The Greymane Walls förseglade portar som perfekta smittspridare för Arugals förbannelse.",["race:Skyborne"]="Äventyrare från himlen varnas uttryckligen för att bli bitna när de utför de dystra begränsningsorderna nära The Greymane Wall.",["race:Undead"]="Forsaken verkar vara unikt immuna mot worgensmittan, vilket gör begränsningsinsatser möjliga utan infektionsrisk för de odöda styrkorna."},sec={{t="Smittan i Silverpine",b="I Silverpine Forest sprids worgenplågan av den avfällige ärkemagikern Arugal. De exakta metoderna och mekanismerna bakom detta vilda tillstånd är fortfarande till stor del okända, men faran för området är obestridlig. Forskare arbetar aktivt med att förstå magins natur, men deras omedelbara fokus är att hindra Arugal från att samla en ostoppbar här av vilda anhängare."},{t="Begränsning vid muren",b="Forsaken-utredare har sett att deras odöda fysiologi gör dem immuna mot worgeninfektionen. Levande människor har däremot inget sådant naturligt försvar. Vid den södra gränsen har ett desperat läger med mänskliga flyktingar samlats kring The Greymane Walls låsta portar. Av rädsla för att dessa försvarslösa överlevande ska bli bitna och förvandlas till Arugals lojala trälar har förebyggande och skoningslösa begränsningsorder utfärdats, för att rensa bort folksamlingen innan smittan får tag i dem."}},faq={{q="Vad handlar uppdraget Stop the Spread om?",a="Stop the Spread är ett uppdrag som går ut på att begränsa worgenförbannelsen som härjar i Silverpine Forest. För att hindra ärkemagikern Arugal från att få fler tjänare skickas styrkor ut för att undanröja mänskliga flyktingar nära The Greymane Wall innan de dukar under för smittan.",al={"vad är stop the spread","stop the spread uppdragslore"}},{q="Vem bär ansvaret för worgen i Silverpine?",a="Ärkemagikern Arugal hålls ansvarig för worgen i Silverpine Forest, vare sig de är resultatet av hans avsiktliga planer eller oförutsedda följder av hans magi. Hans växande flock hotar hela regionen.",al={"vem sprider worgenförbannelsen","arugals koppling till worgen"}},{q="Kan Forsaken smittas av worgenförbannelsen?",a="Enligt lokala Forsaken-forskares rön kan worgenförbannelsen inte smitta de odöda. Denna immunitet gör att Forsaken-agenter kan bekämpa hotet utan risk att förvandlas till bestialiska tjänare åt Arugal.",al={"kan forsaken bli worgen","är odöda immuna mot worgen"}},{q="Varför är mänskliga flyktingar vid The Greymane Wall måltavlor?",a="En stor grupp mänskliga flyktingar har samlats utanför The Greymane Walls förseglade portar. Eftersom levande människor är mottagliga för Arugals förbannelse anses de utgöra ett överhängande hot, då de kan öka worgenhordens antal.",al={"varför döda flyktingar","flyktingar vid greymane wall"}},{q="Hur sprids worgensmittan?",a="Det är känt att worgenförbannelsen kan överföras genom bett, men de exakta magiska och biologiska mekanismerna bakom smittspridningen undersöks fortfarande av forskare i Silverpine Forest.",al={"hur sprids worgen","worgenförbannelsens smittspridning"}},{q="Finns det något sätt att hejda eller bota worgenförbannelsen?",a="För närvarande finns det inget känt botemedel mot worgensmittan. Forskare försöker hitta ett sätt att hejda förbannelsen, men deras omedelbara prioritet är fortfarande kraftfulla begränsningsåtgärder.",al={"kan worgenförbannelsen botas","botemedel mot worgen"}}},fp="15,307,25.434.0,23.511.1,40.259.0,48.223.0,40.203.0,59.218.0,38.201.0,48.189.0"}
P.entries["quest:983"] = {n="Buzzbox 827",s="Buzzbox 827 är den första i en experimentell kommunikationskedja som gnomen Wizbang Cranktoggle byggt längs Darkshores kust. De märkliga mekaniska apparaterna drabbas ofta av haverier och bygger på en excentrisk konstruktion som använder delar från det lokala djurlivet vid fältreparationer. När den tysta maskinen återställs kan Wizbang testa sitt långdistansnät för röstsändningar direkt från Auberdine.",h="Buzzbox 827 är den första i en experimentell kommunikationskedja som gnomen Wizbang Cranktoggle byggt längs...",kw={"auberdine","buzzbox 827","crawler legs","darkshore","gnomisk ingenjörskonst","reef crawler","tide crawler","wizbang cranktoggle"},ang={["profession:Engineering"]="Att använda organiskt kitin och leddjurslemmar i stället för smidda kugghjul av mässing är typiskt för gnomisk improvisationsförmåga: hållbarhet byts mot lättillgängliga material från närområdet.",["race:Gnome"]="Wizbangs apparat står för klassisk gnomisk ambition och försöker föra teknisk uppkoppling till ett forntida, otämjt land som aldrig har sett en telefon eller radio.",["race:NightElf"]="De skramlande, rykande Buzzboxarna är en bisarr skamfläck vid Kalimdors heliga, dystra stränder, men nattalverna i Auberdine tolererar uppfinnarens experiment."},sec={{t="Gnomisk uppfinningsrikedom vid forntida stränder",b="Under ett besök i Auberdine ville den excentriske gnomiske ingenjören Wizbang Cranktoggle överbrygga de långa avstånden längs den vilda kusten med en serie långdistansreläer för ljudöverföring, kallade Buzzboxes. De här spakförsedda apparaterna är utformade för att överföra röster över långa avstånd och står i skarp kontrast till Darkshores forntida ruiner och dystra skogar. Men likt många ambitiösa gnomiska uppfinningar lider de av kronisk instabilitet och kräver nästan ständig skötsel för att hålla kugghjulen i gång."},{t="Ekologiskt underhåll",b="I stället för att släpa förädlade järnkugghjul och kopparstift genom vildmarken valde Wizbang en okonventionell lösning: han byggde varje Buzzbox så att den kunde servas med delar från närliggande inhemska djur. Buzzbox 827, placerad strax söder om Auberdine längs den dimmiga strandlinjen, konstruerades för att fungera med de kraftiga, ledade benen från lokala tidvatten- och revkrypare. När benen läggs i mottagarfacket sätter maskinen ihop sig själv och vaknar till liv igen, så att Wizbangs avlägsna röst hörs ur högtalarna."}},faq={{q="Vad är en Buzzbox?",a="En Buzzbox är en långdistansmaskin för röstkommunikation som uppfunnits av gnomen Wizbang Cranktoggle. Den är utrustad med spakar och ett inre maskineri och utformad för att överföra röster över Darkshores otämjda vidder, så att folk kan tala med varandra över flera mil.",al={"vad gör en buzzbox","buzzboxens syfte","gnomisk låda darkshore"}},{q="Varför behöver en metallmaskin krabbben för att fungera?",a="Wizbang konstruerade med flit varje Buzzbox för att använda organiska delar från det omgivande djurlivet som provisoriska reservdelar. Genom att placera Buzzbox 827 nära stranden där krypare lever såg han till att resande kunde utföra akuta mekaniska reparationer med kitinösa lemmar i stället för sällsynt bearbetad metall.",al={"varför crawler legs","reparation med crawler leg","varför mata in ben"}},{q="Var finns Buzzbox 827?",a="Buzzbox 827 står längs Darkshores strandlinje, bara en kort vandring söder om kustbosättningen Auberdine.",al={"buzzbox 827 plats","var finns buzzbox 827","hitta buzzbox 827"}},{q="Vem är Wizbang Cranktoggle?",a="Wizbang Cranktoggle är en gnomisk uppfinnare som bor på övervåningen i värdshuset i Auberdine. Ambitiös och företagsam försöker han bygga ett sammankopplat kommunikationsnät över Darkshore, trots att hans prototyper ständigt krånglar.",al={"wizbang cranktoggle","vem byggde buzzbox","gnom i auberdine"}},{q="Var hittar jag Crawler Legs till reparationen?",a="Crawler Legs kan samlas in från Pygmy Tide Crawlers och Young Reef Crawlers som kilar omkring i sanden och det grunda vattnet längs Darkshores strand, strax söder om Auberdine.",al={"crawler leg plats","hur får man crawler legs","pygmy tide crawler"}},{q="Vad händer när Buzzbox 827 har reparerats?",a="När Crawler Legs matats in i facket bearbetar maskinen dem på plats, börjar surra igen och förmedlar Wizbangs röst från Auberdine. Han är nöjd med resultatet och ber dig genast resa längre längs kusten för att reparera nästa enhet i kedjan, Buzzbox 411.",al={"efter buzzbox 827","nästa del av buzzbox-uppdraget","buzzbox 827 klar"}}},fx={aa80bf26={q="Varför vill Wizbang Cranktoggle att Buzzbox 827 repareras?",a="Wizbang Cranktoggle testar sin senaste uppfinning: ett experimentellt kommunikationsnät över Darkshore som låter folk tala med varandra på långt håll. Tyvärr kräver hans buzzboxar ständigt underhåll och går ofta sönder. Att få Buzzbox 827 att fungera är första steget mot att bevisa att nätverket faktiskt fungerar.",al={"wizbang cranktoggles motiv","varför laga buzzbox 827","varför vill wizbang att detta görs"}},["2c1df07a"]={q="Vad används Crawler Legs till?",a="Wizbang konstruerade varje buzzbox så att den använder delar från det inhemska djurlivet i närheten. Buzzbox 827 behöver särskilt sex Crawler Legs för att ersätta slitna eller trasiga mekaniska delar i hållaren. När de satts in mal och passar enhetens inre kugghjul in benen på plats, så att ström och överföring återställs.",al={"vad används crawler legs till","crawler leg till buzzbox","varför crawler legs"}}},fp="11,235,36.349.0,22.410.0,18.189.0,47.198.0,29.67.0,27.169.0,45.165.0,42.226.1"}
P.entries["quest:98319"] = {n="Secure the Mountain",s="Secure the Mountain är ett uppdrag för Alliansen om hur ett plötsligt stort antal wendigos har tagit över The Grizzled Den i Dun Morogh. Äventyrare skickas in i den angripna grottan för att hitta en överentusiastisk dvärgspanare vid namn Cornelius och hämta en viktig rapport åt Whitebeard.",h="Secure the Mountain är ett uppdrag för Alliansen om hur ett plötsligt stort antal wendigos har tagit över The...",kw={"cornelius","dun morogh","the grizzled den","bergsbestigare","secure the mountain","troll","wendigo","whitebeard"},ang={["faction:Alliance"]="Det är viktigt att se till att Whitebeard får underrättelserapporterna, så att Alliansens styrkor kan upprätthålla gränssäkerheten mot de inhemska hoten i bergen.",["race:Dwarf"]="När grottor som The Grizzled Den återtas skyddas dvärgarnas bergsbestigare och resenärer från aggressiva wendigos som tränger in på Dun Moroghs vägar."},sec={{t="En grotta översvämmad av wendigos",b="Dvärgspanare som bevakar de iskalla bergssluttningarna har problem från två håll. Utöver det ständiga hotet från Frostmane-troll har de lokala wendigosarna börjat föröka sig snabbt. De lämnar sina vanliga, ensliga hålor och trängs i The Grizzled Den norrut. De här vildsinta bestarna gör färder genom bergsklipporna farliga för både patruller och kurirer."},{t="Dumdristigt mod",b="En spanare vid namn Cornelius rusade rakt in i The Grizzled Den för att hämta en viktig rapport som skulle till Whitebeard. Hans impulsiva mod lämnade hans partner strandsatt utanför, på jakt efter dugliga äventyrare som vågar ta sig in i den besttäta grottan, leta reda på den dumdristiga dvärgen och minska antalet våldsamma wendigos."}},faq={{q="Vem är Cornelius?",a="Cornelius är en spanare eller bergsbestigare som arbetar med uppdragsgivaren. Drivna av dumdristigt mod rusade han rakt in i The Grizzled Den, som kryllar av wendigos, och lämnade sin partner utanför i väntan på hjälp med att hitta honom och hämta Whitebeards rapport.",al={"vem är cornelius","dvärgen cornelius","var är cornelius"}},{q="Vad är The Grizzled Den?",a="The Grizzled Den är en grotta norr om bergsbestigarnas utpost. Wendigos brukar hålla sig i avlägsna berghålor, men på senare tid har de tagit över grottan i ovanligt stort antal.",al={"vad är grizzled den","var finns wendigos","wendigogrotta dun morogh"}},{q="Varför sprider sig wendigos?",a="Wendigos brukar hålla till i avlägsna grottor, men lokala spanare har lagt märke till att de förökar sig och sprider sig snabbt över de snöiga bergsklipporna. Tillsammans med det lokala trollhotet utgör de en allvarlig fara.",al={"varför sprider sig wendigos","wendigoproblem dun morogh","wendigos förökar sig snabbt"}},{q="Vem är Whitebeard och vad gäller rapporten?",a="Whitebeard är en befälhavare eller annan auktoritet som väntar på en viktig spaningsrapport om förhållandena i bergen. Cornelius bar med sig rapporten när han dumdristigt rusade in i grottan.",al={"vem är whitebeard","whitebeards rapport","senir whitebeard"}},{q="Vad är målet med Secure the Mountain?",a="Det är ett räddnings- och utrensningsuppdrag där äventyrare ska gå in i The Grizzled Den, hitta den försvunne spanaren Cornelius och minska antalet fientliga wendigos som angripit grottan.",al={"vad är secure the mountain","målet med secure the mountain"}},{q="Hur bidrar trollen till problemen i bergen?",a="Lokala spanare utsätts redan för ett ihållande tryck från Frostmane-troll som hör hemma bland bergstopparna. Den plötsliga ökningen av aggressiva wendigos skapar ett farligt hot från två håll för patruller som försöker säkra bergspassen.",al={"troll dun morogh","trollhot"}}},fp="19,269,13.358.0,14.321.0,17.251.0,25.196.0,31.204.0,41.195.0,40.177.0,54.215.0"}
P.entries["quest:98321"] = {n="Flintfire's Shipment",s="Tognus Flintfire i Kharanos har akut brist på förnödenheter sedan vilda wendigos tagit över hans främsta malmkälla vid Grizzled Den. Gruvarbetarna tvingades lämna sina lådor under evakueringen, och nu får äventyrare i uppdrag att hämta de förlorade lasterna så att de lokala smedjorna kan hållas igång.",h="Tognus Flintfire i Kharanos har akut brist på förnödenheter sedan vilda wendigos tagit över hans främsta...",kw={"dun morogh","flintfire","smedja","the grizzled den","kharanos","gruvarbetare","malm","leveranser","tognus flintfire","wendigo"},ang={["profession:Blacksmithing"]="Att återfinna Flintfires leveranser är avgörande för att förse smedjorna i Kharanos med bearbetbar metall.",["profession:Mining"]="De förlorade leveranserna består av viktig malm som gruvarbetarna lämnade kvar när de evakuerade sin främsta gruva under wendigornas attack.",["race:Gnome"]="Tognus Flintfire välkomnar särskilt gnomäventyrare som är villiga att utföra tungt kroppsarbete i Dun Morogh, och visar uppriktig uppskattning för deras uthållighet."},sec={{t="En försörjningskris i Kharanos",b="I den snöiga bosättningen Kharanos står Tognus Flintfire inför en allvarlig försörjningskris vid sin smedja. Områdets mest produktiva och pålitliga malmkälla har plötsligt tystnat efter att vilda wendigos invaderat gruvan. Gruvarbetarna överrumplades av de våldsamma rovdjuren och tvingades lämna sina poster utan förvarning, fly för sina liv och lämna nyfyllda lådor med värdefull malm utspridda över grottans golv."},{t="In i Grizzled Den",b="Den övertagna gruvan Grizzled Den ligger väster om Kharanos. Tognus är tacksam över att alla gruvarbetare lyckades undkomma de våldsamma bestarna oskadda, men arbetsstoppet hotar att helt lamslå den lokala smidesverksamheten. I stället för att vänta på en beväpnad expedition som röjer grottan söker Tognus modiga äventyrare som kan smyga in i wendigornas håla, samla ihop lådorna som lämnats kvar och föra den viktiga malmen tillbaka till smedjan."}},faq={{q="Vem är Tognus Flintfire?",a="Tognus Flintfire är en dvärg i Kharanos som behöver regelbundna leveranser av bruten malm för att hålla sin smedja igång. Efter att wendigos tagit över hans främsta gruva råder det akut brist på förnödenheter, så han ber resande att trotsa faran och hämta de övergivna lådorna.",al={"vem är tognus flintfire","tognus flintfire","uppdragsgivare"}},{q="Var ligger Grizzled Den?",a="Grizzled Den är ett grottsystem väster om Kharanos i Dun Morogh. Den var tidigare en pålitlig gruva, men är nu en håla för vilda wendigos. Den som söker den förlorade malmen måste därför ge sig in på fientligt territorium.",al={"var ligger grizzled den","grizzled den plats","var hittar man leveranserna"}},{q="Varför övergavs gruvan?",a="Grottan var de lokala gruvarbetarnas pålitligaste malmkälla tills fientliga wendigos invaderade och tog över platsen. Arbetarna tvingades släppa sin utrustning och de lagrade leveranserna i en desperat flykt, men lyckades mirakulöst nog ta sig ut levande.",al={"varför flydde gruvarbetarna","vad hände med gruvan","wendigoattack"}},{q="Vad finns i de saknade leveranserna?",a="Leveranserna består av bruten malm som gruvarbetarna packade i lådor innan de drevs ut. Utan materialet stannar den lokala metallbearbetningen och smidesverksamheten i Kharanos helt.",al={"vad är flintfires leveranser","vad finns i lådorna","leveransernas innehåll"}},{q="Skadades några gruvarbetare i attacken?",a="Wendigorna var skrämmande våldsamma, men Tognus konstaterar lättat att alla gruvarbetare lyckades ta sig oskadda ut ur Grizzled Den och bara lämnade sina förnödenheter och sin malm bakom sig.",al={"överlevde gruvarbetarna","dödsoffer bland gruvarbetarna","wendigooffer"}},{q="Vad händer när leveranserna har återfunnits?",a="När leveranserna har säkrats får Tognus Flintfire den råmetall som behövs för att få fyr i den lokala smedjan och åter sätta den i drift, utan att först behöva röja hela den angripna grottan.",al={"varför behövs malm","vad händer efter återfyndet","smedjan i drift"}}},fp="20,302,27.462.0,31.435.0,24.270.0,34.235.0,34.255.0,37.209.0,42.189.0,46.204.0"}
P.entries["quest:98322"] = {n="Secure the Mountain",s="Secure the Mountain är ett uppdrag för Alliansen som börjar i Kharanos i Dun Morogh. En lokal tjänsteman som sammanställer underrättelser åt Ironforge skickar äventyrare väster om staden för att undersöka hur det går för Mountaineer Gretchen, efter att spanare som undersökte aggressiva wendigoer inte återvänt.",h="Secure the Mountain är ett uppdrag för Alliansen som börjar i Kharanos i Dun Morogh.",kw={"dun morogh","dvärg","ironforge","kharanos","mountaineer gretchen","secure the mountain","wendigo","whitebeard"},ang={["faction:Alliance"]="När du hjälper de lokala dvärgpatrullerna runt Kharanos stärks samordningen av försvaret i det snötäckta hjärtat av Khaz Modan.",["race:Dwarf"]="Bergsspanarna i Dun Morogh patrullerar vaksamt snöiga åsar och förrädiska grottor. Tillförlitlig spaning är avgörande för att hålla dvärgarnas bosättningar säkra."},sec={{t="En försenad rapport",b="En tjänsteman i Kharanos har i uppdrag att sammanställa lokal militär underrättelse åt Ironforges högsäte, men hans rutinmässiga korrespondens avbryts. Ett bergsspanarteam som skickats för att bedöma aktiviteten bland närliggande wendigoer har inte återvänt med uppdateringar. I stället för att själv utforska iskalla grottor ber byråkraten dugliga resenärer att bege sig strax väster om staden och ta reda på hur det står till med spanarna."},{t="Oro på den västra åsen",b="När Mountaineer Gretchen spåras upp väster om Kharanos byts den lugna rutinen med regional bevakning mot oro. Gretchen bekräftar att Whitebeards förfrågningar nått henne, men avslöjar att oron bland wendigoerna i de omgivande bergsklipporna är långt mer våldsam än de första rapporterna antydde. Det bäddar för vidare spaning i den närliggande vildmarken."}},faq={{q="Vem ger uppdraget Secure the Mountain?",a="Uppdraget ges av Senir Whitebeard i Kharanos, som Mountaineer Gretchen kallar ”Ol' Whitebeard”. Hans uppgift är att sammanställa officiella rapporter om hoten i den lokala vildmarken och skicka dem till dvärgarnas ledning i Ironforge.",al={"vem ger secure the mountain","uppdragsgivare för secure the mountain","vem startar secure the mountain"}},{q="Var hittar man Mountaineer Gretchen?",a="Mountaineer Gretchen är stationerad strax väster om staden Kharanos i Dun Morogh. Hon håller uppsikt över hotet från wendigoer vid bergssidorna och grottorna i närheten.",al={"var är gretchen","mountaineer gretchens plats","hitta mountaineer gretchen"}},{q="Varför letar uppdragsgivaren efter Mountaineer Gretchen?",a="Uppdragsgivaren ansvarar för att skicka underrättelser till Ironforge, men spanaren som skickats för att undersöka wendigoaktiviteten i området har inte rapporterat tillbaka i tid. Han ligger efter i arbetet och vill undvika att utforska farliga grottor, så han ber en äventyrare på genomresa att se till Mountaineer Gretchen.",al={"varför skicka en äventyrare","varför behöver whitebeard hjälp","varför kontrollera hur det går för gretchen"}},{q="Vilket problem med wendigoer hotar området?",a="Wendigoer håller till i de klippiga bergssluttningarna och mörka grottorna runt Kharanos. Deras aggressiva närvaro utgör ett direkt hot mot resenärer och lokala utposter, så spanare från Ironforge håller noga koll på deras rörelser.",al={"wendigohotet mot kharanos","vad gör wendigoerna","varför är wendigoerna ett problem"}},{q="Vad rapporterar Mountaineer Gretchen när man kommer fram?",a="När du når Mountaineer Gretchen väster om staden bekräftar hon att hon fått Whitebeards förfrågningar och konstaterar bistert att hela situationen med de närliggande wendigoerna har blivit ett rejält elände.",al={"vad säger gretchen","lämna in secure the mountain","gretchens lägesrapport"}},{q="Vilken roll har bergsspanare runt Kharanos?",a="Bergsspanare är Ironforgedvärgarnas främsta gränsvakter, spårare och spaningsstyrkor. De bevakar avlägsna pass, mörka grottor och snöiga leder i Dun Morogh för att skydda städer som Kharanos.",al={"vilka är bergsspanarna","ironforges bergsspanarpatrull","vad gör bergsspanare"}}},fp="19,263,17.400.0,28.377.1,40.242.0,40.162.0,55.298.0,45.217.0,51.195.0,47.205.0"}
P.entries["quest:98323"] = {n="Secure the Mountain",s="Secure the Mountain är en spaningsrapport som Mountaineer Gretchen skickar till Senir Whitebeard i Kharanos. Efter en katastrofal expedition till en närliggande grotta bedömer Gretchen att grottan är förlorad och vägrar skicka fler spejare in i den övertagna dödsfällan. Uppdraget visar hur Ironforges bergsvakter fortsätter kämpa för att hålla Dun Morogh tryggt när hoten växer.",h="Secure the Mountain är en spaningsrapport som Mountaineer Gretchen skickar till Senir Whitebeard i Kharanos.",kw={"grotta","cornelius","dun morogh","kharanos","mountaineer gretchen","mountaineers rapport","secure the mountain","senir whitebeard"},ang={["faction:Alliance"]="Att säkra de höga passen runt Ironforge är avgörande för trygga resor och försvar i Alliansens snöiga fäste i Khaz Modan.",["race:Dwarf"]="Dun Morogh är Bronzebeard-dvärgarnas uråldriga bergshem, så Mountaineer Gretchens envisa vakthållning är avgörande för att skydda hennes folk mot farorna omkring dem."},sec={{t="En dyster rapport",b="Mountaineer Gretchen är utposterad bland de iskalla topparna i Dun Morogh och håller vakt med order om att säkra de höga passen. Men en färsk utflykt till en närliggande grotta visar att vildmarken långt ifrån är pacificerad. Efter att ha bedömt läget drar Gretchen slutsatsen att grottan har blivit en dödsfälla, översvämmad av fientliga byrackor. I stället för att riskera fler liv stannar hon på sin post i sluttningarna, fast besluten att hålla stånd medan hon skickar ett sändebud med sin skriftliga bedömning."},{t="Förluster i djupet",b="Beslutet att avbryta fler intrång i grottan följer på ett kostsamt offer. Bland offren för den misslyckade spaningen fanns Cornelius, vars död tynger Mountaineer Gretchen. Hon medger att grottan inte kan återtas under rådande förhållanden och beordrar att alla ytterligare utforskningsuppdrag i de underjordiska gångarna ska upphöra. Hennes prioritet skiftar från offensiv rensning till defensiv inneslutning, och hon vägrar offra fler spejare i onödan åt de skoningslösa varelserna som lurar under de snötäckta branterna."},{t="Senir Whitebeards akt",b="I den livliga bosättningen Kharanos håller Senir Whitebeard reda på de många faror som hotar dvärgarnas hjärtland. När han får Gretchen dystra bedömning blir Whitebeard föga förvånad över beskedet att grottan är helt övertagen. Han har accepterat den bistra verklighet som Dun Morogh står inför och viker tyst ihop Gretchens brev och lägger det i sin växande hög med fältrapporter. Uppgifterna blir ännu ett nedslående dokument i Ironforges större arbete med att kartlägga och hantera den oroliga gränsmarken."}},faq={{q="Vem är Mountaineer Gretchen?",a="Mountaineer Gretchen är en vaktpost från Ironforge, utstationerad i Dun Moroghs snöiga vildmark. Hon är hängiven sin plikt och vägrar lämna sin post på berget förrän det omgivande området bedöms vara säkert. Efter ett dödligt spaningsuppdrag i en närliggande grotta skriver hon en officiell fältrapport om den stora fiendenärvaron och skickar den till Kharanos.",al={"gretchen","bergsvakten gretchen i berättelsen","vem är gretchen"}},{q="Vem är Senir Whitebeard?",a="Senir Whitebeard är en dvärgisk myndighetsperson stationerad i staden Kharanos. Han samlar in underrättelser och samordnar lokala säkerhetsinsatser i Dun Morogh, och tar emot rapporter och spaningsbedömningar från bergsvakter i fält. När han får veta om farliga fiendeintrång eller grottor som gått förlorade arkiverar han rapporterna i sina officiella handlingar för att bedöma hotnivån i regionen.",al={"senir whitebeard","whitebeard kharanos","vem är senir"}},{q="Vem var Cornelius?",a="Cornelius var en medarbetare eller medspejare som deltog i utforskningen av den angripna grottan på berget. Mountaineer Gretchen nämner hans tragiska öde med sorg, vilket tyder på att han omkom under det olycksaliga spaningsuppdraget. Hans död påverkade direkt Gretchens beslut att kalla grottan en dödlig dödsfälla och förbjuda att fler liv slösades där inne.",al={"cornelius","vem är cornelius","vad hände med cornelius","cornelius secure the mountain"}},{q="Vad hände i bergsgrottan?",a="Utforskningen av grottan slutade i katastrof när spejarna upptäckte att gångarna var helt övertagna av fientliga byrackor. Uppdraget ledde till att Cornelius tragiskt gick förlorad. Efter denna dystra upptäckt förklarade Mountaineer Gretchen den underjordiska passagen för förlorad och slog fast att det vore självmord att skicka in mer personal. I stället valde hon att spärra av eller undvika området.",al={"vad finns i grottan","varför är grottan en dödsfälla","grottan är förlorad"}},{q="Varför vägrar Gretchen lämna sin post?",a="Mountaineer Gretchen tar sin ed att skydda Dun Morogh på allvar och säger bestämt att hon inte tänker lämna sin position förrän själva berget är säkert. Hon inser att den närliggande grottan är för farlig att återta, men stannar ändå på de snöiga höjderna för att vakta tillfartsvägen och hålla utkik medan hon skickar besked om hotet till Kharanos.",al={"varför stannar gretchen","gretchens post","varför stanna på berget"}},{q="Hur reagerar Senir Whitebeard på Gretchens rapport?",a="Senir Whitebeard blir knappast förvånad över att höra att grottan är helt övertagen, vilket antyder att sådana fientliga angrepp blivit alltför vanliga i Dun Morogh. Han reagerar inte med bestörtning, utan tar stoisk emot de dåliga nyheterna och lägger Gretchens skriftliga rapport i sin växande hög med anteckningar. Han för noggranna register över farorna som hotar riket.",al={"senirs reaktion","whitebeards reaktion på rapporten","vad gör senir"}},{q="Vilken roll har bergsvakterna i Dun Morogh?",a="Bergsvakterna fungerar som Ironforges vaksamma gränsspejare och gränsvakter. De patrullerar Dun Moroghs förrädiska snötäckta toppar, höga leder och bergspass. Dessa härdade dvärgar är stationerade långt från huvudstadens värme och håller uppsikt över fientliga bestars rörelser, spanar i grottor och rapporterar viktig information till lokala knutpunkter som Kharanos för att skydda resande och bosättningar.",al={"ironforges bergsvakter","vad är bergsvakter","dvärgarnas bergsvakter i berättelsen"}}},fp="19,408,13.521.0,20.537.1,26.515.0,28.375.0,24.401.0,18.390.0,35.405.0,43.359.0,53.378.0,49.403.0"}
P.entries["quest:98326"] = {n="Frosthowl",s="Frosthowl är ett uppdrag i Dun Morogh där äventyrare ska återta en stulen säck fisk från en tjuvaktig wendigo. Odjuret överföll en lokal dvärgisk fiskare och flydde in i djupet av The Grizzled Den.",h="Frosthowl är ett uppdrag i Dun Morogh där äventyrare ska återta en stulen säck fisk från en tjuvaktig wendigo.",kw={"dun morogh","frosthowl","frusen sjö","the grizzled den","isfiske","paxton","stulen fisk","wendigo"},ang={["faction:Alliance"]="Det är upp till lokala äventyrare i Alliansen att hålla de isiga stigarna och fiskeplatserna nära Brewnall och Kharanos trygga från aggressiva rovdjur.",["race:Dwarf"]="Härdade dvärgiska fiskare uthärdar den bitande kylan vid Dun Moroghs frusna sjöar. Wendigoattacker är ett ständigt hot mot ortsborna och deras försörjning."},sec={{t="En stulen fångst",b="Isfiske i Dun Moroghs iskalla vatten är ett slitsamt och bistert arbete. En dvärgisk fiskare och hennes make Paxton tillbringade dagar ute på den frusna sjön och trotsade bitande vindar för att få ihop en enda säck fisk. Deras hårda arbete blev plötsligt ogjort när Frosthowl, en hotfull och dånande wendigo, överföll lägret och försvann med hela fångsten ut i den snötäckta vildmarken."},{t="The Grizzled Dens skränfock",b="Frosthowl är ingen vanlig asätare. Odjuret är ökänt för sina dånande vrål som får isen att skaka och skrämmer bort sjöns fåtaliga fiskar. Efter att ha stulit fiskarens säck drog sig den dreglande varelsen djupt in i de mörka tunnlarna i The Grizzled Den åt sydost. De strandsatta fiskarna är nu desperata efter någon som vågar möta monstret och återta deras stulna egendom."}},faq={{q="Vem är Frosthowl?",a="Frosthowl är en högljudd och aggressiv wendigo som håller till i Dun Morogh. Odjuret är känt för att ryta och terrorisera de frusna vattendragen och anföll nyligen en lokal dvärgisk fiskare för att stjäla den fångst som hennes make slitit hårt för att få ihop.",al={"vem är frosthowl","vad är frosthowl","frosthowl wendigo"}},{q="Var finns Frosthowl?",a="Frosthowl har tagit sin tillflykt djupt inne i The Grizzled Den, ett grottsystem sydost om den frusna sjön där Paxton fiskar.",al={"var finns frosthowl","frosthowls plats","var gömmer sig wendigon"}},{q="Vad stal Frosthowl?",a="Frosthowl överföll en dvärgisk fiskare och stal en hel säck fisk som hennes make Paxton hade tillbringat dagar med att fånga i den frusna sjön. Äventyrare ombeds att spåra upp odjuret och återta den stulna fångsten.",al={"vad stal frosthowl","varför döda frosthowl","vad tog wendigon"}},{q="Vem är Paxton?",a="Paxton är en dvärgisk fiskare som tillbringade dagar ute på den frusna sjön i hopp om en blygsam fångst. Hans fru ber förbipasserande resenärer att spåra upp Frosthowl efter att odjuret stulit deras enda säck fisk.",al={"vem är paxton","paxton dun morogh","paxton fiskare"}},{q="Vad är The Grizzled Den?",a="The Grizzled Den är ett känt tillhåll för wendigor sydost om den frusna sjön i Dun Morogh. Det är en mörk tillflykt där odjur som Frosthowl kan samla kött från asätande och stulna förnödenheter.",al={"vad är the grizzled den","wendigogrotta the grizzled den","var bor wendigor i dun morogh"}},{q="Varför heter odjuret Frosthowl?",a="Wendigon kallas en skränfock vars dånande vrål och tjut ekar över de snötäckta slätterna. Ljuden hotar att skrämma bort fiskarna och terroriserar alla som arbetar vid de frusna sjöarna.",al={"hur fick frosthowl sitt namn","varför kallas den frosthowl","högljudd wendigo"}}},fp="9,205,13.383.0,33.394.0,17.220.0,29.135.0,25.209.0,14.211.0,25.197.0,33.187.0"}
P.entries["quest:98341"] = {n="The Great Windborne Cat Spirit",s="The Great Windborne Cat Spirit är en helig mentor från riket Zephras, som visar sig som Saeyleenans avatar i Moonglade. Den vägleder unga shen'dorei-druider genom deras andliga prövning, så att de kan anta sitt avlägsna hemlands vindburna kattgestalt.",h="The Great Windborne Cat Spirit är en helig mentor från riket Zephras, som visar sig som Saeyleenans avatar i...",kw={"kattgestalt","kattande","druidprövning","moonglade","saeyleenan","shen'dorei","vindburen katt","zephras"},ang={["class:Druid"]="Druider från Zephras umgås med den vindburna kattanden för att bemästra sin kattgestalt och fullgöra en rit som är anpassad till deras unika arv, snarare än följa Azeroths traditionella väg.",["race:Skyborne"]="Druiderna kallas shen'dorei och vägleds av andarna från sitt hemland Zephras i stället för att anta Azeroths inhemska former."},sec={{t="En besökare från Zephras",b="I Moonglades heliga helgedom har en ande från det avlägsna riket Zephras visat sig söder om tvillingbroarna. Den kallar sig Saeyleenans avatar och har korsat över till Azeroth för att vägleda och undervisa unga shen'dorei-druider som är redo att låsa upp sin kattgestalt."},{t="Den vindburna gestaltens natur",b="Alla druider söker så småningom kattgestaltens visdom, men de från Zephras följer en tradition som skiljer sig från Azeroths ursprungsbefolkningars. I stället för att anta en vildkatts gestalt från Azeroth antar shen'dorei sitt hemlands vindburna rovdjursform. För att se till att de förstår dess andliga natur övervakar Saeyleenan själv deras prövning i Moonglade."}},faq={{q="Vem är The Great Windborne Cat Spirit?",a="Den vindburna kattanden visar sig som Saeyleenans avatar, en ande från shen'doreis avlägsna hemland Zephras. Den har rest till Moonglade för att vägleda och pröva unga shen'dorei-druider som vill anta dess kattgestalt.",al={"vem är den vindburna kattanden","vad är saeyleenans avatar","saeyleenans bakgrund"}},{q="Var finns Saeyleenans avatar?",a="Andens avatar visar sig i Moonglades södra delar, strax söder om tvillingbroarna.",al={"var hittar man kattanden i moonglade","saeyleenans avatars plats","den vindburna kattens plats"}},{q="Varför umgås druider från Zephras med en annan kattande?",a="Eftersom shen'dorei-druider kommer från Zephras återspeglar deras kattgestalt hemlandets vindburna andar snarare än Azeroths inhemska stora kattdjur. Anden övervakar personligen deras prövning för att se till att de verkligen antar dess väsen.",al={"varför ser kattgestalten annorlunda ut","skillnaden mellan kattgestalter från zephras","varför inte azeroths kattande"}},{q="Vad går den vindburna kattens prövning ut på?",a="Saeyleenans avatar låter den blivande druiden genomgå Azeroths Great Cat Spirits prövning, samtidigt som den själv övervakar och bekräftar att druiden förstår den vindburna andens unika natur.",al={"vilken prövning ger kattanden","zephras kattandes prövning","hur får man den vindburna kattgestalten"}},{q="Vad syftar shen'dorei på?",a="Saeyleenans avatar tilltalar den blivande druiden som shen'dorei, vilket anger att hen kommer från Zephras och skiljer hens arv och andliga sedvänjor från Azeroths ursprungsbefolkningars.",al={"vilka är shen'dorei","shen'dorei-druider","vad betyder shen'dorei"}},{q="Vad är Zephras?",a="Zephras är shen'doreis avlägsna hemland. Dess inhemska växter, djur och andar skiljer sig tydligt från Azeroths, vilket har gett upphov till unika skepnadsskiftande former bland dess druider.",al={"vad är zephras","var ligger zephras","zephras hemland"}}},fp="30,266,22.312.0,32.368.0,38.227.0,44.106.0,58.248.0,48.211.0,30.191.0,16.188.0"}
P.entries["quest:98362"] = {n="To Thunder Bluff",s="Uppdraget To Thunder Bluff markerar en ung tauren-druids triumferande återkomst från mötet med Cenarion Circle i Moonglade. Efter att ha vunnit The Great Cat Spirits gunst återvänder novisen till Turak Runetotem på Elder Rise för att bemästra kattens skepnad.",h="Uppdraget To Thunder Bluff markerar en ung tauren-druids triumferande återkomst från mötet med Cenarion...",kw={"kattform","dendrite starblaze","druid","elder rise","the great cat spirit","moonglade","thunder bluff","turak runetotem"},ang={["class:Druid"]="Den här riten låser upp dina rovdjursinstinkter och ger dig, enligt Turak Runetotems läror, mästerskap över smygande och klor.",["faction:Horde"]="Även om Cenarion Circle förblir neutralt måste Horde-druider återvända till sin huvudstad för att säkerställa att deras växande kraft tjänar försvaret av deras folk.",["race:Tauren"]="Resan visar hur tauren återknyter till Cenarion-traditionerna och för lärdomarna från det heliga Moonglade tillbaka till Elder Rise i Thunder Bluff."},sec={{t="Åter från Moonglade",b="Efter att ha visat sin insikt och sitt värde inför Dendrite Starblaze och The Great Cat Spirit i Moonglades heliga lundar måste en ung druid föra andens välsignelse tillbaka till Mulgore. Mötet med sådana urkrafter är en avgörande milstolpe i en druids träning och förenar urgamla nattalviska läror med taurenfolkets jordnära arv."},{t="Bemästra kattformen",b="Turak Runetotem väntar på dig högt uppe på Elder Rise i Thunder Bluff. Dendrite förmedlade mötet med själva anden, men Turak ska vägleda den fysiska förvandlingen. När The Great Cat Spirits välsignelse har bekräftats förmedlar den äldre tränaren den heliga kunskap som krävs för att anta kattens snabba, rovdjurslika skepnad."}},faq={{q="Var börjar och slutar uppdraget?",a="Dendrite Starblaze ger uppdraget i Moonglades heliga tillflyktsort. Det leder resenären tillbaka till Elder Rise i Thunder Bluff för att tala med Turak Runetotem.",al={"var lämnar jag in uppdraget","vem startar to thunder bluff","lämna in uppdraget to thunder bluff"}},{q="Vad är syftet med uppdraget?",a="Det är den avslutande övergången i druids prövning av katten. Efter att ha fått The Great Cat Spirits välsignelse i Moonglade måste novisen återvända till sin mentor i Thunder Bluff för att till slut lära sig anta kattform.",al={"varför göra to thunder bluff","vad får jag från to thunder bluff","uppdraget om kattform"}},{q="Vem är Turak Runetotem?",a="Turak Runetotem är en respekterad äldre tauren-druid på Elder Rise i Thunder Bluff. Han ansvarar för träningen och invigningen av unga Horde-druider som vill leva i harmoni med naturen och bemästra sina skepnadsförvandlingar.",al={"turak runetotem i berättelsen","vem är turak"}},{q="Vem är Dendrite Starblaze?",a="Dendrite Starblaze är en nattalvisk väktare inom Cenarion Circle som vägleder besökande druider i Nighthaven i Moonglade. Han förmedlar lärdomar mellan urgamla kaldoreiska traditioner och tauren-utövare, trots spänningar mellan fraktionerna.",al={"dendrite starblazes roll","nattalv i moonglade"}},{q="Vad är The Great Cat Spirit?",a="The Great Cat Spirit är en uråldrig urkraft som druider vördar och som förkroppsligar rovdjursinstinkt, smygande och smidighet. Varje druid som vill anta kattens skepnad måste klara en prövning för att förtjäna dess välsignelse och förstå dess dubbla natur, både lekfull och dödlig.",al={"om kattandens historia","kattens ande"}},{q="Har Alliance-druider en motsvarande uppgift?",a="Ja. Nattalviska druider genomgår en liknande rit i Moonglade och återvänder till Darnassus för att rapportera till sin egen mentor, i stället för att bege sig till Mulgore och dess vindpinade platåer.",al={"alliance-versionen av to thunder bluff","nattalv återvänder för kattform"}}},fx={cdfa9758={q="Varför skickar Dendrite Starblaze dig tillbaka till Thunder Bluff?",a="Dendrite Starblaze är mentor och prövare i Moonglade, där han vägleder dig när du kommunicerar med The Great Cat Spirit. När du har klarat prövningen och vunnit andens gunst är hans roll i det här skedet av din träning över. Han skickar dig tillbaka till Turak Runetotem, så att din huvudlärare kan ge dig de sista lärdomarna och vägleda dig när du antar kattformen.",al={"varför skicka till thunder bluff","dendrite starblazes motiv","varför återvända till turak runetotem"}}},fp="16,278,21.359.0,22.359.0,36.169.0,34.235.0,23.236.0,26.240.0,29.262.0,43.168.0"}
P.entries["quest:98372"] = {n="An Unfortunate End",s="En fallen Night Watchman ligger i Duskwoods mörker, svårt söndersliten av ett okänt rovdjur. Att ta den släckta facklan ur hans kalla fingrar ger en möjlighet att tränga igenom mörkret omkring dig och avslöja det som döljer sig i skuggorna.",h="En fallen Night Watchman ligger i Duskwoods mörker, svårt söndersliten av ett okänt rovdjur.",kw={"an unfortunate end","odjur","duskwood","söndersliten","nattvakt","fackla"},sec={{t="En dyster upptäckt",b="En fallen medlem av Night Watch ligger stilla på Duskwoods mörka mark, med djupa hugg och skärsår efter ett vilt möte. De fruktansvärda såren tyder på att ett enormt odjur överföll patrullvakten innan han hann fly."},{t="Ljus i mörkret",b="I den fallna vaktens stela fingrar ligger en släckt fackla. Tar du den ur hans grepp får du ett värdefullt redskap mot skuggorna som tränger sig på. Den kan avslöja sådant som döljer sig i Duskwoods djupa mörker och längs andra mörka vägar."}},faq={{q="Vem tillhör kroppen?",a="Den fallna kroppen tillhör en medlem av Night Watch, stadsvakten som patrullerar Duskwoods mörka vägar och gränser. Han mötte en våldsam död ensam i skuggorna.",al={"vem är den döda kroppen","vem dog här","vem är den döda nattvakten"}},{q="Vad dödade vakten?",a="Han slets sönder av ett stort odjur, och kroppen bär djupa hugg och vilda skärsår. Odjuret hann övermanna honom innan han kunde försvara sig eller tända sin fackla.",al={"vad dödade nattvakten","hur dog vakten","vad anföll honom"}},{q="Varför är facklan viktig?",a="Den släckta facklan som vakten höll i kan lysa upp mörkret omkring dig och hjälpa vandrare att avslöja sådant som döljs i Duskwoods täta mörker och länderna bortom.",al={"vad används facklan till","vad gör jag med facklan","facklans användning i duskwood"}}},fp="18,247,16.253.0,21.269.0,19.179.0,25.180.0,27.172.0"}
P.entries["quest:98386"] = {n="Alther's Mill",s="Alther's Mill är ett uppdrag i Redridge Mountains som Foreman Oslow ger i Lakeshire. Han behöver äventyrare som röjer bort en farlig invasion av tarantlar vid det närbelägna sågverket, så att arbetarna tryggt kan hämta virket som behövs för att färdigställa bron i Lakeshire.",h="Alther's Mill är ett uppdrag i Redridge Mountains som Foreman Oslow ger i Lakeshire.",kw={"alther's mill","bro","foreman oslow","lakeshire","sågverk","redridge mountains","tarantel"},ang={["faction:Alliance"]="Att återuppbygga Lakeshires infrastruktur är viktigt för kungariket Stormwind, men ständiga hot drar resurser från bron."},sec={{t="En flaskhals i virkesflödet",b="Foreman Oslow har fullt upp med att hålla broreparationerna i Lakeshire enligt tidsplanen. Fientliga Blackrock-orcher, framryckande gnollflockar och aggressiva murlocer längs Lake Everstill pressar hans arbetsstyrka till bristningsgränsen. Det senaste avbrottet slår direkt mot försörjningskedjan: Alther's Mill, sågverket österut, har tagits över av jättelika tarantlar, vilket stoppar virkesleveranserna som behövs till stadens bro."},{t="Röj bort invasionen",b="Sågverket är så gott som obrukbart medan spindlar lurar bland timmerstaplarna. Foreman Oslow vågar inte skicka in sina arbetare i ett bo av större tarantlar, så han anlitar dugliga äventyrare för att röja bort spindlarna och förstöra deras äggsamlingar. Oslow är irriterad över att Alther låtit sågverket förfalla så, men att få igång virkesflödet igen går före alla klagomål."}},faq={{q="Vem är Foreman Oslow?",a="Foreman Oslow är stenhuggaren och arbetsledaren med ansvar för att reparera och återuppbygga bron i Lakeshire. Lokala hot försenar ständigt hans byggarbete.",al={"vem är foreman oslow","foreman oslow i redridge"}},{q="Vad är Alther's Mill?",a="Alther's Mill är ett sågverk öster om Lakeshire i Redridge Mountains. Det levererar viktigt virke till byggprojekt runt Lakeshire, däribland bron.",al={"vad är alther's mill","var ligger alther's mill"}},{q="Vem är Alther?",a="Alther äger eller driver sågverket öster om Lakeshire. Enligt Foreman Oslow ansvarar Alther för att sköta platsen, men just nu har spindlar tagit över hans sågverk.",al={"vem är alther","var är gamle alther"}},{q="Varför behöver Foreman Oslow få Alther's Mill röjt?",a="Foreman Oslow kan inte tryggt skicka arbetare för att hämta nödvändiga virkesleveranser medan sågverket är fullt av tarantlar. När spindlarna röjs bort och deras ägg förstörs kan sågverket tryggt återuppta leveranserna till brobygget.",al={"varför röja alther's mill","varför döda spindlar i redridge"}},{q="Vad har invaderat Alther's Mill?",a="Större tarantlar har invaderat sågverksområdet, tillsammans med samlingar av spindelägg. De utgör ett allvarligt hot mot alla arbetare som skickas dit för att hämta virke.",al={"vilka spindlar finns vid alther's mill","spindlar i redridge"}},{q="Vilken bro försöker Foreman Oslow bygga?",a="Foreman Oslow arbetar med att återuppbygga bron i Lakeshire, men arbetet försenas gång på gång av fientliga orcher, gnoller och murlocer samt brist på resurser till följd av lokala skadedjur.",al={"vilken bro i redridge","bron i lakeshire"}}},fp="13,266,22.434.0,24.416.0,21.184.0,22.193.0,14.214.0,50.241.0,32.148.0,45.179.0"}
P.entries["quest:98387"] = {n="Blackrock Blockade",s="Blackrock Blockade är ett militärt uppdrag från Alliansen som Marshal Marris utfärdar i Lakeshire. Stadsvakten vill svälta ut inkräktarna och ta deras vapen när den möter Blackrock-orcherna som rycker fram öster om Lake Everstill.",h="Blackrock Blockade är ett militärt uppdrag från Alliansen som Marshal Marris utfärdar i Lakeshire.",kw={"battleworn axe","blackrock blockade","blackrock-klanen","lakeshire","marshal marris","redridge mountains","stonewatch keep"},ang={["class:Warrior"]="I närstrider mot de härdade Blackrock-orcherna är det grundläggande gränskrigföring att beröva fienden tunga huggare och förnödenheter.",["faction:Alliance"]="Varje vapen som tas från Blackrocks förtrupp köper dyrbar tid åt Lakeshire, som måste stå emot fientliga arméer utan nämnvärd hjälp från Stormwind."},sec={{t="Ett utnötningskrig",b="Blackrock-klanen har gjort djärva räder in i Redridge Mountains, men deras fräcka framryckning in på Alliansens territorium har pressat deras försörjning till bristningsgränsen. Utan regelbundna försörjningstransporter måste deras främsta krigstrupper leva av de karga kullarna i Redridge. Marshal Marris vet att inte ens våldsamma orcher kan föra ett fälttåg utan stadig tillgång till förnödenheter och stål."},{t="Skär av de främsta lägren",b="Orchernas läger söder om Stonewatch Keep utgör spetsen i Blackrocks offensiv. Genom att plundra lägren, tömma deras förråd och ta tillbaka deras stulna vapen hoppas Alliansens försvarare slå ut förtruppens stridsstyrka och knäcka dess moral."}},faq={{q="Vad är målet med Blackrock Blockade?",a="Uppdraget ska försvaga Blackrock-klanens främsta läger söder om Stonewatch Keep. Genom att slå till mot deras försörjningslinjer, ta deras mat och återta deras vapen hoppas vakten i Lakeshire svälta ut orcherna och hejda deras framryckning in i Redridge.",al={"vad är blackrock blockade","målet med blackrock blockade","syftet med blockaden"}},{q="Vem utfärdar uppdraget?",a="Marshal Marris, befälhavare för stadsvakten i Lakeshire, leder försvaret av Redridge och styr arbetet med att störa Blackrocks försörjning.",al={"vem ger blackrock blockade","uppdragsgivare","marshal marris uppdrag"}},{q="Var ligger Blackrock-lägren?",a="De utpekade krigslägren ligger i de östra kullarna i Redridge Mountains, strax söder om Stonewatch Keep, på andra sidan floden från Lakeshire.",al={"var finns orcherna","blackrock-lägrets plats","var ligger stonewatch-lägret"}},{q="Varför förlitar sig Lakeshire på utnötning i stället för ett direkt anfall?",a="Vakten i Lakeshire har för få soldater och får knappt några förstärkningar från Stormwind. Det här är ett utnötningskrig: Blackrock-orchernas fräcka framryckning in på Alliansens territorium har gjort dem sårbara och lämnat dem utan förnödenheter. De är beroende av bergen omkring sig för att få resurser, och en armé kan inte kämpa på tom mage.",al={"varför svälta ut orcherna","varför inte anfalla stonewatch direkt","lakeshires strategi"}},{q="Vilka vapen beslagtar man från orcherna?",a="Marshal Marris vill att vapnen och förnödenheterna som lagras i Blackrock-lägren ska beslagtas, så att orcherna blir utan sina krigsredskap.",al={"vilka föremål behövs","vilka yxor","berättelser om stridsnötta yxor"}},{q="Tillhör de här orcherna Thralls Horde?",a="Nej. Blackrock-orcherna i Redridge tillhör den förrymda Dark Horde, som har sin bas i Blackrock Mountain. De förkastar Thralls ledarskap och är fortsatt fientliga mot både Alliansen och den nya Horden.",al={"är de här orcherna från horden","tillhör blackrock horden","thrall och blackrock-klanen"}}},fp="18,226,18.396.0,26.282.0,43.267.0,27.167.0,46.134.0,67.307.0,49.139.0,46.205.0"}
P.entries["quest:98389"] = {n="A Light in the Darkness",s="Aramis Hammerhand erbjuder uppdraget i Deathknell. Där ska Forsaken-äventyrare rädda nyväckta odöda som fastnat i Night's Web Hollow. Uppdraget belyser det känsliga förhållandet mellan odöda som utövar den Heliga Ljuset och ett folk som misstror dem djupt. Genom att hjälpa sina fallna fränder hoppas dessa heliga utövare bevisa sin lojalitet mot Sylvanas och Forsakens sak.",h="Aramis Hammerhand erbjuder uppdraget i Deathknell.",kw={"aramis hammerhand","deathknell","executor arren","forsaken","heliga ljuset","night's web hollow","tirisfal glades","nätfångade offer"},ang={["class:Priest"]="För Forsaken som kanaliserar helig energi visar uppdraget hur svårt det är att balansera kvarvarande dödlig tro mot odödhetens hårda verklighet.",["race:Undead"]="Uppdraget visar Forsakens inre konflikter och hur individer kan övervinna fördomar bland sitt eget nyväckta folk."},sec={{t="En bräcklig tro",b="Den Heliga Ljuset är ökänd för att vålla odöda svåra plågor och vara farlig för dem, men vissa Forsaken behåller sin koppling till den heliga magi de utövade i livet. I Deathknell försöker personer som Aramis Hammerhand visa att deras tro inte har vänt dem mot deras eget folk. För att motbevisa misstanken att heliga utövare ska vända sig mot andra odöda som om de vore vidunder använder de aktivt sina förmågor och sin medkänsla för att skydda sina fränder."},{t="Night's Web Hollow",b="Nordväst om Deathknell ligger Night's Web Hollow, en fuktig grotta full av ilskna spindlar. Nyväckta odöda, fortfarande omtöcknade efter uppvaknandet och oförmögna att försvara sig, irrar ofta in i hålan och hamnar insvepta i klibbiga nät. Att rädda dessa olyckliga Forsaken har två syften: att rädda nya rekryter åt den Mörka Damen och att bevisa för ledare som Executor Arren att de som utövar Ljuset är hängivna tjänare åt Forsaken."}},faq={{q="Vem ger uppdraget A Light in the Darkness?",a="Uppdraget ges av Aramis Hammerhand, en helig utövare stationerad i Deathknell i Tirisfal Glades.",al={"uppdragsgivare","vem ger a light in the darkness","aramis hammerhand uppdrag"}},{q="Var ligger Night's Web Hollow?",a="Night's Web Hollow ligger nordväst om Deathknell, bland kullarna i Tirisfal Glades.",al={"night's web hollow plats","var finns de nätfångade offren","var ligger grottan"}},{q="Varför misstror Forsaken dem som utövar Ljuset?",a="Den Heliga Ljuset bränner svårt och är farligt för odött kött. Många Forsaken fruktar att den som utövar heliga krafter kan se dem som styggelser som måste utrotas, snarare än som fränder att välkomna.",al={"varför frukta ljuset","varför hatar forsaken paladiner","forsakens rädsla för heliga krafter"}},{q="Vilka är offren som fastnat i näten?",a="Offren i kokongerna är nyväckta Forsaken-äventyrare som råkade irra in i spindelgrottorna innan de hittade rätt.",al={"vem sitter fast i nät","vad finns i näten","fångade offer"}},{q="Vem är Executor Arren, och varför vill Aramis imponera på honom?",a="Executor Arren ansvarar för den militära och civila ordningen i Deathknell. Att vinna hans förtroende är avgörande för heliga utövare som vill bli en del av Forsakens styrkor.",al={"vem är executor arren","varför är arren viktig"}},{q="Kan de odöda verkligen utöva den Heliga Ljuset?",a="Ja. Genom en oerhörd viljestyrka och hängivenhet behåller vissa odöda sin koppling till Ljuset, trots att det orsakar dem stort obehag att kanalisera det och att deras eget samhälle ser på dem med misstänksamhet.",al={"kan forsaken använda ljuset","odöda och ljuset i läran"}}},fx={f946e0be={q="Varför vill Aramis Hammerhand att de spindelinsnärjda offren befrias?",a="Aramis vill bevisa för sina andra Forsaken att odöda som brukar det heliga ljuset inte är ett hot mot sina egna. Många i Deathknell, däribland Executor Arren, fruktar eller misstänker att ljusbärare ska vända sina krafter mot andra odöda som om de vore monster. Genom att rädda nyväckta Forsaken från spindlarna i Night's Web Hollow hoppas Aramis visa att deras kraft finns till för att skydda Forsaken och tjäna Dark Ladys vision.",al={"aramis hammerhands motiv","varför befria de spindelinsnärjda offren","varför vill aramis att detta görs"}}},fp="23,388,18.444.0,18.480.0,44.104.0,36.90.0,51.201.0,40.137.0,63.169.0,43.194.0"}
P.entries["quest:98391"] = {n="The Sisterhood of Elune",s="The Sisterhood of Elune är ett introduktionsuppdrag som leder äventyrare till Darnassus för att träffa Sister Aquinne. Som den främsta andliga auktoriteten bland Night Elf behöver orden snabbt hjälp utifrån för att möta de växande utmaningarna i sina länder.",h="The Sisterhood of Elune är ett introduktionsuppdrag som leder äventyrare till Darnassus för att träffa Sister...",kw={"aquinne","darnassus","elune","prästinna","sister aquinne","the sisterhood of elune","teldrassil"},ang={["class:Priest"]="Prästerskapet i kaldoreisk kultur är synonymt med hängivenhet till Elune, och genom att svara Sister Aquinne knyter du an direkt till templets höga traditioner.",["faction:Alliance"]="Eftersom Darnassus är en viktig huvudstad för Alliance i Kalimdor bidrar din hjälp till The Sisterhood till stabiliteten i Night Elfs andliga och civila styre.",["race:NightElf"]="The Sisterhood of Elune är hjärtat i Night Elfs andliga liv och ledarskap. Därför är det en helig plikt för varje stjärnornas barn att svara på deras kallelse."},sec={{t="En kallelse till huvudstaden",b="”The Sisterhood of Elune” är en kallelse som uppmanar äventyrare att söka upp Sister Aquinne i Night Elf-huvudstaden Darnassus. Som företrädare för Elunes trogna skickar prästinnorna ofta ut kallelser efter pålitliga hjältar som kan hjälpa till med brådskande angelägenheter som berör deras folk och heliga länder."},{t="Rapportera till Sister Aquinne",b="När du anländer till Darnassus och hittar Sister Aquinne uttrycker hon stor lättnad över att du kom så snabbt. Hennes välkomnande markerar början på ditt direkta arbete för The Sisterhood of Elune och visar att prästinnorna ställs inför allt fler krav som behöver pålitliga händer utanför deras slutna krets."}},faq={{q="Vem är Sister Aquinne?",a="Sister Aquinne är ett sändebud och en prästinna som tjänar The Sisterhood of Elune i huvudstaden Darnassus. Hon tar emot resenärer som skickats för att hjälpa prästerskapet med brådskande angelägenheter som möter Night Elf.",al={"vem är sister aquinne","aquinne darnassus","var finns aquinne"}},{q="Vad är The Sisterhood of Elune?",a="The Sisterhood of Elune är en uråldrig orden av Night Elf-prästinnor som ägnar sig åt mångudinnan Elune. De vördas som andliga vägledare, helare och ledare för kaldoreisk kultur och ansvarar för sitt folks andliga välfärd och försvar.",al={"vad är the sisterhood of elune","vilka är elunes systrar","night elf-prästinnor"}},{q="Vart ska jag bege mig för att slutföra uppdraget?",a="Du måste resa till Darnassus, Night Elfs mäktiga huvudstad högt uppe på Teldrassil. Sister Aquinne väntar på dig i staden för att ge dig en genomgång på The Sisterhood of Elunes vägnar.",al={"var lämnar jag in the sisterhood of elune","plats för the sisterhood-uppdraget","vart går jag för the sisterhood of elune"}},{q="Varför behöver The Sisterhood hjälp?",a="Sister Aquinne antyder att The Sisterhood snabbt behöver hjälp utifrån för att hantera de akuta problem som drabbar Darnassus och de omkringliggande Night Elf-länderna. När du talar med henne får du fler uppdrag från dem.",al={"varför behöver the sisterhood hjälp","problem för the sisterhood","vilken hjälp behöver the sisterhood"}},{q="Kan Horde-karaktärer ta sig an det här uppdraget?",a="Nej. The Sisterhood of Elune står i centrum för Night Elfs ledarskap och är helt knuten till Alliance. Darnassus är en huvudstad för Alliance, så uppdraget är exklusivt för äventyrare i Alliance.",al={"får horde det här uppdraget","kan horde göra the sisterhood of elune"}},{q="Vem leder The Sisterhood of Elune?",a="Översteprästinnan Tyrande Whisperwind är The Sisterhood of Elunes andliga ledare och den högsta ledaren för kaldoreifolket. Hon vägleder sina systrar från Temple of the Moon i Darnassus.",al={"vem leder the sisterhood of elune","the sisterhoods ledare","tyrande och the sisterhood"}}},fp="23,262,21.297.0,27.292.0,22.215.0,32.239.0,45.187.0,36.224.0,42.189.0,34.199.0"}
P.entries["quest:98392"] = {n="Darkness in the Glade",s="Darkness in the Glade är en utredning ledd av Sentinel Arynia Cloudsbreak om förgiftade läderbälten från harpyor i The Oracle Glade. Amuletter från harpyornas matriarker bekräftar att demonisk felmossa har slagit rot i Teldrassils grenar.",h="Darkness in the Glade är en utredning ledd av Sentinel Arynia Cloudsbreak om förgiftade läderbälten från...",kw={"arynia cloudsbreak","arysa","darkness in the glade","fel moss","gaedress","harpyor","hatescreech","the oracle glade","teldrassil"},ang={["class:Druid"]="Felmossa som förorenar djurliv och läderfibrer är ett tecken på en onaturlig farsot som rubbar världsträdets naturliga balans.",["faction:Alliance"]="Sentinel Cloudsbreak företräder Darnassus militära vaksamhet och arbetar för att hitta demonisk förorening som hotar Alliansens länder.",["race:NightElf"]="När felkorruption sprider sig genom heliga grenar som The Oracle Glade slår den direkt mot kaldoreiernas strävan att vårda och skydda Teldrassil."},sec={{t="Förgiftade fibrer",b="I The Oracle Glades rofyllda trädkronor lade Sentinel Arynia Cloudsbreak märke till något märkligt bland de lokala harpyflockarna. Läderbälten från varelserna bar på en onaturlig förorening, invävd direkt i materialet. Cloudsbreak misstänkte ett demoniskt intrång snarare än vanligt aggressivt beteende hos bestar och behövde säkra bevis innan hon slog larm till Darnassus."},{t="En bekräftad farsot",b="Cloudsbreak skickade hjältar till de västra bona för att fälla flyktens matriarker: Hatescreech, Windmistress Gaedress och Witchmother Arysa. Var och en bar en amulett med synliga spår av sin kraft. När Sentinel undersökte stenarna upptäckte hon vidriga gröna virvlar inneslutna i ädelstenarna, vilket bekräftade att felmossa aktivt förvred harpyorna och trängde in i de heliga grenarna."}},faq={{q="Vad är Darkness in the Glade?",a="Darkness in the Glade är ett uppdrag från Sentinel Arynia Cloudsbreak i The Oracle Glade. Efter att ha upptäckt en onaturlig förorening i harpyornas läderbälten skickar hon äventyrare för att hämta amuletter från harpyledarna och fastställa föroreningens källa.",al={"vad är darkness in the glade","uppdraget darkness in the glade"}},{q="Vem ger uppdraget?",a="Sentinel Arynia Cloudsbreak ger uppdraget. Hon är stationerad i The Oracle Glade, där hon vakar över Teldrassils grenar och undersöker märkliga störningar bland de harpyor som bor där.",al={"vem ger darkness in the glade","uppdragsgivare the oracle glade"}},{q="Varför vill Arynia ha amuletter från harpyledarna?",a="Sentinel Cloudsbreak upptäckte förorenade fibrer i läderbälten från vanliga harpyor och behövde fler bevis. Hon misstänkte att harpyornas ledare bar smycken som visade farsotens verkliga natur och ursprung.",al={"varför döda harpyledare","varför hämta amuletter","varför harpyamuletter"}},{q="Vilka harpyledare har amuletterna?",a="Amuletterna tillhör tre framstående ledare med bon i väster: Hatescreech, Windmistress Gaedress och Witchmother Arysa.",al={"vilka harpyor har amuletter","harpyledare the oracle glade"}},{q="Vad orsakar föroreningen i gläntan?",a="Föroreningen kommer från felmossa. När Arynia undersöker de återfunna amuletterna upptäcker hon vidriga gröna virvlar i ädelstenarna, vilket bekräftar att felmossa förorenar området.",al={"vad förorenar harpyorna","vad är den gröna virveln","ursprunget till gläntans mörker"}},{q="Har föroreningen dykt upp någon annanstans?",a="Ja, Sentinel Cloudsbreak nämner att rapporter om felmossa som vänder miljön mot nattalverna också har kommit från Shadowglen och andra grenar runt om på världsträdet.",al={"felmossa på andra platser","är shadowglen förorenat"}}},fp="21,273,14.379.0,18.410.1,30.255.0,21.184.0,52.224.0,37.125.0,44.185.0,43.179.0"}
P.entries["quest:98393"] = {n="The Great Cat Spirit",s="The Great Cat Spirit är ett heligt druidiskt uppdrag som kallar utövare till Nighthaven i Moonglade för att möta Dendrite Starblaze. Efter att ha bemästrat björnens aspekt kallas druider att påbörja sin resa in i vildmarkens kattperspektiv, med Father Cenarius välsignelse.",h="The Great Cat Spirit är ett heligt druidiskt uppdrag som kallar utövare till Nighthaven i Moonglade för att...",kw={"kattaspekten","cenarius","dendrite starblaze","druidutbildning","moonglade","nighthaven","the great cat spirit"},ang={["class:Druid"]="Denna kallelse är en viktig övergångsrit för druider som vill bemästra vildmarkens aspekter bortom björnen.",["race:NightElf"]="Moonglade är förfädernas mark för kaldorei-druider som följer Cenarius uråldriga läror.",["race:Tauren"]="Taurendruider reser fritt till Nighthaven tillsammans med sina nattalvssystrar och -bröder under Cenarion Circles gemensamma ledning."},sec={{t="Kallelsen till Moonglade",b="Efter att redan ha visat att de behärskar björnens uthålliga aspekt blir blivande druider åter kallade till Moonglades heliga skog. Äldsten Dendrite Starblaze sträcker sig över landet och kallar lärjungar till den fridfulla tillflyktsorten Nighthaven för att inleda nästa steg i sin förening med naturen. Druider använder sin unika andemagi för att färdas långa sträckor och samlas i Cenarion-visdomens stilla hjärta."},{t="Kattens perspektiv",b="När du anländer till Nighthaven åkallar Dendrite Starblaze Father Cenarius och en svag kraftens aura sänker sig medan han välkomnar den växande lärjungen. Han berättar att tiden är inne att ta till sig kattens perspektiv, en vild aspekt som är rovdjurslik och smidig. Liksom vid tidigare övergångsriter öppnar Dendrite vägen till förståelse, men resan att förkroppsliga och sprida denna kattande vilar helt på utövaren."}},faq={{q="Vem kallar på dig i The Great Cat Spirit?",a="Dina druidtränare kallar på dig på uppdrag av Dendrite Starblaze, en äldste och mentor i Nighthaven, i Moonglades avskilda tillflyktsort.",al={"vem ger uppdraget the great cat spirit","dendrite starblaze kallelse"}},{q="Var hittar man Dendrite Starblaze?",a="Dendrite Starblaze bor i byn Nighthaven, Moonglades centrala bosättning, som nås med druidisk teleportationsmagi.",al={"var finns dendrite starblaze","dendrite starblazes plats"}},{q="Vad är syftet med att träffa Dendrite Starblaze?",a="Dendrite förbereder dig på att kommunicera med och förstå naturens kattaspekt, så att du kan fortsätta din andliga utveckling efter att ha lärt dig björnens vägar.",al={"vad lär dendrite ut","uppdrag för kattformsutbildning"}},{q="Varför åkallar Dendrite Father Cenarius?",a="Dendrite åkallar Father Cenarius när han hälsar dig välkommen för att hedra halvguden och druidismens beskyddare, som först lärde de dödliga naturens och skepnadsskiftandets hemligheter.",al={"varför father cenarius","cenarius nämns av dendrite"}},{q="Hur reser druider till Moonglade när de blir kallade?",a="Druider använder sin medfödda andliga förmåga att kommunicera med naturen och teleportera direkt till Moonglade när deras mentorer kallar på dem.",al={"hur tar man sig till moonglade","druidteleportering till moonglade"}},{q="Hur hänger denna aspekt ihop med björnaspekten?",a="Druidisk lära närmar sig naturen ur olika perspektiv. Nybörjare börjar med att bemästra björnens uthålliga styrka innan de går vidare till kattens snabba rovdjursinstinkt.",al={"lore om kattform jämfört med björnform","björnform först"}}},fp="20,299,24.440.0,26.441.0,42.143.0,38.137.0,50.156.0,41.166.0,51.134.0,47.184.0"}
P.entries["quest:98397"] = {n="To Darnassus",s="To Darnassus är slutpunkten på en nattalvdruids resa för att samråda med The Great Cat Spirit. När du har visat dig värdig inför Dendrite Starblaze i Moonglade skickas du tillbaka till Cenarion Enclave för att bemästra konsten att anta kattform.",h="To Darnassus är slutpunkten på en nattalvdruids resa för att samråda med The Great Cat Spirit.",kw={"kattform","cenarion enclave","dendrite starblaze","the great cat spirit","mathrengyl bearwalker","moonglade","teldrassil","to darnassus"},ang={["class:Druid"]="Det här uppdraget markerar din övergång till att jaga från skuggorna och ger dig förmågan att kanalisera The Great Cat Spirit direkt genom kattform.",["faction:Alliance"]="Alliansens druider återvänder från Moonglades neutrala mark till Darnassus och stärker sitt hemlands magiska försvar.",["race:NightElf"]="När du återvänder till Darnassus hedrar du nattalvernas traditioner, som Cenarion Circle har bevarat under världsträdet Teldrassil."},sec={{t="Återvänd till Cenarion Enclave",b="Efter att ha samrått med The Great Cat Spirit under Dendrite Starblazes vägledning i Moonglade måste en nattalvdruid under utbildning återvända till Teldrassil. Starblaze anser att du har visat dig vara en värdig elev och skickar dig tillbaka till din huvudlärare, Mathrengyl Bearwalker, som väntar under trädkronorna i Cenarion Enclave i Darnassus."},{t="Kattens natur",b="När du anländer till Darnassus konstaterar Mathrengyl Bearwalker att du har tagit till dig The Great Cat Spirits visdom. Enligt honom ställs varje druidsläkte inför ett prov som formas av denna uråldriga varelse, som är lika lekfull som dödlig. När din förbindelse har knutits och din ande förberetts ger Mathrengyl dig de sista riterna som krävs för att anta kattens smidiga form."}},faq={{q="Vad är syftet med det här uppdraget?",a="Det här uppdraget avslutar ditt prov med The Great Cat Spirit. När du har utfört dina uppgifter åt Dendrite Starblaze i Moonglade skickas du tillbaka till Mathrengyl Bearwalker i Darnassus, så att han kan lära dig att anta kattform.",al={"varför göra uppdraget","syftet med to darnassus","uppdrag för kattform"}},{q="Vem skickar dig tillbaka till Darnassus?",a="Dendrite Starblaze, en högt uppsatt druid som bor i Nighthaven i den heliga fristaden Moonglade, ger dig uppdraget efter att du har fått The Great Cat Spirits välsignelse.",al={"vem startar uppdraget","uppdragsgivare"}},{q="Var hittar jag Mathrengyl Bearwalker?",a="Mathrengyl Bearwalker finns i Cenarion Enclave, druidernas helgedom i Darnassus nordvästra kvarter på Teldrassil.",al={"mathrengyls plats","var finns bearwalker"}},{q="Vad betyder The Great Cat Spirit?",a="The Great Cat Spirit är en uråldrig, vild naturande som förkroppsligar smidiga, dödliga rovdjur. Druider måste vinna dess gunst och förstå dess dubbla natur, både lekfull och livsfarlig, innan de får kanalisera dess gestalt.",al={"kattandens bakgrund","vad är the great cat spirit"}},{q="Går alla druider igenom exakt samma prov?",a="Enligt Mathrengyl Bearwalker måste alla druider klara ett prov som The Great Cat Spirit ger dem för att bemästra dess form, men provens exakta utformning varierar mellan generationerna.",al={"är druidernas prov likadana","prov mellan generationer"}},{q="Kan andra än nattalver ta uppdraget?",a="Det här särskilda uppdraget är till för alliansens nattalvdruider som återvänder till Darnassus. Taurendruider följer sin egen väg och rapporterar tillbaka till sina egna lärare i Thunder Bluff efter besöket i Moonglade.",al={"är uppdraget bara för alliansen","kan taurener göra detta"}}},fx={["5fd4c60a"]={q="Varför skickar Dendrite Starblaze dig tillbaka till Darnassus?",a="Du har visat ditt värde inför The Great Cat Spirit i Moonglade, och dina prövningar under Dendrite Starblaze är över. Dendrites uppgift var att vaka över din gemenskap med den uråldriga anden. Nu väntar din första tränare, Mathrengyl Bearwalker, på dig i Darnassus för att hjälpa dig omsätta lärdomarna och slutligen bemästra kattens skepnadskonst.",al={"varför skicka till darnassus","dendrite starblazes motiv","varför återvända till mathrengyl"}}},fp="12,205,21.309.0,21.309.0,34.201.0,32.138.0,39.103.0,49.198.0,44.150.0,36.174.0"}
P.entries["quest:98398"] = {n="The Oracle Tree",s="The Oracle Tree är ett uppdrag där en lovande äventyrare får i uppgift att söka kontakt med ett medvetet, uråldrigt träd. Genom att leta efter en barkbit som trädet med avsikt har fällt får resenärer ta emot dess rogivande telepatiska budskap och förbereda sig för större uppgifter.",h="The Oracle Tree är ett uppdrag där en lovande äventyrare får i uppgift att söka kontakt med ett medvetet...",kw={"oracle tree","oracle tree-bark","medvetet träd","fälld bark","telepati","the oracle tree"},ang={["class:Druid"]="Druider är naturligt mottagliga för medvetet växtliv och uråldriga träds röster. Därför blir kontakten med The Oracle Tree en förlängning av deras vördnad för naturen."},sec={{t="Ett kall till större uppgifter",b="The Oracle Tree är ett vist, medvetet träd som vakar över sin omgivning och vägleder resenärer som visar sitt värde. När det behöver en agent ute i världen fäller det med avsikt en bit bark i närheten. De som lägger märke till den kallas att träda fram, ett tecken på att deras inledande uppgifter är avslutade och att större ansvar väntar dem."},{t="Kontakt genom barken",b="The Oracle Tree talar inte med en vanlig, fysisk röst. I stället kan trädet nå direkt in i sökarens sinne när denne undersöker den fallna barkbiten. Dess närvaro är lugn och rogivande och sveper över lyssnaren som en mild bris genom ett lövverk. Trädet förmedlar tankar och önskningar utan att yttra ett enda ord."}},faq={{q="Vad är The Oracle Tree?",a="The Oracle Tree är ett uråldrigt, medvetet träd som kan kommunicera telepatiskt med dem som befinner sig i närheten. När det vill förmedla ett budskap eller ge någon en uppgift fäller det en bit bark för att få värdiga äventyrares uppmärksamhet.",al={"vad är oracle tree","oracle trees bakgrund"}},{q="Hur kommunicerar The Oracle Tree?",a="I stället för att tala med hörbar röst förmedlar The Oracle Tree sina tankar telepatiskt. Den som undersöker den fallna barken hör en lugn, rogivande röst träda in i sitt sinne, som en mild bris som susar genom lövverket.",al={"hur talar oracle tree","oracle trees kommunikation"}},{q="Varför behöver du hitta barken från The Oracle Tree?",a="Trädet fäller en bit bark särskilt när det har ett syfte eller en uppgift som måste tas om hand. När du undersöker barken får trädet en fokalpunkt för att förmedla sin telepatiska vägledning.",al={"varför hitta barken","syftet med den fallna barken"}},{q="Vem leder dig till The Oracle Tree?",a="En lokal uppsyningsman eller vårdare som har följt dina framgångar inser att större uppgifter väntar dig. När personen får syn på den nyfallna barken leder hen dig till trädet för att ta emot dess vägledning.",al={"vem skickar dig till oracle tree","uppdragsgivare för oracle tree"}},{q="Vad är syftet med uppdraget The Oracle Tree?",a="Uppdraget inleder kontakten mellan en erfaren resenär och själva trädet. Genom att söka upp barken öppnar du ditt sinne för trädets budskap och får veta vilken större uppgift det vill att du utför.",al={"målet med oracle tree-uppdraget","vad vill oracle tree"}},{q="Var hittar du barken från The Oracle Tree?",a="Den fällda barken ligger på marken alldeles intill The Oracle Tree, i väntan på att undersökas av någon som är tillräckligt mottaglig för att höra dess budskap.",al={"var hittar man oracle tree-bark","barkens plats"}}},fp="15,263,24.358.0,26.358.0,24.230.0,37.225.0,47.190.0,35.216.0,49.203.0,36.149.0"}
P.entries["quest:984"] = {n="How Big a Threat?",s="How Big a Threat? är ett alliansuppdrag som Terenthis ger i Auberdine. Efter att ha sett furbolgarnas vansinne få fäste över Teldrassil skickar nattalvdruiden ut spejare för att undersöka lokala furbolgbosättningar i Darkshore och ta reda på om samma mörka besmittelse har korsat havet.",h="How Big a Threat?",kw={"ameth'aran","auberdine","fördärv","darkshore","furbolg","teldrassil","terenthis","hot"},ang={["class:Druid"]="Furbolgarna har starka band till naturen och vildmarkens uråldriga andar, så deras plötsliga fall i fördärv är ett allvarligt bekymmer för druiderna som har till uppgift att läka Kalimdors balans.",["faction:Alliance"]="Auberdine är alliansens främsta port till norra Kalimdors fastland. Att skydda staden från hot i vildmarken är avgörande för regionens säkerhet och försörjning.",["race:NightElf"]="För kaldorei är det både en bitter tragedi och en omedelbar fara för heliga marker att se uråldriga allierade som furbolgarna falla i irrationellt mörker så kort efter det tredje kriget."},sec={{t="Skuggor över havet",b="Nattalverna i norra Kalimdor har länge haft vänskapliga eller fredliga relationer med ursprungsbefolkningens furbolgstammar. Men efter det tredje kriget började märkliga förvridningar rubba furbolgarnas sinnen i Teldrassil, vilket ledde till våldsamma kidnappningar och vilda attacker mot deras forna allierade. Druiden Terenthis, som är stationerad i Auberdine, fruktar att denna olycksbådande plåga inte är begränsad till Världsträdet, utan sprider sig bland fastlandets stammar längs Darkshores dimhöljda kuster."},{t="En storm samlas",b="Spaning vid ett furbolgläger nära ruinerna av Ameth'Aran bekräftar Terenthis värsta farhågor. Furbolgarna där uppvisar oberäknelig, fientlig aggressivitet och bär tydliga tecken på samma fördärv som plågar norr. Deras närhet till Auberdine gör dem till ett akut försvarshot mot alliansens bosättning i stället för fredliga grannar i vildmarken."}},faq={{q="Vem är Terenthis?",a="Terenthis är en nattalvdruid stationerad i kuststaden Auberdine. Han hemsöks av berättelser om nattalver som angripits och tillfångatagits av vansinniga furbolgar runt Teldrassil, och arbetar för att bevaka och hejda nya hot i Darkshore.",al={"terenthis uppdragsgivare","vem ger uppdraget how big a threat","terenthis auberdine"}},{q="Varför blir furbolgarna i Darkshore fientliga?",a="Terenthis har sett tecken på fördärv i Darkshore och misstänker att furbolgarna kan vara drabbade, liksom vissa på Teldrassil. Han ber dig undersöka deras läger eftersom han ännu inte har fastställt om tecknen är utbredda.",al={"varför är furbolgarna galna","fördärvade furbolgar i darkshore","furbolgarnas fördärv"}},{q="Var ligger det fördärvade furbolglägret?",a="Lägret ligger en bit inåt landet i centrala Darkshore, strax norr om de uråldriga högalveruinerna i Ameth'Aran och sydöst om Auberdine.",al={"lägrets plats","var ligger furbolglägret","platsen för how big a threat"}},{q="Hur hänger detta samman med händelserna på Teldrassil?",a="På Teldrassil kidnappade och skadade flera fördärvade furbolgar nattalvsnärvakter och civila. Terenthis hänvisar till de nyligen genomförda räddningarna när han vill ta reda på om fastlandet i Darkshore står inför exakt samma kris.",al={"samband med teldrassil","furbolgar på teldrassil","varför nämner terenthis teldrassil"}},{q="Vad händer efter att du rapporterat tillbaka till Terenthis?",a="Rapportera alla tecken på fördärv till Terenthis i Auberdine. Hans reaktion på fynden får du se när du återvänder.",al={"nästa uppdrag","vad följer efter how big a threat","fortsättning på uppdraget"}},{q="Varför oroar sig nattalverna så mycket för furbolgläger nära Auberdine?",a="Auberdine är alliansens främsta hamn och försörjningsled på fastlandet. Djupt fördärvade, fientliga stammar inom anfallsavstånd gör handelsvägarna, spejargrupperna och själva staden sårbara för plötsliga angrepp.",al={"hot mot auberdine","varför bry sig om furbolgarna"}}},fx={["0269df0a"]={q="Varför vill Terenthis att detta görs?",a="Terenthis svor personligen att hindra mer blodspillan efter att hans nattalvskamrater behövt räddas från fördärvade furbolger på Teldrassil. Han har redan märkt svaga tecken på att korruptionen nått Darkshore, och fruktar att smittan kan spridas obemärkt genom de lokala furbolgstammarna. Genom att skicka dig för att spana på deras läger hoppas han avgöra om faran redan står vid Auberdines tröskel innan fler liv går förlorade.",al={"terenthis motiv","varför undersöka furbolger i darkshore","varför bryr sig terenthis"}},["1e1a0eb0"]={q="Vem skickas du för att undersöka?",a="Du skickas för att spana på de lokala furbolgstammarna i Darkshore. Många furbolgklaner levde en gång fredligt eller tillbakadraget sida vid sida med nattalverna, men mörka krafter har börjat förvrida deras sinnen och driva dem till vansinne. Terenthis skickar dig för att inspektera deras bosättningar och ta reda på om denna plåga fått fäste bland stammarna som lever farligt nära Auberdine.",al={"vem undersöker jag","vilket furbolgläger","vem är målet"}}},fp="17,227,22.371.0,17.273.1,17.194.0,50.218.0,42.132.0,45.202.0,47.96.0,68.180.0"}
P.entries["quest:98403"] = {n="Twisted Hatred",s="Twisted Hatred är ett uppdrag i Teldrassil som avslöjar vem som styr Lord Melenas. Äventyrare tar sig in i The Cleft, nordväst om Dolanaar, för att möta Xethorr the Wicked och utrota hans förvridna spindlar innan hans onda planer sprider sig bland trädets grenar.",h="Twisted Hatred är ett uppdrag i Teldrassil som avslöjar vem som styr Lord Melenas.",kw={"befouled webwood","the cleft","dolanaar","lord melenas","mature fel moss","satyr","tallonkai swiftroot","teldrassil","twisted hatred","xethorr the wicked"},ang={["class:Druid"]="När Teldrassils naturliga spindlar förvandlas till ett fördärvat yngel rubbas naturens balans, och Cenarionförsvararna måste rena platsen.",["faction:Alliance"]="Genom att hjälpa Tallonkai Swiftroot skyddar du bosättningen Dolanaar mot satyrernas växande intriger i Alliansens främsta fristad på Kalimdor.",["race:NightElf"]="Teldrassil är hjärtat i kaldoreiernas återkomst. Därför är det en direkt förolämpning och ett hot mot ditt folk när demoniskt fördärv frodas bland de inhemska djuren i The Cleft."},sec={{t="En skuggornas mästare",b="Upptäckten att Lord Melenas inte agerade på egen hand avslöjar en mörkare strömning i Teldrassils vildmark. Bakom Melenas stod Xethorr the Wicked, en förhärdad satyr som drog i trådarna från skogens skuggor för att undergräva världsträdets fridfulla grenar."},{t="The Clefts fördärvade yngel",b="Xethorr tog sin tillflykt nordväst om Dolanaar, i den avskilda enklaven som kallas The Cleft, och riktade sedan blicken mot Teldrassils inhemska spindlar. Genom att förvrida lokala Webwood-spindlar till fördärvade bestar försökte satyren använda deras gift i lömska demoniska planer. Tallonkai Swiftroot skickade äventyrare för att decimera ynglet och ta Xethorrs Mature Fel Moss innan fördärvet kunde sprida sig ytterligare."}},faq={{q="Vem är Xethorr the Wicked?",a="Xethorr the Wicked är en illvillig satyr som ligger bakom fördärv i Teldrassil. Han styrde Lord Melenas och slog sig ner i The Cleft, där han förvrider inhemska spindlar och använder Mature Fel Moss för sina ondskefulla planer.",al={"vem är xethorr","xethorr the wicked","vem är satyren"}},{q="Var ligger The Cleft?",a="The Cleft är ett avskilt område djupt inne i skogen nordväst om Dolanaar i Teldrassil. Där har Xethorr the Wicked och hans fördärvade yngel slagit sig ner.",al={"var ligger the cleft","the clefts läge","var hittar jag xethorr"}},{q="Varför är Teldrassils spindlar fördärvade?",a="Befouled Webwoods är inhemska spindlar från Teldrassil som Xethorr the Wicked har fördärvat. Satyren förvrängde deras sinnen och kroppar för att skörda deras gift till en avskyvärd demonisk plan.",al={"varför förändrades spindlarna","vad är befouled webwoods","befouled webwoods bakgrund"}},{q="Vem är Tallonkai Swiftroot?",a="Tallonkai Swiftroot är en nattalvsväktare stationerad i byn Dolanaar i Teldrassil. Han ger äventyrare i uppdrag att röja undan demoniskt inflytande i skogarna omkring byn.",al={"vem gav uppdraget","var finns tallonkai","tallonkai swiftroots roll"}},{q="Vad är Mature Fel Moss?",a="Mature Fel Moss är ett fördärvande växtprov som Xethorr the Wicked bär på. Tallonkai Swiftroot vill få tag på det för att ta reda på mer om satyrens verkliga motiv och pågående verksamhet i Teldrassil.",al={"mature fel moss","varför samla fel moss","vad är fel moss"}},{q="Hur var Lord Melenas inblandad?",a="Lord Melenas handlade inte av egen illvilja, utan på direkt uppmaning av Xethorr the Wicked. Det avslöjar en samordnad satyrkonspiration i Teldrassil.",al={"melenas koppling","vem är lord melenas","melenas och xethorr"}}},fp="14,273,18.291.0,31.408.1,26.227.0,27.169.0,43.188.0,27.178.0,28.194.0,30.171.0"}
P.entries["quest:98404"] = {n="The Great Windborne Cat Spirit",s="The Great Windborne Cat Spirit är en helig prövning i list och smygande för blivande druider. De invigda måste bege sig till den närbelägna Stormrage Barrow Den för att hämta tre uråldriga reliker och samtidigt smita förbi fientliga, rasande andar. Den som klarar denna andliga rit bevisar sitt mästerskap i kattens dygder: smygande, ursinne och list. Då får de välsignelsen att anta kattgestalt.",h="The Great Windborne Cat Spirit är en helig prövning i list och smygande för blivande druider.",kw={"avatar of saeyleenan","kattgestalt","druidprövning","rasande andar","relic of the claw","relic of the fang","relic of the silent shadow","saeyleenan","stormrage barrow den","the great windborne cat spirit"},ang={["class:Druid"]="Denna rit är en viktig milstolpe för druider som lär sig att kanalisera vildkattens smidighet, smygförmåga och rovdjursinstinkt. De måste bevisa att de besitter list och ursinne innan anden skänker sin välsignelse till formskiftet.",["race:NightElf"]="Stormrage Barrow Den bär namnet från en av de mest framstående nattalviska druidiska släktlinjerna. Att utforska dess djup knyter Kaldorei-utövare direkt till folkets uråldriga gravkammartradition och förfädersandar."},sec={{t="Prövningen i list och smygande",b="För att dra kraft ur den stora kattandens makt måste aspiranter bevisa att de har rovdjurets temperament. Sann harmoni med katten kräver förståelse för list och tålamod, tillsammans med explosivt ursinne när den trängs in i ett hörn. Anden skänker inte sin gåva lättvindigt till dem som bara kräver makt. I stället prövar den om en sökare kan tänka, röra sig och slå till som vildmarkens kattjägare. Först när en invigd visar dessa inre egenskaper kan den hoppas förtjäna rätten att anta kattens fysiska gestalt."},{t="Stormrage Barrow Den",b="Provet skickar sökare in i dunklet i den närbelägna Stormrage Barrow Den, strax öster om andens avatar. Djupt inne i de underjordiska salarna finns tre heliga föremål: Relic of the Fang, Relic of the Claw och Relic of the Silent Shadow. Men det är långt ifrån enkelt att hämta dem. Gravkammaren har blivit full av rasande andar som våldsamt angriper alla inkräktare de får syn på. För att överleva grottan och nå relikerna kan en sökare inte förlita sig enbart på råstyrka, utan måste röra sig varsamt genom mörkret."},{t="Saeyleenans avatar",b="I centrum för denna prövning står Avatar of Saeyleenan, den fysiska gestalt genom vilken The Great Windborne Cat Spirit talar till unga invigda. Eftersom otränade sökare saknar en erfaren jägares naturliga smygförmåga erbjuder en staty vid gravkammarens ingång en tillfällig välsignelse som döljer dem. De som lyckas smita förbi de ursinniga andarna och återvända med alla tre reliker bevisar att de har tagit till sig rovdjurets lärdomar. Som svar erkänner avataren deras värdighet och skänker välsignelsen som krävs för att anta kattgestalt."}},faq={{q="Vad är The Great Windborne Cat Spirit?",a="The Great Windborne Cat Spirit är en vild beskyddare som vägleder unga druider i att bemästra kattens skepnadsskifte. Anden visar sig genom Avatar of Saeyleenan och förkroppsligar rovdjurets främsta dygder: list, smygande och ursinne. I stället för att fritt skänka sin gestalt prövar den aspiranter genom en helig rit för att försäkra sig om att de respekterar kattens rovdjursinstinkter och natur.",al={"vindburen kattande","vem är saeyleenan","kattandens historia"}},{q="Vad är Avatar of Saeyleenan?",a="Avatar of Saeyleenan är The Great Windborne Cat Spirits fysiska gestalt och språkrör. Avataren står väster om Stormrage Barrow Den och vakar över områdets druidiska prövning. Den ger sökare i uppgift att hämta gravkammarens stulna eller gömda reliker och bedömer om en invigd har visat tillräckligt med smygförmåga och list för att förtjäna kattens välsignelse.",al={"avatar of saeyleenan","vem är avatar saeyleenan","saeyleenan npc"}},{q="Vilka reliker krävs för prövningen?",a="Prövningen kräver att tre särskilda reliker hämtas från Stormrage Barrow Den: Relic of the Fang, Relic of the Claw och Relic of the Silent Shadow. Tillsammans symboliserar dessa föremål de fysiska vapen och den svårfångade smygförmåga som utmärker kattandens gestalt. De visar att den invigde vördar rovdjurets alla sidor.",al={"tre reliker","relic of the claw","stormrage barrow den reliker"}},{q="Var ligger Stormrage Barrow Den?",a="Stormrage Barrow Den ligger strax öster om Avatar of Saeyleenan. De underjordiska kamrarna är druidprövningens testområde och rymmer de tre heliga relikerna. Invigda måste bege sig ner i de mörka salarna och undvika de farliga, rasande andar som strövar i tunnlarna.",al={"stormrage barrow den plats","var ligger gravkammaren","var hittar man relikerna"}},{q="Varför vaktar rasande andar gravkammaren?",a="Stormrage Barrow Den har blivit övertagen av mäktiga, rasande andar som angriper alla levande inkräktare de får syn på. Dessa fientliga varelser är ingen villig vaktstyrka, utan utgör en aktiv fara i gravkammaren. Därför måste blivande druider använda list och smygförmåga för att hämta relikerna i stället för att ta strid direkt.",al={"varför är andarna rasande","rasande andar i gravkammaren","gravkammarens väktare"}},{q="Hur smiter sökare förbi de rasande andarna?",a="En stenstaty vid ingången till Stormrage Barrow Den skänker sökare en tillfällig välsignelse i smygande. Unga invigda har ännu inte förtjänat sin egen medfödda kattgestalt eller förmåga att smyga fram. Därför gör denna skyddande förtrollning att de kan smita förbi de vaksamma, fientliga andarna utan att upptäckas och hämta relikerna.",al={"hur smyger man i gravkammaren","smygandevälsignelse från statyn","hur undviker man rasande andar"}},{q="Vilken belöning eller välsignelse får man när prövningen är avklarad?",a="När sökaren återlämnar Relic of the Fang, Relic of the Claw och Relic of the Silent Shadow anser Avatar of Saeyleenan att sökaren förtjänar The Great Windborne Cat Spirits välsignelse. Riten visar att den invigde förstår kattens sanna natur och ger den andliga bekräftelse som krävs för att anta rovdjurets gestalt.",al={"prövningens belöning","vad får man från kattanden","kattandens välsignelse"}}},fp="30,389,32.527.0,24.549.0,24.577.0,38.385.0,33.383.0,39.359.0,42.302.0,48.345.0,46.323.0,61.330.0"}
P.entries["quest:98407"] = {n="Show of Force",s="Show of Force är ett defensivt uppdrag för Alliansen i Redridge Mountains, som Deputy Feldon har gett. För att hejda gnollflockar som tränger fram mot Lakeshire skickas äventyrare ut för att jaga gnoll thrashers och samla in deras taggiga halsband, så att vidare intrång i mänskliga bosättningar avskräcks.",h="Show of Force är ett defensivt uppdrag för Alliansen i Redridge Mountains, som Deputy Feldon har gett.",kw={"deputy feldon","gnoll thrasher","gnoller","lakeshire","redridge mountains","show of force","taggigt halsband"},ang={["class:Warrior"]="Gnoller ger bara vika för uppvisningar av direkt, förkrossande våld. Därför är en rak militär disciplin vid frontlinjen det bästa sättet att bryta deras led.",["faction:Alliance"]="Lakeshire är en av Alliansens östligaste utposter i södra Eastern Kingdoms. Att säkra dess gränser mot vilddjursangrepp är avgörande för stabiliteten i området.",["race:Human"]="Redridges nybyggare och stadsbor är undersåtar av Stormwind, lämnade farligt oskyddade och beroende av sina fränder för att slå tillbaka vilda plundrare."},sec={{t="Ett djärvt intrång",b="Redridge Mountains har länge gett skydd åt vilda gnollstammar, men de har blivit allt djärvare. I stället för att hålla sig isolerade högt uppe bland de klippiga kullarna har gnollernas plundrarflockar slagit läger oroväckande nära Lakeshire och de avlägsna mänskliga gårdarna. Stormwinds militär är hårt ansträngd och kan inte avvara förstärkningar till landsbygdens gränstrakter, så de lokala myndigheterna måste förlita sig på förbipasserande äventyrare för att säkra området innan de framryckande banden vågar anfalla själva staden."},{t="Tala deras språk",b="Deputy Feldon vet att gnoller är brutala och oorganiserade varelser som knappt respekterar något utöver ren militär överlägsenhet. Diplomatiska vädjanden och halvhjärtade åtgärder hjälper inte om de ska drivas tillbaka ut i vildmarken. Feldon vill slå mot deras våldsammaste förtrupper, gnoll thrashers, och ta deras taggiga halsband som ett bistert bevis på överlägsenhet. Genom att slå ut deras främsta krigare och visa upp troféerna från deras nederlag hoppas Lakeshires försvarare skrämma de överlevande flockarna till reträtt upp i högländerna."}},faq={{q="Vem erbjuder uppdraget och var finns de?",a="Uppdraget erbjuds av Deputy Feldon, en stadsvakt som är stationerad vid områdets gräns nära Lakeshire i Redridge Mountains.",al={"uppdragsgivare","deputy feldons plats","vem ger show of force"}},{q="Varför tränger gnollerna så nära Lakeshire?",a="Gnoller är aggressiva opportunister som prövar sina gränser. Eftersom Lakeshire kämpar med försvaret och får lite militär hjälp från Stormwind har gnollerna blivit så djärva att de slagit upp jaktläger alldeles utanför de mänskliga bosättningarna.",al={"varför anfaller gnollerna","gnollhot i redridge","varför är gnollerna nära"}},{q="Vilka fiender måste besegras i det här uppdraget?",a="Uppdraget riktar in sig på gnoll thrashers, de farligare och mer aggressiva anfallsgrälarna i de lokala flockarna, som bär tunga taggiga halsband.",al={"vilka gnoller","vilka fiender ska dödas","gnoll thrashers"}},{q="Varför vill Deputy Feldon särskilt ha taggiga halsband?",a="Gnoller styrs av en brutal hierarki och råstyrka. Att ta halsbanden från deras thrashers visar upp direkt våldsam styrka och ska skrämma de överlevande gnollerna till att retirera upp i bergen.",al={"varför taggiga halsband","halsbandets syfte","varför ta halsband"}},{q="Kan Stormwind skicka soldater för att ta hand om gnollerna?",a="Stormwind har i stort sett lämnat Redridge att försvara sig självt. Huvudstaden står inför inre instabilitet och brist på trupper i hela riket och har skickat nästan inga förstärkningar, så de lokala deputerade tvingas förlita sig på självständiga hjältar.",al={"stormwinds hjälp till redridge","varför ingen stormwind-armé","var finns vakterna"}},{q="Var brukar gnollerna slå läger i Redridge?",a="Gnollernas läger ligger utspridda bland kullarna och de låga höjdryggarna intill Lake Everstill och längs vägarna österut mot Stonewatch-området.",al={"gnolläger","var hittar man gnoller","gnollplatser i redridge"}}},fp="13,284,19.520.0,23.530.0,49.120.0,49.244.0,50.136.0,56.214.0,55.228.0,52.149.0"}
P.entries["quest:98423"] = {n="The Treaty of Understanding",s="The Treaty of Understanding är en forntida dvärgtavla som beskriver det historiska fredsavtalet mellan Bronzebeard- och Wildhammer-klanerna efter War of the Three Hammers. Den återfanns i underjordiska djup och fördes inför King Magni Bronzebeard. Artefakten bevarar ett avgörande ögonblick i dvärgarnas historia och visar samtidigt den bittra spricka som höll Dark Iron-klanen utanför freden.",h="The Treaty of Understanding är en forntida dvärgtavla som beskriver det historiska fredsavtalet mellan...",kw={"dark iron","ironforge","madoran bronzebeard","magni bronzebeard","fredsavtal","treaty of understanding","war of the three hammers","wildhammer"},ang={["faction:Alliance"]="Den historiska freden mellan Bronzebeard- och Wildhammer-dvärgarna lade grunden för deras moderna samarbete inom Grand Alliance.",["race:Dwarf"]="Den här stentavlan är ett påtagligt vittnesmål om dvärgarnas försoning och visar hur dina förfäder lade fejden åt sidan efter kampen om berget."},sec={{t="En relik som försonade dvärgar",b="The Treaty of Understanding återfanns djupt inne i ett forntida valv. Den är en historisk stentavla som dokumenterar det formella slutet på fientligheterna mellan dvärgklaner. Den härrör från den oroliga tiden efter War of the Three Hammers och markerar ögonblicket då fred slöts mellan Bronzebeard- och Wildhammer-klanerna, efter att Bronzebeard-klanen säkrat kontrollen över Ironforge-berget."},{t="Den osignerade freden",b="När den återfunna tavlan visas upp känner King Magni Bronzebeard igen den som ett verk av sin förfader Madoran Bronzebeard, den förste Bronzebeard-kungen av Ironforge. Dokumentet bär underskrifterna från både Bronzebeard- och Wildhammer-ledarna, men saknar tydligt Dark Iron-klanens märke. Det vittnar än i dag om den bestående sprickan mellan Dark Irons och deras släktingar från berget."}},faq={{q="Vad är The Treaty of Understanding?",a="The Treaty of Understanding är en forntida dvärgisk stentavla som återfanns i djupa valv. Den beskriver det formella fredsavtalet mellan Bronzebeard- och Wildhammer-klanerna, som slöts direkt efter War of the Three Hammers.",al={"vad är treaty of understanding","avtalstavla","vad är det här för avtal"}},{q="Vem skapade avtalet?",a="Avtalet skrevs i tiden efter War of the Three Hammers, under Madoran Bronzebeards regeringstid. Han var den förste Bronzebeard-kungen av Ironforge, efter att de tre klanerna kämpat om berget.",al={"vem skrev treaty of understanding","vem skapade treaty of understanding","vem utformade avtalet"}},{q="Varför skrev Dark Iron-klanen inte under avtalet?",a="Dark Iron-klanen vägrade acceptera fred efter att Bronzebeard-klanen tagit kontroll över Ironforge. Därför skrev bara Bronzebeard- och Wildhammer-klanerna under avtalet, vilket lämnade Dark Irons isolerade och fientligt inställda.",al={"varför skrev dark iron inte under","skrev dark iron under avtalet","dark irons saknas på avtalet"}},{q="Vem är intresserad av The Treaty of Understanding?",a="Tavlan överlämnas till King Magni Bronzebeard i High Seat i Ironforge. Han värdesätter den som en ovärderlig relik efter sin förfader Madoran och som ett stycke dvärghistoria.",al={"vem vill ha avtalet","vem ska jag lämna treaty of understanding till","var lämnar jag in avtalet"}},{q="Vad var War of the Three Hammers?",a="War of the Three Hammers var ett bittert inbördeskrig mellan dvärgklanerna Bronzebeard, Wildhammer och Dark Iron om kontrollen över Ironforge-berget. Bronzebeard-klanen segrade och tog berget, medan de andra klanerna drevs bort.",al={"vad var war of the three hammers","dvärgarnas inbördeskrig","three hammers-kriget"}},{q="Vem var Madoran Bronzebeard?",a="Madoran Bronzebeard var förfader till King Magni Bronzebeard och den förste Bronzebeard-kungen som styrde Ironforge efter inbördeskriget mellan de tre dvärgklanerna.",al={"vem är madoran bronzebeard","madoran bronzebeard","magni förfader madoran"}}},fp="27,406,33.386.0,18.411.0,36.252.0,23.210.0,47.215.0,49.162.0,38.254.0,28.166.0"}
P.entries["quest:98459"] = {n="A Lack of Virtue",s="A Lack of Virtue är ett leveransuppdrag om ett långlivat småaktigt agg mellan två sjömän som spelar kort, Tom Half-fish och Bart Tidewater. Resande fraktar en inslagen gåva över havet till Menethil Harbor och hamnar mitt i en ömsesidig anklagelse om fusk kring hur Maiden's Virtue vanns.",h="A Lack of Virtue är ett leveransuppdrag om ett långlivat småaktigt agg mellan två sjömän som spelar kort, Tom...",kw={"a lack of virtue","bart tidewater","maidens virtue","menethil harbor","poker","tanaris","tom half-fish","tom's gift","wetlands"},ang={["faction:Alliance"]="Alliansresande som passerar Menethil Harbor stöter ofta på Bart Tidewater när han skäller order till sin besättning. Leveransen blir ett snabbt avbrott medan du väntar på transport över Great Sea."},sec={{t="Ett bittert agg",b="A Lack of Virtue kretsar kring en bitter rivalitet mellan två saltstänkta sjöfarare och spelare: Tom Half-fish och Bart Tidewater. Tom värvar förbipasserande resande för att frakta ett inslaget paket över vattnet till Bart i Menethil Harbor, som en småaktig, illvillig pik mot sin tidigare följeslagare. På vägen varnar Tom för att Bart inte alls är någon riktig sjöbuse, utan en före detta skådespelare som fuskade i kortspel för att köpa sitt befäl."},{t="Korten på bordet",b="När Bart Tidewater får Tom's Gift på kajen i Menethil Harbor blir han rasande bara den gamle bekantens namn nämns. Bart vänder genast anklagelsen mot Tom och svär på att det var Tom som fuskade i kortspel och att Bart bara vann tillräckligt med mynt för att köpa Maiden's Virtue efter att deras pokerkrets uteslutit Half-fish. Trots sitt häftiga vredesutbrott hejdar sig Bart snart, ber kuriren om ursäkt för sitt rytande och hälsar resanden välkommen till hamnen."}},faq={{q="Vem är Bart Tidewater?",a="Bart Tidewater är den självutnämnde kaptenen på Maiden's Virtue, som ligger förtöjd i Menethil Harbor. Enligt hans gamle bekant Tom Half-fish var Bart ursprungligen skådespelare och köpte sitt skepp för vinster från pokerspel, fast båda männen anklagar varandra för att fuska i kortspel.",al={"vem är bart tidewater","bart tidewaters bakgrund","vem är kapten på maidens virtue"}},{q="Vem är Tom Half-fish?",a="Tom Half-fish är en gammal bekant till Bart Tidewater som ger resande en gåva att frakta över havet till Bart. Han hyser ett glödande agg mot kaptenen och hävdar att Bart är en bedragare, en snåljåp och en fuskare i kortspel.",al={"vem är half-fish","vem är tom half-fish","vem ger uppdraget a lack of virtue"}},{q="Vad är Maiden's Virtue?",a="Maiden's Virtue är ett fartyg som ligger förtöjt i Menethil Harbor i Wetlands. Bart Tidewater hävdar att det är det finaste skeppet på Great Sea, fast Tom Half-fish hånfullt påstår att fartyget har seglat lika långt som en klippa i Tanaris.",al={"vad är maidens virtue","maidens virtue skepp","var finns maidens virtue"}},{q="Vad är Tom's Gift?",a="Tom's Gift är ett paket som Tom Half-fish skickar till Bart Tidewater i Menethil Harbor. Kuriren får aldrig veta vad det innehåller, men mottagandet får genast Bart att brista ut i rasande förolämpningar om Toms eget pokerspel och fusk.",al={"vad är tom's gift","vad finns i tom's gift","varför blir bart arg på tom's gift"}},{q="Vem fuskade egentligen i poker?",a="Båda sjömännen anklagar varandra häftigt för fusk. Tom Half-fish insisterar på att Bart är en skådespelare som bara vann tillräckligt många pokerhänder för att köpa sitt skepp genom att fuska, medan Bart hävdar att han vann sitt fartyg på hederligt vis först efter att ha kastat ut Tom ur deras pokerkrets för fusk.",al={"vem fuskade i poker","fuskade bart i poker","fuskade tom i poker"}},{q="Hur lämnar du gåvan i Menethil Harbor?",a="Resande kan ta sig till Menethil Harbor i Wetlands med båt över Great Sea. Uppdragsgivaren nämner att en direkt båttur stannar vid hamnen på sitt andra stopp.",al={"hur tar jag mig till menethil harbor","båt till menethil harbor"}}},fp="16,307,15.452.0,18.486.1,22.281.0,21.231.0,28.229.0,19.251.0,30.269.0,47.179.0"}
P.entries["quest:98461"] = {n="Unrequited Love",s="Unrequited Love är ett leveransuppdrag för Alliansen som börjar i Auberdine vid Darkshores kust. Hollee ber resenärer på väg med båten till Menethil Harbor att överlämna en personlig hälsning till Tarrel Rockweaver, en studiekamrat från utgrävningsutbildningen som hon fortfarande hyser varma känslor för.",h="Unrequited Love är ett leveransuppdrag för Alliansen som börjar i Auberdine vid Darkshores kust.",kw={"auberdine","darkshore","utgrävning","hollee","hollee's note","menethil harbor","merrin","tarrel rockweaver","unrequited love","wetlands"},ang={["faction:Alliance"]="Den här leveransen förbinder Alliansens hamn Auberdine i Darkshore direkt med Menethil Harbor i Wetlands och knyter samman Kalimdor och Eastern Kingdoms.",["race:Dwarf"]="Tarrel Rockweaver och Hollee har båda erfarenhet av utgrävning, ett yrke som har en central plats i dvärgarnas traditioner och studier på Azeroth."},sec={{t="Ett meddelande över havet",b="I hamnstaden Auberdine längs Darkshores dimmiga kust ser Hollee resenärer gå ombord på fartyg till Eastern Kingdoms. Hon söker hjälp av förbipasserande att nå en gammal studiekamrat, Tarrel Rockweaver. De tillbringade flera år med att studera utgrävningskonsten innan examen skilde dem åt över kontinenterna."},{t="Outtalade känslor",b="Hollee minns Tarrels skarpa intellekt och skicklighet inom utgrävning med värme, men tappar fattningen när hans fru Merrin kommer på tal. Trots avståndet och hans äktenskap anförtro hon en äventyrare ett personligt brev och ber dem söka upp Tarrel nära Menethil Harbor för att försäkra sig om att han är trygg."}},faq={{q="Vem erbjuder uppdraget Unrequited Love?",a="Hollee ger uppdraget i kustbosättningen Auberdine i Darkshore. Hon ber resenärer som går ombord på båten till Menethil Harbor att lämna en personlig hälsning till en gammal skolkamrat.",al={"vem ger uppdraget unrequited love","uppdragsgivare auberdine"}},{q="Vem är Tarrel Rockweaver?",a="Tarrel Rockweaver är utgrävare och Hollees före detta skolkamrat. Efter deras studier skickades han till Wetlands, där han nu arbetar nära Menethil Harbor tillsammans med sin fru Merrin.",al={"vem är tarrel rockweaver","tarrels bakgrund"}},{q="Vem är Merrin?",a="Merrin är Tarrel Rockweavers fru. Hollee nämner henne med tydlig tvekan och rynkad panna, vilket avslöjar hennes kvarvarande, obesvarade känslor för Tarrel trots hans äktenskap.",al={"vem är merrin","tarrels fru"}},{q="Varför heter uppdraget Unrequited Love?",a="Titeln syftar på Hollees stillsamma känslor för Tarrel Rockweaver. De studerade utgrävning tillsammans som nära skolkamrater, men Tarrel gifte sig med Merrin och lämnade Hollee att längta efter honom på andra sidan havet i Auberdine.",al={"vad handlar uppdraget unrequited love om","varför heter det unrequited love"}},{q="Var finns Tarrel Rockweaver?",a="Tarrel Rockweaver finns nära Menethil Harbor i Wetlands, på andra sidan Stora havet från Darkshore. En passagerarbåt från Auberdine tar resenärer direkt till hamnens bryggor.",al={"var hittar man tarrel rockweaver","tarrels plats wetlands"}},{q="Vilket föremål ska lämnas i uppdraget?",a="Du ska ta med Hollee's Note till Tarrel Rockweaver för att se hur han mår i Wetlands och lämna hennes personliga meddelande.",al={"vad ska lämnas","hollees brev"}}},fp="15,272,24.318.0,17.299.0,37.180.0,25.188.0,14.182.0,40.208.0,35.183.0,37.134.0"}
P.entries["quest:98463"] = {n="Talk of the Town",s="En vänlig värdshusvärd visar resenärer som söker ett livligare sällskap till hamnen Booty Bay i Stranglethorn Vale. Den som vill ha vildare sällskap får rådet att leta upp Nixxrax Fillamug på Salty Sailor Tavern.",h="En vänlig värdshusvärd visar resenärer som söker ett livligare sällskap till hamnen Booty Bay i Stranglethorn...",kw={"booty bay","goblinvärdshus","nixxrax fillamug","salty sailor tavern","stranglethorn vale","talk of the town"},sec={{t="Ett ord över disken",b="Ord sprids snabbt mellan serveringspersonal och gäster, och nyheter färdas långt bortom den lokala disken. En vänlig bartender tipsar om var det verkligen är livat och hänvisar den som söker vildare nöjen till hamnen Booty Bay."},{t="Salty Sailor",b="Målet är Salty Sailor Tavern, ett livligt etablissemang som drivs av gobliner mitt i Stranglethorn Vales myller. Där håller Nixxrax Fillamug muggarna fyllda åt alla som kommer in."}},faq={{q="Vart leder det här?",a="Det leder till Stranglethorn Vale, rakt till hamnstaden Booty Bay som drivs av gobliner.",al={"vart ska jag gå","resmål","vägbeskrivning till booty bay"}},{q="Vem ska du leta upp i Booty Bay?",a="Du får rådet att leta upp Nixxrax Fillamug inne på Salty Sailor Tavern, där han ser till att allas drycker är påfyllda.",al={"vem ska besökas","vem är nixxrax","nixxrax fillamug"}},{q="Varför skicka någon ända till Stranglethorn Vale?",a="Bartendrar hör allt skvaller från sina gäster, och ryktet säger att Salty Sailor Tavern bjuder på traktens vildaste festligheter, trots att gobliner sköter stället.",al={"varför salty sailor","varför åka till booty bay","varför rekommendationen"}}},fp="16,221,25.271.0,16.199.0,21.84.0,42.117.0,51.166.0"}
P.entries["quest:985"] = {n="How Big a Threat?",s="How Big a Threat? är ett alliansuppdrag som ges av nattalven Terenthis i Auberdine. Äventyrarna har redan spanat på det fientliga Blackwood-furbolglägret söder om staden och skickas nu för att decimera de korrumperade stigfinnarna och vindviskarna innan deras raseri hotar bosättningen.",h="How Big a Threat?",kw={"auberdine","blackwood","darkshore","fel moss","furbolg","grimclaw","stigfinnare","terenthis","vindviskare"},ang={["class:Druid"]="Druider känner tragedin djupt, eftersom furbolgernas öde speglar skogens fortsatta lidande under felmossans besudling.",["faction:Alliance"]="Auberdine är en livsviktig hamn för Alliansen i Darkshore, vilket gör det avgörande för regionens säkerhet att slå ut fientliga läger i närheten.",["race:NightElf"]="För nattalverna är decimeringen av Blackwood en bitter sorg. Århundraden av släktskap med furbolgerna har krossats av den demoniska farsot som dröjer kvar efter det tredje kriget."},sec={{t="En nödvändig decimering",b="Efter den första spaningen söder om Auberdine har Sentinels fastställt att Blackwood-furbolgerna utgör en omedelbar fara för Darkshores flyktingar och försvarare. Terenthis ger stridsdugliga resenärer i uppdrag att slå direkt mot lägret och eliminera Blackwood Pathfinders och Windtalkers för att bryta deras offensiva framfart."},{t="De korrumperades tragedi",b="Nattalver ser traditionellt furbolgerna som andliga fränder och vildmarkens gamla allierade. Men den onda spridningen av felmossa och demonisk besudling över norra Kalimdor har drivit Blackwood-stammen till vansinne. Eftersom det inte finns något känt botemedel som kan återställa furbolgernas sinnen ser Auberdines försvarare våld som en dyster nödvändighet för att förhindra oskyldigas död."},{t="Grimclaw anländer",b="När du rapporterar decimeringen till Terenthis rusar en vit björn vid namn Grimclaw in i Auberdine, mot nattalven. Ankomsten förebådar nya brådskande händelser kring djurlivet och korruptionen som härjar längs kusten och inleder nästa steg i Auberdines försvar."}},faq={{q="Varför vill Terenthis döda Blackwood-furbolgerna?",a="Blackwood-stammen söder om Auberdine har fallit offer för korruption och blivit våldsam och irrationell. Eftersom deras läger utgör ett överhängande hot mot bosättningen och inget botemedel mot korruptionen har upptäckts, beordrar Terenthis en förebyggande attack för att skydda Auberdine.",al={"varför döda blackwood-furbolger","orsak till att decimera furbolger","terenthis furbolguppdrag"}},{q="Var ligger Blackwood-furbolglägret?",a="Lägret ligger strax söder om Auberdine, i Darkshores kustskog, bland de korrumperade träden där Blackwood-stammen har samlats.",al={"blackwood-furbolgernas plats","var finns stigfinnare och vindviskare","furbolgläger i darkshore"}},{q="Vem är Grimclaw?",a="Grimclaw är en vit björn som är knuten till vildmarksundersökningarna i Darkshore.",al={"vit björn i auberdine","grimclaw björnen"}},{q="Vad får furbolgerna att bli vansinniga?",a="Furbolgerna har förgiftats av felmossa och kvarvarande demonisk korruption från tiden efter det tredje kriget. De mörka energierna som härjar i Darkshore förvrider både kropp och sinne och driver fredliga stammar till okontrollerad aggression.",al={"varför är furbolgerna galna","furbolgernas korruption i darkshore","vad korrumperade blackwood"}},{q="Varför tvekar nattalver att döda furbolger?",a="Furbolgerna och nattalverna har haft ett vänskapsband och vördat naturen tillsammans i tusentals år. För nattalverna känns det som att slakta sina egna vilda bröder att avliva dem, men korruptionen lämnar inget annat val.",al={"nattalver och furbolger","varför sörja furbolgerna"}},{q="Vad är skillnaden mellan det första och det andra uppdraget ”How Big a Threat?”?",a="Det första uppdraget prövar din förmåga att spana genom att kräva att du hittar och observerar Blackwood-lägret. Det andra uppdraget är ett direkt stridsuppdrag där du ska decimera lägrets stigfinnare och vindviskare när hotet väl har bekräftats.",al={"delar av how big a threat","skillnad mellan how big a threat-uppdragen"}}},fx={a17cffed={q="Varför skickar Terenthis en äventyrare i stället för Auberdines väktare?",a="Terenthis vänder sig till en resenär som redan har visat sig skicklig på att spana på Blackwood-lägret. Han frågar om samma resenär är beredd att möta stammen i strid och minska hotet mot Auberdine.",al={"varför skicka mig","varför inte använda vakter","varför behöver terenthis mig"}},["0dbe6a0f"]={q="Vilka är Blackwood-spejarna och vindpratarna?",a="De är medlemmar av furbolgstammen Blackwood, som har slagit läger söder om Auberdine. Skogskorruptionen sprider sig, gör dem vansinniga och aggressiva, och deras spejare och schamaner utgör ett omedelbart och växande hot mot nattalvbebyggelsen. Tills ett botemedel mot deras plåga upptäcks anser Terenthis att det enda sättet att skydda sitt folk är att decimera deras led.",al={"blackwood-spejare","blackwood-vindpratare","vem dödar vi"}}},fp="17,188,16.285.0,24.309.0,18.289.1,54.201.0,44.144.0,16.81.1,39.186.0,47.189.0,79.168.0"}
P.entries["quest:98512"] = {n="Al'Aketh Assassins",s="Al'Aketh Assassins är ett uppdrag där en farlig grupp dödliga mördare ska elimineras. Äventyrare hjälper en spejare att undanröja hotet och får ett formellt erkännande som ska tas med i en rapport till Valanaar.",h="Al'Aketh Assassins är ett uppdrag där en farlig grupp dödliga mördare ska elimineras.",kw={"al'aketh","mördare","uppdrag","rapport","valanaar"},ang={["class:Rogue"]="Att möta dödliga mördare som Al'Aketh kräver samma dödliga fokus och skoningslösa precision."},sec={{t="Ett dödligt hot",b="Al'Aketh-mördarna utgör ett dödligt hot i fältet och beskrivs av spejare på plats som iskalla mördare. Deras skoningslösa effektivitet och samordnade närvaro gör varje konfrontation med dem ytterst farlig för både lokala spejare och resenärer. De måste hanteras snabbt och beslutsamt innan de hinner slå till mot sina mål."},{t="Rapport till Valanaar",b="När den fientliga Al'Aketh-styrkan har oskadliggjorts uttrycker en allierad fältagent stor lättnad över att du överlevde mötet med så farliga motståndare. Spejaren är tacksam för ditt snabba ingripande och lovar att dokumentera din heroiska hjälp i en officiell rapport till Valanaar."}},faq={{q="Vad är Al'Aketh Assassins?",a="Al'Aketh Assassins är ett uppdrag där äventyrare ska eliminera en dödlig grupp Al'Aketh-agenter. Hotet de utgör är så allvarligt att omedelbara åtgärder och en officiell rapport krävs.",al={"vad är alaketh assassins","vad är det här för uppdrag","alaketh assassins uppdrag"}},{q="Vilka är Al'Aketh-mördarna?",a="Al'Aketh-mördarna beskrivs som iskalla mördare som verkar som en samordnad och farlig anfallsstyrka. Deras dödliga framtoning gör dem till ett allvarligt hot i fältet.",al={"vilka är alaketh","vilka är alaketh-mördarna","alaketh-mördare"}},{q="Vad är Valanaar?",a="Valanaar är bosättningen vid öns sydöstra kant och en bas för dess fredsvakter. Spejaren planerar att ta med din hjälp i en rapport när hen återvänder till Valanaar.",al={"vad är valanaar","rapport till valanaar","rapportera till valanaar"}},{q="Varför måste Al'Aketh-mördarna hanteras?",a="Al'Aketh-mördarna utgör ett omedelbart dödligt hot mot agenter och resenärer i området. De måste oskadliggöras för att skydda de allierade styrkorna och säkra deras överlevnad.",al={"varför slåss mot alaketh","varför döda alaketh-mördarna","alaketh-hot"}},{q="Vad händer efter att mördarna har hanterats?",a="Efter konfrontationen med mördarna förbereder sig spejaren på att rapportera tillbaka till Valanaar och erkänner din avgörande hjälp under uppdraget.",al={"vad händer efter alaketh assassins","nästa uppdrag alaketh","rapportera till valanaar uppdrag"}},{q="Vem erkänner din hjälp med att besegra mördarna?",a="Uppdraget involverar en allierad fältagent som övervakar fientliga rörelser. Spejaren är tacksam för ditt ingripande mot de dödliga mördarna och noterar ditt bidrag för befälet.",al={"vem ger alaketh assassins","vem är spejaren","spejarens rapport valanaar"}}},fp="18,221,15.370.0,21.289.0,27.207.0,31.177.0,16.178.0,46.178.0,46.164.0,53.200.0"}
P.entries["quest:98545"] = {n="Leonid's Letter",s="Leonid's Letter är ett leveransuppdrag som leder resenärer ner i Undercitys djup. Leonid är försiktig med att själv gå in i De bortglömdas huvudstad, eftersom han har en ansträngd relation till Lady Sylvanas Windrunner. Därför anlitar han en opartisk kurir som ska överlämna ett meddelande till Glix Xizzix, en gammal goblinkontakt i Trade Quarter.",h="Leonid's Letter är ett leveransuppdrag som leder resenärer ner i Undercitys djup.",kw={"dark lady","glix xizzix","leonid","hittegods","naxxramas","förseglat brev","sylvanas","trade quarter","undercity"},ang={["faction:Horde"]="När du tar dig in i De bortglömdas huvudstad på uppdrag av en utomstående får Horde-äventyrare enkel tillgång till bekvämligheterna i Undercitys Trade Quarter.",["race:Undead"]="Leonids bakgrund med Dark Lady hindrar honom från att själv kliva in i Undercity och visar på de politiska spänningarna mellan oberoende odöda och Sylvanas lojala anhängare."},sec={{t="Ett ärende åt en utomstående",b="Leonid behöver en kurir som kan lämna ett förseglat brev till en bekant i Undercity. På grund av tidigare motsättningar och en ansträngd relation till Lady Sylvanas Windrunner väljer Leonid att inte själv gå genom De bortglömdas huvudstad. I stället litar han på en kringresande neutral part som kan passera stadens vakter utan att väcka misstankar."},{t="Gamla kamrater i Trade Quarter",b="Mottagaren är Glix Xizzix, en opportunistisk goblin som gör affärer i Undercitys Trade Quarter. När Glix får meddelandet minns han hur han och Leonid överlevde sida vid sida i skuggan av Scourge-citadellet Naxxramas. Han blir både förvånad och irriterad över Leonids löfte om ersättning, men betalar motvilligt ur sortimentet av kvarglömda saker som vårdslösa odöda kunder lämnat efter sig."}},faq={{q="Vem är Leonid och varför går han inte in i Undercity?",a="Leonid är en erfaren soldat som upprätthåller känsliga relationer med flera fraktioner. På grund av en komplicerad bakgrund med Lady Sylvanas Windrunner undviker han att gå in i Undercity själv och förlitar sig på kringvandrande äventyrare som kan lämna meddelanden till hans bekanta.",al={"vem ger leonid brevet","leonid barthalomew","leonid uppdragsgivare"}},{q="Vem är Glix Xizzix?",a="Glix Xizzix är en goblin som håller till i Undercitys livliga Trade Quarter. Han verkar arbeta i närheten av frisörtjänster och har en samling kvarglömda saker som tankspridda odöda kunder lämnat efter sig.",al={"var finns glix xizzix","vem är glix xizzix","goblinfrisör i undercity"}},{q="Vad har Leonid för bakgrund med Dark Lady?",a="Leonid medger att han har en ”något färgstark bakgrund” med Sylvanas Windrunner, De bortglömdas bansheedrottning. För att inte riskera att reta upp henne eller hennes vakter anlitar han neutrala mellanhänder för sina ärenden inne i staden.",al={"leonids bakgrund med dark lady","leonid och sylvanas"}},{q="Hur känner Leonid och Glix varandra?",a="Glix minns Leonid som en erfaren veteran från hårda militära strider mot Scourge. Han minns hur den fruktade citadellet Naxxramas regnade förödelse över dem.",al={"glix xizzix leonid naxxramas","hur känner glix och leonid varandra"}},{q="Varför belönar Glix dig med kvarglömda saker?",a="Leonid sa till kuriren att Glix gärna skulle betala dricks, men Glix hade inte lovat något sådant. Goblinen går motvilligt med på det och erbjuder märkliga prydnadssaker från salongens hittegods, sådant som tankspridda kunder ur De bortglömda lämnat efter sig.",al={"uppdragsbelöning från glix","varför hittegods"}},{q="Vart levereras brevet?",a="Brevet förs ner till De bortglömdas huvudstad Undercity, rakt in i Trade Quarter där köpmän, hantverkare och gobliner gör affärer under Royal Apothecary Societys och stadsvakternas vaksamma blickar.",al={"vart ska leonids brev levereras","leverans till trade quarter"}}},fp="15,315,20.328.0,33.404.0,47.259.0,19.218.0,44.236.0,39.175.0,51.231.0,30.227.0"}
P.entries["quest:98574"] = {n="Hallowed Memorandum",s="Hallowed Memorandum är en skriftlig kallelse som ber blivande gnompräster i Coldridge Valley att möta Branstock Khalder i Anvilmar. Den inleder deras andliga träning och beskriver Holy Light som en filosofisk gåta, väl lämpad för gnomers intellekt och nyfikenhet.",h="Hallowed Memorandum är en skriftlig kallelse som ber blivande gnompräster i Coldridge Valley att möta...",kw={"anvilmar","branstock khalder","coldridge valley","dun morogh","gnompräst","hallowed memorandum","holy light"},ang={["class:Priest"]="Det här memorandumet markerar början på den formella prästutbildningen i Coldridge Valley och introducerar blivande helare till Holy Lights filosofi.",["race:Gnome"]="Gnomer som närmar sig Light tar med sig skarpt intellekt och nyfikenhet till sina andliga studier och begrundar de heliga mysterierna som gåtor vid sidan av tron."},sec={{t="En kallelse till Anvilmar",b="När de hjälper sina allierade i Coldridge Valley får lovande gnomnoviser Hallowed Memorandum, ett inledande meddelande som ber dem söka upp Branstock Khalder i Anvilmar. Anteckningen är en uppmaning till andliga studier och bjuder in blivande präster att påbörja sin formella utbildning i Dun Morogh."},{t="Trons gåtor",b="När novisen visar upp memorandumet välkomnar Branstock Khalder hen. Han förklarar att fördjupning i Holy Light inte är ett strikt tekniskt hantverk, utan en djupgående gåta som kräver nyfikenhet, skarpt intellekt och harmoni mellan tanke och känsla. Genom begrundan och övning lär sig eleverna att kanalisera dessa heliga mysterier till läkande krafter och gudomlig vedergällning."}},faq={{q="Vem skickade Hallowed Memorandum?",a="Memorandumet förmedlades av en lokal allierad medan du hjälpte till i Coldridge Valley. Det kom ursprungligen från Branstock Khalder, prästtränaren som bor i Anvilmar.",al={"vem gav mig memorandumet","vem skickade hallowed memorandum","varifrån kom anteckningen"}},{q="Vem är Branstock Khalder?",a="Branstock Khalder är en dvärgisk prästtränare i Anvilmar i Coldridge Valley. Han vägleder blivande präster i att förstå Light och använda heliga krafter för att läka sår eller slå ner ondska.",al={"vem är branstock","branstock khalder i anvilmar"}},{q="Hur närmar sig gnomer Holy Light?",a="Branstock förklarar att gnomers nyfikenhet och intellekt är naturliga vägar till förståelse av Light. I stället för att se det som ett strikt tekniskt hantverk uppmuntrar han dem att betrakta det som en filosofisk gåta som förenar tanke och känsla.",al={"kan gnomer bli präster","gnomers koppling till light","hur ser gnomer på light"}},{q="Vad lär Branstock ut om Light?",a="Branstock beskriver Light som en gåta som ger praktiska välsignelser och lärdomar om livet, inte som en krävande teknisk disciplin. Gåtan kan lösas genom att förena sina tankar med sina innersta känslor.",al={"vad är light enligt branstock","branstocks gåta om light"}},{q="Vilka förmågor kan Branstock lära ut?",a="När en präst börjar förstå Light erbjuder Branstock vägledning i att kanalisera dess kraft till skyddande helande böner och heliga slag mot de onda, i utbyte mot en blygsam donation.",al={"vad lär branstock ut","vad kan prästtränare lära ut"}},{q="Var finns Branstock Khalder?",a="Anvilmar är en central fästning och välkomsthall i hjärtat av Coldridge Valley i Dun Morogh. Där finns tränare och en fristad för dvärgar och besökande gnomer.",al={"var ligger anvilmar","var finns branstock"}}},fp="19,298,21.309.0,20.398.0,33.184.0,25.205.0,38.246.0,42.193.0,45.208.0,37.168.0"}
P.entries["quest:98575"] = {n="Tainted Tablet",s="Tainted Tablet är ett nybörjaruppdrag i Valley of Trials som leder blivande magiker till Nartok i The Den. Det introducerar Durotars demonbesvärjares pragmatiska men försiktiga synsätt. De söker kraft från Nether för att forma sitt eget öde, trots att det förflutna fortfarande kastar en skugga över dem.",h="Tainted Tablet är ett nybörjaruppdrag i Valley of Trials som leder blivande magiker till Nartok i The Den.",kw={"durotar","nartok","nether","tainted tablet","the den","valley of trials","demonbesvärjare"},ang={["class:Warlock"]="Tainted Tablet markerar den formella introduktionen av Durotars blivande demonbesvärjare till deras tränare, Nartok. Den uppmanar dem att bemästra Nether i stället för att frukta dess kraft.",["faction:Horde"]="Thralls nya Horde är på sin vakt mot demonisk fördärvning, men utövare som håller till på platser som The Den hävdar att de tryggt kan härska över Nether-krafter och säkra en framtid för sitt folk.",["race:Orc"]="Med tanke på demonpaktens katastrofala arv på Draenor är felmagi fortfarande kontroversiell bland orker. Därför råder Durotars demonbesvärjare dem att hålla sig dolda och visa mod."},sec={{t="En mörk kallelse",b="Tainted Tablet är ett inskrivet meddelande till nyanlända utövare som inleder sin färd i Valley of Trials. Stenen har passerat genom oroliga lägerförvaltares händer och bär en kallelse från Nartok, en tränare i demonbesvärjelse som har sitt hem i The Dens skuggiga djup. Meddelandet bjuder in läsaren att lämna vanliga stamplikter bakom sig och utforska magins djupare, förbjudna strömningar."},{t="Att härska över Nether",b="När Nartok får svar på sin kallelse talar han öppet om orkernas stormiga historia med Nether. Han menar att de starka måste gripa makten över sitt eget öde, i stället för att avsvära sig dessa oberäkneliga krafter av skam eller rädsla. I hans ögon kommer utövare som med list bemästrar varelser från Nether att nå framgång där vanliga hövdingar misslyckas. Men eftersom rädda sinnen gärna angriper det de inte förstår varnar han för att alltid hålla sådana krafter väl dolda."}},faq={{q="Vad är Tainted Tablet?",a="Tainted Tablet är en skriftlig kallelse som lämnas till en blivande utövare i Valley of Trials. Den uppmanar dem att söka upp Nartok, deras klasstränare, som väntar i The Den.",al={"vad är tainted tablet","uppdraget tainted tablet","tavlans syfte"}},{q="Vem skickade Tainted Tablet?",a="Tavlan skickades av Nartok, en orsk demonbesvärjare och tränare som håller till i The Den i Valley of Trials. Han använder den för att presentera sig för nyanlända utövare och bjuda in dem till undervisning.",al={"vem skrev tavlan","vem är nartok","vem skickade tavlan"}},{q="Var finns Nartok?",a="Nartok bor i The Den, en grotta undangömd i Valley of Trials där mörkare konster och specialiserad träning utövas i det fördolda.",al={"var finns nartok","var finns the den","hur hittar man nartok"}},{q="Varför varnar Nartok för att hålla sina krafter väl dolda?",a="Nartok varnar för att vanligt folk fruktar krafter de inte förstår och ofta slår tillbaka i panik. Eftersom orkerna har lidit svårt av demonisk fördärvning förr i tiden håller demonbesvärjare sina konster dolda och går försiktigt fram.",al={"varför dölja demonbesvärjare","varför hålla krafter dolda","varför demonbesvärjare håller sig dolda"}},{q="Vad tycker Nartok om att utöva felmagi?",a="Nartok tror att de som bemästrar varelserna från Nether kan skapa sin egen väg och gripa makten att forma sitt folks öde, där vanliga ledare misslyckas, i stället för att låta ödet förslava dem.",al={"vad är nartoks mål","nartoks filosofi","varför använda krafter från nether"}},{q="Vem ger dig Tainted Tablet?",a="En lokal uppdragsgivare i Valley of Trials lämnar över tavlan. Hen erkänner öppet sitt obehag inför felmagiker, men inser att Nartoks kallelse ändå måste levereras.",al={"vem levererade tavlan","vem gav mig tavlan"}}},fp="14,296,14.424.0,21.513.0,27.188.0,28.199.0,26.146.0,50.226.0,46.203.0,33.181.0"}
P.entries["quest:98576"] = {n="Glyphic Parchment",s="I Valley of Trials visar Glyphic Parchment unga magiker vägen till sina första lektioner. Gornek lämnar över det runmärkta meddelandet, som skickar dem till Mai'ah nära The Den för att börja lära sig magi.",h="I Valley of Trials visar Glyphic Parchment unga magiker vägen till sina första lektioner.",kw={"arkana","durotar","glyphic parchment","gornek","magiker","mai'ah","the den","valley of trials"},ang={["class:Mage"]="Som magiker skickas du med detta meddelande till Mai'ah för att börja dina studier och utöka din besvärjelsebok.",["faction:Horde"]="Som medlem av Horden lär du dig att Valley of Trials fostrar även oberäkneliga konster som magi med disciplin, för att stärka Hordens framtid.",["race:Troll"]="Som troll kan du se till Mai'ah och Darkspears växande magitraditioner. Hon delar sin förståelse för kosmiska krafter med andra troll och allierade rekryter."},sec={{t="En kallelse till studier",b="Nya rekryter prövar sin styrka mot Durotars lokala skadedjur, men de som dras till magi behöver mer än råstyrka. Gornek lämnar över ett runmärkt meddelande. Det visar nybörjare i magi till Mai'ah, som vägleder Hordens nyaste rekryter genom deras första lektioner i magi."},{t="Det arkanas väg",b="Mai'ah väntar strax utanför The Den, där hon lär unga magivävare att tygla sina ambitioner med tålamod och eftertanke. Hon uppmanar dem att välja rätt ögonblick i stället för att kasta ut rå magi utan omsorg. Under hennes lektioner lär sig nybörjare att väva kosmos sköra trådar i stället för att släppa lös en vild storm."}},faq={{q="Vem skickar Glyphic Parchment?",a="Mai'ah skickar pergamentet, och Gornek räcker det till dig. Magitränaren väntar nära The Den i Valley of Trials.",al={"vem skrev glyphic parchment","vem skickade det här","pergamentets författare"}},{q="Var finns Mai'ah?",a="Mai'ah väntar strax utanför The Den i Valley of Trials i Durotar, tillsammans med de andra klassmentorerna.",al={"var finns mai'ah","mai'ahs plats","hitta mai'ah"}},{q="Vad är syftet med det här uppdraget?",a="Pergamentet visar nybörjare i magi till deras tränare. När du talar med Mai'ah börjar din formella undervisning i magi och vägen öppnas till nya besvärjelser och grundläggande träning.",al={"vad gör glyphic parchment","varför göra uppdraget","uppdragets mål"}},{q="Vad är Mai'ahs filosofi om magi?",a="Mai'ah lär ut att magi kräver intellekt, återhållsamhet och tålamod. En magiker iakttar noga och agerar sedan i rätt ögonblick.",al={"vad lär mai'ah ut","mai'ahs bakgrund"}},{q="Varför tränar en troll magiker i Valley of Trials?",a="Valley of Trials välkomnar unga orcher och Darkspear Trolls till Horden. Darkspear-magiker som Mai'ah lär blivande magiker om kosmiska krafter.",al={"varför trollmagiker","troll och det arkana","trolltränare i orchområde"}},{q="Vem lämnar pergamentet till spelaren?",a="Gornek, prövningarnas övervakare vid Valley of Trials centrala läger, ger dig pergamentet när du återvänder till honom under dina första uppgifter.",al={"vem ger glyphic parchment","gorneks uppdrag"}}},fp="17,193,18.283.0,21.309.0,32.116.0,26.102.0,34.173.0,37.139.0,54.173.0,41.138.0"}
P.entries["quest:98581"] = {n="Archaic Rune",s="Archaic Rune är ett introduktionsuppdrag för unga dvärgschamaner i Dun Morogh. Den heliga tavlan är genomsyrad av elementarkraft från uråldriga Wildhammer-inskrifter och introducerar unga lärlingar till deras elementära arv. När stenen överlämnas till Teo Hammerstorm i Anvilmar inleds formellt deras träning i jordens, luftens, eldens och vattnets vägar.",h="Archaic Rune är ett introduktionsuppdrag för unga dvärgschamaner i Dun Morogh.",kw={"anvilmar","archaic rune","bronzebeard","coldridge valley","element","schaman","teo hammerstorm","wildhammer-klanen"},ang={["class:Shaman"]="Archaic Rune är det allra första steget på en dvärgschamans andliga resa. Den bekräftar deras elementära samhörighet och för dem till deras första mentor.",["faction:Alliance"]="När Wildhammer-mentorer för schamankonsterna till Dun Morogh breddas Alliansens andliga utövning, och elementära traditioner får en plats vid sidan av det heliga ljuset.",["race:Dwarf"]="Den här runan markerar ett viktigt kulturutbyte mellan dvärgklaner, när Wildhammer delar sina uråldriga andliga traditioner med sina Bronzebeard-fränder i Coldridge Valley."},sec={{t="En uråldrig inskrift",b="Unga äventyrare i Coldridge Valley upptäcker Archaic Rune efter att ha hjälpt lokala allierade nära Anvilmar. Stenen bär en tydlig skrift, huggen i Wildhammer-klanens stil, och är synbart och påtagligt laddad med uråldrig elementarkraft. Runan är inte bara en relik av stenhantverk, utan också ett elementärt prov: endast de med en gryende förmåga att stämma in på urtidens andar kan förstå tecknen som ristats på dess väderbitna yta. För dem som kan läsa skriften ger den tydliga instruktioner om att söka rätt undervisning i den närbelägna dvärgposteringen."},{t="Wildhammers visdom i Dun Morogh",b="I Anvilmars stora sal tar Wildhammer-schamanen Teo Hammerstorm emot den inskrivna stenen. I generationer bevarades elementens andliga konster till största delen av Wildhammer-klanen bland deras vindpinade bergstoppar. Nu har dessa traditioner börjat slå rot bland Bronzebeard-dvärgarna i Ironforge och Dun Morogh. Hammerstorm fungerar som en viktig bro mellan de två dvärgkulturerna. Han välkomnar unga lärlingar som visar en kallelse att tala med elementen och erbjuder formell undervisning i jordens, luftens, eldens och vattnets discipliner."}},faq={{q="Vad är Archaic Rune?",a="Archaic Rune är en uråldrig stentavla med gammal Wildhammer-skrift, genomsyrad av elementarkraft. Den ges till lovande nya äventyrare i Coldridge Valley som ett första prov på deras andliga förmåga. Om en lärling har den inre känslighet som krävs för att läsa runan, bekräftar det deras kallelse till schamanens väg och visar dem att tala med tränaren i Anvilmar.",al={"uppdraget archaic rune","vad är den här runan","föremålet archaic rune"}},{q="Vem ristade Archaic Rune?",a="Inskrifterna på runan är utförda i Wildhammer-klanens traditionella stil. Den skickades av Teo Hammerstorm, en Wildhammer-schaman som bor i Anvilmar. Han använder den inskrivna stenen för att hitta och ta kontakt med nya lärlingar som har en medfödd koppling till elementandar.",al={"vem gjorde archaic rune","runans ursprung","wildhammer-runans skapare"}},{q="Vem är Teo Hammerstorm?",a="Teo Hammerstorm är en Wildhammer-dvärg och schamantränare stationerad i Anvilmar i Coldridge Valley. Han har rest till Dun Morogh för att hjälpa till att dela sin klans förfäders schamanlära med Bronzebeard-dvärgarna och vägleda nya utövare i jordens, eldens, vattnets och luftens vägar.",al={"vem är teo hammerstorm","teo hammerstorm i anvilmar","schamantränare i anvilmar"}},{q="Varför delas Wildhammer-läran med Bronzebeard-dvärgar?",a="Schamankonsterna bevarades och vaktades traditionellt av Wildhammer-klanen under många år, men nyligen har även Bronzebeard-dvärgarna tagit sig an dessa elementära seder. Mentorer som Teo Hammerstorm har tagit på sig att lära Ironforge-dvärgar hur de kan tala med och hedra elementandar.",al={"varför är dvärgar schamaner","bronzebeard och wildhammer-schamaner","dvärgschamanernas historia"}},{q="Vart ska jag ta Archaic Rune?",a="Runan måste föras till Teo Hammerstorm, som finns i Anvilmars huvudbyggnad i Coldridge Valley. När du visar honom runan demonstrerar du din förmåga att kanalisera elementen och får tillgång till vidare träning i dina grundläggande schamantrollformler.",al={"var lämnar jag in archaic rune","lämna in archaic rune","hitta teo hammerstorm"}},{q="Vad innebär det att läsa runan?",a="Archaic Rune är genomsyrad av elementarkrafter från en uråldrig dvärgskrift. Endast en lärling med en medfödd förmåga att stämma in på elementarkrafterna kan tyda skriften. Att lyckas läsa den bevisar att en äventyrare har de naturliga förutsättningarna och den andliga beredskapen för att bli en sann schaman.",al={"varför kan jag läsa runan","runans betydelse","läsa archaic rune"}}},fp="12,371,22.600.0,31.566.0,25.392.0,28.298.0,23.292.0,67.343.0,33.257.0,35.290.0"}
P.entries["quest:986"] = {n="A Lost Master",s="A Lost Master ger en alliansäventyrare i uppdrag att samla material som ska hjälpa till att hitta Volcor, en nattalv som försvunnit i Darkshores vildmark. Terenthis i Auberdine erbjuder sig att väva en förtrollad kamouflagekappa som skyddar den som ger sig ut för att leta, men behöver då skinn från kustens vildaste moonstalkers.",h="A Lost Master ger en alliansäventyrare i uppdrag att samla material som ska hjälpa till att hitta Volcor, en...",kw={"a lost master","auberdine","darkshore","fine moonstalker pelt","grimclaw","moonstalker","terenthis","volcor","wildbend river"},ang={["class:Druid"]="Druider kan uppskatta Terenthis respekt för moonstalkers naturliga förmåga att smyga, när han omvandlar deras vilda essens till skyddande kamouflage.",["class:Hunter"]="Jägare känner igen bandet mellan Volcor och Grimclaw, liksom skickligheten som krävs för att spåra och jaga Darkshores matriarker och hanar.",["race:NightElf"]="Att hitta Volcor speglar nattalvernas plikt att skydda sitt folk och sina vilda följeslagare i Darkshores otämjda vidder."},sec={{t="En sökning i vildmarken",b="Medan Terenthis i Auberdine spårar hot längs Darkshores kust börjar han oroa sig för hur det har gått för Volcor och hans följeslagare Grimclaw. Det är ökänt farligt att ge sig djupt in i regionens södra delar, där aggressiva rovdjur och förvridet djurliv håller till. I stället för att skicka ut en oskyddad spejare lägger Terenthis upp en plan på att skapa en skyddande mantel genomsyrad av vilda illusioner."},{t="Päls från de stoltaste",b="Vanliga skinn räcker inte för att väva en mantel som kan förvilla Darkshores odjur. Terenthis behöver fina moonstalker-skinn från fullvuxna moonstalker-hanar eller matriarker. Dessa väldiga kattdjur strövar i skogarna söder om Auberdine, nära Wildbend River och vidare mot Ashenvales skogsklädda gräns."},{t="Skör magi",b="Det färdiga plagget använder moonstalker-päls och naturens förtrollningar så att bäraren kan ta sig obemärkt genom fientliga områden medan hen söker efter Volcor. Men Terenthis varnar för att illusionen är skör: ansträngande aktivitet eller strid bryter förtrollningen och lämnar den som letar oskyddad."}},faq={{q="Vem är Volcor?",a="Volcor är en nattalv, spejare eller spårare, som försvann i södra Darkshores vildmark. Hans följeslagare Grimclaw och Terenthis i Auberdine försöker hitta honom, vilket sätter sökandet i gång.",al={"vem är volcor","volcors bakgrund","den försvunne mästaren volcor"}},{q="Vem ger uppdraget?",a="Terenthis, en nattalv som är stationerad i bosättningen Auberdine i Darkshore, ger uppdraget efter att äventyrare hjälpt honom med tidigare problem i området.",al={"uppdragsgivare","var får man uppdraget a lost master","terenthis plats"}},{q="Var hittar man moonstalker-hanar och matriarker?",a="Dessa fullvuxna moonstalkers strövar omkring i södra Darkshore, särskilt nära Wildbend Rivers stränder och längre söderut mot gränsen till Ashenvale.",al={"platser med fine moonstalker pelt","var hittar man moonstalkers","kattdjur vid wildbend river"}},{q="Vad ska manteln göra?",a="Terenthis tänker skapa en förtrollad mantel som döljer bäraren för Darkshores fientliga odjur, så att hen kan leta efter Volcor utan att ständigt dra till sig angrepp.",al={"vad gör manteln","terenthis mantel","mantelns förtrollning"}},{q="Varför behöver Terenthis särskilda skinn?",a="Terenthis säger att han behöver fem fina skinn från moonstalker-hanar eller matriarker för att få tillräckligt med material till manteln.",al={"varför hanar och matriarker","varför fina skinn"}},{q="Har kamouflagemanteln några begränsningar?",a="Ja. Terenthis varnar för att förtrollningen är skör. Det går bra att prata med andra, men ansträngande aktiviteter eller strid skingrar snabbt illusionen.",al={"bryts illusionen","mantelns begränsningar"}}},fx={bc18541c={q="Varför vill Terenthis att detta ska göras?",a="Terenthis är djupt bekymrad för sin nattalvskamrat Volcor, som försvann i de farliga vildmarkerna i södra Darkshore, och för den lojala björnen Grimclaw, som kom till Auberdine för att söka hjälp åt sin herre. Terenthis vägrar skicka dig in i så farligt område utan skydd, så han insisterar på att först förbereda en magisk kamouflagekappa. Den ska se till att du tryggt kan hitta Volcor utan att kustens rovdjur sliter dig i stycken.",al={"varför hjälpa volcor","terenthis motiv","varför vill terenthis ha pälsar"}}},fp="13,197,23.292.0,18.247.0,14.262.0,14.150.0,21.105.0,49.135.0,30.155.0,39.87.0,43.148.0"}
P.entries["quest:98601"] = {n="A Difficult Path",s="A Difficult Path markerar den formella början på en Forsaken-paladins träning i Deathknell. Efter att ha tagit hand om de tanklösa odöda som reser sig ur kryptorna får nyvaknade Ljusets förkämpar instruktioner om att söka upp Aramis Hammerhand i bykyrkan och möta den plågsamma verkligheten i att utöva helig kraft som odöd.",h="A Difficult Path markerar den formella början på en Forsaken-paladins träning i Deathknell.",kw={"a difficult path","aramis hammerhand","consecrated scroll","deathknell","forsaken-paladin","holy light","shadow priest sarvis","tirisfal glades"},ang={["class:Paladin"]="Uppdraget utgör den grundläggande prövningen för en Forsaken-paladin och framställer helig kraft inte som en lätt välsignelse, utan som en plågsam smältdegel av disciplin och uthållighet.",["race:Undead"]="För Forsaken visar åkallan av Ljuset att hängivenhet och disciplin kan överleva den fysiska döden, även om magin aktivt bränner det kärl som kanaliserar den."},sec={{t="En stinkande skriftrulle",b="När en nyväckt Forsaken-paladin har rensat bort de vilda odöda utanför kryptan överlämnar Shadow Priest Sarvis en oväntad försändelse. Consecrated Scroll utstrålar så intensiv helig kraft att skuggprästen synbart ryggar tillbaka och bryskt ber bäraren att flytta sig. För den som utövar skuggmagi och förfall känns själva auran från Holy Light som en öppen låga."},{t="Den heliga eldens smältdegel",b="I Deathknells vanhelgade kyrka väntar Aramis Hammerhand, paladintränaren bland Forsaken. Medan andra raser utövar Ljuset naturligt och med glädje får odöda som åkallar det utstå en brännande, påtaglig smärta. Aramis försöker inte mildra sanningen: att kanalisera helig kraft genom ett ruttnande kärl är ren plåga, men han kräver att lärjungarna omfamnar smärtan i stället för att rygga undan och använder den som en smältdegel för att härda sin nyfunna beslutsamhet."}},faq={{q="Varför tycker Shadow Priest Sarvis illa om skriftrullen?",a="Shadow Priest Sarvis är hängiven skuggmagi och att bevara sina odöda fränder. Consecrated Scroll utstrålar ren helig kraft, som är i grunden fientlig mot odött kött och djupt oroande för dem som utövar skuggan.",al={"sarvis heliga skriftrulle","varför är sarvis orolig","skuggpräst reagerar på skriftrulle"}},{q="Kan Forsaken verkligen utöva Holy Light utan att dö?",a="Forsaken kan utöva Ljuset genom ren viljestyrka och tro, men det orsakar dem intensiv smärta, särskilt när de kanaliserar det för att hela sig själva eller andra. Det kräver enorm mental uthållighet att kanalisera kraften.",al={"forsaken-paladiners historia","odöda som använder ljuset","gör ljuset ont på forsaken"}},{q="Vem är Aramis Hammerhand?",a="Aramis Hammerhand är paladintränaren som finns i Deathknells kapell. Han vägleder nyuppståndna Forsaken-paladiner och lär dem att uthärda plågan i att utöva Ljuset som odöd och smida det till ett effektivt vapen.",al={"vem är aramis hammerhand","paladintränare i deathknell","aramis roll"}},{q="Var utspelar sig uppdraget?",a="Uppdraget börjar hos Shadow Priest Sarvis på den centrala gläntan i Deathknell och avslutas bara några steg bort, inne i byns förfallna kapell där Aramis Hammerhand håller till.",al={"var finns a difficult path","uppdragets plats","var finns deathknells kyrka"}},{q="Måste jag läsa Consecrated Scroll för att slutföra uppdraget?",a="Nej, det är inte strikt nödvändigt att läsa skriftrullen för att slutföra målet. Om du talar direkt med Aramis Hammerhand inne i kyrkan går din träning vidare.",al={"läsa consecrated scroll","måste man läsa skriftrullen","hoppa över läsning av skriftrullen"}},{q="Varför kallas vägen ”svår”?",a="Namnet speglar Forsaken-paladinens brutala väg. Medan andra av Ljusets krigare finner tröst och ro i sin tro måste en odöd paladin uthärda brännande helig eld som flödar genom dött kött varje gång de kastar en välsignelse eller slår till.",al={"varför svår väg","uppdragsnamnets betydelse"}}},fx={["6833d98f"]={q="Varför vill Shadow Priest Sarvis att detta ska göras?",a="Sarvis vill bara slippa se det Heliga ljuset. Den konsekrerade skriftrullen kom till dig medan du gallrade bland de tanklösa Scourge, och dess strålande magi kränker naturligt hans skuggberörda sinnen. I stället för att stanna i dess närhet eller ta hand om en blivande paladin skickar han dig till din egen tränare, Aramis Hammerhand, så att du kan börja lära dig att finslipa din smärtsamma disciplin.",al={"varför skickar sarvis mig till aramis","sarvis motiv svår väg","varför ger sarvis mig skriftrullen"}}},fp="16,322,16.384.0,25.449.0,49.238.0,54.212.0,25.226.0,33.179.0,63.159.0,35.256.0"}
P.entries["quest:98738"] = {n="Blessings of the Great Windborne Cat Spirit",s="Blessings of the Great Windborne Cat Spirit är en övergångsrits där en novis återvänder efter att ha kommunicerat med The Great Cat Spirit i Zephras. Novisen har tagit till sig vildkattens smygförmåga, snabbhet och ursinne och visar upp sin nyväckta aura för Dendrite för fortsatt andlig vägledning.",h="Blessings of the Great Windborne Cat Spirit är en övergångsrits där en novis återvänder efter att ha...",kw={"blessings of the great windborne cat spirit","kattform","dendrite","druid","the great cat spirit","shen'dorei","smygförmåga","zephras"},ang={["class:Druid"]="Uppdraget markerar en viktig milstolpe i bemästrandet av kattdjurets rovdjursinstinkter och ger druider den smygförmåga, snabbhet och det ursinne som krävs för att kommunicera med och anta kattens aspekt.",["race:Skyborne"]="Anden erkänner särskilt novisen som unga shen'dorei och erbjuder vägledning genom vind och skugga från Zephras, medan novisen lär sig att tygla sin vilda kraft."},sec={{t="Gemenskap med vindanden",b="Blessings of the Great Windborne Cat Spirit markerar höjdpunkten i en helig gemenskap med The Great Cat Spirit i Zephras. Efter att ha sökt upp denna vindburna beskyddare och vunnit dess gunst återvänder en novis till Dendrite för att visa att hen har tagit till sig vildkattens list, rovdjurens smygförmåga och ursinne."},{t="Dendrites vägledning",b="När novisen återvänder efter att ha fått välsignelsen gör Dendrite subtila kroppsrörelser för att läsa av novisens nyväckta aura. Dendrite känner hur kattdjurets instinkter vävts in i novisens själ och bekräftar att kandidaten äntligen är redo att fokusera sitt sinne och åkalla kattens sanna aspekt."}},faq={{q="Vad är Blessings of the Great Windborne Cat Spirit?",a="Blessings of the Great Windborne Cat Spirit är en övergångsrits där en novis som sökt upp och fått The Great Cat Spirits välsignelse återvänder till Dendrite för att fullborda sin andliga gemenskap.",al={"vad är det här för uppdrag","kattens välsignelseuppdrag","kattandens uppdrag"}},{q="Vem är Dendrite?",a="Dendrite är en mentor som skickar noviser för att kommunicera med The Great Cat Spirit. När de återvänder utför han rituella gester för att känna av förvandlingen och bekräfta om novisen har tagit till sig den smygförmåga, snabbhet och list som krävs för att kanalisera kattdjurets natur.",al={"vem är dendrite","dendrites historia"}},{q="Vem är The Great Cat Spirit?",a="The Great Cat Spirit är en uråldrig beskyddarande ande i Zephras. Den skänker värdiga noviser andlig gunst, vindarnas snabbhet och rovdjurens smygförmåga innan den skickar tillbaka dem för att fortsätta sin utbildning.",al={"vad är kattanden","den stora vindburna kattanden"}},{q="Var ligger Zephras?",a="Zephras är The Great Cat Spirits hem. Dit reser lovande noviser för att söka dess råd, få dess välsignelser av vind och skugga och lära sig grunderna i kattdjursformen.",al={"var ligger zephras","kattandens plats"}},{q="Varför tilltalar anden novisen som shen'dorei?",a="The Great Cat Spirit tilltalar novisen direkt som unga shen'dorei och syftar på utövarens förfäders arv. Utövaren söker gemenskap med naturandar och vill bemästra vild förvandlingsmagi.",al={"vilka är shendorei","unga shendorei"}},{q="Vad ger kattandens välsignelse?",a="Välsignelsen skänker kattdjursformens list, snabbhet och smygförmåga. Med välsignelsen i hand blir novisen erkänd av Dendrite och kan fokusera sitt inre ursinne och åkalla kattens sanna natur.",al={"vad ger välsignelsen","kattandens välsignelseeffekt"}}},fp="43,313,35.325.0,22.316.0,52.216.0,16.273.0,28.216.0,25.187.0,55.199.0,47.214.0"}
P.entries["quest:98815"] = {n="Highland Hides",s="Highland Hides är ett expeditionskontrakt beställt av James Halloran, en garvare i Menethil Harbor. Halloran söker förstklassiga material från Highlands dimhöljda bergsträsk och byter tillverkade lädervaror mot de tåliga skinnen från rovdjuren Thicket Raptors.",h="Highland Hides är ett expeditionskontrakt beställt av James Halloran, en garvare i Menethil Harbor.",kw={"highland hides","highlands","james halloran","menethil harbor","raptorhudar","garvare","thicket raptor","wetlands"},ang={["class:Hunter"]="Jägare som ger sig ut i Highlands bergsträsk möter mäktiga bestar som Thicket Raptors, vars tåliga hudar kräver noggrann spårning och en ren jakt.",["faction:Alliance"]="Menethil Harbor är en viktig allianshamn i Wetlands, där handelsmän som James Halloran utrustar resenärer på väg ut i de farliga träskmarkerna runt omkring."},sec={{t="En garvares möjlighet",b="James Halloran, en skicklig garvare verksam i hamnstaden Menethil Harbor, håller ständigt utkik efter exotiska hantverksmaterial. När han får höra om en expedition som utforskar bortglömda ruiner i Highlands bryr han sig mindre om forntida historia och mer om de mäktiga bestar som strövar omkring i bergsträsken. Han inser djurlivets kommersiella värde och värde för hantverkare och anlitar djärva äventyrare för att ge sig in bland de dimhöljda topparna och hämta tillbaka utvalda skinn."},{t="Highlands bestar",b="Bland djuren som lurar i Highlands är Thicket Raptors ökända rovdjur, väl anpassade till den oländiga träskterrängen. Hantverkare värdesätter deras tåliga, strukturerade skinn för särskilt läderarbete. Halloran ber resenärer spåra upp varelserna och återvända med fyra hela hudar, som han använder till fina detaljer och dekorativa kanter på verkstadens alster."}},faq={{q="Vem är James Halloran?",a="James Halloran är en lokal garvare och hantverkare med bas i Menethil Harbor. Han arbetar med läder och oljor och söker skinn av hög kvalitet från exotiska bestar i Wetlands och de omgivande högländerna för att tillverka fina kanter och rustningar.",al={"vem ger highland hides","vem är james halloran","garvare i menethil"}},{q="Varför behöver James Halloran de här hudarna?",a="Halloran vill ha hudar från Thicket Raptors för deras exceptionella tålighet och struktur. Han anser att de hör till de finaste hudar han har hanterat och använder dem till spektakulära detaljer på läderkanter.",al={"vad används highland hides till","varför vill james ha raptorhudar","syftet med raptorhudar"}},{q="Var hittar man Thicket Raptors?",a="Thicket Raptors håller till i Highlands bergsträsk och lurar i den oländiga vildmarken nära forntida ruiner som en expedition utforskar just nu.",al={"var finns thicket raptors","thicket raptors plats","var finns raptrarna"}},{q="Vilka ruiner syftar Halloran på?",a="I Highlands finns bortglömda ruiner som ett expeditionsteam undersöker just nu. Medan hantverkare som Halloran fokuserar på djurlivet utforskar lärda och upptäcktsresande områdets forntida hemligheter på djupet.",al={"vilka ruiner finns i highlands","highlands expeditionsruiner","vem utforskar highlands"}},{q="Är jakten tänkt för en grupp?",a="Halloran råder dig att ta med välutrustade följeslagare. I Highlands bergsträsk finns farliga vilda djur, så utflykter mot rovdjur som Thicket Raptors är riskfyllda för den som reser ensam.",al={"är highland hides farligt","behövs en grupp för highland hides","behöver jag vänner för highland hides"}},{q="Vad erbjuder James Halloran i byte?",a="I utbyte mot fyra felfria hudar från Thicket Raptors erbjuder Halloran läderarbeten av hög kvalitet, tillverkade i hans verkstad. Äventyrare får välja en del som passar deras resor.",al={"vad byter halloran bort","belöningslore för highland hides"}}},fp="14,272,22.488.0,23.393.0,22.231.0,41.212.0,35.172.0,36.217.0,34.216.0,40.187.0"}
P.entries["quest:98824"] = {n="Prehistoric Prism",s="Prehistoric Prism är ett upptäcktsuppdrag där äventyrare ska föra en mångfacetterad titanrelik från Wetlands till Ironforge. Prospector Whelgar ger dig reliken, som skänks till High Explorer Magellas i Hall of Explorers för att främja League:s studier av de forntida väktarna.",h="Prehistoric Prism är ett upptäcktsuppdrag där äventyrare ska föra en mångfacetterad titanrelik från Wetlands...",kw={"hall of explorers","high explorer magellas","ironforge","prehistoric prism","prospector whelgar","titan relic","uldaman","wetlands"},ang={["faction:Alliance"]="När du skänker forntida skatter du hittat berikar du direkt de lärda samlingarna i Ironforge prestigefyllda Hall of Explorers.",["race:Dwarf"]="Att återfinna äkta titanreliker går till kärnan av dvärgarnas identitet och Explorers' Leagues uppdrag att avslöja deras skapares ursprung."},sec={{t="En forntida upptäckt",b="När Prospector Whelgar undersöker Wetlands hittar han en anmärkningsvärd artefakt med intrikata väktarinskrifter på sina många fasetter. Han inser att ett fynd med så stor historisk betydelse hör hemma hos lärda och uppmanar dig att genast föra det till dvärgarnas huvudstad Ironforge. Whelgar hoppas att upptäckten ska föras in i den officiella katalogen, så att äventyraren får erkännande tillsammans med hans äkthetsintyg."},{t="En gåva till museet",b="I Hall of Explorers anrika salar tar High Explorer Magellas emot reliken på Explorers' League vägnar. Den ledande arkeologen förundras över dess äkta tillverkarstämplar och säger att ljuset som strömmar genom de polerade fasetterna påminner om underverken han såg vid sin första utgrävning i Uldaman. Genom att skänka artefakten bevaras den för studier och League:s växande dokumentation av titanernas arv utökas."}},faq={{q="Vem ger uppdraget Prehistoric Prism?",a="Prospector Whelgar ber dig föra reliken till Ironforge efter att ha bekräftat att inskrifterna på fasetterna i Wetlands liknar titanernas.",al={"vem ger prehistoric prism","var börjar prehistoric prism","uppdragsgivare prehistoric prism"}},{q="Var lämnar du in Prehistoric Prism?",a="Du lämnar reliken till High Explorer Magellas i Hall of Explorers i Ironforge. Han tar gärna emot den till museets samling.",al={"vem lämnar man in prehistoric prism till","var lämnar man in prehistoric prism","slutföra prehistoric prism"}},{q="Vad är det för slags artefakt, Prehistoric Prism?",a="Det är en forntida artefakt med många fasetter och tydliga kännetecken från väktarna. När ljuset träffar den dansar det genom kristallformen på ett sätt som påminner om relikerna som grävts fram i Uldaman.",al={"vad är prehistoric prism","är prehistoric prism en titanrelik","vad är reliken"}},{q="Varför är Hall of Explorers intresserad av prismat?",a="Explorers' League samlar aktivt in och katalogiserar äkta reliker med titanursprung. High Explorer Magellas anser att artefakter av den här kalibern är nödvändiga för att vidga världens kunskap och förstå forntida historia.",al={"varför vill magellas ha den","varför skänka prismat","hall of explorers prismat"}},{q="Hur hör prismat ihop med Uldaman?",a="När High Explorer Magellas undersöker artefaktens ljusbrytning och väktarmärkningar jämför han det dansande ljuset med reliker han undersökte under sin allra första arkeologiska utgrävning i Uldaman.",al={"har uldaman något med prismat att göra","kopplingen till uldaman","prismat uldaman"}},{q="Blir ditt namn infört i museets katalog?",a="Prospector Whelgar och High Explorer Magellas ser till att du formellt får erkännande för att ha återfunnit reliken och att det förs in i Explorers' Leagues historiska arkiv.",al={"prehistoric prism katalog","får man erkännande","historiskt erkännande prismat"}}},fp="17,294,20.472.0,20.438.0,38.150.0,43.143.0,47.205.0,53.223.0,37.186.0,54.171.0"}
P.entries["quest:98895"] = {n="Darkspear Islands Clash",s="Darkspear Islands Clash är en militär uppmaning från Alliansen att försvara viktig mark mot de våldsamma Darkspear Raiders. Utan omedelbart stöd vid frontlinjen riskerar Alliansen att helt förlora den omstridda ögruppen.",h="Darkspear Islands Clash är en militär uppmaning från Alliansen att försvara viktig mark mot de våldsamma...",kw={"alliansen","slagfält","brigadgeneral","darkspear islands","darkspear islands clash","darkspear raiders","marks of honor"},ang={["class:Paladin"]="Alliansens heliga krigare möter de våldsamma striderna med orubblig beslutsamhet och svarar på uppmaningen att skydda alliansmedlemmars liv och slå tillbaka fiendestyrkorna.",["class:Warrior"]="Stridskämparna vid frontlinjen får ta emot den hårdaste stöten från de våldsamma trollräderna. Militär disciplin och tapperhet på slagfältet kan vända stridens gång.",["faction:Alliance"]="Alliansens högsta befäl förlitar sig på frivilliga mästare för att förstärka fronten mot Darkspear Raiders och skydda strategiska positioner på öarna."},sec={{t="En omstridd front",b="Kampen om kontrollen över Darkspear Islands har brutit ut i öppet krig mellan Alliansen och aggressiva krigsband av Darkspear Raiders. Alliansens befälhavare varnar för att deras fäste i ögruppen kommer att övermannas utan brådskande förstärkningar. Därför har de kallat dugliga mästare till vapen för att hejda fiendens framryckning."},{t="Ett bevis på tapperhet",b="Alliansens ledning förlitar sig på beprövade stridskämpar som är villiga att ge sig direkt ut på frontlinjen. För att upprätthålla disciplin och uppmärksamma verkligt hjältemod kräver befälhavarna att krigare återvänder med Darkspear Islands Marks of Honor som ett konkret bevis på sina stridsinsatser. De hedrar dem som vänder stridens gång."}},faq={{q="Vad är Darkspear Islands Clash?",a="Darkspear Islands Clash är en militär uppmaning till vapen från Alliansens officerare som leder krigsinsatsen vid frontlinjen. Alliansens mästare ska strida mot Darkspear Raiders och bevisa sina insatser genom att hämta hedersmärken från striderna.",al={"vad är darkspear islands clash","uppdraget clash","striden på darkspear islands"}},{q="Vilka är Darkspear Raiders?",a="Darkspear Raiders är trollkrigsband som kämpar om kontrollen över Darkspear Islands. Deras aggressiva framryckningar hotar Alliansens fästen i området och får högsta befälet att kalla på förstärkningar utan dröjsmål.",al={"vilka är darkspear raiders","fienden darkspear raiders","vilka strider vi mot på darkspear islands"}},{q="Varför strider Alliansen på Darkspear Islands?",a="Alliansen försöker hålla strategiskt viktig mark på Darkspear Islands och hindra att regionen helt hamnar under trollens kontroll. Om Alliansen förlorar mark hotas dess inflytande och säkerhet i de omstridda kustvattnen.",al={"varför strider alliansen på darkspear islands","varför strida här","alliansens krig mot darkspear"}},{q="Vem utfärdar och tar emot uppdraget?",a="En brigadgeneral från Alliansen, stationerad utanför slagfälten, leder truppmobiliseringen och tar emot bevis på återvändande mästares insatser i strid.",al={"vem utfärdar darkspear islands clash","vem tar emot darkspear marks of honor","var finns alliansens brigadgeneral"}},{q="Vad är Darkspear Islands Marks of Honor?",a="Marks of Honor är militära märken som tilldelas stridskämpar för tapperhet och aktivt deltagande vid frontlinjen. Om du överlämnar tre sådana märken till en brigadgeneral från Alliansen får du ett slutgiltigt bevis på dina insatser på slagfältet.",al={"vad är marks of honor","darkspear islands mark of honor","hur bevisar man insatser vid frontlinjen"}},{q="Vad står på spel om Alliansen misslyckas?",a="Utan snabba förstärkningar riskerar Alliansens positioner på Darkspear Islands att helt kollapsa under Darkspear Raiders obevekliga tryck. Genom att säkra öarna hindrar Alliansen fiendestyrkorna från att befästa sin obestridda dominans över ögruppen.",al={"vad händer om alliansen förlorar darkspear islands","varför behövs brådskande hjälp","förlusten av darkspear islands"}}},fp="23,242,17.337.0,14.308.0,32.280.0,30.215.0,54.233.0,38.161.0,42.236.0,39.257.0"}
P.entries["quest:98896"] = {n="Darkspear Islands Clash",s="Darkspear Islands Clash kallar krigare att samla sina följeslagare och besegra de fientliga Darkspear Raiders som strider om ögruppen. Den pågående striden kräver samordnade insatser för att hejda fiendens intrång på öarna.",h="Darkspear Islands Clash kallar krigare att samla sina följeslagare och besegra de fientliga Darkspear Raiders...",kw={"strid","darkspear islands","darkspear raiders","ökonflikt","samla","skärmytsling","trollplundrare"},ang={["faction:Horde"]="Det här är Alliansens sida av kampen om Darkspear Islands, de heliga trollöarna utanför Kalimdors kust som Horden försvarar mot alla främlingar.",["race:Troll"]="För trolläventyrare är Darkspear Raiders, som den här alliansordern riktar sig mot, Vol'jins eget folk, som försvarar stammens heliga öar."},sec={{t="Ögruppen i krig",b="Darkspear Islands Clash är en pågående militär offensiv på de omstridda Darkspear Islands. Styrkor som skickats till stridsområdet uppmanas att hålla stånd mot vågor av Darkspear Raiders, som fortsätter att utkämpa skärmytslingar längs stränderna och i inlandet. Striden är ingen isolerad händelse, utan en del av ett långvarigt fälttåg för att säkra ett brohuvud i ögruppen."},{t="Samla frontlinjen",b="Befälhavarna vid fronten betonar att organisation och numerärt övertag krävs för att besegra de motståndskraftiga plundrarna. Överlevnad och seger beror på att samla närliggande allierade till en samlad styrka som kan stå emot motattacker, driva bort befästa plundringsförband och bryta deras grepp om de omstridda öarnas fästen."}},faq={{q="Vad är Darkspear Islands Clash?",a="Darkspear Islands Clash är ett uppdrag som kallar äventyrare att samla sina allierade och gå till angrepp mot de fientliga Darkspear Raiders i den pågående konflikten på Darkspear Islands.",al={"vad är det här för uppdrag","sammanfattning av darkspear islands clash","information om stridsuppdraget"}},{q="Var utkämpas striden?",a="Skärmytslingen utkämpas på Darkspear Islands, en ögrupp präglad av hårda territoriella strider och pågående sjödrabbningar.",al={"var utspelar det sig","var ligger darkspear islands","stridens plats"}},{q="Vilka är Darkspear Raiders?",a="Darkspear Raiders är hordenstroll som försvarar Darkspear Islands, de heliga öarna där Vol'jins stam bor. Ordern kräver att soldaterna besegrar dem medan de kämpar om territorium på öarna.",al={"vilka är fienderna","vilka slåss vi mot","mål för darkspear raiders"}},{q="Varför måste styrkor samlas inför striden?",a="Konflikten kräver att allierade styrkor samlas och mobiliseras för att stå emot långvariga motattacker och bryta igenom de fientliga plundrarnas linjer.",al={"varför samla styrkor","vad är målet","hur slutför man striden"}},{q="Varför fortsätter striderna på Darkspear Islands?",a="Horden och Alliansen utkämpar en olöst kamp om öarnas fästen: Horden försvarar dem som helig trollmark, medan Alliansen söker ett brohuvud utanför Kalimdors kust.",al={"varför pågår striderna","varför konflikt på öarna","orsaken till östriden"}},{q="Vem leder styrkorna i den här striden?",a="Ordern kommer från Alliansens brigadgeneral i Alterac Mountains, som uppmanar soldaterna på marken att rycka fram utan att tveka.",al={"vem ger uppdraget","uppdragsgivare för striden","stridens befälhavare"}}},fp="23,244,22.393.0,23.328.0,36.187.0,33.138.0,30.209.0,42.141.0,53.198.0,42.147.0"}
P.entries["quest:99"] = {n="Arugal's Folly",s="Arugal's Folly kulminerar i en farlig undersökning av förbannelsen som håller Pyrewood Village i sitt grepp. Dalar Dawnweaver ger Hordens agenter i uppdrag att hämta förtrollade bojor från byborna för att tyda ärkemagikern Arugals förvridna verk. När bojorna undersöks blottas den tragiska magi som håller bosättningen i worgenens skugga.",h="Arugal's Folly kulminerar i en farlig undersökning av förbannelsen som håller Pyrewood Village i sitt grepp.",kw={"arugal","arugal's folly","dalar dawnweaver","moonrage-worgen","pyrewood shackles","pyrewood village","silverpine forest","the sepulcher"},ang={["class:Mage"]="För magiutövare är Arugals bojor en dyster påminnelse om hur Kirin Tors trolldom kan spåra ur i vansinne när den blandas med utomvärldsliga frammanade bestar.",["faction:Horde"]="När bojorna säkras bryts Arugals mystiska grepp om vägen söderut mot The Greymane Wall.",["race:Undead"]="De Fördärvade ser på Pyrewood Village med kall fascination och skoningslös pragmatism. De vill gärna montera ned Arugals förtrollningar för att säkra södra Silverpine."},sec={{t="Pyrewoods dubbla liv",b="Söder om The Sepulcher ligger Pyrewood Village, en bosättning fångad i ett kusligt tillstånd. I dagsljus lever invånarna som vanliga mänskliga bönder, rädda och tillbakadragna. Men när skymningen faller över skogen slits deras mänskliga gestalter sönder och blir till vilda Moonrage-worgen som stryker omkring på gatorna under Arugals kontroll. Dalar Dawnweaver försöker reda ut exakt vilka magiska bindningar som orsakar denna fasansfulla förvandling om natten."},{t="Bojorna krossas",b="För att analysera förtrollningen som håller Pyrewood i sitt våld behöver Dawnweaver förtrollade Pyrewood Shackles som tagits direkt från de förvandlade byborna. De här bojorna är mer än enkelt järn; de pulserar av kvarvarande magi från Arugals misslyckade skyddsförtrollningar. Genom att studera deras magiska sammansättning hoppas den Fördärvades magikern förstå hur förvandlingen till odjur går till och hitta ett sätt att till slut störta den avfällige ärkemagikern i Shadowfang Keep."}},faq={{q="Varför förvandlas invånarna i Pyrewood Village till worgen om natten?",a="Ärkemagikern Arugal lade förvridna förtrollningar över Pyrewood Village. Dagtid upprätthåller hans besvärjelser en illusion av mänsklighet eller ett vilande mänskligt tillstånd, men vid mörkrets inbrott förvandlas byborna till Moonrage-worgen under hans kontroll.",al={"pyrewood dag och natt","pyrewoods förbannelse","varför människa först och varg sedan"}},{q="Vad är Pyrewood Shackles?",a="De är förtrollade bojor som de förbannade invånarna i Pyrewood Village bär. Arugal använde dem som en del av sin magi över byn, och Dalar Dawnweaver studerar förbannelsen med hjälp av deras kvarvarande energi.",al={"pyrewood shackle","arugals bojor"}},{q="Vem är Dalar Dawnweaver?",a="Dalar Dawnweaver är en Fördärvad magiker som är stationerad vid The Sepulcher i Silverpine Forest. Han leder de Fördärvades magiska undersökning av ärkemagikern Arugals frammanade worgen.",al={"dalar dawnweavers bakgrund","vem ger uppdrag vid sepulcher"}},{q="Botar det Pyrewood Village om uppdraget slutförs?",a="Nej. De återfunna bojorna ger Dalar Dawnweaver de magiska insikter han behöver för att förstå Arugals magi, men förbannelsen fortsätter att hålla Pyrewood i ständig plåga.",al={"går pyrewood att bota","blir pyrewoods invånare botade"}},{q="Hur kontrollerar Arugal byborna?",a="Med vårdslösa förtrollningar och förtrollade bojor band Arugal byborna till sin vilja och tvingade dem att anta odjursgestalter som vaktar vägen till hans domän i Shadowfang Keep.",al={"arugal och pyrewood","hur kontrollerar arugal dem"}},{q="Vad händer när uppdragskedjan Arugal's Folly är slutförd?",a="Det här uppdraget utgör det sista kapitlet i kedjan Arugal's Folly. Kunskapen som samlats in låter de Fördärvade bedöma hotet från Shadowfang Keep fullt ut och planera Arugals fall.",al={"efter arugals folly","arugals folly avslutning"}}},fx={["0ad90a3b"]={q="Varför vill Dalar Dawnweaver ha Pyrewood Shackles?",a="Dalar Dawnweaver studerar de besynnerliga förtrollningar som Archmage Arugal har kastat över Silverpine Forest. Genom att analysera magin som är bunden i bybornas bojor hoppas Dalar kunna avslöja Arugals så kallade botemedel, bemästra hemligheterna bakom hans vilda besvärjelser och samla den viktiga kunskap som krävs för att till sist fälla den galne magikern och upphäva hans vårdslösa trolldom.",al={"varför vill dalar ha detta","dalar dawnweavers motiv","varför samla pyrewood shackles"}}},fp="14,342,26.434.0,23.448.1,64.222.0,31.198.0,24.175.0,48.176.1,38.183.0,61.185.1"}
P.entries["quest:990"] = {n="Trek to Ashenvale",s="Trek to Ashenvale är ett reseuppdrag för Alliansen som leder erfarna äventyrare söderut från Darkshore till Ashenvales urskogar. Sentinel Selarin, som kom till Auberdine för att söka hjälp, skickar resenärer till Raene Wolfrunner i Astranaar, där Sentinels kämpar mot en spridande förvridning.",h="Trek to Ashenvale är ett reseuppdrag för Alliansen som leder erfarna äventyrare söderut från Darkshore till...",kw={"ashenvale","astranaar","darkshore","night elf","raene wolfrunner","sentinel selarin","färd till ashenvale"},ang={["faction:Alliance"]="Som mästare för Alliansen stärker du banden till nattalverna när du hörsammar Astranaars vädjan och hjälper till att säkra fraktionens främsta fäste i norra Kalimdor.",["race:NightElf"]="För nattalver innebär den här färden en återkomst till Kalimdors heliga hjärtland, där du hörsammar dina systrars vädjan att skydda de uråldriga heliga markerna från onaturlig röta."},sec={{t="Från kusten",b="Efter att ha hörsammat Sentinel Selarins nödrop i Auberdine lämnar resenärerna kustens dystra, grå stränder och skuggade ruiner bakom sig. Sentinel ser att de är stridsvana kämpar och spejare som klarar sig själva och visar dem vägen rakt in i nattalvernas skogsrike. När de lokala hoten i Darkshore är hanterade riktas uppmärksamheten mot de långt större faror som tränger in från söder."},{t="Vägen till Astranaar",b="Vägen söderut följer en uråldrig nattalvsväg som slingrar sig genom Ashenvales täta, gamla trädkronor. Raene Wolfrunner, ledare för Sentinels i Astranaar, har vädjat om förstärkning med brådskande besked. Demonkontaminering, vilddjur på härjningståg och intrång i förfädernas marker har pressat Sentinels i Astranaar hårt. De behöver hjälp utifrån för att hålla stånd i den heliga skogen."}},faq={{q="Vem skickar dig på färden?",a="Sentinel Selarin, en nattalvsvakt som Raene Wolfrunner skickat till Auberdine för att söka hjälp, visar dig söderut mot Astranaar.",al={"uppdragsgivare","vem startar trek to ashenvale","selarin"}},{q="Vem är Raene Wolfrunner?",a="Raene Wolfrunner är den högsta Sentinel-befälhavaren i Astranaar. Hon ansvarar för att organisera försvaret av Ashenvale och samordna insatserna mot den förvridning som drabbar skogen.",al={"raene","wolfrunner","ledare i astranaar"}},{q="Varför skickas äventyrare till Ashenvale?",a="Ashenvales uråldriga skogar dukar under för en spridande förvridning och växande yttre hot. De lokala nattalvsvakterna är överväldigade och behöver brådskande dugliga allierade som kan hjälpa Astranaars invånare och försvarare.",al={"varför ashenvale","vad händer i ashenvale","förvridning i ashenvale"}},{q="Är vägen mellan Darkshore och Ashenvale säker?",a="Sentinel Selarin råder dig särskilt att hålla dig nära vägen. Om du lämnar stigen och går in i den djupa skogen utsätter du dig för aggressiva rovdjur, satyrer och fientliga styrkor som strövar omkring i de vilda gränstrakterna.",al={"säkerhet på vägen","är vägen i ashenvale säker"}},{q="Vad ska jag göra när jag kommer fram till Astranaar?",a="När du har rapporterat direkt till Raene Wolfrunner råder hon dig att tala med de andra invånarna och försvararna runt om i Astranaar. Många av dem behöver omedelbar hjälp med lokala kriser.",al={"vad göra i astranaar","ankomst till astranaar"}},{q="Vilken nivå är uppdraget avsett för?",a="Den här färden brukar markera slutet på äventyrares tid i Darkshore kring nivå nitton och övergången till Ashenvales vidsträcktare och mer omstridda gränsland.",al={"vilken nivå","nivåkrav"}}},fx={b4a50545={q="Varför vill Sentinel Selarin att du ska bege dig till Ashenvale?",a="Sentinel Selarin lyder under Raene Wolfrunner, som leder försvaret och återställningsarbetet i Astranaar. Den utbredda korruptionen plågar de uråldriga skogarna i Ashenvale, och de lokala Sentinels är hårt ansträngda och under stor press. Selarin skickar beprövade kämpar från Darkshore direkt till sin härskarinna, så att dugliga händer genast kan börja lindra skogens nöd.",al={"varför skicka till ashenvale","selarins motiv","varför färdas till ashenvale"}}},fp="17,339,17.409.0,21.425.0,27.126.0,24.193.0,44.232.0,49.209.0,44.192.0,46.171.0"}
P.entries["quest:99046"] = {n="The Lost Runner",s="The Lost Runner är ett uppdrag där du ska hitta Sentinel Eralya Leafshadow, en budbäraraspirant som är försenad från The Oracle Tree. Det är viktigt eftersom kommunikationen mellan det heliga trädet och de äldste i Darnassus är avgörande för Night Elf-ledarskapet.",h="The Lost Runner är ett uppdrag där du ska hitta Sentinel Eralya Leafshadow, en budbäraraspirant som är...",kw={"council of the forest","darnassus","eralya leafshadow","the oracle glade","oracle tree","sentinels","the lost runner"},ang={["faction:Alliance"]="Säkra vägar och kommunikationslinjer genom Teldrassil bidrar till stabiliteten i Darnassus och alliansens territorium.",["race:NightElf"]="Att säkra kommunikationen mellan det uråldriga The Oracle Tree och ledarskapet i Darnassus är avgörande för kaldoreis säkerhet och andliga vägledning."},sec={{t="Budbärare från The Oracle",b="Council of the Forest har en grupp Sentinels stationerad vid det vördnadsvärda The Oracle Tree i Teldrassil. Trädet förmedlar heliga meddelanden till Night Elf-äldste, och förlitar sig på hängivna löpare som bär dessa försändelser tillbaka till Darnassus längs de slingrande skogsvägarna. Att se till att dessa meddelanden kommer fram säkert är avgörande för kaldoreis vägledning och styre."},{t="En försenad budbärare",b="Tiden mellan meddelandena från The Oracle Tree varierar, men en ovanligt lång tystnad väcker oro när en budbärare inte dyker upp. Det senaste uppdraget gick till Sentinel Eralya Leafshadow, en aspirant som fortfarande genomgår sin utbildning. Hennes överordnade fruktar att hon råkat ut för en olycka längs vägen och ber resande söka längs den västra vägen mot The Oracle Glade för att ta reda på vad som hänt henne."}},faq={{q="Vem är den försvunna löparen?",a="Den försvunna löparen är Sentinel Eralya Leafshadow, en Night Elf-sentinel under utbildning som fick i uppdrag att leverera ett meddelande från The Oracle Tree till Darnassus.",al={"vem är den försvunna löparen","försvunnen sentinel","vem är eralya"}},{q="Vad är The Oracle Tree?",a="The Oracle Tree är ett uråldrigt träd i The Oracle Glade som med jämna mellanrum förmedlar meddelanden till Night Elf-äldste i Darnassus. Stationerade Sentinels måste leverera dem säkert.",al={"vad är the oracle tree","the oracle glades syfte","varför meddelanden från the oracle tree"}},{q="Vart var Eralya på väg?",a="Eralya väntades längs den västra vägen mellan Darnassus och The Oracle Glade, där löpare regelbundet färdas för att förmedla budskap från trädet.",al={"vart var eralya på väg","eralya rutt","den försvunna löparens plats"}},{q="Vem stationerade Sentinels vid The Oracle Tree?",a="Council of the Forest skickade en avdelning Sentinels till The Oracle Tree för att se till att meddelanden snabbt och säkert förs vidare till de äldste i Darnassus.",al={"vem skickade sentinels till the oracle tree","vad är council of the forest"}},{q="Varför är hennes frånvaro oroande?",a="Även om det varierar hur ofta meddelanden kommer från The Oracle Tree, har hennes frånvaro varat ovanligt länge. Hennes överordnade är oroliga med tanke på att hon fortfarande är under utbildning.",al={"varför är hennes försening ovanlig","hur ofta skickar the oracle meddelanden"}},{q="Vad är målet med sökandet?",a="Du ombeds följa stigen västerut mot The Oracle Glade och leta efter Sentinel Eralya Leafshadow för att ta reda på vad som har försenat henne.",al={"vad gör man i the lost runner","målet med uppdraget the lost runner"}}},fp="15,238,24.380.0,18.378.0,23.164.0,24.189.0,36.160.0,47.157.0,29.162.0,37.141.0"}
P.entries["quest:99047"] = {n="Not Dead Yet",s="'Not Dead Yet' är en brådskande vädjan från Eralya, en dödligt sårad Night Elf som hittas efter ett katastrofalt uppdrag mot The Oracle Tree. Övermannad av grymma harpies ber hon resande att underrätta Byancie i Dolanaar om patrullens öde. Berättelsen visar de dödliga hot som tränger in på Teldrassils skogsstigar.",h="'Not Dead Yet' är en brådskande vädjan från Eralya, en dödligt sårad Night Elf som hittas efter ett...",kw={"byancie","dolanaar","eralya","harpies","not dead yet","oracle tree","teldrassil"},ang={["faction:Alliance"]="Alliansens äventyrare som utforskar Teldrassil får i uppdrag att föra brådskande bud tillbaka till utposter som Dolanaar när fältspanare blir avskurna och övermannade.",["race:NightElf"]="Den fallna budbäraren Eralya och hennes systrar är väktare som tjänstgör på Teldrassil. Att se Night Elf-försvarare överfallas av harpies nära det heliga The Oracle Tree visar tydligt hur farorna på grenarna tilltar."},sec={{t="En överfallen patrull",b="I Teldrassils vildmark kretsar 'Not Dead Yet' kring Eralya, en sårad Night Elf-budbärare som hittas blödande och klamrande sig fast vid livet. Hon skickades på ett viktigt uppdrag mot det heliga The Oracle Tree tillsammans med sina systrar, men patrullen överfölls brutalt och mejades ner av harpies som trängde sig fram. Ingen hjälp är på väg och hennes krafter sinar snabbt. Eralya anförtror förbipasserande resande att föra brådskande nyheter tillbaka till tryggheten."},{t="Ett rop till Dolanaar",b="Med rossliga andetag och blodhosta ber Eralya spelaren att föra hennes rapport till Byancie i den närbelägna byn Dolanaar. Harpies som hemsöker Teldrassils mäktiga grenar har blivit allt djärvare och aggressivare. De utgör ett dödligt hot mot ensamma budbärare och väktare som försöker ta sig fram längs skogsstigarna. Om du för Eralyas vädjan vidare får Dolanaars invånare veta om överfallet vid The Oracle Tree innan fler liv går förlorade."}},faq={{q="Vem är Eralya?",a="Eralya är en Night Elf-väktare eller budbärare som överfölls på ett uppdrag till The Oracle Tree. Hon klamrar sig fast vid livet och hostar blod medan hon ber förbipasserande äventyrare att berätta om hennes enhets öde innan tiden rinner ut.",al={"vem är eralya","eralya uppdrag","döende night elf"}},{q="Vad är The Oracle Tree?",a="The Oracle Tree är ett gammalt landmärke i Teldrassils Oracle Glade. Eralya och hennes systrar skickades dit med ett brådskande meddelande men övermannades på vägen.",al={"vad är oracle tree","oracle glade träd","vart var eralya på väg"}},{q="Vad hände med Eralya och hennes patrull?",a="Eralya och hennes systrar överfölls och övermannades av harpies som hemsöker Teldrassils grenar. Varelserna svärmade fram i stora mängder, mejade ner patrullen och lämnade Eralya dödligt sårad.",al={"vem attackerade eralya","vem överföll henne","varför blöder eralya"}},{q="Vem är Byancie?",a="Byancie är en kontaktperson stationerad i Night Elf-byn Dolanaar. Eralya ber enträget att någon för bud om harpies överfall och patrullens svåra läge direkt till Byancie.",al={"vem är byancie","var finns byancie","byancie dolanaar"}},{q="Vart ska Eralyas meddelande föras?",a="Dolanaar är den främsta Night Elf-byn längs vägen söder om Shadowglen på Teldrassil. Byancie finns där för att ta emot rapporter och samordna det lokala försvaret.",al={"vart ska meddelandet föras","eralya överlämning","var finns dolanaar"}},{q="Vad hände med de andra systrarna på uppdraget?",a="Eralyas Night Elf-kamrater bland väktarna skildes åt eller dödades under harpies brutala angrepp. Utan förstärkningar i sikte fruktade Eralya att ingen av hennes systrar hade undkommit anfallet.",al={"vad hände med eralyas systrar","väktarpatrullens systrar"}}},fp="12,332,18.433.0,18.460.0,14.233.0,24.184.0,39.196.0,15.178.0,41.186.0,50.188.0"}
P.entries["quest:99048"] = {n="A Missing Hand",s="A Missing Hand är ett uppdrag i Durotar som handlar om Heglan Shadeeyes plötsliga försvinnande. Hon är en spanare i Shattered Hand med uppdrag att hålla uppsikt över Tiragarde Keep. När hennes regelbundna underrättelserapporter plötsligt upphör skickas en utredare för att hitta hennes postering och ta reda på vad som tystade henne.",h="A Missing Hand är ett uppdrag i Durotar som handlar om Heglan Shadeeyes plötsliga försvinnande.",kw={"a missing hand","durotar","heglan shadeeye","skurk","spanare","shattered hand","tiragarde keep"},ang={["class:Rogue"]="Shattered Hand fungerar som hordens hemliga ryggrad och underrättelsegille. Utredningen av en försvunnen agent visar hur farliga deras spaningsuppdrag i fält kan vara.",["faction:Horde"]="Det är avgörande för Durotars säkerhet att hålla uppsikt över resterna av Kul Tiras vid Tiragarde Keep, och en oförklarligt försvunnen spanare tyder på ett möjligt osynligt hot alldeles intill Orgrimmars tröskel.",["race:Orc"]="Durotar är ett nyligen säkrat orkområde, och när en agent tystnar inom synhåll från de närliggande mänskliga inkräktarna väcks omedelbart oro för rikets säkerhet."},sec={{t="Tystnade rapporter",b="A Missing Hand börjar med växande oro för Heglan Shadeeye, en spanare i Shattered Hand. Hon är stationerad i Durotar för att på avstånd bevaka den fientliga mänskliga garnisonen i Tiragarde Keep, men hennes stadiga ström av underrättelserapporter upphör plötsligt utan förklaring. Hennes överordnade tvivlar på att människosoldaterna lyckades upptäcka och tillfångata henne, vilket väcker farhågor om att en oväntad och farligare fara ingrep. Äventyrare skickas norr om fästningen för att hitta hennes postering och avgöra om avbrottet bara beror på en försening i kommunikationen eller på något mycket mörkare."},{t="Den kalla kojan",b="När du kommer fram till den angivna observationsposten norr om Tiragarde Keep slutar sökandet i tragedi. Heglan ligger död bland de splittrade resterna av en raserad koja. De fysiska spåren tyder på att angriparen inte var människa, vilket väcker den obehagliga frågan om vilken varelse eller entitet som fällde en tränad agent så nära hordens områden. Ledtrådar kring spillrorna antyder ett okänt hot som nu måste avslöjas."}},faq={{q="Vad är uppdraget A Missing Hand?",a="A Missing Hand är ett uppdrag i Durotar där en äventyrare får i uppdrag att hitta Heglan Shadeeye, en spanare i Shattered Hand. Hon var stationerad norr om Tiragarde Keep, men hennes regelbundna underrättelserapporter upphörde plötsligt.",al={"vad är a missing hand","översikt över uppdraget a missing hand"}},{q="Vem är Heglan Shadeeye?",a="Heglan Shadeeye är en agent i Shattered Hand med uppdrag att i hemlighet bevaka Tiragarde Keep från en närliggande utsiktspunkt. Hennes spaningsrapporter upphörde plötsligt, vilket ledde till en utredning om var hon befann sig.",al={"vem är heglan","var är heglan shadeeye","försvunnen spanare"}},{q="Vad hände med Heglan Shadeeye?",a="Det är vad uppdraget ska ta reda på. Hennes rapporter från posteringen norr om Tiragarde Keep upphörde utan förvarning, och den som skickar dig tvivlar på att människorna tog henne till fånga och befarar att något farligare ligger bakom.",al={"vad hände med heglan shadeeye","är heglan död","heglans öde"}},{q="Vad är Shattered Hand?",a="I den moderna Horden är Shattered Hand en organisation av diskreta agenter, lönnmördare och spioner. De utför hemlig övervakning och underrättelsearbete för att skydda hordens områden.",al={"vad är shattered hand","vilka är shattered hand"}},{q="Dödade människorna i Tiragarde Keep Heglan?",a="Hennes överordnade tvivlar på det. Heglan bevakade de fientliga människorna från Kul Tiras som höll Tiragarde Keep, men den som skickar dig tror inte att de kunde ha tagit henne till fånga och befarar att något farligare ligger bakom.",al={"dödade människor heglan","dödade soldater från tiragarde henne"}},{q="Varför bevakades Tiragarde Keep?",a="Tiragarde Keep är en utpost som hålls av fientliga sjömän och soldater från Kul Tiras, vilka hotar Durotars kust. Heglan var stationerad i närheten för att hålla uppsikt över deras förehavanden och rapportera underrättelser till Horden.",al={"varför bevakade heglan tiragarde keep","övervakning av tiragarde keep"}}},fp="14,289,14.588.0,12.461.1,33.223.0,23.220.0,33.218.0,27.202.0,45.228.0,37.212.0"}
P.entries["quest:99049"] = {n="Threat from Below",s="Threat from Below är ett uppdrag för Horde där du undersöker ett våldsamt bakhåll längs östra Durotars kust. Efter att spanaren Heglan Shadeeye överfallits vid sin post i en hård strid måste du leta efter ledtrådar i det skövlade området. Fysiska bevis avslöjar ett hot som direkt hotar Razor Hills försvarslinjer.",h="Threat from Below är ett uppdrag för Horde där du undersöker ett våldsamt bakhåll längs östra Durotars kust.",kw={"durotar","heglan shadeeye","horde","naga","orgnil soulscar","razor hill","spanare","threat from below"},ang={["faction:Horde"]="Att undersöka kusten är avgörande för Durotars säkerhet och skyddar den unga Horde-nationen från att bli kringränd längs sina kustgränser.",["race:Orc"]="Orciska försvarare ser bakhållet mot spanaren Heglan Shadeeye som ett outhärdligt intrång i deras etablerade hemland och kräver en omedelbar undersökning och hämnd.",["race:Troll"]="Darkspear Trolls känner naga-farornas lömska natur alltför väl efter att tidigare ha mött sjöhäxor och fasor från havet i Great Sea."},sec={{t="Bakhåll vid Durotars kust",b="En våldsam strid längs Durotars kust lämnar marken sönderslagen och väcker omedelbar oro bland Hordes försvarare. Heglan Shadeeye, en spanare från Shattered Hand som höll vakt från sin post, överfölls av en osedd fiende. Stridsplatsen visar tydligt att Heglan kämpade hårt och skadade sina angripare. Fientliga styrkor rör sig obehindrat längs den östra kusten. Därför får äventyrare från Horde i uppdrag att undersöka det skövlade lägret, söka igenom marken efter ledtrådar och ta reda på vilken sorts fiende som anföll spanaren."},{t="Ormhota",b="I spillrorna hittar du en sönderriven fana och en flisa från ett exotiskt klingvapen. Båda tillhör de ormlika naga. De lömska vattenvarelserna tycks ha krupit söderut längs Durotars kust från Azshara för att skapa ett fäste där de kan jaga. För garnisonen i Razor Hill signalerar fyndet en annalkande kris. Bosättningen är redan ansatt av människor från Kul Tiras vid Tiragarde Keep i söder och quilboar längs de västra ravinerna. Den kan inte stå emot ett nytt anfall från havet i norr utan att riskera att falla helt."}},faq={{q="Vad är Threat from Below?",a="Threat from Below är ett uppdrag i Durotar där äventyrare från Horde undersöker bakhållet mot spanaren Heglan Shadeeye. Efter tecken på en våldsam strid längs kusten söker du igenom den uppbökade marken efter ledtrådar som angriparna lämnat. Sedan lämnar du fynden direkt till Orgnil Soulscar i Razor Hill, så att han kan bedöma det militära hotet mot området.",al={"uppdraget threat from below","vad är threat from below","översikt över threat from below"}},{q="Vem är Heglan Shadeeye?",a="Heglan Shadeeye är en spanare från Shattered Hand som höll uppsikt över Tiragarde Keep från en hydda norr om fästet och vaktade Hordes kärnland. Under ett uppdrag överfölls hon vid sin utsiktspost vid kusten. De omfattande skadorna på lägerplatsen tyder på att hon kämpade hårt mot angriparna. Därför kräver ledarna i Razor Hill omedelbara svar.",al={"heglan shadeeye","vem är heglan","heglan shadeeyes bakgrund"}},{q="Vem anföll Heglan Shadeeye?",a="Heglan Shadeeye överfölls av naga som rörde sig söderut längs Durotars kust. Fysiska bevis från striden, närmare bestämt en särskild fana och en bit av ett sönderslaget klingvapen, bekräftar att ormvarelserna utförde räden. Striden var så våldsam att även angriparna skadades.",al={"vem överföll heglan","heglans angripare","vad anföll heglan shadeeye"}},{q="Vem är Orgnil Soulscar?",a="Orgnil Soulscar är en framstående orcisk befälhavare stationerad i Razor Hill i centrala Durotar. Han ansvarar för att organisera områdets försvar och samordna Hordes spanare, och håller uppsikt över underrättelser om fientliga intrång. När Heglan Shadeeye inte återvänder förlitar sig Orgnil på spanare och äventyrare som kommer tillbaka för att identifiera angriparna och skydda bosättningen.",al={"vem är orgnil","orgnil soulscar","orgnil i razor hill"}},{q="Varför är naga ett hot mot Razor Hill?",a="Razor Hill är redan hårt pressat av människor från Kul Tiras som befäst sig i söder och fientliga quilboar i väster. Om naga etablerar ett permanent brohuvud längs den östra kusten i norr riskerar Hordes utpost att fångas i en omöjlig kniptång. Det skulle tänja garnisonens begränsade styrkor till bristningsgränsen och skära av förstärkningsvägarna genom Durotar.",al={"varför är naga farliga här","naga hotar razor hill","naga-faran vid razor hill"}},{q="Varifrån kom naga som anföll?",a="De militära lämningarna tyder på att naga färdades söderut längs kusten från nordliga vatten, troligen från Azshara eller kontinentalsockeln i Great Sea. Genom att färdas på vattenvägarna och undvika patruller i inlandet kunde vattenvarelserna snabbt slå till mot isolerade kustposter innan Durotars försvarare hann ordna ett sammanhängande försvar.",al={"varifrån kom naga","nagas ursprung i durotar","hur kom naga till durotar"}}},fp="17,381,27.563.0,18.564.1,26.391.0,23.367.0,29.310.0,23.374.0,40.379.0,39.355.0"}
P.entries["quest:99050"] = {n="The Great Tree Provides",s="The Great Tree Provides är ett uppdrag i Dolanaar där Byancie ber om hjälp att hejda en farlig åkomma som hotar Eralya. Genom att samla daggiga lasherskott från Teldrassils sjöar och hämta grundläggande förnödenheter hjälper spelarna till att förbereda en brådskande läkande salva.",h="The Great Tree Provides är ett uppdrag i Dolanaar där Byancie ber om hjälp att hejda en farlig åkomma som...",kw={"åkomma","byancie","daggiga lasherskott","dolanaar","eralya","läkande salva","lake al'ameth","teldrassil","the great tree provides","wellspring lake"},ang={["class:Druid"]="Druider uppskattar de naturligt läkande egenskaperna hos Teldrassils växter och förlitar sig på inhemska växter som lasherskott i stället för konstgjorda blandningar.",["profession:Herbalism"]="För erfarna örtmästare är det naturligt att samla inhemskt växtmaterial som daggiga lasherskott för att brygga kraftfulla läkande salvor.",["race:NightElf"]="Teldrassils örtmediciner speglar kaldoreis tro på att deras världsträd uppehåller och skyddar dem genom att erbjuda levande läkemedel mot plötsliga åkommor."},sec={{t="En kamp mot tiden",b="I den skogsklädda byn Dolanaar vårdar Byancie de lokala nattalverna. När beskedet kommer att Eralya har drabbats av en farlig åkomma ute i Teldrassils vildmark börjar Byancie genast förbereda en akut behandling. Utan en snabbverkande salva som hejdar sjukdomens förlopp överlever Eralya inte färden tillbaka till byn för att få ordentlig vård."},{t="Det väldiga världsträdet",b="Även i krisens stund litar kaldorei på Teldrassils överflöd. Byancie vänder sig till det levande världsträdet för att finna botemedlet och söker daggiga lasherskott som växer nära Lake Al'Ameth i söder och Wellspring Lake i nordväst. Blandade med rent källvatten i en enkel glasflaska ger dessa kraftfulla blad den viktiga medicin som behövs för att hålla åkomman stången."}},faq={{q="Vad är The Great Tree Provides?",a="The Great Tree Provides är ett brådskande uppdrag i Dolanaar från Byancie, som vill blanda till en läkande salva för att hejda en åkomma som hotar Eralya tills vidare behandling blir möjlig.",al={"vad är the great tree provides","uppdraget the great tree provides","byancies uppdrag"}},{q="Vem är Byancie?",a="Byancie är en nattalv och helare eller apotekare som bor i byn Dolanaar på Teldrassil. Hon ägnar sig åt att vårda sjuka och tillreda naturläkemedel av den lokala floran.",al={"vem är byancie","byancie i dolanaar","uppdragsgivaren byancie"}},{q="Vem är Eralya och vad hände henne?",a="Eralya är en drabbad person som befinner sig utanför Dolanaar och vars tillstånd snabbt försämras. Byancie behöver en akut salva för att stabilisera henne länge nog för att hon ska kunna föras tryggt in till byn för fullständig behandling.",al={"vem är eralya","vad hände eralya","eralya åkomma"}},{q="Var hittar man daggiga lasherskott?",a="Daggiga lasherskott växer på växtlashers runt Lake Al'Ameth, rakt söder om Dolanaar, samt längs Wellspring Lake och dess flod i nordväst.",al={"var hittar man daggiga lasherskott","plats för daggiga lasherskott","lasherskott på teldrassil"}},{q="Vilka ingredienser behövs för att tillreda salvan?",a="Byancie behöver sex daggiga lasherskott som plockats från inhemska lashers, en tom flaska och Refreshing Spring Water för att blanda den akuta läkande salvan.",al={"vilka ingredienser behöver byancie","salvans ingredienser i dolanaar","föremål till the great tree provides"}},{q="Var kan man få tag på en tom flaska och Refreshing Spring Water?",a="Både tomma flaskor och Refreshing Spring Water kan köpas direkt av handlare med allmänna varor eller handelsvaror i Dolanaar.",al={"var får man tag på flaska och källvatten","tom flaska i dolanaar","refreshing spring water i dolanaar"}}},fp="23,260,19.409.0,24.393.0,32.190.0,15.180.0,39.214.0,35.159.0,51.149.0,63.150.0"}
P.entries["quest:99051"] = {n="Threat from Below",s="Threat from Below är ett försvarsuppdrag där aggressiva naga-spejare som slagit läger i närheten ska rensas bort. Genom att slå till mot spejarstyrkorna och ta deras ryggfenor försöker äventyrarna driva de ormlika inkräktarna norrut och skydda området.",h="Threat from Below är ett försvarsuppdrag där aggressiva naga-spejare som slagit läger i närheten ska rensas...",kw={"fotsoldater","naga","naga-ryggfenor","spejare","ormavskum","ryggfenor","threat from below"},ang={["faction:Horde"]="Uppdragsgivaren mobiliserar Horde-fotsoldater för att hålla utkik efter eftersläntrare, vilket gör detta till ett förebyggande försvar av Horde-kontrollerat territorium mot naga-spejare som tränger in."},sec={{t="Ormlikt intrång",b="Threat from Below handlar om en växande gränsstörning som orsakas av naga-spejare som tränger in i området. De ormlika plundrarna har börjat anlägga förläger i närheten, så de lokala försvararna slår till innan inkräktarna hinner säkra ett permanent fotfäste. Äventyrarna skickas ut för att slå ut spejarstyrkorna och återvända med naga-ryggfenor som bevis på att lägret har krossats."},{t="Säkra gränsen",b="Det är inte första gången ormfolket stör området, och det lokala befälet gör klart att deras närvaro inte kommer att tolereras. Efter anfallet mot deras spejarläger är målet att driva alla överlevande naga norrut och låta vaksamma Horde-fotsoldater hålla vakt mot eftersläntrare eller plötsliga bakhåll."}},faq={{q="Vad är Threat from Below?",a="Threat from Below är ett Horde-uppdrag där äventyrarna ska eliminera naga-spejare som har börjat anlägga läger i närheten. För att stoppa intrången måste spelarna döda de framryckande ormfolken och samla naga-ryggfenor som bevis på bedriften.",al={"vad är threat from below","uppdraget threat from below"}},{q="Vilka är ormarna som nämns i ordern?",a="”Ormarna” eller ”ormavskummet” syftar på naga, amfibiska ormlika humanoider som har kommit från kusternas eller vattendjupens mörker för att spana på lokala positioner.",al={"vilka är ormarna","ormar i threat from below"}},{q="Varför måste naga-spejarna elimineras?",a="Lägren tyder på en organiserad spaningsinsats, inte kringströvande varelser. Den lokala befälhavaren kräver ett snabbt motangrepp för att driva bort inkräktarna innan de kan inleda ett större anfall eller befästa sina positioner ytterligare.",al={"varför döda naga-spejare","nagas motiv"}},{q="Varför samlas naga-ryggfenor in?",a="Avskurna ryggfenor är ett otvetydigt fysiskt bevis på att spejarlägren har upptäckts och slagits sönder, och bekräftar att det omedelbara trycket längs gränsen har brutits.",al={"varför ryggfenor","bevis från naga"}},{q="Vart förväntas naga dra sig tillbaka?",a="När fenorna lämnas in säger befälhavaren att förhoppningen är att anfallet ska driva naga norrut igen. Fotsoldater får i uppdrag att hålla utkik efter eftersläntrare eller misstänkta rörelser.",al={"vart tar naga vägen","naga norrut"}},{q="Vem håller vakt när spejarna har dödats?",a="Horde-fotsoldater får i uppdrag att hålla vakt i området och se till att inga eftersläntrare finns kvar och att naga inte försöker göra fler intrång.",al={"vem håller utkik efter naga","fotsoldater håller utkik efter naga"}}},fp="17,245,20.379.0,20.334.0,26.262.0,43.157.0,39.231.0,33.178.0,39.179.0,43.143.0"}
P.entries["quest:99052"] = {n="Threat from Below",s="Threat from Below är en belöningsuppgift från Horde där äventyrare får i uppdrag att jaga en farlig havsjätte som stryker längs Durotars norra kust. Att besegra en så väldig kusttitan skyddar stränderna i närheten och vinner Durotars krigares respekt.",h="Threat from Below är en belöningsuppgift från Horde där äventyrare får i uppdrag att jaga en farlig havsjätte...",kw={"blod och åska","kustmonster","durotar","horde-uppdrag","the north coast","havsjätte","threat from below"},ang={["class:Warrior"]="Att möta en väldig havsjätte i direkt strid är ett hårt prov på kamputhållighet och ett sätt att bevisa sig mot en av kustens allra tyngsta bestar.",["faction:Horde"]="När en havsjätte fälls längs Durotars kust försvinner en farlig koloss som lurade alldeles intill Hordes kärnland.",["race:Orc"]="Orchisk heder värdesätter att möta titaniska motståndare och besvara stridsropet ”blod och åska” med överväldigande fysisk styrka."},sec={{t="Den norra kustlinjen",b="Längs Durotars norra kustlinje sköljer Stora havets vatten mot ojämna sandstränder och klippiga kuster. Där brukar enkla asätare och krabbor hålla till, men på den norra kusten lurar ett mycket dödligare hot: en väldig havsjätte som strövar på grunt vatten och hotar alla som försöker färdas längs eller säkra vattnen intill Hordes torra, nya hemland."},{t="Vågornas titan",b="Havsjättar är resliga bestar som kan slå sönder långbåtar och krossa krigare under sina väldiga nävar. Det är ingen vanlig bedrift för unga äventyrare att dräpa en sådan, och den som fäller denna vågarnas koloss vinner stor respekt bland orcherna. Då ekar det traditionella stridsropet ”blod och åska” över de torra, röda klipporna."}},faq={{q="Vad är uppdraget Threat from Below?",a="Threat from Below är ett uppdrag åt Hordes mästare att jaga och besegra en kolossal havsjätte som strövar längs Durotars norra kust och återvända med bevis på bedriften.",al={"vad är threat from below","uppdraget threat from below","havsjätteuppdrag durotar"}},{q="Var hittar man havsjätten?",a="Havsjätten strövar i vattnen och längs stränderna på Durotars norra kust.",al={"var finns havsjätten","havsjättens plats i durotar","platsen för threat from below"}},{q="Vad är en havsjätte för slags varelse?",a="Havsjättar är väldiga, uråldriga kustkolosser som skapades för att muddra haven och forma Azeroths kustlinjer. Få kringvandrande överlever en direkt konfrontation med en av dem.",al={"vad är en havsjätte","havsjättens historia","vilka är havsjättarna"}},{q="Varför måste havsjätten dödas?",a="En så enorm varelse som stryker så nära Durotar utgör en allvarlig fara för kustresenärer, fiskare och Hordes läger längs stranden.",al={"varför döda havsjätten","är havsjätten farlig","hot mot durotar"}},{q="Vad menar uppdragsgivaren med ”blod och åska”?",a="”Blod och åska” är ett traditionellt orcist stridsrop som hyllar kampstyrka, våldsamhet och äran i att segra över farliga motståndare.",al={"betydelsen av blod och åska","orchehälsning blod och åska"}},{q="Vilket bevis krävs för att slutföra uppdraget?",a="Uppdraget kräver att du tar med ett konkret, fysiskt bevis på havsjättens fall från den norra kusten, så att det kan bekräftas att den väldiga besten har dödats.",al={"bevis för threat from below","bevis på bedriften"}}},fp="17,246,22.365.0,20.340.0,36.172.0,29.92.0,37.170.0,45.156.0,54.152.0,44.150.0"}
P.entries["quest:99053"] = {n="Escaping Ban'ethil",s="Escaping Ban'ethil är ett räddningsuppdrag i den underjordiska gravkammaren på Teldrassil. Sentinel Lynessa Duskblossom, som tillfångatogs av aggressiva Gnarlpine furbolg när hon levererade ett meddelande till sovande druider, måste eskorteras säkert upp till ytan och rapporteras vara i trygghet i Dolanaar.",h="Escaping Ban'ethil är ett räddningsuppdrag i den underjordiska gravkammaren på Teldrassil.",kw={"ban'ethil barrow den","dolanaar","escaping ban'ethil","furbolg","gnarlpine","kaldorei","kyra starsong","lynessa duskblossom","oracle tree","teldrassil"},ang={["class:Druid"]="Ban'ethil Barrow Den är avsedd som en fristad för druider som slumrar medan de kommunicerar med The Emerald Dream. Att den fallit i händerna på vilda furbolg är därför en akut kris för Cenarion-försvararna.",["faction:Alliance"]="Att skydda Darnassus och Teldrassil kräver att man hjälper Sentinels att möta den växande fientligheten från fördärvat inhemskt djurliv och stammar.",["race:NightElf"]="Sentinel Lynessa Duskblossom är en vapensyster vars fångenskap under rötterna går stick i stäv med nattalvernas heliga band till Teldrassils öppna stjärnhimmel och trädkronor."},sec={{t="Bakhåll under rötterna",b="Oracle Tree skickade Sentinel Lynessa Duskblossom på ett brådskande ärende för att överlämna ett meddelande till druiderna som vilade i Ban'ethil Barrow Den. Det som skulle ha varit en vanlig budtjänst slutade i katastrof när hon upptäckte att de underjordiska kamrarna var helt översvämmade av aggressiva Gnarlpine furbolg. Hon blev avskuren och överfallen innan hon hann retirera, och togs till fånga i de mörka tunnlarna. Hon fruktade ett grymt slut i händerna på stammen tills en äventyrare ingrep och kämpade med henne upp till ytan."},{t="Trygg återkomst till Dolanaar",b="För kaldorei Sentinels är det underjordiska mörkret i en gravkammare en onaturlig och motbjudande plats att vara fången på, långt från Elunes rogivande stjärnljus och Teldrassils friska luft. Efter att ha räddats ur djupet flyr Lynessa tillbaka mot civilisationen, medan budet om att hon överlevt förs till Dolanaar. Där tar Sentinel Kyra Starsong emot nyheten om sin väns överlevnad med stor lättnad och belönar dem som hjälpte hennes kamrat att försvara kaldorei-folket."}},faq={{q="Vem är Sentinel Lynessa Duskblossom?",a="Sentinel Lynessa Duskblossom är en night elf-sentinel stationerad på Teldrassil. Oracle Tree skickade henne för att leverera ett viktigt meddelande till druiderna som vilade i Ban'ethil Barrow Den, men hon överfölls och tillfångatogs av Gnarlpine furbolg djupt under marken.",al={"vem är lynessa duskblossom","lynessa duskblossom","vem är fångad i gravkammaren"}},{q="Varför gick Sentinel Lynessa in i Ban'ethil Barrow Den?",a="Oracle Tree skickade henne på ett officiellt uppdrag för att bära ett meddelande till druiderna som slumrade i Ban'ethil Barrow Den. När hon nådde den underjordiska gravkammaren upptäckte hon att fientliga furbolg hade tagit över den innan hon hann överlämna sitt meddelande.",al={"varför gick lynessa till banethil","vad var lynessas uppdrag","meddelande från oracle tree"}},{q="Vem tillfångatog Sentinel Lynessa?",a="Hon tillfångatogs av Gnarlpine furbolg som bodde i gravkammaren. Stammen var fientlig och aggressiv och överföll henne innan hon hann fly och släpade ner henne i djupet, så att hon fruktade att bli deras nästa måltid.",al={"vem tillfångatog lynessa","vilka furbolg finns i banethil","gnarlpine furbolg"}},{q="Vad är Ban'ethil Barrow Den?",a="Ban'ethil Barrow Den är en underjordisk fristad på Teldrassil, väster om Dolanaar. Den höggs traditionellt ut under jorden som viloplats för night elf-druider som gick in i djup gemenskap, men har tagits över av fördärvade Gnarlpine furbolg.",al={"var ligger banethil barrow den","vad är banethil barrow den","gravkammare på teldrassil"}},{q="Vem är Sentinel Kyra Starsong?",a="Sentinel Kyra Starsong är en night elf-sentinel stationerad i byn Dolanaar. Hon är nära vän med Lynessa Duskblossom och väntar ivrigt på nyheter om att Lynessa har flytt och återvänt i trygghet.",al={"vem är kyra starsong","var lämnar jag in escaping banethil","dolanaars sentinel"}},{q="Varför avskyr Lynessa att vara under jord?",a="Druider använder gravkammare för helig sömn, men många night elf-sentinels och krigare ogillar starkt att vara instängda under jord. Kaldorei-kulturen värnar om den öppna natthimlen, Elunes stjärnljus och skogens skyddande grenverk ovanför de underjordiska tunnlarna.",al={"varför ogillar nattalver gravkammare","under jorden hör kaldorei inte hemma"}}},fp="18,283,26.512.0,23.504.0,36.266.0,52.249.0,30.236.0,29.245.0,30.201.0,42.281.0"}
P.entries["quest:99073"] = {n="Easing Suffering",s="Easing Suffering är ett uppdrag i Teldrassil där du ska ge akut hjälp åt Sentinel Eralya Leafshadow, som ligger svårt sjuk av en häftig röta på vägen till The Oracle Tree. Du skyndar Lashwater Salve till henne för att lindra plågorna och ge ro åt hennes sviktande andning.",h="Easing Suffering är ett uppdrag i Teldrassil där du ska ge akut hjälp åt Sentinel Eralya Leafshadow, som...",kw={"easing suffering","eralya leafshadow","lashwater salve","oracle tree","röta","sentinel eralya","teldrassil"},ang={["faction:Alliance"]="När du hjälper fallna Night Elf-väktare längs vägarna i Darnassus hemland bidrar du till att bevara den sköra frontlinjen mot den växande korrumperingen i Teldrassils grenar.",["race:NightElf"]="Sentinel Eralya Leafshadow är en av dina egna, drabbad av en häftig korrumpering i Teldrassils vildmark nära The Oracle Tree. När du ger henne tröst hedrar du det ansvar som Sentinels har för sina fränder."},sec={{t="En kamp mot rötan",b="Sentinel Eralya Leafshadow ligger svårt sjuk av en snabbt spridande, varig röta på vägen till The Oracle Tree. För att hejda hennes plågsamma försämring måste en nyberedd Lashwater Salve föras till henne utan dröjsmål, innan åkomman får fullt grepp."},{t="Ro i skuggorna",b="De som vårdar henne tvivlar på att Lashwater Salve är stark nog att helt utrota farsoten, men när den ges lugnar den snabbt Eralyas ansträngda, rosslande andning. Det är osäkert om hon överlever, men behandlingen ger henne ro under hennes mörkaste stund."}},faq={{q="Vem är Sentinel Eralya Leafshadow?",a="Sentinel Eralya Leafshadow är en Night Elf-väktare som ligger sjuk längs vägen mot The Oracle Tree. När hon hittas är hon utslagen och nära döden, drabbad av en aggressiv, varig röta.",al={"vem är eralya","eralya leafshadow","vem är sentinel eralya"}},{q="Vad är Lashwater Salve?",a="Lashwater Salve är ett läkemedel som ska lindra den våldsamma smärta som den häftiga rötan orsakar Sentinel Eralya. Det är osäkert om det kan bota åkomman helt, men det lindrar hennes plågor.",al={"vad är lashwater salve","lashwater salve","botar salvan röta"}},{q="Överlever Sentinel Eralya åkomman?",a="Salvan lindrar Sentinel Eralyas andning och ger henne viss ro, men det är fortfarande osäkert om hon verkligen återhämtar sig eller dukar under för rötan som fått fäste.",al={"överlever eralya","är eralya botad","dog eralya"}},{q="Var hittar man Sentinel Eralya Leafshadow?",a="Sentinel Eralya Leafshadow ligger längs stigen mot The Oracle Tree, i Teldrassils uråldriga marker.",al={"var finns oracle tree","vägen till oracle tree","eralya plats"}},{q="Vilken åkomma drabbade Sentinel Eralya?",a="Eralya lider av en aggressiv, varig röta som snabbt sprider sig genom kroppen. Den exakta källan till smittan är okänd, men den angriper snabbt och blir allt häftigare med tiden.",al={"vad orsakade eralyas sjukdom","vad är rötan","eralya åkomma"}},{q="Varför måste salvan levereras skyndsamt?",a="Rötan sprider sig snabbt genom Eralyas kropp och blir värre. Det är nödvändigt att skynda, eftersom varje ögonblick för henne närmare att helt duka under för plågorna och förruttnelsen.",al={"varför skynda med salvan","varför skynda för eralya"}}},fp="16,278,22.266.0,20.296.1,34.208.0,24.209.0,44.175.0,46.129.0,39.191.0,43.194.0"}
P.entries["quest:99079"] = {n="Longwalker Malah",s="Longwalker Malah är en försvunnen tauren-spejare som skickades för att undersöka Mulgore östra gränstrakter på uppdrag av Bloodhoof Village. Som en av de främsta Longwalker-spejarna, direkt underställd överhövdingen, väcker hennes plötsliga frånvaro efter tre dagar en brådskande efterlysning för att säkra både hennes överlevnad och dalens trygghet.",h="Longwalker Malah är en försvunnen tauren-spejare som skickades för att undersöka Mulgore östra gränstrakter...",kw={"baine bloodhoof","bloodhoof village","fjäderprydd stav","longwalker malah","longwalkers","malah longwind","mulgore","tauren-spejare"},ang={["class:Hunter"]="Jägare respekterar Longwalkers kunskaper i att spåra vildmarken och den uthållighet som krävs för att till fots patrullera Mulgore avlägsna utkanter.",["faction:Horde"]="När du hjälper ledarna i Bloodhoof Village att hitta försvunna gränsspejare bidrar du till att skydda Mulgore mot yttre hot som tränger in på Horde-land.",["race:Tauren"]="Longwalkers är vördnade spejare som rapporterar direkt till överhövdingen Cairne Bloodhoof. Därför är deras säkerhet en fråga av största kulturella och taktiska vikt för alla tauren."},sec={{t="Överhövdingens ögon",b="Longwalkers tjänar som shu'halos ögon och öron. De är kända över slätterna för sina outtröttliga steg och sin överlevnadsförmåga. Dessa elitspejare har svurit trohet direkt till överhövdingen Cairne Bloodhoof och får i uppdrag att färdas genom vidsträckta områden för att samla underrättelser och leverera viktiga budskap. Även om deras trohet ytterst endast tillhör överhövdingen, ber unge Baine Bloodhoof dem ibland om hjälp med att skydda bosättningen Bloodhoof Village och betesmarkerna runtomkring."},{t="Försvunnen vid gränsen",b="Longwalker Malah Longwind skickades för att bevaka Mulgore östra gräns och gav sig ut på ett vanligt spaningsuppdrag som skulle pågå i tre dagar. När hon inte återvände till Bloodhoof Village som väntat började byns ledare bli oroliga. Longwalkers bär på livsviktiga underrättelser, och faror lurar ständigt längs Mulgore gränsklippor. Därför ombeds spejare och villiga resenärer att följa hennes spår och ta reda på om hon är oskadd. Du känner igen Malah på ordens traditionella kännetecken: ett ceremoniellt pannband och en fjäderprydd stav."}},faq={{q="Vem är Longwalker Malah?",a="Longwalker Malah Longwind är en uppskattad tauren-spejare som tjänar överhövdingen. Hon skickades på ett spaningsuppdrag nära Mulgore östra gräns och bar det traditionella pannbandet och den fjäderprydda staven som kännetecknar hennes orden.",al={"vem är malah","malahs bakgrund","longwalker malah identitet"}},{q="Vilka är Longwalkers?",a="Longwalkers är taurenfolkets mest betrodda elitspejare och budbärare. De har svurit trohet direkt till överhövdingen, men andra stamledare, som unge Baine Bloodhoof, ber dem ibland om hjälp med viktig gränsbevakning.",al={"vad är longwalkers","vilka är longwalkers","tauren-spejare"}},{q="Varför letar man efter Longwalker Malah?",a="Malah skickades för att undersöka Mulgore östra utkanter och väntades tillbaka inom tre dagar. När hon inte återvände blev man orolig i Bloodhoof Village för att något kunde ha hänt henne under patrulleringen av den oländiga gränsen.",al={"varför är malah försvunnen","varför malah-uppdraget","vart tog malah vägen"}},{q="Var kan Malah finnas?",a="Longwalker Malah skickades mot Mulgore östra gräns, förbi Bloodhoof Village och mot bergsryggen vid gränsen. Resenärer som söker efter henne bör leta i gränstrakterna öster om byn.",al={"var är malah","malahs plats","hitta malah"}},{q="Hur känner du igen Longwalker Malah?",a="Du känner igen Malah på Longwalkers utmärkande dräkt: ett särskilt pannband och en hög fjäderprydd stav som spejare från den ansedda orden bär.",al={"malahs utseende","hur känner man igen malah","longwalkers utrustning"}},{q="Varför är Baine Bloodhoof inblandad med Longwalkers?",a="Longwalkers rapporterar endast till överhövdingen Cairne Bloodhoof, men hans son Baine sköter lokala angelägenheter i Bloodhoof Village. Ibland ber han dem använda sina spårningskunskaper för att bevaka gränsen och trygga dalen.",al={"baines roll","varför är baine inblandad","baine bloodhoof spejare"}}},fp="16,324,25.502.0,27.554.0,24.243.0,25.268.0,43.230.0,25.192.0,38.160.0,53.249.0"}
P.entries["quest:991"] = {n="Raene's Cleansing",s="Raene's Cleansing börjar när Raene Wolfrunner ber en äventyrare att leta reda på hennes försvunne vän Teronis. För att hitta ett sätt att hejda furbolgernas våldsamma angrepp i Ashenvale gav sig Teronis av mot Lake Falathim för att hämta en magisk ädelsten.",h="Raene's Cleansing börjar när Raene Wolfrunner ber en äventyrare att leta reda på hennes försvunne vän Teronis.",kw={"ashenvale","falathim","furbolg","ädelsten","murloc","raene","teronis","wolfrunner"},ang={["faction:Alliance"]="Alliansens rekryter som anländer till Astranaar får snart veta att Ashenvales heliga lundar belägras av fientliga vilddjur, furbolger och invaderande murlocs.",["race:NightElf"]="Teronis försvinnande är ännu ett hårt slag för nattalverna, som redan har fullt upp med att hela Ashenvale och skydda sina helgedomar från korruption."},sec={{t="En väns oro",b="Raene Wolfrunner tjänstgör tillsammans med Sentinels i Astranaar och försvarar Ashenvale mot växande hot. Teronis var en av hennes närmaste följeslagare och tog på sig att hitta ett kraftfullt försvar mot de allt våldsammare furbolgstammarna. När dagarna gick utan att han återvände blev Raene djupt orolig. Hon kunde inte lämna sin post, men fruktade det värsta."},{t="Jakten på staven",b="Teronis följde rykten om en mäktig stav som smitts av en avliden, ondskefull trollkarl. Han trodde att dess magi kunde stilla furbolgernas raseri. För att återställa artefakten behövde han en förtrollad ädelsten som gömts i en alvisk helgedom vid Lake Falathim, nära bergen i väster. Tyvärr hade aggressiva murlocstammar nyligen tagit över de fridfulla vattnen."},{t="Tragedin vid Lake Falathim",b="När du följer Teronis spår till ön i Lake Falathim möts du av en mörk syn. Teronis tog sig aldrig levande ur vattnet. Hans döda kropp ligger vid helgedomen, täckt av djupa hugg från murlocernas vapen och klor. Hans sökande fick ett alltför tidigt slut."}},faq={{q="Vem är Raene Wolfrunner?",a="Raene Wolfrunner är en nattalv som är allierad med Ashenvales Sentinels och stationerad i Astranaar. Hon leder olika försvarsinsatser för att skydda skogen mot fiender som tränger in.",al={"raene","vem är raene","uppdragsgivare"}},{q="Vem var Teronis?",a="Teronis var en nära vän till Raene Wolfrunner som sökte efter forntida magiska lösningar för att rädda skogen. Han trodde att en förtrollad stav kunde lugna de korrumperade furbolgerna och gav sig ensam av för att hämta dess delar.",al={"vem är teronis","teronis bakgrund","försvunnen vän"}},{q="Var försvann Teronis?",a="Teronis försvann vid Lake Falathim, en sjö vid foten av bergen i västra Ashenvale, som hade översvämmats av fientliga murlocs.",al={"var är teronis","teronis plats","lake falathim"}},{q="Varför letade Teronis efter en ädelsten?",a="Ädelstenen var en viktig del som behövdes för att ge kraft åt en magisk stav skapad av en avliden, ond trollkarl. Teronis hoppades kunna använda stavens kraft för att hejda de rasande furbolgernas angrepp.",al={"vilken ädelsten","varför ädelsten","teronis ädelsten"}},{q="Vad hände med Teronis?",a="Raene har inte hört från honom sedan han gav sig av till Lake Falathim. Om du följer hans spår får du veta vad som hände honom.",al={"hur dog teronis","teronis mördare","vem dödade teronis"}},{q="Varför angriper furbolgerna Ashenvale?",a="Efter det tredje kriget föll Ashenvales furbolger offer för demonisk korruption och vansinne. Det drev stammar som en gång levt i fred till skoningslös, våldsam fientlighet mot sina tidigare allierade.",al={"furbolgangrepp","varför är furbolgerna aggressiva","furbolgernas vansinne"}}},fx={["82e89856"]={q="Varför vill Raene Wolfrunner att Teronis ska hittas?",a="Teronis är en gammal och betrodd vän till Raene Wolfrunner som ställde upp för att hjälpa Sentinels mot de rasande furbolgs. Han gav sig av för att söka efter en magisk stav och ädelsten som kanske kunde stoppa angreppen på deras folk, men han kom aldrig tillbaka. Raene oroar sig djupt för hans säkerhet och är desperat efter att få veta vilken hjälp han kan ha funnit åt deras hårt ansatta länder.",al={"varför vill raene hitta teronis","raene wolfrunners motiv","varför leta efter teronis"}}},fp="17,245,18.364.0,21.353.0,24.268.1,24.182.0,16.210.0,29.155.0,34.185.0,25.98.1,41.194.0"}
P.entries["quest:99108"] = {n="Sparring Match",s="Sparring Match är ett introduktionsprov under kampinstruktören Tang Stonehoofs uppsikt. Provet prövar nykomlingar oavsett klass eller bakgrund. Äventyrarna ska besegra tre arenanybörjare eller andra duellanter för att visa sitt mod i direkt strid.",h="Sparring Match är ett introduktionsprov under kampinstruktören Tang Stonehoofs uppsikt.",kw={"arena","stridsträning","duell","novice warrior","sparring","sparring match","tang stonehoof"},ang={["class:Warrior"]="Tang Stonehoof kan inte träna icke-krigare i deras särskilda discipliner, men hans sparringring betonar krigarfilosofin: att stridsgrunder, mod och stärkt kampvilja är till nytta för alla äventyrare.",["race:Tauren"]="Tang Stonehoof använder traditionella taurenuttryck som ”vässa hornen” för att beskriva hur man prövar sitt mod. Han välkomnar alla villiga motståndare till sparringarenan, oavsett ursprung."},sec={{t="Sparring Grounds",b="Den erfarne instruktören Tang Stonehoof håller uppsikt över sparringmatchen, där äventyrare med alla slags bakgrunder bjuds in i ringen för att pröva sitt mod. Tang uppmärksammar särskilt dem som följer andra vägar än krigarens, men menar att kampdisciplin och direkt strid ger alla resenärer visdom i en farlig värld."},{t="Vässa hornen",b="I Tang Stonehoofs arena suddas skillnader i härkomst och vapenval ut. Oavsett om utmanarna använder svärd, båge eller magi ska de visa att de är redo för strid genom att besegra tre villiga motståndare, antingen träningskrigarna Novice Warriors eller andra äventyrare i dueller. När du klarar dessa kamper vinner du Tangs respekt och bandage att lägga om såren efter en ärlig strid."}},faq={{q="Vem är Tang Stonehoof?",a="Tang Stonehoof är en stridsinstruktör som håller uppsikt över den lokala sparringarenan. Även för dem som följer andra vägar än krigarens erbjuder Tang stridsundervisning och bjuder in lovande äventyrare att pröva sitt mod i direkt strid mot nybörjare eller villiga motståndare.",al={"vem är tang stonehoof","tang stonehoof bakgrund","uppdragsgivare"}},{q="Vad kräver Tang Stonehoof för sparringmatchen?",a="Provet kräver att du besegrar tre motståndare i arenan, antingen andra äventyrare som vill duellera eller Novice Warriors som tränar där under Tang Stonehoofs ledning. Syftet är att visa att du är redo och har förmåga att strida direkt.",al={"sparring match mål","vad göra i sparring match","vem ska man slåss mot"}},{q="Varför tränar en krigarinstruktör andra klasser?",a="Tang Stonehoof tror att alla äventyrare har nytta av att möta direkt strid, oavsett om de använder klinga, båge eller magi. I hans arena betyder härkomst och klassens särskilda disciplin mindre än viljan att pröva sig själv och stärka sin kampvilja.",al={"kan icke-krigare delta","varför sparring för andra klasser","inte en krigare"}},{q="Var äger sparringmatchen rum?",a="Tävlingen äger rum precis framför Tang Stonehoof i den öppna sparringarenan, där nybörjare tränar och villiga utmanare kan mötas på lika villkor.",al={"var slåss man mot nybörjare","arenans plats","var finns ringen"}},{q="Kan du duellera med andra spelare i stället för med nybörjarkrigarna?",a="Ja. Tang Stonehoof godtar segrar över både Novice Warriors som tränar i arenan och andra äventyrare som besegras i formella dueller. Det enda han bryr sig om är att du prövar din förmåga mot villiga motståndare.",al={"kan jag slåss mot spelare","duellera med spelare för uppdraget","novice warriors eller spelare"}},{q="Vad säger Tang Stonehoof när du har klarat matchen?",a="När du har bevisat dig mot tre motståndare erkänner Tang din skicklighet och uttrycker hopp för den nya generationen. Han erbjuder förbandsmaterial så att du kan ta hand om dina sår inför den hårda väg som väntar.",al={"belöning för sparring match","vad ger tang dig"}}},fp="14,280,20.350.0,20.393.0,22.269.0,56.247.0,50.262.0,41.171.0,58.204.0,57.198.0"}
P.entries["quest:99123"] = {n="Lost in the Shadows",s="'Lost in the Shadows' är ett uppdrag där Pal'juh, en impulsiv jägare som ensam gav sig in i faran, måste räddas. Räddningen visar hur vildmarkens spårare måste balansera rå aggressivitet med tålamod när de smyger på sitt byte.",h="'Lost in the Shadows' är ett uppdrag där Pal'juh, en impulsiv jägare som ensam gav sig in i faran, måste...",kw={"jägare","lost in the shadows","pal'juh","paljuh","rovfågel","tiger"},ang={["class:Hunter"]="Uppdraget lyfter fram en grundläggande jägarregel: ha tålamod och smyg som en tiger i stället för att rusa vårdslöst fram som en hungrig rovfågel.",["race:Troll"]="Pal'juhs namn och temperament speglar unga Darkspear-jägare som ivrigt vill bevisa sin skicklighet i vildmarken innan de har lärt sig behärskning."},sec={{t="En vårdslös spejare",b="'Lost in the Shadows' handlar om att hitta och rädda Pal'juh, en skicklig men hetlevrad jägare som ensam gav sig ut i fientligt territorium. Hon ville inte vänta på förstärkning och hamnade snart i en situation hon inte kunde hantera, så hon behövde hjälp utifrån för att komma hem oskadd."},{t="Jaktens tålamod",b="När Pal'juh har räddats påpekar hennes övervakare att hennes potential som spejare och spårare är obestridlig, men att hon rusar rakt in i faran som en rovfågel i stället för att smyga med en tigers tålamod. Att hon överlevde prövningen är en tydlig påminnelse om vildmarkens skoningslösa natur."}},faq={{q="Vem är Pal'juh?",a="Pal'juh är en lovande ung jägare som är känd för att ge sig ut på egen hand i farliga områden. Hon är skicklig, men har rykte om sig att handla förhastat och hamna i kläm eller bli övermannad av vilddjur och vildmarken.",al={"vem är paljuh","paljuhs bakgrund","pal'juh"}},{q="Vad händer under uppdraget 'Lost in the Shadows'?",a="I 'Lost in the Shadows' gav sig Pal'juh ut ensam och råkade illa ut igen. En äventyrare behövdes för att spåra upp henne och hjälpa henne innan hon skadades allvarligt.",al={"vad hände i lost in the shadows","bakgrund till uppdraget lost in the shadows","berättelsen om lost in the shadows"}},{q="Varför säger uppdragsgivaren att Pal'juh beter sig mer som en rovfågel än en tiger?",a="Jämförelsen handlar om jaktteknik och disciplin. En rovfågel kastar sig fram aggressivt utan försiktighet eller eftertanke, medan en tiger väntar, smyger tålmodigt och slår till med precision och beräknande list.",al={"varför rovfågel och tiger","betydelsen av mer som en rovfågel än en tiger","jägare rovfågel tiger"}},{q="Vem tar emot rapporten för Lost in the Shadows?",a="Uppdraget avslutas hos en mentor eller jämlike som känner Pal'juh väl nog för att förutse hennes vårdslöshet och uttrycker lättnad över att någon ingrep och räddade den egensinniga spåraren.",al={"vem lämnar in lost in the shadows","uppdragsgivaren för lost in the shadows"}},{q="Lär sig Pal'juh något av det här missödet?",a="Pal'juh klarade sig tack vare hjälp utifrån, men de som har uppsikt över henne håller fortfarande ögonen på om hon verkligen lär sig hur farligt det är att ge sig av ensam.",al={"lärde sig paljuh något","mår paljuh bra"}},{q="Anses Pal'juh vara en skicklig jägare?",a="Hon anses vara en lovande jägare med stor medfödd talang och mod, men hennes mentorer varnar för att instinkt inte kan ersätta taktiskt tålamod när man spårar farligt byte.",al={"är paljuh en bra jägare","paljuhs skicklighet"}}},fp="19,237,16.263.0,20.278.0,15.204.0,52.175.0,74.211.0,48.179.0,53.179.0,39.182.0"}
P.entries["quest:99127"] = {n="A Net Disaster",s="A Net Disaster är ett uppdrag i Elwynn Forest som kretsar kring en ovanlig störning vid Crystal Lake. Mete och lina ger ingen fångst, och till och med småfiskarna har försvunnit från det grunda vattnet. Därför skickas äventyrare ut för att undersöka nattens fällor. De förstörda fällorna visar att fientliga grannar aktivt saboterar den lokala fiskeutrustningen.",h="A Net Disaster är ett uppdrag i Elwynn Forest som kretsar kring en ovanlig störning vid Crystal Lake.",kw={"a net disaster","crystal lake","elwynn forest","fiskbestånd","fiskefällor","lee","murlocs","besvärliga grannar"},ang={["faction:Alliance"]="Crystal Lake ligger mitt i Elwynn Forest, så störningar här hotar direkt försörjningen och förråden som stöder hjärtat av Alliansens territorium."},sec={{t="Oroliga vatten vid Crystal Lake",b="Vid Crystal Lake i Elwynn Forest står de lokala fiskarna inför en oroväckande brist på fångst. Tomma krokar är inget ovanligt, men när inte ens småfisk syns i det grunda vattnet blir det vardagliga fisket ett allvarligt mysterium. För att rädda det som går sätter de ut fällor över natten i hopp om att få upp ett grundbestånd."},{t="Förstörda fällor och besvärliga grannar",b="När de nedsänkta fällorna dras upp visar det sig att problemet inte beror på otur, utan på rent sabotage och förstörelse. Fientliga grannar längs sjöns stränder har förstört fällorna och hotar att driva de lokala fiskarna ur branschen om ingen gör något."}},faq={{q="Vad är A Net Disaster?",a="A Net Disaster är ett uppdrag vid Crystal Lake i Elwynn Forest. De lokala fiskarna har märkt att fisken slutat nappa och att till och med småfiskarna har försvunnit. Därför undersöker de nattens fällor.",al={"vad är a net disaster","uppdraget a net disaster","a net disaster vid crystal lake"}},{q="Var ska du undersöka fiskefällorna?",a="Fiskefällorna ligger nedsänkta i Crystal Lake. Lee satte ut dem över natten för att säkra fiskbeståndet när vanligt mete med krok och lina inte gav någon fångst.",al={"var finns fällorna","a net disaster plats","fällor i crystal lake"}},{q="Vem är Lee?",a="Lee är en lokal fiskare vid Crystal Lake som satte ut fällor över natten för att säkra fångsten när fisken slutade nappa på krok och lina.",al={"vem är lee","lee fiskare"}},{q="Vad hände med fisken i Crystal Lake?",a="Fisken har helt försvunnit från ytvattnet, och inte ens en enda småfisk syns till. Undersökningen visar att nattens fällor har förstörts av nya besvärliga grannar.",al={"vad hände med fisken i crystal lake","varför finns det ingen fisk i crystal lake","tomma crystal lake"}},{q="Vilka är de besvärliga grannarna som nämns i slutet?",a="Uppdragsgivaren syftar på nya besvärliga grannar som tränger sig in vid Crystal Lake. Aggressiva murlocs har slagit läger i och längs vattnet och ställt till oreda bland det lokala djurlivet och fiskeutrustningen.",al={"vilka är de besvärliga grannarna","a net disaster besvärliga grannar","vem förstörde fällorna"}},{q="Varför är fiskbristen ett så stort problem för fiskarna?",a="Uppdragsgivaren är direkt beroende av fiskbeståndet i Crystal Lake för sin försörjning. Med skadade fällor och tomma fångster hotar ekonomisk ruin om störningen inte stoppas.",al={"varför bryr sig uppdragsgivaren","fisket vid crystal lake"}}},fp="14,338,31.310.0,39.280.1,23.215.0,39.146.0,11.137.0,42.192.0,55.231.0,61.191.0"}
P.entries["quest:99128"] = {n="Slimy Menace",s="Slimy Menace handlar om en växande murlocinvasion längs stränderna vid Crystal Lake i Elwynn Forest. Dessa aggressiva varelser hotar att tömma sjön på fisk och utsätta lokalbefolkningen i närheten för fara. Snabba åtgärder krävs för att hålla deras antal nere.",h="Slimy Menace handlar om en växande murlocinvasion längs stränderna vid Crystal Lake i Elwynn Forest.",kw={"crystal lake","elwynn forest","fisk","goldshire","murloc","murlocer","slimy menace"},ang={["faction:Alliance"]="Att säkra stränderna vid Crystal Lake skyddar lokala fiskare i Elwynn och resenärer nära Goldshire från aggressiva murlocräder.",["race:Human"]="För folket i Elwynn Forest hotar murlocernas framryckning direkt deras vattenleder, matförråd och tryggheten i närliggande bosättningar."},sec={{t="Problem vid Crystal Lake",b="Längs den östra stranden vid Crystal Lake har en aggressiv murlocgrupp fått fäste. Dessa vilda, halvvattenlevande varelser har vassa tänder och ett häftigt temperament, och har förvandlat en gång så fridfull sjö till en farlig födopplats. Lokalbefolkningen är starkt beroende av sjön för sin dagliga försörjning, men murlocernas närvaro hotar nu alla som vågar fiska eller närma sig vattenbrynet."},{t="En ändlös invasion",b="Utöver den fysiska fara de utgör för resenärer hotar murlocer att sluka varenda fisk i sjön om de tillåts föröka sig obehindrat. När deras antal minskar får vattnen i området ett välbehövligt andrum, men deras kusliga, ekande läten är fortfarande en dyster påminnelse om deras envishet. Även när de skingras fyller murlocer snabbt på sina led, så strandlinjen måste hållas under ständig uppsikt."}},faq={{q="Vad handlar uppdraget Slimy Menace om?",a="Slimy Menace är en lokal uppgift som gäller den aggressiva murlocpopulationen vid Crystal Lakes avlägsna stränder. Om de lämnas ifred slukar dessa groddjurslika varelser den lokala fisken och hotar alla som arbetar eller färdas i närheten.",al={"vad är slimy menace","information om uppdraget slimy menace","sammanfattning av slimy menace"}},{q="Var utspelar sig händelserna i uppdraget?",a="Oroligheterna utspelar sig runt Crystal Lake i Elwynn Forest, där en grupp murlocer har samlats på den motsatta stranden. Deras närvaro stör sjöns naturliga djurliv och utgör en fara för lokalbefolkningen.",al={"var finns murlocer vid crystal lake","var ligger crystal lake","var händer detta"}},{q="Varför måste murlocer vid Crystal Lake gallras ut?",a="Murlocer tömmer snabbt sjön på fisk och terroriserar samtidigt omgivningen med sitt vilda temperament och sina vassa tänder. Att decimera deras antal hjälper till att skydda fisket i sjön och hejdar tillfälligt deras aggressiva utbredning.",al={"varför döda murlocer vid crystal lake","murlocer äter fisk","vad är problemet med murlocer"}},{q="Löser det problemet permanent att röja undan murlocer?",a="Att gallra ut murlocer ger bara en tillfällig lättnad. Som det framgår när uppgiften är slutförd förökar sig murlocer och samlar sig igen i oroväckande takt, så deras antal återhämtar sig snabbt trots de första förlusterna.",al={"är murlocer borta för alltid","utrotade vi murlocer","kommer murlocer tillbaka till crystal lake"}},{q="Vem ber om hjälp med det slemmiga hotet?",a="Uppgiften ges av en invånare i Elwynn som oroar sig för Crystal Lakes tillstånd. Plågad av murlocernas obehagliga läten och glupska aptit ber personen äventyrare att minska deras antal för att skydda fisket.",al={"vem ger slimy menace","uppdragsgivare för slimy menace"}},{q="Vad gör murlocer så hotfulla?",a="Murlocer beskrivs som vilda, lättretliga groddjurslika varelser med vassa tänder och ett ökänt, gutturalt läte. De samlas längs stränderna, försvarar sitt revir aggressivt och anfaller allt som kommer för nära deras födoplatser.",al={"hur är murlocer","murlocers beteende vid crystal lake"}}},fp="12,255,23.409.0,22.433.0,37.239.0,45.220.0,47.247.0,58.213.0,40.227.0,37.257.0"}
